{"凯里酸汤鱼": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "草鱼","q": "1条约800g","a": "减到600g汤色更集中、酸汤需同步减1/4；加到1.2kg要延长炖煮10分钟，否则鱼肉发柴"},{"n": "红酸汤（自制发酵番茄辣椒）","q": "400ml","a": "加到600ml酸味冲、会盖住鱼本身的甜味；减到250ml则酸香柔和，适合不能吃太酸的人"},{"n": "糊辣椒","q": "3勺（约20g）","a": "加到5勺糊香更突出、油亮更红；减到1勺只剩辣味没有糊香，会偏燥"},{"n": "糍粑辣椒","q": "2勺（约30g）","a": "加到4勺红油更浓、汤色更红亮，但会发苦；减到1勺汤色偏淡，糊香撑不住"},{"n": "折耳根","q": "100g","a": "加到150g腥味抢过鱼香；减到50g则药香不足，失去黔味特色"},{"n": "姜蒜","q": "30g","a": "加到50g会盖住红酸汤的果香；减到15g则腥味压不住"},{"n": "菜籽油","q": "50ml","a": "加到80ml汤面浮油厚、抢酸味；减到30ml煎鱼易粘锅"},{"n": "料酒","q": "20ml","a": "加到40ml酒味盖过酸香；减到10ml去腥力偏弱"},{"n": "盐","q": "5g","a": "加到10g会压住酸汤自带的发酵咸鲜；减到2g则发酵酸味发闷"},{"n": "白胡椒粉","q": "2g","a": "加到5g辛味抢口、喉头发干；减到1g几乎尝不出后味"}],"steps": ["草鱼处理干净，剁成3cm见方的块，用清水反复冲洗至血水变清，沥干备用。","锅中放菜籽油烧至六成热，下姜蒜末爆香，倒入红酸汤转小火慢熬5分钟，至酸香充分溢出、汤色转为橙红。","另起干锅不放油，撒入干辣椒用小火慢焙3-5分钟，至辣椒表皮起虎皮、边缘微微焦黑，晾凉后放入石臼舂碎成糊辣椒——焙过头会发苦，火太小焙不出香，这是全程最容易失败的一步。","糍粑辣椒用开水烫30秒后捞出剁碎；酸汤锅中加入糍粑辣椒再炒2分钟，炒出红油、汤色更浓稠。","转大火将鱼块下锅，烹入料酒，加盖炖8分钟，至鱼块变白、用筷子能轻松夹断，中途不要频繁翻动。","放入折耳根段和糊辣椒，转中火翻炒1分钟让辣椒均匀裹在鱼块上。","调入盐和白胡椒粉，尝味后撒野葱段，翻匀出锅装盘。"],"key": "贵州酸汤的酸味来自自然发酵的番茄辣椒，不可直接用醋替代；鱼块下锅后不要频繁翻动，否则会碎。","tip": "想吃重口就把糊辣椒提到5勺；给小孩或老人吃，把折耳根减半、辣椒减到1勺，保留鲜味即可。没有自制酸汤时可用市售红酸汤，但别用白醋+番茄酱兑。"},"花溪牛肉粉": {"time": "2小时","level": "中等","servings": "2-3人份","ing": [{"n": "黄牛腱子肉","q": "600g","a": "减到400g汤的鲜味下降但更清爽；加到900g需多炖40分钟且汤更浑，撇油要更勤"},{"n": "牛骨","q": "500g","a": "加到1kg汤更浓白但会盖住牛肉本味；减到200g汤色偏清、鲜味不足"},{"n": "贵州花溪细米粉","q": "200g（干重）","a": "200g可煮3碗；减到150g汤味更突出，加到300g则粉比汤抢味、吃两口就腻"},{"n": "姜","q": "20g","a": "加到35g姜味冲、盖住牛肉香；减到10g去腥力偏弱"},{"n": "葱","q": "15g","a": "加到30g葱香过重抢汤香；减到8g成菜少一分清香"},{"n": "花椒","q": "8g","a": "加到15g麻味刺喉；减到4g则只有辣没有麻、失去贵州味"},{"n": "盐","q": "8g","a": "加到15g汤咸得发苦、粉吃不出味；减到4g则牛味腥气返上来"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香盖过汤香、抢牛味；减到1勺只有生辣没有糊香"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣油过重、汤面全红；减到1勺辣味不够层次"},{"n": "折耳根","q": "30g","a": "加到60g药草味盖过牛骨汤；减到10g则贵州特色不明显"}],"steps": ["黄牛腱子肉切大块，冷水下锅，加姜、葱段、料酒，大火烧开撇净浮沫，捞出用温水冲洗干净——必须用温水，冷水会让肉紧缩变柴。","牛骨焯水后与牛肉一起放入大锅，加姜片、葱结、花椒、清水2L，大火烧开转小火，保持汤面似开非开地炖90分钟。","炖至牛肉能用筷子扎透、汤色微微泛白时关火，捞出牛肉放凉后逆纹切片；汤用纱布过滤两次，得到清亮不浑的牛骨原汤。","干锅不放油，撒干辣椒小火慢焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒备用。","米粉用温水泡30分钟，沸水下锅煮3分钟至断生无硬芯，捞出装入碗中。","碗底放糊辣椒2勺、油辣椒3勺、盐少许，浇滚烫牛骨原汤冲开辣椒，再铺上牛肉片。","放折耳根、烫好的青菜豆芽，趁热拌匀食用，汤别放凉——凉了牛油凝在面上、腥味返上来。"],"key": "花溪牛肉粉讲“汤清肉烂”：汤必须过滤两次保持清亮，牛肉切片要逆着纹路切，逆纹切才嫩不塞牙。","tip": "汤一次多炖些冷藏，次日回锅烧开风味更足；不吃辣的话把油辣椒减到1勺，只留糊辣椒的香。"},"遵义羊肉粉": {"time": "3小时","level": "稍难","servings": "2-3人份","ing": [{"n": "遵义黑山羊带骨羊肉","q": "800g","a": "减到600g汤的膻味压不住；加到1.2kg需多炖60分钟、汤更浓但成本高"},{"n": "羊骨","q": "400g","a": "加到600g汤更奶白厚重；减到200g汤味单薄、没有羊膻的底味"},{"n": "遵义细米粉","q": "200g（干重）","a": "200g可煮3碗；减到150g汤味更足，加到300g粉多汤少、每口都是坨粉"},{"n": "遵义干辣椒","q": "15g","a": "加到25g辣味压羊膻过猛；减到8g则膻味留口、汤发苦"},{"n": "花椒","q": "6g","a": "加到12g麻得舌头发木、吃不出羊肉鲜；减到3g去膻力有限"},{"n": "姜","q": "30g","a": "加到50g姜辣发苦；减到15g压不住膻"},{"n": "白胡椒粉","q": "3g","a": "加到6g辛麻突出、抢汤的奶香；减到1g几乎无效果"},{"n": "羊脑壳豆腐乳（毛豆腐乳）","q": "20g","a": "加到40g咸香过头、盖住羊味；减到10g则那点发酵香出不来"},{"n": "糊辣椒","q": "3勺（约20g）","a": "加到5勺糊香更足但辣度超载；减到1勺只剩辣、没糊香"},{"n": "油辣椒","q": "2勺（约20ml）","a": "加到4勺红油铺满碗面、盖住汤色；减到1勺辣味单薄"}],"steps": ["羊肉切块冷水下锅，加姜片、料酒，大火烧开煮3分钟，撇净血沫后捞出用温水冲洗——这步去膻最关键，水一定要用温水。","羊骨焯水后与羊肉一同入锅，加干辣椒、花椒、姜块、清水2.5L，大火烧开转最小火，锅盖留一条缝，慢炖2.5小时。","炖到羊肉用筷子一夹就散、汤色呈浓白时关火，捞出羊肉晾凉切片，羊汤过滤备用。","干锅不放油，撒干辣椒小火焙至虎皮焦香，晾凉舂碎成糊辣椒。","米粉温水泡30分钟，沸水煮3分钟至无硬芯，捞入碗中；豆腐乳用温水化开调成稀糊备用。","碗底放糊辣椒、油辣椒、化开的豆腐乳、少量盐，冲入滚烫羊汤，再铺羊肉片。","撒白胡椒粉和葱花，趁热拌匀。羊汤面上那层白油不要撇——那是羊膻被高温逼到汤里的精华，也是遵义羊肉粉香气的来源。"],"key": "去膻靠“温水冲洗+小火长炖+干辣椒花椒”三件事，大火滚沸会让膻味锁在肉里。","tip": "怕膻的人第一次可把干辣椒加到25g压味；羊汤一次多做，冷藏保存次日回锅，加点盐和白胡椒粉调味即可当早饭。"},"肠旺面": {"time": "2小时","level": "稍难","servings": "2-3人份","ing": [{"n": "猪大肠","q": "400g","a": "减到250g脆哨分量不足、面少香；加到600g需要多搓洗清洗时间且腻口"},{"n": "鸭血（或猪血旺）","q": "300g","a": "加到500g血旺味重、抢脆哨的香；减到150g则“一碗看不到血”"},{"n": "猪腿肉（做脆哨）","q": "250g","a": "减到150g臊子不够香；加到400g需多炸5分钟才干香"},{"n": "贵阳鸡蛋面","q": "200g（干重）","a": "200g煮3碗；减到150g汤宽面少；加到300g则面坨汤少"},{"n": "熟猪油","q": "40g","a": "加到70g面上油亮过重、盖住血旺味；减到20g则香不够挂面"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣得盖过脆哨的肉香；减到1勺贵阳味不足"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到3勺糊香足但会盖住血旺的嫩滑感；不加则少一层次"},{"n": "蒜末","q": "15g","a": "加到30g蒜味冲鼻；减到8g香气不够"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g香气不足"},{"n": "折耳根","q": "30g","a": "加到50g药草味压过肉味；减到10g特色变淡"}],"steps": ["猪大肠翻面用盐和面粉反复搓洗去黏液，冲洗干净后冷水下锅，加姜、料酒煮20分钟至能用筷子穿透，捞出切成1cm见方的丁。","锅放菜籽油烧至五成热，下大肠丁小火慢炸8-10分钟，炸到表面干硬发黄、咬下去咯吱响，捞出即成脆哨。","鸭血切2cm厚块，冷水下锅小火汆煮5分钟，撇去表面浮沫至水清，捞出用原汤或清水泡着保温——久煮血旺会发柴、起孔。","猪腿肉剁成末，锅里下油炒散至肉末干香发脆，盛出与脆哨拌匀备用。","另起干锅小火焙干辣椒至虎皮焦香，晾凉舂碎成糊辣椒。","鸡蛋面沸水煮2分半钟，捞出沥干装碗；碗底放熟猪油、油辣椒、糊辣椒、酱油、蒜末，浇一勺面汤冲开。","铺上脆哨肉末和汆好的鸭血块，撒葱花、折耳根，趁热从碗底翻拌均匀，让每根面都挂上红油。"],"key": "脆哨要“干炸”而不是“水煮”：大肠丁必须炸到干硬发黄才有那口咯吱脆感；鸭血只能汆熟，久了必老。","tip": "喜欢更香可加一勺熟油辣子骨；不吃鸭血的用猪血旺或鸭血豆腐代替，豆腐要最后放、煮久了会散。"},"贵阳素粉": {"time": "20分钟","level": "简单","servings": "1-2人份","ing": [{"n": "贵阳细米粉（干）","q": "150g","a": "150g煮一大碗；减到100g粉少味淡，加到200g需多煮1分钟否则芯硬"},{"n": "酸汤（红酸汤兑水）","q": "80ml","a": "加到150ml酸得冲、抢油辣椒的香；减到40ml则“素粉”的酸字就没了"},{"n": "油辣椒","q": "2勺（约20ml）","a": "加到4勺辣油盖过所有香味；减到1勺辣度不够、味道寡淡"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到2勺糊香更足；减半则只剩生辣"},{"n": "豆芽","q": "80g","a": "加到150g配菜抢眼、也增脆；减到40g整碗只有粉"},{"n": "折耳根","q": "20g","a": "加到40g药味盖过豆香；减到10g贵州味偏淡"},{"n": "蒜末","q": "10g","a": "加到20g生蒜味刺口；减到5g香气不足"},{"n": "葱花","q": "15g","a": "加到30g抢味；减到8g偏淡"},{"n": "香醋","q": "5ml","a": "加到15ml尖酸直接盖过酸汤的自然酸；减到2ml酸味不够立体"},{"n": "盐","q": "2g","a": "加到6g咸过头、压住酸香；减到1g基本靠酸汤自带咸度"}],"steps": ["米粉用温水泡30分钟，沸水下锅煮3分钟至完全断生，捞出沥干水分装碗。","豆芽焯水30秒断生，捞出沥干；焯豆芽的水别倒，留着当面汤底。","碗底放油辣椒2勺、糊辣椒1勺、蒜末、葱花、折耳根、盐2g。","舀入两勺煮粉的热水冲开辣椒，让辣椒的香气和辣味充分释放。","倒入酸汤80ml、香醋5ml搅匀，尝一下酸度，酸不够再补2ml醋。","铺上豆芽，从碗底把粉和调料一起翻拌均匀，让每根粉都挂上红油。","趁热吃，粉凉了会返生坨、辣椒油凝在面上。"],"key": "素粉的“素”指没有肉臊子，但绝不是没味道——全靠酸汤和油辣椒撑住，辣椒一定要用滚粉汤冲开而不是直接拌。","tip": "一勺自制酸汤兑两勺热水就是贵州“酸汤水”的比例，比例对了比一味加醋更圆润；不能吃辣就把油辣椒减半、糊辣椒减到半勺。"},"酸粉": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "大米（做酸浆用）","q": "300g","a": "减到200g酸度偏弱、浆水不够稠；加到500g发酵时间拉长、酸味更冲"},{"n": "发酵米浆（酸浆）","q": "400ml","a": "自制：用300g米磨浆加10g酒曲密封发酵3天。加到600ml粉丝更酸、需多兑水；减到250ml酸味不够、与普通米粉无异"},{"n": "豌豆粉（漏粉用）","q": "30g","a": "加到60g粉条更劲道有嚼劲；减到10g则条子软塌易断"},{"n": "沸水（冲浆用）","q": "500ml","a": "加到700ml浆偏稀、粉条挂不牢；减到400ml浆会结块、漏出的粉条粗细不匀"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣味盖住发酵的酸香；减到1勺酸香出不来"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到3勺糊香足、味道更立体；减半只剩辣"},{"n": "肉末臊子","q": "150g","a": "加到250g变肉粉面；减到80g酸香主导更明显"},{"n": "折耳根","q": "30g","a": "加到50g药味盖住酸味；减到10g特色弱"},{"n": "豆芽与时蔬","q": "150g","a": "加到250g解腻但会稀释挂汁；减到80g配菜太少"},{"n": "蒜末","q": "12g","a": "加到25g蒜味刺鼻；减到6g香气淡"}],"steps": ["大米淘净泡3小时，加水打成细腻米浆，用纱布滤掉米渣，留浆约400ml。","米浆加10g酒曲拌匀，装坛密封放在温暖处发酵3天，掀盖见细密气泡、闻着有酸甜酒香即成酸浆——发酸不冲、带一点酒味才对，发臭就是坏了。","酸浆倒进耐热锅，中火加热并不断搅动，熬到起大泡、变稠能挂勺（这步叫“熟浆”），能拉出细丝即离火。","另一锅水烧至大滚，箩筐架在锅上，熟浆分两次倒入箩筐：第一次冲熟、第二次用离火沸水冲透，粉条自动漏下，落入冷水中即成酸粉条。","酸粉条捞出沥干，拌少许熟油防粘，装碗备用。","碗底放油辣椒、糊辣椒、蒜末、折耳根、肉末臊子，加两勺面汤冲开。","放上酸粉条和焯熟的豆芽青菜，从碗底翻拌，让酸浆自然挂浆，充分挂汁后食用。"],"key": "酸粉的酸是米浆自然发酵来的，熬浆时火候要小、必须不停搅动，否则底部焦糊整锅发苦。","tip": "嫌发酵麻烦可直接买现成酸浆或用市售酸汤兑米浆，发酵味会淡一些；一次可多漏些粉条，煮熟后冷藏能放3天。"},"丝娃娃": {"time": "40分钟","level": "中等","servings": "3-4人份","ing": [{"n": "面粉","q": "200g","a": "减到150g皮薄易破、卷不住料；加到300g皮偏厚、嚼着发硬"},{"n": "温水","q": "130ml","a": "加到160ml饼软塌难摊；减到110ml面团硬、饼一卷就裂"},{"n": "绿豆芽","q": "150g","a": "加到250g爽脆但蘸水挂不住；减到80g口感单调"},{"n": "折耳根","q": "60g","a": "加到100g药味盖过酸汤；减到30g黔味不够"},{"n": "卷心菜丝","q": "80g","a": "加到150g甜味抢戏；减到40g少一层脆甜"},{"n": "胡萝卜丝","q": "40g","a": "加到80g配色好看但味道偏生；减到20g点缀即可"},{"n": "红酸汤（兑蘸水用）","q": "250ml","a": "加到400ml蘸水酸得倒牙；减到150ml酸香不足、只剩辣"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香盖住酸味；减到1勺蘸水只有辣味"},{"n": "油辣椒","q": "2勺（约20ml）","a": "加到4勺辣度过强抢酸汤；减到1勺香辣不够"},{"n": "香醋","q": "15ml","a": "加到30ml尖锐的酸盖过发酵酸香；减到8ml酸不够爽"}],"steps": ["面粉加130ml温水和5g盐揉成软硬适中的面团，盖湿布醒30分钟——醒不到位饼皮会回缩、卷时裂开。","面团分小份擀薄，擀到能隐约透光即可。烧热平底锅，滴少许油把饼两面各烙15秒至鼓起小泡、边缘微微透焦，取出放凉。","豆芽焯水1分钟断生，捞出过一遍凉水保持脆度；折耳根洗净切细段，卷心菜、胡萝卜切细丝，全部沥干水分。","调蘸水：红酸汤250ml加香醋15ml、糊辣椒2勺、油辣椒2勺、蒜末、少许盐搅匀，静置10分钟让味道融合。","取一张饼摊开，中间放折耳根、豆芽、菜丝各一小撮。","把饼两侧往中间折、底部向上兜起，卷成小巧的方筒，形似娃娃。","装盘后蘸酸汤一口一个，饼皮要凉了才够柔韧，热的会黏手。"],"key": "饼皮必须凉透再卷；卷心菜丝要切得极细且沥干，带水会泡烂饼皮、一咬就漏。"},"恋爱豆腐果": {"time": "30分钟","level": "中等","servings": "2人份","ing": [{"n": "老豆腐（卤水豆腐）","q": "1块约400g","a": "减到250g不够一人吃、影响蘸水比例；加到600g表面水分多、烤后发软难脆"},{"n": "折耳根","q": "80g","a": "加到150g药草味盖过豆香；减到40g则黔味不足、像普通烤豆腐"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香突出但会盖住豆腐的清甜；减到1勺只有辣没有糊香"},{"n": "油辣椒","q": "1勺（约10ml）","a": "加到3勺辣味过重、豆腐本味发苦；减到半勺则香气单薄"},{"n": "辣椒水（醋+糊辣椒+蒜水）","q": "150ml","a": "加到250ml汁多豆腐泡涨、口感变软；减到80ml蘸不匀、味道挂不住"},{"n": "蒜末","q": "15g","a": "加到30g蒜味刺鼻盖住折耳根；减到8g蒜香不足"},{"n": "葱花","q": "15g","a": "加到30g抢味；减到8g香气不够"},{"n": "菜籽油","q": "20ml","a": "加到40ml烤时滋滋响、表面过油发腻；减到10ml粘烤盘"},{"n": "花椒粉","q": "2g","a": "加到5g麻得舌头发木；减到1g几乎尝不出"},{"n": "盐","q": "2g","a": "加到6g和辣椒水抢味；减到1g基本靠辣椒水带咸"}],"steps": ["老豆腐切成1.5cm厚的片，用厨房纸吸干表面水分，这一步决定成品是脆是软。","平底锅烧热刷一层菜籽油，中小火把豆腐片两面各烙3-4分钟，烙到两面起金黄色薄壳、边缘微微卷起。","另起干锅不放油，撒干辣椒小火慢焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒，与花椒粉、盐拌匀成干蘸料。","折耳根洗净切细段，拌入蒜末、少许油辣椒、葱花，再淋入辣椒水调成蘸汁——辣椒水要先调好静置5分钟，味才融合。","豆腐片烙好后垫在盘底，趁热把干蘸料均匀撒在豆腐表面。","用筷子在豆腐片中间划开一道浅口，让蘸汁渗进去——这是“恋爱豆腐果”和普通烤豆腐最明显的区别。","淋上剩余辣椒水，撒葱花，趁热吃；豆腐放凉了皮就不脆了。"],"key": "豆腐必须吸干水分再用中小火慢烙，表皮起壳才叫“脆”；蘸汁要划口渗入，否则只是浮在表面。","tip": "没有炭火用平底锅同样可以，但火力要小；怕辣就把糊辣椒减到1勺、油辣椒减半，用酸汤兑水替辣椒水也一样好吃。"},"豆腐圆子": {"time": "60分钟","level": "稍难","servings": "3-4人份","ing": [{"n": "嫩豆腐（石膏豆腐）","q": "500g","a": "减到350g浆水比例对不上、难以挂粉成团；加到650g需延长滤水时间否则太稀"},{"n": "淀粉（红薯淀粉或豌豆粉）","q": "100g","a": "加到150g外壳更厚更脆但口感偏硬；减到60g外皮薄、容易炸破"},{"n": "清水（调淀粉糊）","q": "160ml","a": "加到220ml挂浆太稀、外壳起泡少；减到110ml糊太稠、团起来表面不光滑"},{"n": "肉末（猪肉）","q": "150g","a": "加到250g变成肉丸子；减到80g豆香突出、但口感偏单"},{"n": "折耳根","q": "60g","a": "加到100g药味抢过豆香；减到30g特色变淡"},{"n": "葱姜末","q": "20g","a": "加到40g抢味；减到10g香气不足"},{"n": "花椒粉","q": "3g","a": "加到6g麻味盖住豆香；减到1g几乎无感"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香足但辣度过载；减到1勺只剩辣味"},{"n": "菜籽油（炸制用）","q": "1L","a": "加到1.5L浪费油且不易控制火候；减到600ml需分两锅炸，否则下锅后温度骤降会粘连"},{"n": "盐","q": "4g","a": "加到8g咸过头；减到2g则豆腐味淡如水"}],"steps": ["嫩豆腐用纱布包住，重物压20分钟滤去水分，压到表面微软不塌为准——水分决定丸子是否能成型。","压好的豆腐与肉末、葱姜末、折耳根末、花椒粉、盐同放盆中，顺一个方向搅打3分钟，搅到肉馅能黏着成团。","淀粉加清水调成能挂勺的稀糊，静置10分钟让淀粉充分吸水——这是外皮起脆壳的关键。","取一团馅料约30g搓圆，蘸淀粉糊后放入油锅，依次全部团好下锅；油温五成热（150℃），下锅后用勺背轻推防止粘连。","中火炸5-6分钟至丸子外皮金黄起泡、浮油变清，捞出沥油，晾2分钟再吃——刚出锅外壳还是软的，放凉后才酥脆。","另起干锅小火焙干辣椒至虎皮焦香，晾凉舂碎成糊辣椒。","取小碗放糊辣椒2勺、酱油、醋、少量花椒粉调成蘸碟，豆腐圆子趁热蘸着吃，外脆内嫩。"],"key": "淀粉糊必须静置吸水后再用，干粉直接拌会在炸的时候脱落、外壳炸不出泡；丸子晾凉再吃才是脆的。","tip": "素食可把肉末换成350g豆腐碎加香菇末；油温不够会粘连，油温太高外壳炸黑而内里还是生的。"},"贵阳辣子鸡": {"time": "50分钟","level": "中等","servings": "3-4人份","ing": [{"n": "土鸡（鸡腿+鸡翅）","q": "800g","a": "减到600g肉少不够吃；加到1kg要延长煨煮时间并分两次炸，否则外焦里生"},{"n": "糍粑辣椒（开水烫过剁碎）","q": "200g","a": "加到300g辣度与糊香都过猛、盖住鸡肉香；减到120g香辣不足、失去黔味"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香更足；减到1勺只剩辣、缺少烘焙的香气"},{"n": "菜籽油","q": "150ml","a": "加到200ml成菜油重易腻；减到100ml则糍粑辣椒容易炒糊"},{"n": "姜蒜","q": "40g","a": "加到60g蒜味压过鸡肉；减到20g腥味压不住"},{"n": "干辣椒（整段）","q": "30g","a": "加到60g辣中带苦；减到15g香气不足"},{"n": "花椒","q": "5g","a": "加到10g麻得说话发木；减到2g几乎无麻"},{"n": "熟白芝麻","q": "10g","a": "加到25g芝麻香抢味、也压不出辣子鸡的“糯”；减到5g点缀即可"},{"n": "花生米（油酥）","q": "50g","a": "加到100g太腻；减到20g口感单薄"},{"n": "盐","q": "3g","a": "加到8g咸得盖住甜味；减到1g则鸡肉不够入味"}],"steps": ["土鸡剁成3cm见方的块，冷水下锅加姜片、料酒焯水3分钟，撇净浮沫后捞出用温水冲洗干净并彻底沥干——带水下油锅会剧烈爆溅、也炸不出脆皮。","锅中放菜籽油烧至六成热，下鸡块炸3-4分钟至表皮金黄发硬，捞出摊开晾2分钟让内部水分回渗——这步让成品外酥里嫩。","锅内留底油，下姜蒜、干辣椒段、花椒小火炒2分钟至香味出来。","转中火下糍粑辣椒炒4分钟，不停翻动炒出红油，糍粑辣椒炒到颜色变成深红、边缘发亮即成；火大会发苦。","倒回鸡块，加盐翻匀，大火翻炒2分钟让辣椒均匀裹住每一块鸡。","撒入油酥花生米，翻炒30秒后立刻关火，防止花生回软。","装盘后撒白芝麻，趁热吃；冷了糍粑辣椒会回潮、辣椒的“糯”劲就没了。"],"key": "糍粑辣椒必须用开水烫过再剁碎（烫过的辣椒不苦、颜色更红），全程中火慢炒出红油，大火会糊。","tip": "正宗做法用糍粑辣椒，提前一晚用开水烫好剁细冷藏备用；素食可用干煸香菇替换鸡块，泡椒味同样出彩。"},"酸汤牛肉": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "黄牛肉（腱子/里脊）","q": "600g","a": "减到450g切薄片会不够铺满；加到800g需分两次涮否则汤变浑"},{"n": "红酸汤（自制发酵番茄辣椒）","q": "400ml","a": "加到600ml酸得倒牙、牛肉的鲜甜被盖住；减到250ml酸香柔和、汤色偏淡"},{"n": "牛骨汤/高汤","q": "800ml","a": "加到1.2L汤味更醇但酸汤被稀释得寡淡；减到500ml汤浓味重、酸汤需同步减量"},{"n": "泡椒","q": "30g","a": "加到60g酸里带冲、抢红酸汤的果香；减到15g酸中带辣更和谐"},{"n": "姜蒜","q": "30g","a": "加到50g蒜味盖住酸香；减到15g牛肉腥味返上来"},{"n": "折耳根","q": "80g","a": "加到150g药草味盖过酸味；减到40g特色不足"},{"n": "豆腐（嫩）","q": "200g","a": "加到350g吸汤变味、酸味渗进去发酸；减到100g配菜太少"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香盖过酸汤；减到1勺酸汤显得单薄"},{"n": "油辣椒","q": "1勺（约10ml）","a": "加到3勺辣味过重盖住酸；减到半勺颜色不够红亮"},{"n": "白胡椒粉","q": "2g","a": "加到5g辛味冲；减到1g几乎无感"}],"steps": ["黄牛肉逆纹切薄片，厚度约2mm，用少许盐、淀粉抓匀腌15分钟，再拌一勺油封住水分——这样涮出来才嫩不塞牙。","锅中放油烧至五成热，下姜蒜末、泡椒炒2分钟出香。","倒入红酸汤小火熬5分钟，至汤色转成砖红、酸香完全释放，然后兑入牛骨汤烧开。","另起干锅不放油，撒干辣椒小火焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒备用。","汤转中火保持微沸，先下豆腐块和泡软的木耳煮3分钟，再下牛肉片，用筷子快速划散，烫40-60秒至变色立刻关火——久煮会老。","起锅前撒入折耳根和糊辣椒，用原汤冲开辣椒，静置1分钟让糊香释放。","撒白胡椒粉，淋油辣椒，配一碟油辣椒干蘸碟上桌。"],"key": "牛肉片必须逆纹切薄并用油封住；汤保持“似开非开”状态涮肉，一滚沸肉就老了。","tip": "没有自制酸汤可用市售红酸汤，切勿用白醋替代；不吃折耳根就换成香菜或蒜苗，但酸汤本身少了那层黔味。"},"豆米火锅": {"time": "2小时","level": "简单","servings": "4-5人份","ing": [{"n": "红豆（芸豆）","q": "300g","a": "减到200g汤不够稠、失去“泡饭一绝”的口感；加到400g汤过稠、菜下锅容易糊底"},{"n": "猪筒骨","q": "800g","a": "减到500g汤的骨香淡；加到1.2kg需多炖40分钟、汤面浮油变厚"},{"n": "黄豆（可选增稠）","q": "50g","a": "加到100g汤更稠但豆味过重抢骨香；减到25g刚好挂勺"},{"n": "白菜","q": "400g","a": "加到600g吸汤太多、汤变淡；减到250g配菜不够"},{"n": "豆腐","q": "300g","a": "加到500g豆腐吸味发干；减到200g不够吃"},{"n": "洋芋片","q": "300g","a": "加到450g煮久会化在汤里；减到200g份量偏少"},{"n": "木耳（泡发）","q": "100g","a": "加到200g泡发后更多、需提前泡足；减到50g点缀"},{"n": "猪油","q": "40g","a": "加到80g汤面浮油厚、不清爽；减到20g锅底易糊"},{"n": "姜蒜","q": "25g","a": "加到40g抢味；减到12g骨香显不出层次"},{"n": "盐","q": "10g","a": "加到18g豆汤发苦；减到6g则骨头味压不住"}],"steps": ["红豆提前用清水泡2小时，沥干备用；猪筒骨冷水下锅焯水，撇净血沫后捞出冲洗干净。","锅中放猪油化开，下姜蒜炒香，加筒骨煸炒2分钟至表面微黄。","倒入泡好的红豆和黄豆，加清水3L，大火烧开转小火慢炖1.5小时，中途搅拌两次防粘底。","炖到红豆开花、豆沙完全化开、汤色变稠、能挂勺时，撇掉表面多余浮油。","另起干锅焙糊辣椒备用；火锅汤底调入盐、姜蒜，保持微沸状态。","先下耐煮的洋芋片和豆腐煮5分钟，再下白菜、木耳煮2分钟。","食客自己涮菜，涮完把汤底浇在米饭上泡着吃——豆米火锅的精髓就在最后这口泡饭。"],"key": "豆米汤要“煮到出沙”而不是煮开花，卖相越碎越不正宗；用猪油煸骨再加水，汤的香气比直接冷水下锅浓一倍。","tip": "这锅底越煮越浓，第二天加汤回锅就是更好的底；不吃猪肉可用鸡架+少量猪油代替，汤同样够厚。"},"酸菜豆米火锅": {"time": "2小时","level": "简单","servings": "4-5人份","ing": [{"n": "红豆（芸豆）","q": "250g","a": "减到180g汤稠度不够；加到350g酸菜味被豆香压住"},{"n": "酸菜（贵州酸菜/泡姜酸菜）","q": "300g","a": "加到450g酸味冲、盖住骨汤鲜味；减到200g酸度温和、锅底层次更好"},{"n": "猪筒骨或鸡骨架","q": "700g","a": "减到450g汤底单薄；加到900g需多炖40分钟"},{"n": "泡椒","q": "30g","a": "加到60g酸辣双重过载；减到15g与酸菜更协调"},{"n": "姜蒜","q": "30g","a": "加到50g抢味；减到15g蒜香不足"},{"n": "猪油","q": "40g","a": "加到80g汤面浮油厚腻；减到20g容易糊底"},{"n": "白菜","q": "350g","a": "加到500g吸汤、汤变淡；减到250g量偏少"},{"n": "豆腐","q": "300g","a": "加到450g吸酸汤发酸；减到200g份量少"},{"n": "洋芋片","q": "300g","a": "加到400g煮久化汤；减到200g不够"},{"n": "盐","q": "8g","a": "加到15g和酸味打架、发苦；减到4g骨汤的咸鲜会漏出来"}],"steps": ["红豆泡2小时；酸菜用手挤干水分，切成粗段——挤水这步不做，酸菜会把汤里的咸度全带走、也压不住豆香。","猪筒骨冷水下锅焯水，撇沫后冲洗干净，沥干备用。","锅中化开猪油，下姜蒜、泡椒炒香，倒入酸菜段翻炒3分钟，炒到酸香味明显窜出、菜色发亮。","加入筒骨煸炒2分钟，倒入泡好的红豆，加清水3L，大火烧开转小火慢炖1.5小时。","炖到豆子出沙、汤变浓稠，撇去浮油，尝味后调盐——酸菜本身咸，先尝再加盐。","另起干锅焙糊辣椒备用，火锅上桌时舀一勺撒面上更香。","先下洋芋片、豆腐煮5分钟，再下白菜，客人自涮；最后把汤浇在饭上泡着吃。"],"key": "酸菜必须炒过再入锅并且挤干水，否则又酸又咸还带生味，整锅汤会被毁掉一半。","tip": "用自家做的贵州酸菜（用淘米水泡的青菜）味道最正；酸菜咸度高时汤别加盐，蘸碟用糊辣椒单独调。"},"糟辣脆皮鱼": {"time": "50分钟","level": "稍难","servings": "3-4人份","ing": [{"n": "草鱼（或黔鱼）","q": "1条约750g","a": "减到550g改花刀刀数要减少，否则鱼身会散；加到1kg需分两锅炸才熟透"},{"n": "糟辣椒（糯米酒糟拌辣椒发酵）","q": "200g","a": "加到300g酸得过冲、抢鱼的鲜甜；减到120g糟香淡、只剩咸辣"},{"n": "甜红醋","q": "40ml","a": "加到70ml酸甜失衡、只剩酸；减到20ml甜味不够、糟香发闷"},{"n": "白糖","q": "25g","a": "加到40g齁甜盖住糟香；减到10g发苦不上味"},{"n": "姜蒜末","q": "30g","a": "加到50g蒜味压住糟的发酵香；减到15g香气不够"},{"n": "干辣椒段","q": "20g","a": "加到40g辣味盖过酸甜；减到10g点缀"},{"n": "淀粉（水淀粉挂糊）","q": "40g","a": "加到70g外皮厚、咬到面疙瘩；减到20g皮不脆易破"},{"n": "料酒","q": "25ml","a": "加到50ml酒味盖住糟香；减到10ml去腥力弱"},{"n": "菜籽油","q": "800ml（炸鱼用）","a": "加到1.2L浪费且难控温；减到600ml需分两批炸"},{"n": "盐","q": "2g","a": "加到6g和糟辣椒的咸打平、发苦；减到1g基本靠糟辣椒带咸"}],"steps": ["草鱼处理干净，两面各划5刀、深至骨但不要切断，抹盐和料酒腌20分钟；刀口深浅一致才能同时炸透、同时入味。","锅中放菜籽油烧至六成热（180℃），鱼身内外擦干薄薄一层水淀粉——有水会爆油炸不起脆皮。","提住鱼尾把鱼放入油锅，中火炸8-10分钟，用漏勺托着翻面，炸到两面金黄、酥壳坚硬，用筷子能扎透即捞出控油。","另起干锅焙糊辣椒至虎皮焦香，晾凉舂碎成糊辣椒；糟辣椒备用。","空锅下菜籽油烧热，下姜蒜末、干辣椒段炒香，倒入糟辣椒中火炒3分钟，炒出红油和发酵的糟香。","加甜红醋40ml、白糖25ml、盐2ml翻匀，加两勺热水烧开熬1分钟至汁略稠、能挂住勺。","把脆皮鱼盛入深盘，浇上滚烫的糟辣汁，撒上糊辣椒和葱花；趁热吃，脆皮沾汁超过1分钟就不脆了。"],"key": "炸鱼的脆靠“水淀粉挂糊+油温六成”，鱼必须彻底擦干；酸甜汁要单独熬好最后浇，泡久了皮就软了。","tip": "没有糟辣椒可用剁椒+少许米酒和白酒发酵两周替代；甜红醋用山西陈醋加等量糖熬成糖醋汁也行，但味道不如糟辣椒。"},"青岩状元蹄": {"time": "3小时","level": "稍难","servings": "4人份","ing": [{"n": "猪后蹄（一只约1200g）","q": "1只","a": "减到800g需延长卤制到3小时才酥；加到1500g汤量要多、焖的时间也拉长"},{"n": "黄豆（垫底同卤）","q": "150g","a": "加到300g豆香抢过肉香；减到80g太素"},{"n": "折耳根","q": "60g","a": "加到120g苦味明显；减到30g清香不显"},{"n": "干辣椒段","q": "30g","a": "加到60g辣味盖过卤香；减到15g只有咸香"},{"n": "花椒","q": "8g","a": "加到15g麻得舌麻；减到4g去腥力弱"},{"n": "卤料（八角3颗、桂皮10g、香叶4片、草果2个、山奈5g）","q": "共50g","a": "加到80g药味发苦、盖住猪香；减到30g香味单薄"},{"n": "姜葱（姜块30g+大葱段50g）","q": "80g","a": "加到130g姜味过重、抢过卤香；减到45g去腥力弱、葱香不足"},{"n": "生抽与老抽","q": "生抽60ml+老抽15ml","a": "生抽加到100ml颜色过深发黑；老抽加到30ml发苦，减到8ml色泽不够红亮"},{"n": "冰糖","q": "30g","a": "加到50g齁甜；减到15g色泽偏淡"},{"n": "黄豆酱/豆瓣酱","q": "30g","a": "加到60g酱味压过肉香；减到15g底味不足"}],"steps": ["猪蹄用喷枪或明火燎去残毛，刮洗干净后从脚踝处剁开成4块，冷水下锅加姜、料酒焯水5分钟，撇净血沫后捞出温水冲洗。","锅中放油和冰糖，小火炒至冰糖融化、变成枣红色的糖色，立刻倒入猪蹄快速翻炒上色——糖色一旦过火就发苦，要一气呵成。","加姜块、葱段、花椒、干辣椒、卤料、豆瓣酱、生抽、老抽炒匀，倒入没过猪蹄的热水（3L）。","加入提前泡2小时的黄豆，大火烧开转小火，盖盖慢炖2.5小时，全程保持汤面微微冒泡不剧烈翻滚。","炖到用筷子能轻松插进蹄筋、轻轻一抖骨肉分离即成；关火后在锅里继续焖30分钟会更入味。","捞出猪蹄摆盘，卤汤滤渣后收浓至挂勺，淋在蹄子上，撒葱花。","配一碟糊辣椒+蒜末+醋调成的蘸水，啃蹄子时蘸着吃，这是青岩吃法。"],"key": "炒糖色必须在火小糖化时一次到位，颜色变枣红立刻下蹄，糖色发黑整锅都会苦。","tip": "卤汁别倒，滤渣后收稠装罐放冰箱，拌面、卤蛋都好用；没有喷枪可用明火燎毛，注意通风防烫。"},"青岩鸡辣角": {"time": "50分钟","level": "中等","servings": "3-4人份","ing": [{"n": "土鸡腿肉（切丁）","q": "600g","a": "减到450g一盘不够分；加到800g需分两锅爆炒，否则下锅后锅温骤降炒不出香"},{"n": "糍粑辣椒（开水烫过剁碎）","q": "150g","a": "加到250g辣度压过鸡香；减到100g只剩辣没有黔味"},{"n": "糊辣椒","q": "3勺（约20g）","a": "加到5勺糊香极足、颜色更红亮；减到1勺只剩生辣"},{"n": "干辣椒段","q": "40g","a": "加到70g辣中带苦、青岩正宗也就这个量；减到20g辣度不够"},{"n": "花椒","q": "6g","a": "加到12g麻得说话不清；减到3g麻味不足"},{"n": "姜蒜","q": "35g","a": "加到60g蒜味盖住鸡肉；减到18g腥味压不住"},{"n": "菜籽油","q": "120ml","a": "加到200ml成菜油腻；减到80ml则糍粑辣椒容易焦糊"},{"n": "折耳根","q": "50g","a": "加到100g药味盖过糊香；减到20g青岩味不足"},{"n": "熟白芝麻","q": "10g","a": "加到25g抢香；减到5g点缀即可"},{"n": "盐","q": "3g","a": "加到8g咸得盖住辣；减到1g鸡肉不入味"}],"steps": ["土鸡腿肉剔骨切2cm见方的丁，冷水下锅加姜片、料酒焯水3分钟，撇净浮沫捞出，务必彻底沥干水分。","另起干锅不放油，撒干辣椒小火慢焙3分钟至表皮起虎皮、边缘微焦，晾凉后放入石臼舂碎成糊辣椒。","锅内放菜籽油烧至六成热，下鸡丁大火爆炒3分钟至表面金黄发紧、边缘微焦，这层焦壳是青岩辣角的灵魂。","转中火下姜蒜末、干辣椒段、花椒炒1分半钟，炒出辣椒和花椒的香气。","下糍粑辣椒转小火炒3分钟，不停翻动至辣椒变成深红、油亮，边缘微微发褐即成；这步千万别用大火，糍粑辣椒一糊就发苦。","下折耳根段翻匀，加盐，大火翻炒1分钟让辣椒裹匀每颗鸡丁。","撒白芝麻出锅，青岩辣角讲究“干香不见油汁”，配一小碗糊辣椒干蘸碟一起上桌。"],"key": "青岩辣角用糍粑辣椒加糊辣椒双料，糍粑辣椒必须小火炒出深红油亮色，火大会糊苦；鸡丁先爆炒出焦壳再放辣椒。","tip": "正宗青岩做法还会加少量糍粑辣椒提前用油拌好静置一夜，风味更透；不吃折耳根可换香菜。"},"水城烙锅": {"time": "50分钟","level": "中等","servings": "3-4人份","ing": [{"n": "土猪肉（带皮薄片）","q": "400g","a": "减到250g烙锅没肉不够香；加到600g需分批下锅、否则一锅太挤烙不脆"},{"n": "洋芋片","q": "300g","a": "加到500g会抢走肉的香；减到150g不够吃"},{"n": "豆腐（老豆腐切块）","q": "250g","a": "加到450g需多烙5分钟、容易碎散；减到120g份量偏少"},{"n": "包菜（莲花白）","q": "300g","a": "加到500g出水多、烙锅会变湿；减到150g缺少爽脆口"},{"n": "香肠（广式/青岩腊肠）","q": "150g","a": "加到250g咸香盖过其他料；减到80g香气点缀即可"},{"n": "菜籽油","q": "80ml","a": "加到150ml底部积油、食物在油里泡着不脆；减到40ml容易粘锅"},{"n": "糊辣椒（蘸辣椒面）","q": "4勺（约30g）","a": "加到6勺太辣盖住食材味；减到2勺糊香不足、只剩辣"},{"n": "花椒粉","q": "3g","a": "加到8g麻得舌头发木；减到1g几乎无感"},{"n": "盐","q": "4g","a": "加到8g和香肠的咸打平发苦；减到2g食材本身够咸"},{"n": "葱花与折耳根（蘸碟）","q": "50g","a": "加到100g抢味；减到20g蘸碟太单调"}],"steps": ["土猪肉带皮切薄片，洋芋切1cm厚的片，豆腐切厚块，香肠切片；所有食材分盘装好，烙的时候一次只下一样。","另起干锅不放油，撒干辣椒小火焙至虎皮焦香，晾凉舂碎成糊辣椒，与花椒粉、盐拌匀成蘸辣椒面，装小碟备用。","六盘水烙锅用厚底砂锅或铸铁锅，锅烧热倒菜籽油，油纹刚起就下第一批食材。","下洋芋片平铺，中火慢烙5分钟，烙到两面金黄、边缘起脆壳，用锅铲压一压能断即成。","再下豆腐块和香肠片，继续中火烙3-4分钟，豆腐烙到两面焦黄带虎皮、香肠出油即可。","最后下包菜和肉片，大火快烙1-2分钟，锅气上来、菜梗还带脆时关火——肉片久烙会发柴。","出锅装大盘，桌上摆糊辣椒蘸碟，蘸着吃，这就是水城烙锅“边烙边吃、越烫越香”的样子。"],"key": "烙锅的灵魂是锅气：锅要烧到冒烟再下油、食材一次只铺薄薄一层，挤太满就成“煮”的了。","tip": "没有砂锅可用厚底铸铁锅或厚底不粘锅；蘸辣椒面里加一点盐和蒜末更香，蘸碟按1:1混糊辣椒和油辣椒更立体。"},"手撕豆腐": {"time": "30分钟","level": "简单","servings": "2人份","ing": [{"n": "老豆腐（卤水豆腐）","q": "400g","a": "减到250g撕不出多少丝、蘸水吃不饱；加到600g烤时出水多、外壳不脆"},{"n": "折耳根","q": "60g","a": "加到100g药味盖过豆香；减到30g特色不足"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香突出但盖住豆腐清甜；减到1勺只剩辣"},{"n": "辣椒水（凉白开+醋+糊辣椒）","q": "180ml","a": "加到280ml豆腐泡涨发软、失去“手撕”的粗粝感；减到100ml蘸不匀挂不住"},{"n": "菜籽油","q": "25ml","a": "加到50ml表面过油发腻；减到12ml粘锅皮不脆"},{"n": "蒜末","q": "15g","a": "加到30g蒜味刺鼻；减到8g香气不足"},{"n": "葱花","q": "15g","a": "加到30g抢味；减到8g偏淡"},{"n": "盐","q": "3g","a": "加到6g和辣椒水抢味；减到1g基本靠蘸水带咸"},{"n": "花椒粉","q": "2g","a": "加到5g麻得舌头发木；减到1g几乎无感"},{"n": "香醋","q": "10ml","a": "加到25ml尖酸盖过糊香；减到5ml酸味不够"}],"steps": ["老豆腐切成5cm见方的大块，用厨房纸反复吸干表面水分，晾10分钟让表面收紧。","平底锅刷菜籽油烧至六成热，放入豆腐块，中小火慢烙5-6分钟，烙到四面金黄起壳、用手按有弹性即成。","另起干锅不放油，撒干辣椒小火焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒，与花椒粉、盐拌匀。","折耳根洗净切细段，与蒜末、葱花、香醋、辣椒水调成蘸汁，静置3分钟让味道融合。","豆腐烙好后趁热用筷子从中间撕成粗条，撕得越不规则、纤维断面越多，蘸汁才挂得住——这是“手撕”和“切条”的区别。","撒上干糊辣椒面，淋入辣椒水，再点几滴菜籽油拌匀。","趁热吃，豆腐凉透后纤维变硬、蘸汁挂不上。"],"key": "必须趁热手撕：热的时候豆腐纤维是软的，能撕出毛糙的断面吸附蘸汁；凉了发硬就挂不住味。","tip": "有炭火最正宗，铁网或竹签架在炭火上烤两面更香；蘸汁里加一勺折耳根末就是贵州街头味道。"},"洋芋粑": {"time": "40分钟","level": "简单","servings": "2-3人份","ing": [{"n": "洋芋（黄心土豆）","q": "500g","a": "减到300g做3个小饼；加到700g需分两锅煎，否则压饼压不平"},{"n": "猪油（或菜籽油）","q": "40g","a": "加到70g饼面过油发腻、失去洋芋的粉糯；减到20g容易粘锅"},{"n": "糯米粉","q": "50g","a": "加到90g黏性足、能拉丝但会盖住洋芋味；减到20g饼心发散易碎"},{"n": "盐","q": "3g","a": "加到8g咸过头；减到1g味道寡淡"},{"n": "折耳根（蘸料）","q": "50g","a": "加到100g药味抢过洋芋香；减到20g黔味变淡"},{"n": "糊辣椒（蘸料）","q": "2勺（约15g）","a": "加到4勺糊香盖住洋芋的粉甜；减到1勺只剩辣"},{"n": "油辣椒（蘸料）","q": "1勺（约10ml）","a": "加到3勺辣度过重；减半则香辣不足"},{"n": "蒜末","q": "12g","a": "加到25g蒜味冲；减到6g香气淡"},{"n": "葱花","q": "15g","a": "加到30g抢味；减到8g偏淡"},{"n": "白芝麻（撒面）","q": "8g","a": "加到20g香味抢戏；减到4g点缀即可"}],"steps": ["洋芋去皮切厚片，蒸锅上汽后蒸20分钟，蒸到筷子能轻松插透、无硬芯。","趁热把洋芋压成泥，趁热加猪油、糯米粉、盐，同方向揉到泥团表面光滑不粘手；凉了就揉不匀会散。","取一团约120g搓圆压扁成1.5cm厚的圆饼，边缘按平整，饼面可压出十字花或用模具出形状。","平底锅烧热刷一层猪油，中小火煎4分钟，煎到一面起金黄脆壳、饼身微微鼓起来再翻面。","另一面再煎3-4分钟，两面都呈深金黄色、用手指按压略有弹性即成，晾1分钟外皮会更脆。","调蘸料：折耳根末、糊辣椒、油辣椒、蒜末、葱花拌匀。","洋芋粑装盘撒白芝麻，蘸料干拌或泡在辣椒水里吃，两种吃法都地道。"],"key": "洋芋必须蒸到透、趁热压泥趁热揉，凉洋芋泥揉进糯米粉会散，煎的时候饼会开裂漏馅。","tip": "按口味可做成甜口（白糖+芝麻）或咸口（盐+折耳根）；火太大会外焦内生，压饼时用锅铲按压能同时受热。"},"炸洋芋": {"time": "30分钟","level": "简单","servings": "2人份","ing": [{"n": "洋芋（黄心土豆）","q": "500g","a": "减到300g炸一盘不够分；加到700g需分两锅炸，否则油温骤降会粘连"},{"n": "菜籽油（炸用）","q": "800ml","a": "加到1.2L浪费且难控温；减到600ml需分批炸，油不够会互相粘"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香突出；减到1勺只剩辣味、少了烘焙香"},{"n": "辣椒面（普通）","q": "5g","a": "加到12g辣度盖过洋芋香；减到2g层次不足"},{"n": "花椒粉","q": "2g","a": "加到6g麻得发木；减到1g几乎无感"},{"n": "盐","q": "4g","a": "加到8g咸过头、辣椒面都尝不出；减到2g洋芋本身淡而无味"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g香气不足"},{"n": "折耳根（可选）","q": "40g","a": "加到80g药味抢戏；减到15g点缀"},{"n": "香菜（可选）","q": "20g","a": "加到50g香草味盖过糊香；减到10g即可"},{"n": "孜然粉（可选）","q": "3g","a": "加到8g抢味、偏离本地味；减到1g仅作点缀"}],"steps": ["洋芋去皮切3cm见方的滚刀块，用清水冲洗掉表面淀粉，捞出摊开彻底晾干水分——带水下油锅会剧烈爆溅。","另起干锅不放油，撒干辣椒小火焙至虎皮焦香，晾凉舂碎成糊辣椒，与辣椒面、花椒粉、盐拌匀成干香料面。","锅中倒菜籽油烧至六成热（180℃），先放一小块洋芋试油温：能立刻起密集小泡说明油温到位。","分批下洋芋块，中火炸4-5分钟，炸到表面起壳、颜色金黄，用筷子能扎透即捞出控油，别一次下太多。","捞出后马上撒干香料面，趁热拌匀——凉了辣椒面挂不上、也失去刚炸出的那口焦香。","撒葱花和折耳根段，翻拌两下让香料面分布均匀。","配一小碗辣椒水（醋+糊辣椒+凉白开）蘸着吃，或直接装袋当路上零嘴。"],"key": "洋芋下锅前必须晾干水分，油温要够高才能炸出“沙”的粗糙脆壳；炸好马上拌料，凉了香料挂不住。","tip": "土豆选黄心的，面粉含量高才够粉糯；白心的太脆容易炸空心。加一小勺醋到炸油里能让外皮更酥脆。"},"冰浆": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "冰块（碎冰或冰沙）","q": "400g","a": "加到600g化成水太多、成了稀糖水；减到250g太稠难吸、搅拌费劲"},{"n": "芒果（或其他水果）","q": "200g","a": "加到300g甜度足但果味被冰冲淡；减到100g香味不够"},{"n": "红糖浆（煮浓的糖水）","q": "50ml","a": "加到90ml齁甜盖住果香；减到25ml不够甜"},{"n": "糯米饭团（或小圆子）","q": "80g","a": "加到150g嚼到饱、也抢了水果味；减到40g口感偏单"},{"n": "炼乳","q": "30g","a": "加到60g奶味盖过一切；减到15g香气不足"},{"n": "椰浆","q": "40ml","a": "加到80ml太腻、挂喉；减到20ml椰香不足"},{"n": "花生碎","q": "20g","a": "加到40g香脆足但抢味；减到10g点缀即可"},{"n": "冰爽薄荷叶（可选）","q": "5g","a": "加到10g清凉感明显；减到2g仅作装饰"},{"n": "柠檬汁","q": "5ml","a": "加到15ml尖酸调亮果味；减到2ml甜味发闷"},{"n": "纯净水（打果泥用）","q": "60ml","a": "加到120ml果泥变稀挂不住杯壁；减到30ml太稠打不动"}],"steps": ["芒果去皮切块，与纯净水、柠檬汁一起用破壁机打成细腻果泥，倒出后静置2分钟让气泡消掉。","糯米饭提前蒸熟捏成小团，或用小圆子煮熟过凉水备用——冰浆里的小圆子是灵魂，糯米的黏是贵阳冰浆区别于普通冰沙的地方。","取大杯，先放一层碎冰，倒一层果泥，再加一勺红糖浆，重复铺两层，最后顶层铺满碎冰。","淋上炼乳和椰浆，撒花生碎，用长勺从杯底往上搅动，让果泥和糖浆融进冰里。","插上吸管，趁冷喝；冰浆要快喝，化开就变成甜水了。"],"key": "冰浆和冰沙的区别就在“冰+果+糯米”三件套：果泥要打细不能有渣，糖浆分层浇才好看好喝，搅的时候从底部往上带。","tip": "在家做先把果泥和糖浆调好冷藏备用，来客人只需铺冰舀料，2分钟出一杯；芒果换成草莓、火龙果、蜜瓜都好吃。"},"杨梅汤": {"time": "40分钟","level": "简单","servings": "3-4人份","ing": [{"n": "杨梅（新鲜）","q": "500g","a": "减到300g汤色淡、酸味不够集中；加到800g要加量糖并延长熬煮时间"},{"n": "冰糖","q": "80g","a": "加到130g齁甜、盖住杨梅的果香；减到50g酸得倒牙"},{"n": "清水","q": "1.5L","a": "加到2L味道寡淡；减到1L熬得浓、需小火防糊底"},{"n": "柠檬片","q": "3片","a": "加到6片酸得发苦；减到1片提亮即可"},{"n": "干桂花（可选）","q": "3g","a": "加到8g香气抢过杨梅；减到1g仅作点缀"},{"n": "山楂片（可选）","q": "10g","a": "加到25g酸得过冲；减到5g只添一点回甘"},{"n": "冰块（镇温用）","q": "200g","a": "加到400g汤被稀释太淡；减到100g镇温不足"},{"n": "老盐","q": "1g","a": "加到3g咸味压过酸味；不加也能喝"}],"steps": ["杨梅用清水冲洗干净，再用淡盐水浸泡10分钟逼出小虫，捞出用流水冲两遍、沥干。","杨梅逐颗检查并用牙签挑掉顶部的杂质，然后用手指轻捏几下——捏破的先吃，完整的留着熬汤。","锅中放清水和冰糖，大火烧开后放入完整杨梅，转中小火熬煮15分钟。","熬到汤汁变成深玫红色、杨梅完全煮破浮起时，用勺子把杨梅渣捞出，只留红亮的汤汁。","关火加柠檬片和干桂花，盖盖焖5分钟让香气融合，晾凉后冷藏。","吃的时候舀杨梅汤倒入杯中，加冰块镇温，酸甜开胃、解腻消暑。","剩下的杨梅果肉别倒，拌进酸奶或直接当果脯吃。"],"key": "熬杨梅汤全程中小火并不断搅动，糖浆沉底一旦焦化整锅发苦；杨梅必须用盐水泡过，否则有小虫。","tip": "贵州杨梅6月最好，选颜色深紫红、颗粒饱满的；汤熬好后加少许老盐或蜂蜜，酸甜会更立体。"},"米豆腐": {"time": "50分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "大米","q": "200g","a": "减到120g做出的块太软、切不成条；加到300g需延长凝固时间、碱水要同步加"},{"n": "清水（磨浆用）","q": "1.2L","a": "加到1.5L米浆稀、凝固后水分多口感发水；减到900ml浆稠难过滤"},{"n": "食用碱（草木灰水/石灰水）","q": "8g","a": "加到15g碱味重、豆腐发黄带苦；减到4g凝不住、浆水不成形"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣油盖过米香；减到1勺辣味不足、米豆腐的清甜出不来"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到3勺糊香足；减半只剩辣"},{"n": "折耳根","q": "40g","a": "加到80g药味抢过一切；减到20g黔味变淡"},{"n": "香醋","q": "15ml","a": "加到30ml尖酸发苦；减到8ml酸不够爽口"},{"n": "蒜末","q": "15g","a": "加到30g蒜味刺鼻；减到8g香气不足"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g偏淡"},{"n": "盐","q": "3g","a": "加到8g咸过头；减到1g基本靠辣椒油带咸"}],"steps": ["大米淘净后用清水浸泡3小时，沥干，加1.2L清水打成细腻米浆，用纱布过滤掉米渣，滤得越细成品越滑。","米浆倒入锅中小火加热，不停搅动防止粘底，熬到米浆冒大泡、体积明显变稠、颜色发白，约需15分钟。","另取小碗，把食用碱（或草木灰水、石灰水）用少量温水化开，分2-3次倒入米浆并立刻快速搅匀，浆体瞬间变稠、颜色转为微黄透明。","把米浆倒进抹了油的方盘或木盆，晃平，静置20-30分钟让其完全凝固成块，指压有弹性不塌即成。","另起干锅不放油，撒干辣椒小火焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒备用。","米豆腐倒扣出模，切成2cm粗条或菱形块，摆在盘里。","碗中放油辣椒、糊辣椒、蒜末、葱花、折耳根、盐、香醋调成料汁，浇在米豆腐上拌匀，冷吃最爽口。"],"key": "米豆腐靠碱水点浆，点浆必须少量多次并立刻搅匀，碱量过了会发黄发苦；凝固后要彻底放凉再切，切早了会散。","tip": "没有碱可用泡过米的水（米浆水）或草木灰滤出的灰水代替；米豆腐也可以煎了吃，两面煎黄再浇红油，是贵阳夜宵摊的常见吃法。"},"红油米豆腐": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "米豆腐","q": "400g","a": "减到250g一盘不够分；加到600g需另备大碗、红油用量同步加"},{"n": "自制红油（辣椒油）","q": "60ml","a": "加到100ml红油过多、米豆腐的清甜被完全盖住；减到30ml颜色不够红亮"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香突出；减到1勺只剩辣、缺少烘焙的香"},{"n": "油辣椒","q": "2勺（约20ml）","a": "加到4勺辣度压过一切；减到1勺红油味不够"},{"n": "香醋","q": "20ml","a": "加到35ml尖酸盖过辣椒香；减到10ml酸爽度不足"},{"n": "折耳根","q": "50g","a": "加到100g药味压过红油；减到25g特色变淡"},{"n": "蒜末","q": "15g","a": "加到30g蒜味刺鼻；减到8g香气不足"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g偏淡"},{"n": "油泼辣子（带辣椒面的）","q": "40g","a": "加到70g辣面颗粒多、抢米豆腐的滑；减到20g红油层次少一半"},{"n": "盐","q": "2g","a": "加到6g咸过头；减到1g靠红油自带咸度"}],"steps": ["米豆腐倒扣出模，切成2cm粗条，码在盘里摆整齐；刀口要利，一刀下去不回刀才不会把豆腐压碎。","另起干锅不放油，撒干辣椒小火慢焙3-5分钟至表皮起虎皮、边缘焦黑，晾凉后放入石臼舂碎成糊辣椒。","烧油至六成热，倒入油泼辣子用的辣椒面和芝麻，中小火炸3分钟至辣椒面呈红棕色、闻到焦香——火大会苦，颜色发黑就倒掉重来。","舀出两勺热油浇在辣椒面上激香，拌匀成红油，静置后红油析出、辣椒面沉底。","取碗放红油60ml、油辣椒2勺、糊辣椒2勺、香醋20ml、蒜末、葱花、盐拌匀成浇汁。","米豆腐条上撒折耳根碎，把调好的红油浇汁整个淋上去。","从底部轻轻翻拌让每块米豆腐挂满红油，冷吃最清爽，热的会有豆腥气。"],"key": "红油要用七成热油激香辣椒面，冷油激不出香味；米豆腐下锅前全程不加热，冷拌才滑嫩，热了就发水发腥。","tip": "自制红油可以一次多做：辣椒面加少量芝麻、少量盐，浇热油后加盖焖一夜更香；浇汁里加两勺泡椒水会更解腻。"},"绿豆粉": {"time": "45分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "绿豆淀粉（豌豆淀粉）","q": "150g","a": "减到100g粉丝偏软、透明度不够；加到200g粉丝更劲道、滑度下降"},{"n": "清水（调糊用）","q": "450ml","a": "加到600ml浆稀、成品会散不成形；减到350ml太稠难搅匀、起泡多"},{"n": "熟菜油（防粘用）","q": "20ml","a": "加到40ml表面过油、滑度反变差；减到10ml略粘"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣味盖过豆香；减到1勺豆香和辣味都不足"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到3勺糊香足；减半只剩辣"},{"n": "折耳根","q": "40g","a": "加到80g药味抢味；减到20g黔味不足"},{"n": "香醋","q": "15ml","a": "加到30ml尖酸盖过清香；减到8ml酸不够"},{"n": "蒜末","q": "15g","a": "加到30g蒜味刺鼻；减到8g香气不足"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g偏淡"},{"n": "盐","q": "3g","a": "加到8g咸过头；减到1g几乎无味"}],"steps": ["绿豆淀粉装盆，先加150ml清水调成稀浆搅匀无颗粒，再一次性倒入剩余300ml清水，搅成完全均匀的粉浆。","粉浆过一遍细筛或纱布，滤掉未溶开的颗粒，这步决定成品是否光滑无渣。","另取大锅，架上蒸笼，铺一张刷油的蒸盘或不锈钢盘。","把粉浆倒入蒸盘，摊平到厚度约3mm，大火蒸8-10分钟，蒸到浆体完全凝固、变成半透明即可。","取出晾凉5分钟，用刀在表面划成宽条，用手指或刀沿划口一卷就成绿豆粉条，滑溜弹牙。","烧一锅水，加少许盐，水开后把绿豆粉条下锅烫10-15秒，捞出沥干；也可直接凉拌。","碗中放油辣椒、糊辣椒、蒜末、葱花、折耳根、香醋、盐调汁，浇在粉条上拌匀即可食用。"],"key": "粉浆必须过筛且蒸到完全透明才熟，半透明带白芯就是没蒸透；粉条要凉透再卷，烫的时候卷会散。","tip": "铜仁绿豆粉也常做成汤食：碗里放原汤或清水、点油辣椒和折耳根，把粉条挑进去烫熟就是一顿；不习惯酸辣就少放醋。"},"铜仁社饭": {"time": "3小时","level": "中等","servings": "4-5人份","ing": [{"n": "糯米","q": "500g","a": "减到350g份量不够、蒸出来太散；加到700g需延长浸泡和蒸制时间"},{"n": "腊肉（肥瘦相间）","q": "200g","a": "加到350g太咸、抢青蒿香；减到120g腊味不足"},{"n": "青蒿（艾蒿/清明菜）","q": "150g","a": "加到250g青草味发苦；减到80g香气不够、社饭特色变淡"},{"n": "紫菜（碎）","q": "30g","a": "加到60g嚼到渣；减到15g量不足"},{"n": "黄豆（泡发）","q": "50g","a": "加到100g豆子抢口感；减到25g点缀不够"},{"n": "盐","q": "5g","a": "加到10g和腊肉的咸打平；减到2g腊肉出油后刚好"},{"n": "胡辣椒/糊辣椒（拌食）","q": "2勺（约15g）","a": "加到4勺辣味盖过青蒿香；减到1勺只剩辣"},{"n": "猪油","q": "30g","a": "加到60g饭粒太亮太腻；减到15g米色偏暗、香味淡"},{"n": "葱花","q": "20g","a": "加到40g抢味；减到10g偏淡"},{"n": "清水（浸泡与蒸制用）","q": "600ml","a": "加到900ml饭偏软不成粒；减到450ml中间层夹生"}],"steps": ["糯米用清水浸泡4小时至发白、用手能捻碎，沥干备用；黄豆提前泡发2小时。","青蒿只取嫩尖，洗净后用沸水焯30秒，捞出挤干水分切成细末——焯水能去掉大部分苦涩味，这步不能省。","腊肉切小丁，肥瘦分开。锅中不放油，下肥肉丁小火干煸3分钟，煸出猪油至微微焦黄，再下瘦肉丁炒香，盛出。","锅中加猪油烧热，倒入糯米翻炒3分钟，让每粒米裹上油、颜色发亮，这一步决定成品是油亮还是发白。","把青蒿末、紫菜碎、炒好的腊肉丁、黄豆和糯米拌匀，铺入蒸笼，按1:1.2的米水比例加清水没过糯米一指节。","大火蒸40分钟，转小火再焖20分钟，蒸到筷子插下去不夹生、米粒能捏散即成。","出锅撒盐、葱花和糊辣椒，拌匀食用；凉了会结块，凉了再上锅蒸十分钟就回软。"],"key": "青蒿必须焯水去苦、糯米必须先用猪油炒过再蒸，两步缺一不可，否则社饭会苦且米粒发白不油亮。","tip": "社饭是苗侗“社日”祭祀后分食的饭，用艾蒿或紫苏也可；蒸的时候在锅边放一碗水，水干就续，防蒸干。"},"贵阳糯米饭": {"time": "40分钟","level": "简单","servings": "2-3人份","ing": [{"n": "糯米","q": "400g","a": "减到250g份量偏少；加到550g需多泡1小时、蒸的时间也更长"},{"n": "猪腿肉（做脆哨）","q": "250g","a": "减到150g脆哨量不足、糯米饭少一口香；加到350g需多炸3分钟"},{"n": "油辣椒","q": "4勺（约40ml）","a": "加到6勺辣油盖过脆哨的肉香；减到2勺红油不足、糯米饭发白"},{"n": "糊辣椒","q": "2勺（约15g）","a": "加到4勺糊香盖过折耳根；减到1勺只有辣味"},{"n": "折耳根","q": "80g","a": "加到150g药味抢过一切；减到40g特色变淡"},{"n": "咸菜（酸萝卜/芽菜）","q": "80g","a": "加到150g太咸、抢味；减到40g解腻作用不足"},{"n": "葱花","q": "30g","a": "加到50g抢味；减到15g香气偏淡"},{"n": "猪油","q": "30g","a": "加到50g饭太腻；减到15g米粒不够亮"},{"n": "盐","q": "3g","a": "加到6g咸过头；减到1g基本靠咸菜和辣椒油带咸"},{"n": "花生米（油酥）","q": "40g","a": "加到80g太脆抢味；减到20g点缀即可"}],"steps": ["糯米淘净后用清水浸泡3小时至发白，沥干，拌入猪油和盐拌匀，让米粒都裹上油。","蒸锅上汽后把糯米铺平入笼，大火蒸30分钟，蒸到米粒完全透亮、用勺子能轻松压散但仍保持颗粒感。","趁热另起干锅焙糊辣椒：撒干辣椒小火慢焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒。","猪腿肉剁成末，锅里放油烧热，下肉末中火煸炒5-6分钟，煸到水分收干、颜色金黄发脆，成脆哨，盛出晾凉。","咸菜切碎挤干水分，折耳根切细段，花生米油酥备用，全部备好。","把蒸好的糯米饭倒进大盆，趁热拌入脆哨、油辣椒、糊辣椒、折耳根、咸菜、葱花，搅拌均匀让每一粒米都挂上红油。","撒盐和油酥花生米再翻拌两下，装碗或用荷叶垫着打包带走，凉了也不影响风味。"],"key": "糯米饭必须趁热拌油辣椒，凉了油凝在米上拌不匀、油辣椒的香气也出不来；脆哨要煸到干香才脆，不能炒成肉末酱。","tip": "正宗贵阳糯米饭会加炸洋芋、卤肉或青菜按口味自由选配；喜欢更香可把猪油换成鸡油，拌出来更清爽。"},"贞丰糯米饭": {"time": "40分钟","level": "简单","servings": "2-3人份","ing": [{"n": "糯米","q": "400g","a": "减到250g不够两人吃；加到550g需多泡1小时否则蒸不透"},{"n": "猪腿肉（脆哨）","q": "200g","a": "减到120g肉香不足；加到300g需多煸5分钟才干香"},{"n": "花生米（油酥或炒香）","q": "60g","a": "加到100g花生香盖过米香；减到30g缺了这份酥香"},{"n": "油辣椒","q": "3勺（约30ml）","a": "加到5勺辣味压住花生的香；减到1勺颜色发白"},{"n": "糊辣椒","q": "1勺（约8g）","a": "加到3勺糊香更足；减半只剩辣味"},{"n": "猪油","q": "35g","a": "加到60g米饭过亮过腻；减到20g米色偏暗、少了油润感"},{"n": "葱花","q": "30g","a": "加到50g抢味；减到15g香气不足"},{"n": "折耳根","q": "50g","a": "加到100g药味盖过花生香；减到25g黔味不足"},{"n": "盐","q": "3g","a": "加到8g咸过头；减到1g靠脆哨和辣椒油带咸"},{"n": "酱油（点味用）","q": "8ml","a": "加到20ml发咸带苦；减到3ml基本尝不出"}],"steps": ["糯米淘净泡3小时至发白，沥干后拌入猪油和盐，铺平入蒸笼。","大火蒸30分钟至米粒透亮、含水刚好，蒸好后先焖5分钟再开盖，避免水汽滴回面上。","另起干锅不放油，撒干辣椒小火焙3分钟至虎皮焦香，晾凉舂碎成糊辣椒备用。","猪腿肉剁末，锅放少许油烧热，下肉末中火煸炒5分钟至收干发金黄成脆哨；花生米下油锅炸1分钟至微黄，捞出压碎。","折耳根切细段，葱花切好，咸菜（如用）切碎挤干水备用。","把蒸好的糯米饭倒进木盆，趁热加酱油、酱油色的红油辣椒、糊辣椒、盐和葱花，同方向拌到每粒米都均匀发红发亮。","拌入脆哨碎、花生碎和折耳根，再翻拌均匀即可装碗；贞丰糯米饭讲究“油亮”，火候不到米色发白就不正宗。"],"key": "贞丰糯米饭的招牌是“油亮”：猪油必须拌进米里、蒸后趁热用红油辣椒上色，凉了米色发白、油凝成块。","tip": "花生米现炸现压才香，密封罐装的花生米会回软；可按喜好加煎蛋、卤牛肉片或酸萝卜，黔西南街头都是这样自由搭配。"},"破酥包": {"time": "约2小时（发面1小时+二次醒发20分钟+蒸12分钟）","level": "中等","servings": "3-4人份（约8个包子）","ing": [{"n": "中筋面粉","q": "500g","a": "改用高筋粉600g皮更有嚼劲但层次偏硬；减到400g并加100g澄粉可得更软糯，但破酥的层次感会变弱"},{"n": "酵母","q": "5g","a": "加到8g发得更快但容易发过头塌陷回缩；减到3g需延长发酵20分钟"},{"n": "温水","q": "280ml","a": "加到320ml面团偏软塌、不好擀开；减到240ml则面团偏硬、油酥层次变薄"},{"n": "猪油","q": "60g","a": "这是破酥的核心，加到100g起酥更明显、油脂香更足；减到30g则只剩普通发面味、完全不出酥"},{"n": "油酥用面粉","q": "120g","a": "加到180g油酥更酥但易掉渣、皮下漏油；减到80g酥层薄，层次分辨不出来"},{"n": "花椒粉","q": "3g","a": "加到6g椒麻香突出，是贵州本地做法；减掉不放则只剩腻人猪油香"},{"n": "盐","q": "5g","a": "加到9g能压住猪油的腻感、吃口更清爽；不放则整包只有油香没有回味"},{"n": "咸馅用芽菜或折耳根末","q": "150g","a": "加到250g咸味更足、配稀饭最出彩；减到80g馅心单薄，一口下去几乎只有面皮"},{"n": "猪肉末","q": "200g","a": "加到300g肉汁更足更香；减到120g口感发干，咬开没有汁水"},{"n": "白糖（做甜馅时用）","q": "60g","a": "加到90g甜味更足；减到40g偏淡，需靠炒香芝麻提味"}],"steps": ["面粉、酵母、2/3温水揉成偏软的面团，盖湿布放温暖处发酵约60分钟，至体积两倍大、扒开呈蜂窝状。","发好的面团揉匀排气，分成10份小剂子，擀成薄圆片；另把猪油、面粉、花椒粉、盐混合搓匀成油酥。","取一张面皮厚厚抹上一层油酥（用量要足，中途可补抹），从一边卷成长卷，末端接缝抹水粘牢。","把长卷从中间对折成两段，用擀面杖从折缝向两端擀开，擀到面皮半透明、能隐约透光为佳。","把擀开的大片卷成小螺旋卷，立起擀成直径约10cm的圆皮，包入馅料，捏紧收口朝下摆入蒸笼，二次醒发20分钟至明显变轻。","蒸锅水开后上屉，大火蒸12分钟，关火焖3分钟再揭盖，避免骤冷回缩塌陷；出锅趁热吃最酥。"],"key": "破酥的关键在油酥：面皮与油酥之间必须完全隔开油脂，面片要擀到半透明再卷，折叠一次到位，蒸出来才有能层层撕开的酥皮。","tip": "新手最常把面皮擀破导致漏油，先拿一张练手；想吃甜口就把馅换成白糖加炒香芝麻、花生碎，油酥卷法完全一样。"},"糊辣椒蘸水": {"time": "约50分钟（焙辣椒15分钟+舂制10分钟）","level": "中等","servings": "3-4人份（可吃一周）","ing": [{"n": "皱皮干辣椒或朝天椒","q": "150g","a": "换成二荆条味道偏香不辣、缺糊香；加到250g则极辣，蘸水只需一小勺就够"},{"n": "蒜瓣","q": "30g","a": "加到50g蒜香更冲；减到15g则糊辣椒只剩辣和糊香，缺蒜的圆润感"},{"n": "姜块","q": "15g","a": "加到25g去腥增辛；减掉不放则香气单薄、发闷"},{"n": "盐","q": "8g","a": "加到12g更保味、久存不坏；减到4g则香氣平淡且容易发霉"},{"n": "菜籽油","q": "40ml","a": "加到70ml油更亮、拌面不干；减到20ml则干辣椒难舂碎、油香也不足"},{"n": "陈醋","q": "40ml","a": "加到60ml酸味更明显；减到20ml则只辣不酸，压不住牛油味"},{"n": "生抽","q": "25ml","a": "加到40ml咸鲜更足；减到10ml则蘸水颜色浅、味道单薄"},{"n": "白糖","q": "4g","a": "加到8g能中和酸辣、显出糊辣椒的回甘；减掉不放则只剩辣和酸、层次发硬"},{"n": "味精","q": "2g","a": "加到4g鲜味提升明显；减掉不放则蘸水香气足但不够鲜"},{"n": "凉白开","q": "80ml","a": "加到150ml蘸水变稀、挂不住食物；减到30ml则太稠，筷子挑起来成坨"}],"steps": ["干辣椒去蒂、剪开去籽（籽多则更辣），放进干燥无油的铁锅或砂锅，小火慢焙并不停翻动。","焙到辣椒表皮起焦斑、颜色由暗红转深褐、手捏干脆并透出焦香，约需10-15分钟，立刻倒出摊开晾凉。","焙过头的辣椒会发苦，一旦闻到底焦味就要马上离火，摊开放凉后再加蒜、姜、盐。","把所有材料放进石臼，边舂边淋入菜籽油，舂到颗粒如粗砂、发出\"沙沙\"声即停，切忌舂成粉状。","舂好的糊辣椒装入玻璃罐密封常温保存，放得越久糊香越浓，一个月后风味更足。","蘸水：碗中放2勺糊辣椒、生抽、陈醋、白糖、味精，兑入凉白开搅拌成稠糊状即可。","调稀稠度：蘸水挂勺太稠就加醋和白开，太稀就再补一勺糊辣椒，边尝边调。"],"key": "焙辣椒必须干锅无油小火慢焙，焙过头发苦；舂的时候要保留颗粒不能成粉，糊辣椒的\"糊\"字就在这口粗砂般的口感里。","tip": "正宗糊辣椒用的是皱皮辣椒（也叫牛角椒），没有就用本地朝天椒，别用墨西哥大辣椒，味型不对；吃不了辣的可以把焙好的辣椒与焙过的蒜、姜一起舂，单独留一半糊辣椒不舂太细。"},"牛瘪火锅": {"time": "约6小时（牛瘪需提前发酵3-5天，牛骨汤4小时）","level": "稍难","servings": "4-5人份","ing": [{"n": "牛瘪汁（新鲜牛宰杀后取出的胆汁与胃液）","q": "150ml","a": "这是灵魂，减到50ml只剩草香没有那股独特鲜酸；加到300ml则酸臭冲、抢了牛肉的鲜味"},{"n": "牛筒骨或牛尾骨","q": "1500g","a": "加到2000g汤更浓、涮煮时更经得起烧；减到1000g汤味寡淡需另加浓汤宝"},{"n": "黄牛后腿肉、牛百叶（涮用）","q": "肉800g、百叶300g","a": "肉加到1200g够5-6人，百叶加到500g更耐涮；肉减到500g一人两片就见底，百叶减到150g则涮不出几片"},{"n": "豆腐、鸭血","q": "豆腐300g、鸭血200g","a": "豆腐加到500g吸汁更好吃，鸭血加到400g口感更丰富；豆腐减到150g会吸不住酸汤，鸭血减到100g解腻作用弱"},{"n": "糊辣椒","q": "60g（3勺）","a": "加到100g辣香更足；减到30g只剩辣味没有糊香，偏燥"},{"n": "姜片、蒜瓣","q": "各30g","a": "姜加到50g压牛膻更有效；蒜减半则香型不完整"},{"n": "花椒、干辣椒段、香叶、草果、白芷","q": "共30g","a": "加到50g香料味更厚；减到15g汤底会偏素、缺复合香"},{"n": "折耳根、蒜苗、葱段","q": "各100g","a": "折耳根加到200g草香更足；减到50g则少了一点贵州味"},{"n": "菜籽油","q": "50ml","a": "加到80ml红油更亮；减到30ml糊辣椒容易焦糊"},{"n": "盐、味精","q": "盐15g、味精3g","a": "盐加到25g配牛瘪的酸才够味；减到5g则发酵的酸味顶得慌"}],"steps": ["牛瘪处理：取新鲜宰杀的牛胆汁与胃液，滤去渣滓和血水，装入玻璃坛密封，放在阴凉处自然发酵3-5天（天冷可发酵7天），表面浮一层白膜属正常现象，发酵后呈酸臭带鲜香。","牛骨冷水下锅焯出血沫，捞出冲洗干净；另起大锅加姜块、葱段、香叶、草果、白芷和8000ml清水，小火慢熬4小时，撇净浮沫，汤色转奶白。","另起炒锅放菜籽油烧至五成热，下姜蒜末、干辣椒段、花椒小火爆香，倒入糊辣椒转中火炒1分钟，炒到红油析出、糊香冲鼻。","把熬好的牛骨汤倒入炒锅煮沸，调入牛瘪发酵汁50ml，中火煮2-3分钟，让生腥气挥发掉即可，久煮会让牛瘪的鲜香挥发散失。","加盐、味精调味，下豆腐块和鸭块煮5分钟入味，豆腐吸汤后变得紧实不碎。","另备黄牛肉片、牛百叶、豆腐皮、时蔬、折耳根、蒜苗上桌；百叶在滚汤里烫8秒、牛肉片烫15秒，捞出立刻蘸糊辣椒蘸水吃。","汤底全程保持滚烫，边吃边加汤，牛瘪味会随着煮沸越煮越香。"],"key": "牛瘪必须提前发酵3天以上才去腥出香，发酵时间不够会有明显腥膻；下锅后只能煮2-3分钟，久煮牛瘪的鲜味就挥发了。","tip": "买不到鲜牛瘪可用成品牛瘪汁（网上有售），按说明兑汤；怕膻的人第一次先用50ml并让店家用纱布过滤汤面浮油。"},"从江香猪": {"time": "约2小时（含腌制与浸泡）","level": "中等","servings": "4-5人份","ing": [{"n": "从江香猪后腿（带皮）","q": "1条约1200g","a": "换成普通五花肉油脂厚、皮粗不脆；加到1500g需同比例延长煮制10分钟"},{"n": "麦芽糖","q": "30g","a": "加到50g皮色更红亮发脆；减到15g上色浅、脆皮效果弱"},{"n": "陈醋","q": "30ml","a": "加到50ml脆皮更酥响；减到10ml皮偏硬、缺少松脆感"},{"n": "老姜、葱","q": "姜50g、葱2根","a": "姜加到80g去腥更彻底；减到20g则姜香不足、仍有杂味，葱加到4根香气更足，减半则去腥效果打折"},{"n": "花椒","q": "10g","a": "加到15g麻香更明显；减到5g几乎尝不出"},{"n": "八角","q": "2个","a": "加到4个香料味更浓；不放则只有姜葱味，偏清淡"},{"n": "料酒","q": "60ml","a": "加到100ml焯水去腥更彻底；减到30ml腥味压不住"},{"n": "生抽","q": "50ml","a": "蘸碟用，加到80ml咸度足；减到20ml蘸汁太淡"},{"n": "盐","q": "12g","a": "加到20g入味更深；减到5g肉心偏淡"},{"n": "冰水","q": "一盆（约5L）","a": "量少无法没过猪腿、皮激不脆；用冷水代替则皮质变硬口感发柴"}],"steps": ["香猪洗净擦干，用竹签在皮上戳若干小孔便于入味，也利于起脆皮；用盐和料酒抹遍全身，腌制30分钟。","锅中加水，放入姜块、葱段、花椒、八角、料酒大火烧开，提着猪腿皮朝上先入锅烫30秒，让皮骤然收缩。","把猪腿完全浸没，转小火保持\"似开非开\"的微沸状态，不加盖，煮35-40分钟；筷子插到最厚处不带血水即熟，关火再焖10分钟。","捞出立刻放入冰水中浸15分钟，表皮骤然收紧变脆——这一步是从江香猪\"皮脆肉嫩\"的关键，缺了就前功尽弃。","取出擦干水，皮面刷上麦芽糖30g、醋30ml、清水20ml煮开的脆皮水，200℃烤箱烤12分钟或挂风口风干一夜。","取下斩件装盘，皮朝上；另备姜末、葱花、蒜泥、生抽调成蘸碟，蘸着吃。"],"key": "白切的火候是\"小火微沸、不加盖\"，大火滚煮会让肉变柴；最后冰水激皮和脆皮水两个动作都不能省，否则皮绵软不脆。","tip": "想吃烤的就把煮好的猪腿用叉子固定，皮面刷脆皮水后用炭火或空气炸锅200℃烤25分钟，中途翻面两次；蘸碟里加2勺糊辣椒就是黔东南吃法。"},"三穗血浆鸭": {"time": "约1小时","level": "中等","servings": "3-4人份","ing": [{"n": "三穗麻鸭","q": "1只（约1200g）","a": "换成普通肉鸭则出油多、肉粗；加到1500g需多炖10分钟"},{"n": "新鲜鸭血（已凝固）","q": "200g","a": "加到400g腥味被压得更足；减到100g腥气偏重"},{"n": "鸭肠与鸭肝","q": "200g","a": "加到300g口感更丰富；减到100g则少了脆嫩的内脏香"},{"n": "糊辣椒","q": "80g（4勺）","a": "加到120g辣度明显上去了；减到40g只剩辣没有糊香，偏燥"},{"n": "豆豉","q": "20g","a": "加到35g发酵豉香更浓；减到10g则香气寡淡、鸭血腥味明显"},{"n": "姜末、蒜末","q": "15g、30g","a": "蒜加到50g更香；姜减半则血腥气压不住"},{"n": "干辣椒段、蒜苗段","q": "10g、30g","a": "干辣椒加到20g辣度更足；减半则层次少一半"},{"n": "料酒","q": "30ml","a": "加到50ml去腥更干净；减到15ml鸭腥味出不来"},{"n": "生抽","q": "20ml","a": "加到35ml咸鲜更足；减到10ml颜色淡、味道不够"},{"n": "盐、白糖","q": "4g、3g","a": "盐加到7g够压鸭油；糖加到6g可提鲜解辣，减掉则味道发闷"}],"steps": ["宰鸭时留鸭血，装入干净碗中加少量盐搅匀，撇去浮沫，静置到完全凝固后切成1cm见方的块。","鸭肉斩成3cm块，冷水下锅加姜片、料酒焯3分钟去血水，捞出冲净；鸭肠鸭肝洗净切段，另焯1分钟去腥。","热锅放油烧至六成热，下姜蒜末、干辣椒段小火煸香，下豆豉炒1分钟出酱香。","倒入鸭块转中火煸炒3分钟，炒到鸭皮出油、边缘焦香；下鸭肠鸭肝再炒1分钟。","倒入鸭血块，加糊辣椒、生抽、盐、白糖，中火翻炒2分钟，让血块均匀裹上辣料。","加少许清水焖3分钟至鸭肉入味、鸭血不散，最后大火收汁，撒蒜苗段出锅。"],"key": "鸭血必须完全凝固后再下锅且只在最后翻炒，久炒会散成渣；糊辣椒最后下锅短炒1分钟，久炒发苦。","tip": "鸭血凝固后拌一点猪油炒不易粘锅；不吃内脏的人可只用鸭血和鸭肉，但少了鸭肠的脆感；配一碗白米饭最下饭。"},"镇远陈年道菜": {"time": "约2小时（蒸制90分钟）","level": "中等","servings": "4-5人份","ing": [{"n": "镇远陈年道菜（腌三年以上的腌青菜）","q": "300g","a": "加到450g酸味更足、配肉更香；减到150g则咸香撑不起这道菜"},{"n": "五花肉","q": "600g","a": "加到800g油多更香；减到400g则一人一片不够吃"},{"n": "豆豉、蒜末","q": "30g、30g","a": "豆豉加到50g发酵香更浓、配腌菜极搭，减到10g香味不足；蒜末加到50g蒜香盖过道菜的酸，减到15g则香气单薄"},{"n": "姜末","q": "15g","a": "加到25g去腥提味；减掉不放味道会发闷"},{"n": "老抽","q": "20ml","a": "加到30ml颜色更深亮；减到10ml肉色偏白不上镜"},{"n": "生抽","q": "30ml","a": "加到50ml咸度足；减到15g（15ml）则偏淡需另补盐"},{"n": "料酒","q": "40ml","a": "加到60ml焯水去腥更彻底；减到20ml肉腥味重"},{"n": "白糖","q": "10g","a": "加到18g可中和道菜的酸咸；减掉不放则又酸又咸、难以下饭"},{"n": "花椒","q": "5g","a": "加到10g麻香突出；减到2g几乎无感"},{"n": "菜籽油","q": "80ml","a": "加到120ml炸肉更透亮；减到50ml肉片炸不出金黄边"}],"steps": ["道菜用清水冲洗两遍，挤干水分切成3cm长的段；再入清水浸泡10分钟去多余盐分，尝一下咸淡——腌三年的道菜很咸，泡水是必须的。","五花肉切1cm厚、8cm宽的片，冷水下锅加姜片、料酒焯3分钟去血水，捞出沥干。","锅内放菜籽油烧至六成热，肉片下锅炸至两面金黄、边缘微微卷起，捞出控油——这是扣肉能定型不塌的关键。","另起锅放少量油，小火炒香豆豉、蒜末、姜末，炒到出红油，下道菜段转中火炒2分钟，加生抽、老抽、白糖炒匀。","取耐热蒸碗，碗底铺一层炒好的道菜（厚约2cm），把炸好的肉片皮朝下整齐码放在上面，一层压一层。","蒸锅水开后上碗，大火蒸90分钟，中途添一次热水；取出倒扣在盘中，把原汁收稠淋在肉上，撒葱花。"],"key": "扣肉必须\"皮朝下\"码放并压实，再大火蒸够90分钟以上，肉才能酥烂到用筷子一夹就断、倒扣出来还不散。","tip": "蒸道菜时碗口扣个盘子防止蒸汽滴落影响口感；没有道菜可用雪菜、芽菜或酸菜代替，但酸度要减半；蒸剩的汤汁留着拌饭。"},"安顺裹卷": {"time": "约40分钟","level": "简单","servings": "3-4人份","ing": [{"n": "安顺米皮","q": "300g","a": "换成干米皮需先泡发再蒸；加到400g够5人；减到200g则一人两条不够"},{"n": "折耳根末、香菜末","q": "50g、30g","a": "折耳根加到100g草香更足（安顺人最爱）；减到20g则少了灵魂味道"},{"n": "黄瓜丝","q": "100g","a": "加到150g更解腻爽口；减到50g水气重、卷起来会漏汤"},{"n": "豆腐皮丝","q": "50g","a": "加到80g口感更丰富；减掉不放则单薄、清淡"},{"n": "猪肉末","q": "100g","a": "加到150g肉香足；减到50g基本尝不出肉味"},{"n": "姜蒜末","q": "30g","a": "加到45g去腥提味；减到15g则肉末腥"},{"n": "糊辣椒","q": "60g（3勺）","a": "加到90g（4勺半）辣味更冲；减到30g蘸水只有酸没有辣"},{"n": "陈醋","q": "30ml","a": "加到45ml酸味更开胃；减到15ml则香辣压不住"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到10ml味道寡淡"},{"n": "凉白开","q": "50ml","a": "加到80ml蘸汁更好调开；减到20ml则太稠挂不住"}],"steps": ["米皮切成12cm见方的片，摆在蒸屉里，水开后大火蒸5分钟，蒸到米皮柔软能弯而不破，摊开晾到不烫手。","锅内放油烧五成热，下姜蒜末和猪肉末炒散炒香，直到肉末发干、微微焦香，盛出晾凉（晾凉才不会烫熟生菜）。","案板上铺一张米皮，依次码上折耳根末、香菜末、黄瓜丝、豆腐皮丝、炒好的肉末，四边各留2cm的空。","从一边卷成紧实的筒，接口朝下摆着、不封口——安顺人吃的就是这个开口朝上的样子，方便蘸汁。","用刀把卷粉斜切成两段，摆入盘中。","蘸料：糊辣椒用陈醋、生抽、凉白开调成酸辣汁；也可以直接配\"清汤\"（煮米皮的清汤加盐、蒜末、葱花）同吃，这是安顺最本地的吃法。"],"key": "米皮只能蒸软不能蒸烂；馅料要少而精，太多会漏；肉末必须先炒香再晾凉才入卷，热的肉末会把折耳根和黄瓜烫软出水。","tip": "夏天现做现吃最好；一次可多卷十几条用湿布盖住冷藏，蘸汁里的醋可以换成酸汤（红酸汤兑水），更本地。"},"夺夺粉": {"time": "约30分钟","level": "简单","servings": "2-3人份","ing": [{"n": "宽粉条（安顺、遵义宽粉）","q": "300g","a": "换成细粉口感不同但也可；加到400g够4人；减到200g一人一小碗"},{"n": "菜籽油","q": "40ml","a": "加到60ml锅底更香、滑粉更顺口；减到20ml糊辣椒易焦苦"},{"n": "糊辣椒","q": "60g（3勺）","a": "加到90g辣香更足；减到30g只有辣味没有糊香，偏燥"},{"n": "豆腐乳","q": "30g（2块）","a": "加到45g（3块）发酵香更浓；减到15g则少了一味关键的咸鲜"},{"n": "豆豉","q": "15g","a": "加到25g豉香足；减到5g香气出不来"},{"n": "姜末、蒜末","q": "10g、20g","a": "蒜加到35g更香；姜减半去腥力弱"},{"n": "葱花、折耳根末","q": "各30g","a": "折耳根加到60g草香足；减半则味道不正宗"},{"n": "高汤或清水","q": "600ml","a": "加到900ml汤多更润、粉更入味；减到400ml汤少粉干、味道集中但容易咸"},{"n": "瘦肉片","q": "150g","a": "加到250g更丰盛；减到80g则像一碗素粉"},{"n": "油豆腐、青菜与洋芋片","q": "100g、150g","a": "洋芋片加到250g更抗煮；减半则锅底太空"}],"steps": ["粉条用温水泡30分钟到软即可（不要泡透，下锅再煮会更筋道）；瘦肉片用少许生抽、淀粉抓匀腌10分钟。","小锅或砂锅烧热，倒入菜籽油烧至五成热，下姜蒜末、豆豉小火炒香，豆豉炒到微微发黑出味。","加豆腐乳用锅铲压成泥、糊辣椒入锅，转中火翻炒1分钟，直到红油析出、糊香冲鼻——这一步决定整锅的辣香味。","倒入高汤或清水大火烧开，转中火煮3分钟，让豆腐乳和糊辣椒完全化开、汤色转红。","下粉条，用竹签挑散，中火煮4分钟到粉条透明、没有白心。","加肉片、油豆腐、洋芋片、青菜煮2-3分钟，肉片变色、青菜断生即关火。","撒葱花和折耳根末，端上桌，削尖的竹签插着吃，这就是\"夺夺\"。"],"key": "糊辣椒必须先在油锅里煵香再兑汤，直接把干糊辣椒倒进汤里只会苦不香；豆腐乳要压碎化开，颗粒化不开会味道不均。","tip": "安顺吃法最后会另加一勺糊辣椒干碟，爱吃辣的自己拌；竹签用竹子削尖泡水防裂，不要用牙签代替。"},"镇宁波波糖": {"time": "约1.5小时","level": "稍难","servings": "4-5人份（约20块）","ing": [{"n": "麦芽糖（饴糖）","q": "500g","a": "加到600g更甜更韧；减到350g则甜度不够、也不够酥"},{"n": "白芝麻","q": "200g","a": "加到280g芝麻香更浓、层次更多；减到120g口感偏单一"},{"n": "花生碎","q": "80g","a": "加到120g更香口更丰富；减到30g则少了酥脆口感"},{"n": "白糖（夹心）","q": "100g","a": "加到150g夹心更甜更明显；减到50g则夹心不甜、层次弱"},{"n": "熟芝麻粉","q": "50g","a": "加到80g夹心更香；减到20g则夹心只有糖没有香"},{"n": "熟菜籽油","q": "30ml","a": "加到50ml糖团更润更好揉；减到15ml揉制时容易粘手开裂"},{"n": "盐","q": "3g","a": "加到5g甜而不腻、能衬出芝麻香；不放则只有甜"},{"n": "炒熟糯米粉（防粘用）","q": "20g","a": "加到40g防粘效果更好；减到5g切块时容易粘连"},{"n": "清油（刷模防粘）","q": "20ml","a": "加到40ml切面更亮；减到10ml表面略黏"},{"n": "干桂花","q": "5g","a": "加到10g清香更明显；不放则只有芝麻香"}],"steps": ["麦芽糖放进干净无水的厚底锅，小火加热，用糖铲不停翻搅，熬到糖浆能拉出细丝、颜色呈琥珀浅黄，控制在240℃左右，糖稀流下能迅速变硬就起锅。","端到案板上趁热加入熟菜籽油和盐，反复揉搓、折叠成松软的白色糖团——这一步叫\"打糖\"，靠手工揉打让糖浆充气起酥，是\"波波\"二字的核心。","把芝麻、花生碎分成两份，一份揉进糖团里揉匀，另一份留着做夹心。","取一半糖团擀成1cm厚的片，均匀撒上白糖加芝麻粉的夹心，再盖上另一半糖团擀平，用擀面杖轻轻压实让夹心分层均匀。","把整块折叠成长方，擀成厚约1.5cm的大块，用刀切成2cm见方的小块，切口要利落不粘连。","表面薄刷一层清油防干，撒上剩下的芝麻和干桂花。","阴凉处保存，或冷藏2小时回软后再吃，此时咬开层次分明、落口即酥。"],"key": "\"波波\"是揉糖起酥的功夫，全靠手工反复揉打折叠让糖浆充气；机器压出来的只有硬没有酥。糖浆熬过头会发苦，焦了就救不回来。","tip": "揉糖时手上抹一点油防粘；糖太硬不好揉时可用喷壶在糖团上喷一点点水回软；夏天做要快，糖团容易因手温变软塌。"},"刺梨汁": {"time": "约40分钟","level": "简单","servings": "4-5人份（约2L）","ing": [{"n": "鲜刺梨果","q": "500g","a": "用刺梨干则减到80g泡发后用，浓度更集中；加到800g酸味更足"},{"n": "蜂蜜","q": "80g","a": "加到150g甜度更适合直接喝；减到30g则酸涩感明显"},{"n": "冰糖","q": "40g","a": "加到80g甜而不腻；减掉不放只剩蜂蜜的浊甜、回味发苦"},{"n": "凉白开","q": "800ml","a": "加到1200ml更适合大瓶饮用；减到400ml则浓稠像果酱、难入口"},{"n": "柠檬汁","q": "10ml","a": "加到20ml提亮酸味、颜色更好看；不放则酸度只靠刺梨本身"},{"n": "淡盐水","q": "一盆（约2L）","a": "用来浸泡去农残，用量以能浸过果实为准；不加泡直接洗也可行但干净度略差"}],"steps": ["鲜刺梨去蒂洗净，用淡盐水浸泡10分钟，再用流水冲净；刺梨干提前用温水泡2小时至完全变软。","果肉连籽一起放进破壁机，加300ml凉白开打成细浆——刺梨籽含大量维生素C，不要过滤掉。","用纱布只滤掉粗渣，保留细纤维，浆液倒入剩余的凉白开搅匀。","加入蜂蜜和冰糖，用小火加热到40℃左右并不断搅动，糖化后立刻离火——绝对不要煮沸，高温会让维C大量流失。","放凉后加柠檬汁调酸，装瓶冷藏。","饮用前加冰块兑成冷饮，也可以打成果昔。"],"key": "刺梨的维生素C极不耐高温，全程温度不超过60℃；必须用真刺梨（鲜果或干果），不能用\"刺梨饮料\"代替。","tip": "野刺梨扎手，戴手套处理；不喜欢籽渣可��纱布多滤一遍但会损失部分VC；剩下的果渣别扔，可以做刺梨果酱。"},"苗家腌鱼": {"time": "约8天（腌制7-10天）","level": "稍难","servings": "4-5人份","ing": [{"n": "鲤鱼或鲢鱼","q": "1条约1.2kg","a": "用草鱼刺多易扎嘴；加到1.5kg需按比例增加盐量并延长腌2天"},{"n": "糯米饭（黏糯米蒸熟）","q": "400g","a": "加到600g米香更浓；减到200g则发酵味突出、米香不足"},{"n": "自制糟辣椒或糊辣椒","q": "150g","a": "加到250g辣度更足；减到80g酸香足但辣味弱"},{"n": "盐","q": "60g","a": "每斤鱼约25g，加到80g腌得更透、存更久；减到40g则入味慢、容易发酸臭"},{"n": "花椒","q": "10g","a": "加到20g麻香明显；减到5g几乎尝不出"},{"n": "姜蒜末","q": "40g","a": "加到60g去腥；减到20g腥味压不住"},{"n": "白酒","q": "30ml","a": "加到50ml抑菌保鲜；减到10ml易长白霉"},{"n": "菜籽油","q": "40ml","a": "加到70ml封住表面、防氧化；减到20ml表面易干发霉"},{"n": "葱段","q": "30g","a": "加到50g增香；不放也不影响"},{"n": "蒸鱼豉油或蒜水（蘸料）","q": "30ml","a": "加到50ml蘸碟更香；减到10ml太清淡"}],"steps": ["鱼从背部剖开但不切断，摊成一片，去内脏洗净，用盐抹遍鱼身内外，腌2小时，沥去血水。","糯米提前泡4小时蒸熟至黏而不散，趁热拌入盐、花椒、糟辣椒、姜蒜末和白酒，搅匀成料。","把料均匀抹在鱼身两面和腹腔，剩余的料装进坛子备用。","用干净塑料袋或纱布把鱼身包紧，压上石块或重物，放阴凉通风处腌7-10天（天热5天即可），中途翻一次面。","腌好后取出洗净表面，挂在竹竿上晾半天，表面风干、内部发酵，此时香味最足。","吃法一：柴火慢烤或烤箱200℃烤20分钟，外皮焦香内里嫩滑；吃法二：上锅大火蒸15分钟，配蒜水生抽蘸碟。"],"key": "糯米饭必须趁热拌料才粘得住，盐要一次给足（每斤鱼约25g），后期发酵才能入味透、还不腐坏。","tip": "家里温度高（夏天）缩短到5天，并每天检查一次；表面发白长黏是正常发酵，若有黑绿毛或臭味则整条丢弃不要吃；没有糯米粉可用糯米面替代。"},"荔波酸肉": {"time": "约1个月（发酵1-3个月）","level": "稍难","servings": "4-5人份","ing": [{"n": "带皮五花肉或瘦肉","q": "1000g","a": "用带皮的做出来油亮好吃；用纯瘦肉则口感发柴不挂糊，减到700g发酵更快但量少"},{"n": "糯米粉","q": "150g","a": "加到220g挂糊更厚、发酵口感更糯；减到80g挂不住料、味道散"},{"n": "自制辣椒面或糟辣椒","q": "150g","a": "加到250g辣度足；减到80g酸香有余而辣味不足"},{"n": "盐","q": "60g","a": "每斤肉30g，加到80g更咸更耐存；减到40g发酵慢且易坏"},{"n": "花椒","q": "15g","a": "加到25g麻香突出；减到8g香气弱"},{"n": "姜末、蒜末","q": "30g、30g","a": "蒜加到50g发酵后更香；姜减半去腥力弱"},{"n": "白酒","q": "50ml","a": "加到80ml抑菌保鲜；减到20ml杂菌易繁殖"},{"n": "老坛（带水封口）","q": "1个","a": "容量需比肉量大一倍，装得太满无法压实；没有可用带密封盖的塑料桶，但发酵时间要加倍"},{"n": "菜籽油","q": "50ml","a": "加到80ml封坛面更保险；减到20ml表面易长霉"},{"n": "清水或淘米水","q": "2000ml","a": "泡肉用的水量以没过肉为准；用淘米水发酵更稳、不易腐坏"}],"steps": ["肉切5cm见方的块，用淘米水或清水浸泡2小时去血水腥味，捞出冲净沥干——泡过水的肉发酵稳定、不易腐坏。","盐、花椒、姜末、蒜末、白酒、辣椒面混合成腌料，与肉块拌匀，让每块肉都裹上料。","糯米粉用少量温水调成能挂住的糊状，与腌料、肉再次拌匀，表面裹一层薄糯米粉糊——这是酸肉吃起来油亮挂汁的关键。","肉装入洗净的坛子，边装边压实，装满后用手压紧排出空气，坛口撒一层白酒封住。","坛口用保鲜膜加水封口，置阴凉处发酵：第一个月是\"嫩酸\"，酸香带鲜；第二三个月转\"老酸\"，酸香浓厚。表面发白起黏属正常发酵现象。","取出后上锅蒸20分钟（老酸肉蒸后油亮透香），或与糟辣椒同炒3分钟最下饭。"],"key": "装坛必须压实无空气、表面封一层油隔绝氧气，发酵才不会变臭长毛；没有老坛用密封桶可以，但发酵时间要加倍。","tip": "判断发酵好没好：坛口有气泡溢出、酸香扑鼻、表面结一层白膜即到位；发酵30天的嫩酸最宜人，酸味柔和；怕酸的人先取少量试味再决定；煮好的酸肉冷冻可存一个月。"},"榕江卷粉": {"time": "约1.5小时（含米浆发酵）","level": "中等","servings": "3-4人份","ing": [{"n": "优质大米","q": "500g","a": "用早稻米口感更软滑；换成糯米则太黏不成型，加到600g浆更厚"},{"n": "清水（打浆用）","q": "600ml","a": "加到750ml浆更稀、摊皮更薄；减到450ml浆稠、摊不开且易破"},{"n": "猪骨汤或红酸汤","q": "600ml","a": "换成600ml清水则味道寡淡；用红酸汤则带酸更开胃"},{"n": "花生碎","q": "50g","a": "加到80g香口更足；减到20g则缺了酥香"},{"n": "瘦肉末","q": "100g","a": "加到150g更香；减到50g基本没有肉香"},{"n": "折耳根末","q": "30g","a": "加到50g草香足；减到10g味道偏淡"},{"n": "葱花","q": "20g","a": "加到30g更香；不放味道发闷"},{"n": "辣椒油","q": "40ml","a": "加到60ml红油更亮；减到20ml挂不住粉"},{"n": "蒜末","q": "20g","a": "加到30g蒜香更冲；减到10g香气不足"},{"n": "白醋","q": "15ml","a": "加到25ml开胃；减到5ml则只有辣、吃不下"}],"steps": ["大米淘洗后浸泡6小时，加水打成细米浆，静置发酵2小时，让米浆带轻微酸味，这样摊出的粉皮更滑。","热锅刷一层薄油，把米浆摊成薄如纸的米皮，趁热用筷子卷成直径约3cm的筒，摆盘晾凉；也可卷好后再上锅蒸2分钟定型。","锅中猪骨汤加盐、味精烧开，浇在卷粉上，汤要没过一半卷粉。","另起锅放油，下蒜末、肉末炒香，加折耳根末炒1分钟，盛出铺在卷粉上。","撒花生碎、葱花，淋上辣椒油和白醋。","吃前用筷子从中间夹断，让汤汁渗进卷粉内部，这样每一口都有味。"],"key": "米皮必须摊得极薄并趁热卷，凉了就硬、卷不动；正宗榕江卷粉讲究\"薄得透光、一抿就化\"，米浆太稠就摊不出这种口感。","tip": "没有摊皮机可用两块玻璃片夹着摊（热锅上倒一勺米浆盖上玻璃片来回晃），效果接近；一次可多卷些冷藏，食用前蒸2分钟回软。"},"五色糯米饭": {"time": "约2小时","level": "中等","servings": "4-5人份","ing": [{"n": "糯米","q": "500g","a": "用本地籼糯米口感更松；加到600g份量更足；减到400g则一人一小碗"},{"n": "紫糯米","q": "100g","a": "加到150g紫色更浓；减到50g则颜色偏灰不好看"},{"n": "枫香叶（黑叶子）","q": "30g","a": "加到50g黑色更纯正；减到15g则染出的米偏黄绿"},{"n": "红藜草或红曲","q": "30g","a": "加到50g红色更鲜艳；减到15g则发暗"},{"n": "栀子黄或黄姜","q": "20g","a": "加到35g黄色更亮；减到10g颜色发白"},{"n": "南瓜","q": "100g","a": "加到200g染出的金黄更明显；减到50g黄色不够明显"},{"n": "腊肉","q": "200g","a": "加到300g咸香更足；减到100g则糯米饭本身偏淡"},{"n": "豆腐干","q": "150g","a": "加到200g口感更丰富；减到80g少了咸香层次"},{"n": "豌豆","q": "100g","a": "加到150g更饱满；减到50g则颜色单调"},{"n": "白糖","q": "20g","a": "加到40g甜咸交融；减掉不放则只有咸、甜味不足"}],"steps": ["糯米淘净后浸泡4小时，沥干；紫糯米单独浸泡至发胀。","染液：枫香叶加足量水反复煮到浓黑，取汁泡白糯米2小时成黑色；红藜草煮水成红汁；栀子或黄姜煮水成黄汁；南瓜蒸熟压泥拌入糯米成金黄。","泡好的米分别沥干，各拌少许油和盐防止蒸后结块，分层装入蒸屉。","水开后大火蒸40分钟，至米粒透亮、筷子插入不夹生饭。","腊肉切块煮熟后切片，豆腐干切条，豌豆另煮熟。","把五色糯米分层装碗，每层颜色分明，铺上腊肉、豆腐干、豌豆，撒白糖，趁热拌匀食用。"],"key": "植物染色成败在两件事：染液要反复煮到浓、并保证浸泡时染液是热的，冷了不上色；浸泡不足则颜色发白不匀。","tip": "染好的米要沥干再蒸，太多水会沤成糊状；也可用紫甘蓝替代紫米、洛神花替代红藜草，颜色同样鲜艳；没枫香叶可用靛蓝替代。"},"打油茶": {"time": "约40分钟","level": "简单","servings": "3-4人份","ing": [{"n": "侗家油茶（粗茶、苦丁茶或清明茶）","q": "30g","a": "加到50g茶味更浓；减到15g则味道太淡、失去\"打\"的意义"},{"n": "阴米（糯米）","q": "200g","a": "加到300g米香更足；减到100g茶汤寡淡"},{"n": "猪油或茶油","q": "60g","a": "这是\"油茶\"的关键，加到90g茶汤更滑润；减到20ml只剩清茶"},{"n": "盐","q": "8g","a": "加到12g咸度才够；减到3g则完全寡淡"},{"n": "蒜片","q": "20g","a": "加到35g蒜香更足；减到10g则香型单薄"},{"n": "阴米花或米花、糍粑","q": "米花100g、糍粑100g","a": "米花加到150g口感更丰富，减到50g则茶汤里没东西可泡；糍粑加到150g泡软后更糯，减到50g则不够饱"},{"n": "花生","q": "30g","a": "加到50g香口更好；减到15g则少一味"},{"n": "白芝麻","q": "10g","a": "加到20g香气更浓；不放也能吃"},{"n": "生姜","q": "15g","a": "加到25g驱寒暖胃；减到5g姜味不足"},{"n": "清水","q": "1000ml","a": "加到1500ml茶汤更解渴；减到700ml则茶味太浓发苦"}],"steps": ["阴米下干锅小火慢炒，不停翻动，炒到米粒鼓起、呈金黄色并散发米香，晾凉备用（米花、糍粑也用同样方法炒香）。","锅中放猪油或茶油烧至四成热，下茶叶小火慢炒2-3分钟，边炒边用手揉搓茶叶，让香气充分释放，炒到茶叶颜色变深、香气浓而不焦。","加蒜片、姜片炒香，倒入清水大火烧开，转小火煮5分钟成茶底，用滤网滤出茶叶。","茶底加盐搅匀，舀入碗中，冲入滚烫的炒米（阴米或米花），边冲边搅，泡出米香。","配米花、糍粑、炸花生、芝麻一起吃，糍粑在油茶里泡软后带着茶香最好吃。","打油茶讲究\"一碗油茶几道菜\"，可边吃边续水续茶，续几次味道会越冲越香。"],"key": "\"油茶\"的油是用茶油或猪油把茶叶炒出来的，不是汤上浮一层油；炒茶和炒米都必须小火慢工，火大就焦苦。","tip": "第一次喝会觉得像咸茶汤，多喝两碗就上瘾；可用炒米花、糍粑、油炸豆腐、煮花生当\"配茶菜\"；剩下的茶底可反复续水喝。"},"遵义鸡蛋糕": {"time": "约1小时","level": "中等","servings": "4-5人份（约8块）","ing": [{"n": "鸡蛋","q": "5个（约250g）","a": "加到6个组织更细腻；减到4个则口感偏粗、蛋糕体不够轻盈"},{"n": "白糖","q": "120g","a": "加到150g更甜香；减到80g则甜度不够、老味不足"},{"n": "低筋面粉","q": "200g","a": "用中筋粉则口感偏韧；减到150g蛋糕更蓬松但更容易塌"},{"n": "玉米油","q": "60ml","a": "加到80ml更润不干；减到40ml则偏干、容易裂"},{"n": "温水","q": "40ml","a": "加到60ml面糊更稀；减到20ml则拌不开、可能有干粉"},{"n": "泡打粉","q": "4g","a": "加到6g膨松度更好；减到2g则发不起来、蛋糕发实"},{"n": "蜂蜜","q": "20g","a": "加到40g香甜更明显；减掉不放表面干涩"},{"n": "柠檬皮屑","q": "少许（约1g）","a": "加到3g香气更清爽；不放会有轻微蛋腥味"}],"steps": ["蛋清蛋黄分离，蛋黄加入白糖搅打至颜色发白、质地浓稠发亮，加入柠檬皮屑拌匀。","蛋清加一小勺糖先打到粗泡，再分三次加糖打发，提起打蛋头能拉出小弯钩即干性发泡——打发不足蛋糕就发不起来。","蛋黄糊中筛入低筋面粉和泡打粉，用刮刀翻拌到无干粉，再分三次把蛋白霜翻拌进去，手法要轻、要快，避免消泡。","拌好的糊倒入垫了油纸的方形模具，抹平表面，轻轻震两下排出大气泡。","蒸锅水开后上锅，中火蒸25-30分钟，用牙签插入中心不带湿面糊即熟。","出锅晾到微温，表面抹一层蜂蜜，切成菱形或方形小块。"],"key": "蛋白必须打到硬性发泡才撑得起松软口感；蒸的时候锅盖包一层布，防止蒸汽水滴落在糕面上造成回缩发硬。","tip": "蒸好后趁热吃最松软，冷藏一夜后风味更足、也更适合当伴手礼带走；家里没有蒸锅可用烤箱170℃烤25分钟。"},"黄粑": {"time": "约2小时","level": "中等","servings": "4-5人份（约10个）","ing": [{"n": "糯米","q": "500g","a": "加到600g份量更多；减到400g则黏性下降、压不实"},{"n": "粽叶（箬叶）","q": "20片","a": "加到30片可多包几个；减到10片不够用，普通芭蕉叶替代也行但要烫软"},{"n": "猪五花肉（咸馅）","q": "200g","a": "加到300g肉馅更足；减到100g则咸味不足"},{"n": "豆豉","q": "20g","a": "加到35g豉香更浓；减到10g香味出不来"},{"n": "姜末","q": "15g","a": "加到25g去腥；减到5g肉腥味重"},{"n": "白糖（做甜馅）","q": "50g","a": "加到80g甜味更足；减到30g甜馅发苦"},{"n": "猪油","q": "30g","a": "加到50g米团更黏糯油润；减到10g则口感发干发散"},{"n": "盐","q": "10g","a": "加到15g咸度合适；减到5g则淡而无味"},{"n": "熟白芝麻（甜馅用）","q": "20g","a": "加到40g更香；不放也可用"},{"n": "棉线或棕绳","q": "1捆","a": "没有线可用竹签固定，但蒸后容易散开"}],"steps": ["糯米淘净浸泡8小时，沥干后大火蒸30分钟，必须完全蒸熟透，黄粑吃的就是熟糯米的黏劲。","趁热把熟糯米舂打（传统用石碓捣，或用擀面杖配合石臼压捣）到黏糊拉丝，可加30g猪油和10g盐一同舂，更香糯。","咸馅：五花肉切末，锅内小火煸出油，加豆豉、姜末炒香到肉末干香发亮；甜馅则是白糖加炒香白芝麻拌匀。","粽叶洗净后用开水烫30秒，叶子变软发绿即可，捞出擦干——叶子发脆包时会裂。","取一块糯米团压扁成圆片，放馅料，再覆一层糯米团收口压平成厚约1.5cm的饼，包上粽叶，用棉线扎紧。","蒸锅水开后上屉，中火蒸20分钟，晾凉后切片；再干锅小火煎至两面金黄更好吃。"],"key": "糯米一定要舂捣到黏、拉丝，这是黄粑\"软而不散\"的关键；粽叶必须开水烫软，否则包的时候容易裂开露馅。","tip": "黄粑做好后冷冻可存一个月，蒸透回软即可；黔北黄粑多为甜馅、黔东北多咸馅；没有石臼可用擀面杖在盆里压捣，累但效果接近。"},"遵义甜酒酿": {"time": "约2天（发酵36-48小时）","level": "简单","servings": "3-4人份","ing": [{"n": "糯米","q": "500g","a": "加到700g出酒更多；减到350g则发酵量少、味道不足"},{"n": "甜酒曲","q": "1小包（10g）","a": "加到15g发酵更快更甜；减到5g则发得慢、甜度低"},{"n": "凉白开","q": "300ml","a": "加到400ml更湿润、发酵更快；减到200ml则米饭太干、可能发不起来"},{"n": "鸡蛋","q": "2个","a": "加到4个蛋香更浓；减到1个则蛋白的鲜味不足"},{"n": "姜","q": "30g","a": "加到50g姜味更足更暖；减到15g驱寒力弱"},{"n": "红糖","q": "60g","a": "加到100g甜度更足；减到30g则酒酿的微酸顶得慌"},{"n": "冰糖","q": "20g","a": "加到40g甜味更圆润；减掉不放只有红糖的浊甜"},{"n": "枸杞","q": "5g","a": "加到10g色泽更好；不放也不影响"},{"n": "干桂花","q": "少许（约3g）","a": "加到8g香气更明显；不放则只有米酒香"}],"steps": ["糯米淘净浸泡8小时，沥干后大火蒸30分钟，摊开晾到温热不烫手（约35℃）。","把甜酒曲先用30ml凉白开化开，再倒进米里拌匀，装入干净容器，中间戳一个到容器底部的洞，便于散热和排气。","盖上盖子，外面包一层棉被，放在30℃左右的地方发酵36-48小时；期间每天搅动一次、观察气泡。","闻到明显酒香、米粒发软、米液渗出就是发酵好了，此时酒酿可以直接吃。","做鸡蛋甜酒：锅中加姜片、红糖和600ml清水煮开成姜糖水。","鸡蛋打散，沿锅边慢慢淋入，边淋边搅成细蛋花，加枸杞、干桂花和甜酒酿煮2分钟关火，最后加冰糖调甜。"],"key": "发酵温度是关键，超过40℃酒曲会失活、米饭发酸坏掉；容器和勺子必须无油无生水，沾生水会整坛发酸长毛。","tip": "夏天室温就够，天冷时可用电热毯或暖气片烘着；一次多做几罐分开放，一罐发酸了还有一罐能吃；喜欢酒味重就多发酵一天。"},"酸汤砂锅粉": {"time": "约30分钟","level": "简单","servings": "2-3人份","ing": [{"n": "贵州细粉或米粉","q": "300g","a": "换成宽粉更挂汁；减到200g一人一小碗"},{"n": "红酸汤（发酵番茄辣椒）","q": "200ml","a": "加到350ml酸味更足；减到100ml则汤味不够酸、失去特色"},{"n": "牛骨高汤","q": "700ml","a": "加到1000ml汤更多更浓；减到400ml汤少粉干、味道发死"},{"n": "糊辣椒","q": "60g（3勺）","a": "加到90g辣香更冲；减到30g只有辣没有糊香"},{"n": "豆腐乳","q": "30g（2块）","a": "加到45g发酵咸鲜更浓；减到15g味道不够厚"},{"n": "姜蒜末","q": "30g","a": "加到45g香气足；减到15g蒜香不足"},{"n": "豆豉","q": "15g","a": "加到25g豉香足；减到5g则酸汤偏素"},{"n": "菜籽油","q": "40ml","a": "加到60ml红油更亮；减到20ml糊辣椒易焦苦"},{"n": "牛肉丸或猪肉片","q": "150g","a": "加到250g更扎实；减到80g则像一碗素粉"},{"n": "折耳根、葱花","q": "各50g","a": "折耳根加到80g草香足；减到20g味道不正"}],"steps": ["砂锅烧干，中火倒入菜籽油烧至五成热，下姜蒜末、豆豉小火炒香到出红油。","加豆腐乳压碎、糊辣椒入锅中火翻炒1分钟，辣香冲鼻时立刻倒入红酸汤，煮沸后酸味被激发出来。","倒入高汤大火烧开，转中火煮5分钟，酸汤与高汤融合、汤色红亮。","加盐调味——酸汤本身带咸，一定要先尝再补，别一次加多。","下牛肉丸煮3分钟至浮起，再下煮好的粉条（干粉需提前泡软）小火煮3分钟，让粉吸味、滑而不烂。","关火撒折耳根和葱花，连锅端上桌，另配一小碟干辣椒面和糊辣椒。"],"key": "酸汤必须\"炒香后加\"——先下酸汤再炒糊辣椒会损失香气；酸汤煮沸5分钟就够，超过10分钟酸味发闷失去鲜劲。","tip": "没有红酸汤可用自制番茄辣椒酱加醋替代，但酸味层次差一截；贵州人吃砂锅粉一定要撒折耳根，这一步不能省。"},"剪粉": {"time": "约20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "米皮","q": "300g","a": "换成粉条则是另一种口感；减到200g份量刚好一人份"},{"n": "辣椒油","q": "50ml","a": "加到80ml红油更足；减到20ml颜色淡、挂不住粉"},{"n": "油辣椒（煳辣椒+油）","q": "40g（2勺）","a": "加到60g糊香更突出；减到20g只有辣没有糊香，偏燥"},{"n": "生抽","q": "25ml","a": "加到40ml咸度足；减到10ml味道淡"},{"n": "陈醋","q": "20ml","a": "加到30ml开胃解腻；减到5ml则只剩辣"},{"n": "芝麻酱","q": "30g","a": "加到50g更香浓顺滑；减到10g则少了一味关键"},{"n": "花生碎","q": "40g","a": "加到60g更酥香；减到15g口感发单"},{"n": "折耳根末","q": "30g","a": "加到50g草香足；减到10g味道偏淡"},{"n": "葱花","q": "20g","a": "加到30g更香；不放味道发闷"},{"n": "盐、白糖","q": "3g、3g","a": "糖加到6g中和酸辣；减掉不放则又酸又辣、口腔发涩"}],"steps": ["米皮切成宽约1cm、长约6cm的条，或直接用剪刀在米皮上剪成条，边缘要利落不断。","剪好的粉在蒸屉上大火蒸3-5分钟至回软，摊凉后拌少许香油防粘。","碗底先放芝麻酱（用凉白开一点点澥开成稀糊）、生抽、陈醋、盐和糖，搅匀成底料。","剪粉入碗，淋上辣椒油和油辣椒，趁粉还热拌匀，让每根粉条都挂上红油。","撒花生碎、折耳根末、葱花，从碗底往上翻拌均匀。","遵义吃法可再加一勺油辣椒和几粒油炸哨子（油炸肥肉丁）——哨子香是本地吃法的一大特色。"],"key": "芝麻酱必须用凉白开一点点澥开，直接倒会结成疙瘩；红油要在粉还热时淋，凉了挂不住味道。","tip": "油炸哨子自己做：肥瘦丁下锅煸出油、炸至金黄酥脆，晾凉备用；拌好后如果太干可加两勺原汤或凉白开调开。"},"贵州烤鱼": {"time": "约1小时","level": "中等","servings": "3-4人份","ing": [{"n": "草鱼或黔江鱼","q": "1条约1.2kg","a": "用鲶鱼或江团肉更细；加到1.5kg需延长烤8分钟"},{"n": "糊辣椒","q": "80g（4勺）","a": "加到120g辣香更足；减到40g只剩辣味没有糊香，偏燥"},{"n": "姜末、蒜末","q": "25g、25g","a": "蒜加到40g更香；姜减半则腥味压不住"},{"n": "干辣椒段","q": "15g","a": "加到25g辣度更足；减到8g则辣味弱"},{"n": "花椒","q": "10g","a": "加到15g麻香突出；减到5g几乎无感"},{"n": "菜籽油","q": "60ml","a": "加到100ml炒辣料汁更润；减到30ml容易焦糊"},{"n": "葱段","q": "50g","a": "加到80g葱香足；减到20g香气弱"},{"n": "料酒","q": "40ml","a": "加到60ml去腥更彻底；减到20ml鱼腥味出不来"},{"n": "生抽","q": "30ml","a": "加到50ml咸度足；减到15ml味道寡淡"},{"n": "盐、白糖","q": "10g、5g","a": "糖加到10g可平衡辣味；减掉不放只有辣"}],"steps": ["鱼处理干净，从背部剖开摊平但腹部保留连接，摊成蝴蝶形；鱼身两侧划斜刀，用盐、料酒、姜片、葱段抹匀，腌30分钟。","腌好后把鱼身内外彻底擦干水，刷一层菜籽油，防止烤的时候粘网、粘皮。","炭火或烤架预热到明火微红，鱼放上后先大火烤5分钟定型，再转中火慢烤15分钟，中途翻面两次。","判断熟度看鱼眼是否凸出变白、鳃盖翻开、刀口处渗出白色鱼油，不要只看时间。","另起锅放菜籽油烧五成热，下姜蒜末、干辣椒段、花椒小火炒香，加糊辣椒炒1分钟至红油析出、糊香冲鼻，关火加生抽、白糖调成辣料汁。","鱼移到长盘中，淋上刚炒好的辣料汁，撒青葱段和剩余的糊辣椒，趁热上桌。"],"key": "糊辣椒只能在最后下锅短炒1分钟以内，久炒必苦；烤鱼的熟度看鱼眼凸出、鳃盖翻开，而不是掐时间。","tip": "没有炭火用烤箱220℃烤20分钟、中途刷两次油；配一碟蒜泥加醋或折耳根蘸水解腻；鱼背上再铺一层鲜姜片、洋葱，烤出来更香。"},"红酸汤锅底": {"time": "约4.5小时（发酵20-45天+熬汤4小时）","level": "稍难","servings": "4-5人份","ing": [{"n": "番茄","q": "1000g","a": "用沙瓤番茄酸度更好；加到1300g酸味更足；减到700g需补醋"},{"n": "皱皮辣椒或小米辣","q": "300g","a": "加到400g辣度更足；减到150g则酸而不辣、失去红酸汤特色"},{"n": "蒜","q": "150g","a": "加到200g发酵后蒜香更浓；减到80g香气不足"},{"n": "姜","q": "100g","a": "加到150g去生味；减到50g则发酵味发冲"},{"n": "盐","q": "80g","a": "每斤番茄约40g，加到110g更保险、不易坏；减到50g发酵会失控长白霉"},{"n": "白酒","q": "50ml","a": "加到80ml抑菌更好；减到20ml杂菌易繁殖"},{"n": "冰糖","q": "30g","a": "加到50g发酵更稳、圆润；减掉不放酸味太冲"},{"n": "牛骨或鸡架","q": "1500g","a": "加到2000g汤更浓白；减到1000g需兑水味道偏淡"},{"n": "干辣椒、白蔻、香叶","q": "10g、5g、3片","a": "加到20g香料味更厚；减到5g汤底发素"},{"n": "葱段、姜片（熬汤用）","q": "各50g","a": "葱加到80g汤更清甜；减半去腥力弱"}],"steps": ["做红酸汤：番茄划十字，开水烫30秒去皮，切小块；辣椒切碎，姜蒜剁成末，全部混合，加盐、白酒、冰糖拌匀。","装入坛中压实，坛口加水封口，置阴凉通风处发酵：室温25℃以上需20-30天，冬天要45天以上。发酵到坛内冒泡、酸香扑鼻即为成汤——\"三月酸\"之名就指三月做的酸最酸。","牛骨焯水后洗净，另起锅加清水，放葱段、姜片、干辣椒、白蔻、香叶，小火熬4小时成奶白高汤，滤渣。","锅底：锅中放油烧五成热，下姜蒜末、干辣椒爆香，倒入高汤煮开。","加入发酵好的红酸汤200ml，中火煮5分钟，让酸香与高汤融合、汤色红亮。","加盐调味（酸汤自带咸度，务必先尝再补），撒葱花蒜末起锅即为红酸汤锅底，涮毛肚、鸭血、豆皮、鲜蔬。"],"key": "番茄一定要开水烫皮去皮，带皮发酵容易长白霉；盐和白酒既是防腐也是发酵菌的养分，量绝对不能减。","tip": "没时间自己发酵可以买现成红酸汤（遵义、凯里一带多有卖），但味道层次不如自制；发酵坛用坛口加水的封法最保险。"},"遵义虾子羊肉粉": {"time": "约4.5小时（熬汤4小时）","level": "中等","servings": "3-4人份","ing": [{"n": "带皮羊肉","q": "1000g","a": "用带皮的汤更浓、膻味轻；去皮羊肉更清爽但香味少；减到700g汤味不足"},{"n": "羊骨","q": "1000g","a": "加到1500g汤更奶白；减到600g汤薄发清"},{"n": "老姜","q": "60g","a": "加到100g去膻最彻底；减到30g膻味压不住"},{"n": "葱段","q": "50g","a": "加到80g汤更清甜；减半香味弱"},{"n": "花椒","q": "10g","a": "加到20g麻香压膻；减到5g效果差"},{"n": "干辣椒","q": "15g","a": "加到25g辣香更足；减到8g辣味弱"},{"n": "遵义细粉","q": "300g","a": "换成剪粉也常见；加到400g够5人；减到200g一人一小碗"},{"n": "辣椒油","q": "60ml","a": "加到90ml红油更亮更香；减到30ml挂不住粉"},{"n": "香菜、蒜苗","q": "各50g","a": "香菜加到80g提味更明显；减到20g则偏腥"},{"n": "盐、白胡椒粉","q": "20g、3g","a": "盐加到30g配羊肉刚好；减到10g则汤淡"}],"steps": ["羊肉切块冷水下锅焯出血沫，捞出后用温水冲洗干净——绝不能用冷水冲，肉会紧缩变柴。","羊骨另焯水去血沫，与羊肉、老姜、葱段、花椒一起下锅，加足量清水大火烧开，转小火保持微沸（似开非开）熬4小时。","熬汤过程中只加热水、不加冷水，也撇净浮沫，汤色才会白而不浑浊发腻。","撇去汤面浮油，羊肉捞出晾凉切成薄片；原汤用纱布过滤两遍，成清亮乳白的高汤。","粉条用温水泡软后下入高汤锅中，小火煮4分钟至粉条透亮断生，捞入碗中。","碗中放盐和白胡椒粉，冲入高汤，铺羊肉片、香菜、蒜苗，淋上辣椒油，趁热拌匀。"],"key": "羊汤去膻的关键是\"焯水后用温水冲洗\"加长时间小火慢熬，全程保持似开非开；大火滚煮会把羊油乳化，汤发白发腻、羊味也散。","tip": "想更简单可用高压锅上汽后压40分钟代替慢熬；遵义人吃羊肉粉常另配一碗原汤单独喝，别把汤全倒进碗里；怕膻可多加白胡椒粉和蒜苗。"},"贵阳肠旺粉": {"time": "约1.5小时","level": "中等","servings": "3-4人份","ing": [{"n": "贵州细粉","q": "300g","a": "换成剪粉是贵阳另一常见吃法；减到200g一人一小碗"},{"n": "猪大肠","q": "300g","a": "加到450g料更足；减到150g则吃不到几段大肠"},{"n": "猪血旺","q": "200g","a": "加到300g血旺更足；减到100g解腻作用弱"},{"n": "肥瘦猪肉丁（脆哨）","q": "150g","a": "加到250g更香；减到80g少了这口酥脆"},{"n": "菜籽油","q": "60ml","a": "加到90ml炒红油更香；减到30ml糍粑辣椒容易焦"},{"n": "糍粑辣椒或油辣椒","q": "60g","a": "加到90g辣味更足；减到30g辣香明显不足"},{"n": "豆豉","q": "15g","a": "加到25g豉香足；减到5g香型不完整"},{"n": "蒜苗","q": "50g","a": "加到80g香气足；减到20g味道偏闷"},{"n": "高汤","q": "600ml","a": "加到900ml汤更多；减到400ml则干、味道集中"},{"n": "盐、味精","q": "8g、2g","a": "盐加到12g配辣油刚好；减到4g则淡"}],"steps": ["大肠用面粉和盐反复揉洗去油污，中途加白醋抓洗去腥，再用清水冲净。","冷水下锅加姜葱料酒焯20分钟，捞出切成3cm长的段。","血旺切成1cm见方的块，入开水锅汆2分钟去腥味，捞出沥干。","肥瘦丁下锅加少量油煸炒出油，摊开晾凉——凉了才会酥脆，这一步叫\"做脆哨\"。","锅中放油烧六成热，下豆豉、姜蒜末炒香，加糍粑辣椒转中火炒1分钟出红油，倒入高汤烧开。","下大肠段煮3分钟，再下血旺块煮1分钟（久煮血旺会起孔散掉）。","下粉条煮3分钟至断生，捞入碗中，浇汤、大肠、血旺，铺脆哨和蒜苗，淋一勺滚油辣椒。"],"key": "血旺只能汆烫和短时间加热，久煮会蜂窝开裂；脆哨必须晾凉才酥，热着铺上去会回软。","tip": "做脆哨时留一点炼出来的油拌在粉里更香；自己炼脆哨要用三分肥七分瘦，纯瘦的丁炸出来发干不脆；不吃大肠可只用血旺加脆哨。"},"盘县火腿": {"time": "约1个月（短期版）+ 6个月以上风干发酵","level": "稍难","servings": "5-6人份","ing": [{"n": "盘县猪后腿（连皮带骨）","q": "1只约3kg","a": "用整腿才腌得透；减到1.5kg需按比例减盐并缩短腌制时间"},{"n": "粗盐","q": "300g","a": "每斤肉50-70g为标准，加到400g更咸更耐存；减到150g则味道寡淡无回味"},{"n": "花椒","q": "20g","a": "加到35g麻香更明显；减到10g几乎尝不出"},{"n": "白酒","q": "100ml","a": "加到150ml防霉防虫；减到50ml表面容易长霉"},{"n": "棕绳","q": "1捆","a": "用棉绳也可以；不用绳扎住肉会松散掉"},{"n": "蒜片","q": "30g","a": "加到50g配火腿更香；减到15g味道偏单"},{"n": "姜末","q": "20g","a": "加到30g去腥；减到10g腥味明显"},{"n": "干辣椒","q": "10g","a": "加到20g辣香更足；减到5g则香型不足"},{"n": "食用油","q": "30ml","a": "加到50ml煸出的油更香；减到15ml容易粘锅"},{"n": "温水","q": "一盆","a": "刷洗表面泥沙用，不可长时间浸泡，盐分会流失"}],"steps": ["修整猪腿，削去多余油脂和边缘破损处，用竹签在皮上扎若干小孔，让盐渗进去。","粗盐与花椒炒香放凉，均匀揉搓在猪腿表面和切口处，堆码进缸里腌制3-5天（每斤肉约50-70g盐），中途翻压两次。","用棕绳扎紧，挂到阴凉通风处晾晒发酵，至少6个月（一年以上风味更醇厚）。","悬挂期间每隔一段时间用白酒擦洗表面防霉防虫，遇雨天要挪到室内；表面长绿毛的整只丢弃不要吃。","成熟火腿用温水刷净表面泥沙，切3mm厚片（蒸食）或切薄片（炒食）。","蒸食：火腿片铺盘，上锅大火蒸20分钟至透亮出油，配蒜片吃。","炒食：热锅下油烧五成热，下干辣椒、姜末、蒜片爆香，加火腿片小火煸炒2分钟至边缘卷曲发亮。"],"key": "腌盐量决定成败：少于每斤40g则味道寡淡没有回味，多于每斤90g则三年都吃不淡；风干期必须防雨防虫，发霉发黑的整只丢弃。","tip": "没条件做整条火腿可以买成品火腿，切片后与新鲜蒜片、辣椒同炒；蒸火腿时垫几片鲜姜和一碗花椒水去咸去腥。"},"威宁荞酥": {"time": "约1小时","level": "中等","servings": "4-5人份（约16块）","ing": [{"n": "苦荞粉","q": "250g","a": "用甜荞粉则没有苦荞的清香；加到300g饼更厚、荞味更足"},{"n": "清水","q": "60ml","a": "苦荞粉吸水少，要分次少量加；加到90ml面团偏软、不好擀"},{"n": "麦芽糖","q": "150g","a": "加到200g甜度与嚼劲更好；减到100g则偏苦、回味差"},{"n": "红糖","q": "100g","a": "加到150g色泽更深；减到50g甜味不足"},{"n": "白糖（夹心）","q": "150g","a": "加到200g夹心甜度更明显；减到80g夹心发苦"},{"n": "白芝麻","q": "60g","a": "加到90g芝麻香更浓；减到30g香气不足"},{"n": "花生碎","q": "60g","a": "加到90g更酥香；减到25g口感偏单"},{"n": "核桃仁碎","q": "40g","a": "加到60g油香更足；减到15g则少了坚果的回味"},{"n": "熟菜籽油","q": "30ml","a": "加到50ml面团更酥、成品不干；减到10ml容易开裂"},{"n": "熟糯米粉（防粘）","q": "20g","a": "加到30g防粘好；减到8g擀面时容易粘案板"}],"steps": ["苦荞粉加50ml清水和10ml熟油先揉，再分次补足剩余的水，揉成硬面团，揉到表面光滑不裂。","面团擀成1cm厚的大片，切成直径约7cm的圆皮，边缘用手捏薄。","白糖加白芝麻、花生碎、核桃碎拌成甜馅，分成小份备用。","取一张圆皮放15-20g馅料，再盖上一张圆皮，像包饺子一样收口捏紧，压扁成厚约1.5cm的圆饼，收口朝下。","平底锅刷薄油，最小火烘烤，每面3-4分钟，烤到两面金黄、饼体鼓起、散出烘焙的苦荞香。","出炉放凉2分钟再吃，此时外皮酥脆，夹心的糖霜在口中化开、落口即酥。"],"key": "夹心是威宁荞酥的招牌：两个荞皮圆片捏合收口后要压扁并烘到鼓起，糖霜才会形成\"落口酥\"的那一层；揉面时水要分次加，一次倒多了面团会黏手发不开。","tip": "用平底锅小火烘最正宗；烤箱170℃烤18分钟也行；夹心可按喜好换成椒盐花生末（咸口）或玫瑰糖（甜口）。"},"织金竹荪炖鸡": {"time": "约2小时（泡发2小时+炖煮90分钟）","level": "中等","servings": "4-5人份","ing": [{"n": "织金白花竹荪（干品）","q": "30g","a": "加到45g菌香更足；减到15g则汤里菌味不足"},{"n": "土鸡","q": "1只约1000g","a": "用乌骨鸡或三黄鸡更嫩；加到1300g需同比例延长炖煮10分钟"},{"n": "老姜","q": "40g","a": "加到60g去腥提味；减到20g鸡腥味压不住"},{"n": "葱段","q": "30g","a": "加到50g汤更清甜；减半香味弱"},{"n": "花椒","q": "10g","a": "加到15g麻香去腥；减到5g效果差"},{"n": "料酒","q": "40ml","a": "加到60ml去腥更彻底；减到20ml腥味残留"},{"n": "枸杞","q": "10g","a": "加到20g色泽更好；减到5g也行"},{"n": "红枣","q": "6颗","a": "加到8颗甜味更足；不放也不影响"},{"n": "盐","q": "10g","a": "加到15g咸度合适；减到5g则汤淡"},{"n": "清水","q": "1500ml","a": "加到2000ml汤更多；减到1000ml味浓但需另加水"}],"steps": ["竹荪干用清水泡发2小时（水必须无油、无漂白剂），泡到完全舒展后剪去底部硬蒂，撕成小段。","竹荪段用清水反复淘洗3遍去掉土腥味，再入开水锅焯30秒，捞出立刻用凉水冲凉，保持脆爽。","土鸡斩成3cm块，冷水下锅加姜片、料酒焯5分钟去血水，捞出用温水冲净。","砂锅加1500ml清水，放入鸡块、老姜、葱段、花椒、料酒，大火烧开转小火炖60分钟。","加竹荪段和红枣，继续小火炖30分钟，汤色转白、竹荪吸足鸡味变得柔软。","出锅前10分钟再加枸杞和盐（盐早放鸡肉会发紧），撒葱花即可。"],"key": "竹荪的土腥味要靠\"泡发+反复淘洗+开水焯+凉水冲\"四步去除，缺一步汤就会发涩；鸡肉先炖够60分钟汤才白，竹荪后放才不会炖烂。","tip": "泡竹荪的水别倒，静置后沉淀一夜可以当\"竹荪水\"用，煮汤时加一碗汤更鲜；土鸡用三黄鸡炖40分钟就够，更快出味。"},"赫章可乐猪蹄": {"time": "约1小时30分钟","level": "简单","servings": "3-4人份","ing": [{"n": "猪蹄","q": "2只约1000g","a": "用前蹄（脚朝上）胶质更多；加到1300g需延长炖煮10分钟"},{"n": "可乐","q": "500ml","a": "加到700ml汤汁更足；减到300ml则甜味太集中、易发苦"},{"n": "清水","q": "300ml","a": "加到500ml炖煮更从容；减到150ml容易糊锅"},{"n": "菜籽油","q": "40ml","a": "加到60ml炒糖色更香；减到20ml炒出的颜色偏淡"},{"n": "姜片、蒜瓣","q": "40g、30g","a": "蒜加到50g更香；姜减半去腥力弱"},{"n": "八角、桂皮、香叶","q": "2个、1段、3片","a": "加到3个八角、2段桂皮香料味更浓；不放则只有甜咸"},{"n": "生抽、料酒","q": "40ml、40ml","a": "生抽加到60ml咸度足；料酒减到20ml焯水去腥不够"},{"n": "老抽","q": "15ml","a": "加到25ml上色更深亮；减到5ml颜色偏浅"},{"n": "冰糖","q": "20g","a": "加到35g颜色更红亮；减到10g色浅味淡"},{"n": "干辣椒","q": "10g","a": "赫章做法带微辣，加到20g辣味更明显；减掉则只有甜咸"}],"steps": ["猪蹄剁成4cm见方的块，冷水下锅加姜片、料酒焯5分钟去血水，捞出用温水洗净并彻底擦干——擦干才能炒出色、不爆油。","锅内放菜籽油和冰糖，最小火慢慢炒糖色，糖液变成琥珀色、冒小泡时立刻倒入猪蹄快速翻炒上色。","加姜片、蒜瓣、八角、桂皮、香叶、干辣椒，小火煸炒2分钟炒出香味。","倒入可乐和清水（没过猪蹄），加生抽、老抽，大火烧开后转小火加盖炖45分钟。","开盖转大火收汁，边收边翻动让糖汁均匀挂在猪蹄上，汤汁收到浓稠发亮即关火。","静置5分钟再装盘，胶质会凝得更紧实，咬下去软糯弹牙。"],"key": "炒糖色必须在猪蹄完全擦干后进行，锅要热、油温低、糖慢慢化开；最后收汁的那几分钟不能离人，糖汁过火会发苦。","tip": "想更入味可先不放可乐，用生抽老抽加料酒把猪蹄煨20分钟再倒可乐；收汁后撒白芝麻或熟花生碎更香；隔夜冷藏风味更足。"},"六枝岩脚面": {"time": "90分钟","level": "中等","servings": "3-4人份","ing": [{"n": "高筋小麦粉","q": "500g","a": "用普通中筋粉替代会断条易烂，减到400g配同量水会偏硬不易煮透，加到600g则面条偏软、挂汤不足"},{"n": "食用碱（土碱水）","q": "30ml（约3g碱）","a": "减到15ml碱味淡、面偏黄而无劲，加到45ml碱味发苦、面条发黄发脆易断"},{"n": "食盐","q": "5g","a": "减到2g则煮后无味，加到10g会咸得盖过肉臊子的香味"},{"n": "清水","q": "170ml（室温28-30℃）","a": "减到140ml和面困难、面筋不充分；加到200ml面团偏软，压延时回缩严重"},{"n": "土鸡蛋","q": "2个","a": "减到1个颜色偏黄不白；加到3个面质更柔但麦香被蛋味盖住，失去岩脚面的本味"},{"n": "猪骨汤","q": "800ml","a": "减到500ml汤味不足、面无味；加到1200ml面会泡涨、汤味变淡"},{"n": "猪肉臊子","q": "150g","a": "减到80g香味单薄；加到250g会抢过面条本身的麦香"},{"n": "酸菜","q": "80g","a": "减到30g酸香不足；加到150g则酸得盖住汤味、面条发软"},{"n": "糊辣椒","q": "20g","a": "加到35g糊香更足、油色更红亮；减到8g只剩干辣没有焦香"},{"n": "葱花、菜籽油","q": "葱花20g、菜籽油30ml","a": "油加到50ml面会泡软挂不住汤；减到10ml则拌开时发干、发涩"}],"steps": ["将高筋小麦粉500g过筛倒在案台上，中间挖一个坑，把食用碱水、盐、2个土鸡蛋磕入坑中，再分3-4次加温水，边加边用筷子搅成雪花絮，最后揉成硬面团。","面团表面抹一层菜籽油防干，盖湿布静置醒发30分钟，让面筋充分吸水、拉伸时不易回缩。","醒好的面团擀成大圆片，用撬杠或擀面杖从中间向四周反复碾压，把面皮从5-6mm逐次压到1mm厚，压到1mm以下会破洞、煮后成糊。","折叠面皮数层，切成宽窄均匀的细条（当地称'韭菜条''蒜叶条'），抖散防止粘连，切口要利落不能有毛边。","宽水锅烧至大滚，水中加入少许盐和几滴菜籽油，下入面条并用长筷迅速拨散，边煮边点两次凉水，约2分半钟至3分钟，面条浮起且中心无白芯即断生。","另起锅把猪肉臊子用中火炒酥炒香至肉粒微微发干，下酸菜碎翻炒1分钟至酸香出来，加盐调味后把臊子连同原汤舀入面汤中。","面条捞入碗中，浇上滚烫的猪骨汤和臊子酸菜，面上撒糊辣椒、葱花，另点一勺炒香的油辣椒即成。"],"key": "和面水温必须控制在28-30℃，碱量宁少勿多；面皮压不到1mm厚就煮不熟、压太薄则下锅即断，这是岩脚面最难的一步。","tip": "现做现吃最好；面条本身带碱的淡黄和麦香，汤只需清汤加臊子，切忌用重油重辣的臊子把麦香盖住。喜欢更酥脆的口感可把面条晾干后先蒸10分钟再煮。"},"兴义杠子面": {"time": "3小时","level": "稍难","servings": "3-4人份","ing": [{"n": "中筋面粉","q": "500g","a": "减到400g配同比例蛋液会偏硬；加到600g面条偏软、滑脆感变差"},{"n": "土鸡蛋","q": "9个（约450g）","a": "减到6个面团黏手、压延开裂；加到11个面条偏软、失去'入口滑脆'的筋性"},{"n": "食用碱","q": "4g","a": "减到2g面条发白无碱香；加到8g则碱味发苦、面条发黄"},{"n": "猪后腿肉","q": "1500g","a": "减到1000g汤的肉香不足；加到2000g汤更浓但熬制时间要多40分钟"},{"n": "白条鸡（母鸡）","q": "1只约2000g","a": "减到1kg鸡肉香不足、汤发薄；加到2500g汤更醇但熬制时间要多40分钟，换成老母鸡则更浓但也需多炖30分钟"},{"n": "猪筒子骨","q": "1000g","a": "减到500g汤色不够乳白鲜亮；加到1500g汤更浓稠、面条挂味更重"},{"n": "姜块、香葱结","q": "姜50g、葱结30g","a": "葱减到10g去腥力弱；姜加到80g会盖掉鸡汤的甜味"},{"n": "脆臊（酥脆肉丁）","q": "150g","a": "减到60g口感单薄；加到250g会抢走鸡肉丝的鲜甜"},{"n": "炸花生仁","q": "60g","a": "减到20g缺少酥脆点缀；加到120g会泡软失去脆感"},{"n": "红油辣椒、酱油、醋、味精、胡椒粉、葱花","q": "红油辣椒40ml、酱油15ml、醋6ml、味精2g、白胡椒粉1g、葱花20g","a": "红油辣椒加到80ml会满碗红油盖住汤色，减到15ml只有浮油没有香；醋加到15ml会盖掉鸡汤鲜味"}],"steps": ["将中筋面粉500g过筛摊在案台上，中间挖坑，打入9个鸡蛋，加食用碱4g，用手把周围面粉慢慢拢入，先搅成絮状再揉成表面光滑、软硬适中的面团。","面团压扁，均匀扑上干豆粉防止粘连，用木质杠子反复坐压——压一次折叠一次再压，如此反复十几次，把面片压到厚度不足0.3mm，掀开时应能透光。","把面片折成垛，用薄面刀切成细如发丝的细丝，抖散成均匀的杠子面备用。","另起大锅，把猪后腿肉1500g、白条鸡1只、猪筒子骨1块、姜块、葱结放入，注入清水没过，大火烧沸撇净浮沫，转小火炖2小时，加盐调味并保持微温备用，这就是原汤。","把捞出的熟猪肉、熟鸡肉晾凉切成细丝；另起锅不放油，下槽头肉丁先煸出油，油出尽后下瘦肉丁煸至焦黄，加甜酒酿25g和食盐继续翻炒，成深褐色的脆臊盛出。","宽水锅水大开，下杠子面并用筷子拨散，煮到断生立刻捞出控水，装入马蹄碗中——面在汤里超过5分钟就会吸汤发软失去滑脆。","舀原汤入碗，放上猪肉丝、鸡肉丝、脆臊、炸花生仁，调入红油辣椒、酱油、醋、味精、白胡椒粉，撒葱花即成。"],"key": "面片必须压到0.3mm以下并切成发丝般细丝，才有'滑脆'口感；煮面只到断生就捞，久煮面条会发黏、失去脆劲。","tip": "和面用的是土鸡蛋且不加水，全靠蛋液和面，这是舒记面坊的老规矩；若鸡蛋不够可补10ml温水，但不宜超过30ml，否则压延时会粘杠子。"},"惠水干拌面": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "本地碱水细面","q": "300g","a": "减到200g则一人一碗不够；加到450g需改用更大的碗，碱水面下锅时间不要超过2分钟，换成干挂面会挂不住酱汁"},{"n": "糊辣椒","q": "30g","a": "减到10g只剩干辣没有糊香；加到50g会苦焦发糊"},{"n": "油辣椒（菜籽油泼）","q": "30ml","a": "加到50ml整碗红亮但发腻，减到10ml挂汁不够、辣椒香出不来"},{"n": "折耳根","q": "60g","a": "减到20g清香不足；加到120g会盖住糊辣椒、拌起来发苦"},{"n": "脆哨（酥肉丁）","q": "80g","a": "减到30g少了酥脆口感，加到150g面会偏咸"},{"n": "酸萝卜丁","q": "40g","a": "减到15g酸头不够，加到80g则只剩酸萝卜味、糊辣椒被压住"},{"n": "生抽","q": "20ml","a": "减到10ml颜色淡、鲜味不足；加到35ml会过咸"},{"n": "香醋","q": "10ml","a": "减到3ml只剩酱味；加到25ml酸味盖住糊辣椒的糊香"},{"n": "蒜末、葱花、花椒油、白糖","q": "蒜末15g、葱花15g、花椒油5ml、白糖3g","a": "白糖减到1g提鲜不明显；花椒油加到15ml会有明显麻感、不适合怕麻的人"},{"n": "熟菜籽油（泼辣用）","q": "40ml","a": "减到20ml则辣椒面发干、拌不匀；加到70ml整碗油亮、面条泡软发腻"}],"steps": ["先做碗底：把糊辣椒、花椒油、蒜末、葱花、白糖、一半生抽和香醋放进碗里，再把烧到七成热的菜籽油直接泼在糊辣椒上——滋啦一声激出焦香，这一步是整碗面的灵魂。","锅里宽水大滚，下碱水细面，用筷子迅速拨散防粘连，煮到浮起后约1分半钟到2分钟即可捞出，捞后马上沥干。","另起小锅烧水，把脆哨、豆芽焯30秒捞出，与折耳根段、酸萝卜丁一起码在面碗一角。","面条抖散装碗，趁热把剩下的生抽和剩余的酸萝卜卤汁浇在面上，用筷子从底部快速挑拌30秒，让每根面均匀挂上红油。","拌好后把糊辣椒油汁再淋一遍在面上，铺上脆哨、酸萝卜、折耳根，淋一勺烧热的菜籽油激香，趁热吃。"],"key": "糊辣椒必须是用干辣椒在干锅中小火焙至焦香后再舂碎的粗粒粉，现做现吃最香；用机器打细的辣椒面只有辣味没有糊香，这是外地人复刻不出来的分水岭。","tip": "不放折耳根就少了三成贵州味，给外地人吃可以把折耳根减半另加黄瓜丝；嗜辣的可再加1勺油辣椒，怕苦的就把油泼的温度从七成降到六成。"},"独山盐酸菜": {"time": "45分钟（另需发酵60天）","level": "稍难","servings": "5-6人份","ing": [{"n": "本地青菜（芥菜）","q": "3kg","a": "单株重量低于2kg的菜腌后口感发软，减到2kg不够一坛；加到4kg需按比例增加盐和甜酒"},{"n": "食盐（腌渍用）","q": "300g","a": "减到200g成品盐分不足、酸度不稳易变软；加到400g则口感发苦、发酵过头"},{"n": "糯米甜酒（醪糟）","q": "250ml","a": "减到100ml酸中缺甜、层次单薄；加到400ml甜味盖过酸、失去'坛酸'特征"},{"n": "独山皱皮辣椒粉","q": "120g","a": "减到50g只有咸酸没有辣；加到200g辣味压过甜、抢掉主味"},{"n": "大蒜（蒜头、蒜苗）","q": "150g","a": "减到60g香气不足；加到250g蒜味太冲会盖住发酵香"},{"n": "冰糖","q": "60g","a": "减到20g回甘不足；加到120g甜得发腻、失去开胃感"},{"n": "白酒","q": "30ml","a": "减到10ml杂菌易生白花；加到60ml酒味太重、腌菜发苦"},{"n": "熟菜籽油（拌食时）","q": "50ml","a": "减到20ml拌菜不够香；加到100ml会盖住盐酸菜本身的酸脆"},{"n": "食用碱（护色）","q": "3g","a": "减到1g菜色暗黄；加到8g会发苦、失去脆度"},{"n": "细盐、葱花（拌食时）","q": "盐10g、葱花20g","a": "盐减到5g会偏淡；加到25g会过咸、抢掉发酵的酸甜。葱花减到8g香气不足；加到40g会抢味"}],"steps": ["选粗壮鲜嫩的青菜，砍收后摊在烈日下晾晒8小时以上至萎蔫失水——这是盐酸菜能保持脆嫩而不烂的关键，摊晒不足的菜腌好后会糊烂。","用盐逐层揉搓青菜，每揉一层撒一层盐，重点在菜梗和叶腋处，揉到菜体出水、渗出盐卤为止。","把腌渍好的青菜装入清洗干净、无油无水的陶坛或玻璃坛，一层菜一层盐码实压紧，上压石块，再注入没过菜面的凉糯米甜酒。","取独山皱皮辣椒粉、蒜头末、蒜苗末、冰糖、白酒、3g食用碱一起拌匀，填入菜层之间，再撒一层盐，注入坛沿水密封坛口。","坛子放在阴凉通风处，前10天每天检查一次、沿坛沿补水防干壳，自然发酵至少60天；坛口出现白花时撒冰糖或白酒即可消除。","食用时开坛取出一把，挤去多余盐卤，切成细段或细丝，用熟菜籽油、蒜末、干辣椒面、细盐、葱花拌匀即可上桌；也可做配菜，蒸扣肉、焖黄鳝、炒肉末、煎咸鱼都极香。"],"key": "整个腌制过程必须无油无生水，取用要专用筷子；一旦沾生水或油花，坛内会起白花、整坛变味，这是盐酸菜最常见的失败原因。","tip": "家庭版可先腌大盐酸（用青菜柄切段）最容易成功；细盐酸需把菜尖叶切细丝、拌料更费工。发酵时间不够不会出现酸，只会发涩，所以耐心等满60天再开坛。"},"贵定米粉": {"time": "2小时","level": "中等","servings": "3-4人份","ing": [{"n": "优质大米（本地高山大米）","q": "500g","a": "用陈米或碎米做出的粉没有筋丝、烫一下即断成碎节，减到400g则份量不足；加到600g需按比例延长蒸制时间"},{"n": "猪筒子骨","q": "600g","a": "减到300g汤味清淡、失去'没有好汤就没有好粉'的本味；加到1000g汤更浓但熬制时间翻倍"},{"n": "黄豆芽","q": "60g","a": "减到20g汤不鲜；加到150g会让汤发甜发浑"},{"n": "猪腿肉","q": "250g","a": "减到150g肉哨量不足；加到400g需多煨20分钟"},{"n": "槽头肉（脆臊原料）","q": "200g","a": "减到120g出油少、脆香不足；加到300g则腻、且会抢汤味"},{"n": "甜酒酿","q": "25g","a": "减到10g脆臊发苦；加到50g会带出明显酒味"},{"n": "豌豆尖","q": "80g","a": "减到30g缺了那一抹清甜；加到150g会抢汤味"},{"n": "油辣椒","q": "25ml","a": "减到8ml香而不辣；加到50ml会盖住骨汤的清鲜"},{"n": "酱油","q": "15ml","a": "减到5ml颜色寡淡；加到30ml会过咸"},{"n": "食醋、味精、白胡椒粉","q": "醋5ml、味精1g、白胡椒粉1g","a": "醋减到2ml酸头不足；加到15ml酸得压过鲜。白胡椒粉减到0.3g香气弱；加到3g会有明显药味"}],"steps": ["大米淘洗后浸泡4小时，磨成细腻米浆，用纱布过滤两遍，浆体呈能缓慢流动的稠度即可；米浆太稠做出的粉发硬，太稀则挂不住汤。","取浅口铁盘，铺上湿纱布，舀一薄层米浆（约1.5mm厚，不能超过这个厚度，超过就嚼着像牛皮），大火蒸3分钟至米粉定型，取下挂在竹竿上稍凉。","把整张米粉叠好，用刀切成宽约3mm的细条——贵定粉讲究'扁粉'，切得宽了叫'宽粉'，是另一道吃法。","另起汤锅，把筒子骨600g焯水后与黄豆芽、姜片、葱结同入清水，大火烧开转小火煨1.5小时至汤色乳白，用盐调味并保持在微温状态。","做脆臊：槽头肉切丁，冷锅下锅先煸出油，油尽后下瘦肉丁煸至焦黄，加入甜酒酿25g和食盐继续翻炒，成深褐色的丁即成脆臊。","另炒猪肉臊：猪腿肉切小丁，加姜末、酱油在锅内煸炒至水分收干成肉哨备用。","宽水锅烧至大滚，下米粉烫30秒左右立刻捞入碗中（久烫必断），舀滚烫骨汤，放脆臊、肉哨、豌豆尖，调油辣椒、酱油、醋、味精、白胡椒粉，撒葱花即成。"],"key": "米粉皮必须控制在1.5mm以内，厚了口感像牛皮；下锅烫的时间要短，烫久了会断成碎节，这是机制米粉最容易翻车的地方。","tip": "正宗贵定米粉讲究'一粉多哨'，脆臊、软哨、鲜肉哨可以同时放；本地人还爱加酸豇豆和豆腐乳，一碗粉配一碗豆浆最地道。"},"榕江手撕鸭": {"time": "3小时","level": "中等","servings": "4-5人份","ing": [{"n": "本地麻鸭（老鸭）","q": "1只约1800g","a": "减到1200g肉少骨多；加到2500g需延长卤制40分钟且柴、柴火灶更香"},{"n": "干辣椒（皱皮）","q": "40g","a": "减到15g辣味不足；加到80g糊辣椒的香会被生辣冲掉"},{"n": "糊辣椒","q": "50g","a": "减到20g只有干辣没有焦香；加到100g会咸焦发苦"},{"n": "卤料（八角、桂皮、香果、小茴香、沙姜）","q": "共25g","a": "减到10g香气单薄；加到50g药味太重、盖住鸭肉本味"},{"n": "姜","q": "30g","a": "减到10g去腥不足；加到60g姜味过冲"},{"n": "蒜","q": "25g","a": "减到10g蒜香不足；加到50g会发苦"},{"n": "花椒","q": "5g","a": "减到2g麻味出不来；加到12g会麻到发木"},{"n": "菜籽油（炸鸭用）","q": "600ml","a": "减到300ml炸不透、皮不脆；加到900ml油多浪费且易溅"},{"n": "生抽、料酒","q": "生抽40ml、料酒50ml","a": "生抽减到20ml上色浅；加到70ml会咸、压住鸭肉香"},{"n": "熟白芝麻、香菜段、葱花","q": "芝麻15g、香菜30g、葱花20g","a": "芝麻加到40g会抢香、也容易焦；香菜减到10g点缀色不够"}],"steps": ["麻鸭洗净去内脏，用料酒40ml、盐10g、生抽20ml抹匀全身并塞入姜片，在冷藏处腌制4小时以上，腌过夜更入味。","锅中加水没过鸭身，放入全部卤料、姜块、葱段和剩余料酒、剩余生抽，大火烧沸后转小火保持微沸状态卤2小时，筷子能轻松插透鸭腿即熟。","卤好的鸭捞出放凉，晾到完全不烫手再手撕——热着撕会碎、纤维撕不干净，撕成手指粗的条状，骨头另行丢弃。","另起锅倒入菜籽油，油温八成热时下鸭条炸3-4分钟，中途翻动两次，炸到表皮焦黄酥脆时捞出控油，晾凉备用。","倒出多余油留底油，转小火下干辣椒段、姜末、蒜末小火炒香，再下糊辣椒继续小火炒1分钟，逼出焦香和红油。","把炸好的鸭条倒回锅中，大火快速翻炒1-2分钟，让每条鸭肉均匀裹上红油和糊辣椒，关火焖3分钟让味道吃进肉里。","装盘撒熟白芝麻、葱花和香菜段，淋一勺锅底余下的红油，吃前再拌匀。"],"key": "鸭子必须卤到骨酥、完全放凉后再手撕；热撕会碎成渣，这是手撕鸭卖相的决定性一步。","tip": "榕江做法常在鸭肉上抹一层自家米酒再炸，皮更焦黄；怕油的可在第二步就不炸，直接用卤汁加糊辣椒拌吃，风味不减但少了那股焦香。"},"黔东南酸汤鸡": {"time": "80分钟","level": "中等","servings": "3-4人份","ing": [{"n": "本地散养土鸡","q": "半只约800g","a": "减到500g汤味不足、鸡不够炖；加到1200g需延长炖煮20分钟"},{"n": "红酸汤（自然发酵番茄辣椒）","q": "400ml","a": "减到250ml酸味不够醇厚；加到600ml酸味刺口、鱼肉甜味被盖住"},{"n": "黄豆芽","q": "100g","a": "减到50g吸汤不足；加到200g会抢汤味"},{"n": "番茄","q": "2个","a": "减到1个汤色偏淡；加到4个汤偏甜、酸汤的发酵香被盖住"},{"n": "姜","q": "25g","a": "减到10g去腥力弱；加到50g姜味太冲"},{"n": "蒜","q": "20g","a": "减到8g香气不足；加到40g发苦"},{"n": "野生木姜子（干）","q": "3g","a": "减到1g那股清凉香气出不来；加到8g会有明显药味"},{"n": "泡椒（小米辣泡制）","q": "4个","a": "减到2个辣度不够；加到10个辣得盖住酸香"},{"n": "折耳根、野葱、鱼香菜","q": "折耳根50g、野葱20g、鱼香菜20g","a": "折耳根减到20g清香不足；加到120g腥味盖过汤味。野葱减到5g香气弱；鱼香菜加到50g会有草腥感"},{"n": "菜籽油、白糖、盐、料酒","q": "菜籽油30ml、白糖5g、盐5g、料酒30ml","a": "白糖减到1g解酸味作用弱；加到15g会有明显甜味、破坏酸汤的酸爽"}],"steps": ["鸡斩成3cm见方的块，冷水浸泡30分钟去净血水，捞出沥干。","锅烧热下菜籽油，中火下姜蒜片爆香，倒入番茄块炒出红汁，直到番茄软烂出沙、汤汁变浓红。","倒入红酸汤400ml，加清水至总量约1200ml，大火烧开后转小火熬5分钟，让酸汤的发酵香和番茄的果酸完全融合。","转中火下鸡块，烹入料酒，加盖炖15分钟，鸡肉变白收紧即熟——不要久炖，鸡肉纤维会散、口感发柴。","放入黄豆芽和泡椒，继续煮3分钟让豆芽吸足酸汤；折耳根最后10秒下锅，久煮会烂且草腥味加重。","关火前滴入3-5滴木姜子油，撒野葱段和鱼香菜段，配一小碟糊辣椒蘸水上桌。"],"key": "酸汤的酸味只能来自自然发酵的番茄辣椒，绝不能用白醋或陈醋替代——醋的酸尖锐刺口，酸汤的酸是圆润带果香的，这是整道菜的根本。","tip": "做苗家酸汤的传统是'倒酸汤'：发酵的母酸要天天用不沾油盐的瓢舀起倒回，直到变酸，家庭简化版可用现成瓶装红酸汤但风味会薄一截。"},"贵州酸汤黄鱼": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "黄辣丁（黄颡鱼/角角鱼）","q": "500g（约6条）","a": "减到350g份量偏少；加到800g需把汤量同比加大，否则鱼肉入味不足"},{"n": "红酸汤","q": "350ml","a": "减到200ml酸味不够、汤色发淡；加到500ml酸味刺口"},{"n": "番茄","q": "1个","a": "减到0则汤色不够红亮、少了果酸回甜；加到3个汤偏甜、酸汤的发酵香被盖住"},{"n": "黄豆芽","q": "100g","a": "减到50g吸味不足；加到200g会稀释汤味"},{"n": "老豆腐","q": "150g","a": "减到60g没有吸附汤汁的厚味；加到250g会抢主角"},{"n": "泡椒（拍破）","q": "3个","a": "减到1个辣度不足；加到8个辣得盖住酸汤"},{"n": "姜片、蒜瓣","q": "姜20g、蒜15g","a": "姜减到8g去腥不足；蒜加到30g发苦"},{"n": "木姜子油","q": "5滴","a": "减到1-2滴香气太弱；加到15滴会有明显药味和苦味"},{"n": "白糖、盐","q": "白糖4g、盐4g","a": "糖减到1g压不住酸；加到12g汤变甜腻、失去酸爽"},{"n": "菜籽油、折耳根、葱香菜","q": "菜籽油25ml、折耳根40g、葱香菜20g","a": "折耳根减到15g清香不足；加到100g会喧宾夺主"}],"steps": ["黄辣丁刮净黏液、去鳃和内脏，冲洗干净后在鱼身两面各划两刀，抹少许盐和料酒腌10分钟去腥。","锅烧热下菜籽油，中火下姜片和蒜瓣爆香，倒入番茄块炒出红汁、炒到软烂出沙。","倒入红酸汤350ml，加清水至800ml，大火烧开后转小火熬3-5分钟，酸汤味完全煮透。","先下豆腐块和泡椒煮3分钟让豆腐吸味，再下黄豆芽煮1分钟。","转中火下黄鱼，用汤汁反复浇在鱼身上，全程不要频繁翻动以免碎鱼。煮3-4分钟，鱼眼变白、鳃盖翻开即熟。","关火前滴入木姜子油，撒折耳根末、葱香菜，另配一碗糊辣椒蘸水同吃。"],"key": "黄鱼下锅后绝不能翻动，一动就碎；判断熟度看鱼眼变白、鳃盖自然翻开，而不是看汤是否变浓。","tip": "黄辣丁刺细，主妇吃可用黄骨鱼或江团替代，味道更醇厚；木姜子油是贵州酸汤的标志香气，但有不习惯的人可省去。"},"玉屏扣肉": {"time": "2小时","level": "稍难","servings": "4-5人份","ing": [{"n": "带皮五花肉","q": "800g","a": "减到500g只够3人吃一顿；加到1200g需延长蒸制20分钟、碗也更深"},{"n": "甜酒酿汁（无则用料酒）","q": "80ml","a": "减到30ml去腥增甜不足；加到150ml甜味过重、盖住肉香"},{"n": "菜油（炸酥用）","q": "800ml","a": "减到500ml不够炸、需分批炸；加到1200ml浪费且炸时易溢出"},{"n": "生抽","q": "40ml","a": "减到20ml上色偏浅；加到70ml会过咸"},{"n": "食盐","q": "15g","a": "减到8g腊香味不足；加到30g蒸后咸到发苦"},{"n": "白糖或冰糖","q": "40g","a": "减到15g甜香不足；加到80g甜到发腻，失去咸香主味"},{"n": "花椒","q": "10g","a": "减到4g麻香不足；加到20g麻得刺口"},{"n": "八角","q": "2颗","a": "减到1颗香气弱；加到5颗药味太重"},{"n": "葱段、姜片","q": "葱40g、姜30g","a": "姜减到10g去腥不足；葱加到80g会抢肉香"},{"n": "煮肉原汤","q": "150ml","a": "减到50ml蒸后干涩发柴；加到300ml汤汁过多、扣盘时易散"}],"steps": ["把五花肉皮面在明火上干烙至焦黄（逼出毛孔里的腥臊），取出用刀刮洗干净，切成约15cm见方的大块。","冷水下锅，加姜片、葱段、八角、花椒烧开1分钟再下肉块，转小火煮到筷子能轻松插入肉皮（约六七分熟），捞出晾凉。","把晾凉的大肉块放入盆中，加甜酒酿汁、生抽、食盐、白糖、姜片、葱段、花椒、八角，腌制30-40分钟，使表面入味。","菜油烧到五六成热（筷子插入周围冒小泡），下腌好的肉块，中火慢慢炸3-4分钟，炸到皮呈酱红色并鼓起小泡，捞出沥油，晾凉后皮会因收缩起皱成虎皮。","把炸好的肉改刀切成约0.5cm厚的长片或长三角形，皮朝下整齐码入碗中，堆叠成塔形。","碗中加入白糖、葱段、姜片，淋上煮肉的原汤150ml，上蒸笼大火蒸40-50分钟，蒸到肉皮软烂颤动即可。","出锅时把盘子扣在碗口上，双手持盘与碗一起快速倒扣过来，揭碗成盘，淋上蒸出的汤汁，撒葱花上桌。"],"key": "扣肉的灵魂在炸酥那一步：油温只能五六成热、中火慢炸，皮炸到酱红鼓泡后必须浸凉水收缩，才会有'皮酥而不烂'的虎皮口感；油温过高肉会发硬。","tip": "玉屏侗家甜扣肉不放任何配菜，靠甜酒酿的发酵香和糖色取胜；想做成咸口扣肉就把白糖减到15g、白酒替代甜酒酿，或在蒸时铺一层炒香的梅干菜吸油。"},"贵州油粑粑": {"time": "3小时","level": "稍难","servings": "3-4人份（可做16-20个粑粑）","ing": [{"n": "糯米","q": "500g","a": "减到300g需减少馅料用量；加到700g外皮太厚、炸不透且难熟"},{"n": "大米","q": "150g","a": "减到50g米浆会太黏、搓不成团；加到300g口感偏硬失去糯劲"},{"n": "黄豆（打豆沙）","q": "200g","a": "减到100g馅料偏稀易漏；加到300g馅太干发柴"},{"n": "红糖","q": "120g","a": "减到60g甜味不足；加到200g过甜、盖住豆香"},{"n": "菜籽油（炸制）","q": "1000ml","a": "减到600ml需分批炸；加到1500ml浪费且吸油过多"},{"n": "猪油或菜籽油（拌豆沙）","q": "50g","a": "减到15g馅心发干不流心；加到100g馅太腻"},{"n": "食盐（豆沙馅）","q": "4g","a": "减到1g只有甜没有咸香回味；加到10g会咸"},{"n": "花椒粉（豆沙馅）","q": "2g","a": "减到0.5g失去贵州豆沙窝的那点椒麻；加到6g发麻"},{"n": "熟黄豆粉、熟芝麻","q": "黄豆粉20g、芝麻10g","a": "黄豆粉减到8g香味不足；加到50g会抢掉糍粑本味、像吃豆面。芝麻减到3g香气弱；加到30g略抢味"},{"n": "葱花、糍粑辣椒（拌豆沙）","q": "葱花20g、糍粑辣椒15g","a": "葱花减到5g香气弱；糍粑辣椒加到40g辣味会盖住甜馅"}],"steps": ["黄豆洗净冷水泡8小时至能轻松捏碎，加水磨成细腻豆浆，用纱布滤去豆渣，豆浆小火煮开并不断搅拌防糊底，煮到能挂勺成稠糊状。","趁热加入红糖120g、50g猪油、食盐4g和花椒粉2g，小火继续翻炒8分钟，炒到豆沙能拉丝、铲起来不流动，摊开晾凉备用。","糯米500g和大米150g混合洗净，冷水浸泡8-10小时到手指能轻松捏碎，沥干后上蒸笼大火蒸30分钟，中途翻拌一次让受热均匀。","蒸熟的米倒入木盆或石臼，趁热用木杵反复舂打8-10分钟，舂到米粒全部破碎、黏糯成团、能拉出细丝。","取一小团糯团压成圆片，包入一勺豆沙，收口捏紧搓成圆球，再压成厚约1.5cm的圆饼，边缘捏出细密花边。","菜籽油烧到六成热（约160℃），下油粑粑用中小火慢炸3分钟，表面微黄后转最小火并盖上锅盖焖3分钟，让内部彻底熟透而不外焦。","捞出控油，趁热撒上熟黄豆粉和芝麻，也可以蘸红糖水吃。"],"key": "糯米必须舂到看不见整粒米、黏糯拉丝才有'外脆内糯'的层次；油炸时'炸微黄+盖盖焖'是外焦里嫩的要诀，直接大火炸会外焦内生。","tip": "遵义豆沙窝用同样的糯米团加咸豆沙，是咸口版本；外面摆摊的油炸粑多是大米糯米黄豆按3:4:3磨浆直接摊成薄饼炸，讲究省事的家庭可以照做。"},"织金糍粑": {"time": "2小时","level": "中等","servings": "3-4人份","ing": [{"n": "糯米","q": "500g","a": "减到300g需同步减少配料；加到700g舂起来更费力、糍粑偏硬"},{"n": "红糖","q": "100g","a": "减到40g甜味不足；加到180g过甜、盖住米香"},{"n": "熟黄豆粉","q": "60g","a": "减到20g香味不够；加到120g会变成一碗豆面"},{"n": "熟白芝麻","q": "20g","a": "减到5g缺少香气层次；加到50g会抢掉红糖的甜"},{"n": "白糖","q": "20g","a": "减到8g糍粑本身偏淡；加到50g甜得发腻"},{"n": "茶籽油或菜籽油","q": "20g","a": "减到5g糍粑容易粘木杵；加到50g揉面打滑不易成形"},{"n": "蜂蜜","q": "20g","a": "减到5g烤制不上色；加到50g太甜且易焦"},{"n": "温水（揉糍粑用）","q": "50ml","a": "减到20ml太硬揉不开；加到120ml会粘手、粘住木杵"},{"n": "玫瑰糖（可选）","q": "20g","a": "减到5g花香气弱；加到50g花香太浓抢主角"}],"steps": ["糯米淘洗干净后用清水浸泡4-8小时，泡到米粒用手指能轻松捏碎，捞出沥干。","把泡好的糯米平铺在饭甑里，大火蒸1小时至完全熟透、饭粒透亮，舀出趁热倒进木盆或石臼。","趁热用木杵均匀舂打，力度要匀——太重杵不动、太轻米不绵密，一直舂到糯米绵软如泥、黏韧能拉出细丝。","把舂好的糍粑摊在抹了油的案板上揉匀，分成每个约60g的剂子，搓圆后压成直径6-7cm、厚1.5cm的圆饼，摆到竹筛上晾至不烫手。","红糖加等量清水在小火上熬成能拉丝的糖浆（熬到铲起像稀蜂蜜就停火，熬过头放凉会变成糖饼），熟黄豆粉加白糖和芝麻拌匀备用。","平底锅刷薄油，小火把糍粑饼两面各烙2-3分钟，烙到两面微黄、外皮起韧；或放烤盘200℃烤10分钟至鼓胀。","装盘后趁热淋红糖浆、撒熟黄豆粉和芝麻，也可以直接蘸红糖水吃。"],"key": "舂糍粑的力度要均匀，舂到'绵软如泥、黏韧交织'才合格；没舂透的糍粑内部还有硬米粒，烤时受热不均会外焦内生。","tip": "织金人爱在冬夜围炉烤糍粑，讲究'烤软烤透'；配黄豆粉是解腻的经典吃法，甜酒汤（米酒）煮糍粑则是另一种早餐吃法。"},"晴隆烤豆腐": {"time": "1.5小时（含发酵）","level": "中等","servings": "3-4人份","ing": [{"n": "发酵小豆腐（酸汤豆腐/臭豆腐）","q": "500g","a": "减到300g份量偏少；加到800g需延长烤制时间"},{"n": "食用碱水","q": "200ml","a": "减到100ml豆腐发不出泡；加到400ml碱味重、表面发滑"},{"n": "折耳根","q": "100g","a": "减到40g缺了那股清冽；加到200g会盖住糊辣椒的焦香"},{"n": "苦蒜（贵州苦蒜）","q": "20g","a": "减到8g辛香不足；加到40g苦味太冲"},{"n": "糊辣椒","q": "35g","a": "减到12g只有辣味没有焦香；加到70g会发苦"},{"n": "姜末","q": "12g","a": "减到5g去腥不足；加到25g姜味冲"},{"n": "蒜泥","q": "15g","a": "减到6g蒜香弱；加到30g发苦"},{"n": "酱油、香醋","q": "酱油25ml、香醋10ml","a": "酱油减到10ml味淡；加到45ml过咸盖住豆腐香。香醋减到3ml酸头不足；加到25ml酸味盖住糊辣椒"},{"n": "味精、花椒面","q": "味精3g、花椒面2g","a": "味精减到1g鲜味弱；花椒面加到6g麻得发木"},{"n": "菜籽油（刷油）","q": "30ml","a": "减到10ml表面干涩易烤焦；加到60ml腻且滴落炭火起烟"}],"steps": ["豆腐切成5cm宽、7cm长、3cm厚的长方块，放入碱水200ml中浸泡约2小时，让豆腐表面碱化发滑，烤出来才是'皮黄内嫩'的口感。","捞出沥干，用湿布盖住放在竹篮里，在25℃左右的温暖处发酵12小时以上；用手触摸表面有黏性即代表发酵到位，发过头会发酸掉渣。","发酵同时调佐料：折耳根切碎、苦蒜切末，与糊辣椒、姜末、蒜泥、酱油、香醋、味精、花椒面拌匀，淋入菜籽油拌成能舀起的糊状蘸水。","炭火炉烧到无明火只剩白灰的中火状态，把豆腐块摆在专用铁丝烤架上，中火烤3-4分钟，边烤边在表面刷一层菜籽油。","烤到豆腐两面皮黄、边缘微微鼓起、内部松泡鼓胀时停火；此时用竹签或小刀在侧面划开一道口，不要划断。","用竹片把豆腐当腰剖开一半，舀入一勺调好的佐料填满，再把表皮盖上，趁热吃。"],"key": "豆腐的碱水浸泡和低温发酵不能省，这是'外黄内嫩、松泡鼓胀'的前提；佐料必须提前拌好，烤豆腐要趁热舀入、凉了豆腐会回缩变硬。","tip": "没有炭火可以用烤箱200℃烤18-20分钟、中途刷两次油；传统用柏木锯末或无烟木炭，火烟不呛人、烤出来有烟香。"},"都匀细粑稀": {"time": "50分钟","level": "中等","servings": "2-3人份","ing": [{"n": "粘米粉","q": "200g","a": "减到120g份量偏少；加到300g需同比例调整糯米粉和容器"},{"n": "糯米粉","q": "80g","a": "减到30g口感不够软糯；加到120g会粘牙、难成型"},{"n": "甜酒（糯米醪糟）","q": "250g","a": "减到120g甜味不够；加到400g甜得盖住米香、只剩酒味"},{"n": "红糖","q": "60g","a": "减到25g颜色浅、甜度不足；加到100g太甜"},{"n": "熟黄豆粉","q": "30g","a": "减到10g香味不足；加到60g会抢掉甜酒的清甜"},{"n": "熟花生碎","q": "25g","a": "减到10g缺了脆感；加到60g会盖住粑粑本身"},{"n": "熟白芝麻","q": "10g","a": "减到3g香气弱；加到25g略抢味"},{"n": "玫瑰糖","q": "15g","a": "减到5g花香气弱；加到40g花香盖过甜酒"},{"n": "温水（拌米粉）","q": "150ml","a": "减到100ml粉捏不成团、蒸后散；加到200ml太稀、蒸不起层"},{"n": "冰糖（甜酒用）","q": "20g","a": "减到8g甜度略淡；加到50g甜酒过甜"}],"steps": ["把粘米粉200g和糯米粉80g混合均匀，分多次少量加温水150ml，边加边用手搓，直到粉团达到'干而不粉、稀而不成团'——一捏能成、一碰就散的状态。","过筛一遍，把粗颗粒筛掉，筛过的粉更细腻、蒸出来口感绵密不夹生。","取腰鼓形小木甑或圆形浅模，把湿粉轻轻搌平填入，不要压实，保留空隙让蒸汽能穿透，否则中间会夹生结硬块。","甑架在已烧开水的锅上，中火蒸约15分钟，蒸到粑粑颜色由白转微黄、用牙签戳进去不带生粉即熟。","另起碗，甜酒250g加冰糖20g，用烧开的甜酒汤或热水冲调成稀薄的甜汤——这一步是'稀'，贵州人叫甜酒汤。","把蒸好的细粑稀放进碗中，倒入冲好的甜酒汤，撒熟黄豆粉、熟花生碎、芝麻和玫瑰糖，趁热拌匀食用。"],"key": "米粉的含水量是成败关键：必须'捏得成团、一碰即散'，压实了会硬成一坨，填得太松又蒸不成型；甑内留空隙是让蒸汽穿透、避免中心夹生。","tip": "甜酒汤要现冲现吃，凉了酒味发酸冲；喜欢更绵密的可用破壁机打细米浆代替石磨磨粉，这是家庭化改良，但传统石磨的米香更足。"},"遵义豆花面": {"time": "1.5小时","level": "稍难","servings": "3人份","ing": [{"n": "上等面粉（宽刀面）","q": "300g","a": "减到200g份量不足；加到400g面条偏硬、挂不住豆浆"},{"n": "土鸡蛋","q": "2个","a": "减到1个面色发黄；加到3个面条偏软失去'薄而透'的口感"},{"n": "食用碱（碱水）","q": "10ml","a": "减到4ml面汤发黄有碱味但面条不滑；加到20ml碱涩明显"},{"n": "黄豆（磨浆点豆花）","q": "150g","a": "减到100g豆浆稀、煮不熟；加到250g需多磨多煮15分钟"},{"n": "酸汤（点豆腐用的窖水）","q": "60ml","a": "减到20ml点不成形、豆花会散；加到100ml豆花偏酸发涩。用石膏卤水替代会有苦涩味"},{"n": "糍粑辣椒","q": "80g","a": "减到30g油辣椒香味不足；加到150g会辣得盖住豆花与豆浆的清甜"},{"n": "菜籽油（熬油辣椒）","q": "150ml","a": "减到80ml无法浸透辣椒；加到250ml油辣椒过腻、挂不住肉丁"},{"n": "猪腿肉丁、鸡肉丁","q": "各60g","a": "减到各30g荤味不足；加到各120g变成纯肉臊面"},{"n": "油炸花生米、油炸豆腐丁、油炸黄豆","q": "各25g","a": "各减到10g口感单薄；各加到50g蘸水太干、缺汤汁"},{"n": "姜末、蒜泥、葱花、鱼香菜（留兰香）、花椒面、酱油、醋、味精","q": "姜末10g、蒜泥15g、葱花15g、鱼香菜15g、花椒面2g、酱油15ml、醋6ml、味精2g","a": "鱼香菜减到5g就没了遵义味；加到40g草腥味过重。姜末减到4g去腥弱；蒜泥加到30g发苦，葱花加到40g抢味。花椒面加到6g麻得压住豆花的嫩；醋加到20ml酸得抢味"}],"steps": ["面粉300g加鸡蛋2个、碱水10ml和120ml温水（约30℃）和成面团，揉至表面光滑不粘手，盖湿布醒30分钟。","把面团擀成极薄的大面片，厚度不超过1.5mm，撒上芡粉防止粘连，再切成韭菜叶宽的宽刀面。","黄豆浸泡4小时后磨浆，滤去豆渣，煮沸后用上次点豆腐留下的酸汤点浆，点成内酯豆腐般的嫩豆花——酸汤点的豆花没有石膏的苦涩，比豆腐脑更紧实。","舀一勺豆浆入锅小火煮开，做成煮面的汤底；豆花切成块状在豆浆里烫热备用。","熬油辣椒：菜籽油烧到八成热，把糍粑辣椒连同盐、五香料粉、南乳、甜酱倒入锅中，边倒边搅，全程不停翻炒约2小时，熬到红亮油润、辣椒香透而不焦——中途要控制火力不能巴锅，一旦辣椒沉底发苦整锅就毁了。","另起小碗做蘸水：炒香的肉丁、鸡丁、炸花生、炸豆腐丁、炸黄豆、姜末、葱花、鱼香菜段、芫荽末、水豆豉、酱油、花椒面、味精拌匀，再舀一勺热油辣椒拌入。","宽水锅烧开下宽刀面，煮到断生即捞入盛有豆浆的碗中，盖上烫热的豆花，配一碟蘸水上桌；吃法是先把面条和豆花挑进蘸碟，蘸着吃。"],"key": "油辣椒是遵义豆花面的灵魂：菜油要单独烧到极热，糍粑辣椒倒入后不停搅动慢熬两小时，火候宁小勿大，辣椒一旦沉底巴焦，整锅油辣椒就发苦毁掉。","tip": "鱼香菜（留兰香薄荷）是遵义味道的记忆点，买不到可用普通薄荷替代但香气略不同；怕麻烦可以用市售油辣椒，但风味层次会少一半。"},"折耳根炒腊肉": {"time": "40分钟","level": "简单","servings": "2-3人份","ing": [{"n": "农家烟熏腊肉","q": "300g","a": "减到150g份量偏少、腊香不足；加到500g会过于咸香、压住折耳根的清气"},{"n": "折耳根（鱼腥草）","q": "250g","a": "减到100g草腥味抢不过腊肉；加到400g会腥得吃不下饭"},{"n": "干辣椒","q": "5个","a": "减到2个香而不辣；加到10个会只剩辣味没有烟熏香"},{"n": "干豆豉（颗颗）","q": "15g","a": "减到5g酱香不足；加到40g会咸得发苦"},{"n": "姜","q": "15g","a": "减到6g去腥不足；加到30g姜味太冲"},{"n": "蒜片、蒜苗","q": "蒜3瓣、蒜苗2根","a": "蒜苗减到1根香气弱；加到4根会抢掉折耳根的味道"},{"n": "菜籽油","q": "30ml","a": "减到10ml腊肉煸不出油；加到60ml整菜油腻"},{"n": "花椒","q": "10粒","a": "减到4粒麻香弱；加到25粒麻得盖住折耳根"},{"n": "生抽","q": "12ml","a": "减到5ml味淡；加到25ml会过咸、腊肉本味被盖"},{"n": "盐","q": "3g","a": "腊肉自带咸味，通常可不放；减到1g略欠味；加到8g会过咸"}],"steps": ["腊肉用温水洗净表面浮灰，上锅蒸15-20分钟至皮软不硌牙，取出晾凉后切成1.5mm薄片——趁热切会粘连发软，晾凉切才利落。","折耳根洗净去掉老根和须，用手掐成3-4cm长段，不用刀切——金属刀口会让折耳根发黑、腥味更重。","锅烧热下菜籽油，中火下腊肉片煸炒2分钟，逼出油脂至肥肉透明、边缘微微卷起，盛出备用。","锅内留底油，转中火下姜丝、蒜片、干辣椒段和豆豉颗，小火炒1分钟至豆豉香散发、辣椒微焦。","转大火下折耳根，快速翻炒1-2分钟至折耳根微微发软即可，久炒会出水变软、脆口感全失。","倒回腊肉片，沿锅边淋生抽12ml、撒盐翻匀，最后下蒜苗段大火翻炒十几秒出锅。"],"key": "折耳根全程必须大火快炒，出水就等于失败；折耳根用手掐不用刀切，是贵州本地人保持脆嫩、去腥的必要细节。","tip": "腊肉偏咸时可先用温水泡30分钟去部分盐分；给外地人吃可把折耳根减半、改用焯水10秒的版本，腥味会轻很多但折耳根的清香也少一半。"},"凉拌折耳根": {"time": "20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "新鲜折耳根","q": "300g","a": "减到150g不够一盘、也压不住糊辣椒；加到500g会剩、且草腥味过重"},{"n": "糊辣椒","q": "25g","a": "减到8g只有干辣没有糊香；加到50g会咸焦发苦"},{"n": "油辣椒","q": "20ml","a": "减到8ml挂汁不足；加到40ml会盖住折耳根的清冽味"},{"n": "生抽","q": "20ml","a": "减到8ml颜色淡；加到35ml会过咸"},{"n": "香醋","q": "12ml","a": "减到4ml酸头不够；加到30ml酸味盖住糊辣椒的焦香"},{"n": "蒜泥","q": "15g","a": "减到6g蒜香不足；加到30g发苦"},{"n": "姜末","q": "8g","a": "减到3g去腥弱；加到20g姜味太冲"},{"n": "花椒面","q": "2g","a": "减到0.5g麻味出不来；加到6g麻到发木、吃不出折耳根的香"},{"n": "葱花、香菜","q": "各20g","a": "香菜减到8g点缀色淡；加到50g会抢掉主味"},{"n": "熟白芝麻、白糖、食盐","q": "芝麻5g、白糖3g、盐2g","a": "白糖减到1g提鲜不明显；盐通常可不加，加到6g会过咸"}],"steps": ["折耳根洗净，掐掉老根和白须，放入冷水中浸泡10分钟去泥土味和涩味，捞出沥干后掐成两指宽的小段。","把糊辣椒、花椒面、蒜泥、姜末、葱花、香菜末、芝麻、白糖、盐先在碗里拌匀。","另起锅烧热菜籽油，冒小烟后关火，直接泼在碗里的糊辣椒上，激出焦香——这就是贵州凉拌折耳根的'灵魂动作'。","倒入生抽和香醋搅匀成蘸汁，尝一下咸淡酸度，不够酸再补半勺醋。","把折耳根段倒进碗里，用筷子从底部翻拌均匀，静置5分钟让味道渗入根茎，装盘即可。"],"key": "糊辣椒必须是干锅小火焙至焦香后舂碎的粗粒，现做现吃最香；用机器打的细辣椒面只有辣味没有糊香，拌出来就是一碗普通凉拌菜。","tip": "外地人第一筷往往不敢夹，可以先只淋汁不拌匀、夹一小根尝味；折耳根选粗壮鲜嫩的、掐断处渗水多的是嫩尖，腥味最轻。给小孩吃可先用开水焯10秒。"},"水豆豉拌折耳根": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "折耳根","q": "250g","a": "减到120g份量少；加到400g豆豉的咸香压不住草腥"},{"n": "水豆豉（湿豆豉）","q": "80g","a": "减到30g酱香不足；加到150g会咸得发苦、抢掉折耳根味"},{"n": "干豆豉","q": "15g","a": "减到5g香气不够；加到30g颗粒太碎、拌不匀"},{"n": "糊辣椒","q": "20g","a": "减到6g没有糊香；加到40g会焦苦"},{"n": "蒜末、姜末、小米辣（剁圈）","q": "蒜末15g、姜末8g、小米辣2个","a": "蒜末减到6g蒜香弱；加到30g发苦。姜末减到3g去腥不足；加到20g姜味冲。小米辣减到1个辣度不足；加到6个辣得盖住豆豉香"},{"n": "生抽","q": "15ml","a": "减到6ml味淡；加到30ml过咸"},{"n": "香醋","q": "10ml","a": "减到3ml酸头弱；加到25ml酸味压过豆豉"},{"n": "菜籽油","q": "25ml","a": "减到8ml豆豉煸不出香；加到50ml会腻"},{"n": "葱花、香菜","q": "各20g","a": "香菜减到8g装饰不足；加到50g草腥加倍"}],"steps": ["折耳根洗净去老根，冷水浸泡10分钟后沥干，掐成3cm小段备用。","干豆豉用温水泡5分钟至微微回软，与水豆豉一起剁成粗末——贵州的水豆豉是用黄豆煮熟后用豆豉叶包裹焐制发酵的，湿软带黏性、酱香浓，剁碎才好拌匀。","锅烧热下菜籽油，小火下蒜末、姜末、小米辣圈炒香，倒入豆豉末继续小火翻炒2分钟，直到豆豉香彻底激发、微微发亮。","调入生抽、香醋、糊辣椒拌匀成酱汁，关火。","折耳根段放入大碗，淋上刚炒好的豆豉酱，撒葱花香菜，快速翻拌均匀即可，讲究现拌现吃。"],"key": "豆豉一定要小火慢炒到发亮出香，不能用大火——大火一炒就发苦，整盘折耳根就毁了；湿豆豉剁碎再炒，是香气均匀的关键。","tip": "豆豉的发酵味有人接受不了，可以减到一半并加一勺油辣椒补足辣味；用干豆豉替代水豆豉要先干锅炒香再泡软，风味偏干香少一分黏糯。"},"糟辣蛋炒饭": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "隔夜米饭（冷藏）","q": "400g","a": "减到250g份量少、且一人份需加大辣量；加到600g需同步增加蛋和辣度，否则味道被稀释"},{"n": "土鸡蛋","q": "3个","a": "减到2个蛋香不足；加到5个会抢过糟辣椒、炒饭只剩蛋味"},{"n": "糟辣椒","q": "45g","a": "减到15g只剩一点微酸、成了普通蛋炒饭；加到90g酸味压过米香、发酸"},{"n": "猪油","q": "30g","a": "减到10ml蛋炒得不蓬松；加到60g会腻口"},{"n": "菜籽油","q": "15ml","a": "减到5ml容易粘锅；加到30ml油重"},{"n": "蒜末","q": "10g","a": "减到3g香气弱；加到20g发苦"},{"n": "腊肉丁（火腿肠丁）","q": "50g","a": "减到20g缺了肉香；加到100g会抢掉糟辣椒的主角位置"},{"n": "生抽","q": "10ml","a": "减到4ml颜色淡；加到25ml会过咸"},{"n": "白糖","q": "3g","a": "减到1g压不住酸；加到10g会有明显甜味"},{"n": "食盐、葱花","q": "盐2g、葱花15g","a": "糟辣椒和生抽自带咸味，盐通常可不加；减到1g略欠味；加到6g会过咸。葱花减到5g香气弱；加到30g会抢味"}],"steps": ["鸡蛋打散加少许葱花；米饭用手抓散到没有结块，腊肉丁切成小丁备用。","锅烧到冒烟，下猪油30g润锅，滑入蛋液，用铲子快速划散炒成大块金黄的蛋，盛出备用。","锅里补一点菜籽油，下蒜末小火炒香，倒入糟辣椒45g转小火慢慢煸2分钟，不停翻炒直到红油完全渗出、酸辣香气冲鼻——这一步炒不出红油就不是糟辣炒饭。","转大火倒入米饭，用铲子背不停压散翻炒2分钟，让米粒粒粒分明并均匀染上红油，炒到锅底微干、饭粒微微发响。","把炒好的蛋和腊肉丁倒回锅中，淋生抽10ml、撒白糖3g快速翻匀，让每粒米都挂上蛋香和糟辣味。","关火撒葱花翻两下出锅，配一碟酸萝卜或泡酸菜一起吃，干香配脆爽最解腻。"],"key": "必须是隔夜冷藏的干饭，米粒收干水分才炒得粒粒分明；新煮的饭湿气重，下锅就黏成团，这是糟辣蛋炒饭最常见的失败原因。","tip": "糟辣椒本身带咸味，盐和生抽都要少放；炒到最后动作要快，炒久了米粒发硬、失去干香。"},"糟辣鱼": {"time": "50分钟","level": "中等","servings": "3-4人份","ing": [{"n": "鲤鱼（或黔鱼/草鱼）","q": "1条约1200g","a": "减到800g鱼不够吃、且需缩短炸制时间；加到1800g需把锅放大并延长焖煮10分钟"},{"n": "糟辣椒","q": "80g","a": "减到40g酸辣味不足、汤色发淡；加到150g酸味盖住鱼肉的鲜甜"},{"n": "姜、蒜","q": "姜25g、蒜25g","a": "姜减到10g去腥不足；加到50g姜味太冲。蒜减到10g蒜香弱；加到50g发苦"},{"n": "大葱段、葱花","q": "大葱40g、葱花20g","a": "葱减到15g香气不足；加到80g会抢味"},{"n": "干花椒（颗粒）","q": "6g","a": "减到2g麻香出不来；加到15g麻得发木"},{"n": "菜籽油（炸鱼）","q": "600ml","a": "减到350ml需分批炸；加到1000ml浪费且易溅油"},{"n": "料酒","q": "40ml","a": "减到15ml去腥不足；加到80ml汤中酒味过重"},{"n": "生抽、白糖、食盐","q": "生抽20ml、白糖8g、盐5g","a": "白糖减到2g压不住酸；加到20g汤变甜腻失去酸辣"},{"n": "香菜、鱼香菜","q": "各20g","a": "香菜减到8g装饰不足；鱼香菜加到50g会有草腥味"},{"n": "淀粉","q": "20g","a": "减到8g防粘效果弱；加到40g外壳会厚、失去脆感"}],"steps": ["鱼处理干净，刮净黑膜、去除鱼腹血丝，在鱼身两面均匀打上深至鱼骨的一字花刀，用料酒、葱段、姜片、盐和花椒粉抹匀内外，腌制15分钟。","擦干鱼身薄拍一层干淀粉，防止下锅粘锅、锁住鱼肉水分。","锅烧热下菜籽油，油温五六成热时下鱼，全程中火慢炸，中途不要急着翻动，等一面定型金黄后再翻面，两面炸至金黄干脆时捞出控油。","锅内留油烧热，下姜蒜末、葱段和干花椒颗粒爆香，倒入糟辣椒80g转中小火翻炒2-3分钟，炒出红油和发酵酸香。","加入清水至刚好没过鱼身的三分之二，大火烧开，调入生抽20ml、白糖8g，再放入炸好的鱼。","转中小火慢焖8-10分钟，期间用勺子把汤汁反复浇在鱼身上帮助入味，汤汁千万不能煮干——留足汤汁拌饭才是灵魂。","关火撒葱花、香菜和鱼香菜，把锅中红亮汤汁舀在鱼身上即成。"],"key": "糟辣椒必须中小火炒出红油再加水，这一步决定了整道菜是'发酵酸香'还是'生辣水煮鱼'；焖煮全程中小火，大火会把鱼肉煮老煮破。","tip": "鱼不要太大，1.2-1.5斤最合适，方便炸透也方便入味；鲤鱼带小刺，招待小孩可换黔鱼或鲈鱼。这道菜隔夜更好吃，次日用汤汁拌面更绝。"},"糟辣回锅肉": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "带皮五花肉","q": "350g","a": "减到200g份量不足；加到500g需多煮10分钟、且腻"},{"n": "糟辣椒","q": "50g","a": "减到20g只剩辣味没有发酵酸香；加到90g会酸得盖住肉香"},{"n": "青蒜苗","q": "150g","a": "减到80g蒜香不足；加到250g会抢味、且蒜苗的生味盖住糟辣"},{"n": "姜、蒜、葱白","q": "姜15g、蒜15g、葱白20g","a": "姜减到6g去腥不足；加到30g姜味太冲。蒜减到6g蒜香弱；加到30g发苦。葱白减到8g香气弱；加到40g会抢味"},{"n": "花椒、八角","q": "花椒10粒、八角1颗","a": "花椒减到4粒麻香弱；加到20粒麻得发木。八角减掉则煮肉时香气不足；加到3颗药味重"},{"n": "菜籽油","q": "30ml","a": "减到10ml肉煸不出油；加到60ml太腻"},{"n": "生抽、老抽","q": "生抽15ml、老抽3ml","a": "生抽减到6ml味淡；加到30ml过咸。老抽超过5ml就会发黑"},{"n": "白糖、黄酒、味精","q": "白糖6g、黄酒15ml、味精2g","a": "白糖减到2g压不住糟椒的酸；加到20g会有明显甜味"},{"n": "辣椒水豆豉","q": "15g","a": "减到5g增香不明显；加到40g会咸得发苦"}],"steps": ["五花肉皮面在明火上干烙至焦黄，取出刮洗干净——烙皮去腥是贵州版回锅肉的关键一步。","锅中烧水，放花椒、葱结、姜片熬开1分钟，再下五花肉煮到筷子能轻松插入肉皮（约七分熟，别煮太烂），捞出沥干。","把肉用冷水冲凉或进冰箱急冻3分钟，趁外冷内热切成尽量完整的薄片，这样切不碎、煸出来有型。","净锅烧热不放油，下肉片用中火慢慢煸出油，至肥肉透亮、肉片边缘微微卷成小碗状，滗出多余油分（剩余不超过3汤匙）。","把肉推到锅沿，用底油下姜丝、葱白丝爆香，再下糟辣椒50g和辣椒水豆豉15g，转小火慢炒1分钟，炒出红油和酸香。","肉片倒回锅中大火翻匀，调入白糖6g、生抽、老抽、黄酒翻炒均匀。","下青蒜苗段大火快炒约1分钟至蒜苗断生，尝咸淡后调味精，出锅装盘。"],"key": "肉要冷水下锅煮、煮完冲冷水再切，这三步决定肉片是软糯不腻还是干硬发柴；煸肉全程中火慢逼油，大火会直接把肉片煎焦。","tip": "糟辣椒和生抽自带咸味，250-350g肉一般不另放盐；怕酸的人可把糟辣椒减半并补一勺油辣椒，老抽只作增色绝不能多放。"},"糍粑辣椒鸡": {"time": "45分钟","level": "中等","servings": "3人份","ing": [{"n": "本地土鸡（切块）","q": "700g","a": "减到450g份量少；加到1000g需把焖煮时间延长到20分钟"},{"n": "糍粑辣椒","q": "120g","a": "减到50g只有辣味没有黏糯的酱状口感；加到200g会糊锅发苦"},{"n": "姜、蒜","q": "姜25g、蒜25g","a": "姜减到10g去腥不足；加到50g姜味冲。蒜减到10g蒜香弱；加到50g发苦"},{"n": "花椒","q": "6g","a": "减到2g麻香出不来；加到15g麻到发木"},{"n": "菜籽油","q": "150ml","a": "减到80ml辣椒吸油不足、香味出不来；加到250ml会腻且辣椒发闷"},{"n": "料酒、白糖、生抽","q": "料酒25ml、白糖8g、生抽15ml","a": "料酒减到10ml去腥弱；加到50ml酒味残留明显。白糖减到3g压不住辣味；加到20g会有明显甜味。生抽减到6ml味淡；加到30ml会过咸"},{"n": "青蒜苗","q": "40g","a": "减到15g缺了蒜香；加到80g会抢味"},{"n": "清水（焖煮用）","q": "150ml","a": "减到60ml易烧干发苦；加到300ml成汤汁、辣椒味被稀释"}],"steps": ["鸡块剁成3cm见方，清水洗净沥干，厨房纸吸干表面水分。","锅烧热下菜籽油120ml，大火下鸡块煸炒3-4分钟，炒到表面水分收干、鸡肉微微焦黄，盛出备用——这一步是把腥味逼出去的关键。","底油转中火，下姜蒜末和花椒炒香，倒入糍粑辣椒120ml，全程中小火慢炒3-4分钟，不停翻炒直到红油大量渗出、辣椒与肉完全融合成酱。","把鸡块倒回锅中翻炒均匀，加生抽15ml、白糖8g、料酒25ml。","加清水150ml，盖上锅盖转小火焖12-15分钟，至鸡肉软烂、汤汁基本收浓、辣椒酱裹满鸡块。","开盖转大火收汁，边收边翻动让辣椒酱均匀挂在鸡块上，汤汁浓稠发亮时下青蒜苗段，翻炒十几秒出锅。"],"key": "糍粑辣椒是贵州辣子鸡的命门：干辣椒洗净去蒂后用清水泡透吸足水，连同仔姜、蒜瓣放入擂钵舂成松散膏状（形似糍粑），炒时才会出黏糯的红油汁；用普通干辣椒碎炒出来是川式干辣子鸡，味道完全不同。","tip": "糍粑辣椒也可以自制：干辣椒去蒂洗净后用开水烫5分钟至吸饱水，捞出晾凉连姜蒜一起舂碎，装坛密封发酵两周风味更足；怕辣可把辣椒减到80g并加一勺甜酒酿提鲜。"},"酸汤白菜": {"time": "30分钟","level": "简单","servings": "3人份","ing": [{"n": "大白菜（或莲花白）","q": "500g","a": "减到300g份量少；加到800g需延长煮制时间，否则白菜不烂"},{"n": "红酸汤","q": "300ml","a": "减到150ml酸味不足；加到500ml酸味刺口、盖住白菜的清甜"},{"n": "黄豆芽","q": "80g","a": "减到30g汤不鲜；加到150g会抢掉白菜的甜"},{"n": "嫩南瓜","q": "150g","a": "减到60g汤里少了那一层清甜；加到300g会盖过白菜"},{"n": "姜片、蒜瓣","q": "姜15g、蒜15g","a": "姜减到5g去腥不足；蒜加到30g发苦"},{"n": "木姜子","q": "2g","a": "减到0.5g清凉香气出不来；加到6g有明显药味"},{"n": "小青椒（拍破）","q": "2个","a": "减到1个辣度不足；加到6个辣得盖住酸香"},{"n": "盐、味精","q": "盐3g、味精2g","a": "盐减到1g汤味偏淡；加到8g会过咸、压住发酵香"},{"n": "糊辣椒（蘸水用）","q": "25g","a": "减到10g没有糊香；加到50g会焦苦"},{"n": "葱花、香菜末","q": "各15g","a": "香菜减到5g点缀色不足；加到40g草腥味重"}],"steps": ["白菜洗净，去掉老叶，用手撕成大片；嫩南瓜去皮切小块，黄豆芽洗净沥干。","锅烧热下菜籽油，中火下姜片和蒜瓣爆香，倒入红酸汤300ml，加清水至600ml，大火烧开后转小火熬3分钟，让酸香完全煮透。","放入拍破的小青椒和木姜子煮1分钟，让青椒的生辣被酸汤激化。","下黄豆芽煮2分钟，再下嫩南瓜块煮3分钟至能用筷子轻松插透。","最后下白菜，转中火煮5-8分钟至白菜软而不烂、汤色清亮发红，关火调入盐和味精。","撒葱花香菜，另配一碗糊辣椒蘸水（糊辣椒加盐、蒜泥、葱花，用一勺酸汤冲开）同吃。"],"key": "素酸汤切忌放油——油会挂壁破坏酸汤的清爽口感，酸汤菜必须清汤寡水才叫'素'；白菜用手撕不用刀切，撕开的断面更易入味。","tip": "凉了更好吃，夏日当配菜或当饮品都行；不习惯酸味的人可用白酸汤（米汤发酵）替换红酸汤，或把酸汤减半、再加几块番茄补回果甜。"},"素瓜豆": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "嫩南瓜（小青南瓜）","q": "400g","a": "减到200g汤味清甜不足；加到700g需延长煮制时间，否则南瓜不化"},{"n": "棒豆（四季豆）","q": "250g","a": "减到120g份量少；加到400g豆香会盖过南瓜的甜"},{"n": "嫩玉米段（可选）","q": "1根约150g","a": "减到半根则汤更清爽；加到2根会抢掉南瓜的清甜"},{"n": "清水（山泉水最佳）","q": "1500ml","a": "减到1000ml需提前加水；加到2000ml汤味被稀释"},{"n": "糊辣椒（蘸水）","q": "30g","a": "减到10g只剩辣没有焦香；加到50g会苦焦"},{"n": "蒜泥、葱花","q": "蒜泥15g、葱花15g","a": "蒜泥减到6g蒜香弱；加到30g发苦。葱花减到5g香气不足；加到40g抢味"},{"n": "花椒面、味精","q": "花椒面2g、味精2g","a": "花椒面减到0.5g麻味出不来；加到6g麻得发木。味精减到1g鲜味不足；加到5g会有化学味"},{"n": "酱油、香醋","q": "酱油15ml、香醋8ml","a": "酱油减到5ml颜色淡；加到30ml会盖掉瓜豆的清甜。香醋减到2ml酸头不够；加到20ml酸味盖住原味"}],"steps": ["嫩南瓜洗净去蒂，用手拍裂、掰成3-4cm的不规则块——贵州讲究'南瓜要砸、豆子要掰，不可见铁'，不用刀切，砸开的断面能更多释放糖分。","棒豆撕去两端老筋，用手掐成3cm长段，保留豆荚的青草香。","锅中加清水1500ml烧开，先下棒豆大火煮3分钟（豆比瓜难熟，必须先下），再下南瓜块。","全程开盖大火煮，保持颜色翠绿、汤色清亮；加盖煮会让菜发黄。若喜欢更浓郁的汤色，可冷水下锅一并发煮，煮出来偏黄但口感甜脆。","继续大火煮6-8分钟，至南瓜能用筷子轻松戳透、四季豆彻底熟透无生豆味（四季豆必须熟透，否则有毒）。关火后不加盖、放凉或冰镇。","另调蘸水：碗中放糊辣椒30g、蒜泥、葱花、花椒面、味精，淋酱油和几滴醋，用煮瓜豆的原汤或烧开的素汤冲开拌匀。","瓜豆捞出装碗，蘸水另上；吃法是夹一筷瓜豆往蘸水里一滚再入口。"],"key": "整道菜不放油、不放盐——放了油盐就不配叫'素瓜豆'，味道全靠食材本身清甜加一碟糊辣椒蘸水；煮时必须开盖大火，否则瓜豆发黄、失去'省汤'的清鲜。","tip": "最解暑的吃法是煮好后放冰箱冰镇，凉了清甜更突出；蘸水除了糊辣椒，还可用烧青椒（薄皮青椒加小番茄在炭火上烧透、去黑皮剁碎，加蒜泥葱花盐）配。"},"豆豉火锅": {"time": "1.5小时","level": "稍难","servings": "4-5人份","ing": [{"n": "干豆豉（或水豆豉）","q": "180g","a": "减到80g酱香不足、成了普通辣汤；加到250g会咸得发苦、抢掉所有配菜的味道"},{"n": "糍粑辣椒","q": "120g","a": "减到60g辣味不够；加到200g会糊锅发苦"},{"n": "带皮五花肉","q": "400g","a": "减到200g汤中肉香不足；加到600g需多煸5分钟出油"},{"n": "熟菜籽油","q": "80ml","a": "减到40ml豆豉煸不出香；加到150ml锅底过腻"},{"n": "姜、蒜、花椒","q": "姜20g、蒜1整头30g、花椒10g","a": "姜减到8g去腥弱；蒜加到60g发苦、抢掉豆豉香。花椒减到4g麻香弱；加到20g麻得盖住发酵香"},{"n": "豆瓣酱、冰糖、白酒","q": "豆瓣酱30g、冰糖10g、白酒15ml","a": "豆瓣酱减到10g酱色不足；加到60g会盖过豆豉本味。冰糖减到3g提鲜弱；加到30g会有明显甜味"},{"n": "高汤或清水","q": "1500ml","a": "减到800ml要边吃边加；加到2500ml味道被冲淡"},{"n": "配菜（土豆、豆腐、豆芽、苕粉、青菜）","q": "土豆2个300g、豆腐250g、豆芽100g、苕粉100g、青菜200g","a": "土豆减到1个不够吸味；豆芽加到200g会抢汤味"},{"n": "糊辣椒蘸水（折耳根、蒜末、香菜、腐乳）","q": "糊辣椒30g、折耳根50g、蒜末15g、香菜20g、腐乳1块","a": "腐乳减到半块则醇厚感偏弱；加到3块会太咸。糊辣椒减到15g焦香不足；加到50g会发苦"}],"steps": ["干豆豉用少量温水泡5分钟至微微回软，沥干后切碎；五花肉切薄片，土豆去皮切厚片，豆腐切块。","热锅下熟菜籽油，中小火煸五花肉片3分钟，逼出晶亮的猪油至肉片微黄焦脆，捞出备用，油留在锅底。","底油中小火下姜蒜末和花椒炸香，炸到香料微焦黄后捞出料渣。","锅中放一小块冰糖小火炒到融化呈浅焦糖色，下豆瓣酱翻炒1分钟炒出红油。","倒入糍粑辣椒，全程中小火慢炒5分钟，不停翻炒炒干水汽、逼出辣香，绝不能糊锅。","下豆豉碎转最小火持续翻炒8-10分钟，炒到豆豉油脂析出、整体油润发亮、豆香扑鼻——这一步是豆豉火锅香浓的核心。","沿锅边淋入白酒，翻炒十几秒让酒精挥发；倒入高汤或清水，大火烧开转中小火熬10分钟让香味融合，调入盐和生抽。","把土豆、豆腐、豆芽、苕粉下锅煮熟，再下青菜；另备糊辣椒蘸水，舀一勺滚烫原汤冲开蘸水后蘸食，最后把汤汁浇在米饭上拌着吃。"],"key": "豆豉必须最小火慢炒8-10分钟把豆香逼出来，绝不能大火，一炒就发苦整锅报废；糍粑辣椒同样要中小火炒出红油，豆豉和辣椒的香气是这锅汤的全部灵魂。","tip": "干豆豉用水豆豉按1:2配合最佳；豆豉自带咸香，加盐前务必先尝汤底。做荤素搭配时先下耐煮的五花肉、酥肉、土豆，再下豆制品，最后放绿叶菜。"},"油渣炒白菜": {"time": "20分钟","level": "简单","servings": "3人份","ing": [{"n": "大白菜","q": "500g","a": "减到300g份量少；加到800g需分锅炒，否则出水变软烂"},{"n": "猪油渣","q": "120g","a": "减到60g香味不足；加到200g会腻得吃不下饭"},{"n": "猪油（炼出的油或另备）","q": "30g","a": "减到10ml白菜会粘锅；加到80ml整菜油腻"},{"n": "干辣椒","q": "3个","a": "减到1个香而不辣；加到6个辣味盖住猪油香"},{"n": "姜末","q": "10g","a": "减到4g去腥不足；加到25g姜味太冲"},{"n": "蒜末","q": "15g","a": "减到6g蒜香弱；加到30g发苦"},{"n": "青蒜苗","q": "2根","a": "减到1根香气弱；加到5根会抢味"},{"n": "生抽","q": "12ml","a": "减到5ml味淡；加到25ml会过咸"},{"n": "白糖","q": "3g","a": "减到1g提鲜不明显；加到12g会有明显甜味"},{"n": "盐、白胡椒粉、料酒","q": "盐3g、白胡椒粉1g、料酒10ml","a": "盐减到1g会偏淡；料酒加到25ml酒味残留明显"}],"steps": ["白菜去掉老叶，菜帮和菜叶分开——菜帮竖着切成1.5cm宽的斜段（这样炒出来菜帮不软塌），菜叶撕成大块，洗净后沥干水分。","锅烧热下猪油30g，中火下姜末、蒜末和干辣椒段炒香。","下猪油渣，中火煸炒1-2分钟，把油渣本身的油脂煸出来，煸到表面微微焦黄发香。","先下白菜帮，转大火快速翻炒1-2分钟，炒到菜帮微微变软、呈半透明状。","下白菜叶继续大火翻炒1分钟至菜叶变软、微微出水。","沿锅边淋入料酒10ml，加生抽12ml、白糖3g、盐3g和白胡椒粉，大火快速翻匀10秒立刻出锅，撒青蒜苗段。"],"key": "油渣不能炒得太干，留在一点油脂炒出来才香；全程大火快炒不能加水，一加水白菜就出水软烂、失去'脆甜'的口感。","tip": "炼猪油渣的窍门是凉油下锅小火慢熬，熬出的油白净；熬油渣时倒半杯水同熬不易糊锅。剩下的猪油留着炒青菜、烤豆腐都是贵州人家的做法。"},"腊肉炒蒜苔": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "农家腊肉","q": "250g","a": "减到150g份量偏少；加到400g会过咸、盖住蒜苔的脆甜"},{"n": "蒜苔","q": "300g","a": "减到150g份量少；加到500g需要先焯水，否则炒不熟会发涩"},{"n": "干辣椒","q": "4个","a": "减到2个香而不辣；加到8个只剩辣味没有腊香"},{"n": "姜","q": "10g","a": "减到4g去腥不足；加到25g姜味太冲"},{"n": "蒜片","q": "3瓣","a": "减到1瓣蒜香弱；加到6瓣发苦"},{"n": "青蒜苗","q": "1根","a": "减到半根则蒜香略欠；加到4根会抢味"},{"n": "菜籽油","q": "25ml","a": "减到10ml腊肉煸不出油；加到50ml整菜油腻"},{"n": "生抽","q": "10ml","a": "减到4ml味淡；加到25ml过咸"},{"n": "白糖","q": "2g","a": "减到1g提鲜不明显；加到10g会有明显甜味"},{"n": "盐","q": "2g","a": "腊肉自带咸味，通常可不加；减到1g略欠味；加到6g会过咸"}],"steps": ["腊肉用温水洗净表面浮灰，上锅蒸15分钟至皮软，取出晾凉切成薄片；蒜苔掐去老头撕掉老筋，斜切成段，粗蒜苔可先焯水30秒。","锅烧热下菜籽油，中火下腊肉片煸炒2分钟，逼出油脂至肥肉透明、边缘微卷。","下姜片、蒜片和干辣椒段，小火炒1分钟至辣椒微焦、蒜香出来。","转大火下蒜苔，快速翻炒2分钟，炒到蒜苔颜色由深转亮、梗部微软但仍咬得出脆感。","倒回腊肉片，淋生抽10ml、撒白糖2g，大火翻炒十几秒让蒜苔均匀裹上腊肉的油香，出锅前撒青蒜苗段。"],"key": "蒜苔要选粗细均匀、掐得出水的嫩蒜苔，火候宁短勿长，炒过会发黄发软失去'脆'；腊肉先煸出油，蒜苔才能被腊香裹住而不是靠调料。","tip": "腊肉偏咸时先温水泡30分钟去盐；如果用新鲜蒜苔（不是蒜苔而是蒜苗），要在起锅前放、炒久了会黏。"},"腊肉炒洋芋": {"time": "30分钟","level": "简单","servings": "3人份","ing": [{"n": "农家腊肉","q": "250g","a": "减到150g份量少；加到400g会过咸、抢掉洋芋的粉糯"},{"n": "洋芋（土豆）","q": "400g（约2个）","a": "减到250g份量少；加到600g需先焯水，否则外熟内生"},{"n": "干辣椒","q": "4个","a": "减到2个香而不辣；加到8个辣味盖过腊香"},{"n": "姜","q": "10g","a": "减到4g去腥不足；加到25g姜味太冲"},{"n": "蒜片","q": "3瓣","a": "减到1瓣蒜香弱；加到6瓣发苦"},{"n": "青蒜苗","q": "2根","a": "减到1根香气弱；加到5根会抢味"},{"n": "菜籽油","q": "30ml","a": "减到12ml洋芋会粘锅；加到60ml会腻"},{"n": "生抽","q": "12ml","a": "减到5ml味淡；加到30ml会过咸"},{"n": "糊辣椒","q": "15g","a": "减到5g缺了糊香；加到30g会焦苦、抢走腊味"},{"n": "盐、白糖","q": "盐3g、白糖2g","a": "盐减到1g略淡；白糖加到10g会有明显甜味"}],"steps": ["洋芋去皮切成滚刀块或厚片，泡在清水里洗去表面淀粉（不泡会氧化发黑、炒时易粘锅），沥干；腊肉蒸15分钟后晾凉切薄片。","锅烧热下菜籽油，中火下腊肉片煸炒2分钟至肥肉透明、边缘微卷，把多余的油留在锅里。","下姜片、蒜片、干辣椒段小火炒1分钟至香味出来。","转中大火下洋芋块，快速翻炒3分钟，让每块洋芋均匀裹上油，此时表面会结出一层薄皮。","加生抽12ml、白糖2g、盐3g，沿锅边淋入小半碗清水（约60ml），盖上锅盖转中小火焖5-8分钟，中途翻动一次，让洋芋熟透。","开盖转大火收汁，撒青蒜苗段翻炒十几秒，再撒一勺糊辣椒提香出锅。"],"key": "洋芋切完必须泡水洗去淀粉，否则一炒就粘成一坨；先炒出皮再焖水，是洋芋外皮焦香、内里粉糯的关键。","tip": "这道菜也常见于街边炸洋芋摊的做法——洋芋切块先炸至金黄再回锅与腊肉同炒，更香更干；想省事先蒸熟再炒也行，风味略淡。"},"血豆腐炒蒜苗": {"time": "30分钟","level": "简单","servings": "2-3人份","ing": [{"n": "熏制血豆腐","q": "250g","a": "减到150g份量少；加到400g需延长蒸制时间"},{"n": "蒜苗","q": "200g","a": "减到100g份量少；加到350g会抢掉血豆腐的烟熏香"},{"n": "干辣椒","q": "3个","a": "减到1个香而不辣；加到6个辣味盖过烟香"},{"n": "姜","q": "10g","a": "减到4g去腥不足；加到25g姜味太冲"},{"n": "蒜片","q": "2瓣","a": "减到1瓣蒜香弱；加到5瓣发苦"},{"n": "花椒","q": "8粒","a": "减到3粒麻香弱；加到18粒麻得发木"},{"n": "菜籽油","q": "25ml","a": "减到10ml血豆腐煸不出香；加到50ml会腻"},{"n": "生抽","q": "10ml","a": "减到4ml味淡；加到25ml会过咸、盖住血豆腐本味"},{"n": "白糖","q": "3g","a": "减到1g提鲜弱；加到12g会有明显甜味"},{"n": "盐","q": "2g","a": "血豆腐本身咸，通常可不加；减到1g略欠味；加到6g会过咸"}],"steps": ["血豆腐用温水把表面的烟灰洗净，上锅大火蒸40-60分钟（蒸到内部熟透、外皮微软不硬），取出晾凉切成1.5cm厚片。","蒜苗斜切成段，蒜白和蒜叶分开放；姜切片，蒜切片，干辣椒剪段。","锅烧热下菜籽油，中火下血豆腐片煸炒2-3分钟，煸到表面微微出油、边缘微微焦黄，逼出多余的油脂。","下姜片、蒜片、花椒和干辣椒段，小火炒1分钟至香味窜出、辣椒微焦。","下蒜苗白转中大火翻炒1分钟至断生，再下蒜苗叶快速翻炒十几秒。","倒回血豆腐片，淋生抽10ml、撒白糖3g翻匀，大火炒十几秒出锅。"],"key": "血豆腐必须先蒸透再炒——生的血豆腐豆腐渣没黏合，炒时会散；炒的时候只煸不炒碎，全程用铲背推、别用铲子翻搅，才片片完整。","tip": "血豆腐也可切片直接蒸熟蘸糊辣椒水吃；切成丁还能用来做哨子，煮粉煮面时加一勺最香。这道菜贵州人爱配酸汤或素瓜豆汤一起吃。"},"炸酥肉": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "猪五花肉","q": "400g","a": "选肥瘦相间三层的，太瘦炸出来发柴；换成梅花肉要减到350g并把油温降到五成热，否则出油过多"},{"n": "红薯粉","q": "100g","a": "贵州本地多用红薯粉或黄豆粉，减到50g则外壳偏薄不够酥脆；加到150g外壳更厚更硬但口感发干"},{"n": "中筋面粉","q": "40g","a": "面粉提供筋道，减到20g则粉浆易散、挂不住肉；加到80g外壳厚重、吸油多，不建议"},{"n": "鸡蛋","q": "1个（约50g）","a": "换成2个则蛋香更重、壳更硬但成本高；不用鸡蛋则外壳发脆度下降，需多撒5g粉"},{"n": "清水","q": "90ml","a": "调成能缓慢流动的稠糊，加到130ml变稀挂不住肉片；减到60ml则结块无法搅匀"},{"n": "盐、白胡椒粉","q": "盐3g、白胡椒粉1g","a": "盐加到5g则腌好后肉本身偏咸、复炸后更咸；减到2g则腥味压不住"},{"n": "料酒","q": "10ml","a": "加到20ml肉味发酸、抢了肉香；减到5ml则料酒味残留明显"},{"n": "菜籽油","q": "1200ml（实耗约250ml）","a": "油量不足时下锅会粘连、无法翻动；用500ml需分3-4锅炸，不能一次下太多"},{"n": "蘸水调料","q": "蒜末20g、生抽15ml、醋10ml、辣椒面5g、凉白开30ml","a": "辣椒面加到10g更冲、适合重口味；减到2g只剩咸味。蒜末加到30g辛味更明显但会盖住肉香"}],"steps": ["猪五花肉切成2mm厚、3cm见方的片，冷水浸泡10分钟去血水，捞出用厨房纸彻底吸干表面水分。","肉片加盐3g、白胡椒粉1g、料酒10ml抓匀，腌制15分钟，腌到肉色发白、手指捏下去回弹明显变慢即可。","红薯粉100g、中筋面粉40g、鸡蛋1个、清水90ml调成稠糊，搅到无颗粒后静置10分钟让粉吸水起劲，提起筷子糊能缓慢成线流下。","腌好的肉片逐片下入面糊抓匀，每片挂薄薄一层糊、不滴落即可，多余的糊用手抹掉。","菜籽油烧至六成热（180℃，筷子插入周围冒小泡），下肉片，中火炸2分钟至表面定型起泡、浮在油面，捞出控油静置3分钟。","油温升到八成热（210℃，油面冒浓烟），复炸40秒至外壳金黄酥脆、掰开断面有层次，随即捞出控油。","蒜末、生抽、醋、辣椒面、凉白开调成蘸水，炸酥肉蘸食或整碗拌匀。"],"key": "面糊必须红薯粉（或豆粉）配面粉混合，单用面粉炸出来软塌不脆；复炸是酥脆的关键，第一遍只负责定型定型，第二遍高温才起酥。","tip": "一次下锅不超过8片，酥肉重叠会互相压软；下锅前务必擦干肉片水分，否则油会剧烈溅起。新手怕油溅可先挂糊后再抖掉多余粉。"},"烧椒皮蛋": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "青尖椒（皱皮椒）","q": "250g","a": "选皮厚肉细的皱皮椒，薄皮椒烧完没肉只剩皮；加到350g需配比增一份料汁"},{"n": "松花皮蛋","q": "3个","a": "3个约450g刚好一盘；减到2个则量偏少、拌一筷子就没了，加到4个要同步加10g蒜末"},{"n": "蒜末","q": "20g（约4瓣）","a": "加到30g蒜味更冲；减到10g则烧椒的焦香压不住"},{"n": "姜末","q": "10g","a": "加到15g去腥更明显但抢味；可省略不减"},{"n": "生抽","q": "20ml","a": "加到30ml咸味过重；减到12ml则皮蛋的碱味出不来"},{"n": "醋","q": "15ml","a": "加到25ml酸得更开胃，适合重口；减到8ml则焦香闷在嘴里"},{"n": "盐","q": "2g","a": "烧椒本身带点咸，加到4g会齁；基本不减"},{"n": "白糖","q": "3g","a": "加到6g可中和焦苦味；减到1g则味偏苦"},{"n": "辣椒面或熟油辣子","q": "10g","a": "加到20g辣度明显上一个台阶；减到3g基本是烧椒本味"},{"n": "香油","q": "8ml","a": "加到15ml更香滑；减到3ml则香气一般"}],"steps": ["青椒洗净后彻底擦干，锅烧热后不放油，青椒下锅中火干烧2-3分钟，不断翻动压压，烤到表皮出现均匀焦黑斑、闻到明显焦香。","关火，锅中加200ml清水烧开，把烧好的青椒放进沸水里焖2分钟，让表皮泡软方便剥除。","青椒捞出沥水，逐个撕去烧焦的皮、去掉蒂和籽，用手撕成宽条，摆入盘中。","皮蛋剥壳，用刀在切口沾水切成6瓣，摆在青椒条上。","蒜末、姜末加生抽、醋、盐、白糖、辣椒面、香油、30ml凉白开调匀成料汁。","料汁淋在皮蛋上，吃前从中间拌开，让每块皮蛋都吸到味。"],"key": "青椒必须干烧出焦斑而不是煮软，焦香是这道菜的全部灵魂；皮蛋要整瓣切、块不能太小，太碎会挂不住汁。","tip": "没耐心干烧可以用喷枪，或200℃烤箱上下火烤8分钟，中途翻面；皮脆的品种烧出来更好吃。"},"泡酸萝卜": {"time": "30分钟准备，3-5天发酵","level": "稍难","servings": "5人份（约2L一坛）","ing": [{"n": "白萝卜","q": "1.5kg","a": "选实心水分少的，糠心萝卜泡出来发柴；加到2kg需按比例增盐20g并保证汤汁能完全淹没"},{"n": "盐","q": "60g","a": "加到90g咸度足、发酵更稳；减到40g则容易发软长霉"},{"n": "红糖","q": "80g","a": "加到120g酸中带甜更柔和；减到40g则只有酸和咸，颜色也发暗"},{"n": "冰糖","q": "20g","a": "与红糖叠加用，加到40g更甜；可与红糖二选一不减量"},{"n": "白酒","q": "50ml","a": "加到80ml抑菌更好、发酵味更冲；减到20ml在夏天容易起白霉"},{"n": "老坛老水（老卤水）","q": "200ml","a": "这是发酵出味的关键，减到50ml则只有单纯酸度、没有醇香；没有可用现成的坛子盐卤水"},{"n": "凉白开（放凉）","q": "800ml","a": "必须凉白开，生水会带杂菌；减到500ml则萝卜不能全浸没"},{"n": "蒜瓣、老姜","q": "蒜10瓣、姜50g","a": "姜加到80g辛味更冲；蒜减到5瓣则发酵香弱"},{"n": "小米辣、花椒","q": "小米辣6个、花椒10粒","a": "小米辣加到10个泡出后更辣；怕辣可减到3个"}],"steps": ["白萝卜削皮切成3cm见方的滚刀块，装竹匾摊开晾晒2小时，晒到表面发蔫起微皱，这样泡出来更脆更入味。","玻璃坛用开水烫洗后倒扣晾干，坛内必须无生水无油污。","坛底先放盐60g、红糖80g、冰糖20g、蒜瓣、姜片、小米辣、花椒。","倒入老坛老水200ml，再加凉白开800ml，把糖盐搅到完全化开，加入白酒50ml搅匀。","萝卜块码入坛中并压实，上面用小石头或倒扣的碗压住，确保全部浸在坛汤里、不露出液面。","坛口加水密封，放阴凉避光处发酵，室温20-25℃约3天可开坛，冬天低温则需7-10天。","开坛先尝一根：酸香足、口感仍脆即可开吃；吃不完继续封坛，坛汤越陈越香，第二坛可只用老汤再兑新水。"],"key": "萝卜必须先晒过再泡、必须完全浸没在坛汤中；沾了生水或浮在液面以上会发软、起白霉、整坛报废。","tip": "想快点吃到可用40℃温水泡坛、坛口滴几滴白酒抑菌，但风味会略冲。泡好的萝卜炒肉末、蒸排骨、泡酸汤都很出彩。"},"酸豆角炒肉末": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "酸豆角","q": "250g","a": "自己泡的酸度差别大，泡得久酸味重的减到200g并把糖加到5g；不够酸的加到300g并配2勺辣椒"},{"n": "猪肉末","q": "200g","a": "用前腿肉或五花肉末出油香，减到150g则不够下饭；换牛肉末要减油到20ml"},{"n": "干辣椒","q": "6个（剪成2cm段）","a": "加到10个辣度明显上升；减到3个则香气不足"},{"n": "蒜末","q": "15g","a": "加到25g蒜香更浓；减到8g衬不出豆角的酸"},{"n": "姜末","q": "8g","a": "加到15g去肉腥更好；减到5g腥味略重，但豆角的酸味能压住"},{"n": "生抽","q": "15ml","a": "酸豆角本身很咸，加到25ml必齁；减到8ml则颜色发淡"},{"n": "老抽","q": "5ml","a": "加到10ml上色过深发黑；减到2ml仅能看出酱色"},{"n": "白糖","q": "3g","a": "加到6g能把酸豆角的酸压得柔和；减到1g则酸味单薄"},{"n": "菜籽油","q": "30ml","a": "加到45ml更润口；减到15ml则肉末容易粘锅"},{"n": "葱花","q": "10g","a": "加到20g更香；减到5g则少一分清香"}],"steps": ["酸豆角洗净切成1cm长段，用刀在每段侧面划开一半，让汤汁和味道进得去。","锅烧热下菜籽油20ml，中火下肉末摊平煎炒2-3分钟，炒到肉末发干、颜色由粉转金黄、锅底析出一层薄油。","把肉末推到锅边，利用空出来的油下干辣椒段和姜末，中火爆香30秒。","转大火下酸豆角段翻炒2分钟，炒到豆角表皮起皱发亮、酸香被热激出来。","加蒜末继续炒1分钟，烹入生抽、老抽、白糖翻匀。","沿锅边淋10ml清水，中火焖1分钟收汁，汤汁略稠能挂住豆角，撒葱花出锅。"],"key": "酸豆角本身带咸带酸，盐一定要最后尝过再决定放不放；肉末要先炒到发干出油再下酸豆角，否则会炒成一锅酸汤。","tip": "拌粉、拌面、盖稀饭都合适；酸豆角自家泡的咸度差异大，第一次先少放酱油。"},"冲菜": {"time": "20分钟","level": "简单","servings": "3人份","ing": [{"n": "皱皮青菜（冲菜菜）","q": "400g","a": "必须用本地皱皮芥菜，普通小白菜没有那股冲味；加到600g需把调料按比例加到1.5倍"},{"n": "糍粑辣椒（开水烫过剁碎的辣椒酱）","q": "40g","a": "改用干辣椒面要减到25g并加5ml水调开，不然冲劲出不来；加到60g则辣到只剩辣味"},{"n": "干辣椒面","q": "30g","a": "与糍粑辣椒二选一；单用干辣椒面香气偏燥，要补5g芝麻油"},{"n": "蒜末","q": "20g","a": "加到30g蒜味更冲；减到10g则冲味太单薄"},{"n": "姜末","q": "5g","a": "加到10g去生青气；减到3g也够用，不加也不影响"},{"n": "盐","q": "4g","a": "加到6g更入味；减到2g则青菜寡淡无味"},{"n": "白糖","q": "2g","a": "加到5g能平衡辣味；减到1g基本尝不出甜"},{"n": "生抽","q": "15ml","a": "加到25ml咸香更足；减到8ml则颜色太浅"},{"n": "醋","q": "15ml","a": "加到25ml更开胃；减到8ml辣味更生猛"},{"n": "香油","q": "10ml","a": "加到20ml更香滑；减到5ml则少了那层回味"}],"steps": ["青菜择洗干净，梗和叶分开：菜梗斜切成薄片，叶子撕成大块。","锅中水加1勺盐、几滴油烧开，先下菜梗烫30秒，再下叶子烫20秒，捞出后立刻投入冰凉开水激一下。","沥干水分摊在漏盆或竹匾上，摊开吹风5分钟，让表面水分收干（带水拌会出汤）。","蒜末、姜末、辣椒面、生抽、醋、盐、白糖、香油调成料汁。","料汁倒入青菜中拌匀，辣椒面要均匀挂在每片菜叶上。","拌入掐成段的折耳根，再快速拌一次即可上桌。"],"key": "“冲”的那股辣上头劲，来自烫熟后还没拌调料的那一瞬间，所以烫好必须马上过凉水、马上拌辣；提前放盐或久放会把这股冲味放跑。","tip": "折耳根可加可不加，加了冲味更足。普通小白菜只能算凉拌青菜，不要用来替代皱皮青菜。"},"青椒炒肉": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "猪二刀肉或里脊","q": "300g","a": "选肥瘦相间的二刀肉最香，全瘦的炒出来发柴；用里脊要加10ml水淀粉抓匀"},{"n": "皱皮青椒（贵州本地椒）","q": "250g","a": "贵州做法辣椒要比肉多，加到350g更下饭；减到150g就失了本地味"},{"n": "蒜末","q": "15g","a": "加到25g蒜香突出；减到8g则被辣椒味盖住"},{"n": "姜丝","q": "5g","a": "加到10g去腥；减到3g影响不大"},{"n": "干辣椒","q": "4个","a": "加到8个增加糊香层次；减到2个则只有青椒的鲜辣"},{"n": "生抽","q": "15ml","a": "加到25ml咸度上升；减到10ml肉味不足"},{"n": "蚝油","q": "10g","a": "加到20g更鲜；减到5g鲜度不够，可用少许糖替代"},{"n": "白糖","q": "2g","a": "加到5g能中和青椒的生辣；减到1g则辣得发苦"},{"n": "菜籽油","q": "25ml","a": "加到40ml更亮更香；减到15ml容易粘锅"},{"n": "料酒","q": "10ml","a": "腌肉用；加到20ml肉发酸，减到5ml酒味残留"}],"steps": ["猪肉逆着纹路切薄片，加生抽、料酒抓匀腌10分钟，腌到肉片表面发黏、颜色变深。","青椒去籽切菱形片，蒜切末，姜切细丝，干辣椒剪段。","锅烧到冒烟，下菜籽油25ml润锅再倒出多余油（贵州做法油亮不腻）。","下腌好的肉片大火快炒1分钟，炒到肉片全部变色、表面发亮，拨到锅边。","下青椒片转中大火炒3分钟，炒到青椒表皮起虎皮、边缘微软塌下。","加蒜末、姜丝、干辣椒爆香30秒，加蚝油、白糖、盐，大火翻匀30秒立即出锅。"],"key": "贵州青椒炒肉辣椒要下得比肉早、量要足，青椒必须炒出虎皮才够香；肉片逆纹切才嫩，顺纹切必柴。","tip": "觉得香度不够可加1勺糊辣椒或1勺糍粑辣椒；如果青椒炒到发蔫塌软，说明火太小、炒久了会发黄发苦。"},"肉末豇豆": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "酸豇豆","q": "250g","a": "泡得久酸味重的减到200g并加糖5g；发酵不足酸味淡的加到300g并多放5g盐"},{"n": "猪肉末","q": "200g","a": "前腿肉末或五花肉末最佳，减到150g则香气不足；用腊肉末要减生抽到5ml并减油到15ml"},{"n": "泡椒（剁碎）","q": "30g（约4个）","a": "加到50g泡椒味更足；减到15g酸豇豆的酸就单薄了"},{"n": "蒜末","q": "15g","a": "加到25g蒜味更浓；减到8g衬不出豇豆的酸"},{"n": "姜末","q": "5g","a": "加到10g去腥；减到3g也够"},{"n": "干辣椒","q": "4个","a": "加到8个辣度上一个台阶；减到2个则欠香"},{"n": "花椒","q": "10粒","a": "加到20粒麻香更明显；减到5粒基本尝不出麻"},{"n": "生抽","q": "15ml","a": "加到25ml偏咸；减到10ml颜色和咸味都偏淡"},{"n": "白糖","q": "3g","a": "加到6g酸甜更平衡；减到1g则酸味单薄"},{"n": "菜籽油","q": "30ml","a": "加到45ml肉末不粘锅；减到15ml易结块"}],"steps": ["酸豇豆洗净切成0.5cm见方的小粒（比切段更入味），泡椒剁成碎末。","热锅凉油下肉末，中火摊炒3分钟，炒到水分收干、肉末发黄、锅底结出一层薄油。","下花椒、干辣椒、泡椒碎、姜末，中火炒香1分钟。","转大火下酸豇豆粒翻炒3分钟，炒到豇豆粒吸足油、颜色转深、酸味被激发出来。","加蒜末、生抽、白糖大火翻匀1分钟，汤汁收干即可出锅。"],"key": "酸豇豆要剁成小粒而不是切段，小粒才能在短时间内吸足肉末的油和味；全程大火快炒，久了会发黄发软。","tip": "配米饭一顿能吃两碗，拌粉拌面也好吃；用不完的酸豇豆分装冷冻，保存半年没问题。"},"洋芋饭": {"time": "50分钟","level": "中等","servings": "4人份","ing": [{"n": "洋芋","q": "2个（约600g）","a": "选粉糯黄心的，切1.5cm滚刀块；加到800g需把水增到800ml、焖煮延到30分钟"},{"n": "大米","q": "400g","a": "减到350g饭偏硬，加到450g需水增到780ml；必须提前泡20分钟才焖得透"},{"n": "猪五花肉或腊肉","q": "150g","a": "腊肉切小丁更香，煸出油后饭更香；用五花肉丁则减盐并加10ml老抽上色"},{"n": "干辣椒","q": "5个","a": "加到8个辣味更足；减到3个则香气不足"},{"n": "糟辣椒或辣酱","q": "30g","a": "加到50g饭色更红、辣味更足；减到15g则只见辣不见香"},{"n": "蒜末","q": "15g","a": "加到25g蒜香更浓；减到8g衬不出糟辣椒的味"},{"n": "姜末","q": "8g","a": "加到15g去肉腥；减到5g也够"},{"n": "菜籽油","q": "30ml（另留15ml淋锅巴）","a": "炒菜部分加到45ml饭更润；淋锅巴的油减到8ml则锅巴不够酥"},{"n": "盐","q": "3g","a": "用腊肉时减到1g；加到5g则咸"},{"n": "清水","q": "700ml","a": "这是硬指标，比米面高出1cm；加到800ml饭偏软黏，减到600ml则夹生"}],"steps": ["大米淘净后用清水浸泡20分钟，沥干备用。","洋芋削皮切成1.5cm滚刀块，泡水冲去表面淀粉后沥干。","锅烧热下菜籽油30ml，先把五花肉丁或腊肉片煸出油，煸到肉丁焦黄、锅底积起一层油。","转小火下姜末、蒜末、干辣椒、糟辣椒炒1分钟，炒出红油和香气。","转中大火下洋芋块翻炒3分钟，炒到洋芋表面微微发黄、结起一层皮。","把洋芋和肉平铺在锅底，米平铺在表面，倒入清水700ml（水面高出米面约1cm），撒盐3g。","大火煮开转小火焖25分钟，中途沿锅边淋一次清水防止糊底，直到水分吸干、米饭粒粒分明。","关火后沿锅边淋15ml菜籽油，转动锅子让油渗进锅巴底部，用铲子整块铲起锅巴，切块装盘。"],"key": "焖饭水量是硬指标（水比米高1cm）；焖好后必须沿锅边淋一圈油再铲锅巴，才有焦香酥脆的锅巴，锅巴是这道菜的灵魂。","tip": "用土锅或铸铁锅焖才有锅巴，电饭煲做不出来；洋芋块不要切太薄，否则焖完全化成泥。"},"四季豆焖饭": {"time": "50分钟","level": "中等","servings": "4人份","ing": [{"n": "四季豆","q": "400g","a": "必须撕净两边老筋；加到500g需把水增到750ml；豆角太老有筋就嚼不动"},{"n": "大米","q": "400g","a": "减到350g饭硬，加到450g需水增到780ml；淘净后泡20分钟"},{"n": "腊肉","q": "150g","a": "风干腊肉最香，减到100g则饭不够香；用五花肉丁可减到100g并加8ml老抽"},{"n": "干辣椒","q": "5个","a": "加到8个更香更辣；减到3个香气不足"},{"n": "蒜末","q": "15g","a": "加到25g蒜香更浓；减到8g则腊肉香单薄"},{"n": "姜末","q": "8g","a": "加到15g去腊肉腥味；减到5g影响不大"},{"n": "菜籽油","q": "30ml（另留20ml淋锅巴）","a": "煸肉部分减到20ml则出油少；淋锅巴的油必须足才有酥脆锅巴"},{"n": "生抽、老抽","q": "生抽20ml、老抽5ml","a": "生抽加到30ml偏咸，减到12ml颜色淡；老抽加到10ml颜色更深，减到2ml仅微上色"},{"n": "清水","q": "700ml","a": "高出米面1cm为准；加到780ml饭偏软，减到600ml会夹生"},{"n": "盐","q": "2g","a": "腊肉咸就不用加；加到4g则过咸，减到0g也不影响"}],"steps": ["大米淘净后用清水泡20分钟沥干；四季豆撕去两侧老筋，掰成5cm长段，洗净沥干。","腊肉切薄片，冷锅下锅小火煸3-4分钟，煸到腊肉边缘透亮、肥肉部分出油、锅底积油。","下干辣椒、姜末、蒜末，小火炒1分钟，烹入生抽、老抽炒匀上色。","转大火下四季豆段翻炒4分钟，炒到豆角表皮起皱、颜色由亮绿转深绿、质地微软。","关火，把四季豆和腊肉平铺在锅底，米铺在上面，加清水700ml（水高出米面约1cm），加盐2g。","大火煮开转最小火焖25分钟，中途绝不揭盖，焖到水干米熟、锅边一圈干饭焦香。","关火沿锅边淋20ml菜籽油，用铲子铲起整块锅巴，配腊肉一起吃。"],"key": "四季豆必须彻底炒到起皱变软，半生的有豆腥味且焖不透；焖饭全程小火不揭盖，否则水汽跑光饭会夹生。","tip": "没有腊肉可用五花肉丁加一点生抽；想做素版可加泡椒和泡香菇，一样香。"},"糟辣茄盒": {"time": "45分钟","level": "稍难","servings": "3-4人份","ing": [{"n": "紫皮长茄","q": "2根（约600g）","a": "选细长的紫皮茄，籽少不苦；加到800g需把肉馅增到300g、糟辣椒增到70g"},{"n": "猪肉末","q": "250g","a": "减到180g则馅薄夹不住；用牛肉末要减到200g并加5ml蚝油"},{"n": "糟辣椒","q": "60g","a": "加到90g辣味更足；减到40g则发酵香出不来"},{"n": "蒜末","q": "25g","a": "加到35g蒜味冲；减到15g衬不出糟辣椒"},{"n": "姜末","q": "8g","a": "加到15g去肉腥；减到5g也够"},{"n": "葱花","q": "15g","a": "一半拌进肉馅、一半撒面；减到8g香气减半"},{"n": "鸡蛋","q": "1个","a": "打进肉馅更滑；不用鸡蛋需把淀粉从20g增到30g"},{"n": "淀粉","q": "20g（10g拌馅、10g调芡）","a": "加到30g馅更黏更不易散；减到10g则馅会散开掉出茄盒"},{"n": "盐、生抽（调肉馅）","q": "盐3g、生抽15ml","a": "盐加到5g馅偏咸，减到2g略淡；生抽加到25ml馅色深，减到8ml馅味不足"},{"n": "菜籽油","q": "40ml","a": "煎茄盒加到60ml不粘；减到25ml容易粘锅破皮"}],"steps": ["茄子切1.5cm厚的大片，每片从中间划开但底部相连，成一个个“夹”即茄盒，挖掉部分白瓤减少涩味。","肉末250g加盐3g、生抽15ml、淀粉10g、葱花一半，顺一个方向搅到发黏上劲（约2分钟）。","茄盒内夹入肉馅，边缘抹少量淀粉水粘合，全部备好后再开火。","锅放菜籽油40ml，中火把茄盒逐个放入煎3-4分钟，煎到一面金黄、茄子变软塌，再翻面煎3分钟。","另起小锅，把糟辣椒60g、蒜末25g、姜末8g、剩余淀粉10g、20ml清水用小火炒2分钟，炒成能挂勺的稠糊，淋几滴油出香。","茄盒摆盘，浇上热糟辣糊，撒剩余葱花。"],"key": "肉馅必须顺一个方向搅到上劲才抱得住，下锅即散；茄子煎时用中火并靠自身蒸汽变软，火大外焦内生、茄子发苦。","tip": "也可改蒸制上锅蒸10分钟代替煎，口感更软更入味；素馅用泡椒末加折耳根加豆腐末也很贵州。"},"糊辣椒拌皮蛋": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "二荆条皱皮青椒","q": "250g","a": "选皮薄肉厚、蒂短的二荆条，糊香最正；加到350g要同步把蒜末增到25g"},{"n": "松花皮蛋","q": "3个","a": "3个约450g刚好一盘；减到2个则量偏少，加到4个需多备一份糊辣椒"},{"n": "蒜末","q": "20g","a": "加到30g蒜味更冲更香；减到12g则焙香压不住"},{"n": "葱花","q": "15g","a": "加到25g更香；减到8g香气弱"},{"n": "盐","q": "3g","a": "加到5g则青椒本身太咸，拌皮蛋会齁；减到2g焦香里少一分底味"},{"n": "味精","q": "1g","a": "加到2g鲜味更明显；减掉也不影响这道菜的味道"},{"n": "香油","q": "8ml","a": "加到15ml更香滑；减到3ml香气一般"},{"n": "生抽","q": "15ml","a": "加到25ml咸度偏高；减到10ml焦香闷着"},{"n": "醋","q": "10ml","a": "加到20ml酸得开胃，能压焦味；减到5ml则只有辣"},{"n": "白糖","q": "2g","a": "加到5g能中和焦苦；减到1g基本尝不出"}],"steps": ["青椒洗净彻底擦干，净锅不放油，中小火干焙5-6分钟，边焙边用手压翻动，直到青椒整体变深褐色、手捏发软塌、有明显焦香而不焦苦。","离火晾凉，剥掉烧焦的皮，去蒂去籽，撕成宽条。","烧好的青椒加盐3g、蒜末20g、生抽、醋、白糖、味精，在砧板上一起剁成糊状，保留细颗粒感，不要剁成泥。","加入香油8ml拌匀，这就是一碗糊辣椒。","皮蛋剥壳切瓣摆盘，浇上糊辣椒，撒葱花。","吃前拌匀，让皮蛋每一面都裹上糊辣椒。"],"key": "糊辣椒的核心是“焙”不是“炸”：必须干锅小火焙到焦香而不焦苦，剥皮后连皮带籽一起舂碎，才有那股“糊”味；炸出来的只有辣没有糊香。","tip": "焙的时候盖锅盖留条缝防止蹦油；做好的糊辣椒装玻璃罐冷藏可存10天，配米豆腐、豆腐脑、折耳根都好吃。"},"折耳根炒洋芋": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "洋芋","q": "2个（约400g）","a": "选粉一点的黄心洋芋，切细丝；加到600g需把油增到40ml"},{"n": "折耳根","q": "200g","a": "用带根的鲜折耳根，冲味更足；只取嫩尖可减到120g，冲味减半、更易入口"},{"n": "猪五花肉（可选）","q": "80g","a": "加到150g更油香；不用肉则把菜籽油从30ml提到40ml补上"},{"n": "蒜末","q": "15g","a": "加到25g蒜香更浓；减到8g衬不出洋芋的香"},{"n": "干辣椒","q": "4个","a": "加到8个更辣更香；减到2个辣度不足"},{"n": "糍粑辣椒或辣酱","q": "20g","a": "加到35g糊辣味更足；减到10g辣味单薄"},{"n": "盐","q": "3g","a": "加到5g偏咸；减到2g则折耳根的腥气压不住"},{"n": "白糖","q": "1g","a": "加到3g能提鲜；减到1g基本无差别"},{"n": "菜籽油","q": "30ml","a": "加到45ml不粘锅；减到20ml容易粘住洋芋丝"},{"n": "生抽","q": "10ml","a": "加到18ml咸味更足；减到5ml颜色偏淡"}],"steps": ["洋芋削皮切成细丝，清水冲洗两遍洗掉表面淀粉，再泡入冷水防氧化，捞出沥干（这是洋芋丝爽脆的关键）。","折耳根择洗干净，掐成3cm小段，嫩梗单独斜切成薄片。","热锅下五花肉片，中火煸2分钟出油，下干辣椒、蒜末、糍粑辣椒小火炒香1分钟。","转大火下洋芋丝，沿锅边淋10ml清水快速炒2分钟，炒到洋芋丝刚断生、边缘透明。","下折耳根大火翻炒1分钟，折耳根要炒出香味但不能炒蔫发软。","加盐、白糖、生抽翻匀30秒出锅。"],"key": "洋芋丝必须洗掉淀粉且不能久泡，下锅才不粘连成坨；折耳根最后下锅且只炒1分钟，多炒就烂。","tip": "折耳根梗和叶分开处理，梗先下锅30秒再下叶；怕冲味可把折耳根焯水10秒再用，但香味会减一半。"},"洋芋片炒腊肉": {"time": "30分钟","level": "简单","servings": "3人份","ing": [{"n": "洋芋","q": "3个（约600g）","a": "切1cm厚片，太厚不易煎透；加到800g需把腊肉增到250g、油增到30ml"},{"n": "腊肉（风干）","q": "200g","a": "咸香风干腊肉最合适，肥瘦约三七；减到150g则香气不足，加到250g需减盐"},{"n": "青椒","q": "2个","a": "加到3个配色更好、更多一份清爽；减到1个也行"},{"n": "蒜","q": "4瓣（切片）","a": "加到6瓣蒜香更浓；减到2瓣则腊肉的油香单薄"},{"n": "干辣椒","q": "4个","a": "加到8个辣味足；减到2个欠香"},{"n": "豆豉（可选）","q": "10g","a": "加到20g咸鲜更足、腊肉味更厚；减到5g只添一点咸香"},{"n": "生抽","q": "10ml","a": "腊肉本身咸，加到18ml会过咸；减到5ml仅上色"},{"n": "白糖","q": "3g","a": "加到6g能中和腊肉的咸；减到1g则咸得发苦"},{"n": "菜籽油","q": "20ml","a": "腊肉煸出的油可当炒菜用，实际只需10ml；炼得太干就补20ml"},{"n": "盐","q": "2g","a": "腊肉够咸就别放；加到4g须把生抽减到5ml"}],"steps": ["洋芋削皮切成1cm厚的片，泡水冲掉表面淀粉后摊开沥干。","腊肉切2mm薄片；青椒切菱形片，蒜切片，干辣椒剪段。","净锅小火下腊肉片慢煸4-5分钟，煸到腊肉颜色变透明、边缘卷起、锅底析出清油，脂香满屋。","油不用倒出，下洋芋片摊开，中大火煎3-4分钟，煎到两面金黄、边缘起焦壳。","下干辣椒、蒜片、豆豉炒香30秒，烹入生抽、白糖。","下青椒片大火翻炒1分钟，加盐调匀出锅，锅底那些焦脆洋芋片留在盘底最香。"],"key": "腊肉要先干煸出油，油出来后再煸洋芋，洋芋才能煎出焦壳；一起下锅只会得到软塌的洋芋片和一份油腻。","tip": "腊肉咸度差别大，煸好后先尝一片再决定放不放盐；锅巴要趁热吃，凉了就不脆。"},"糟辣椒炒肉末": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "猪肉末","q": "300g","a": "前腿肉末出油香，减到200g则不够拌饭；用牛肉末需减油到25ml并加5ml蚝油"},{"n": "糟辣椒","q": "80g","a": "这是灵魂，减到50g发酵香出不来；加到120g辣味压过肉香"},{"n": "姜末","q": "10g","a": "加到15g去肉腥；减到5g也够"},{"n": "蒜末","q": "20g","a": "加到30g蒜香足；减到12g衬不出糟辣椒"},{"n": "豆豉","q": "10g","a": "加到20g咸鲜更厚；减到5g基本只添咸味"},{"n": "葱花","q": "15g","a": "加到25g更香；减到8g香气减半"},{"n": "生抽","q": "15ml","a": "糟辣椒很咸，加到25ml必齁；减到8ml则颜色淡"},{"n": "白糖","q": "4g","a": "加到8g能压住过酸；减到2g酸味太冲"},{"n": "菜籽油","q": "35ml","a": "加到50ml肉末更润；减到25ml容易粘锅"},{"n": "清水或高汤","q": "50ml","a": "加到100ml更湿润好拌饭；减到20ml则干香、略焦"}],"steps": ["锅烧热放菜籽油35ml，下肉末中大火摊炒4分钟，炒到肉末颗粒散开、颜色由粉变深黄、锅底析出一层薄油。","下姜末、蒜末中火炒香40秒。","加豆豉10g略炒30秒出香。","下糟辣椒80g，转小火慢炒2分钟，让发酵香和红油完全释放，颜色变得红亮。","加生抽、白糖、50ml清水，中火焖1分半收汁。","撒葱花出锅，拌饭拌面都香。"],"key": "糟辣椒必须最后下锅并小火慢炒；和肉末一起大火炒容易发酸发苦。炒到红油析出、边缘微微发褐才算炒透。","tip": "糟辣椒本身很咸，盐不要再放。一次多做些分装冷冻，可存三个月，拌面、蒸肉末、拌折耳根都能用。"},"糟辣椒拌豆腐": {"time": "15分钟","level": "简单","servings": "2-3人份","ing": [{"n": "嫩豆腐或豆腐脑","q": "400g","a": "用内酯豆腐/豆腐脑最滑；换成老豆腐要减到300g并增加调味汁，否则口感柴不吸味"},{"n": "糟辣椒","q": "50g","a": "加到70g辣味更足；减到35g则只剩辣酱味没有发酵的酸香"},{"n": "蒜末","q": "15g","a": "加到25g蒜味更冲；减到8g则糟辣椒的香气出不来"},{"n": "姜末","q": "5g","a": "加到10g去豆腐腥；减到3g也够"},{"n": "葱花","q": "10g","a": "加到20g更香；减到5g香气减半"},{"n": "生抽","q": "15ml","a": "加到25ml咸度足；减到10ml豆腐寡淡"},{"n": "醋","q": "8ml","a": "加到15ml更清爽开胃；减到3ml基本尝不出"},{"n": "白糖","q": "2g","a": "加到5g平衡酸味；减到1g略酸"},{"n": "香油","q": "8ml","a": "加到15ml更香滑；减到3ml少了回味"},{"n": "折耳根（可选）","q": "30g","a": "加到60g冲味更足；减到20g则清爽少冲味"}],"steps": ["豆腐沥去多余水分（内酯豆腐轻轻倒掉水）装入盘中，豆腐脑直接舀入盘中。","蒜末、姜末、糟辣椒、生抽、醋、白糖、香油、15ml凉白开调匀成料汁，搅到糟辣椒散开。","料汁直接浇在豆腐上，用勺子把豆腐轻轻推散让表面都挂上汁。","撒葱花，拌入切段的折耳根。","吃的时候从中间挖开拌到底，每一块豆腐都要裹上料汁。"],"key": "必须用嫩豆腐或豆腐脑，老豆腐口感柴、吸不进味；料汁要一次调够，别边吃边加，否则咸淡不匀。","tip": "想更香可加一勺糊辣椒或油辣子；夏天做凉拌更开胃，加醋和折耳根最提神。"},"折耳根拌豆腐": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "嫩豆腐或豆腐脑","q": "400g","a": "用内酯豆腐最滑；换老豆腐减到300g并延长腌的时间到5分钟"},{"n": "折耳根","q": "150g","a": "只取嫩尖可减到100g，冲味减一半；带根的150g冲味最足"},{"n": "蒜末、姜末","q": "蒜末15g、姜末5g","a": "蒜末加到25g蒜味更冲，减到8g则折耳根的生味压不住；姜末加到10g去土腥更强，可省略"},{"n": "辣椒面","q": "15g","a": "改用糍粑辣椒可用30g、味道更醇；加到25g则非常辣"},{"n": "熟油辣子","q": "15ml","a": "加到25ml油香更足；减到8ml则只有干辣椒面的苦"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到12ml豆腐偏淡"},{"n": "醋","q": "15ml","a": "加到25ml更清爽；减到8ml酸度不足"},{"n": "白糖","q": "2g","a": "加到5g提鲜；减到1g基本无差别"},{"n": "盐","q": "2g","a": "加到4g更入味；减到1g豆腐有点白淡"},{"n": "香油","q": "10ml","a": "加到15ml更香滑；减到5ml香气一般"}],"steps": ["折耳根择洗干净，掐成3cm长段，嫩梗切成细丝。","豆腐沥水装盘，撒1g盐抹匀，静置3分钟腌出水，让豆腐微微入味（这期间不要翻动）。","倒掉渗出的水（否则料汁被稀释、味道寡淡）。","蒜末、姜末、辣椒面、生抽、醋、白糖、盐、香油调成料汁。","料汁淋在豆腐和折耳根上，淋熟油辣子。","轻轻拌开，折耳根只拌不捣，保持脆度。"],"key": "豆腐腌出水后一定要轻轻倒掉再拌料，否则料汁被稀释；折耳根只拌不捣，捣久了出黏水就失去脆感。","tip": "贵州本地多用豆腐脑（嫩豆花），口感更滑；折耳根只取嫩尖部位，冲味最轻、接受度最高。"},"水豆豉炒饭": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "隔夜冷米饭","q": "400g（2碗）","a": "必须隔夜冷饭；用新煮的饭水分多炒不成粒，可先摊开吹干再炒"},{"n": "水豆豉","q": "40g","a": "贵州水豆豉咸鲜回甜，加到60g更咸香；减到25g则香气不足，需另加5g豆豉"},{"n": "猪肉末","q": "80g","a": "加到150g更香；不用肉末可用100g油酥花生"},{"n": "鸡蛋","q": "2个","a": "加到3个更饱腹；减到1个则蛋香弱"},{"n": "葱花","q": "15g","a": "加到25g更香；减到8g香气减半"},{"n": "蒜末","q": "10g","a": "加到20g蒜香足；减到5g衬不出豆豉"},{"n": "干辣椒","q": "3个","a": "加到6个更香；减到2个欠辣"},{"n": "生抽","q": "15ml","a": "水豆豉本身咸，加到25ml必咸；减到8ml饭色淡"},{"n": "菜籽油","q": "30ml","a": "加到45ml不粘；减到20ml容易结块"},{"n": "白糖","q": "2g","a": "加到5g可解咸；减到1g略咸"}],"steps": ["水豆豉是发酵的豇豆豉，先用清水快速冲一下（不去掉太咸），用手抓散成小块，豆粒别捣成泥。","热锅下菜籽油，中火把肉末炒散炒香2分钟。","打入蛋液炒散成小块蛋花，加蒜末、干辣椒炒香30秒。","下水豆豉转中火炒2分钟，炒到豆豉出香、颜色发亮、发酵味被激发出来。","下米饭转大火翻炒3分钟，用锅铲把饭团压散，炒到米饭粒粒分明、每粒都裹上酱色。","加生抽、白糖翻匀30秒，撒葱花出锅。"],"key": "水豆豉要用水冲一下再下锅，否则太咸太冲；米饭必须是隔夜冷饭，新饭水分多，炒出来是糊的不是粒。","tip": "贵州水豆豉咸鲜回甜，除了炒饭也可以直接拌饭、蒸肉末、炒洋芋片；换成干豆豉要先用温水泡10分钟再炒。"},"糟辣椒拌皮蛋": {"time": "20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "松花皮蛋","q": "3个","a": "3个约450g一盘刚好；减到2个量少，加到4个需多备一份料汁"},{"n": "糟辣椒","q": "60g","a": "加到80g辣味更足；减到40g发酵香偏弱，可换成糊辣椒15g"},{"n": "蒜末","q": "20g","a": "加到30g蒜味冲；减到12g则辣味单薄"},{"n": "葱花","q": "15g","a": "加到25g更香；减到8g香气减半"},{"n": "生抽","q": "20ml","a": "加到30ml偏咸；减到12ml不够咸香"},{"n": "醋","q": "10ml","a": "加到20ml能解皮蛋的碱味；减到5ml则碱味发闷"},{"n": "白糖","q": "2g","a": "加到5g中和辣味；减到1g基本尝不出"},{"n": "香油","q": "8ml","a": "加到15ml更香滑；减到3ml少一层回味"},{"n": "熟油辣子","q": "15ml","a": "加到25ml油香更浓；减到8ml只有干辣"},{"n": "折耳根","q": "50g","a": "加到100g冲味更足；减到20g则清爽少冲味"}],"steps": ["皮蛋剥壳，刀口在热水中蘸一下再切，切成6瓣整齐码入盘中（刀沾水切面平整不粘）。","糟辣椒60g加蒜末、葱花、生抽、醋、白糖、香油调匀成糊状料汁。","料汁浇在皮蛋上，淋熟油辣子。","撒入掐成段的折耳根。","吃前从中间拌开，让皮蛋吸足料汁。"],"key": "皮蛋用勺子切比用刀切更完整不碎；料汁要一次浇足拌匀，皮蛋吸味靠拌，不要只淋在上面。","tip": "糟辣椒本身很咸，拌皮蛋绝不再放盐；把糟辣椒换成糊辣椒就是另一道“糊辣椒拌皮蛋”，香气更足，是夜宵更常见的吃法。"},"酸豆角拌折耳根": {"time": "20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "酸豆角","q": "150g","a": "自己泡的酸味重就把醋从15ml减到8ml；不够酸可加到200g并多放3g盐"},{"n": "折耳根","q": "150g","a": "只取嫩尖可减到100g；带根带须的150g冲味最足"},{"n": "蒜末","q": "20g","a": "加到30g蒜味更冲；减到12g压不住两样的生味"},{"n": "辣椒面","q": "15g","a": "加到25g更辣；减到8g只剩香味"},{"n": "熟油辣子","q": "20ml","a": "加到30ml油香更足；减到10ml干辣发苦"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到12ml味道偏淡"},{"n": "醋","q": "15ml","a": "加到25ml更开胃；减到8ml则酸味只有豆角给的"},{"n": "白糖、盐","q": "白糖3g、盐2g","a": "白糖加到6g平衡酸味，减到1g酸得单薄；盐加到4g容易齁，酸豆角本身很咸，先少放再尝"},{"n": "香油","q": "8ml","a": "加到15ml更香滑；减到4ml少了回味"},{"n": "熟芝麻","q": "3g","a": "加到8g香得更明显；减到1g基本看不出"}],"steps": ["酸豆角洗净切成0.5cm见方的小粒，梗和籽一起切，籽是酸味所在不要丢掉。","折耳根择洗干净，掐成3cm长段，嫩梗斜切成薄片。","蒜末、辣椒面、生抽、醋、白糖、盐、香油、15ml凉白开调成料汁。","酸豆角和折耳根一起放大碗，淋入料汁拌匀。","加熟油辣子翻拌均匀，撒上熟芝麻即可。"],"key": "这是纯凉拌，全程不加火不加水，酸味和冲味全靠生料拌出来；酸豆角自带咸度，盐一定要先少放再尝。","tip": "想要折耳根更爽脆，可把折耳根梗单独用淡盐水泡5分钟再冲洗；配料里也可以加炒香的油酥花生或酥黄豆。"},"糊辣椒炒洋芋": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "洋芋","q": "3个（约500g）","a": "切1cm厚片；加到700g需把糊辣椒增到60g、油增到40ml"},{"n": "青椒","q": "3个","a": "加到4个更清爽；减到2个则糊辣椒味太单"},{"n": "糊辣椒（自制焙焦舂碎的青椒糊）","q": "50g","a": "这是灵魂，减到30g糊香不足；加到70g则糊味压过洋芋香"},{"n": "猪五花肉","q": "100g","a": "加到150g更油香；不用肉要把油提到40ml"},{"n": "蒜末","q": "15g","a": "加到25g蒜香突出；减到8g衬不出糊辣椒"},{"n": "姜末","q": "8g","a": "加到15g去腥；减到5g影响不大"},{"n": "生抽","q": "15ml","a": "加到25ml偏咸；减到10ml颜色偏淡"},{"n": "白糖","q": "3g","a": "加到6g能平衡辣味；减到1g辣得发苦"},{"n": "菜籽油","q": "30ml","a": "加到45ml不粘；减到20ml洋芋片易粘锅"},{"n": "盐","q": "3g","a": "加到5g偏咸；减到2g则味道淡"}],"steps": ["洋芋削皮切成1cm厚的片，泡水冲掉表面淀粉，捞出摊开彻底沥干。","青椒去籽切菱形片，蒜切末，姜切末。","热锅下五花肉片，中火煸出油2分钟，下姜末、蒜末炒香30秒。","下糊辣椒50g，小火炒1分钟炒出糊香，让肉片均匀裹上红油。","转中大火下洋芋片炒3分钟，炒到洋芋片边缘焦黄发软。","下青椒片大火炒1分钟，加生抽、白糖、盐翻匀出锅。"],"key": "糊辣椒要最后加并用小火炒香，加热过久会发苦整锅带焦味；必须先炒洋芋再放糊辣椒，糊香和呛味才压得住洋芋的土腥。","tip": "自制糊辣椒：二荆条青椒净锅小火焙到焦黑，泡水剥皮去蒂，连皮带籽一起舂碎，加盐拌匀。现成的贵州糊辣椒酱也可以直接用。"},"酸汤煮豆腐": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "嫩豆腐","q": "400g","a": "内酯豆腐最滑；换老豆腐要减到300g并多煮2分钟，口感才不柴"},{"n": "红酸汤（自制发酵番茄辣椒）","q": "300ml","a": "这是本菜的核心，减到200ml酸味不足；加到400ml要同时减番茄，否则过酸"},{"n": "番茄","q": "2个（约250g）","a": "加到3个汤更浓稠甜味足；减到1个汤色偏淡"},{"n": "泡椒（剁碎）","q": "3个（约25g）","a": "加到6个辣味足；减到1个酸味不够有层次"},{"n": "蒜末","q": "15g","a": "加到25g蒜香浓；减到8g衬不出酸汤"},{"n": "姜末","q": "8g","a": "加到15g去腥；减到5g影响不大"},{"n": "折耳根","q": "80g","a": "加到120g冲味更足；减到40g则清淡"},{"n": "菜籽油","q": "25ml","a": "加到40ml汤面红油更亮；减到15ml酸味单薄"},{"n": "清水或高汤","q": "400ml","a": "加到500ml汤更宽；减到300ml则汤浓味挤"},{"n": "盐、白胡椒粉","q": "盐3g、白胡椒粉1g","a": "红酸汤自带咸，盐加到5g会齁，减到1g时尝味再定；白胡椒粉加到2g更辛香，减掉也不影响"}],"steps": ["番茄去皮切小块，泡椒剁碎；豆腐切2cm方块备用。","热锅下菜籽油25ml，中火炒番茄块3分钟，炒到番茄出汁、变软出沙。","下泡椒碎、姜末、蒜末，小火炒1分钟炒出红油和酸香。","加红酸汤300ml和清水400ml煮开，转小火熬5分钟让汤味融合，起锅前撒白胡椒粉。","豆腐块轻轻滑入汤中，小火煮5分钟，豆腐浮起、边缘微微发颤即熟透，切勿大火翻滚。","撒折耳根段，加盐调味后连汤盛入汤碗。"],"key": "酸汤要自己发酵才够味，醋和番茄酱调不出那个层次；豆腐下锅后只能小火慢煮，滚沸会把豆腐冲成碎渣。","tip": "没有红酸汤可用番茄加糊辣椒加一点点白酒煮，但酸香偏单薄；加5g油辣椒能贴近本地味。折耳根一定最后撒，煮久了冲味跑光。"},"洋芋粑炒腊肉": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "蒸熟洋芋","q": "500g（3个洋芋）","a": "粉一点的黄心洋芋做出的粑才软糯；减到400g则比例偏干要加20g糯米粉"},{"n": "糯米粉","q": "100g","a": "蒸熟洋芋500g配100g是软糯不塌的比例；加到150g则糍而不软，减到60g则软塌夹不住"},{"n": "腊肉","q": "150g","a": "风干腊肉最香，减到100g则锅巴不香；用五花肉可减到120g并加10ml老抽"},{"n": "青椒","q": "2个","a": "加到3个解腻更多；减到1个也够"},{"n": "蒜","q": "4瓣（切片）","a": "加到6瓣蒜香足；减到2瓣则腊肉油香单薄"},{"n": "干辣椒","q": "4个","a": "加到8个辣味更足；减到2个欠香"},{"n": "豆豉","q": "8g","a": "加到15g咸鲜更厚；减到4g只添一点咸"},{"n": "生抽、白糖","q": "生抽10ml、白糖2g","a": "腊肉咸，生抽加到18ml会咸，减到5ml仅上色；白糖加到5g中和咸味，减到1g略咸"},{"n": "菜籽油","q": "25ml","a": "腊肉煸出的油可复用，实际只需10ml；油太少会粘锅"},{"n": "清水（焯粑用）","q": "约1.5L","a": "量以能没过粑为准，减到1L需分两次焯；必须用沸水焯定型才不散"}],"steps": ["洋芋去皮蒸熟（约20分钟），趁热压成泥，加糯米粉揉成不粘手的团（500g洋芋配100g糯米粉），搓成长条，切1.5cm厚的片或斜刀块。","锅中水烧开，洋芋粑片下锅煮2分钟至浮起，捞出沥干（先焯水定型，后面煎才不碎不粘）。","净锅小火下腊肉片煸4分钟，煸到出油、边缘卷起透亮。","转中火下洋芋粑，用锅铲轻推慢煎3-4分钟，煎到两面金黄起焦壳。","下蒜片、干辣椒、豆豉炒香30秒，烹入生抽、白糖。","下青椒片大火炒1分钟出锅。"],"key": "洋芋粑必须先焯水定型再煎，否则一碰就散；煎的时候只推不翻，用铲背轻压比翻面更容易结出焦壳。","tip": "一次揉不完的洋芋粑可搓成条冷冻，随取随煮；煎好的隔夜回锅一次又脆又香。不想自制就买现成洋芋粑粑块。"},"折耳根炒肉末": {"time": "20分钟","level": "简单","servings": "3人份","ing": [{"n": "猪肉末","q": "250g","a": "前腿或五花肉末出油香，减到180g则不够下饭；换腊肉末要减生抽到5ml、油到15ml"},{"n": "折耳根","q": "200g","a": "带根的200g冲味足；只取嫩尖减到120g，接受度更高"},{"n": "蒜末","q": "15g","a": "加到25g蒜香更浓；减到8g衬不出折耳根味"},{"n": "姜末","q": "8g","a": "加到15g去肉腥；减到5g也够"},{"n": "干辣椒","q": "4个","a": "加到8个更辣更香；减到2个辣度不足"},{"n": "糍粑辣椒","q": "30g","a": "加到45g糊辣味足；减到15g则只剩干辣"},{"n": "生抽","q": "15ml","a": "加到25ml偏咸；减到10ml颜色偏淡"},{"n": "白糖","q": "2g","a": "加到5g提鲜；减到1g无差别"},{"n": "菜籽油","q": "30ml","a": "加到45ml肉末不粘；减到20ml容易结块"},{"n": "葱花","q": "10g","a": "加到20g更香；减到5g香气减半"}],"steps": ["折耳根择洗干净，掐成3cm长段，嫩梗切成斜片，分开放。","热锅下菜籽油，中大火下肉末摊炒3-4分钟，炒到肉末发干、颜色金黄、锅底出香。","下干辣椒、姜末、蒜末中火炒香40秒，加糍粑辣椒30g转小火炒30秒出红油。","加生抽、白糖炒匀。","下折耳根梗大火炒40秒，再下折耳根叶子炒40秒，炒到断生即可，不要炒蔫。","撒葱花出锅。"],"key": "折耳根梗和叶必须分开下，梗先炒才脆；全程大火快炒，久了出水就软塌、冲味也散了。","tip": "折耳根先用淡盐水泡5分钟再冲洗能减冲味；用糍粑辣椒比干辣椒面香很多，这是贵州本地做法。"},"糊辣椒鸡丁": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "鸡腿肉（去骨切丁）","q": "400g","a": "鸡腿肉比鸡胸嫩很多，减到300g则不够吃；用鸡胸需加10ml水淀粉抓到发黏"},{"n": "糊辣椒（焙焦舂碎的青椒糊）","q": "70g","a": "减到45g糊香不足；加到90g则辣味压过鸡丁的鲜"},{"n": "蒜末","q": "15g","a": "加到25g蒜香足；减到8g衬不出糊香"},{"n": "姜末","q": "8g","a": "加到15g去鸡腥；减到5g也够"},{"n": "葱段","q": "20g","a": "加到30g葱香更足；减到10g也够"},{"n": "花椒","q": "10粒","a": "加到20粒麻香明显；减到5粒基本无麻"},{"n": "生抽","q": "15ml","a": "加到25ml偏咸；减到10ml腌味不足"},{"n": "白糖","q": "3g","a": "加到6g能中和辣味；减到1g辣得发苦"},{"n": "菜籽油","q": "40ml","a": "加到55ml炒鸡丁更滑；减到30ml易粘锅"},{"n": "料酒、淀粉（腌鸡丁）","q": "料酒15ml、淀粉15g","a": "料酒加到25ml肉发酸，减到8ml酒味残留；淀粉加到25g鸡丁更滑更挂汁，减到8g则口感发柴"}],"steps": ["鸡腿肉去骨切成1.5cm见方的丁，加生抽、料酒、淀粉15g抓匀腌15分钟，腌到表面发黏、颜色发白。","热锅下菜籽油40ml，下花椒、蒜末、姜末，小火炒香40秒。","转大火下鸡丁快速滑炒2分钟，炒到鸡丁全部变白、边缘微微焦香。","转小火下糊辣椒70g，慢慢翻炒1分半，让糊辣椒的焦香和红油裹住鸡丁，锅里不能出现焦苦味。","加白糖3g翻匀，沿锅边淋8ml清水，中火收汁30秒。","下葱段大火翻10秒出锅。"],"key": "糊辣椒下锅后必须转小火慢炒，猛火一炒就焦糊发苦，整锅都带焦糊味；它下得晚，所以前期必须把鸡丁本身的香炒足。","tip": "自制糊辣椒：二荆条青椒净锅小火焙至焦黑，泡水剥皮去蒂，加盐和熟油舂成糊。一次多做些，拌面拌饭都好用。"},"苦瓜炒腊肉": {"time": "30分钟","level": "简单","servings": "3人份","ing": [{"n": "苦瓜","q": "1根（约600g）","a": "选肉厚实的直苦瓜，加到800g需把腊肉增到200g；瓤刮不净会苦"},{"n": "腊肉（风干）","q": "150g","a": "减到100g咸香不足；加到200g要减糖并尝味再定盐"},{"n": "蒜","q": "4瓣（切片）","a": "加到6瓣蒜香足；减到2瓣腊肉油香单薄"},{"n": "干辣椒","q": "4个","a": "加到8个更香更辣；减到2个欠香"},{"n": "青椒","q": "1个","a": "加到2个解腻更明显；不用也成立"},{"n": "豆豉","q": "8g","a": "加到15g咸鲜更厚；减到4g只添一点咸味"},{"n": "生抽","q": "10ml","a": "腊肉咸，加到18ml会过咸；减到5ml仅上色"},{"n": "白糖","q": "3g","a": "加到6g能中和咸味、并显出苦瓜回甜；减到1g发苦"},{"n": "菜籽油","q": "20ml","a": "腊肉煸出的油可当炒菜用；油太少苦瓜会吸油发腻"},{"n": "盐","q": "2g","a": "腌苦瓜用掉1g，炒时再1g；腊肉够咸就别加"}],"steps": ["苦瓜剖开，刮净内部白瓤（白瓤是苦味主要来源），切成薄片，用1g盐抓匀腌10分钟，再用清水冲洗两遍，沥干。","腊肉切薄片，青椒切菱形片，蒜切片。","净锅小火下腊肉片煸4分钟，煸到出油、颜色透明。","转中火下苦瓜片，大火炒2分钟，炒到苦瓜边缘透明发软。","下蒜片、干辣椒、豆豉炒香30秒，加青椒片。","加生抽、白糖、盐大火翻匀30秒立即出锅，苦瓜回甜最好吃的就是刚断生那一下。"],"key": "苦瓜一定要挖净白瓤并用盐腌后再冲水，苦味才减得下去；腊肉要煸出足够的油，油不足苦瓜会吸油发腻。","tip": "苦瓜切薄一点更容易炒到半透明；腌过水的苦瓜若还有苦味，可再焯水10秒。回甜最嫩，不要久炒成软塌。"},"土豆丝炒折耳根": {"time": "25分钟","level": "简单","servings": "3人份","ing": [{"n": "土豆","q": "2个（约400g）","a": "选脆一点的黄心土豆；加到600g需把油增到40ml、醋增到25ml"},{"n": "折耳根","q": "150g","a": "带根的150g冲味足；只取嫩尖减到100g更易入口"},{"n": "青椒","q": "2个","a": "加到3个贵州味更足（本地做法爱加青椒丝）；减到1个也够"},{"n": "蒜末","q": "15g","a": "加到25g蒜香足；减到8g压不住折耳根土味"},{"n": "干辣椒","q": "4个","a": "加到8个更辣；减到2个辣度不足"},{"n": "花椒","q": "15粒","a": "加到25粒麻香明显；减到5粒基本无麻"},{"n": "醋","q": "20ml（分两次）","a": "加到30ml酸度更冲；减到12ml则酸得不够亮"},{"n": "盐","q": "3g","a": "加到5g偏咸；减到2g则土豆丝本身寡淡"},{"n": "生抽","q": "10ml","a": "加到18ml咸味足；减到5ml颜色偏淡"},{"n": "菜籽油","q": "30ml","a": "加到45ml不粘；减到20ml容易粘住土豆丝"}],"steps": ["土豆去皮先切薄片再切细丝，流水冲洗到水清（洗掉淀粉才脆），泡入冷水防氧化，捞出沥干。","折耳根洗净掐成3cm长段，嫩梗切细丝；青椒切丝。","热锅下菜籽油，小火下花椒炸出香味后捞掉，下蒜末、干辣椒炒香30秒。","转大火下土豆丝，沿锅边淋10ml清水快速翻炒2分钟，炒到土豆丝刚断生、边缘透明。","加醋10ml、糖1g、盐3g、生抽翻匀，继续大火炒30秒。","下折耳根大火炒1分钟，起锅前淋入剩余10ml醋，撒葱花翻匀出锅。"],"key": "土豆丝必须洗掉淀粉并泡水才不粘；醋分两次放是这道菜的诀窍——第一次遇热出香、第二次起锅提酸，才有“酸得亮”的鲜劲；折耳根最后下锅，1分钟足矣。","tip": "想要更地道的贵州味就把青椒丝一起下锅炒；醋用白醋或米醋，别用陈醋，色深味浊。"},"番茄炒蛋": {"time": "20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "番茄","q": "3个（约450g）","a": "选沙瓤番茄，炒出来才有沙；减到2个则量偏少，加到4个需把糖增到10g"},{"n": "鸡蛋","q": "4个（约200g）","a": "3-4人份用4个正好；加到5个更饱腹，减到3个则要再加番茄"},{"n": "白糖","q": "8g","a": "甜派加到12g、咸派减到3g；减到2g则番茄的酸顶不上来"},{"n": "盐","q": "3g（蛋液1g、菜里2g）","a": "加到5g偏咸；减到2g酸味打不开"},{"n": "菜籽油","q": "40ml（炒蛋30ml、炒番茄10ml）","a": "加到60ml更润；减到25ml容易发干"},{"n": "葱花","q": "10g","a": "加到20g更香；减到5g香气减半"},{"n": "蒜末","q": "10g","a": "加到20g蒜香足、能托番茄味；减到5g蒜香不足但更清爽"},{"n": "生抽","q": "5ml","a": "加到10ml提咸香；减掉也不影响，很多本地做法只放糖不放酱油"},{"n": "清水（兑蛋液）","q": "20ml","a": "加到40ml蛋更嫩滑；减到10ml或不加则蛋更蓬松"},{"n": "水淀粉","q": "20ml（淀粉5g+水15ml）","a": "加到35ml汤汁更浓挂蛋；减到10ml则汤汁偏稀"}],"steps": ["番茄底部划十字，浇开水烫30秒去皮，切滚刀块；鸡蛋打散，加1g盐和20ml清水搅匀，蛋液要打到完全起泡、没有蛋清块。","热锅下菜籽油30ml，倒入蛋液，先别急着搅动，等边缘凝固、鼓起大泡再用铲子推散，蛋块到八成熟就盛出。","锅内补10ml油，下蒜末炒香30秒，下番茄块中火炒3分钟，炒到番茄出汁、变软出沙。","加糖8g、盐2g、生抽5ml，翻匀后把炒好的蛋倒回锅里。","淋入水淀粉20ml翻匀收汁，汤汁略稠能挂住蛋块，撒葱花出锅。"],"key": "鸡蛋要八成熟就盛出，最后回锅靠余温和汤汁烫熟，才嫩；番茄一定要炒到出沙出汁，否则是“番茄加蛋”而不是番茄炒蛋。","tip": "甜派加糖到12g、咸派减到3g；番茄不够红可以加1勺番茄酱，但别多，多了有股罐头酱味。"},"酸辣土豆丝": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "土豆","q": "2个（约450g）","a": "选脆的黄心土豆，切细丝；加到600g需把油增到40ml、醋增到25ml"},{"n": "干辣椒","q": "5个（剪段）","a": "加到8个辣味更足；减到3个则香而不辣"},{"n": "花椒","q": "15粒","a": "加到25粒麻香明显；减到5粒基本无麻"},{"n": "泡椒、泡姜（剁碎）","q": "20g","a": "贵州版本的关键，加到30g酸辣更有层次；没有可换成剁椒10g加姜末"},{"n": "蒜末","q": "15g","a": "加到25g蒜香足；减到8g酸辣缺个衬"},{"n": "姜末","q": "5g","a": "加到10g去土豆生味；减到3g影响不大"},{"n": "醋","q": "20ml（分两次各10ml）","a": "加到30ml酸度更冲；减到12ml酸得不够亮"},{"n": "盐、白糖","q": "盐3g、白糖2g","a": "盐加到5g偏咸，减到2g土豆丝本身寡淡；白糖加到5g能压住辣味，减到1g略辣"},{"n": "菜籽油","q": "30ml","a": "加到45ml不粘；减到20ml土豆丝易粘连"},{"n": "葱花","q": "10g","a": "加到20g更香；减到5g香气减半"}],"steps": ["土豆去皮切薄片再切细丝，流水冲洗至水清，泡入冷水防氧化，捞出沥干备用。","泡椒、泡姜剁碎成末，干辣椒剪成2cm段，蒜姜切末。","热锅下菜籽油，中火下花椒炸出香味后捞掉，下干辣椒段、泡椒末、泡姜末、蒜末、姜末炒香40秒。","转大火下土豆丝，沿锅边淋10ml清水快速翻炒2分钟，炒到土豆丝刚断生、边缘发透明。","加糖2g、盐3g、第一次的醋10ml翻匀，继续大火炒30秒。","起锅前淋入剩下的10ml醋，撒葱花翻匀出锅。"],"key": "土豆丝要切得细而均匀，下锅前必须洗掉淀粉否则粘连；醋分两次放是酸辣土豆丝的诀窍，一次放只有酸不香，两次放才有“酸得亮”的鲜香。","tip": "想要脆就全程大火、时间不超过2分钟，久炒必软；泡椒泡姜是贵州版的关键，没有可用剁椒加姜末替代。醋用白醋或米醋，别用陈醋。"},"青椒肉丝": {"time": "20分钟","level": "中等","servings": "2-3人份","ing": [{"n": "猪里脊","q": "250g","a": "换成前腿精肉或梅花肉均可，切丝量不变；肉加到400g需分两锅滑炒，一锅不炒会出水变柴；减到150g则肉香不足、青椒抢味"},{"n": "青椒","q": "200g（约3个）","a": "加到300g青椒会变软塌、汤汁变多；减到120g则只剩辣味没有清香，菜量明显不够"},{"n": "大蒜","q": "15g（4瓣切片）","a": "加到25g蒜味更冲、适合重口；减到8g蒜香不足，可用姜末2g顶替一部分"},{"n": "生抽","q": "15ml","a": "加到25ml颜色变深、咸度明显上升，需把盐减到1g；减到8ml则颜色发白不挂汁"},{"n": "料酒","q": "10ml","a": "加到20ml去腥更彻底但成菜会有酒味；减到5ml腌肉略腥，可在腌料里加1g姜粉"},{"n": "淀粉","q": "10g","a": "加到15g肉丝挂浆更厚、滑油后更嫩，但会有轻微芡感；减到5g肉丝易炒老"},{"n": "食用植物油","q": "40ml（滑油25ml、炒菜15ml）","a": "加到60ml更润但成菜偏腻；减到20ml肉丝易粘锅，需用不粘锅并补5ml水"},{"n": "盐","q": "3g（腌1g、炒2g）","a": "加到5g会齁咸，建议同时减生抽5ml；减到1g则肉片和青椒会淡而无味"},{"n": "白胡椒粉","q": "1g","a": "加到2g胡椒味抢过肉香；减掉不加味道更纯粹，适合怕胡椒味的人"},{"n": "香油","q": "3ml","a": "加到8ml会在盘底积一层油、拌不开；减到1ml几乎尝不出，只用于增亮"}],"steps": ["猪里脊先顺纹切成1cm薄片，再逆着纹路切成火柴粗细的丝——逆纹切纤维被切断，炒出来才嫩不塞牙；加料酒5ml、盐1g、淀粉8g抓匀至上浆，再淋3ml油封住水分，腌10分钟。","青椒去籽切同样粗细的丝，蒂部留1cm不要切断防止散汁；蒜切成薄片，蒜片太厚爆香慢且发苦。","锅烧到五成热下25ml油，转大火把腌好的肉丝一次下锅，用铲子快速滑散40秒，看到肉丝全部变白、表面发亮立刻盛出，这一步是嫩的关键。","锅内留15ml底油，六成热下蒜片，中火炒20秒出香即可，蒜片刚变黄就要下青椒，蒜焦了整锅都发苦。","转最大火下青椒丝，快速翻炒1分钟，炒到青椒颜色变深、边缘开始打软出水，此时把肉丝回锅。","沿锅边淋生抽15ml、料酒5ml，加盐2g、白胡椒粉1g，大火翻炒30秒让调料裹匀，起锅前淋香油3ml，翻两下装盘。"],"key": "肉丝必须逆纹切并上浆封油，且滑油到变色就盛出，回锅久炒肉必柴；全程大火是这道菜不出水的保证。","tip": "没有生抽可用酱油分两次加，第一次上色第二次提味更好；想更下饭可加5ml蚝油代替部分生抽；配一碗白米饭，锅底的汁别浪费。"},"鱼香茄子": {"time": "25分钟","level": "中等","servings": "2-3人份","ing": [{"n": "长茄子","q": "400g（约2根）","a": "换成圆茄子需减到350g并多吸油时间；加到600g要多煎2分钟，否则外焦内生"},{"n": "泡红辣椒","q": "25g（剁碎）","a": "加到40g辣味和泡椒香更突出，需减白糖5g平衡；减到10g只有辣没有泡椒的发酵香"},{"n": "泡姜","q": "15g（剁末）","a": "加到25g姜香压得住鱼香味；减到5g腥味上扬，可加5ml泡椒水补味"},{"n": "大蒜","q": "20g（剁末）","a": "加到30g蒜香更浓但会盖住泡椒；减到10g需多用5g泡椒提味"},{"n": "大葱","q": "20g（切葱花）","a": "加到30g葱香更冲；减到10g香气不够，可用蒜末补一部分"},{"n": "白糖","q": "15g","a": "加到25g甜味明显盖过酸，需把醋减到15ml；减到8g则酸甜失衡、发苦不挂汁"},{"n": "香醋","q": "20ml","a": "加到30ml酸香更立体，此时白糖要加到20g；减到10ml会发甜腻，失去鱼香"},{"n": "生抽","q": "15ml","a": "加到25ml咸度高、需减盐；减到8ml颜色淡不挂汁"},{"n": "淀粉水","q": "40ml（淀粉8g+水32ml）","a": "加到60ml汤汁更稠能挂住茄子；减到20ml收不住汁，茄子会泡在汤里"},{"n": "菜籽油","q": "50ml","a": "加到70ml茄子更亮更润但偏腻；减到30ml煎时易粘锅，可先蒸软茄子再回锅"}],"steps": ["茄子切3cm见方的滚刀块，撒盐3g拌匀静置10分钟杀出水分，用手挤干表面水——这一步能减少一半吸油量，是不腻的前提。","碗中调鱼香汁：泡红辣椒碎、泡姜末、蒜末入碗，加白糖15g、香醋20ml、生抽15ml、淀粉水40ml搅匀备用。鱼香味的核心就是泡椒泡姜蒜葱加糖醋比例。","锅烧到六成热下40ml菜籽油，中火下茄子块，摊平煎3-4分钟，煎到表面微黄发软、能用筷子轻松穿透。","把茄子拨到锅边，锅内空出位置下10ml油，把泡辣椒碎、泡姜末、蒜末下锅小火炒1分钟，炒出红油、香气冲鼻，这是鱼香味的关键一步。","倒入调好的鱼香汁，大火烧开后转中小火2分钟，让茄子充分吸收料汁，汤汁开始变稠。","开盖转大火翻匀收汁，汤汁浓稠能挂住茄子时，撒葱花颠匀出锅。"],"key": "鱼香味全在泡椒、泡姜、蒜末和糖醋比例上：泡椒泡姜蒜要小火炒出红油，糖与醋按1:1、醋略多于糖才能甜而不腻、酸而不涩。","tip": "没有泡椒可用泡椒酱20g加剁椒10g替代，但需把白糖减到10g；茄子先蒸8分钟再煎可以省一半油；想上桌快可省掉最后大火收汁。"},"可乐鸡翅": {"time": "35分钟","level": "简单","servings": "2-3人份","ing": [{"n": "鸡中翅","q": "500g（约10个）","a": "加到700g需用1.5罐可乐并延长焖煮5分钟；减到300g用半罐即可，汁更少更稠"},{"n": "可乐","q": "330ml（1罐）","a": "加到500ml（1.5罐）更甜更稀，收汁时间要延长到8分钟；减到200ml则需分次加，收出的汁偏苦"},{"n": "生抽","q": "30ml","a": "加到45ml咸味足、可减盐；减到15ml颜色不够深，需补老抽5ml"},{"n": "老抽","q": "5ml","a": "加到10ml颜色变深近乎发黑；减到2ml成菜偏浅，可多煎一会儿上色"},{"n": "料酒","q": "15ml","a": "加到25ml去腥彻底；减到8ml会有鸡腥味，可用姜片多放2片"},{"n": "姜","q": "15g（4片）","a": "加到25g姜香更明显；减到8g姜味不足，可加2片香叶"},{"n": "小葱","q": "10g（2段）","a": "加到20g葱香更浓；减掉也不影响，葱久煮会发苦"},{"n": "白糖","q": "8g","a": "加到15g甜度明显上升、需减可乐50ml；减到3g则甜味只靠可乐，收汁后偏淡"},{"n": "食用植物油","q": "20ml","a": "加到30ml煎出的鸡翅更油亮；减到10ml易粘锅，需用不粘锅"},{"n": "熟白芝麻","q": "2g","a": "加到5g撒面更香；减掉不减风味，纯粹为点缀"}],"steps": ["鸡中翅两面各划两刀便于入味，冷水下锅加姜片、料酒，大火烧开撇净浮沫后煮3分钟，捞出用温水冲净沥干——用温水冲，鸡肉才不发柴。","锅烧热下20ml油，把鸡翅平铺中火煎3-4分钟，煎到两面金黄、边缘微焦，这层焦壳是成品颜色和香味的关键。","倒入可乐至刚好没过鸡翅，加生抽30ml、老抽5ml、姜片、葱段，大火烧开后转小火加盖焖15分钟，中途翻一次面让上色均匀。","开盖转大火收汁，晃锅让糖汁均匀包裹鸡翅并不断翻动，汤汁由稀变稠、开始冒大泡、拉出亮丝。","收到汤汁浓稠挂住鸡翅、锅底只剩薄薄一层油亮的汁时，再晃锅30秒让糖汁完全裹匀，关火撒白芝麻。"],"key": "收汁阶段必须用大火并且不停翻动：糖汁一旦停火会返潮变稀，停手则会焦苦发黑，火力和翻动频率决定成败。","tip": "想更快可以先焖20分钟再收汁；用零度可乐比含糖可乐甜度低，需要额外加5g糖；剩下的汁别倒，拌面或卤蛋都好吃。"},"糖醋排骨": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "猪肋排","q": "600g","a": "加到800g要先炸后焖时间各加8分钟；减到400g用同样汁量会偏咸，需减生抽5ml"},{"n": "白糖","q": "40g","a": "加到55g糖色更亮更甜，需把香醋减到30ml；减到25g则挂汁不够、酸甜失衡"},{"n": "香醋","q": "40ml","a": "加到55ml酸味更立体，此时糖必须加到50g；减到25ml会发齁甜，失去糖醋菜的灵魂"},{"n": "生抽","q": "20ml","a": "加到30ml颜色深咸度足；减到10ml颜色偏淡，需靠老抽补色"},{"n": "老抽","q": "5ml","a": "加到10ml颜色过深发黑；减到2ml成菜颜色不够红润"},{"n": "料酒","q": "20ml","a": "加到30ml去腥更好；减到10ml会有肉腥，可用姜片多放"},{"n": "姜","q": "15g（4片）","a": "加到25g姜香更足；减到8g去腥作用弱"},{"n": "大蒜","q": "20g（4瓣）","a": "加到30g蒜香明显，适合重口；减到10g蒜香不足"},{"n": "菜籽油","q": "400ml（炸排骨用）","a": "加到600ml油温更稳、排骨更挺；减到250ml锅浅需分批炸，否则排骨会沉底粘锅"},{"n": "熟白芝麻","q": "3g","a": "加到8g点缀更明显；减掉不减风味"}],"steps": ["排骨剁成5cm长段，冷水浸泡30分钟去血水，中途换两次水，捞出沥干——血水去不干净，炖出来发腥发柴。","冷水下锅加姜片、料酒，大火烧开撇净浮沫，再煮3分钟，捞出用温水冲洗干净，务必用温水。","厨房纸把排骨表面水分彻底吸干，锅烧热下400ml油，六成热下排骨，中火炸4-5分钟至外层定型金黄，捞出静置2分钟，再把油温升到八成热复炸40秒逼出油分，这样吃起来外酥里嫩。","另起锅留10ml底油，小火下姜末蒜末炒香，加白糖40g小火熬到融化、起小泡、变成琥珀色。","倒入排骨快速翻动裹上糖色，加香醋40ml、生抽20ml、老抽5ml、料酒10ml和150ml热水，大火烧开转小火炖15分钟。","开盖转大火收汁，不停翻动让糖汁均匀挂在排骨上，汤汁浓稠、亮油不澥时撒芝麻出锅。"],"key": "两个致命环节：一是炒糖色必须小火熬到琥珀色就立刻下排骨，晚一秒就发黑发苦；二是排骨焯水后只能用温水冲洗，冷水会让肉纤维骤缩变柴。","tip": "糖与醋严格按1:1（40g糖配40ml醋）是不齁不酸的基准；醋可先放10ml在熬糖时补香、其余起锅前补足；想更亮可用红糖10g替掉白糖10g。"},"红烧带鱼": {"time": "40分钟","level": "中等","servings": "3人份","ing": [{"n": "带鱼","q": "600g（两段，约1.5条）","a": "加到900g需延长焖煮5分钟并放大锅；减到400g汁多易咸，减生抽5ml"},{"n": "姜","q": "20g（5片）","a": "加到30g姜味更足；减到10g腥味上扬"},{"n": "大蒜","q": "20g（4瓣）","a": "加到30g蒜香更浓；减到10g需多放干辣椒补香"},{"n": "干辣椒","q": "5个（剪段）","a": "加到8个辣味明显；减到2个则只留咸鲜，可加1勺剁椒"},{"n": "生抽","q": "30ml","a": "加到45ml咸味足需减盐；减到15ml颜色淡、需补老抽"},{"n": "老抽","q": "5ml","a": "加到10ml颜色发黑；减到2ml色不够红润"},{"n": "料酒","q": "20ml","a": "加到30ml去腥彻底；减到10ml会有腥味，可加姜片"},{"n": "白糖","q": "10g","a": "加到18g口味更圆润；减到5g则咸鲜直给、缺一点回甘"},{"n": "香醋","q": "5ml","a": "加到12ml能明显去腥提亮；减到3ml基本尝不出"},{"n": "菜籽油","q": "40ml","a": "加到60ml可半煎半炸、带鱼更挺更香；减到25ml需改用不粘锅并把鱼擦干"}],"steps": ["带鱼去头去尾去内脏，剪成5cm长段，两面用厨房纸反复擦干水分，表面水分擦不干下锅必溅油——每面各划三刀便于入味。","撒盐3g、料酒10ml抓匀腌10分钟，倒掉渗出的水，表面拍一层薄面粉至干爽。","锅烧至五成热下40ml菜籽油，下姜片、蒜片、干辣椒段，小火炒30秒出香。","转中火，抖掉多余面粉把带鱼轻放入锅，煎3分钟到底面金黄定型再翻面，两面各约3分钟，中途不要频繁翻动以免翻碎。","加生抽30ml、老抽5ml、料酒10ml、白糖10g和200ml热水，放入葱段，大火烧开转中小火焖8分钟。","汤汁收至浓稠挂住带鱼后，沿锅边淋香醋5ml，翻匀出锅。"],"key": "带鱼表面必须彻底擦干、锅要热油要热再下锅，否则粘锅破皮、溅油；煎时全程中火、只翻一次面，才保得住完整形状。","tip": "带鱼表面的银膜不用刮，煎后更香；怕油溅可先蒸5分钟再煎，油能省一半；香醋一定沿锅边淋，高温激出的醋香才明显。"},"蒜苔炒肉": {"time": "18分钟","level": "简单","servings": "2-3人份","ing": [{"n": "蒜苔","q": "300g","a": "加到450g需分两次干煸，否则受热不均；减到200g则肉多菜少、少了蒜苔的脆甜"},{"n": "猪五花肉","q": "150g","a": "换成猪里脊200g更嫩不腻；肉加到250g需把油量减到20ml，成菜不腻"},{"n": "干辣椒","q": "5个","a": "加到8个辣味更足；减到2个基本不辣，可改用1勺剁椒"},{"n": "大蒜","q": "15g（4瓣切片）","a": "加到25g蒜香更浓；减到8g蒜片不够焦香"},{"n": "生抽","q": "15ml","a": "加到25ml颜色深咸度高；减到8ml挂汁不足"},{"n": "料酒","q": "10ml","a": "加到20ml去腥更足；减到5ml腌肉略腥"},{"n": "淀粉","q": "8g","a": "加到12g肉片更滑嫩；减到4g肉片易老"},{"n": "食用植物油","q": "25ml","a": "加到35ml煸出的肉更香；减到15ml肉片易粘锅"},{"n": "盐","q": "3g","a": "加到5g会咸，需减生抽5ml；减到1g则蒜苔寡淡无味"},{"n": "香醋","q": "3ml","a": "加到8ml能明显提香解腻；减到1ml几乎尝不出"}],"steps": ["蒜苔掐去老根，撕掉表面老筋，切成4cm段，洗净后彻底沥干——带水下锅会剧烈溅油。","五花肉切薄片，加料酒5ml、生抽5ml、淀粉8g抓匀腌10分钟。","干锅不放油，中小火干煸蒜苔4分钟，边煸边压，让表皮起皱、发白、微软出香，煸好后盛出——这是这道菜灵魂所在，直接下锅炒会又生又涩。","锅烧至六成热下油25ml，下肉片滑散，中火炒2分钟至变色出油、边缘微焦。","下干辣椒段和蒜片炒30秒，倒入蒜苔转大火翻炒1分钟。","加生抽10ml、盐2g翻匀，沿锅边淋香醋3ml，关火出锅。"],"key": "蒜苔必须先干锅煸到起皱发软、彻底去水，直接炒会外生内生、涩口不香；蒜苔下锅前必须沥干水，否则溅油且易出水变黄。","tip": "干煸时怕溅油可加少许盐一起，盐能加速出水；肉用五花肉更香、用里脊更嫩；喜欢更下饭可加一小勺豆瓣酱。"},"韭菜炒蛋": {"time": "12分钟","level": "简单","servings": "2人份","ing": [{"n": "韭菜","q": "250g","a": "加到350g需分两次下锅，一次下会出水；减到150g则香味不足、盘底全是蛋"},{"n": "鸡蛋","q": "3个","a": "加到4个蛋量足、需多加油5ml；减到2个则只能配150g韭菜"},{"n": "盐","q": "4g（蛋液1g、菜3g）","a": "加到6g会明显发咸；减到2g则韭菜的辛香压不住、味道淡"},{"n": "食用植物油","q": "25ml（炒蛋20ml、炒韭5ml）","a": "加到40ml蛋更嫩滑但偏腻；减到15ml蛋易焦边"},{"n": "香油","q": "5ml","a": "加到10ml香油味足；减到2ml只作增亮用"},{"n": "料酒","q": "5ml","a": "加到10ml去蛋腥；减掉不减风味，可加1g白胡椒粉"},{"n": "白胡椒粉","q": "0.5g","a": "加到1g提香明显；减掉不加也成立"}],"steps": ["韭菜择洗干净，切掉1cm老根（根部泥沙多），再切3cm段，根部和叶子分开放。","鸡蛋3个打散，加盐1g、料酒5ml，充分搅匀至蛋液表面浮起一层细密泡沫。","锅烧至六成热下油20ml，倒入蛋液，中火等边缘鼓起后用铲子推炒成大块，约1分钟，蛋液刚凝固就盛出。","锅内余油5ml，中火下韭菜根部炒30秒，再下韭菜叶转大火快炒40秒，炒到叶子刚塌下、颜色深绿发亮即止。","蛋块回锅，加盐3g、白胡椒粉0.5g，大火翻10秒，淋香油5ml出锅。"],"key": "韭菜下锅后总共不超过1分钟，多炒就出水发黄、辛香全失；蛋必须炒成大块回锅，碎成蛋末就吃不出蛋香。","tip": "喜辣可加1勺剁椒在蛋液里；蛋液中加1勺清水（约15ml）炒出来更滑嫩；根部一定要炒透，生韭菜根发辛发苦。"},"玉米排骨汤": {"time": "90分钟","level": "简单","servings": "3-4人份","ing": [{"n": "猪肋排","q": "600g","a": "加到800g汤更浓需多加水200ml；减到400g用同样的料则味道会过浓，需减盐"},{"n": "甜玉米","q": "2根","a": "加到3根汤更甜更浓，要相应减少盐；减到1根清甜味不足，可加胡萝卜补甜"},{"n": "胡萝卜","q": "1根（约150g）","a": "加到2根汤色更红甜味更足；减掉不影响，是配色提甜的配角"},{"n": "姜","q": "20g（4片）","a": "加到30g姜味更足；减到10g去腥力弱"},{"n": "料酒","q": "20ml","a": "加到30ml去腥更彻底；减到10ml会有肉腥"},{"n": "盐","q": "6g","a": "加到9g汤偏咸；减到3g则汤味寡淡"},{"n": "白胡椒粉","q": "1g","a": "加到2g胡椒香更明显；减掉不加也成立"},{"n": "枸杞","q": "5g","a": "加到10g更多点缀；减掉也不影响，是最后撒的装饰"}],"steps": ["排骨冷水浸泡30分钟去血水，中间换两次水，剁成5cm长段；玉米切4cm圆段，胡萝卜切滚刀块。","冷水下锅加姜片、料酒，大火烧开撇净浮沫，浮沫必须撇干净，汤才清；再煮3分钟，捞出排骨用温水冲净。","换一次清水，一次加足约1200ml，放入排骨、玉米和姜片，大火烧开转小火炖50分钟。","加胡萝卜块继续炖20分钟，炖到玉米和胡萝卜都能用筷子轻松穿透。","加盐6g、白胡椒粉1g，撒枸杞再焖3分钟关火。"],"key": "盐必须最后放，中途加盐会让肉纤维收紧发柴、汤也不够清甜；焯水后的排骨用温水冲洗，才不会让汤变浑发苦。","tip": "选甜糯的水果玉米或黑糯玉米，粉玉米不甜；砂锅比铁锅出味更浓；隔夜汤回锅热一下更好喝，别反复煮沸。"},"凉拌黄瓜": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "黄瓜","q": "2根（约300g）","a": "加到3根需等比例增加调料；减到1根则一盘不够吃，调料会偏咸"},{"n": "大蒜","q": "15g（4瓣剁末）","a": "加到25g蒜味更冲；减到8g蒜香不足，可加2g辣椒粉"},{"n": "香醋","q": "15ml","a": "加到25ml酸味更明显，需把白糖减到3g；减到8ml发不出爽口的酸"},{"n": "生抽","q": "15ml","a": "加到25ml咸度上升，需减盐；减到8ml味道寡淡"},{"n": "辣椒油","q": "15ml","a": "加到25ml辣味更足；减到5ml基本不辣，可换成小米辣圈"},{"n": "白糖","q": "5g","a": "加到10g甜味更圆润；减到2g则咸酸太直接"},{"n": "香油","q": "5ml","a": "加到10ml香油味足；减到2ml只是提亮"},{"n": "盐","q": "4g（杀水用）","a": "加到6g出得多、底味偏咸；减到2g杀不出水、入味慢"},{"n": "熟白芝麻","q": "3g","a": "加到8g点缀更香；减掉不减风味"}],"steps": ["黄瓜洗净，先用刀背拍裂，再切成3cm段——拍裂的断面不规则，比刀切更容易吸味，这是这道菜的关键一步。","拍好的黄瓜加盐4g拌匀，静置10分钟，杀出黄瓜里的水分。","倒掉渗到盘底的水——腌足10分钟水就基本出尽，不倒水调料会被稀释、挂不住黄瓜，这一步不能省。","蒜切末，与香醋15ml、生抽15ml、白糖5g、辣椒油15ml、香油5ml调成一碗料汁，搅到白糖化开。","把料汁倒入黄瓜中拌匀，静置5分钟让味道渗进断面，撒上白芝麻装盘。"],"key": "黄瓜必须先拍裂、再用盐杀水并倒掉渗出的水，这两步决定它脆不脆、料汁挂不挂得住；腌够10分钟才入味，急着拌只吃个咸。","tip": "想更入味可提前拌好冷藏半小时；加几圈小米辣更解暑；拍黄瓜时刀背用力要稳，拍扁即可不要拍成泥。"},"皮蛋豆腐": {"time": "10分钟","level": "简单","servings": "2人份","ing": [{"n": "内酯豆腐","q": "1盒（400g）","a": "换成北豆腐需先蒸5分钟去豆腥；加到2盒则汁要减半，否则味淡"},{"n": "松花皮蛋","q": "2个","a": "加到3个摆盘更满，但膏体味会盖过豆腐；减到1个则盘子空一半"},{"n": "大蒜","q": "12g（3瓣剁末）","a": "加到20g蒜香更浓；减到6g香味偏淡"},{"n": "生抽","q": "20ml","a": "加到30ml咸度上升，需减盐；减到12ml则味道不够"},{"n": "香醋","q": "8ml","a": "加到15ml能解皮蛋的碱味；减到3ml则皮蛋的涩味会留在嘴里"},{"n": "辣椒油","q": "10ml","a": "加到18ml辣味更明显；减到3ml就是纯粹的咸鲜"},{"n": "香油","q": "5ml","a": "加到10ml香油味足；减到2ml只作提亮"},{"n": "盐","q": "1g","a": "加到3g会明显偏咸；减掉不加，因为生抽和皮蛋卤本身有咸度"},{"n": "葱花","q": "5g","a": "加到10g香气更足；减掉不减风味"}],"steps": ["内酯豆腐倒出沥水，刀刃蘸水切成1.5cm见方的块，铺在盘底，块与块之间留一点空隙。","松花皮蛋现剥现切，剥壳后每个切成4瓣——冷藏久放的皮蛋表面发灰、碱味重，切开发涩。","剥好的皮蛋摆在豆腐块上，蛋瓣的切面朝上，摆好静置1分钟让蛋液稍稍流到豆腐上，好看也便于入味。","蒜切末，与生抽20ml、香醋8ml、辣椒油10ml、香油5ml、盐1g在碗里搅匀，糖化开、无沉底即成料汁。","把料汁沿盘边均匀淋在豆腐和皮蛋上，静置2分钟让味道渗进去，撒上葱花即可上桌。"],"key": "皮蛋一定现剥现切，冷藏久放的皮蛋表面发灰、碱味重；料汁要一次调匀再淋，别分几次倒，否则味道不匀。","tip": "豆腐用内酯豆腐最嫩最滑；怕豆腥可先把豆腐块用开水焯30秒再摆盘；不吃辣就把辣椒油换成2ml香油。"},"虎皮青椒": {"time": "20分钟","level": "中等","servings": "2人份","ing": [{"n": "薄皮青椒","q": "300g（约6个）","a": "换成厚皮灯椒需划深些、煎到6分钟；加到450g要用两个锅，挤在一起压不出虎皮"},{"n": "大蒜","q": "20g（5瓣切片）","a": "加到30g蒜香更浓；减到10g蒜片不够香"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到10ml颜色淡、不入味"},{"n": "香醋","q": "15ml","a": "加到25ml酸味更突出，需减白糖5g；减到8ml酸香不足"},{"n": "白糖","q": "12g","a": "加到20g甜味盖过酸；减到6g则偏咸口"},{"n": "盐","q": "2g","a": "加到4g会偏咸；减掉不加，青椒自带微甜、靠酱油调味即可"},{"n": "菜籽油","q": "30ml","a": "加到45ml煎得更润不粘锅；减到20ml容易粘皮"},{"n": "豆豉","q": "10g（剁碎）","a": "加到20g咸香更浓，需减生抽5ml；减掉不加就是家常版咸鲜"}],"steps": ["青椒去蒂去籽，用手压扁把籽彻底碾掉，籽要碾净，洗净后用厨房纸彻底擦干表面水分并晾2分钟，有水下锅会溅油、也起不了虎皮；蒜切成薄片备用。","平底锅烧至五成热下菜籽油30ml，中火下青椒，用锅铲而不是手去压，翻动时压到两面各煎2-3分钟，煎到表皮鼓起虎皮斑、颜色由亮绿转为深绿带焦。","下蒜片和豆豉，小火炒30秒炒出香味，此时青椒已经软塌。","加生抽20ml、香醋15ml、白糖12g、盐2g，沿锅边淋入并快速翻匀，加盖焖1分钟让青椒回软吸味。","开盖大火收一下汤汁，青椒软塌但仍保持整条完整时立刻出锅。"],"key": "虎皮只能靠煎出来——表皮必须煎到起泡发斑才有虎皮纹，用水焩是焯青椒不是虎皮青椒；压青椒用锅铲压，手捏必破。","tip": "选薄皮的皱皮青椒或螺丝椒最容易出虎皮；没有豆豉可以省掉，咸度靠生抽；配一碗粥或拌面都合适。"},"白灼菜心": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "菜心","q": "400g","a": "加到600g焯水时间不变、需分两锅；减到250g则一盘只够两人尝味"},{"n": "大蒜","q": "15g（4瓣剁末）","a": "加到25g蒜香油亮；减到8g淋油会寡淡"},{"n": "蒸鱼豉油","q": "25ml","a": "加到35ml咸味更足；减到15ml味道偏淡，需加1g盐"},{"n": "蚝油","q": "8g","a": "加到15g鲜味更厚；减到3g鲜味单薄"},{"n": "白糖","q": "3g","a": "加到6g能中和豉油的咸；减掉不加会有点咸口"},{"n": "菜籽油","q": "20ml","a": "加到30ml蒜香更油润；减到12ml蒜末易焦"},{"n": "盐","q": "2g（焯水用）","a": "加到4g菜心偏咸；减到1g焯水水味不清"},{"n": "姜","q": "10g（3片）","a": "加到20g姜味更足；减到5g焯水去杂味作用弱"}],"steps": ["菜心洗净，对半剖开——根部有老梗，剖开才熟得均匀，剖口要切到梗心不断裂，剖完冲一遍凉水、沥干2分钟备用。","烧一锅水，加盐2g、几滴油和几片姜，水烧到完全沸腾。","下菜心烫1分半钟，菜梗刚透明、叶片仍是翠绿就立刻捞出，多一秒就会发黄。","捞出后立刻码盘，菜梗朝同一方向摆整齐，摆盘讲究就先把菜梗切齐再摆，摆好静置1分钟沥掉余水。","另起锅下菜籽油20ml，小火下蒜末15g，炒到微黄出香即关火。","加蒸鱼豉油25ml、蚝油8g、白糖3g，小火烧开约20秒，淋在菜心上。"],"key": "焯水时间必须卡在1分半钟内，超过2分钟菜心就软塌发黄、失去\"鲜\"字；油必须最后淋热油激蒜香，蒜末才香而不苦。","tip": "摆盘把菜梗朝同一方向码齐会好看很多；用高汤代替清水焯烫更鲜；蒜蓉一半生一半熟混合，蒜香层次更好。"},"香菇青菜": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "小青菜","q": "400g","a": "换成上海青、菜苔均可；加到600g要分锅炒，青菜会出水变黄"},{"n": "干香菇","q": "5朵（约15g）","a": "加到8朵香味更浓，需把泡菇水加到120ml；减到3朵味不足，要用蚝油补鲜"},{"n": "大蒜","q": "15g（4瓣切片）","a": "加到25g蒜香更浓；减到8g香菇的甜味出不来"},{"n": "生抽","q": "15ml","a": "加到25ml颜色深、需减盐；减到8ml挂汁淡"},{"n": "蚝油","q": "10g","a": "加到18g鲜味更厚；减到4g味偏淡"},{"n": "淀粉水","q": "30ml（淀粉6g+水24ml）","a": "加到50ml汁更稠挂菜；减到15ml会出清汤挂不住"},{"n": "菜籽油","q": "25ml","a": "加到35ml更香；减到15ml香菇易粘锅"},{"n": "盐","q": "3g","a": "加到5g偏咸，需减生抽5ml；减到1g则青菜水煮无味"},{"n": "白胡椒粉","q": "0.5g","a": "加到1g提香明显；减掉不加味道更清爽"}],"steps": ["干香菇用温水泡发30分钟，泡香菇的水静置后留用，香菇挤干水分切片——泡菇水是这道菜的天然高汤，倒掉就鲜味少一半。","青菜洗净对半剖开，剖到梗心让梗叶同步熟，再摊开彻底沥干3分钟；蒜切成薄片备用。","锅烧至五成热下油25ml，六成热下蒜片和香菇片，中火炒2分钟，炒到香菇变软、边缘微微焦黄并出香。","倒入80ml泡菇水烧开，加生抽15ml、蚝油10g、盐3g，淋淀粉水30ml勾成薄芡，汤汁浓稠即可。","下青菜转大火翻炒1分钟，炒到叶子塌下、梗仍带脆感，淋白胡椒粉翻匀出锅。"],"key": "香菇必须先干煸炒出香再加汤，直接煮只会寡淡无味；泡香菇的水是这道菜鲜味的核心，绝对别倒。","tip": "青菜梗厚要先焯30秒再回锅；想更香可加几粒干贝或虾米同炒；全程大火，最后1分钟不下锅就回锅，青菜会出水。"},"木须肉": {"time": "25分钟","level": "中等","servings": "2-3人份","ing": [{"n": "猪里脊","q": "200g","a": "用梅花肉或后臀尖均可；加到300g需分两锅炒；减到150g则不够夹饭"},{"n": "鸡蛋","q": "2个","a": "加到3个蛋香更足、需多加油5ml；减到1个则蛋香太淡"},{"n": "干木耳","q": "8g","a": "加到15g木耳更足；减到4g口感单薄，必须用冷水泡发不能热水"},{"n": "黄瓜","q": "100g","a": "加到150g更解腻；减掉不减风味，是配色配脆的配角"},{"n": "胡萝卜","q": "50g","a": "加到100g颜色更漂亮；减掉也不影响成菜"},{"n": "大葱","q": "30g（切马蹄段）","a": "加到50g葱香更足；减到15g香气弱，可用蒜末补"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足需减盐；减到10ml颜色发白"},{"n": "料酒","q": "15ml","a": "加到25ml去腥彻底；减到8ml腌肉有腥味"},{"n": "淀粉","q": "12g","a": "加到18g肉片更滑；减到6g肉片易老、勾芡挂不住"},{"n": "食用植物油","q": "40ml","a": "加到55ml更润；减到28ml需用不粘锅"}],"steps": ["木耳用冷水泡发30分钟洗净撕小朵，沸水焯1分钟；黄瓜、胡萝卜切菱形片，葱切马蹄段；里脊切薄片。","里脊加料酒10ml、生抽10ml、淀粉8g抓匀腌10分钟；另取小碗打散2个鸡蛋，加盐1g。","锅烧至六成热下油30ml，倒入蛋液，大火炒成蓬松大块，约1分钟即盛出——蛋久炒会老。","锅内留油10ml，下腌好的里脊大火滑散1分钟至变白，加葱段、胡萝卜片、木耳大火炒1分钟。","蛋块回锅，加黄瓜片、生抽10ml、盐1g、白胡椒粉，大火翻炒20秒，淋淀粉水（淀粉4g+水20ml）勾一层薄芡，翻匀出锅。"],"key": "木耳必须冷水泡发且充分焯煮，生木耳不可食用；蛋要单独炒到刚凝固就盛出、回锅只翻20秒，才能保持嫩滑大块。","tip": "老北京做法是加几片蒜同炒、更生猛；勾芡只勾薄芡，芡太厚会糊嘴；黄瓜临出锅前放才保持脆度。"},"水蒸蛋": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "鸡蛋","q": "3个","a": "加到4个需用260ml水、蒸12分钟；减到2个则羹量少一人份"},{"n": "温水","q": "240ml（约蛋液的1.5倍）","a": "加到300ml（2倍）蒸出来更嫩但晃；减到180ml蒸出来更硬更粗糙"},{"n": "盐","q": "3g","a": "加到5g偏咸；减到1g则蛋腥味明显"},{"n": "生抽","q": "10ml","a": "加到20ml咸味更足；减到5ml味道偏淡"},{"n": "香油","q": "5ml","a": "加到10ml香油味更足；减到2ml只是提香"},{"n": "料酒","q": "5ml","a": "加到10ml去蛋腥；减掉可加1g白胡椒粉"},{"n": "葱花","q": "5g","a": "加到10g点缀更香；减掉不减风味"}],"steps": ["鸡蛋打散，加盐3g、料酒5ml，用筷子朝一个方向打散到蛋液均匀、没有成团的蛋白。","倒入240ml约40℃的温水，搅匀后用细筛过滤两遍，蛋筋和泡沫滤掉，成品才细腻。","用小勺把表面浮沫全部撇净，撇1分钟到看不见泡沫为止——浮沫不撇，蒸出来表面就有蜂窝。","碗上盖一个盘子或扎几个小孔的保鲜膜，水开后上锅，中小火蒸10分钟。","关火焖2分钟再取出，表面淋生抽10ml、香油5ml，撒葱花。"],"key": "蛋液与温水按1:1.5，多了晃少了粗；过滤两遍加盖中小火蒸，蜂窝和气孔就消失了；蒸过头会起蜂窝，超过15分钟必粗糙。","tip": "想要更嫩可以用30℃的温水、把碗换成更深的碗并延长到13分钟；判断熟没熟看表面凝固无流动液体、中心微微晃动即可；出锅前淋几滴香油或猪油更滑。"},"土豆炖牛肉": {"time": "100分钟","level": "中等","servings": "4人份","ing": [{"n": "牛腩","q": "700g","a": "用牛腱子肉也行、口感更劲道；加到1kg要按比例加汤和焖煮时间"},{"n": "土豆","q": "2个（约400g）","a": "加到3个（600g）需晚放10分钟，否则炖成泥；减到1个不够吃"},{"n": "胡萝卜","q": "1根（约150g）","a": "加到2根汤更甜；减掉不影响，土豆单炖也好吃"},{"n": "姜蒜","q": "40g（姜20g、蒜20g）","a": "加到60g去腥更重；减到20g香料味不足"},{"n": "八角","q": "2颗","a": "加到4颗卤味更浓；减到1颗也够，多了会发苦"},{"n": "生抽","q": "30ml","a": "加到45ml咸度足需减盐；减到15ml颜色淡"},{"n": "老抽","q": "10ml","a": "加到20ml颜色更深、汤色更红；减到3ml颜色不够红亮"},{"n": "料酒","q": "30ml","a": "加到45ml去腥更彻底；减到15ml会有肉腥"},{"n": "冰糖","q": "15g","a": "加到25g汤色更红亮、甜味柔和；减到8g汤色偏淡"},{"n": "菜籽油","q": "30ml","a": "加到45ml煸出的牛肉更香；减到15ml煸不出油、成品偏干"}],"steps": ["牛腩切3cm见方的块，冷水浸泡30分钟去血水；土豆切滚刀块泡在清水里防氧化发黑，胡萝卜切滚刀块。","冷水下锅加姜片、料酒，大火烧开撇净浮沫煮5分钟，捞出用温水冲洗干净。","锅烧至六成热下菜籽油30ml，下姜蒜、八角小火炒1分钟出香，倒入牛肉块转中火翻炒3-4分钟至表面微焦收紧。","加生抽30ml、老抽10ml、料酒20ml、冰糖15g翻炒上色，一次加足约900ml热水，大火烧开转小火炖60分钟。","加土豆和胡萝卜块，继续炖25分钟，炖到土豆边角开始化开、汤汁浓稠。","加盐3g，大火略收汁让汤汁挂住土豆和牛肉即可。"],"key": "焯过的牛肉只能用温水冲，且中途绝不加冷水——冷水会让肌肉骤缩变柴；土豆必须晚放20分钟，早了会炖化成泥。","tip": "用高压锅上汽后转小火20分钟更省时；土豆选粉糯品种口感更好；一次加足热水，中途添水汤味会变淡；留两勺汤汁拌饭极香。"},"萝卜炖羊肉": {"time": "110分钟","level": "中等","servings": "4人份","ing": [{"n": "羊腿肉","q": "700g","a": "用羊排或羊腩可，羊腿肉最不柴；加到1kg需按比例加水和炖煮时间"},{"n": "白萝卜","q": "1根（约500g）","a": "加到2根（1kg）需晚放10分钟；减到半根则不够炖、不够清甜"},{"n": "姜","q": "30g（6片）","a": "加到50g姜味能压住膻；减到15g膻味会返上来"},{"n": "大葱","q": "30g（2段）","a": "加到50g葱香更足；减到15g香味弱"},{"n": "花椒","q": "10粒","a": "加到20粒麻味更重；减到5粒去膻作用有限"},{"n": "白胡椒粉","q": "3g","a": "加到5g胡椒香更突出；减掉羊肉味道会寡淡"},{"n": "料酒","q": "30ml","a": "加到45ml去膻彻底；减到15ml会有羊膻"},{"n": "生抽","q": "20ml","a": "加到30ml颜色深；减到10ml汤色淡"},{"n": "菜籽油","q": "30ml","a": "加到45ml能煸出更多羊油、汤更香；减到15ml羊肉煸不出油会发腻"},{"n": "盐","q": "4g","a": "加到6g偏咸；减到2g汤味不足"}],"steps": ["羊肉切4cm块，冷水浸泡1小时去血水，这是去膻最关键的一步；白萝卜切滚刀块。","冷水下锅加姜片、花椒、料酒，大火烧开撇净浮沫，浮沫要撇干净否则汤发浑发腥，再煮3分钟捞出用温水冲净。","锅烧至六成热下菜籽油30ml，下羊肉块中火煸炒4分钟，煸到表面收紧焦黄、边缘出油，逼出膻味物质。","加生抽20ml、料酒10ml炒匀，倒入约900ml热水和葱段姜片，大火烧开转小火炖70分钟。","加白萝卜块继续炖25分钟，炖到萝卜透明软糯、汤色发白，加盐4g和白胡椒粉3g调味，撒香菜。"],"key": "去膻靠三步：长时间冷水泡血水、焯水撇净浮沫、煸炒逼出膻味油，缺一步都会留味；萝卜必须晚放否则炖化、失去清甜。","tip": "白胡椒粉是这道菜的灵魂别省；炖时放几片白萝卜同炖能吸膻；香菜梗先下、叶子最后放；隔夜冷藏后回锅更香。"},"葱油拌面": {"time": "30分钟","level": "简单","servings": "2人份","ing": [{"n": "小葱","q": "150g","a": "加到200g葱油更香但要久炸；减到100g葱香偏薄，可加5g干辣椒"},{"n": "生抽","q": "40ml","a": "加到60ml咸味明显变重；减到25ml挂面不够味"},{"n": "老抽","q": "10ml","a": "加到20ml颜色更深；减到3ml酱汁颜色偏浅"},{"n": "白糖","q": "15g","a": "加到25g甜度上升、需减生抽；减到8g酱汁会发咸发苦"},{"n": "料酒","q": "20ml","a": "加到30ml去葱腥、酱汁更圆润；减到10ml会有生抽的发酵味"},{"n": "干虾米","q": "10g","a": "加到20g鲜味更足；减掉不加就是纯葱油版，可加5g白芝麻"},{"n": "食用油","q": "150ml","a": "加到200ml可多炸一次葱备用；减到100ml葱不能完全炸透、香味不足"},{"n": "面条","q": "250g（生重）","a": "换成300g需把葱油酱汁加到50ml生抽；减到200g面更筋道"}],"steps": ["小葱洗净后彻底晾干，葱白切细圈、葱绿切4cm长段，分开放——葱里带水下油锅会剧烈爆溅。","冷油下干虾米和葱白，小火慢炸5分钟，炸到葱白微黄、虾米出香。","再下葱绿继续小火慢炸8分钟，炸到葱段变成焦褐色，捞出葱段和虾米沥油备用。","葱油留在锅里，加生抽40ml、老抽10ml、白糖15g、料酒20ml，小火煮开2分钟到糖完全化开、酱汁微微发稠，立刻关火。","水开下锅煮面条，大火滚煮到八分熟（筷子夹起能弯、芯还有一点硬芯）立刻捞出沥干，趁热拌入葱油酱汁和炸好的葱段，快速拌匀装碗。"],"key": "葱必须全程小火慢炸到焦褐色，葱一旦炸黑就发苦、整罐油报废；葱油和酱汁一定要趁热拌进面，凉了挂不上味。","tip": "葱油一次多做，装玻璃罐冷藏能放两周，随时拌面拌饭；炸好的葱段最后拌入，保持酥脆；没有虾米可用干香菇丁代替。"},"蛋炒饭": {"time": "15分钟","level": "中等","servings": "2人份","ing": [{"n": "隔夜冷米饭","q": "400g（约2碗）","a": "用新蒸的米饭水分大，炒出来结块发黏；加到600g需分两锅炒"},{"n": "鸡蛋","q": "3个","a": "加到4个蛋更多、油要加到40ml；减到2个则不够香"},{"n": "腊肠","q": "60g","a": "用火腿肠80g也行、味道更淡；减到30g香味不足，可用干虾米10g补"},{"n": "小葱","q": "30g","a": "加到50g葱香更足；减到15g香气弱，可加1勺葱油"},{"n": "盐","q": "3g","a": "加到5g会偏咸，需减生抽；减到1g则饭不够味"},{"n": "白胡椒粉","q": "0.5g","a": "加到1g提香明显；减掉不加也成立"},{"n": "食用植物油","q": "30ml","a": "加到45ml米粒更亮不粘锅；减到20ml容易结块"},{"n": "生抽","q": "5ml","a": "加到12ml米粒上色更深；减掉不减风味，可全靠盐和腊肠的咸"}],"steps": ["隔夜冷米饭用手抓散到粒粒分开，抓3-4下捏不出成团才算散开；腊肠切小丁，葱切花，鸡蛋打散备用。","锅烧至六成热下油20ml，倒入蛋液大火炒成碎块，看到蛋刚凝固就盛出——蛋炒久了就老。","锅内补油10ml，下腊肠丁中火煸2分钟，煸到边缘微微透明、逼出油脂。","下米饭转中大火不停翻炒2-3分钟，用铲子压散结块，炒到米粒粒粒分明、互相跳动、表面微微发亮。","加盐3g、白胡椒粉0.5g、生抽5ml炒匀，把蛋碎倒回锅中翻匀，撒葱花出锅。"],"key": "必须用隔夜冷饭，新蒸米饭水分大，炒出来只会结块发黏；蛋要单独炒到刚凝固就盛出，和饭一起炒会老；全程中大火才能把饭\"炒跳\"。","tip": "想要金黄蛋炒饭可以把蛋液直接拌进冷饭里再下锅炒（金包银），火力要够大；配一碗紫菜蛋花汤刚好解腻。"},"肉末茄子": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "长茄子","q": "500g（约3根）","a": "换成圆茄子要减到400g并多吸油；加到700g需分锅煎，否则外焦内生"},{"n": "猪肉末","q": "150g","a": "换成牛肉末200g更香不腻；加到250g肉末太多会抢走茄子味"},{"n": "大蒜","q": "20g（5瓣）","a": "加到30g蒜香更浓；减到10g蒜香不足"},{"n": "郫县豆瓣","q": "20g","a": "加到35g辣味更重，需减生抽8ml；减到8g则只有咸鲜没有酱香"},{"n": "干辣椒","q": "5个","a": "加到8个辣味明显；减到2个基本不辣，可改用剁椒15g"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到10ml味道偏淡"},{"n": "蚝油","q": "10g","a": "加到18g鲜味更厚；减到4g鲜味单薄"},{"n": "白糖","q": "6g","a": "加到12g能中和豆瓣的咸和辣；减到2g偏咸口"},{"n": "食用油","q": "40ml","a": "加到60ml茄子更亮但偏腻；减到25ml需先用盐杀透水再煎"},{"n": "葱花","q": "10g","a": "加到20g点缀更香；减掉不减风味"}],"steps": ["茄子切3cm滚刀块，撒盐2g拌匀腌10分钟，然后用手挤干渗出的水——杀水是这道菜不油腻、不吸油的前提。","锅烧至六成热下油40ml，中火下茄子块摊平，煎4分钟至表皮金黄软塌，用铲子推到锅边。","锅内空出的位置下肉末，中火煸炒3分钟至煸出肉末自身油脂、变得酥香。","下蒜末、豆瓣酱和干辣椒段，小火炒1分钟，炒出红油和酱香——豆瓣一定要在肉末出油后下，干炒容易焦糊发苦。","加生抽20ml、蚝油10ml、白糖6g翻炒均匀，让肉末裹满茄子，再加50ml热水盖盖中火焖3分钟。","开盖大火收汁到油亮挂汁，撒葱花出锅。"],"key": "茄子先用盐杀水再煎，才不会像海绵一样疯狂吸油；豆瓣酱必须在肉末煸出油之后下锅，早下会焦；收汁到\"油亮挂汁\"即止，久收会干柴。","tip": "长茄子比圆茄子好，籽少肉嫩不易塌；想吃重辣可加20g豆瓣同时把生抽减到12ml；茄子用蒸的做法可省一半油。"},"红烧豆腐": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "北豆腐","q": "400g","a": "用内酯豆腐200g替代要先焯2分钟固定形状；加到600g需多煎3分钟"},{"n": "大蒜","q": "15g（4瓣切末）","a": "加到25g蒜香更浓；减到8g蒜香不足"},{"n": "小葱","q": "15g","a": "加到25g葱香更足；减到8g点缀变少"},{"n": "生抽","q": "25ml","a": "加到35ml咸度上升；减到15ml豆腐颜色发白"},{"n": "老抽","q": "5ml","a": "加到10ml颜色更深；减到2ml颜色不够红润"},{"n": "蚝油","q": "12g","a": "加到20g鲜味更厚；减到5g味道偏素"},{"n": "白糖","q": "5g","a": "加到10g能中和咸味；减到2g会发苦"},{"n": "料酒","q": "10ml","a": "加到20ml去豆腥更彻底；减到5ml豆腥味明显"},{"n": "淀粉水","q": "40ml（淀粉8g+水32ml）","a": "加到60ml汁更稠挂豆腐；减到20ml挂不住、汤寡淡"},{"n": "食用油","q": "30ml","a": "加到45ml煎出的豆腐更香；减到18ml容易粘锅"}],"steps": ["北豆腐切2.5cm见方的块，用厨房纸吸干表面水分——水多下锅会溅油、也难煎定型。","平底锅烧至五成热下油30ml，豆腐块平铺，中小火煎3分钟到底面金黄结壳，再翻面煎2分钟，煎出的这层皮是豆腐不碎的关键。","锅内留底油，下蒜末小火炒香，加生抽25ml、老抽5ml、蚝油12ml、白糖5g、料酒10ml和150ml热水烧开。","轻轻推入豆腐块，中小火焖6分钟让豆腐吸味，中途用锅铲背面轻推，不要翻炒。","加盐2g，分两次淋淀粉水40ml勾薄芡，汤汁浓稠挂住豆腐，撒葱花出锅。"],"key": "豆腐先煎定型再烧，全程只用锅铲背面轻推、一翻就碎；淀粉水要分两次淋，先调稀挂住豆腐再加浓汤汁，才既有型又不澥。","tip": "用北豆腐不用内酯豆腐，带皮的一面先煎更不易碎；不用油煎改用蒸的做法可省油；撒一把香菜或熟白芝麻都很搭。"},"干煸豆角": {"time": "35分钟","level": "中等","servings": "3人份","ing": [{"n": "四季豆","q": "400g","a": "换成豇豆300g也可、味道更筋道；加到600g需分锅煸，否则煸不透"},{"n": "猪肉末","q": "100g","a": "用牛肉末150g更香；减到50g则干香不足，可用油多放5ml补"},{"n": "干辣椒","q": "8个","a": "加到12个辣味很冲；减到4个辣度适中，更家常"},{"n": "花椒","q": "10粒","a": "加到20粒麻味突出；减到5粒仍有香气"},{"n": "大蒜","q": "20g（5瓣）","a": "加到30g蒜香更浓；减到10g蒜香不足"},{"n": "姜","q": "10g（3片）","a": "加到20g姜味更足；减到5g去腥作用弱"},{"n": "生抽","q": "20ml","a": "加到30ml咸味足需减盐；减到10ml挂汁不够"},{"n": "料酒","q": "10ml","a": "加到20ml去腥；减到5ml略有腥味"},{"n": "菜籽油","q": "40ml","a": "加到60ml煸豆角不粘锅、油香更足；减到25ml豆角容易粘锅"},{"n": "盐","q": "3g","a": "加到5g偏咸；减到1g则豆角寡淡"}],"steps": ["四季豆撕去两边的老筋，掰成6cm长段，洗净后用厨房纸彻底擦干——带水煸会溅油，而且水汽会影响成品的干香。","锅烧至五成热下油40ml，中火下豆角慢煸8-10分钟，边煸边用铲子压，煸到表皮起皱发白、彻底变软后捞出控油。豆角必须彻底煸熟，半生的含皂素会中毒。","锅内留油20ml，下肉末中火煸3分钟，煸到肉末出油、变得酥香。","下干辣椒段、花椒、姜蒜末，小火炒1分钟炒出香味。","倒回豆角，加生抽20ml、料酒10ml、盐3g、白糖3g，大火翻炒2分钟，让豆角干香挂汁、边缘微微起焦。"],"key": "豆角必须彻底煸熟到起皱发软，绝不能夹生——生的四季豆含皂素会引起中毒；下锅前擦干水，否则溅油且口感变湿。","tip": "省油可用空气炸锅200℃12分钟代替油煸，再回锅和肉末同炒；用牛肉末配干辣椒最香；煸好的豆角放凉后会变硬，回锅前可回温一下。"},"酸汤肥牛": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "肥牛卷","q": "350g（约2盒）","a": "加到500g需用1.5倍汤量，煮的时间不变；减到250g汤汁相对多、味道更浓"},{"n": "泡椒","q": "30g（剁碎）","a": "加到50g酸辣味更足，此时白糖要减量；减到15g只有辣没有酸"},{"n": "野山椒","q": "20g（剁碎）","a": "加到35g酸香更立体，是金汤的关键；减到8g金汤的酸度不足"},{"n": "大蒜","q": "25g（半切末半剁蓉）","a": "加到35g蒜香更浓；减到15g蒜香不足，可加5g姜末"},{"n": "黄灯笼辣椒酱","q": "20g","a": "加到35g辣度更足，色更正；减到10g颜色偏淡，需加5g红油"},{"n": "高汤或清水","q": "500ml","a": "加到700ml汤更多但味淡，需加10g盐；减到350ml汤浓味厚、可用高汤"},{"n": "莴笋","q": "150g（切薄片）","a": "加到250g垫底更多、配粥更好；减到80g垫底少"},{"n": "白胡椒粉","q": "3g","a": "加到5g胡椒辣更明显；减到1g酸汤的刺激感弱"},{"n": "淀粉水","q": "40ml（淀粉8g+水32ml）","a": "加到60ml汤更稠能挂住肥牛；减到20ml汤清不挂"}],"steps": ["肥牛卷自然解冻10分钟不要泡水；莴笋切薄片；泡椒、泡姜剁碎，蒜一半切末一半剁成蓉。","锅烧至五成热下油30ml，下泡椒碎、蒜蓉、野山椒和黄灯笼酱，小火炒3分钟，炒到红油析出、香气冲鼻——金汤的酸和辣全在这一步。","倒入高汤500ml和莴笋片，中火烧开煮2分钟，加盐3g、白胡椒粉3g调成金汤。","把肥牛卷逐片下锅，注意不要搅动，中火煮1分半钟，看到肉片边缘刚刚失去粉红色就关火，久煮会缩紧变老。","淋淀粉水40ml勾芡至汤微稠，起锅装盆，表面撒蒜末，淋一勺烧到冒烟的热油激出蒜香。"],"key": "肥牛下锅后绝不能搅动、不能久煮，1分半钟变色即关火才嫩；金汤的味道来自泡椒、野山椒、黄灯笼酱三件套，小火炒出红油是前提。","tip": "想要更酸可在最后加15ml白醋或柠檬汁；莴笋换成金针菇、豆腐皮都好；汤汁别倒，拌面极好。"},"清炒时蔬": {"time": "12分钟","level": "简单","servings": "2人份","ing": [{"n": "时令绿叶菜","q": "400g","a": "换成当季青菜、菠菜、苋菜均可；加到600g需分锅炒，一次下会出水变黄"},{"n": "大蒜","q": "15g（4瓣切片）","a": "加到25g蒜香更浓；减到8g蒜片不够香，可加2g姜末"},{"n": "盐","q": "3g","a": "加到5g会偏咸；减到1g则菜味寡淡"},{"n": "食用植物油","q": "20ml","a": "加到30ml更润；减到12ml菜叶容易粘锅"},{"n": "白胡椒粉","q": "0.5g","a": "加到1g提香；减掉不加更清爽"},{"n": "香油","q": "3ml","a": "加到8ml香油味足；减到1ml基本尝不出，只用于起锅提亮"}],"steps": ["绿叶菜择洗干净，菜梗长的对半剖开，让梗和叶同时熟，剖好的菜摊开沥水3分钟备用。","洗好的菜摊在滤篮里彻底沥干3分钟，抖得水基本滴净为止——带水下锅就变成煮青菜了。","锅烧至五成热下油20ml，六成热下蒜片，小火炒30秒出香，蒜片一变黄就要下菜。","转最大火下青菜，用铲子快速翻炒1分钟，炒到叶片刚刚塌下、菜梗还带脆劲、颜色深绿。","加盐3g、白胡椒粉0.5g，翻炒10秒立即关火出锅装盘，起锅前淋香油3ml。"],"key": "全程大火、总共1分钟内出锅，多炒就出水变黄、青菜香也散了；蒜片下锅不超过30秒，蒜黄了整锅就发苦。","tip": "当天的绿叶菜才需要清炒，蔫了或放过夜的不要用；已经焯过水的青菜别再下锅炒，会二次出水；焯过水的菜心可以直接淋热油生抽。"},"手撕包菜": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "包菜","q": "400g（约半颗）","a": "加到600g需分两锅炒，包菜出水后要炒更久；减到250g则份量不足"},{"n": "干辣椒","q": "6个","a": "加到10个辣味很冲；减到3个就是微微辣，可加1勺剁椒"},{"n": "大蒜","q": "20g（5瓣切片）","a": "加到30g蒜香更浓；减到10g蒜香不足"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到10ml挂汁淡"},{"n": "香醋","q": "15ml","a": "加到25ml酸味更突出，需减白糖5g；减到8ml酸香不足"},{"n": "白糖","q": "6g","a": "加到12g能中和醋的酸；减到2g则偏咸口"},{"n": "盐","q": "2g","a": "加到4g偏咸；减掉不加，靠生抽调味即可"},{"n": "菜籽油","q": "25ml","a": "加到35ml更香；减到15ml包菜容易粘锅、炒不出焦边"}],"steps": ["包菜用手撕成5cm左右的不规则片——手撕的断面不规则，边缘毛糙，比刀切更容易挂汁。","撕好的包菜洗净后摊开彻底沥干3分钟，抖两下不滴水为止——带水下锅会出水、也炒不出焦边。","锅烧至六成热下油25ml，下干辣椒段和蒜片，中火炒1分钟，炒出辣椒的香和蒜的辛。","转最大火下手撕包菜，快速翻炒1分半钟，炒到边缘微微焦黄、菜梗仍然脆。","沿锅边淋生抽20ml、香醋15ml、白糖6g、盐2g，大火翻30秒立刻出锅。"],"key": "手撕不用刀切，且下锅后只炒1分半钟——炒久了包菜出水就成了煮包菜；醋必须沿锅边淋，高温激出的酸香才立体。","tip": "想更脆可先干锅手撕煸1分钟去掉部分水分再加油炒；不喜辣就把干辣椒减到3个；配粥或拌饭都合适。"},"蒜蓉西兰花": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "西兰花","q": "400g（约1颗）","a": "换成菜花、芥蓝同理；加到600g焯水时间不变、需分锅炒"},{"n": "大蒜","q": "30g（剁蓉）","a": "加到45g蒜香极浓；减到15g蒜香不足，可加5g姜末"},{"n": "盐","q": "4g（焯水2g、炒2g）","a": "加到6g偏咸；减到2g则焯水水味不清"},{"n": "菜籽油","q": "20ml","a": "加到30ml更油亮；减到12ml蒜蓉易焦"},{"n": "淀粉水","q": "30ml（淀粉6g+水24ml）","a": "加到50ml汁更稠挂菜；减到15ml会挂不住、发水"},{"n": "蚝油","q": "8g","a": "加到15g鲜味更厚；减到3g味道偏淡"}],"steps": ["西兰花切成小朵，泡在淡盐水（1g盐加500ml水）里5分钟再冲洗干净。","用刀在花梗根部划个十字，切到梗心不断裂为止，划完用清水冲一遍、沥干2分钟，焯水时更容易入味、熟得也更快更均匀。","水烧开加盐2g和几滴油，下西兰花焯1分半钟，捞出立刻过一遍凉开水——过凉开水是颜色保持翠绿不发黄的关键，捞出后沥干。","锅烧至五成热下油20ml，六成热下蒜蓉30g，小火炒40秒到微黄出香就下菜，蒜蓉一旦焦了就发苦。","下西兰花转大火翻炒1分钟，加蚝油8g、盐2g，淋淀粉水30ml勾一层薄芡，翻匀出锅。"],"key": "焯水后必须过凉开水，颜色才能保持翠绿不发黄；蒜蓉全程小火、炒到微黄立刻下菜，焦了整锅发苦；焯水别超过2分钟，久了软烂失去脆。","tip": "蒜蓉一半生一半熟混合，蒜香层次最好；焯水时加几滴油能让花球更亮；西兰花梗削皮切片一起炒，别浪费。"},"红烧肉": {"time": "100分钟","level": "稍难","servings": "4人份","ing": [{"n": "带皮五花肉","q": "700g","a": "用五花腩600g也行、肥瘦更匀；加到1kg需按比例加水和焖煮时间"},{"n": "冰糖","q": "35g","a": "加到50g糖色更亮更甜，需减老抽3ml；减到20g糖色偏淡、发苦"},{"n": "生抽","q": "40ml","a": "加到60ml咸味足需减盐；减到25ml颜色不够深"},{"n": "老抽","q": "10ml","a": "加到18ml颜色更深；减到3ml成菜颜色偏淡"},{"n": "料酒","q": "40ml","a": "加到60ml去腥彻底；减到20ml会有肉腥"},{"n": "姜","q": "25g（5片）","a": "加到40g姜味更足；减到15g去腥作用弱"},{"n": "大蒜","q": "20g（4瓣）","a": "加到30g蒜香更浓；减到10g蒜香不足"},{"n": "八角","q": "2颗","a": "加到4颗卤味更浓；减到1颗也够，多了发苦"},{"n": "桂皮","q": "1小段","a": "加到2段香气更厚；减掉不加也可以，只是少了点暖香"},{"n": "菜籽油","q": "30ml","a": "加到45ml煸出的油更香；减到15ml肉块易粘锅"}],"steps": ["五花肉切3cm见方的块，冷水下锅加姜片、料酒、葱段，大火烧开撇净浮沫煮5分钟，捞出用温水冲洗干净，务必温水。","锅烧热不放油，下肉块中火干煸3-4分钟，煸出多余的油脂，煸到四面金黄、肉块微微卷缩，这一步是成品肥而不腻的关键。","锅内留油20ml，小火下冰糖35g，不停搅动熬到糖融化、起小泡、由白转琥珀色——一变深就立刻下肉，晚一秒就发黑发苦。","倒入肉块快速翻动裹上糖色，加生抽40ml、老抽10ml、料酒20ml、姜蒜、八角、桂皮翻炒均匀，再加约700ml热水没过肉块。","大火烧开转小火加盖焖60分钟，炖到筷子能轻松穿透肥肉、瘦肉却不散开的程度。","开盖转大火收，不停翻动让每块肉均匀挂上亮汁，汤汁浓稠如能挂勺时加盐3g，关火出锅。"],"key": "炒糖色是整道菜的成败点：必须小火、看到琥珀色立刻下肉，糖过火就发黑发苦；焯好的肉只用温水冲，冷水会让肉骤缩变柴。","tip": "加半块老豆腐或一把干黄豆同炖，能吸油解腻又添软糯口感；收汁留一点汤拌饭最好吃；用砂锅焖比铁锅更软糯。"},"香菇滑鸡": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "鸡腿肉","q": "400g","a": "用鸡胸肉300g也行但更易柴；加到600g需分锅滑炒"},{"n": "干香菇","q": "6朵（约20g）","a": "加到10朵香味更浓，泡菇水要加到150ml；减到4朵味淡，需用蚝油补鲜"},{"n": "姜","q": "15g（4片）","a": "加到25g姜味更足；减到8g去腥力弱"},{"n": "大蒜","q": "15g（4瓣切末）","a": "加到25g蒜香更浓；减到8g蒜香不足"},{"n": "小葱","q": "15g","a": "加到25g葱香更足；减到8g点缀少"},{"n": "生抽","q": "20ml","a": "加到30ml咸度足；减到12ml颜色和咸度都偏淡"},{"n": "蚝油","q": "12g","a": "加到20g鲜味更厚；减到5g鲜味不足"},{"n": "料酒","q": "15ml","a": "加到25ml去腥更彻底；减到8ml会有鸡腥味"},{"n": "淀粉","q": "12g","a": "加到18g鸡肉更滑嫩；减到6g鸡肉易柴"},{"n": "食用植物油","q": "20ml","a": "加到30ml煎鸡更香滑；减到12ml容易粘锅"}],"steps": ["干香菇用温水泡发30分钟，泡菇水静置后留用（这是这道菜的鲜味来源），香菇挤干水分切片，切片比整朵更入味；鸡腿肉切1.5cm厚的片。","鸡肉加生抽10ml、料酒10ml、淀粉10g、蛋清1个、白胡椒粉1g、盐2g抓匀，腌15分钟到肉片表面发黏、挂上薄浆。","锅烧至五成热下油20ml，下姜蒜末和香菇片，中火炒2分钟，炒到香菇变软、香气出来。","把上浆的鸡肉平铺入锅，中火煎2分钟到底面定型，再翻炒几下均匀，接着倒入120ml泡菇水，盖盖中火焖6分钟。","开盖加蚝油12ml、生抽10ml，淋淀粉水（淀粉2g+水10ml）勾薄芡，让汤汁均匀裹在鸡片上，撒葱花出锅。"],"key": "鸡肉必须上蛋清淀粉浆并腌足15分钟，腌够才滑嫩；下锅后先煎2分钟定型再焖，中途不要乱翻，一翻肉片就散、浆就掉。","tip": "用鸡腿肉不用鸡胸肉，鸡胸容易柴；泡菇水一定要滤掉沉渣再用；香菇可提前煸香再和鸡一起焖，香气更足。"},"梅菜扣肉": {"time": "2.5-3小时（含蒸制）","level": "稍难","servings": "4-5人份","ing": [{"n": "带皮五花肉","q": "750g","a": "减到400g则一人份不够、扣不成整块；加到1kg需蒸3小时以上，中间层容易夹生"},{"n": "梅干菜","q": "80g（干）","a": "必须是梅州产盐渍发酵的乌梅干，减到30g吸味不够发不出梅香；加到150g只剩咸菜味盖过肉香"},{"n": "腐乳","q": "2块（红腐乳）","a": "减到1块上色和咸香偏淡；加到3块太咸发酸，蒸久了肉会发硬"},{"n": "姜、蒜","q": "姜4片、蒜4瓣（蒜拍碎剁蓉）","a": "姜减到2片去腥力弱、加到8片抢味发苦；蒜减到2瓣蒜香不足、加到6瓣会抢走梅菜的清甜"},{"n": "老抽","q": "1勺（15ml）","a": "只用于上色，减半虎皮颜色偏浅；加到2勺上色过深发苦"},{"n": "生抽","q": "3勺（45ml）","a": "减到2勺梅菜和肉都偏淡；加到4勺咸度过高"},{"n": "白糖","q": "2勺","a": "梅干菜本身带回甜，减到1勺略苦；加到3勺过甜压住肉香"},{"n": "料酒","q": "2勺","a": "煮肉去腥用，减到1勺酒味不足；加到3勺酒味冲"},{"n": "八角、桂皮","q": "八角2个、桂皮1小段","a": "八角加到4个甜香过重；桂皮超过1段药味明显"},{"n": "食用油","q": "500ml（炸皮用）","a": "油不够会粘锅炸不匀；用锅底余油煎皮可省一半用量但虎皮效果差"}],"steps": ["梅干菜提前用温水泡发20分钟，反复搓洗掉泥沙与表层盐分，捞出挤干水切碎备用；五花肉整块冷水下锅，加姜片、料酒，水开后撇净浮沫，中火煮20分钟至筷子能扎透但肉皮尚未破开，捞出趁热在肉皮上抹匀老抽并用竹签扎满小孔。","锅中放油烧至六成热，肉皮朝下入锅，用锅铲压住肉皮防止卷起，小火炸2-3分钟至肉皮鼓起密实小泡呈棕红色，关火把肉直接放入温水中浸泡10分钟，让皮肉分离发胀成虎皮状。","取一只深碗，碗底铺几片洗净的大白菜帮或芋头片（吸汁防粘），把五花肉切成8mm厚、10cm长的大片，皮朝下整齐码入碗中，每片之间紧贴不留大空隙。","锅中下2勺油，小火下姜蒜末爆香，倒入梅干菜碎炒2-3分钟至水分收干、香气冲出发亮，加入压碎的腐乳、生抽、白糖、料酒和小半碗清水，搅匀成浓稠的梅菜酱。","把梅菜均匀铺在扣肉上并压实，表面再摆几片姜，浇入碗中剩余的梅菜酱汁。","蒸锅上汽后放入碗，大火蒸2小时至2小时半，中途需添一次热水防止烧干；关火焖5分钟再端出。","取一只大盘扣在蒸碗上，双手按住盘沿迅速倒扣，扣肉完整落在盘中；锅内留少许原汁，加半勺糖和一点淀粉水收稠，淋在扣肉上，撒葱花。"],"key": "扣肉的“颤巍巍”来自两个关键：肉皮必须先炸成虎皮再用温水泡发，蒸后才有胶质软糯的弹性；肉片要皮朝下、紧贴着码满整碗，蒸完翻扣才能连成整块不散。","tip": "赶时间可用高压锅上汽后压40分钟代替蒸2小时；梅干菜务必自己挑盐渍发酵的梅州乌梅干，市售甜梅菜香气浮、挂不住汁。给忌口的人做时把老抽减半、盐减1g。"},"粉蒸排骨": {"time": "1小时10分钟","level": "简单","servings": "3-4人份","ing": [{"n": "猪肋排","q": "600g","a": "斩成5cm长段，换成小排400g最嫩但份量少；加到900g需分两碗蒸"},{"n": "蒸肉米粉","q": "150g","a": "减到80g露肉不挂粉口感发柴；加到220g米粉盖过肉味、入口发干"},{"n": "南瓜","q": "250g","a": "垫底吸汁用，切1.5cm厚片；换成土豆250g更粉糯；减到100g垫底不够"},{"n": "腐乳","q": "1块","a": "压泥腌肉，减半则咸香不足；加到2块排骨太咸蒸后发硬"},{"n": "生抽","q": "2勺","a": "减到1勺颜色淡味道单薄；加到3勺发咸"},{"n": "蚝油","q": "1勺","a": "减半鲜味不够；加到2勺会发齁"},{"n": "料酒","q": "2勺","a": "去腥用，减到1勺腥味残留；加到3勺酒味冲"},{"n": "白糖","q": "1勺","a": "减半略苦；加到2勺过甜"},{"n": "姜末、蒜末、白胡椒粉","q": "姜末1勺、蒜末1勺、白胡椒粉1g","a": "姜蒜减到半勺去腥力弱、加到2勺会抢米粉的米香；白胡椒粉减半几乎尝不到、加到3g发冲"},{"n": "菜籽油","q": "2勺","a": "先用油拌排骨再裹粉才挂得住，减到1勺米粉发干；加到4勺成品油腻"}],"steps": ["排骨斩成5cm长段，冷水浸泡30分钟泡出血水，中途换一次水，冲净后沥干。","排骨加压成泥的腐乳、生抽、蚝油、料酒、糖、姜末、蒜末、白胡椒粉抓匀，码味20分钟。","蒸肉米粉先与1勺菜籽油拌匀使其微微湿润，南瓜切1.5cm厚块铺在碗底。","把腌好的排骨逐块放入盆中，撒上拌过油的蒸肉米粉，用手抓匀，让每块排骨都薄薄挂住一层白粉且粉面略粗糙。","排骨整齐码放在南瓜上，粉面朝上，不要互相叠压太紧。","蒸锅水烧开后上锅，大火蒸40分钟，中途不揭盖；至排骨完全脱骨、粉粒吸水变成半透明即熟。","出锅撒葱花，可沿碗边淋一勺烧热的油激香。"],"key": "米粉不能干撒，必须先用油拌湿再裹，否则蒸时米粉吸油不匀，局部发白局部发干；排骨腌足20分钟再上粉，蒸出来才有咸香入味。","tip": "自制蒸肉米粉可用大米与糯米按7:3加花椒八角小火炒香后打粗粒，只做一次可多打些冷冻备用。牙口不好的人可把蒸制延到50分钟，排骨更脱骨。"},"干锅花菜": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "有机花菜","q": "500g","a": "掰小朵后用盐水泡，普通花菜梗太硬要削掉；加到700g需先焯水否则炒不透"},{"n": "五花肉","q": "150g","a": "切薄片，减到80g无肉香；加到250g会变成肉炖花菜"},{"n": "干辣椒","q": "8个","a": "剪段去籽可减呛；加到12个川味更正宗，超过15个会盖过花菜"},{"n": "花椒","q": "1勺","a": "减到半勺麻味不足；加到2勺麻得发木"},{"n": "姜蒜","q": "姜3片、蒜4瓣（切片）","a": "姜减到1片去腥弱、加到6片出苦味；蒜减到2瓣香气弱、加到6瓣发苦"},{"n": "郫县豆瓣酱","q": "1勺","a": "必须用红油豆瓣，减半色泽不足；加到2勺偏咸且抢味"},{"n": "青红椒","q": "各1个","a": "配菜增色增脆，减量可省；加到2个量太多抢花菜"},{"n": "生抽、白糖","q": "生抽1勺、白糖1g","a": "生抽减半味道淡、加到2勺发咸；白糖减到0.5g略苦、加到3g发甜"},{"n": "菜籽油","q": "3勺","a": "油少会粘锅花菜出水，减到1勺就成水煮花菜；加到5勺过于油腻"}],"steps": ["花菜掰成3cm左右的小朵，用淡盐水浸泡10分钟去除杂质和虫卵，捞出用厨房纸彻底擦干表面水分（有水会变成水煮花菜）。","冷锅下1勺菜籽油，中火下花椒和干辣椒段煸出香味后把辣椒花椒倒出备用——这是干煸花菜的核心。","锅烧至冒烟，下2勺油，油热后放入五花肉片煸炒，油被煸出、肉片微卷发透明。","转大火下姜蒜片爆香，倒入擦干的花菜翻炒2-3分钟，直到花菜边缘微微焦黄、表面起皱。","下豆瓣酱炒出红油，加生抽、白糖、盐快速翻匀。","倒入第一步煸好的干辣椒花椒和青红椒块，大火翻炒30秒立刻出锅。"],"key": "花菜必须先干锅煸出焦香（表面有虎皮皱褶）再合炒，直接下锅炒只会软塌发白；下锅前一定要彻底沥干水，这是干锅花菜与水煮花菜的分水岭。","tip": "正宗干锅花菜全程不放一滴汤汁。若想颜色油亮可在出锅前淋半勺烧到冒烟的热油；素版可用香干替代五花肉。"},"蚝油生菜": {"time": "8分钟","level": "简单","servings": "2-3人份","ing": [{"n": "生菜","q": "400g","a": "掰成大片，减到250g一盘不够；加到600g必须分两锅，否则出水变烂"},{"n": "蚝油","q": "2勺（30ml）","a": "减到1勺鲜味不足；加到3勺发咸发黏"},{"n": "蒜","q": "3瓣","a": "切末，减到1瓣香气不足；加到5瓣会有生蒜冲味"},{"n": "白糖","q": "半勺","a": "提鲜不显甜，减到1/4勺几乎尝不出；加到1勺偏甜"},{"n": "盐","q": "1g","a": "生菜本身带淡咸，减到0.5g即可；加到3g过咸"},{"n": "水淀粉","q": "1勺","a": "勾薄芡让芡汁挂叶，加到2勺会变成厚芡；减半挂不住汁"},{"n": "高汤或清水","q": "50ml","a": "加到150ml会冲淡蚝油；减到20ml调不开味"},{"n": "菜籽油","q": "1勺","a": "减半容易炒焦；加到2勺过于油腻"}],"steps": ["生菜掰成大片洗净，甩干表面水分；蒜切细末。","锅烧到冒烟，下菜籽油，六成热时倒入蒜末炒香约20秒。","转最大火倒入生菜，快速翻炒30-40秒，看到叶片刚塌下、边缘微微发蔫立刻准备出锅。","加蚝油、白糖、盐和50ml高汤，快速翻匀。","淋入水淀粉勾一层薄芡，翻两下让芡汁挂在菜叶上，立即装盘。"],"key": "全程最大火、40秒内出锅，靠镬气和速度取胜；下锅前必须甩干水，否则一锅水就成煮生菜，蚝油也会被冲淡。","tip": "若想更清爽可改白灼做法——焯水后过冰水，另调蚝油汁淋上，但粤式正宗的炒法镬气更足。"},"韭菜炒豆芽": {"time": "8分钟","level": "简单","servings": "2人份","ing": [{"n": "绿豆芽","q": "300g","a": "掐去头尾根须；换成黄豆芽更粗更爽但要焯水去豆腥；加到450g要分两次炒"},{"n": "韭菜","q": "150g","a": "切4cm段，减到80g香味不足；加到250g出水变软"},{"n": "干辣椒","q": "2个","a": "剪段，可省；加到4个微辣"},{"n": "蒜末","q": "1勺","a": "减半香气弱；加到2勺会发苦"},{"n": "盐","q": "2g","a": "减到1g偏淡；加到4g过咸"},{"n": "生抽","q": "1勺","a": "减到半勺味道寡淡；加到2勺发咸"},{"n": "香醋","q": "1勺","a": "沿锅边激醋增香，减半味道平淡；加到2勺会发酸"},{"n": "白胡椒粉","q": "1g","a": "减半几乎无味；加到3g发冲"},{"n": "菜籽油","q": "1.5勺","a": "减到1勺易粘锅；加到3勺过于油腻"}],"steps": ["豆芽掐去头尾和根须洗净沥干；韭菜洗净切4cm段，韭菜根与叶分开放。","锅烧热下菜籽油，六成热下干辣椒段和蒜末爆香。","转大火倒入豆芽翻炒1分钟，至根须透明、豆芽略软但仍挺。","先下韭菜根部炒20秒，再下韭菜叶大火炒40秒至断生。","加盐、生抽、白胡椒粉，沿锅边淋入香醋，翻匀后立刻出锅。"],"key": "韭菜分两次下锅（根先、叶后）才熟得均匀；豆芽必须大火快炒，超过2分钟就会软塌出水失去爽脆。","tip": "起锅前沿锅边淋一勺醋是提香关键，能让豆芽爽脆不发酸；喜欢更香可把干辣椒换成蒜苗头同炒。"},"糖醋里脊": {"time": "35分钟","level": "中等","servings": "3-4人份","ing": [{"n": "猪里脊","q": "300g","a": "切1cm粗5cm长条；换成梅花肉更嫩但出油多；加到450g需分两锅炸"},{"n": "鸡蛋","q": "1个","a": "只取蛋清挂糊，减半挂不住炸后掉粉；加到2个糊过厚发硬"},{"n": "淀粉","q": "50g","a": "减到25g挂不住糊，炸后表面光秃；加到80g外壳太厚发硬"},{"n": "番茄酱","q": "2勺","a": "减到1勺颜色偏淡；加到3勺酸甜变成番茄味盖住肉香"},{"n": "白糖","q": "3勺","a": "减到2勺不够挂汁；加到4勺甜得发腻"},{"n": "香醋","q": "4勺","a": "减到2勺不够酸；加到6勺太酸盖住甜味"},{"n": "生抽","q": "1勺","a": "减半只够提鲜不上色；加到2勺汁发黑发苦"},{"n": "清水","q": "100ml","a": "加到150ml汁稀挂不住；减到60ml容易糊锅"},{"n": "料酒、盐","q": "料酒1勺、盐1g","a": "腌肉去腥用，料酒减半腥味残留、加到2勺酒味冲；盐减半味淡、加到3g会先咸后被糖盖住"},{"n": "食用油","q": "约800ml（炸制用）","a": "油不够会粘锅；炸好沥干可减到600ml"}],"steps": ["里脊逆纹切1cm粗、5cm长的条，加料酒和盐抓匀腌10分钟，加蛋清抓至发黏，再加淀粉抓到每根均匀挂上厚厚一层糊。","锅中倒油烧至六成热（筷子插入冒小泡），下里脊条炸2分钟至外层定型、表面微黄，捞出摊开。","油温升到八成热（约200℃），把里脊回锅复炸40秒至外壳金黄酥脆、声音清脆，捞出控油备用。","另起干净锅，淋少许油下番茄酱小火炒散出红油，加白糖、香醋、生抽、清水，小火熬煮2分钟至汤汁浓稠、能把勺背挂住。","倒入炸好的里脊快速翻匀，让每根都挂满糖醋汁，撒熟白芝麻立即出锅。"],"key": "复炸是外壳酥脆的唯一保证：第一次低温炸定型、第二次高温逼油定脆；只炸一次的糖醋里脊放5分钟就回软。","tip": "糖醋汁基础比例是糖:醋=3:4，可加半勺蜂蜜增亮；给孩子吃改成糖:醋=1:1.5做甜口版，但酸甜汁挂汁时长要缩短。炸油倒出滤渣可重复用两次。"},"酸辣鸡杂": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "鸡胗","q": "200g","a": "去筋膜改花刀切薄片，减到100g配料太多抢味"},{"n": "鸡肝","q": "150g","a": "减到80g口感单薄；加到250g需多焯1分钟"},{"n": "鸡肠","q": "100g","a": "剪去多余油脂再洗净，减到50g份量少"},{"n": "泡椒","q": "4个","a": "酸辣的灵魂，减到2个味道单薄；加到6个会盖住鸡杂本身味道"},{"n": "干辣椒、花椒","q": "干辣椒5个（剪段）、花椒1勺","a": "干辣椒减到2个几乎不辣、加到8个偏辣；花椒减半麻味不足、加到2勺麻得发木"},{"n": "姜末、蒜末","q": "各10g","a": "减到5g去腥力弱；加到各20g抢味发苦"},{"n": "香醋","q": "2勺","a": "减到1勺酸辣不足；加到3勺过酸盖住鲜味"},{"n": "白胡椒粉","q": "2g","a": "减半味淡；加到5g发冲"},{"n": "生抽、料酒","q": "各1勺","a": "减半味道寡淡；各加到2勺发咸有酒味"},{"n": "食用油","q": "2勺","a": "油少易粘锅，减到1勺会粘；加到4勺过于油腻"}],"steps": ["鸡胗去掉表面筋膜改十字花刀再切薄片，鸡肝切薄片，鸡肠剪成3cm段洗净；全部加料酒和姜片抓匀腌15分钟去腥。","烧一锅水，下姜片葱段，水开后放入鸡杂焯40秒，颜色一变立刻捞出，用温水冲净表面浮沫并沥干（焯久了会变老）。","锅烧热下2勺油，五成热下干辣椒段和花椒小火炒香，加泡椒片和姜蒜末炒出酸辣味。","转大火倒入鸡杂，快速翻炒1分半，至肉片变白卷曲、边缘微焦。","沿锅边淋入香醋，加白胡椒粉、生抽翻匀，撒葱段出锅。"],"key": "鸡杂焯水后必须冲净再炒，残留血水会发腥；全程大火不超过2分钟，超过就咬不动，鸡胗会变韧。","tip": "最正宗是川式泡椒味——泡椒先单独剁碎炒香比整片下锅更出味，配干锅或啤酒最合适。不吃内脏可全部换成鸡翅根同法。"},"冬瓜排骨汤": {"time": "1小时10分钟","level": "简单","servings": "3-4人份","ing": [{"n": "猪肋排","q": "500g","a": "斩5cm段，减到300g汤味淡需另加高汤；加到700g要换大锅"},{"n": "冬瓜","q": "400g","a": "去皮切1.5cm块，皮和瓤都能用；加到600g会变瓜盅"},{"n": "姜","q": "4片","a": "切片，减到2片去腥弱；加到8片发辛"},{"n": "料酒","q": "2勺","a": "焯水去腥用，减到1勺酒味残留；加到3勺酒味冲"},{"n": "盐","q": "3g","a": "出锅前再放，早放肉会发紧变柴；加到6g过咸"},{"n": "白胡椒粉","q": "2g","a": "减到1g几乎尝不到；加到5g发冲"},{"n": "枸杞","q": "10g","a": "减半点缀即可；加到30g汤会发甜"},{"n": "清水或高汤","q": "1500ml","a": "加到2000ml汤味变淡；减到1000ml需改用高压锅"},{"n": "菜籽油","q": "1勺","a": "煸排骨用，可省；加到3勺汤面浮油多"},{"n": "葱花","q": "1根","a": "装饰用，可省"}],"steps": ["排骨冷水下锅，加姜片和料酒，水开后撇净浮沫，捞出用温水冲洗干净（温水冲能保持肉不柴，冷水冲会让肉收紧发柴）。","另起一锅加1500ml清水，放排骨和姜片，大火烧开转小火炖40分钟。","冬瓜去皮去瓤切1.5cm厚块，炖到排骨能用筷子戳透时把冬瓜下锅，继续炖15分钟至冬瓜透明。","加盐和白胡椒粉调味，撒枸杞再煮2分钟。","关火撒葱花，连汤带肉盛出。"],"key": "排骨焯水后必须用温水冲净浮沫，汤才清亮；盐一定要出锅前再放，早放会让肉纤维收紧、炖不烂。","tip": "想更清甜可加几颗红枣；冬瓜皮别削太厚，削下的皮可以一起下汤煮10分钟再捞出，汤会明显更清甜。"},"麻婆豆腐": {"time": "25分钟","level": "稍难","servings": "3人份","ing": [{"n": "嫩豆腐","q": "400g","a": "北豆腐太硬不合适，加到600g需分锅否则嫩豆腐多会出水"},{"n": "牛肉末","q": "100g","a": "用牛肉粒150g更香；减到50g少了肉臊的酥香"},{"n": "豆瓣酱、豆豉","q": "郫县红油豆瓣2勺、豆豉10g（剁碎）","a": "豆瓣必须是郫县红油，减到1.5勺色泽不足、3勺过咸；豆豉减到5g香气弱、加到20g发苦"},{"n": "蒜末、姜末","q": "各1勺","a": "减半去腥和爆香不足；加到2勺抢味"},{"n": "辣椒面","q": "1勺（二荆条）","a": "减半辣味不够；加到2勺麻味盖过香辣"},{"n": "花椒粉","q": "2g","a": "起锅前撒，减到1g麻味不显；加到4g麻得舌头发木"},{"n": "蒜苗","q": "2根","a": "切段，减到1根香味不足；加到4根会抢味"},{"n": "高汤","q": "200ml","a": "清水会寡，加到300ml味淡"},{"n": "淀粉水、蛋清","q": "淀粉水30ml（分三次）、蛋清1个","a": "淀粉水一次倒足会澥汤，必须分三次；减到15ml挂不住豆腐。蛋清减半牛肉末会散、加到2个发黏"},{"n": "菜籽油","q": "3勺","a": "油少豆瓣炒不出红油，减到1勺颜色发暗；加到5勺过于油腻"}],"steps": ["豆腐切2cm见方，放淡盐水中浸5分钟再用清水冲净沥干；牛肉末加蛋清和1勺淀粉水抓匀腌10分钟。","锅烧热下2勺菜籽油，四成热下牛肉末，中火煵3分钟至酥香发干、粒粒分明。","转小火下豆瓣酱炒2分钟，炒到油色红亮、香气冲出，再下豆豉、姜蒜末、辣椒面炒1分钟。","倒入高汤烧开，勾入第一次薄芡（这是麻婆豆腐三次勾芡的第一次），转中火下豆腐块，加盖焖2分钟，用锅铲背轻轻推匀，全程不可翻炒。","汤汁重新收稠后淋第二次淀粉水，让芡汁挂住豆腐块，再补第三次极薄的芡收亮。","起锅撒蒜苗段和花椒粉，最后淋一勺烧到冒烟的热油激出麻辣香。"],"key": "三次勾芡是麻婆豆腐的灵魂：第一次定味定形、第二次挂体、第三次提亮亮芡，一次性倒足会让豆腐挂不住芡、汤会澥；下锅后只能推不能翻，否则豆腐碎成渣。","tip": "麻婆豆腐讲究麻辣烫酥嫩鲜：酥是牛肉末、烫是滚汁，上桌后一分钟内必须吃。怕辣可把辣椒面减半并增加豆瓣酱量，麻辣不减。"},"回锅肉": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "二刀五花肉","q": "400g","a": "带皮五花才卷得成灯盏窝，减到250g一人份；加到600g需多煮15分钟"},{"n": "蒜苗","q": "150g","a": "斜切马耳段，减到80g蒜香不足；加到200g会抢肉味"},{"n": "郫县豆瓣酱","q": "1.5勺","a": "必须红油豆瓣，减到1勺颜色和香都不够；加到2.5勺偏咸"},{"n": "豆豉","q": "10g","a": "剁碎，减到5g香气弱；加到20g发苦"},{"n": "甜面酱","q": "1勺","a": "减半甜味收敛；加到2勺发甜盖住豆瓣香"},{"n": "姜末、蒜末","q": "各10g","a": "减到5g香气不足；加到各20g发苦"},{"n": "青椒","q": "1个","a": "配菜，可省；加到2个会抢味"},{"n": "料酒","q": "2勺","a": "煮肉去腥用，减到1勺腥味重；加到3勺酒味冲"},{"n": "白糖","q": "1g","a": "减到0.5g略咸；加到3g发甜"},{"n": "食用油","q": "1勺","a": "煸肉时基本不用另加油，多余肥油会被煸出；加到3勺会腻"}],"steps": ["五花肉整块冷水下锅，加姜片、葱段、料酒，水开后撇净浮沫，中火煮20分钟至筷子能扎透但肉皮不烂，捞出晾凉至手摸不烫（晾凉才切得薄而不碎）。","顺肉纹切2mm薄片，蒜苗斜切马耳段、茎叶分开，青椒切块。","锅烧热不放油，肉片下锅中火煸2分钟，边煸边推，至肉片卷成灯盏窝、肥膘边缘透明微焦，多余油脂被煸出。","用锅中煵出的油，下豆瓣酱小火炒1分钟至出红油出香，加豆豉、姜蒜末炒香。","加甜面酱、青椒块翻炒1分钟，让甜面酱均匀裹上肉片。","下蒜苗茎炒30秒，最后下蒜苗叶，加糖翻匀立即出锅。"],"key": "肉要煮到断生后晾凉再切，且只煸不炒——煸到灯盏窝卷曲、肥膘透明才是正宗回锅肉；煸出的油用来炒豆瓣，油少则豆瓣香不浓。","tip": "家常版可把甜面酱减半、豆瓣酱提到2勺；甜面酱必须最后放，早放容易糊锅发苦。肥瘦分开煸炒是更讲究的做法，出来的口感叫“盐菜”。"},"宫保鸡丁": {"time": "30分钟","level": "稍难","servings": "3人份","ing": [{"n": "鸡腿肉","q": "300g","a": "去骨切1.5cm方丁，鸡胸更瘦柴；加到400g需同步增加淀粉水和水量"},{"n": "干辣椒、花椒","q": "干辣椒30个（小二荆条，剪段去籽）、花椒1勺","a": "干辣椒减到15个不够糊辣、加到40个过于呛人；花椒减半麻味不足、加到2勺麻得发木"},{"n": "葱","q": "2根（切马耳段）","a": "减到1根香气弱；加到4根抢味"},{"n": "蒜末、姜末","q": "各1勺","a": "减半爆香不足；加到2勺发苦"},{"n": "白糖","q": "2勺","a": "减到1勺偏酸不成荔枝口；加到3勺过甜"},{"n": "香醋","q": "3勺","a": "减到2勺不够酸；加到4勺太酸盖住甜味"},{"n": "生抽","q": "1勺","a": "减到半勺颜色淡；加到2勺发咸"},{"n": "淀粉水、蛋清、料酒","q": "淀粉水40ml、蛋清1个、料酒1勺","a": "淀粉水分两次用，减到20ml挂不住芡、加到60ml芡汁过厚；蛋清减半浆挂不住炒出来柴、加到2个发黏；料酒减半腥味重"},{"n": "油酥花生米","q": "50g","a": "减到30g口感不足；加到80g会抢鸡肉味"}],"steps": ["鸡腿肉去骨切1.5cm见方的丁，加料酒、蛋清、1勺淀粉水抓匀腌15分钟，抓到肉丁表面发黏封住水分。","另调宫保汁：白糖2勺、香醋3勺、生抽1勺、剩余淀粉水加2勺清水搅匀备用。","锅烧热下2勺油，四成热下干辣椒段用小火炸1分钟，至颜色变成棕红发亮、表皮略皱（绝不能炸焦，焦了只剩苦味），下花椒炒香后把辣椒花椒捞出备用。","锅内留油转大火，下鸡丁快速滑炒1分钟至全部变白，下姜蒜末和葱段炒香。","沿锅边倒入调好的宫保汁，大火翻炒收汁，芡汁浓稠、能挂住鸡丁表面即可。","下油酥花生米翻两下，让芡汁裹住花生米，立刻出锅。"],"key": "宫保汁要沿锅边淋入并一次收到位，不能反复补芡；干辣椒只能炸到棕红发皱，炸黑发苦就没有“糊辣香”了。","tip": "正宗是糊辣荔枝口——先尝糊香与微酸，再回甜，糖醋比约2:3。怕辣可减干辣椒到15个，但糊香也会随之变淡，可用多放花椒补麻。"},"鱼香肉丝": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "猪里脊","q": "250g","a": "横刀逆纹切二粗丝；换成梅花肉更嫩但出油多；加到350g要同步加泡椒"},{"n": "泡红椒、泡姜","q": "泡红椒50g、泡姜10g（均剁碎）","a": "泡红椒是鱼香的地基，减到20g只剩泡椒味、加到80g盖住肉香；泡姜减到5g香气不足、加到20g发苦"},{"n": "豆瓣酱","q": "1勺","a": "增色增香，减半偏淡；加到2勺发咸"},{"n": "蒜末、葱花","q": "蒜末1勺、葱花1根","a": "蒜末减半香气弱、加到2勺蒜味冲；葱花可减半"},{"n": "木耳、青笋、胡萝卜","q": "木耳30g（泡发）、青笋80g、胡萝卜40g","a": "都切成与肉丝同粗的丝；木耳可省，青笋减到40g则配菜少一半"},{"n": "白糖","q": "2勺","a": "鱼香比例糖醋约1:1，减到1勺不甜；加到3勺发腻"},{"n": "香醋","q": "2勺","a": "减到1勺不够酸；加到3勺太酸"},{"n": "生抽","q": "1勺","a": "减到半勺味道淡；加到2勺发咸"},{"n": "淀粉水、蛋清","q": "淀粉水30ml、蛋清1个","a": "淀粉水分两次，减到15ml挂不住、加到45ml芡汁过厚；蛋清减半肉丝会散、加到2个发黏"},{"n": "菜籽油","q": "3勺","a": "油少泡椒炒不出红油，减到1勺色泽不对；加到5勺油腻"}],"steps": ["里脊横刀片薄再切成二粗丝（筷子粗细），加蛋清、淀粉水、料酒抓匀腌10分钟；木耳泡发切丝，青笋、胡萝卜切同样粗细的丝。","锅烧热下2勺油，三成热下泡椒末与泡姜末小火炒2分钟，炒到泡椒出红油、香气冲鼻——这是鱼香味区别于普通泡椒炒肉的关键。","加豆瓣酱小火炒1分钟出红油，转大火下肉丝快速滑散，炒到肉丝全部变白。","下木耳丝、青笋丝、胡萝卜丝大火炒1分钟至断生。","加白糖、香醋、生抽和葱花，大火翻匀后淋入淀粉水勾芡，芡汁亮而不流、能挂住每根肉丝即可出锅。"],"key": "泡椒末必须先用低温油小火炒出红油再下肉，这是“鱼香”与普通泡椒炒肉的分水岭；肉丝要横刀逆纹切再切丝，才嫩不断。","tip": "最正宗是用自制泡红椒（用二荆条剁碎），没有可用泡椒末加少量红油和醋调成泡椒酱替代，酸香味会弱一些。配菜可用莴笋、木耳、笋丝。"},"水煮鱼": {"time": "40分钟","level": "稍难","servings": "4人份","ing": [{"n": "草鱼","q": "1条约800g","a": "片鱼前先称重，800g鱼约出400g鱼片；换成黑鱼1条片更厚更嫩"},{"n": "豆芽","q": "200g","a": "垫底，减到100g底不厚；加到300g需多烫1分钟"},{"n": "蛋清、淀粉、料酒、盐","q": "蛋清1个、淀粉1勺、料酒2勺、盐3g","a": "全部用于给鱼片上浆；蛋清减半挂不住浆会散、加到2个发黏；淀粉减半浆太薄、加到2勺浆太厚发糊；料酒减到1勺腥味重；盐减半味淡"},{"n": "郫县豆瓣酱","q": "2勺","a": "必须红油豆瓣，减到1勺汤色不红；3勺过咸"},{"n": "干辣椒面、花椒","q": "干辣椒面3勺、花椒2勺","a": "干辣椒面减到1.5勺不够麻香、加到5勺会只剩辣；花椒减到1勺麻味不足、加到3勺麻得发木"},{"n": "蒜末、姜末","q": "蒜2勺、姜1勺","a": "减半香气弱；加量过多抢味"},{"n": "高汤或清水","q": "800ml","a": "加到1200ml汤味变淡；减到500ml需用浓高汤"},{"n": "蒜苗、葱段","q": "蒜苗3根、葱2根","a": "减量可省；蒜苗加到5根会抢味"},{"n": "白胡椒粉、生抽","q": "白胡椒粉2g、生抽1勺","a": "白胡椒粉减半味淡、加到5g发冲；生抽减到半勺汤味淡、加到2勺发咸"},{"n": "食用油、红油","q": "菜籽油100ml、红油2勺","a": "热油少于80ml激不出香；加到150ml面上过油"}],"steps": ["鱼去骨片成蝴蝶片，鱼骨剁成块；鱼片用清水反复冲洗至水清，攥干水分，加盐、料酒、蛋清、淀粉抓至发黏，腌15分钟。","锅中水开加姜葱料酒，下豆芽焯1分钟捞出，铺在大碗底。","锅中下3勺菜籽油，小火炒香豆瓣酱至出红油，加姜蒜末和一半辣椒面炒香，倒入高汤烧开。","下鱼骨熬5分钟至汤色微白，捞出鱼骨码在豆芽上，汤保持在菊花心状态（汤面呈菊花状微微翻动，不可大滚）。","汤保持微沸，逐片下入鱼片，下一片等上一片浮起再下下一片，全部下完后用筷子轻轻拨散，鱼片浮起变白立刻连汤倒入碗中。","碗面铺蒜苗段和葱段，撒剩余干辣椒面、花椒粉、蒜末，淋上烧到冒烟的热油100ml激出麻辣香，再沿碗边淋红油。"],"key": "鱼片上浆后绝不能冲洗也不能久煮，浮起变白就要连汤出锅，久煮鱼肉发柴；保持“菊花心”的水位是关键，水大滚会把鱼片冲散。","tip": "辣椒面和花椒先撒一半用热油泼香、再撒一半生的，麻香层次最好；怕上火可把热油减到80ml。鱼骨汤别倒掉，它是这碗汤的底味。"},"水煮牛肉": {"time": "40分钟","level": "稍难","servings": "4人份","ing": [{"n": "牛肉","q": "400g","a": "选吊龙、牛霖等嫩部位，逆纹切2mm薄片；加到600g需分锅"},{"n": "豆芽","q": "200g","a": "垫底，减到100g底薄；加到300g需多烫1分钟"},{"n": "蒜苗","q": "3根","a": "切段，减到2根香味不足；加到5根会抢味"},{"n": "蛋清、淀粉、料酒、盐","q": "蛋清1个、淀粉1勺、料酒2勺、盐3g","a": "全部用于给牛肉上浆；蛋清减半肉会散、加到2个发黏；淀粉减半浆薄、加到2勺浆厚发糊；料酒减到1勺腥味重；盐减半味淡"},{"n": "郫县豆瓣酱","q": "2勺","a": "必须红油豆瓣，减到1勺汤不红；加到3勺过咸"},{"n": "干辣椒面、花椒","q": "干辣椒面3勺、花椒2勺","a": "干辣椒面减到1.5勺不够麻、加到5勺只剩辣；花椒减到1勺麻味不足、加到3勺麻得发木"},{"n": "蒜末、姜末","q": "蒜2勺、姜1勺","a": "减半香气不足；加量过多发苦"},{"n": "黄豆粉","q": "2勺","a": "川菜正宗必加，增到4勺汤会发糊挂渣；减到1勺汤挂不住肉"},{"n": "高汤","q": "900ml","a": "清水会寡，加到1200ml味淡；减到700ml需用浓骨汤"},{"n": "食用油、红油","q": "菜籽油100ml、红油2勺","a": "热油少于80ml激不出麻辣香；加到150ml过于油腻"}],"steps": ["牛肉逆纹切2mm薄片或2cm条，用清水冲净血水攥干，加盐、料酒、蛋清、淀粉抓匀腌20分钟至表面发亮。","豆芽焯水断生铺在碗底，蒜苗切段备用。","锅中下3勺菜籽油，小火炒豆瓣酱2分钟出红油，加一半姜蒜末、干辣椒面、花椒炒香，倒入高汤烧开，加黄豆粉搅匀。","汤微沸时逐片下牛肉，用筷子轻轻拨散，牛肉刚变色断生即关火，连汤倒入碗中，铺上蒜苗段。","碗面撒剩余的干辣椒面、花椒粉、蒜末，淋上烧到冒烟的热油激出麻辣香，最后沿碗边淋红油。"],"key": "牛肉下锅后必须用筷子轻拨、绝不能用勺翻炒，否则浆脱落肉质发柴；黄豆粉是川菜正宗的关键增稠提香，别省，它让汤挂在肉片上。","tip": "牛肉片腌20分钟以上更嫩；没有黄豆粉可用少量淀粉水替代，但香味和稠度会差一截。配一碗米饭泡汤吃才是完整吃法。"},"重庆辣子鸡": {"time": "45分钟","level": "中等","servings": "3-4人份","ing": [{"n": "鸡腿肉","q": "500g","a": "斩2.5cm方丁，用三黄鸡或鸡腿最嫩；加到700g需分两锅炸"},{"n": "干辣椒、花椒","q": "干辣椒100g（剪2cm段）、花椒2勺","a": "干辣椒减到60g香味不足、带籽更香但更呛；花椒减到1勺麻味不足、加到3勺麻得发木"},{"n": "姜、蒜","q": "姜5片、蒜5瓣","a": "姜减到2片去腥弱、加到10片发苦；蒜减到3瓣香气不足、加到8瓣发苦"},{"n": "白糖","q": "1勺","a": "1勺够回甜，减到半勺略苦；加到2勺发甜"},{"n": "熟白芝麻","q": "2勺","a": "减到1勺点缀即可；加到4勺发腻"},{"n": "葱段","q": "3根","a": "减到2根香气弱；加到6根会发甜"},{"n": "料酒、生抽","q": "料酒3勺、生抽2勺","a": "料酒减到2勺腥味重、加到4勺酒味冲；生抽减到1勺颜色淡、加到3勺发咸"},{"n": "淀粉","q": "1勺","a": "拍薄浆减到半勺炸后不脆；加到2勺外壳硬"},{"n": "食用油","q": "约1000ml（炸制用）","a": "油不够会粘锅；炸好滤渣可反复用"}],"steps": ["鸡腿肉斩2.5cm见方的丁，加料酒、生抽、姜片、葱段码味30分钟，腌好后拣出姜葱、拍掉表面水分（水越干炸出来越酥）。","锅中倒油烧至六成热，下鸡丁炸4分钟，边炸边推至表面定型微黄，捞出；油温升到八成热（约200℃），鸡丁回锅复炸90秒至外皮干香酥硬，捞出控油。","锅内留底油3勺，下干辣椒段中火干煸1分半，至颜色转深红、香气彻底炸出（绝不能煸糊，糊了只有苦味），下花椒、姜蒜片炒香。","转大火倒入炸好的鸡丁，快速翻炒1分钟，让辣椒味和花椒味均匀裹住鸡丁。","加白糖翻匀，撒白芝麻和葱段，再大火翻炒30秒出锅。"],"key": "鸡丁要炸两遍，第二遍高温逼出油分才能外酥里嫩；干辣椒最后煸时绝不能发黑，发黑就只剩苦味没有香气。","tip": "重庆做法辣椒用量很大，鸡与辣椒约1:4，嫌呛可减到60g并多放花椒补麻。剩下的炸鸡丁油滤渣后可以做红油或炒其他菜。"},"酸菜鱼": {"time": "40分钟","level": "中等","servings": "3-4人份","ing": [{"n": "草鱼","q": "1条约750g","a": "片鱼前先称重；换黑鱼1条约900g则鱼片更厚更嫩"},{"n": "老坛酸菜","q": "200g","a": "必须自然发酵的老坛酸菜，减到100g酸香不足；加到300g压住鱼鲜"},{"n": "泡椒","q": "5个（剁碎）","a": "酸菜之外的主要酸辣来源，减到2个味道单薄"},{"n": "姜末、蒜末","q": "姜1勺、蒜1.5勺","a": "减半香气弱；加到2勺以上抢味"},{"n": "干辣椒、花椒","q": "干辣椒4个、花椒1勺","a": "干辣椒减到2个几乎不辣、加到6个偏辣；花椒减半麻味不足、加到2勺麻得发木"},{"n": "蛋清、淀粉","q": "蛋清1个、淀粉1勺","a": "蛋清减半鱼片挂不住会散；淀粉减半浆薄、加到2勺发糊"},{"n": "蛋皮丝、葱花、蒜苗","q": "蛋皮半张、葱花1根、蒜苗2根","a": "装饰用，减量可省"},{"n": "白胡椒粉","q": "2g","a": "减半味淡；加到5g发冲"},{"n": "鱼骨汤或高汤","q": "800ml","a": "加到1000ml味淡；减到600ml要熬得浓"},{"n": "食用油、红油","q": "菜籽油2勺、红油2勺","a": "油少香不出；红油减到1勺颜色淡"}],"steps": ["鱼去骨，鱼骨剁块用清水冲净血水；鱼片加盐、料酒、蛋清、淀粉抓黏腌15分钟。","锅中下菜籽油，小火炒香姜蒜末、泡椒碎、干辣椒段和花椒，下酸菜段炒2分钟至酸香冲出。","倒入鱼骨汤或高汤烧开，下鱼骨熬6分钟至汤色发白，捞出鱼骨垫在碗底。","汤保持微沸，下鱼片并用筷子轻轻拨散，鱼片浮起变白立刻关火，连汤倒入碗中。","铺蒜苗段、葱花、蛋皮丝，淋红油和烧热的花椒油。"],"key": "酸菜要先干炒出酸香再加汤，直接下锅煮汤又酸不香；鱼骨熬汤、鱼片另做，汤要浓白、鱼要滑嫩，两步分开才出味道。","tip": "自制老坛酸菜：青菜洗净晾软，一层菜一层盐压进坛子、盖水密封，阴凉处发酵10天以上；急用可买泡椒水加现成酸菜代替，风味略逊。"},"毛血旺": {"time": "40分钟","level": "稍难","servings": "4人份","ing": [{"n": "鸭血","q": "300g（1盒）","a": "切1.5cm块，淡盐水浸5分钟去腥；加到450g要调整烫煮时间"},{"n": "毛肚、鸭肠、黄喉","q": "毛肚200g、鸭肠100g、黄喉100g","a": "毛肚用黑毛肚最脆，减到100g份量少、加到300g需多烫10秒；鸭肠剪段洗去黏液，黄喉可省、加到150g需多烫5秒"},{"n": "午餐肉","q": "150g","a": "切厚片，减到80g份量少；加到200g偏咸"},{"n": "豆芽、宽粉","q": "豆芽150g、宽粉50g（泡软）","a": "宽粉要提前泡30分钟，减到30g份量少"},{"n": "豆瓣酱、火锅底料","q": "豆瓣酱2勺、火锅底料1.5勺","a": "豆瓣必须红油，减到1勺汤色不红、加到3勺过咸；火锅底料用牛油款才够香，减半则香气淡、加到2勺偏咸"},{"n": "干辣椒面、花椒","q": "干辣椒面2勺、花椒1.5勺","a": "干辣椒面减到1勺麻辣不足、加到3勺偏辣；花椒减到1勺麻味不足、加到2.5勺麻得发木"},{"n": "蒜末、姜末","q": "蒜2勺、姜1勺","a": "减半香气弱；加量过多抢味"},{"n": "高汤","q": "900ml","a": "清水会寡，加到1200ml味淡"},{"n": "蒜苗、葱段","q": "蒜苗3根、葱1根","a": "减量可省；蒜苗加到5根抢味"},{"n": "白胡椒粉","q": "2g","a": "减半味淡；加到5g发冲"}],"steps": ["鸭血切1.5cm块用淡盐水浸5分钟去腥味，冲净沥干；毛肚洗净切条，鸭肠剪段反复洗去表面黏液，宽粉用温水泡30分钟。","锅中下油，小火炒香姜蒜末，下豆瓣酱和火锅底料炒2分钟至出红油、香气冲出。","倒入高汤大火烧开，撇净浮沫，下豆芽、宽粉、午餐肉和藕片等耐煮料煮3分钟。","下鸭血块煮2分钟（久煮即碎），最后转大火下毛肚、鸭肠、黄喉，烫15-20秒立刻关火。","连汤倒进大碗，撒干辣椒面、花椒粉、蒜末、蒜苗段和葱段，淋烧到冒烟的热油激出麻辣香。"],"key": "毛肚、鸭肠、黄喉只能烫十几秒，多一秒就老；所有荤腥要在最后一步下锅并保持脆嫩，鸭血最后下且不能搅。","tip": "这是重庆江湖菜，家里锅小可以分两次做；不吃黄喉可用午餐肉加宽粉替代。想更麻可把花椒粉减半、另加现磨花椒。"},"夫妻肺片": {"time": "1小时40分钟（含卤制）","level": "稍难","servings": "3-4人份","ing": [{"n": "牛腱肉、牛肚、牛舌","q": "牛腱肉400g、牛肚150g、牛舌100g","a": "牛腱减到250g份量少、加到500g需多卤20分钟；牛肚牛舌均可省、加到各200g需多卤10分钟"},{"n": "老卤水","q": "800ml","a": "没有老卤可用清水加香料另熬；减到500ml卤不透"},{"n": "花椒、干辣椒面","q": "花椒1勺、干辣椒5个、辣椒面2勺","a": "花椒减到半勺麻味不足、加到2勺麻得发木；辣椒面减到1勺辣味不足、加到3勺太辣"},{"n": "红油","q": "3勺","a": "减到2勺挂汁不够红亮；加到5勺过腻"},{"n": "蒜泥","q": "2勺","a": "减到1勺蒜香不足；加到3勺冲鼻"},{"n": "生抽、香醋","q": "生抽2勺、香醋1勺","a": "生抽减到1勺味道淡、加到3勺发咸；醋减到半勺酸味弱、加到2勺过酸"},{"n": "白糖、味精","q": "白糖1勺、味精1g","a": "糖减到半勺略苦、加到2勺发甜；味精减半几乎无味、加到3g发苦"},{"n": "熟花生碎、白芝麻","q": "花生碎3勺、芝麻1勺","a": "减半口感不足；加到6勺花生碎会抢味"},{"n": "芹菜","q": "100g","a": "垫底用，减到50g份量少；换成黄瓜丝更清爽"}],"steps": ["牛腱、牛肚、牛舌分别焯水去血沫，捞出用老卤水小火卤50分钟至筷子能扎透有嚼劲，卤好后捞出晾凉。","晾凉后牛肉逆纹切极薄片（要薄到透光），牛肚切薄条，牛舌切薄片。","碗底铺焯过水的芹菜段和一半蒜泥。","调味汁：辣椒面与花椒粉用200ml卤水调开，上火烧开激出香味，再加蒜泥、红油、生抽、醋、糖、味精搅匀成红油汁。","把牛肉片、牛肚、牛舌片整齐码入碗中，淋上调好的红油汁，撒花生碎、白芝麻和葱花。"],"key": "牛肉必须卤足50分钟再晾凉切，晾透了才好切薄片；薄片要薄到透光才叫“肺片”，厚了就成了牛肉片。","tip": "正宗是用卤牛肉、牛杂、牛舌等拼盘。家里没有现成卤牛肉可用卤味熟牛肉代替，但不要用煎牛排，会差很多。花生碎要在最后拌入才保持酥脆。"},"担担面": {"time": "25分钟","level": "中等","servings": "2人份","ing": [{"n": "猪肉末","q": "150g","a": "肥瘦3:7最好，减到100g臊子香味弱；加到200g过于油腻"},{"n": "宜宾芽菜","q": "30g","a": "减到15g咸香不足；加到50g会抢味"},{"n": "酥黄豆","q": "20g","a": "减到10g口感不足；加到40g会抢味"},{"n": "花椒粉、葱花","q": "花椒粉2g、葱花1根","a": "花椒粉减到1g麻味不显、加到4g麻得发木；葱花装饰用可省"},{"n": "辣椒油","q": "3勺","a": "减到1勺不够香；加到5勺偏辣"},{"n": "生抽、白糖","q": "生抽2勺、白糖1g","a": "生抽减到1勺臊子味淡、加到3勺发咸；糖减到0.5g略咸、加到3g发甜"},{"n": "香醋","q": "1勺","a": "减到半勺酸味弱；加到2勺过酸"},{"n": "蒜水","q": "3勺","a": "减到1勺蒜味不足；加到5勺冲鼻"},{"n": "菜籽油","q": "2勺","a": "油少肉末煵不出酥香，减到1勺会粘锅"},{"n": "碱水面（干）","q": "200g","a": "1人份约100g；减到150g份量少；加到250g需多煮一锅水"}],"steps": ["锅中下菜籽油，中火下肉末不停煵炒5分钟，煵到水分收干、肉末干香发亮结成小酥粒——这是担担面的关键，绝不能加水。","加入宜宾芽菜碎再炒2分钟至干香，调入1勺生抽和糖，成臊子备用。","碗底依次放辣椒油、生抽、醋、蒜水、花椒粉、白糖和葱花，搅匀。","另起锅烧宽水，下碱水面煮至八分硬，捞入碗中（面要硬一点才筋道，泡软会坨）。","面上铺满臊子，撒酥黄豆，吃前从碗底充分拌匀，让每一根面都裹上红油。"],"key": "肉末一定要煵到干香酥脆，加了水就变成稀肉末，味道完全不同；碱水面煮到八分硬即可，泡软就会坨成一团。","tip": "正宗宜宾担担面的臊子必须有芽菜和酥黄豆，缺了就少了那股咸香脆感；没有芽菜可用雪菜碎加油炸花生碎替代。"},"钟水饺": {"time": "35分钟","level": "中等","servings": "2人份","ing": [{"n": "饺子皮","q": "30张","a": "减到20张不够吃；加到40张需多备红油汁"},{"n": "猪肉馅","q": "250g（肥瘦3:7）","a": "减到150g份量少；加到350g需增加1勺姜水"},{"n": "姜末","q": "1勺","a": "减半去腥弱；加到2勺抢味"},{"n": "甜红酱油","q": "3勺","a": "钟水饺的甜全靠它，减到2勺偏淡；加到4勺太甜盖住红油"},{"n": "红油","q": "3勺","a": "减到2勺颜色不够亮；加到5勺过辣"},{"n": "芝麻酱","q": "1.5勺","a": "用煮饺原汤澥开，减到1勺香味淡；加到3勺会糊嘴"},{"n": "蒜泥","q": "2勺","a": "减到1勺蒜香弱；加到3勺冲鼻"},{"n": "白糖、香醋","q": "白糖1勺、香醋1勺","a": "糖在甜红酱油够甜时可减半、加到2勺过甜；醋减到半勺酸味弱、加到2勺过酸"},{"n": "花椒粉","q": "1g","a": "减到0.5g几乎无味；加到3g发冲"},{"n": "葱花、熟白芝麻","q": "葱花1根、白芝麻1勺","a": "装饰用，葱花可省；芝麻减半点缀即可"}],"steps": ["肉馅加姜末、盐、料酒，分三次打入80ml清水，每次都顺一个方向搅打到完全吸收、肉馅发黏上劲（打水让馅更嫩）。","取饺子皮放馅捏紧收口，饺子呈元宝形但稍扁，全部包好。","锅中水宽大火烧开，下饺子，用勺背沿锅边轻推防止粘底，水开点两次凉水，饺子浮起鼓肚即熟。","碗中放甜红酱油、红油、芝麻酱（用两勺煮饺子的原汤澥开）、蒜泥、白糖、醋、花椒粉搅匀成红油汁。","饺子捞入碗中（不要过凉水，会冲掉吸附的汁），淋上调好的红油汁，撒葱花和白芝麻。"],"key": "钟水饺的“钟”全在那碗甜红油汁里：甜红酱油不能换成普通生抽；芝麻酱必须用煮饺原汤澥开，否则结块发苦。","tip": "红油汁提前调好静置10分钟味道更融合；没有甜红酱油可用生抽加白糖各1勺替代，甜味稍淡。钟水饺讲究“一面红油一面脆皮”，饺子不要久煮。"},"龙抄手": {"time": "35分钟","level": "稍难","servings": "2人份","ing": [{"n": "抄手皮","q": "30张","a": "必须薄皮才叫龙抄手，普通饺子皮太厚；减到25张份量少"},{"n": "猪肉馅","q": "250g","a": "肥瘦3:7，减到150g份量少；加到300g需增1勺姜水"},{"n": "姜水","q": "100ml（分三次打入）","a": "100ml配300g肉馅刚好；加到150ml馅稀易破；减到60ml馅不弹牙"},{"n": "紫菜、虾皮","q": "紫菜5g、虾皮5g","a": "减量可省；加到各15g汤会有腥味"},{"n": "红油","q": "2勺","a": "减到1勺颜色不亮；加到4勺过辣"},{"n": "生抽、香醋、蒜泥","q": "生抽1.5勺、香醋1勺、蒜泥1勺","a": "生抽减到1勺味淡、加到2.5勺发咸；醋减到半勺酸味弱、加到2勺过酸；蒜泥减半蒜香不足、加到2勺冲鼻"},{"n": "花椒粉、白胡椒粉","q": "各1g","a": "减到0.5g几乎无味；加到3g发冲"},{"n": "高汤或清水","q": "600ml","a": "加到900ml味淡；减到400ml需用浓骨汤"},{"n": "葱花、香油","q": "葱1根、香油1勺","a": "香油可省，加到2勺会腻"}],"steps": ["肉馅分三次打入姜水，每次都顺一个方向搅打至完全吸收、肉馅发黏发胀——这是龙抄手馅嫩的关键。","取一张抄手皮放少许馅，对折捏紧，再把两角交叉捏合，成菱形、状如龙头。","碗底放紫菜、虾皮、生抽、醋、蒜泥、花椒粉、白胡椒粉，冲入600ml热高汤调匀，再加2勺红油。","锅中水烧开，下抄手，用手勺轻推防粘，煮到全部浮起后再点一次水，共约2分钟，捞入碗中。","浇上剩余红油汤，撒葱花，淋1勺香油。"],"key": "姜水分三次打入并始终顺一个方向搅，馅才上劲不散、入口弹牙；皮要薄且捏成菱形才是龙抄手，煮时不能大火翻滚，否则皮破馅散。","tip": "红油汤是灵魂，也可另做一份金汤（鸡骨白汤）对比着吃。抄手一次别下太密，会互相粘连破皮。"},"钵钵鸡": {"time": "1小时30分钟（含煮鸡与浸泡）","level": "中等","servings": "3人份","ing": [{"n": "毛肚、藕片、豆皮、木耳","q": "毛肚100g、藕片80g、豆皮50g、木耳50g","a": "毛肚切条减到50g份量少；素菜总量可减半，豆皮加到100g会抢味"},{"n": "藤椒油","q": "3勺","a": "钵钵鸡的灵魂，减到1勺只有麻没有清香；加到4勺麻得盖住其他味"},{"n": "红油","q": "3勺","a": "减到2勺颜色不亮；加到5勺过辣"},{"n": "辣椒面","q": "2勺","a": "减到1勺辣味不足；加到3勺偏辣"},{"n": "蒜泥","q": "2勺","a": "减到1勺蒜香弱；加到3勺冲鼻"},{"n": "生抽","q": "3勺","a": "减到2勺味淡；加到4勺发咸"},{"n": "香醋","q": "2勺","a": "减到1勺酸味弱；加到3勺过酸"},{"n": "白糖、味精","q": "白糖2勺、味精1g","a": "糖减到1勺略苦、加到3勺发甜；味精减半几乎无味、加到3g发苦"},{"n": "白芝麻、花生碎、竹签","q": "芝麻1勺、花生碎1勺、竹签20根","a": "减半点缀即可；竹签可减到12根"},{"n": "鸡胸肉","q": "300g","a": "换成鸡腿肉300g更香；减到200g串不够吃"}],"steps": ["鸡胸肉冷水下锅，加姜葱料酒，水开后转小火煮12分钟至刚熟（筷子扎透无血水），捞出立刻过冰水，撕成粗丝或切厚片。","毛肚、藕、豆皮、木耳分别焯熟断生，捞出沥干；所有食材用竹签串起摆盘。","调料汁：辣椒面、蒜泥、花椒粉、生抽、醋、糖、味精先拌匀，用3勺煮鸡原汤澥开，再加入藤椒油和红油搅匀，最后撒白芝麻。","串好的食材放入料汁中浸泡至少1小时入味，冷藏风味更佳（冷吃是钵钵鸡的特色）。","食用前捞出摆盘，淋一勺剩余料汁，撒花生碎。"],"key": "料汁必须用藤椒油而不是普通花椒油，那种清亮的藤椒麻香才是钵钵鸡区别于其他凉菜的地方；浸泡时间要够，至少1小时才入味。","tip": "夏天提前泡一夜放冷藏最好；鸡胸肉煮好立刻过冰水才不柴。没有藤椒油可用青花椒油加几滴柠檬汁替代。"},"冒菜": {"time": "25分钟","level": "简单","servings": "2人份","ing": [{"n": "牛油","q": "100g","a": "用菜籽油50g替代更清淡，但少了牛油的浓香；加到150g过于油腻"},{"n": "火锅底料、豆瓣酱","q": "火锅底料2勺、豆瓣酱1.5勺","a": "底料减到1勺香味不足、加到3勺偏咸；豆瓣减到1勺底味不厚、加到2.5勺过咸"},{"n": "高汤或清水","q": "1000ml","a": "清水会寡，加到1500ml味更淡；减到700ml需用浓骨汤"},{"n": "豆芽、藕片、土豆片、木耳","q": "各150g、100g、100g、50g","a": "素菜可按喜好增减；土豆片加到150g需多煮2分钟"},{"n": "午餐肉","q": "100g","a": "减到50g份量少；加到150g偏咸"},{"n": "牛肉丸","q": "100g","a": "可换成午餐肉或鱼丸；减到50g份量少"},{"n": "干辣椒、花椒","q": "干辣椒5个、花椒1勺","a": "干辣椒减到2个几乎不辣、加到8个偏辣；花椒减半麻味不足、加到2勺麻得发木"},{"n": "蒜末、姜末","q": "蒜2勺、姜1勺","a": "减半香气弱；加量过多抢味"},{"n": "油碟：蒜泥、葱花、香菜","q": "蒜泥2勺、葱花1根、香菜2根","a": "香菜可省；蒜泥加到3勺冲鼻"},{"n": "生抽、香醋（蘸碟）","q": "各2勺、1勺","a": "减半蘸碟味淡；各加到1倍则过咸"}],"steps": ["锅中下牛油小火化开，下火锅底料和豆瓣酱小火炒3分钟，炒到油色红亮、香气彻底逼出（这是冒菜底料的关键）。","加姜蒜末、干辣椒、花椒炒1分钟，倒入高汤或清水大火烧开，撇净浮沫。","按耐煮顺序下锅：土豆片、藕片先煮4分钟，再下木耳、豆芽、午餐肉、牛肉丸煮3分钟。","食材捞出装碗，舀一勺底汤浇在碗里（底汤比食材更入味，别浪费）。","蘸碟：蒜泥、生抽、醋、葱花、香菜调匀，蘸食；喜欢更辣可再泼一勺热油加干辣椒面。"],"key": "底料必须用牛油小火把豆瓣和底料炒透，油色红亮才够香；用清水代替高汤会寡淡，这正是家里做冒菜最容易失手的地方。","tip": "一人食最省事：所有食材依次下锅同煮，最后统一捞出。素食版可用清汤加菜籽油、豆豉代替牛油，香味淡但清爽。"},"蒜泥白肉": {"time": "40分钟","level": "简单","servings": "3人份","ing": [{"n": "二刀五花肉","q": "350g","a": "切2mm薄片；减到250g份量少；加到500g需久煮20分钟"},{"n": "蒜泥","q": "4瓣","a": "减到2瓣蒜香不足；加到6瓣会有生蒜冲味"},{"n": "辣椒油","q": "3勺","a": "减到2勺颜色偏淡；加到4勺辣味重"},{"n": "生抽","q": "2勺","a": "减到1勺味淡；加到3勺发咸"},{"n": "香醋","q": "1.5勺","a": "减到1勺酸味弱；加到2.5勺过酸"},{"n": "白糖、盐","q": "白糖1勺、盐2g","a": "糖减到半勺略咸、加到2勺发甜；盐减到1g略淡、加到4g过咸"},{"n": "花椒粉","q": "1.5g","a": "减到0.5g麻味不显；加到3g麻得发木"},{"n": "姜片、葱段、料酒","q": "姜4片、葱1根、料酒2勺","a": "煮肉用；料酒减到1勺腥味残留"},{"n": "高汤或清水","q": "50ml","a": "用来澥蒜泥，减到20ml调不开；加到100ml会冲淡蒜香"},{"n": "熟白芝麻、葱花","q": "白芝麻1勺、葱花1根","a": "装饰可省"}],"steps": ["五花肉整块冷水下锅，加姜片、葱段、料酒，水开后撇净浮沫，小火煮25分钟至筷子能扎透，捞出晾凉。","晾凉后逆着肉纹切2mm极薄片，整齐码入盘中。","蒜泥放在碗底，用烧到冒烟的热油浇上去泼一遍激出蒜香（关键一步，泼过的蒜泥不辛不冲）。","加辣椒油、生抽、醋、糖、盐、高汤、花椒粉搅匀成料汁。","淋在白肉上，撒白芝麻和葱花，吃前从底部拌匀。"],"key": "白肉要切得极薄而且逆纹切，逆着纹切才不会断不会塞牙；蒜泥必须用热油泼过才香而不辛，这是川式凉菜的基础手法。","tip": "四川凉白肉多用二刀肉，肥瘦相间，太肥的部位切片会塌；垫底加黄瓜丝或焯豆芽更爽口。剩下的一半肉汤可煮面条。"},"干煸四季豆": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "四季豆","q": "400g","a": "掐两头撕老筋，掰5cm段；加到600g要分锅煸，太多会出水变烂"},{"n": "猪肉末","q": "80g","a": "减到40g肉香不足；加到150g会盖过豆香"},{"n": "干辣椒","q": "5个","a": "剪段，减到2个几乎不辣；加到8个偏辣"},{"n": "蒜末、姜末","q": "蒜1.5勺、姜1勺","a": "减半香气弱；加到2勺发苦"},{"n": "宜宾芽菜","q": "20g","a": "减到10g香味弱；加到30g会偏咸"},{"n": "郫县豆瓣酱","q": "1勺","a": "减半色泽不足；加到2勺发咸"},{"n": "生抽","q": "1勺","a": "减到半勺味淡；加到2勺发咸"},{"n": "白糖","q": "1g","a": "减到0.5g略苦；加到3g发甜"},{"n": "盐","q": "1g","a": "减到0.5g即可；加到3g过咸"},{"n": "食用油","q": "3勺","a": "油少会粘锅，煸不透；加到5勺过于油腻"}],"steps": ["四季豆掐去两头、撕掉两侧老筋，掰成5cm长段，洗净后用厨房纸彻底擦干表面水分。","锅中放3勺油，中火下四季豆煸炒6-8分钟，不停翻动压炒，直到表皮起皱发软、边缘焦黄（这是干煸的核心，不能加水）。","四季豆盛出，锅中留底油下肉末煵散，加豆瓣酱、干辣椒、姜蒜末、芽菜小火炒香2分钟。","倒入四季豆，加生抽、糖、盐大火翻炒2分钟至入味。","出锅前再撒一点蒜末增香，翻匀装盘。"],"key": "四季豆必须先过油干煸到起皱发软才能吃，半生的有毒；煸的时候绝对不能加水，一加水就变成炖四季豆。","tip": "想少油可用空气炸锅或烤箱200℃烤15分钟代替先油煸；芽菜是川味提香的关键，别省，嫌咸可减一半。"},"蚂蚁上树": {"time": "20分钟","level": "简单","servings": "2-3人份","ing": [{"n": "绿豆粉丝","q": "100g（干重）","a": "减到60g份量少；加到150g需多10ml汤"},{"n": "猪肉末","q": "120g","a": "减到80g肉少味不足；加到180g偏油腻"},{"n": "郫县豆瓣酱","q": "1勺","a": "减半色泽和咸味不足；加到2勺发咸"},{"n": "蒜末、姜末","q": "蒜1.5勺、姜1勺","a": "减半香气弱；加到2勺发苦"},{"n": "干辣椒","q": "3个","a": "剪段，减到1个几乎不辣；加到5个偏辣"},{"n": "高汤或水","q": "300ml","a": "加到400ml会稀挂不住；减到200ml容易糊锅"},{"n": "生抽","q": "1勺","a": "减到半勺味淡；加到2勺发咸"},{"n": "蒜苗、熟白芝麻","q": "蒜苗2根、熟白芝麻1勺","a": "蒜苗切段减到1根香味弱；芝麻装饰用可省"},{"n": "白胡椒粉","q": "1g","a": "减到0.5g几乎无味；加到3g发冲"},{"n": "食用油","q": "2勺","a": "油少肉末煵不出香，减到1勺会粘锅"}],"steps": ["粉丝用温水泡20分钟至变软无硬芯，捞出用剪刀剪成两段（剪短才不会抱成一团），拌少许油防粘。","锅中下油，中火下肉末煵炒3分钟至酥香发干，下豆瓣酱、蒜末、姜末、干辣椒炒1分钟出香。","倒入高汤烧开，下粉丝，用筷子挑散，加生抽和白胡椒粉。","中火煮3分钟让粉丝吸汤，中途晃锅防止粘底，汤汁收到浓稠能挂住粉丝。","出锅撒蒜苗段和白芝麻。"],"key": "粉丝要用温水泡到无硬芯，泡久了会烂成糊；下锅后只能挑不能压，压多了就成了“一坨”，也就看不到“蚂蚁”了。","tip": "要让“蚂蚁”看得见，肉末必须煵到干香酥散再加汤；想更好看可以加青椒丝或笋丝配色，汤汁拌饭更香。"},"粉蒸肉": {"time": "1小时50分钟","level": "中等","servings": "4人份","ing": [{"n": "带皮五花肉","q": "500g","a": "切5mm厚片；减到350g份量少；加到700g需分两碗蒸"},{"n": "蒸肉米粉","q": "150g","a": "减到80g挂不住；加到220g发干失去糯感"},{"n": "南瓜或土豆","q": "300g","a": "垫底吸油，切1.5cm厚片；换成土豆更粉糯；减到150g垫底不够"},{"n": "腐乳、豆瓣酱","q": "腐乳1块（压泥）、豆瓣酱1勺","a": "腐乳减半咸香不足、加到2块太咸；豆瓣减半色泽不足、加到2勺发咸"},{"n": "生抽","q": "2勺","a": "减到1勺味道淡；加到3勺发咸"},{"n": "白糖","q": "1勺","a": "减到半勺略苦；加到2勺发甜"},{"n": "姜末","q": "1勺","a": "减半去腥弱；加到2勺抢味"},{"n": "料酒","q": "1勺","a": "去腥，减到半勺腥味重"},{"n": "白胡椒粉","q": "1g","a": "减到0.5g几乎无味"},{"n": "菜籽油","q": "2勺","a": "拌肉用，减到1勺蒸后发干；加到3勺成品油腻"}],"steps": ["五花肉切5mm厚片，加压成泥的腐乳、豆瓣酱、生抽、糖、姜末、料酒、白胡椒粉抓匀码味30分钟。","南瓜切1.5cm厚块铺在碗底，把腌好的肉片倒进盆中拌入蒸肉米粉，粉要薄而均匀地挂在肉片表面。","肉片整齐码放在南瓜上，粉面朝上，不要叠压太紧，淋1勺菜籽油。","蒸锅上汽后放入，大火蒸1小时30分钟至肉软烂、米粉吸水变成半透明发亮，中途需补一次热水防止烧干。","出锅撒葱花，可配一碟蒜泥蘸水同吃。"],"key": "蒸肉米粉必须是自己炒香后打成的粗颗粒，市售预拌粉香气不足、打成细粉又会蒸成糊；肉片码味后要醒30分钟再上粉，蒸出来才有味透到肉里。","tip": "自制米粉：大米与糯米按7:3加花椒八角小火炒香，打成粗颗粒不要打成细粉。牙口不好可延长到2小时；垫底的南瓜甜糯，土豆更吸油更香。"},"跷脚牛肉": {"time": "3小时（熬汤）","level": "稍难","servings": "3-4人份","ing": [{"n": "牛骨、清水","q": "牛骨1500g（棒子骨或牛大骨）、清水2500ml","a": "牛骨减到1000g汤不浓白、加到2000g需更大锅；水减到2000ml要勤翻、加到3000ml味变淡"},{"n": "牛肉片","q": "400g","a": "选吊龙嫩牛肉逆纹切2mm薄片；减到250g份量少；加到600g需分盘"},{"n": "牛舌、牛肚","q": "各100g","a": "切条，可省；加到各200g需多烫10秒"},{"n": "金针菇、茼蒿","q": "金针菇150g、茼蒿100g","a": "可把茼蒿换成油麦菜；金针菇减到100g份量少"},{"n": "干辣椒面（干碟）","q": "4勺","a": "1勺太温和，2勺偏轻；加到6勺会辣得盖住牛肉"},{"n": "花椒粉（干碟）","q": "1勺","a": "减到半勺麻味不足；加到2勺麻得发木"},{"n": "盐、味精（干碟）","q": "盐3g、味精2g","a": "盐减到2g略淡；味精可省"},{"n": "姜、葱、料酒","q": "姜6片、葱2根、料酒2勺","a": "熬汤用，料酒减到1勺腥味重"},{"n": "香油、葱花","q": "香油1勺、葱花1根","a": "香油可省；葱花装饰用，不影响味道"}],"steps": ["牛骨冷水下锅焯水去血沫，冲洗干净；另起锅加2500ml清水，放牛骨、姜片、葱段、料酒，大火烧开转小火熬2.5-3小时。","汤熬到浓白如牛奶、汤面浮一层胶质时离火，滤去骨渣，撇净表面浮油（撇油才不腻），加盐调味，保持90℃微沸备用。","牛肉逆纹切极薄片，牛舌、牛肚切条；金针菇、茼蒿洗净分盘装好。","干碟：干辣椒面4勺、花椒粉1勺、盐3g、味精2g拌匀，另备葱花。","客人自行夹牛肉片在滚汤中烫8-10秒至变色即捞出，蘸干碟食用；金针菇、茼蒿烫熟同吃。"],"key": "跷脚牛肉的精髓一半在汤要浓白一半在干碟够麻辣；熬好的汤必须撇净浮油，否则喝起来腻口、盖住牛肉本身的鲜甜。","tip": "干碟可做变化：一半辣椒面加一半白芝麻更香；蘸碟里加一勺蒜泥或香油更解腻。汤别一次煮太多，隔夜回锅味道更好。"},"宜宾燃面": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "宜宾碱水细面","q": "400g（约2人份）","a": "减到300g则面条稀薄、红油挂不上碗壁；加到500g需多煮1分钟否则芯发硬，一碗约450g才够挂汁"},{"n": "二荆条辣椒面","q": "40g","a": "加到60g红油更红更香但会盖掉芽菜的咸鲜；减到20g只剩辣味没有糊香，且容易发燥"},{"n": "宜宾芽菜","q": "40g","a": "减到20g香气不足、缺宜宾灵魂；加到60g会抢走芝麻酱的香、整碗发咸"},{"n": "猪油","q": "30g","a": "减到15g面条容易粘连结团；加到50g会腻口，冲洗时要多冲一遍"},{"n": "生抽","q": "20ml","a": "加到30ml颜色更深、咸味压过芽菜；减到10ml则味不足需补盐"},{"n": "香醋","q": "20ml","a": "加到30ml酸味压住芝麻酱的厚味；减到10ml只剩甜腻，建议18-22ml"},{"n": "白糖","q": "8g","a": "减到3g酸咸失衡、辣味发冲；加到15g则成甜面失去咸鲜"},{"n": "花椒粉","q": "2g","a": "加到5g麻味过重盖住红油香；减到1g则完全尝不到麻味"},{"n": "芝麻酱","q": "15g","a": "减到8g香味变薄、不挂面；加到25g发稠、拌不开"},{"n": "葱花","q": "15g","a": "减到8g香气平淡；加到30g会出水冲淡碗底调料"}],"steps": ["宽水加姜葱烧开，下碱面大火煮2分半钟，掐断看无白芯即捞出（八分熟），立刻拌入猪油摊在竹匾上吹凉，让面条根根分开不粘连。","干锅小火焙二荆条辣椒面至棕红出香，注意不能发黑，再倒入烧至六成热的菜籽油激成红油，晾凉备用。","宜宾芽菜切成细末，若偏咸可先用温水冲一遍挤干。","碗底下蒜末、葱花、花椒粉、芝麻酱、生抽、香醋、白糖、味精和20ml煮面原汤，搅匀成酱汁。","凉面抖散装入碗中，堆上芽菜末，淋入红油约25ml。","从碗底向上快速翻拌20下，让每根面都挂上红油与酱汁，最后撒葱花即成。"],"key": "煮面只到八分熟并用猪油拌开摊凉，这是宜宾燃面条条分明不粘连的关键；火候过头面就烂了。","tip": "正宗燃面讲究素而不寡，红油和芽菜的咸鲜是主味，芝麻酱只作底。若买不到宜宾芽菜，可用榨菜碎替代但要减盐。"},"重庆小面": {"time": "50分钟","level": "中等","servings": "2人份","ing": [{"n": "碱水面","q": "300g","a": "减到200g则一碗过少、料味太重；加到400g需多加半勺猪油才不粘"},{"n": "干豌豆","q": "80g（泡发后约200g）","a": "减到50g豌杂量少、豌豆沙不细；加到120g则成纯豆沙面失去肉香"},{"n": "猪肉馅","q": "170g（肥瘦3:7）","a": "减到120g豌杂会散不挂汁；加到220g则油腻"},{"n": "复制酱油","q": "30ml","a": "减到15ml则发苦发黑不够鲜；加到45ml会咸得盖住豌豆香，需减盐"},{"n": "红油辣子","q": "40ml","a": "减到20ml辣味不足、整碗偏甜；加到60ml辣度上去了但香火味被盖住"},{"n": "蒜水","q": "30ml","a": "减到15ml蒜香不足；加到50ml蒜味生冲、盖住红油"},{"n": "花椒粉","q": "2g","a": "减到1g麻不出来；加到5g舌头发木吃不出别的味"},{"n": "猪油","q": "15g","a": "减到5g面条发硬；加到30g碗面泛油花、腻口"},{"n": "葱花","q": "15g","a": "减到8g香气弱；加到30g会泡软发蔫"},{"n": "味精与白糖","q": "味精3g、白糖4g","a": "白糖减到2g则咸鲜发苦；味精加到6g会有化工味"}],"steps": ["干豌豆提前用冷水泡发4小时，加水煮至用手一捏即烂（约50分钟），沥干后用破壁机打成带颗粒的豌豆泥。","豌豆泥与猪肉馅、3勺葱姜水、生抽10ml、盐2g顺时针搅打上劲，直到肉馅抱紧不散，摔在砧板上能成团。","锅中下猪油与剁细的芽菜，中火炒2分钟至干香，再倒入肉豌杂摊平，中火慢炒5-6分钟，用铲子反复压散，炒到肉粒发干发香、豌豆起沙。","加复制酱油10ml、姜末、蒜末炒1分钟出香，起锅前撒胡椒粉盛出备用。","宽水烧开下碱面煮2分半钟至断生，捞出沥干装碗。","碗底放复制酱油20ml、蒜水30ml、红油辣子40ml、猪油15g、味精3g、白糖4g调匀。","把面挑入碗中铺开，舀2勺热豌杂盖在面上，撒葱花15g与花椒粉2g，从碗底翻拌均匀即可。"],"key": "豌杂必须用带颗粒的豌豆泥与肉馅同炒，且中火慢炒到发干，这样才有市井小面的干香与挂汁感。","tip": "红油辣子先在油温七成热泼出静置一夜最香；面条不要过冷水，冲一下即入碗，否则挂不住味。"},"乐山甜皮鸭": {"time": "3小时","level": "稍难","servings": "4人份","ing": [{"n": "整鸭","q": "1只约1.5kg","a": "减到1kg皮脆面积不够、切片份量少；加到2kg需延长卤制40分钟并分两次上色"},{"n": "精盐","q": "30g","a": "减到15g肉里发腥、鸭皮挂不住糖色；加到45g卤水过咸无法收口"},{"n": "花椒","q": "10g","a": "减到5g香味不足；加到20g麻得刺舌"},{"n": "料酒","q": "30ml","a": "减到15ml腥味残留；加到50ml卤水带酒味"},{"n": "卤料包（八角3颗、桂皮1段、甘草5g、山奈2个）","q": "1份","a": "减半则卤味单薄缺回甜；加到2份会发苦发黑"},{"n": "老姜与大葱","q": "姜60g、葱1根","a": "姜减到30g去腥力弱；加到100g姜味太冲压住鸭香"},{"n": "冰糖（卤汤用）","q": "20g","a": "减到10g卤汁不醇；加到40g卤汤偏甜"},{"n": "麦芽糖浆（糖色用）","q": "60g","a": "减到30g挂色淡、脆度不足；加到90g甜味过重发硬"},{"n": "熟菜油","q": "500ml（炸皮用）","a": "油温低于160℃糖色不化、皮不脆；油量少于300ml则一次炸不完"},{"n": "花椒粉与盐（碟子用）","q": "花椒粉5g、盐8g","a": "花椒粉减到2g无麻味；盐加到15g则过咸"}],"steps": ["整鸭洗净擦干，把盐、花椒、料酒、少量五香粉抹匀鸭身内外和腹腔，腌制2小时；腌好后用清水冲净表面盐分，晾干水汽。","锅中加清水1.5L、卤料包、老姜、葱结和冰糖，大火烧开后下鸭，提起鸭脖在卤汤中三提三放让腔内外温度一致，再整只沉入。","转小火保持汤面似开非开，卤45分钟，鸭皮用竹签一扎能透即熟；关火后在卤汤中浸泡20分钟更入味。","取出鸭子架起彻底晾干水汽，这一步决定最终皮能否炸脆。","麦芽糖浆加30ml水小火熬至拉丝挂勺、能挂住木勺不流，熬成琥珀色糖色。","趁鸭身尚温，用勺把糖色均匀刷遍鸭皮，尤其背部与腿部缝隙。","油烧至七成热（约200℃），提鸭入油锅炸40秒，勤翻动至皮面鼓起大泡、颜色金红，立即捞出架起滴油。","斩件装盘，撒椒盐，或蘸甜皮鸭专用甜面酱与芝麻酱。"],"key": "卤完必须彻底晾干再刷糖色炸皮，鸭皮上有水汽就炸不出泡、只会回软。","tip": "没有麦芽糖可用冰糖加少量水熬制，颜色偏深味微苦；糖色熬好后要趁热刷，冷了挂不上。"},"四川火锅": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "牛油","q": "400g","a": "减到200g锅底香味薄、挂壁差；加到600g过于油腻需多涮几片菜去油"},{"n": "郫县豆瓣","q": "100g","a": "减到50g红度不足、发酵香弱；加到150g会发苦、需多加水稀释"},{"n": "糍粑辣椒","q": "80g（干辣椒开水烫30秒剁碎）","a": "减到40g糊香不足、颜色偏暗；加到120g辣味压过牛油香、需减盐"},{"n": "姜蒜","q": "姜40g、蒜60g","a": "蒜减到30g香气不够；加到100g蒜味发冲发苦"},{"n": "干辣椒段","q": "30g","a": "减到15g没有辣型香气；加到50g干香过重"},{"n": "汉源花椒","q": "15g","a": "减到8g麻味不足；加到25g舌头发木、盖住其他味"},{"n": "郫县豆豉","q": "20g","a": "减到10g咸鲜不足；加到35g过咸、需减盐"},{"n": "白酒","q": "30ml","a": "减到15ml去酒味不足；加到60ml锅底带酒味、抢鲜味"},{"n": "高汤或清水","q": "1.2L","a": "减到800ml锅底太浓、料味不够；加到1.8L则味被稀释、需补味精"},{"n": "大葱与干辣椒（垫底）","q": "葱2根、干辣椒50g","a": "葱减到1根香气不够；加到4根则抢味"}],"steps": ["牛油入厚底锅，小火慢慢化开，加姜片、葱段、蒜瓣小火炸5分钟至葱段焦黄捞出，这一步逼出牛油香。","转中火下郫县豆瓣，用铲子压散小火炒3-4分钟，炒到油色红亮、豆瓣出沙。","下糍粑辣椒、干辣椒段、汉源花椒、豆豉、姜末蒜末，中火炒3分钟至糍粑辣椒变深红、整体发出刺鼻香（豆瓣炒香后不能糊）。","沿锅边淋入白酒，晃锅让酒气挥发2分钟，再倒入高汤或清水1.2L。","大火烧开后转中火煮8-10分钟，让味道融合，汤面浮油呈红亮颜色即可；捞去大块姜蒜。","另起小锅烧油，下葱段、干辣椒段、花椒炸香后倒入火锅汤中激香（传统叫铺底）。","汤底烧滚后下菜，按耐煮程度顺序：先鸭血、鸭肠、午餐肉，再毛肚、鸭舌，最后娃娃菜、藕片、豆皮、鹌鹑蛋。"],"key": "糍粑辣椒必须开水烫过后剁碎，烫过的辣椒只出香不出燥辣，这是老四川火锅与单纯辣椒面火锅的区别。","tip": "牛油锅底第一次开涮会发苦属正常，多涮几样菜把苦味带走；牛油量超过500g时涮菜顺序要把肥牛提前，用来解腻。"},"口水鸡": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "三黄鸡或土鸡","q": "半只约800g","a": "减到600g不够3人份、皮也不够脆；加到1整只需按每500g延长3分钟浸煮"},{"n": "姜葱花椒（煮鸡用）","q": "姜30g、葱30g、花椒8g","a": "姜减到15g去腥弱；加到60g姜味盖过鸡鲜"},{"n": "料酒","q": "20ml","a": "减到10ml汤有腥气；加到40ml鸡香被酒味带走"},{"n": "辣椒面（二荆条）","q": "25g","a": "减到15g红油量不足、色不红；加到40g辣度太高不适合配鸡"},{"n": "食用油","q": "40ml","a": "油温低于160℃激不出香、辣椒发苦；油量少于25ml则辣椒面成坨"},{"n": "蒜泥","q": "30g","a": "减到15g蒜香不足；加到50g蒜味刺鼻、压住花椒香"},{"n": "生抽","q": "40ml","a": "减到25ml咸度不够；加到60ml过咸需减盐"},{"n": "香醋","q": "15ml","a": "减到8ml不够解腻；加到25ml酸得倒牙"},{"n": "白糖","q": "8g","a": "减到3g辣味发苦；加到15g则酸甜失衡"},{"n": "花生碎与熟芝麻","q": "花生碎30g、芝麻5g","a": "花生碎减到15g口感单薄；加到50g会吸油发腻"}],"steps": ["整鸡洗净，锅中放足量水加姜、葱结、花椒、料酒大火烧开。","提着鸡颈把鸡浸入沸水烫10秒再提起，重复三次（让鸡腔内外温度一致），然后整只沉入水中，转小火保持水面似开非开浸25分钟。","筷子插鸡腿最厚处无血水即熟，立刻捞出放入冰水中浸10分钟，让鸡皮收缩变爽脆。","沥干鸡身水珠斩件摆盘，鸡皮朝上均匀铺开。","碗中放蒜泥、生抽、香醋、白糖、盐、味精搅匀备用。","另取碗放辣椒面、花椒粉、芝麻，用烧至七成热的食用油分两次泼在辣椒面上，边泼边搅激出红油，晾至温热。","把红油汁倒入调味碗中与蒜汁混合，再加花生碎拌匀，淋在鸡件上，撒葱花。"],"key": "煮好的鸡必须立刻过冰水，皮才爽脆有弹性；省掉这一步鸡皮发黏、失去口水鸡的招牌口感。","tip": "红油一次泼到位容易半生半熟，分两次泼并不断搅拌，油温才够高。红油可多做一些冷藏备用，一周内风味最佳。"},"开水白菜": {"time": "4小时","level": "稍难","servings": "3人份","ing": [{"n": "老母鸡","q": "1只约1.2kg","a": "减到600g汤味不够醇厚；加到2只需延长炖煮1小时、汤量也要加"},{"n": "宣化火腿","q": "100g","a": "减到50g鲜味不足；加到150g汤会发咸、需减盐"},{"n": "干贝与瑶柱","q": "干贝15g、瑶柱20g","a": "减半则鲜味打折、汤不奶白；加到50g汤过鲜发腥"},{"n": "老姜与大葱","q": "姜50g、葱60g","a": "姜减到20g去腥不够；加到100g姜味太重"},{"n": "清水","q": "2L","a": "减到1.5L需多加油并延长熬制；加到3L汤味变淡"},{"n": "鸡胸肉（做鸡茸）","q": "100g","a": "减到60g澄清效果弱；加到200g汤会带絮状渣"},{"n": "鸡蛋清","q": "3个","a": "减到1个蛋清量不够挂不住鸡茸；加到5个会有腥味"},{"n": "淀粉","q": "15g","a": "减到5g鸡茸挂不匀；加到30g汤会发黏发稠"},{"n": "白菜心或菜心","q": "300g","a": "减到150g份量偏少；加到500g需用两个盘子装"},{"n": "盐与白胡椒粉","q": "盐6g、白胡椒粉2g","a": "盐减到3g汤味寡淡；加到12g则破坏清淡本味"}],"steps": ["老母鸡洗净剁成大块，冷水下锅加姜葱焯5分钟，撇净血沫捞出冲洗干净，锅具用清水涮一遍不要有油。","砂锅中放鸡块、火腿、干贝、瑶柱、姜块、葱段和清水2L，大火烧开转小火炖3小时，全程保持汤面微滚不剧烈沸腾。","熬好后用纱布过滤汤渣，再把汤倒入干净砂锅，撒入盐和白胡椒粉调味，转小火保温。","鸡胸肉剁成极细的茸，加2个鸡蛋清、淀粉和3勺清水顺时针搅打15分钟至发黏、提起能缓慢流成线。","汤重新烧至微沸（不要大滚），把鸡茸一次性倒入汤中，转大火让汤剧烈翻滚，鸡茸受热结成颗粒浮起。","用细密漏勺把所有颗粒捞出，重复此步骤一次到两次，直到汤色清澈如清水、汤面只有极少的油星。","白菜心或广东菜心焯水30秒至断生，捞出装入深盘。","把澄清的汤沿盘边缓缓注入汤量约400ml，上桌前撒几粒葱花，汤面不浮油星才算合格。"],"key": "让汤由浑变清的核心是鸡茸扫汤：鸡茸在沸汤中受热结成颗粒吸附悬浮杂质，捞走颗粒汤即澄清。","tip": "这是川菜检验火候功夫的菜，成败看两点：汤必须清亮见底、口感却是醇厚浓缩的鲜；家里可用两只土鸡加火腿一起熬，汤味更足。"},"樟茶鸭": {"time": "4小时","level": "稍难","servings": "4人份","ing": [{"n": "鸭","q": "1只约1.5kg","a": "减到1kg烟味渗透不足；加到2kg需增加熏制时间到60分钟"},{"n": "精盐","q": "25g","a": "减到12g腥味重、腌不进去；加到40g过咸"},{"n": "花椒","q": "10g","a": "减到5g麻香不足；加到20g麻得刺舌"},{"n": "料酒","q": "30ml","a": "减到15ml去腥不够；加到50ml带酒味"},{"n": "豆腐乳","q": "15g（红腐乳）","a": "减到8g上色浅、香味不足；加到25g颜色发黑、腐乳味过重"},{"n": "姜葱","q": "各30g","a": "减半则腌料香味不足；加到60g会抢鸭肉味"},{"n": "樟木屑或樟树枝","q": "150g","a": "减到80g烟味淡、樟香不显；加到250g烟味过冲发苦"},{"n": "大米（助燃与垫底）","q": "50g","a": "减到20g温度上不来；加到100g只冒白烟不带樟香"},{"n": "五香粉与花椒粉（蘸料）","q": "各4g、盐5g","a": "盐减到2g鸭肉发淡；花椒粉加到8g麻得盖住樟香"}],"steps": ["鸭子洗净擦干，把盐、花椒、料酒、豆腐乳、姜葱末、少量五香粉调成料糊，均匀抹在鸭身内外与腔壁，腌制3小时。","蒸锅上汽后放入腌好的鸭，大火蒸40分钟至鸭肉完全熟透、鸭皮微软，取出晾10分钟并擦去表面水分。","熏缸底部铺一层大米，再铺樟树枝与樟木屑（留出通风口），把鸭子架在铁丝网上架于缸中。","点燃底部大米与樟木屑，让其阴燃不出现明火（明火会烧焦鸭皮），盖严缸盖密闭熏40分钟。","开盖检查，鸭皮应呈均匀的棕红色、有明显樟木清香而不发黑；颜色不够则再熏10分钟。","取出鸭子擦净浮灰，切块装盘。","用盐、五香粉、花椒粉调成干碟，鸭肉蘸干碟食用；也可配少量烧椒或葱白段。"],"key": "熏制必须阴燃而非明火，樟木香要靠烟慢慢渗进鸭皮；见明火会烤焦鸭皮并产生焦苦味。","tip": "没有樟木可用柏枝、柚木、桂枝代替，风味略有差别但方法相同；熏好后静置1小时再切，皮味更融合。"},"三大炮": {"time": "90分钟","level": "稍难","servings": "3人份","ing": [{"n": "糯米","q": "300g","a": "减到200g份量少；加到400g炸锅负担重、油耗大"},{"n": "红糖","q": "100g","a": "减到60g甜味不足、糍粑不挂浆；加到150g齁甜发腻"},{"n": "黄豆粉","q": "50g","a": "减到20g豆香不足、吃不出童年味；加到80g粉感太重盖住红糖"},{"n": "猪油","q": "20g（拌糯米用）","a": "减到10g糍粑发硬不弹；加到35g糍粑太软难成型"},{"n": "桂花酱","q": "15g","a": "减到5g香气弱；加到30g甜味与花香过重"},{"n": "熟白芝麻","q": "10g","a": "减到5g香味不足；加到20g略焦"},{"n": "菜籽油（炸制）","q": "1.5L","a": "油温低于170℃糍粑不膨起；油量少于1L需分两锅炸"},{"n": "红糖浆（红糖100g+水150ml熬成）","q": "1份","a": "熬得太稠挂不上、结块；太稀则冲淡黄豆粉不挂粉"}],"steps": ["糯米淘净后用清水浸泡4小时，沥干摊在蒸笼中大火蒸40分钟至完全熟透、透亮发黏。","趁热把蒸熟的糯米舀入碓窝或石臼中舂捣5-8分钟，捣至糯米完全起胶、黏成一团不散，摊开放凉。","猪油小火化开拌入糍粑，揉匀，使糍粑软硬适中不粘手。","取一团糍粑搓成乒乓球大小的圆球，全部搓好备用。","菜籽油烧至八成热（约190℃），下糍粑球炸40-60秒，糍粑会迅速膨起成空心泡状，用漏勺轻推使其受热均匀。","传统做法是趁热把炸好的糍粑甩向石臼，借冲力崩开成碎块（这一下就是炮），没有石臼可用漏勺压散。","红糖加150ml水小火熬成能挂勺的糖浆备用。","取粗碗，先撒一层黄豆粉，铺上崩散的糍粑块，淋红糖浆，再撒剩余黄豆粉、桂花酱和熟芝麻，吃前拌匀。"],"key": "糍粑必须舂到完全起胶才炸得起来泡；蒸熟后直接搓团下锅会沉底散开、炸成碎渣。","tip": "可用木杵代替石臼，捣到拉丝不粘杵即可。糍粑球要现炸现吃，放凉回软就失去脆泡口感。"},"甜水面": {"time": "45分钟","level": "中等","servings": "2人份","ing": [{"n": "中筋面粉","q": "300g","a": "减到200g面条偏细、吸汁少；加到400g需延长和面时间否则擀不开"},{"n": "红糖","q": "50g","a": "减到30g甜味不够、芝麻酱发腻；加到80g甜到发苦"},{"n": "芝麻酱","q": "40g","a": "减到20g香味不足、挂不匀；加到60g稠成膏、拌不动"},{"n": "红油","q": "30ml","a": "减到15ml不上色、辣味缺；加到50ml辣味盖过甜味"},{"n": "生抽","q": "25ml","a": "减到12ml咸味不足；加到40ml过咸"},{"n": "香醋","q": "15ml","a": "减到8ml甜腻不散；加到25ml酸得倒牙"},{"n": "白糖","q": "5g","a": "减到2g酸咸打架；加到10g更甜"},{"n": "花生碎","q": "30g","a": "减到15g口感单薄；加到50g吸油、拌不匀"},{"n": "蒜泥","q": "12g","a": "减到5g蒜香弱；加到25g蒜味生冲"},{"n": "熟白芝麻","q": "8g","a": "减到3g香气平淡；加到15g略多"}],"steps": ["面粉加盐2g和清水170ml揉成硬面团（能拉出粗面条的硬度），盖湿布醒30分钟。","醒好的面团擀成约3mm厚的大片，折叠后切成约1cm宽的长条，抖散备用。","宽水大火烧开，下面条煮2分半至3分钟，掐断无白芯即捞出，立即过一遍凉开水让面爽滑有弹性，沥干装碗。","碗底放芝麻酱、红糖、红油、生抽、香醋、白糖、蒜泥、少许凉白开（约40ml）搅匀成浓稠酱汁。","把面条整齐铺入碗中，从底部彻底翻拌20下，让每根粗面都挂满酱汁。","撒花生碎和熟白芝麻，吃前再从底部翻拌一次即可。"],"key": "面条要手工擀到3mm左右，粗而扁才挂得住芝麻酱；机器细面口感完全不同。","tip": "甜水面讲究甜而不腻，芝麻酱必须先用凉白开澥开再加糖，直接把酱和糖搅会结块。"},"军屯锅盔": {"time": "2小时","level": "中等","servings": "4人份","ing": [{"n": "中筋面粉","q": "400g","a": "减到300g饼太厚不易烤透；加到500g需延长醒发30分钟"},{"n": "菜籽油（和面用）","q": "120ml","a": "减到60ml层次少、只有厚实不酥；加到200ml饼过酥易破、卷制时难成形"},{"n": "椒盐","q": "10g（盐7g、花椒粉3g）","a": "减到5g无咸味花椒香；加到18g过咸、抢走肉味"},{"n": "酵母","q": "4g","a": "减到2g发不起来；加到8g发得过快、饼易发酸"},{"n": "温水","q": "210ml","a": "减到170ml面团偏硬难卷；加到260ml面团太软、粘案板"},{"n": "红糖（卷层用）","q": "30g","a": "减到15g甜味弱；加到60g过甜发苦"},{"n": "白芝麻","q": "15g","a": "减到8g香气不足；加到30g会焦"},{"n": "卤肉馅","q": "250g（肥瘦3:7，卤熟切碎）","a": "减到150g夹起来漏油；加到350g太油腻"},{"n": "生菜与香菜","q": "各30g","a": "减到15g解腻不足；加到60g菜太多抢味"},{"n": "食用碱水（可选）","q": "2ml","a": "加到5ml饼发黄带碱味；可省略"}],"steps": ["面粉、菜籽油、椒盐、酵母倒入盆中，先用60ml温水化开酵母倒回，剩余温水分次加入，揉成光滑偏硬的面团。","盖保鲜膜发酵至两倍大（约60分钟），手指戳洞不回缩即发好。","取出面团擀成长方形薄片，抹上红糖与剩余菜籽油，均匀撒白芝麻。","从长边卷成筒，再盘成螺旋饼坯，用擀面杖从中间向外擀成直径约20cm、厚约1.5cm的圆饼。","静置醒发15分钟，让酥层松弛，烤时才能鼓起层次。","烤箱预热230℃中层，饼坯放入烤盘，中火烤15分钟至表面金黄起酥、层次分开。","出炉后趁热从侧面剖开成口袋状但不切断，夹入卤肉馅、生菜、香菜，挤上少量卤汁即可。"],"key": "酥层来自烫面卷酥：抹红糖油后卷起再盘成螺旋，擀时不能把层次擀死，层次越分明烤出来越掉渣。","tip": "军屯锅盔讲究现烤现夹，凉了酥层回软；缸炉烤比烤箱更立体，但家用烤箱200℃需多烤5分钟。"},"成都肥肠粉": {"time": "2小时","level": "稍难","servings": "3人份","ing": [{"n": "肥肠","q": "600g","a": "减到400g份量不足；加到800g需延长卤制40分钟"},{"n": "红薯粉","q": "150g","a": "减到100g粉少汤宽；加到200g粉条过密、拌不开"},{"n": "郫县豆瓣","q": "25g","a": "减到10g汤色不红、香味不足；加到40g汤过咸需减盐"},{"n": "豆豉","q": "15g","a": "减到8g咸鲜不足；加到25g过咸"},{"n": "姜蒜","q": "姜20g、蒜30g","a": "蒜减到15g蒜香弱；加到50g蒜味太冲"},{"n": "花椒","q": "8g","a": "减到4g麻味不足；加到15g麻得盖住豆瓣香"},{"n": "干辣椒段","q": "15g","a": "减到8g没有辣型香；加到30g辣度过高"},{"n": "高汤或清水","q": "900ml","a": "减到600ml汤太浓稠、粉不易烫熟；加到1.2L则味淡需补盐"},{"n": "红油","q": "40ml","a": "减到20ml汤色偏淡；加到60ml表面浮油过多"},{"n": "葱花与香菜","q": "各15g","a": "减到8g香气弱；加到30g盖住汤色"}],"steps": ["肥肠翻面用盐和面粉反复揉搓冲洗3遍去净黏液，剪成3cm段，冷水下锅加姜、料酒焯3分钟，撇净浮沫捞出冲洗。","锅中下红油与剁细的豆瓣小火炒2分钟出红油，加豆豉、姜蒜末、干辣椒段炒1分钟。","倒入高汤900ml烧开，下肥肠段转小火加盖炖60分钟至肥肠软糯，用筷子能轻松夹断。","捞出1/3肥肠切段装碗，其余留汤中，调盐、生抽10ml、白胡椒粉2g调味成红汤。","红薯粉用温水泡30分钟至软；碗底先放红油40ml、生抽10ml、蒜泥、少许味精。","锅中水烧开下粉条煮3-4分钟至透明无白芯，捞入碗中。","舀一勺滚烫红汤冲入碗中把粉烫热，再放上切好的肥肠节子，撒花椒粉、葱花和香菜，拌匀食用。"],"key": "肥肠去腥的关键是面粉加盐反复揉搓，再焯水去浮沫；焯不干净则一锅汤都是腥味。","tip": "红油要先在豆瓣里炒出红油再兑汤，直接把红油淋进清水汤里颜色发浑、味道寡淡。"},"藤椒鸡": {"time": "40分钟","level": "简单","servings": "2人份","ing": [{"n": "鸡腿肉","q": "400g","a": "减到250g份量少；加到500g需延长焯水时间、味道变淡"},{"n": "鲜藤椒","q": "30g","a": "减到15g麻香明显不足；加到50g麻得盖住鸡味、舌头发木"},{"n": "干青花椒","q": "5g","a": "减到2g麻味单薄；加到10g麻感过重"},{"n": "小米辣","q": "15g","a": "减到8g辣度不足；加到30g辣味盖过麻香"},{"n": "姜蒜末","q": "姜15g、蒜20g","a": "蒜减到10g香气弱；加到35g蒜味生冲"},{"n": "熟白芝麻","q": "10g","a": "减到5g香味不足；加到20g略多"},{"n": "食用油","q": "50ml","a": "油温低于170℃激不出藤椒香；减到30ml则粉不均匀"},{"n": "生抽","q": "20ml","a": "减到12ml咸度不够；加到30ml过咸"},{"n": "香醋","q": "8ml","a": "减到4ml不解腻；加到15ml酸味压住麻味"},{"n": "白糖","q": "4g","a": "减到2g辣味发苦；加到8g偏甜"}],"steps": ["鸡腿去骨切1.5cm见方的丁，加盐1g、生抽10ml、料酒10ml抓匀腌15分钟。","锅中水烧开，下鸡丁焯30秒至变色，捞出立刻过冰水激紧，口感更嫩爽。","鲜藤椒与干青花椒剁成碎末，加盐2g、蒜末、姜末、小米辣圈拌匀成料糊。","锅中油烧至七成热（约190℃），把热油分两次泼在料糊上，边泼边用筷子搅匀，激出藤椒的清麻香。","料糊晾至温热后加入生抽10ml、香醋8ml、白糖4g拌匀。","鸡丁沥干水分，与料糊充分拌匀使每块鸡丁都挂上椒麻料。","撒熟芝麻，装盘即食，冷藏10分钟后风味更融合。"],"key": "藤椒必须用七成热油泼激才出清麻香，直接拌生藤椒泥只有麻没有香，颜色也不亮。","tip": "没有鲜藤椒可用藤椒油代替，减到10ml并减少油量；用青花椒粉替代干花椒则麻味更浑浊。"},"老妈蹄花": {"time": "3小时","level": "中等","servings": "3人份","ing": [{"n": "猪蹄（前蹄）","q": "2只约1000g","a": "减到600g不够3人份；加到1.5kg需延长炖煮40分钟"},{"n": "老姜","q": "60g","a": "减到30g去腥不足；加到100g姜味太重压住椒麻"},{"n": "大葱","q": "1根","a": "去掉则香气少一半；换成3根会发甜"},{"n": "汉源花椒","q": "15g","a": "减到8g麻味不足；加到25g麻得盖住其他味"},{"n": "干辣椒段","q": "15g","a": "减到8g只有椒香没有辣味；加到30g辣味过重"},{"n": "料酒","q": "40ml","a": "减到20ml腥味残留；加到60ml酒味重"},{"n": "醪糟（糟水）","q": "50g","a": "减到20g酒香不足；加到100g带明显酒味、甜度过高"},{"n": "盐","q": "20g","a": "减到12g蹄花入味不足；加到30g过咸、肉发紧"},{"n": "蒜泥","q": "30g","a": "减到15g蘸水不香；加到50g蒜味刺鼻"},{"n": "红油与花椒粉（蘸碟）","q": "红油40ml、花椒粉4g、生抽25ml、香醋12ml","a": "红油减到20ml色淡；花椒粉加到8g太麻"}],"steps": ["猪蹄用刀从中间劈成两半，洗净后冷水下锅，加姜块、葱段、料酒，中火煮5分钟，撇净所有浮沫后捞出用温水冲洗干净。","砂锅中重新加清水1.5L，放入蹄花、姜块、花椒、干辣椒、醪糟，大火烧开转小火炖2.5小时。","炖至用筷子能轻松插入蹄骨而不散，肉皮呈半透明胶状时关火，加盐20g再炖10分钟入味。","连汤倒入容器，晾凉后放入冰箱冷藏2小时以上，让蹄花凝冻变弹。","取出斩成大块装盘，汤另盛小碗或过滤后留作底。","蘸碟：蒜泥、生抽、香醋、红油、花椒粉、少许盐调匀。","吃时以蹄花蘸取，或淋少许原汤后拌食。"],"key": "炖蹄花中途不能揭盖、汤要一次加足，否则蹄皮会收缩变硬；冷却是蹄花弹牙的关键。","tip": "用高压锅上汽后压40分钟可省时，但皮的口感不如砂锅炖的糯；蘸碟可加香菜、蒜苗提味。"},"白切鸡": {"time": "50分钟","level": "中等","servings": "3人份","ing": [{"n": "三黄鸡或清远鸡","q": "1只约1.2kg","a": "减到800g不够3人份；加到1.8kg需每500g延长3分钟浸煮"},{"n": "姜","q": "60g（煮鸡20g、蘸料40g）","a": "减到30g姜味不足；加到100g姜末太粗、抢鸡味"},{"n": "葱","q": "80g（煮鸡40g、蘸料40g）","a": "减到40g香气弱；加到120g过辛"},{"n": "花椒","q": "8g","a": "减到4g无麻；加到15g麻得盖住鸡鲜"},{"n": "盐","q": "8g（蘸料用）","a": "减到4g姜葱蓉寡淡；加到15g过咸"},{"n": "食用油","q": "50ml（泼香用）","a": "油温低于170℃激不出葱香；减到30ml葱姜蓉发干"},{"n": "花生油（可选增香）","q": "10ml","a": "可省略；加入更香"},{"n": "料酒","q": "20ml","a": "减到10ml去腥弱；加到40ml酒味残留"}],"steps": ["整鸡洗净去内脏，锅中加足量清水（没过鸡身1倍）、姜片、葱结、花椒、料酒，大火烧开。","提着鸡颈将鸡浸入沸水烫10秒提起，倒掉锅里的水（这是让鸡腔内外温度一致的关键动作），重复三次。","把鸡整只沉入锅中，转小火保持水面微微冒泡不剧烈沸腾，浸25分钟；判断标准是筷子插鸡腿最厚处无血水渗出。","立刻捞出放入冰水中浸10分钟，让鸡皮收缩变爽脆，捞出沥干斩件摆盘。","姜葱剁成蓉加盐拌匀。","油烧至八成热冒青烟，分两次浇在姜葱蓉上，边浇边搅激出葱香，晾至温热即成蘸料。","斩好的鸡件配姜葱蓉上桌。"],"key": "白切鸡的火候全在浸煮：水温保持虾眼水不沸腾，全鸡浸25分钟，过火则肉柴、过嫩则血水未净。","tip": "斩鸡要等鸡彻底凉了再斩，热斩会压破鸡皮渗出汁水；蘸料可加少量沙姜或香菜。"},"广式烧鹅": {"time": "2小时","level": "稍难","servings": "4人份","ing": [{"n": "黑棕鹅或梅头肉","q": "1只约2.5kg（半只也行）","a": "减到1.5kg皮脆度不够、皮薄处易破；加到3kg需延长炉时15分钟"},{"n": "蒜蓉","q": "30g","a": "减到15g蒜香不足；加到50g蒜味盖住鹅油香"},{"n": "甜面酱或南乳","q": "南乳25g","a": "减到12g颜色淡、缺少发酵香；加到40g过咸发苦"},{"n": "麦芽糖","q": "50g","a": "减到30g上色浅、脆度不足；加到80g甜味过重"},{"n": "海鲜酱","q": "20g","a": "减到10g鲜味弱；加到35g偏咸"},{"n": "五香粉","q": "5g","a": "减到2g香气不足；加到10g香料味重、压住鹅香"},{"n": "精盐","q": "12g","a": "减到6g挂料淡；加到20g过咸"},{"n": "五香粉与白胡椒粉（擦腌用）","q": "各3g","a": "可并入上项；单擦用"},{"n": "玫瑰露酒或米酒","q": "20ml","a": "减到10ml香气不足；加到40ml酒味重"},{"n": "酸梅酱（配食）","q": "50g","a": "减到30g解腻不足；加到80g太酸"}],"steps": ["鹅洗净擦干，蒜剁蓉，与南乳、海鲜酱、麦芽糖、盐、五香粉、白胡椒、玫瑰露调成挂糊，均匀涂满鹅身内外。","用铁叉或竹签在鹅皮上均匀扎小孔，让挂料渗入，同时便于排油；挂起风干2小时至表皮收紧发干。","烤箱预热260℃，把鹅架在烤网上，烤盘下垫锡纸接油，先烤25分钟给皮定型上色。","取出鹅身刷一遍麦芽糖浆（糖浆用1:1水稀释），再入炉260℃烤20分钟，至表皮金红起泡、敲起来有干脆声。","关火不开炉门，焖20分钟让肉汁回流到皮下，这一步决定皮下是否多汁。","取出刷一层熟油防止表皮发干，晾10分钟后斩件。","配酸梅酱或芥末生抽上桌。"],"key": "烧鹅皮脆的秘密是风干、扎孔、排油、刷糖、焖炉五步连贯，缺一环皮就回软不脆。","tip": "没有挂炉用烤箱也能成，但温度需更高、时间更长，250℃烤25分钟加焖20分钟；麦芽糖不可用白砂糖代替，否则皮不脆。"},"蜜汁叉烧": {"time": "1.5小时","level": "中等","servings": "3人份","ing": [{"n": "梅头肉或带皮五花","q": "700g","a": "减到500g份量不足；加到900g需延长烤制15分钟"},{"n": "南乳","q": "20g","a": "减到10g颜色不够红、发酵香弱；加到35g过咸"},{"n": "蚝油","q": "20g","a": "减到10g鲜味不足；加到35g偏咸、甜味被压"},{"n": "芝麻酱","q": "10g","a": "减到5g香度不足；加到20g发腻"},{"n": "蒜蓉","q": "15g","a": "减到8g蒜香弱；加到25g蒜味冲"},{"n": "玫瑰露酒或料酒","q": "20ml","a": "减到10ml去腥不足；加到35ml酒味重"},{"n": "白糖","q": "30g","a": "减到15g不够甜；加到50g齁甜"},{"n": "蜂蜜","q": "30g","a": "减到15g上色与焦化不足；加到50g太甜、边缘易焦"},{"n": "柱侯酱","q": "15g","a": "减到8g风味单薄；加到25g酱味过重"},{"n": "五香粉","q": "3g","a": "减到1.5g香气淡；加到6g香料味压过蜜香"}],"steps": ["梅头肉切成3cm宽、2cm厚的长条，洗净擦干。","南乳压碎，与蚝油、芝麻酱、蒜蓉、玫瑰露、白糖、柱侯酱、五香粉、少量生抽调匀成腌料。","腌料与肉条充分抓匀按摩5分钟，让肉缝吸满味，静置冷藏4小时以上（隔夜最佳）。","烤箱预热200℃，烤盘垫锡纸，肉条架起摆放，先烤20分钟。","取出翻面，刷上一层稀释蜜汁（蜂蜜与水1:1），再烤15分钟。","取出刷第二层蜜汁，转上火230℃再烤8-10分钟，表面起焦亮、边缘微微发黑即为糖化到位。","出炉静置10分钟再切片，切片后可见漂亮的焦糖色边与肉汁。"],"key": "叉烧的颜色来自糖而非酱油，腌料里的酱油只管咸味；上色靠分次刷蜜汁加高温焦化。","tip": "用梅头肉（猪颈肉）比五花肉更嫩不腻；烤到最后阶段守着看，蜂蜜很容易从焦糖色变成焦黑。"},"虾饺": {"time": "90分钟","level": "稍难","servings": "3人份","ing": [{"n": "澄面","q": "150g","a": "减到100g皮偏薄易破；加到200g皮太厚、蒸不透"},{"n": "生粉","q": "50g（澄面生熟比1:1.5）","a": "减到30g皮太软粘手；加到80g皮发硬、开裂"},{"n": "猪油","q": "10g","a": "减到5g皮无油光、韧性差；加到20g皮发腻"},{"n": "滚开水","q": "220ml","a": "水量不足面团夹生；多到260ml面团过软粘案板"},{"n": "鲜虾仁","q": "300g","a": "减到200g馅少味淡；加到400g一只饺塞不下、难捏褶"},{"n": "肥膘（猪板油）","q": "30g","a": "减到15g口感不够滑；加到60g油腻"},{"n": "笋丁","q": "40g","a": "减到20g鲜味不足；加到60g抢虾味"},{"n": "盐与白胡椒粉","q": "盐4g、白胡椒粉1g","a": "盐减到2g虾不甜；加到6g发咸"},{"n": "蛋清","q": "1个","a": "减半则上浆不足虾仁不脆；加到2个馅发黏难包"},{"n": "淀粉（腌虾用）","q": "10g","a": "减到5g虾仁出水；加到20g馅发糊"}],"steps": ["澄面与生粉混匀，分次倒入滚开水，边倒边用筷子快速搅成絮状，再揉成光滑面团，加猪油揉匀，盖保鲜膜醒30分钟。","鲜虾去壳去虾线，保留尾部或不用，留尾更美观；用盐1g、蛋清、淀粉抓匀腌10分钟至虾仁发黏。","肥膘切小丁，笋丁切碎；虾仁一半剁成泥一半留粒。","虾泥、肥膘丁、笋丁加盐3g、白胡椒粉，顺一个方向搅打3-5分钟至上劲发黏（这是虾饺弹的关键）。","面团搓成长条切剂子，按扁后擀成中间厚边缘薄的圆皮，直径约7cm。","放馅后一手托皮一手捏褶，捏出12褶以上，收口捏成梳子形（蟹子饺），尾部收拢。","蒸锅水开后上屉，大火蒸7-8分钟（虾饺皮变透亮、能看到馅色即熟），关火焖1分钟再开盖，避免皮回缩。"],"key": "澄面皮必须用滚开水一次冲熟，比例约1:1.5，馅要顺一个方向搅打上劲，两者决定虾饺皮薄透、馅弹。","tip": "手慢的话先包好再蒸，但虾皮久放会回缩；一次蒸不超过15分钟，久蒸虾肉变老。"},"肠粉": {"time": "60分钟","level": "稍难","servings": "3人份","ing": [{"n": "大米","q": "150g","a": "减到100g浆薄易破；加到200g浆厚、蒸出来发硬"},{"n": "清水（磨浆用）","q": "200ml","a": "米水比控制在1:1.3，减到150ml浆太稠挂不住勺；加到260ml浆太稀会漏"},{"n": "澄面","q": "10g","a": "减到5g皮不够爽滑；加到20g皮偏硬、失去米香"},{"n": "鸡蛋","q": "2个","a": "减到1个蛋香不足；加到3个蛋味重、盖住米香"},{"n": "瘦肉末","q": "120g","a": "减到80g料少；加到180g口感太干"},{"n": "虾仁","q": "80g","a": "减到40g鲜度不足；加到150g需多蒸1分钟"},{"n": "蒸鱼豉油","q": "50ml","a": "减到30ml咸度不够；加到70ml过咸盖住米香"},{"n": "白糖","q": "8g","a": "减到4g豉汁发苦；加到15g太甜"},{"n": "香菇与虾米（泡水）","q": "香菇3朵、虾米8g","a": "可省略；加量到双倍则豉汁过鲜"},{"n": "葱花与熟油","q": "葱花15g、食用油10ml","a": "葱花减到8g香气弱；熟油可省略"}],"steps": ["大米洗净用清水浸泡3小时，加水打成米浆，用细筛过滤两遍去渣，倒入盆中加澄面搅匀静置30分钟。","瘦肉切末加生抽5ml、淀粉5g腌10分钟；虾仁切丁。","豉汁：蒸鱼豉油50ml、白糖8g、泡软的香菇虾米及水50ml煮开，勾薄芡成芡汁备用。","抽屉式肠粉机或蒸盘刷薄油烧热，倒入一薄层米浆（约30ml）快速摊平。","铺上肉末和虾仁，淋入打散的蛋液，大火蒸3-4分钟至米浆起大泡、边缘变透明。","用刮板从蒸盘一端把米皮卷起成卷，移到盘中，用刀斩成3-4cm段。","淋上滚烫的豉油芡汁，撒葱花，淋几滴熟油。"],"key": "米浆要过滤两遍且不能太稀，蒸的时候米浆起大气泡、边缘透亮才是熟透的标志；蒸过头会发硬起皮。","tip": "在家可用平底不锈钢盘代替蒸盘，一样能卷；布拉肠要现蒸现吃，放久米皮会回硬回黏。"},"煲仔饭": {"time": "50分钟","level": "中等","servings": "2人份","ing": [{"n": "丝苗米","q": "300g","a": "减到200g份量少、锅底不够厚难结锅巴；加到400g需加大水量并延长焗制5分钟"},{"n": "广式腊肠","q": "2条约150g","a": "减到1条腊味不足；加到3条油脂过多、饭发腻"},{"n": "广式腊肉","q": "80g","a": "减到40g咸香不足；加到150g过咸需减豉汁"},{"n": "猪油","q": "15g","a": "减到8g锅巴不脆；加到30g饭偏腻"},{"n": "青菜（菜心或芥蓝）","q": "200g","a": "减到100g份量少；加到300g焗时会出太多水"},{"n": "清水","q": "330ml（水米比1:1.1）","a": "减到280ml饭偏硬；加到380ml需延长焗制8分钟"},{"n": "蚝油","q": "10g","a": "减到5g鲜味弱；加到20g太咸"},{"n": "生抽","q": "20ml","a": "减到10ml咸度不够；加到30ml过咸"},{"n": "白糖","q": "5g","a": "减到2g豉汁发苦；加到10g偏甜"},{"n": "姜丝","q": "8g","a": "减到4g去腊味不足；加到15g姜味太重"}],"steps": ["丝苗米淘净后浸泡30分钟沥干；砂锅内壁用姜丝擦一遍再抹一层猪油，这就是防粘的关键。","米入砂锅，加清水330ml铺平，大火烧开后转最小火，盖盖焗8分钟。","把腊肠斜切、腊肉切片铺在饭面上，继续盖盖小火焗8-10分钟，至锅边冒泡、饭粒收水变干。","沿锅边淋一圈猪油10ml，把洗好的青菜竖插在饭四周，盖盖再焗3分钟，让菜熟并逼出锅巴香气。","取一勺生抽20ml、蚝油10g、白糖5g、姜丝调成豉汁备用。","关火后先淋豉汁入锅底迅速翻拌均匀，让每一粒米都裹上酱色。","用饭勺把饭翻松、把底部的金黄锅巴饭翻上来（锅巴最香），铺上余下的腊味即可。"],"key": "锅巴要靠砂锅底高温、少量水、沿边淋油三件事配合；水太多只会煮成稀饭，底不会结锅巴。","tip": "没有砂锅可用厚底小锅，但要先干烧2分钟形成粗糙底面，锅巴效果差一些；淋豉汁一定在关火后翻拌，锅还热时淋会苦。"},"云吞面": {"time": "2小时","level": "稍难","servings": "2人份","ing": [{"n": "竹升面（碱水面）","q": "300g","a": "减到200g份量少；加到400g需多煮30秒并多冲一次碱水"},{"n": "鲜虾仁","q": "200g","a": "减到120g馅味单薄；加到300g包不稳、汤也浑"},{"n": "猪前腿肉","q": "100g","a": "减到60g云吞馅太瘦发柴；加到150g馅偏肥"},{"n": "大地鱼（干）","q": "20g","a": "减到10g汤鲜味不足；加到35g汤味过腥发臭"},{"n": "猪骨","q": "500g","a": "减到300g汤不浓白；加到800g需延长熬煮时间"},{"n": "荸荠（马蹄）","q": "30g","a": "减到15g脆度不足；加到50g馅过甜发脆"},{"n": "韭黄","q": "60g","a": "减到30g香气与配色弱；加到100g抢味"},{"n": "生抽","q": "15ml","a": "减到8ml汤味不足；加到25ml过咸"},{"n": "麻油","q": "10ml","a": "减到5ml香气不足；加到20ml盖住汤鲜"},{"n": "猪油","q": "8g","a": "减到4g面不滑；加到15g汤面浮油过多"}],"steps": ["猪骨焯水去血沫，加姜片、2500ml清水大火烧开转小火熬90分钟至汤色奶白。","大地鱼用温水泡软洗净，放汤中再煮15分钟，起锅前把鱼捞出（留汤），避免腥味过重。","虾仁一半切丁一半剁成泥，猪肉剁成泥，加马蹄碎、盐2g、白胡椒粉、少量淀粉水，顺一个方向搅打上劲至发黏。","包云吞：取一张竹升面皮放馅，对折捏紧两角使其成蝴蝶状，收口用手指捏一下防漏。","竹升面另起锅宽水加少许油和碱水，煮90秒至刚断生，捞出立刻用凉开水冲一遍去掉碱味，沥干。","碗底放生抽15ml、麻油10ml、猪油8g、少许滚汤，把面摆入碗中。","云吞放入另一锅中用滚汤烫熟（约1分钟），连汤一起倒入面碗中，最后铺韭黄60g。"],"key": "竹升面必须煮到刚断生就捞出并冲碱水，煮过头会糊、碱味重；汤要奶白但不能有渣。","tip": "汤底可用大地鱼干和虾壳一起熬，层次更足；正宗云吞面讲究面、汤、馅三味分开出味再汇合。"},"艇仔粥": {"time": "50分钟","level": "简单","servings": "2人份","ing": [{"n": "大米","q": "150g","a": "减到100g粥太稀不挂勺；加到200g需多加水并延长熬煮5分钟"},{"n": "清水","q": "1.5L","a": "减到1.2L粥太稠；加到1.8L米味变淡要补盐"},{"n": "鱼片（草鱼或鲈鱼）","q": "150g","a": "减到80g料不足；加到250g需多烫1分钟"},{"n": "油条","q": "1根","a": "减到半根吸油不足；加到2根泡粥易烂"},{"n": "花生米（油炸）","q": "30g","a": "减到15g口感单薄；加到50g会抢粥味"},{"n": "麻油","q": "10ml","a": "减到5ml香气不足；加到20ml过香"},{"n": "姜丝","q": "15g","a": "减到8g去腥不足；加到25g姜味太重"},{"n": "葱花","q": "15g","a": "减到8g香气弱；加到30g会发蔫"},{"n": "生抽","q": "10ml","a": "减到5ml味不足；加到20ml粥发咸"},{"n": "猪皮冻或皮蛋（增稠）","q": "皮蛋1个","a": "可省略；加到2个粥色发黑"}],"steps": ["大米淘净，加1勺油和少许盐拌匀腌15分钟，这样煮出来的粥米粒更靓更绵。","锅中加1.5L清水大火烧开，下米，转最小火保持微微冒泡的状态熬35-40分钟，期间用勺子贴着锅底不停搅动防止糊底。","熬到米粒开花、粥面起稠如米油浮层即成；用勺子提起能成线缓慢滴落。","鱼片用少许盐、姜丝、料酒腌10分钟，粥快好时下入鱼片，用勺子轻轻推动，烫熟即可不要久煮。","油条剪成小段，剩余部分撕碎放入碗底。","碗中加生抽10ml、麻油10ml、姜丝、葱花、炸花生米。","盛入滚烫的艇仔粥铺上油条段，趁热拌开食用。"],"key": "艇仔粥讲究绵滑，熬粥必须小火不沸腾并持续搅动，火大就会米粒开花成渣、失去米油。","tip": "油条要最后放不能久泡，泡久了就烂了失去脆感；想更鲜可加皮蛋或瑶柱同熬。"},"清蒸鲈鱼": {"time": "25分钟","level": "简单","servings": "2人份","ing": [{"n": "鲈鱼","q": "1条约600g","a": "减到400g份量少；加到800g需每500g延长3分钟蒸制"},{"n": "姜","q": "40g（垫底与铺面）","a": "减到20g去腥不足；加到70g姜味抢鱼鲜"},{"n": "葱","q": "50g","a": "减到25g香气不足；加到80g葱味过冲"},{"n": "蒸鱼豉油","q": "40ml","a": "减到25ml咸鲜不足；加到60ml过咸盖住鲜味"},{"n": "食用油","q": "30ml","a": "减到15ml葱香激不出；加到50ml油多不香"},{"n": "料酒","q": "15ml","a": "减到8ml腥气残留；加到25ml酒味重"},{"n": "盐","q": "3g","a": "减到1g鱼不够入味；加到6g鱼肉发紧"},{"n": "白胡椒粉","q": "1g","a": "可省略；加到3g有粉渣感"},{"n": "蒸鱼豉油（调味）","q": "40ml","a": "可与上面合并"},{"n": "红椒丝（装饰）","q": "10g","a": "可省略；加到20g偏辣"}],"steps": ["鲈鱼处理干净，两面各划3刀至鱼骨，擦干水分，用盐3g和白胡椒粉抹匀鱼身内外，淋料酒15ml腌10分钟。","盘底铺两根筷子或几段葱姜架空鱼身，让蒸汽能从鱼身下循环，鱼肉受热均匀不夹生。","锅中水完全烧开（必须大滚），把鱼连盘放入蒸屉，大火蒸8分钟（1斤鱼8分钟，关火虚蒸2分钟），鱼肉能轻松脱骨即熟。","取出倒掉盘中腥水（这一步不能省），拣去旧葱姜，重新铺上新鲜葱丝和姜丝。","淋上蒸鱼豉油40ml，均匀浇在鱼身上。","锅中油烧至冒青烟（约200℃），趁热泼在葱丝姜丝上，激出葱香。","上桌前撒几根红椒丝或葱花装饰。"],"key": "蒸鱼时间按重量算（每500g蒸5分钟）且水要大开；蒸好后盘里的腥水必须倒掉，否则鱼是腥的。","tip": "豉油本身含盐，一般不需要再额外加盐；喜欢更鲜可把蒸鱼豉油换成蒸鱼豉油加一点点糖。"},"白灼虾": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "基围虾或竹节虾","q": "500g","a": "减到300g份量少；加到800g需分两锅煮、否则水温降得快"},{"n": "姜","q": "30g（煮虾20g、蘸料10g）","a": "减到15g去腥不足；加到50g姜味过重"},{"n": "葱","q": "30g","a": "减到15g香气弱；加到50g葱味太冲"},{"n": "料酒","q": "20ml","a": "减到10ml虾有腥味；加到35ml酒味残留"},{"n": "盐","q": "10g","a": "减到5g虾不够入味；加到20g虾肉发紧、虾脑发苦"},{"n": "蒸鱼豉油或生抽","q": "30ml","a": "减到20ml咸度不够；加到45ml过咸"},{"n": "香醋","q": "10ml","a": "减到5ml不够开胃；加到20ml太酸"},{"n": "姜末","q": "10g","a": "减到5g香气弱；加到20g姜末太粗"},{"n": "熟花生油或芝麻油","q": "10ml","a": "减到5ml香气不足；加到20ml盖住鲜味"},{"n": "冰水","q": "1盆","a": "可省略；使用后虾肉更弹"}],"steps": ["虾剪去虾须、挑出虾线，冲洗干净；锅中水加姜片、葱段、料酒和盐10g大火烧开。","下虾，保持中火煮90秒到2分钟，看到虾身弯曲变红、虾头虾身连接处变白即熟，立即捞出。","捞出立刻放入冰水浸1-2分钟，让虾肉收紧变弹（这是虾肉爽脆的关键）。","捞出沥干摆盘。","蘸料：姜末10g、蒸鱼豉油或生抽30ml、香醋10ml拌匀，淋一勺烧热的熟花生油激香。","虾上桌后尽快吃，久放虾肉会变绵。"],"key": "白灼虾只看一个标准：虾身弯成弓形、虾头与虾身交界处变白，立刻捞出，多煮10秒肉就变韧。","tip": "一定要用活虾；死虾煮出来虾肉发暗、纤维发柴。蘸料里加几滴芥末或小米辣更提味。"},"豉汁蒸排骨": {"time": "45分钟","level": "简单","servings": "2人份","ing": [{"n": "猪肋排","q": "500g","a": "减到350g份量少；加到700g需每500g延长2分钟蒸制"},{"n": "豆豉","q": "20g","a": "减到10g豉香不足；加到30g过咸、发酵味重"},{"n": "生抽","q": "20ml","a": "减到12ml咸度不够；加到30ml过咸"},{"n": "蚝油","q": "10g","a": "减到5g鲜味弱；加到18g偏甜腻"},{"n": "白糖","q": "6g","a": "减到3g豉味发苦；加到12g太甜"},{"n": "生粉","q": "10g","a": "减到5g排骨干柴；加到20g会黏成坨"},{"n": "食用油","q": "15ml","a": "减到8ml发干；加到25ml蒸时出油多"},{"n": "姜丝","q": "15g","a": "减到8g去腥不足；加到25g姜味重"},{"n": "蒜末","q": "20g","a": "减到10g蒜香弱；加到35g蒜味冲"},{"n": "葱花","q": "10g","a": "减到5g香气弱；加到20g发蔫"}],"steps": ["肋排斩成3cm小段，冲水15分钟去血水，沥干后用厨房纸吸干水分。","豆豉略剁碎，与生抽、蚝油、白糖、生粉、食用油、料酒10ml、白胡椒粉1g、蒜末一半拌匀。","排骨与腌料抓匀，静置30分钟入味。","腌好的排骨平铺在盘中，摊平不要叠太厚（叠起来受热不均，中间会夹生），上面铺姜丝和剩余蒜末。","锅中水烧开，放上蒸屉，大火蒸12分钟（500g排骨12分钟），关火虚蒸2分钟。","用筷子能轻松插入排骨即熟透；肉质偏柴说明时间不足，发软发烂则说明蒸过头。","出锅撒葱花10g，淋一勺热油激香。"],"key": "排骨要摊平单层蒸、腌料含生粉锁水，火候足到筷子能插入而不散，蒸出来才是早茶那种滑嫩。","tip": "豆豉本身很咸，生抽要减量；蒸好撒葱花淋热油那一步能让香气翻倍。"},"老火靓汤": {"time": "3.5小时","level": "简单","servings": "3人份","ing": [{"n": "猪筒骨或老鸡","q": "600g","a": "减到400g汤味不够醇；加到900g需延长1小时"},{"n": "瑶柱","q": "15g","a": "减到8g鲜味打折；加到25g汤过鲜带腥"},{"n": "干贝","q": "10g","a": "减到5g鲜味弱；加到20g腥味过重"},{"n": "南杏","q": "10g","a": "减到5g润肺不足；加到20g汤带苦涩"},{"n": "北杏","q": "5g","a": "减到2g不够香；加到10g苦味明显"},{"n": "陈皮","q": "5g","a": "减到2g陈香弱；加到10g陈皮味苦"},{"n": "蜜枣","q": "3颗","a": "减到1颗甜度不足；加到5颗过甜发腻"},{"n": "老姜","q": "40g","a": "减到20g去腥弱；加到70g姜味太重"},{"n": "清水","q": "2.5L","a": "减到2L需多加油；加到3L汤味变淡需补盐"},{"n": "盐","q": "8g（起锅前放）","a": "减到4g汤味寡淡；加到15g过咸"}],"steps": ["猪筒骨或鸡块冷水下锅，加姜片和料酒焯5分钟，撇净血沫捞出冲洗干净，砂锅用清水涮一遍不留油。","瑶柱、干贝用温水泡30分钟至软，洗净；南杏、北杏、陈皮、蜜枣快速冲洗。","砂锅中放骨头、姜片、瑶柱、干贝、南杏、北杏、蜜枣和清水2.5L。","大火烧开，撇一次浮沫，转最小火保持汤面只冒小泡（像菊花心）的状态慢煲3小时，中途不加水不加盐。","出锅前10分钟加盐8g，再煲10分钟让盐味融入汤中。","捞出药材，只留清汤；汤色清亮、入口有回甘即为合格。"],"key": "老火汤讲三不：不时加冷水、不早放盐、不大火滚；大火滚汤会变浑浊，盐早放肉就柴。","tip": "这是广式例汤的骨架，可随季节换料：夏天加薏米、冬天加桂圆红枣；隔夜汤回滚一次风味不减。"},"双皮奶": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "全脂牛奶","q": "500ml","a": "减到300ml奶皮太薄、只有一层；加到700ml需用大碗、蒸的时间延长3分钟"},{"n": "蛋清","q": "3个","a": "减到2个结不起第二层皮；加到5个会有蛋腥味"},{"n": "白糖","q": "40g","a": "减到25g不够甜；加到60g齁甜盖住奶香"},{"n": "双皮碗或浅口碗","q": "1个","a": "碗太深只能结一层皮；用两个碗可做双份"},{"n": "淡奶（可选）","q": "20ml","a": "可省略；加到50ml奶味更浓但失去清甜"},{"n": "红豆或芒果（装饰）","q": "50g","a": "可省略；加到100g甜度需减糖"}],"steps": ["牛奶倒入锅中加热到边缘刚冒小泡（约80℃），立刻离火，切勿煮沸，沸了不起奶皮。","把热牛奶沿碗边缓缓倒入浅口碗中，静置10分钟，表面会自然结出一层奶皮。","用小刀沿碗边划开奶皮，把碗底牛奶倒出到另一个碗中，奶皮留在原碗底。","倒出的牛奶加白糖40g拌匀至溶解，再加3个蛋清（只要蛋白）搅匀，用细筛过滤两遍去泡沫和蛋筋。","沿碗边缓缓把蛋奶液倒回原碗，奶皮会自动浮到表面形成第二层。","碗上盖保鲜膜或倒扣一个盘子防水蒸气，中火蒸12-15分钟至表面凝固、轻晃中心不颤。","取出晾凉后冷藏2小时口感最佳，食用时可加红豆或芒果。"],"key": "第一层奶皮靠牛奶加热后放凉自然结出，第二层靠蛋清液回倒让奶皮重新浮起；水蒸气滴进碗里会起蜂窝，所以要盖盖。","tip": "必须用全脂牛奶，脱脂奶结不出皮；判断火候看碗中央，凝固不颤即关火，蒸过头会有蜂窝孔和蛋味。"},"杨枝甘露": {"time": "45分钟","level": "简单","servings": "2人份","ing": [{"n": "芒果","q": "2个约500g","a": "减到1个份量少、果肉不足；加到3个则偏甜需减糖"},{"n": "西柚","q": "半个","a": "减到四分之一个酸味不足；加到1个则苦味太重"},{"n": "西米","q": "60g","a": "减到40g份量少；加到90g口感过密"},{"n": "淡奶","q": "100ml","a": "减到60ml椰香不足；加到150ml太腻"},{"n": "椰浆","q": "80ml","a": "减到40ml椰香弱；加到150ml盖住芒果香"},{"n": "白糖","q": "40g","a": "减到25g甜度不够；加到60g齁甜"},{"n": "淡奶油","q": "50ml","a": "可省略；加到100ml更像港式做法但更腻"},{"n": "吉利丁片","q": "5g（可选）","a": "可省略；加到10g口感偏硬Q"}],"steps": ["西米放入沸水煮12分钟至只剩小白点，关火焖10分钟至完全透明，捞出用冷水冲洗至不粘，沥干备用。","芒果去皮切丁，一半（约250g）打成芒果泥；留一半切1cm的小丁。","芒果泥加淡奶100ml、椰浆80ml、白糖40g用料理机或手动搅打至顺滑细腻。","若喜欢港式浓稠口感，可将淡奶油50ml与芒果酱一起打匀，冷藏1小时更入味。","西柚剥出果粒，逐粒撕去白膜（白膜会发苦），得到干净的红宝石色柚粒。","取碗放西米打底，舀入芒果酱，再撒芒果丁和西柚粒。","食用前拌匀，冷藏后风味最佳。"],"key": "西柚的白色内膜必须撕净，否则整碗发苦；西米煮到透明后必须过冷水洗，才会弹而不粘。","tip": "芒果要选熟透软身的，打出来的酱才香浓带黄；西柚买不到可用葡萄柚或西柚汁替代但会偏苦。"},"糯米鸡": {"time": "3小时","level": "中等","servings": "3人份","ing": [{"n": "糯米","q": "300g","a": "减到200g份量少；加到400g需延长蒸制15分钟"},{"n": "鸡腿肉","q": "250g","a": "减到150g糯米会偏硬无肉香；加到350g偏腻"},{"n": "干香菇","q": "6朵","a": "减到3朵香气不足；加到10朵菌味过重"},{"n": "广式腊肠","q": "2根","a": "减到1根腊味不足；加到3根偏咸需减盐"},{"n": "干贝或瑶柱","q": "15g","a": "减到8g鲜味弱；加到25g腥味重"},{"n": "红枣","q": "4颗","a": "减到2颗甜度不足；加到8颗过甜"},{"n": "板栗仁","q": "50g","a": "可省略；加到100g口感偏粉"},{"n": "姜丝","q": "10g","a": "减到5g去腥不足；加到20g姜味重"},{"n": "生抽与蚝油","q": "生抽25ml、蚝油15g","a": "生抽减到15ml偏淡；加到40ml过咸"},{"n": "干荷叶与棉线","q": "荷叶2张、棉线1团","a": "荷叶用1张包不住；用3张味道更浓但不易成形"}],"steps": ["糯米淘净后浸泡3小时至发胀，沥干；干香菇用温水泡发30分钟，挤干水分切丁；干贝泡软搓成丝。","鸡腿肉切1.5cm的丁，加生抽25ml、蚝油15g、姜丝、少许糖和油腌30分钟。","热锅冷油下鸡丁中火炒3分钟至变白，再下腊肠丁、香菇丁、干贝丝炒2分钟出香。","把炒好的料与沥干的糯米、红枣、板栗仁拌匀，尝味并补盐至淡咸合适（生抽蚝油已带咸味）。","荷叶用开水烫30秒至变软变绿，铺在碗底（荷叶背朝上更贴形）。","把糯米料装入荷叶中，压实、收拢成方包，用棉线十字捆紧。","蒸锅上汽后放入，大火蒸1.5小时至糯米完全熟透、荷叶香透米粒；关火焖5分钟再开盖，淋少许热油和生抽即可。"],"key": "荷叶必须用开水烫软再包，扎紧棉线才不会散开；糯米要压实，蒸出来才是紧实有嚼劲的糯米鸡而不是散饭。","tip": "正宗糯米鸡还会加咸蛋黄、虾米和瑶柱；蒸好趁热淋一勺热油和少许生抽，荷叶香会更明显。"},"干炒牛河": {"time": "25分钟","level": "中等","servings": "2人份","ing": [{"n": "河粉","q": "400g","a": "减到250g则一锅只够1人，河粉下锅后翻炒时间翻倍易碎断；加到600g需换宽口铁锅，否则一锅太满、锅铲压不下去就断条"},{"n": "雪花牛肉","q": "150g","a": "减到100g则肉味淡、镬气不足，只剩河粉味；加到250g需把腌肉时间延长到20分钟并分两次下锅，否则老"},{"n": "绿豆芽","q": "80g","a": "减到30g则少一分爽脆；加到150g会抢河粉主角地位，炒出来像杂菜面"},{"n": "韭黄","q": "50g","a": "减到20g则香气不足；加到100g会出水变湿，镬气全失，需最后半分钟才下"},{"n": "洋葱","q": "半个（约80g）","a": "减到0g则少了甜味垫底；加到1整个（约160g）会抢味且出汁多、炒出来发湿，应切丝控制在80g以内"},{"n": "老抽","q": "15ml（1勺）","a": "减到5ml则颜色发白不够亮；加到30ml会发黑发苦，只能沿锅边淋一圈"},{"n": "生抽","q": "15ml（1勺）","a": "减到5ml则不够咸需另补盐；加到30ml会过咸并让河粉出水变软"},{"n": "猪油","q": "30g","a": "减到10g则镬气不足、香味寡淡；加到60g则腻，河粉表面挂厚油不脆"},{"n": "盐与白胡椒粉","q": "盐2g+白胡椒粉1g","a": "盐加到5g会过咸盖掉豉油香，减到0g则全靠酱油、咸味不均匀；白胡椒粉加到3g会发苦带辛冲，减到0g少一层暖香回味"},{"n": "糖与淀粉（腌牛肉用）","q": "糖3g+淀粉5g","a": "减到0g则肉片下锅即散、缺少回甜；加到糖8g、淀粉12g则肉片发黏抱团，炒不出镬气"}],"steps": ["河粉从冰箱取出摊开回温至不结冰，用手指把粘连处轻轻抖散，绝不能泡水或冲洗，泡过水的河粉下锅必烂成糊。","牛肉逆纹切薄片，加10ml生抽、3g糖、5g淀粉抓匀腌15分钟，腌到肉片发黏、表面挂浆即可。","铁锅烧到冒青烟（滴水成珠），下20g猪油化开，转猛火下洋葱丝炒20秒至边缘透明微焦。","转大火下牛肉片快速滑炒40秒，七成熟即盛出，此时中心还带粉红色即可，久炒必老。","锅内补余下猪油烧至冒烟，河粉整份倒下去，沿锅边淋10ml老抽，用锅铲从锅底抄起抖散，让每根河粉均匀受热着色。","大火翻炒约90秒，看到河粉表面微微起“镬气”、边缘出现透明焦点时，沿锅边再补5ml老抽和余下生抽，快速翻匀。","下绿豆芽和韭黄段，大火翻炒30秒至断生，芽头仍脆、韭黄刚塌即把牛肉回锅。","撒盐和白胡椒粉，从锅边淋5ml生抽兜匀，颠勺两下立刻装盘，锅气散得越快越好。"],"key": "全程猛火、河粉下锅后必须在90秒内完成上色，断条的最主要原因不是火小，而是锅没烧够热、加油后又降温。","tip": "家里没有铁锅就用厚底铸铁锅或烧到冒烟的不粘锅；怕辣又想要镬气，可多放2g糖提鲜，不要靠多加油来解腻。"},"盐焗鸡": {"time": "90分钟（含腌制焗制）","level": "中等","servings": "3-4人份","ing": [{"n": "三黄鸡（或清远鸡）","q": "1只约1.2kg","a": "减到800g则不够3人吃，焗制时间也要缩到35分钟；加到1.5kg则要焗70分钟，否则鸡心未熟"},{"n": "盐焗鸡粉","q": "60g（3包）","a": "减到30g则香味只到表层，咬到鸡腿没味；加到100g会咸到无法入口，且盐分锁在皮上发苦"},{"n": "粗盐（海盐颗粒）","q": "1kg","a": "减到500g埋不没鸡身，焗热不足；加到1.5kg要多焗15分钟导热，避免外层过熟内层夹生"},{"n": "沙姜","q": "20g","a": "减到10g则辛香不足、只剩纯咸；加到40g会辛到刺鼻抢过鸡香"},{"n": "姜","q": "30g（4片）","a": "减到10g则去腥力弱；姜片可塞入鸡腹与姜蓉调酱两用，加到50g出锅只苦不香"},{"n": "葱","q": "2根","a": "减到1根香气不够；加到4根会出一股生葱味，减到0g则失去葱油回甜"},{"n": "花椒","q": "10g","a": "减到3g麻香不足；加到20g麻得盖住鸡肉甜味"},{"n": "料酒","q": "20ml","a": "减到10ml去腥不彻底；加到40ml会有酒味残留到成菜"},{"n": "芝麻油","q": "5ml","a": "减到2ml则成菜没灵魂；加到15ml则腻口，只在出锅前点几滴"},{"n": "粗盐（锅底铺盐用）","q": "另备1kg","a": "这是铺在砂锅底吸热传热的量，减到500g则锅底温度不足焗出的鸡皮发软；加到2kg要多焗15分钟，避免外层过熟内层夹生"}],"steps": ["鸡洗净后用厨房纸彻底擦干内外，水分不擦干会稀释腌料、盐也结块；有条件用吹风机冷风吹10分钟更好。","盐焗鸡粉加沙姜蓉、姜蓉、葱段、少许料酒调成糊，均匀抹遍鸡身内外并按摩3分钟，塞几片姜葱进鸡腹。","冷藏腌制至少30分钟（隔夜更入味），期间用保鲜膜封好；腌好后倒掉盘中血水，别重复使用腌料汁。","砂锅底铺1kg粗盐，中火干炒10分钟不停翻动到盐粒发烫、手伸近有热浪感，这一步决定焗出的鸡皮干爽还是湿烂。","腌好的鸡用厨房纸再吸干表面水珠，两层纱布或油纸包紧（先包纸再包纱布，防止盐粒直接黏在鸡皮上）。","把热砂锅移开，鸡放在砂锅中央剩余热盐上，用热盐覆盖鸡身四周压实，只露出鸡腿顶部一小截。","盖上锅盖置中火焗40分钟，全程不时转动砂锅让受热均匀；转小火续焗10分钟，关火不开盖焖30分钟更嫩。","出锅去掉纱布，锅内渗出的鸡汁留作蘸料；剪姜葱丝铺在鸡身上，淋5ml热芝麻油和1勺原汁即可斩件上桌。"],"key": "盐必须先干炒到发烫才能埋鸡，盐温不足是盐焗鸡皮软塌、不起“盐香”的头号原因；另外鸡身要干、湿鸡焗出来是水煮味。","tip": "没有砂锅可用铸铁锅或厚底不锈钢锅加一层热盐；嫌焗味太咸，腌料减到40g并在出锅后用温水快速抹一遍表面再斩件。"},"客家酿豆腐": {"time": "40分钟","level": "中等","servings": "3-4人份","ing": [{"n": "板豆腐（客家酿豆腐用老豆腐）","q": "400g（约1盒）","a": "减到250g则只够2人、每人只夹得2块；加到600g需延长煎制到每面4分钟，否则底易焦"},{"n": "猪肉末","q": "200g","a": "减到120g则馅心不成团、容易从洞里掉出来；加到300g则馅比豆腐重，煎时难翻面"},{"n": "咸鱼（腊鱼干）","q": "20g","a": "这是客家酿豆腐的咸香命根，减到0g就变成普通肉酿豆腐；加到40g会过咸需同步减盐"},{"n": "干香菇","q": "3朵（约8g）","a": "减到1朵香气淡；加到6朵会抢肉味，且馅心出水难上劲"},{"n": "马蹄（荸荠）","q": "60g","a": "减到20g则缺少脆粒口感；加到120g会挤掉肉汁变成纯脆"},{"n": "葱花","q": "20g","a": "减到5g则香气弱；加到50g则馅心发水，煎时易散"},{"n": "生抽","q": "15ml（1勺）","a": "减到8ml则馅心寡淡；加到25ml则馅心咸、豆腐反而没味"},{"n": "蚝油与老抽","q": "蚝油10ml+老抽5ml","a": "蚝油减到0g少一层鲜甜、加到20ml会发黏、勾芡后发亮过头；老抽减到0g颜色浅、加到10ml发黑发苦，只用于调色"},{"n": "高汤（或清水）","q": "150ml","a": "减到50ml则豆腐吸不进味；加到300ml则一盘全是汤"},{"n": "糖与淀粉","q": "糖5g+淀粉8g（3g腌馅、5g调芡）","a": "糖减到0g则馅心鲜味单薄、勾芡后寡淡；淀粉加到15g芡汁过稠挂不住豆腐，糖加到12g会发甜盖住咸鱼香"}],"steps": ["香菇提前用温水泡20分钟泡出香味，咸鱼剁成细蓉，马蹄拍碎切小粒，干香菇挤干水分后切碎，备用。","豆腐从盒中倒出沥水，切成约4cm见方的块（约12块），用小勺在每块中间挖一个小洞，挖出的豆腐碎直接拌进肉馅里不浪费。","肉馅加入咸鱼蓉、香菇碎、马蹄粒、葱花、一半生抽、5g糖、3g淀粉，顺一个方向搅打2分钟至上劲发黏。","将肉馅填满豆腐洞并稍稍堆高成小丘，用手指抹平表面封口，防止煎制时馅心从洞口挤出。","平底锅烧热下20ml油，中火将豆腐块馅面朝下入锅，煎3分钟到金黄结壳；小心翻面再煎2分钟，让四面都上色。","调汁：10ml生抽、10ml蚝油、5ml老抽、40ml高汤或清水倒入锅中小火烧2分钟，让豆腐吸味。","分三次淋入淀粉水，每次淋后晃锅让芡汁均匀挂在豆腐上，收到汤汁浓稠能挂勺即可，约2分钟。","起锅装盘，淋上锅底余汁，撒一把葱花，趁热吃；豆腐凉透口感会变硬。"],"key": "肉馅必须搅到上劲发黏才能填进洞里不散，咸鱼蓉是客家风味核心，不能用酱油代替。","tip": "没有马蹄可用荸荠或莲藕切碎替代；要更清淡可把咸鱼减到10g并加5g剁椒提味。"},"脆皮烧肉": {"time": "3小时（含风干）","level": "稍难","servings": "4-5人份","ing": [{"n": "带皮五花肉","q": "600g","a": "减到400g只够3人、每人一碗不到；加到900g需烤90分钟，否则肥肉未透"},{"n": "盐","q": "8g","a": "减到4g则肉馅部分不够咸；加到15g则腌后肉死咸且难出水"},{"n": "五香粉","q": "3g","a": "减到0g则只有盐味没有肉香；加到8g会盖住肉本身的甜味"},{"n": "南乳（腐乳）","q": "15g","a": "减到0g则少了酒香与发酵味，颜色也不够红；加到30g会过咸发苦"},{"n": "生抽","q": "20ml（1勺半）","a": "减到10ml则颜色偏淡；加到35ml会咸到无法蘸酱吃"},{"n": "蜂蜜或麦芽糖","q": "15ml","a": "减到0g皮烤不出脆壳；加到40ml会过甜，且焦化后发苦"},{"n": "蒜","q": "4瓣","a": "减到2瓣蒜香不足；加到8瓣会有生蒜味抢过肉香"},{"n": "米酒","q": "20ml","a": "减到10ml去腥不彻底；加到40ml会有明显酒味"},{"n": "姜片","q": "20g","a": "减到10g去腥力弱；加到40g只会出姜味不出香"},{"n": "高汤","q": "200ml","a": "减到100ml则焗后肉发干；加到400ml则肉松散不成形，切时易碎"}],"steps": ["五花肉整块切成长约8cm的条（不要切小块，小块皮受热面积不够，爆不出脆皮），皮面用刀尖均匀扎小孔。","盐、五香粉、南乳压碎、生抽、蒜末、米酒、姜末调成腌料，抹匀肉条并按摩3分钟，冷藏腌制30分钟以上。","肉皮表面抹匀蜂蜜或麦芽糖，用绳子把肉条吊起或架在网筛上，通风阴凉处风干一夜（最少4小时，急着吃可用烤箱60℃烘2小时）。","烤箱预热220℃，肉条皮朝上放烤盘，下面垫接油盘，中层烤40分钟，期间取出两次倒掉渗出的油脂。","取出肉条，用刀刃把烤盘里的凝固猪油刮干净（这一步是脆皮不软塌的关键），把肉翻面肉朝上。","将200ml高汤倒入烤盘铺底，把腌料剩下的酱汁刷在肉上，塞入剩余姜片，盖锡纸。","回炉180℃烤20分钟让肉吸足高汤至八成软，中途打开一次刷汁；取出揭掉锡纸，再刷一层麦芽糖水。","调到230℃高温再烤6-8分钟守在烤箱前看，表皮起泡、颜色深红带焦点、敲起来有脆响即为成功，趁热切块装盘。"],"key": "脆皮烧肉的脆来自“烤干猪油”，烤盘里的油必须两次刮净，再用高汤焖出肉味，最后高温逼干表面水分形成脆壳。","tip": "风干那步能省就省，但至少要有2小时；怕上火可缩短焗制到15分钟并多烤一次逼油。"},"罗卜焖牛腩": {"time": "100分钟","level": "中等","servings": "4人份","ing": [{"n": "牛腩","q": "600g","a": "减到400g则每人只有约100g牛腩，显得小气；加到900g要炖90分钟，萝卜须后放否则烂成泥"},{"n": "白萝卜","q": "500g（约1根）","a": "减到300g则只见腩不见萝卜；加到800g需延长焖煮10分钟，且汤汁会变清稀"},{"n": "柱候酱","q": "30g（2勺）","a": "这是粤式焖牛腩的灵魂，减到10g会变成清汤牛肉；加到50g会咸且带发酵酸味冲过牛腩"},{"n": "南乳","q": "15g（1小块）","a": "减到0g少一分酒香回甜；加到30g会发咸发苦"},{"n": "料酒","q": "20ml","a": "减到10ml则焯水时酒香不够；加到40ml会残留酒味"},{"n": "姜与蒜","q": "姜30g（4片）+蒜4瓣","a": "姜减到10g去腥力弱、加到60g只苦不香；蒜减到2瓣爆香不足、加到8瓣蒜味盖过柱候酱"},{"n": "蒜","q": "4瓣","a": "减到2瓣香气减半；加到8瓣蒜味盖过柱候"},{"n": "八角与陈皮","q": "八角1颗+陈皮3g","a": "减掉八角少一层甘香；八角加到3颗、陈皮加到10g都会发苦出药味"},{"n": "葱花","q": "10g","a": "减到0g少一层清香；加到30g会抢掉柱候酱的味道，装盘撒一把即可"},{"n": "高汤","q": "800ml","a": "减到400ml则没焖透的汤汁；加到1200ml需大火收汁时间延长8分钟，否则太稀"}],"steps": ["牛腩切3cm见方块，冷水下锅加姜片和料酒，中火焯8分钟，撇净浮沫后捞出用温水冲洗干净，焯水后的血水不洗会导致汤发浑。","锅烧热不放油，下牛腩块中火干煸6分钟，煸到表面微焦发紧、边缘出油，这一步让牛腩久炖不散且汤更浓。","起锅倒掉多余的油，爆香姜片蒜瓣，下柱候酱和压碎的南乳，小火炒1分钟至酱料起泡出红油、香气冲鼻。","倒入高汤烧开，加八角、陈皮和剩余料酒，加盖转小火炖60分钟，筷子能插入牛腩但有阻力即到位。","白萝卜去皮切滚刀块，放入锅中继续小火焖25分钟，焖到萝卜边缘透明、中心略软但仍有形，不能炖到完全透明化开。","开盖转大火收汁8-10分钟，不停晃锅防止粘底，收到汤汁浓稠、勺背挂汁成薄膜即可。","尝味调整：偏淡补一小勺柱候酱再收一下，偏咸加50ml热水稀释后重新收汁。","连汁盛入深盘，撒葱花或垫焯过水的青菜叶同煲上桌，配白饭吃汁最下饭。"],"key": "牛腩干煸、萝卜后放、收汁不加盖，三步决定这道菜是“浓香挂汁”还是“清汤寡肉”。","tip": "想更香浓可把高汤换成1罐炖好的牛骨汤；不吃辣完全不用加辣椒，粤式做法本就不放辣。"},"沙姜猪手": {"time": "3小时","level": "稍难","servings": "4人份","ing": [{"n": "猪手","q": "2只约800g","a": "减到1只则4人分吃太少，每人一只猪蹄盖饭才够；加到3只需延长煮制到80分钟，否则中间没熟透"},{"n": "沙姜","q": "30g","a": "这是菜名里的主角，减到10g只剩普通卤猪手味；加到60g会辛辣刺鼻、盖掉猪手胶质香"},{"n": "蒜","q": "1整头（约40g）","a": "减到半头蒜香淡；加到2头会出蒜臭，卤汁发苦"},{"n": "姜","q": "30g","a": "减到10g去腥不够；加到60g姜味发冲"},{"n": "料酒","q": "30ml","a": "减到15ml腥味去不掉；加到60ml酒味久久不散"},{"n": "生抽与老抽","q": "生抽30ml+老抽10ml","a": "生抽减到15ml则卤汁颜色浅、咸度不足、加到50ml过咸发苦；老抽减到0g不上色、加到20ml发黑发苦"},{"n": "米醋","q": "15ml","a": "减到0g则少了爽口的酸意；加到30ml会酸得抢味，醋要在关火前放"},{"n": "冰糖","q": "10g","a": "减到0g卤汁发苦不圆润；加到25g会甜腻粘喉"},{"n": "八角","q": "2颗","a": "减到1颗香气减弱；加到4颗有药味"},{"n": "熟白芝麻","q": "10g","a": "减到0g少一点香；加到30g会抢掉沙姜的香气"}],"steps": ["猪手剁成大块，冷水下锅加姜片和一半料酒，中火煮10分钟焯出血沫，捞出用温水把表面浮沫冲洗干净。","沙姜去皮切片，用石臼或刀背拍打成蓉（一定要捣烂，颗粒状的沙姜出香慢），蒜一半拍蓉一半切末备用。","锅中加水2000ml，放姜片、蒜蓉、沙姜蓉、八角、生抽、老抽、冰糖和剩余料酒，大火烧开煮3分钟出味。","放入焯好的猪手，重新煮沸后转小火加盖煮50分钟，筷子能轻松插入蹄筋即火候到位，不要煮到肉烂散开。","关火不揭盖，让猪手在卤汤中泡30分钟入味，此时皮肉吸足卤味而不会发柴。","捞出猪手立刻投入一盆加冰块（或冰水）的盆中浸10分钟，冰镇让猪皮收缩变爽脆弹牙，这一步是“爽脆”二字的来源。","斩件装盘，淋上煮好的卤汁和蒜末，撒熟芝麻、淋几滴米醋拌匀上桌，冷食最佳。"],"key": "沙姜必须捣烂才出香；煮好过冰水是爽脆弹牙的关键，直接捞出上桌口感会发黏发软。","tip": "怕沙姜辛辣可减到15g并多放葱段同煮；不吃冷盘可把斩件回锅加卤汁炒热，牺牲脆度换取热食口感。"},"干蒸烧卖": {"time": "50分钟","level": "稍难","servings": "3-4人份（12个）","ing": [{"n": "猪前腿肉","q": "300g","a": "减到200g则馅心紧实但量少，只够8个；加到400g需多蒸3分钟，12个以上要分两笼蒸"},{"n": "虾仁","q": "150g","a": "减到80g则少了那口弹牙的整虾；加到250g则虾味盖过猪肉，失去烧卖本味"},{"n": "肥膘（猪板油）","q": "50g","a": "减到0g则馅心发柴不爆汁；加到100g会腻，肥膘粒不能剁成泥"},{"n": "马蹄或冬笋","q": "60g","a": "减到20g则缺脆感；加到100g会挤走肉汁、咬起来太水"},{"n": "姜","q": "10g","a": "减到0g有腥味；加到25g姜味抢过虾香"},{"n": "生抽","q": "15ml（1勺）","a": "减到8ml则馅心不够咸鲜；加到25ml则馅心过咸，出汁变多"},{"n": "盐","q": "4g","a": "减到0g则只有酱油味、味道单薄；加到8g会咸到发苦"},{"n": "糖","q": "4g","a": "减到0g则鲜味单薄；加到10g会甜腻盖住肉味"},{"n": "淀粉","q": "15g","a": "减到5g馅心不上劲、蒸后散开；加到30g则口感发糊发黏"},{"n": "咸蛋黄","q": "1个","a": "这是顶上那朵黄的来源，减到0g失去标志；整颗放会太咸，切两半放"}],"steps": ["肥膘切成小丁（不要剁成泥，留颗粒才有爆汁口感），虾仁去壳去虾线切大丁，马蹄拍碎切碎粒。","猪前腿肉手工切成粗粒，不要用绞肉机打成肉泥——粗粒肉馅才有烧卖那种“有咬劲”的颗粒感。","肉粒加盐、糖、生抽、姜蓉、淀粉搅打2分钟至上劲发黏，再拌入虾丁、肥膘丁、马蹄粒轻轻拌匀。","把肉馅装入锡纸小杯，压实后堆出中间高、四周低的小丘状，堆得太平蒸后塌下去不成形。","每个烧卖顶面轻按半个咸蛋黄（那朵黄），用手指轻轻压实，蒸后蛋黄微微起沙出油。","蒸锅上汽后放入烧卖，大火蒸8分钟，关火再焖1分钟，起盖时不马上开盖防止水汽滴落皮面。","取出小心脱去锡纸，摆在蒸笼或盘中，趁着热吃，配一壶普洱或菊花茶解腻。"],"key": "肉馅必须手切成粗粒并搅打上劲，这是烧卖区别于肉丸的关键；顶上的咸蛋黄要在蒸前按上，蒸后才放会化开流走。","tip": "蒸制时间按个头调整，12个小杯大火8分钟刚好；一次做多可生坯冷冻，蒸时不用解冻直接上汽蒸即可。"},"及第粥": {"time": "60分钟","level": "中等","servings": "2-3人份","ing": [{"n": "大米","q": "150g","a": "减到100g则粥太稠无法当汤喝；加到250g则底粥过厚，料被埋住看不见"},{"n": "猪瘦肉","q": "120g","a": "减到60g则缺了粥中最主要的肉香；加到200g需多汆一次水，否则血腥味明显"},{"n": "猪肝","q": "80g","a": "减到0g则少了及第粥那口滑嫩；加到150g会发苦发柴，必须切得极薄"},{"n": "粉肠","q": "60g","a": "减到0g则没那股弹韧；加到120g需焯洗更久，否则有骚味"},{"n": "虾","q": "80g","a": "减到0g则少一味鲜甜；加到150g会让粥变腥，须最后放"},{"n": "姜","q": "15g（切丝）","a": "减到5g去腥不足且少了姜香；加到40g会辣口抢味"},{"n": "葱花","q": "10g","a": "减到0g少一层香；加到40g会发蔫不脆"},{"n": "盐与白胡椒粉","q": "盐5g+白胡椒粉1g","a": "盐加到10g会过咸且掩盖猪肝清甜，减到2g不够味；白胡椒粉加到3g发苦带辛冲，减到0g少一层暖香回味"},{"n": "香油（或花生油）","q": "5ml","a": "减到0g粥面不泛亮光；加到15ml则整碗油汪汪发腻"},{"n": "生抽","q": "15ml（1勺）","a": "减到5ml则汆料不入味；加到30ml则粥底发咸发黑"}],"steps": ["大米淘洗干净，用清水浸泡20分钟至米粒发白起泡，沥干后下锅，这样熬出来的米粒更容易开花起胶。","猪瘦肉切薄片，用少许生抽抓匀；猪肝切极薄片，再用清水泡10分钟去血水，泡到水清即可；粉肠洗净切小段焯水2分钟去腥。","锅中加1500ml水烧开下米，大火煮沸后转最小火，盖盖留一条缝慢熬，中间搅动2-3次防止粘底。","熬40分钟至米粒完全开花、汤汁浓稠如米浆，用勺子舀起能拉出丝即是好粥底，尝一口应绵密顺滑无颗粒感。","另起一锅水烧开，下猪肉片汆30秒至变色捞出，再下猪肝汆20秒、粉肠焯30秒、虾汆20秒，全部捞出备用，绝不能一股脑倒进粥里。","把汆好的料依次放入滚粥中，用勺子背轻轻推散，立刻搅动10秒让粥重新滚开。","加盐、生抽调味，撒姜丝和葱花，最后滴几滴香油或花生油在表面，粥面立刻泛起亮光。","趁热连锅端上桌，从边缘喝起，咸鲜味在热粥里会更明显。"],"key": "好粥底靠的是米粒熬到完全开花的胶质，不是靠淀粉水作弊；所有猪杂必须先用滚水汆熟再入粥，血水进粥就毁一锅。","tip": "赶时间可用高压锅20分钟出粥底；不吃内脏可把猪肝换成更多瘦肉和虾，加料不变。"},"马拉糕": {"time": "50分钟（含静置发酵）","level": "中等","servings": "4人份","ing": [{"n": "低筋面粉","q": "200g","a": "减到150g则糕体偏黏不易发；加到280g则口感变扎实但蜂窝孔变少，需延长发酵"},{"n": "鸡蛋","q": "3个（约150g）","a": "减到2个则蛋香不足、气孔松散；加到4个则糕体更轻盈但需要多蒸3分钟"},{"n": "黄糖","q": "120g","a": "减到60g甜度不够、蛋腥味显；加到180g会过甜盖住蛋香，用红糖则色泽更深带焦香"},{"n": "淡奶","q": "120ml","a": "减到60ml则糕体偏干；加到200ml则更像蒸蛋糕、失去马拉糕的清甜"},{"n": "玉米油","q": "60ml","a": "减到20ml则蛋糕发干；加到100ml口感偏腻"},{"n": "泡打粉","q": "6g","a": "减到2g发不起来，实心没蜂窝；加到12g会有碱味并导致发色偏黄"},{"n": "泡打水（糖水）","q": "20ml","a": "减到0g泡打粉活性发挥不全；加到40ml则糕体偏稀易塌"},{"n": "温水","q": "60ml（化糖用）","a": "减到30ml糖化不开有颗粒；加到90ml会稀释面糊、蜂窝变少"},{"n": "盐","q": "2g","a": "减到0g甜味发腻；加到5g会咸"},{"n": "熟白芝麻","q": "10g","a": "减到0g少一点香；加到30g表面会掉渣"}],"steps": ["黄糖加60ml温水搅拌隔水加热至完全融化成糖浆，放凉到不烫手备用，糖浆必须凉透再用，热的会把蛋冲成蛋花。","鸡蛋打散，倒入糖浆搅匀，再加入泡打粉和20ml泡打水（泡打粉先用这20ml水调开）搅匀。","低筋面粉加盐过筛两次，倒入蛋液中，用刮刀翻拌到无干粉即停手，不要画圈搅拌起筋，否则出蒸硬疙瘩。","分次倒入淡奶和玉米油，翻拌均匀成细腻无颗粒的奶黄色面糊，提起刮刀面糊呈缎带状缓慢流下。","面糊倒入垫了油纸的蒸笼或模具，抹平表面，静置发酵30分钟，看到面糊明显变蓬松、边缘冒小泡即可。","蒸锅上汽后放入，大火蒸22分钟（牙签插入中心不带湿面糊即熟），关火不开盖焖5分钟再揭盖，防止回缩塌腰。","出锅稍凉至不烫手，用锋利刀切成长方块，表面可刷一层蜂蜜水，撒熟白芝麻。"],"key": "糖必须先用温水化开并放凉再入蛋液，这是避免糖不溶和蛋液过热的两个关键；面糊静置发酵这30分钟不能省，否则蒸出来是死实的馒头味。","tip": "想更松软可把静置时间延长到45分钟或发酵到1.5倍大；蒸好后趁热装盒盖上，凉了再盖会回潮发黏。"},"剁椒鱼头": {"time": "35分钟","level": "中等","servings": "3-4人份","ing": [{"n": "雄鱼头（胖头鱼/鲢鱼头）","q": "1个约750g","a": "减到500g则每人分不到几口；加到1.2kg要延长蒸制到12分钟，否则鱼肉不熟"},{"n": "剁椒","q": "120g","a": "自制的剁椒带发酵酸香，减到60g则辣味够但香不足；加到200g会咸到吃不出鱼肉本身的甜"},{"n": "姜","q": "20g（切末+姜片）","a": "减到8g则去腥不足、辛香弱；加到40g姜末盖过鱼味"},{"n": "蒜","q": "15g（切末）","a": "减到0g则少一层蒜香；加到30g会有生蒜辣冲味"},{"n": "葱（葱段+葱花）","q": "30g（葱段垫底+葱花）","a": "减到10g则垫不出底香；加到60g则葱味发生、抢掉剁椒香"},{"n": "蒸鱼豉油","q": "30ml","a": "减到10ml则味道单薄；加到50ml会过咸盖住剁椒的发酵香"},{"n": "料酒","q": "20ml","a": "减到10ml去腥不彻底；加到40ml会有酒味"},{"n": "白胡椒粉","q": "2g","a": "加到5g会发苦；减到0g少一层辛香"},{"n": "猪油（或食用油）","q": "30g","a": "减到10ml则激不出葱香、油亮感弱；加到60g则盘底积油过腻"},{"n": "盐","q": "3g","a": "减到0g则靠剁椒和豉油咸度；加到6g会过咸"}],"steps": ["鱼头从下颌正中劈开摊成两大片，扣在盘中，去掉鳃和黑膜，用清水反复冲洗直到盆中水清，务必把血水洗干净，否则有腥味。","鱼头用盐和料酒里外抹匀，腌15分钟，倒掉渗出的血水，擦干鱼身表面水分。","盘底铺厚厚一层姜片和葱段，把鱼头摊开摆正，鱼皮朝上，肉面朝上，鱼眼露出盘面。","剁椒均匀铺满鱼头肉面，铺的厚度要一致，中间可略厚，蒸后辣椒受热会收缩出汁。","蒸锅水开后放入，大火蒸8分钟（750g鱼头标准），关火焖2分钟再揭盖，蒸久了鱼肉发柴变散。","取出鱼头，倒掉盘中腥水（这一步绝不能省，否则冲淡剁椒味），重新铺上姜末、蒜末和葱花。","淋上蒸鱼豉油，再把猪油烧到冒烟后直接浇在葱姜蒜上，激出香味，油温不够会发闷。","热腾腾端上桌，剁椒的汁水留着拌面条是隐藏的第二道菜。"],"key": "剁椒要自己用剁椒坛子发酵才够酸香，超市成品偏咸偏咸鲜；另外蒸好后盘底那层腥水必须倒掉再淋豉油。","tip": "鱼头买回来先放清水里泡15分钟去血水效果更好；不喜剁椒的酸可将剁椒减到60g，另加10g蒜末提香。"},"辣椒炒肉": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "螺丝椒（带皮）","q": "300g（约4根）","a": "减到150g则辣椒味不足；加到450g需延长炒制到3分钟，否则水分太多变软塌"},{"n": "猪前腿肉","q": "200g","a": "减到120g则每人只夹到几片；加到350g要分两锅炒，否则一次下太多出水成煮肉"},{"n": "豆豉","q": "10g（剁碎）","a": "这是湖南味的关键，减到0g则少了发酵的咸香；加到20g会发苦"},{"n": "蒜","q": "4瓣","a": "减到2瓣蒜香不足；加到8瓣生蒜味冲"},{"n": "干辣椒","q": "5个（剪段）","a": "减到2个则没有干香；加到10个会苦"},{"n": "生抽","q": "15ml（1勺）","a": "减到5ml肉片不入味；加到30ml则咸且出水"},{"n": "老抽","q": "5ml","a": "减到0g则颜色浅；加到10ml发黑发苦"},{"n": "淀粉","q": "8g","a": "减到0g则肉片下锅即散；加到20g肉会发黏成坨"},{"n": "猪油","q": "25g","a": "减到10g则少一分镬气；加到50g则腻"},{"n": "盐","q": "2g","a": "加到5g会过咸；减到0g则咸味全靠酱油"}],"steps": ["猪前腿肉逆纹切薄片，加生抽、老抽、5g淀粉抓匀腌15分钟，抓到肉片表面挂浆、颜色发亮即可。","螺丝椒洗净后斜切成段，带皮不去，辣椒皮的虎皮是这道菜的灵魂，蒂部切掉即可。","锅烧到冒青烟，下猪油化开转中火，肉片平铺下锅，先不翻动煎30秒让底部定型上色，然后大火快炒40秒至变色即盛出，全程不超过1分钟。","锅内留底油，下豆豉碎、干辣椒段和蒜片，小火炒40秒到豆豉出香、蒜片微黄。","转大火下螺丝椒，不加水干炒2分钟，炒到辣椒表皮起虎皮斑、边缘微微塌软但仍带脆感。","转大火继续干炒30秒让辣椒吸味，此时会腾起镬气的白烟，全程不加水才是干炒。","肉片回锅，撒入盐，大火翻炒20秒至肉片全部裹上辣椒即可立即装盘，多炒10秒肉就老了。"],"key": "肉要分两锅炒：一锅炒肉盛出，一锅干炒带皮辣椒出虎皮，最后合炒。混在一起炒辣椒会出水、肉会变灰失去镬气。","tip": "选辣椒时挑细长的螺丝椒，糊辣子炒不出香；怕辣可把一半辣椒去籽，辣度减一半但香味不变。"},"小炒黄牛肉": {"time": "25分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "黄牛里脊（嫩牛肉）","q": "300g","a": "减到200g则每人一小碟不过瘾；加到450g需分两锅爆炒并延长腌制约20分钟"},{"n": "螺丝椒","q": "150g","a": "减到80g辣度不足；加到250g则牛肉被辣椒盖住、抢了主角"},{"n": "紫苏","q": "10g","a": "这是湖南小炒的灵魂，减到0g就只是辣椒炒牛肉；加到30g会有草腥气"},{"n": "蒜","q": "4瓣（切片）","a": "减到2瓣蒜香弱；加到8瓣生蒜味重"},{"n": "干辣椒","q": "8个（剪段）","a": "减到3个缺干香；加到15个发苦"},{"n": "郫县豆瓣酱","q": "1勺（15g）","a": "减到0g则少了红油和发酵咸鲜；加到30g会咸发苦"},{"n": "生抽（腌肉与调味）","q": "20ml+5ml","a": "减到10ml则牛肉腌得不够味；加到30ml肉色过深发咸"},{"n": "蛋清","q": "1个（约30ml）","a": "这是嫩滑的关键，减到0g牛肉会老；加到2个会黏手不好抓"},{"n": "淀粉","q": "10g","a": "减到3g锁不住肉汁；加到25g肉会发糊、失去爽脆"},{"n": "食用油","q": "40ml","a": "减到20ml则镬气不足；加到80ml则成炒油泡肉"}],"steps": ["黄牛里脊逆着纹理切薄片，逆纹切断纤维是嫩的第一道保险；切好用清水冲10分钟洗去血水，沥干后吸水纸压干。","牛肉加20ml生抽、10g淀粉抓到发黏，再加蛋清抓匀封住，静置腌20分钟，冷藏腌更嫩。","螺丝椒斜切段，蒜切片、紫苏切碎备用。","锅烧至冒青烟，下30ml油烧热，转猛火下干辣椒和蒜片爆香20秒，随即下豆瓣酱炒出红油。","转大火下牛肉片，用锅铲快速滑散，成大块散开状后立刻翻炒40秒，牛肉七成熟（中心还带粉红）马上盛出，多炒10秒就老。","锅内补油，转中大火下螺丝椒炒2分钟至起虎皮表皮微软但仍有嚼劲，倒出辣椒。","重新开大火，牛肉回锅与辣椒一同快速翻炒20秒，沿锅边再淋5ml生抽翻匀，咸度全靠生抽控制。","关火倒入紫苏碎，用余温拌匀立刻装盘，紫苏遇久煮会发黑变苦，必须最后放。"],"key": "嫩滑靠三件事：逆纹切、蛋清淀粉封浆、大火七成熟离锅回锅一次就够。任何一步拖到全熟，牛肉立刻变柴。","tip": "没有黄牛肉可用牛里脊或牛外脊替代；不喜辣可减小米辣为0并把螺丝椒换成青椒，只用干辣椒提香。"},"口味虾": {"time": "45分钟","level": "稍难","servings": "3人份","ing": [{"n": "小龙虾","q": "1000g（约15只）","a": "减到600g不够3人过瘾；加到1500g要分两锅炸，否则下锅后挤成一团炸不透"},{"n": "干辣椒","q": "20g","a": "减到10g则辣味不猛、香料不足；加到40g会苦且盖住虾的鲜"},{"n": "花椒","q": "10g","a": "这是麻味来源，减到3g只有辣没有麻；加到25g麻到舌头发木"},{"n": "蒜","q": "1整头（约50g，切末）","a": "减到半头蒜香不足；加到2头蒜味生辣、油发苦"},{"n": "啤酒","q": "330ml（1罐）","a": "这是去腥提鲜的关键，减到0g用清水会发腥；加到2罐则口味变淡且收汁时间翻倍"},{"n": "郫县豆瓣酱","q": "2勺（30g）","a": "减到1勺则红油不足；加到4勺会咸得吃不出虾味"},{"n": "辣椒酱（自制或市售）","q": "1勺（20g）","a": "减到0g则少一层发酵辣；加到40g会辣到麻木"},{"n": "紫苏","q": "10g","a": "减到0g少一味清凉草香；加到30g发苦"},{"n": "生抽","q": "20ml","a": "减到10ml则不够咸鲜；加到35ml过咸"},{"n": "食用油","q": "500ml（炸虾用）","a": "半锅即可，够淹没虾身；减到200ml会粘锅"}],"steps": ["小龙虾用清水冲洗干净，剪去虾头前端约1cm的尖刺，虾头背部开一刀挑出虾线，逐只冲净，虾线不去会发苦发腥。","锅烧热倒500ml油，油温到六成热（筷子插入周围起小泡），下小龙虾炸90秒至外壳红亮定形，捞出沥油。虾不用炸透，焖的时候还会熟。","倒出多余油留底油30ml，转小火下蒜末、干辣椒、花椒炒香1分钟，蒜末炒到微黄即可，发黑就苦了。","下豆瓣酱和辣椒酱，小火炒30秒炒出红油，锅底油色变成深红。","倒入啤酒烧开，加生抽搅匀，把炸好的小龙虾回锅，加盖中火焖5分钟。","开盖转大火收汁3分钟，不断翻动让每只虾均匀裹上汤汁，收到汤汁浓稠发亮、虾身油光发红。","下紫苏，翻炒20秒立刻出锅装盘，汤汁一起上桌，用手指捏开虾壳蘸汤吃。"],"key": "虾必须先过油炸定壳再回锅焖，这样壳红亮不烂、锁住虾肉汁；蒜末只炒到微黄就够，炒黑整锅发苦。","tip": "怕辣可把干辣椒减到10g、豆瓣酱减到1勺，用啤酒多焖2分钟出腥；配一份手工面拌汤汁是长沙标准吃法。"},"常德牛肉粉": {"time": "2小时（含熬汤）","level": "稍难","servings": "3人份","ing": [{"n": "牛腩","q": "500g","a": "减到300g则码子太少、每人只几片；加到800g需炖到100分钟否则咬不动"},{"n": "干米粉（常德米粉）","q": "250g","a": "减到150g则一人只一小碗；加到400g需分碗烫煮，一次煮太多会糊成坨"},{"n": "牛骨","q": "1000g","a": "这是汤底浓白的来源，减到500g则汤清味淡；加到2000g需熬5小时且占满灶头"},{"n": "干辣椒与黄辣椒面","q": "干辣椒20g+黄辣椒面30g","a": "干辣椒减到8g辣味不足、加到40g发苦；黄辣椒面减到10g则辣香不正宗、加到60g辣得盖住牛肉和汤味"},{"n": "姜与蒜","q": "姜30g+蒜20g","a": "姜减到10g去腥弱、加到60g姜味过冲；蒜减到8g蒜香不足、加到40g生蒜味重"},{"n": "香料（八角+桂皮）","q": "八角1颗+桂皮1小段","a": "减掉八角少一层甘香；八角加到3颗、桂皮加到3段会发苦出药味"},{"n": "生抽与盐","q": "生抽15ml+盐10g","a": "生抽减到8ml码子不入味、加到30ml过咸；盐减到5g汤味偏淡、加到20g咸到喝不下汤"},{"n": "豆豉","q": "10g（剁碎）","a": "这是码子的咸鲜底味，减到0g少一味发酵香；加到20g发苦"},{"n": "葱花","q": "15g","a": "减到5g香气不够；加到40g会发蔫不脆"},{"n": "食用油","q": "40ml","a": "减到20ml爆香时容易糊锅；加到100ml则汤面浮油太厚、辣椒面发腻"}],"steps": ["牛骨斩块焯水3分钟去血沫，冲洗干净；牛腩切3cm方块，也焯水后沥干。","大锅下油爆香姜片、蒜瓣和香料（八角、桂皮），下干辣椒节小火炒1分钟炒出红油。","倒入牛骨翻匀，加1500ml水大火烧开，转最小火熬60分钟至汤色泛白，这层白是牛骨骨髓熬出来的。","加入牛腩块和豆豉，转小火再炖50分钟至牛腩软烂能用筷子戳透，中途汤少了要补热水不能补冷水。","牛腩捞出切薄片码在碗底，原汤过滤掉渣滓备用。","干米粉用温水泡20分钟至软身不断；另起一锅宽水烧开，把米粉放漏勺在开水里烫40秒至刚熟，捞出装碗。","碗底放黄辣椒面、豆豉、生抽、葱花，把滚烫的牛骨汤直接冲入碗中，辣椒面被烫出香而不苦。","铺上牛肉片，想吃更讲究可加煎蛋、豆腐泡、牛肉码子另配，最后撒葱花、淋一勺热油。"],"key": "汤要浓白必须用牛骨长时间小火吊，汤只到“香”不到“浓”就失了常德牛肉粉的魂；冲汤的水温必须滚沸才能烫香辣椒面。","tip": "赶时间可用高压锅40分钟出浓汤；不食牛骨可用牛尾或浓骨汤替代，自己熬的最对味。"},"长沙臭豆腐": {"time": "25分钟","level": "中等","servings": "2人份","ing": [{"n": "黑色臭豆腐（发酵豆腐）","q": "400g（约8块）","a": "减到200g则每人一两块；加到600g需分两锅煎，否则吸油过多变软"},{"n": "蒜末","q": "30g","a": "这是长沙臭豆腐的命根，减到10g则少了蒜香；加到60g会生辣冲鼻"},{"n": "剁椒（或辣椒酱）","q": "20g","a": "减到0g少了辣味；加到40g会咸且抢掉豆腐的发酵香"},{"n": "豆豉","q": "10g（剁碎）","a": "减到0g少一味发酵咸香；加到20g发苦"},{"n": "葱花","q": "15g","a": "减到0g香气少一层；加到40g会发蔫"},{"n": "紫苏","q": "5g","a": "减到0g少一味草香；加到15g会发苦"},{"n": "生抽","q": "15ml（1勺）","a": "减到8ml汁不够味；加到25ml过咸"},{"n": "陈醋与糖","q": "陈醋10ml+糖5g","a": "陈醋减到0g少一点开胃的酸、加到25ml酸得倒牙；糖减到0g咸中无回甜、加到12g发甜"},{"n": "高汤或清水","q": "80ml","a": "减到20ml则浇汁太干挂不住；加到200ml会冲淡蒜香变成水"},{"n": "食用油","q": "30ml","a": "减到10ml会粘锅且煎不出金黄边；加到60ml则油腻"}],"steps": ["臭豆腐从坛子里取出，用清水快速冲洗一遍沥干，千万别泡久，泡久了发酵香气会流失、豆腐会散。","平底锅烧热，下油中火放入臭豆腐，煎3分钟到一面金黄结壳，翻面再煎2分钟，两面都煎到微焦发硬。","用厨房剪把每块臭豆腐表面划成三四小块，稍微剪深一点，让浇汁能渗进去，但不要剪散。","另起小碗调浇汁：蒜末、豆豉碎、剁椒、生抽、陈醋、高汤搅匀，静置5分钟让蒜味与豆豉味融合。","把调好的汁直接浇在热臭豆腐上，汁遇到热豆腐会滋滋作响、香气立刻冲出来。","撒紫苏碎和葱花，再淋一小勺烧到冒烟的热油激香，趁热吃，凉了就少了那股冲劲。"],"key": "豆腐要煎到两面结壳微焦才香，且必须趁热浇汁、撒葱花；凉吃发软、汁也挂不上。","tip": "怕蒜味冲可把蒜末减到15g并加5g剁椒补味；正宗黑豆腐买不到可用发酵豆腐或臭豆腐乳自制替代。"},"糖油粑粑": {"time": "40分钟","level": "中等","servings": "2人份（约14个）","ing": [{"n": "糯米粉","q": "250g","a": "减到150g则只能做8个；加到350g需延长和面时间，粉多易开裂"},{"n": "温水","q": "190ml（分次加）","a": "减到150ml则面团硬、压不扁；加到220ml会太软下锅即散，必须一点点加"},{"n": "红糖","q": "150g","a": "减到80g糖浆味淡、挂汁薄；加到220g会甜到发腻"},{"n": "白砂糖","q": "40g","a": "减到0g只有红糖的焦苦缺清甜；加到80g会盖掉红糖香"},{"n": "麦芽糖或蜂蜜","q": "20g","a": "减到0g糖浆挂不住粑粑；加到50g甜度过高"},{"n": "清水（熬糖浆用）","q": "80ml","a": "减到40ml糖浆过稠易糊锅；加到150ml则糖稀挂不牢"},{"n": "食用油（炸用）","q": "500ml","a": "减到200ml会粘锅；加到800ml没坏处只是更费油，能没过粑粑即可"},{"n": "熟白芝麻","q": "10g","a": "减到0g少一点香；加到25g表面掉渣"},{"n": "熟黄豆粉","q": "15g（装盘撒）","a": "减到0g少传统口感；加到40g会抢味"}],"steps": ["糯米粉分三次倒入190ml温水，边倒边用筷子搅成絮状再下手揉，揉成不粘手、能按扁不回弹的软面团。","面团盖湿布醒20分钟，醒过的粉团更细腻不裂，做出的粑粑表面光滑。","取小块面团搓圆压扁，用手指在中间轻轻压一个凹，成小碗状，这样炸后中间鼓、外缘薄脆。","油锅烧到五成热（150℃左右，丢一小粒面进去能缓慢浮起），改用小火。","生坯逐个放入锅中，用漏勺轻推不要压，等粑粑自己浮起并鼓成气球状，全程3-4分钟，粑粑浮起且颜色金黄即熟，捞出沥油。","另起锅放红糖、白糖、麦芽糖和80ml清水，小火不停搅拌熬2分钟至糖浆浓稠、能挂勺拉丝。","把炸好的粑粑倒入糖浆中翻匀，小火再煮2分钟让每个粑粑吸满糖浆，糖浆起大泡、粑粑表面挂出亮釉即可。","装盘趁热撒熟黄豆粉和白芝麻，糖油粑粑要热吃才软糯，冷了会硬成一坨。"],"key": "炸的时候必须小火慢炸并用漏勺轻推，粑粑会自己膨起来；火大会炸爆、外面焦里面还没熟透。","tip": "一次可多炸些生坯生坯冷冻，随吃随炸；糖浆熬好后可以留一小份，冷藏3天内回锅化开还能用。"},"毛氏红烧肉": {"time": "90分钟","level": "中等","servings": "4人份","ing": [{"n": "带皮五花肉","q": "600g","a": "减到400g只够3人；加到900g需炖到100分钟，否则瘦肉部分不够酥"},{"n": "冰糖（或白砂糖）","q": "40g","a": "这是不用酱油上色的关键，减到20g颜色淡；加到70g会过甜发苦"},{"n": "八角","q": "1颗","a": "减到0g少一层甘香；加到3颗有药味"},{"n": "桂皮","q": "1小段","a": "减到0g香气单薄；加到2段发苦"},{"n": "干辣椒","q": "5个","a": "这是毛氏的特色，减到0g少了微辣和发酵香；加到12个会辣到抢味"},{"n": "姜","q": "20g（4片）","a": "减到8g去腥弱；加到40g姜味冲"},{"n": "蒜","q": "3瓣","a": "减到0g少蒜香；加到8瓣发苦"},{"n": "料酒","q": "30ml","a": "减到15ml焯水去腥不彻底；加到60ml酒味残留"},{"n": "盐","q": "3g","a": "减到0g靠糖和香料则不够咸；加到8g会过咸"},{"n": "清水或高汤","q": "700ml","a": "减到400ml不够没过肉；加到1000ml需多收10分钟汁"}],"steps": ["五花肉切3cm见方块，冷水下锅加姜片和料酒，中火焯8分钟撇净浮沫，捞出温水冲净沥干。","锅烧热不放油，下冰糖小火慢慢炒，全程约5分钟，用勺背不停搅动，糖会先起大泡再变小泡，最后变成枣红色的糖色并开始冒小烟，此时立刻下肉。","肉块下锅后转中大火翻炒2分钟，让每一块肉均匀裹上糖色，炒到表面微微发亮；糖色过火发黑就苦了，宁可浅一点。","下姜片、蒜瓣、八角、桂皮、干辣椒炒香30秒，烹入料酒，加清水至刚好没过肉面。","大火烧开转小火，盖盖炖60分钟，中途翻一次面让上下都上色；筷子能轻松插入肉皮即到火候。","开盖转大火收汁8-10分钟，不停晃锅防止粘底，收到汤汁浓稠、每块肉挂上红亮油亮的糖色。","尝味：甜度合适就不要再加糖，咸淡不够补1g盐，关火后趁热装盘即可。"],"key": "毛氏红烧肉全程不放酱油，全靠炒糖色上色。炒糖色必须在糖变成枣红冒小烟时立刻下肉，早了色浅、晚了发苦。","tip": "炒糖色怕失手可先少下10g糖试色，不够再补；上色满意后剩下的糖油都倒进锅里同炖，不浪费。"},"干锅肥肠": {"time": "60分钟","level": "稍难","servings": "3人份","ing": [{"n": "肥肠（猪大肠）","q": "500g","a": "减到300g则每人不到100g；加到800g需延长翻洗和爆炒时间，否则炒不干"},{"n": "面粉与白醋（洗肠用）","q": "面粉20g+白醋30ml","a": "这是搓洗去黏液的关键，减到白醋10ml去黏液效果弱、面粉0g则腥味洗不掉；面粉加到50g要反复搓洗10分钟，白醋加到60ml会残留醋酸味需用清水冲净"},{"n": "干辣椒与花椒","q": "干辣椒15g+花椒10g","a": "干辣椒减到8g辣香不足、加到30g发苦；花椒减到3g没有麻味、加到25g麻得舌头发木"},{"n": "蒜","q": "1头（50g，切末）","a": "减到半头蒜香不足；加到2头会有生蒜冲味"},{"n": "姜","q": "15g（切片）","a": "减到5g去腥弱；加到30g姜味抢过一切"},{"n": "紫苏","q": "10g","a": "减到0g少一味草香；加到25g会发苦"},{"n": "郫县豆瓣酱","q": "2勺（30g）","a": "减到1勺红油不足；加到4勺会咸得发苦"},{"n": "生抽与盐","q": "生抽20ml+盐3g","a": "生抽减到10ml不够咸、加到35ml过咸；盐加到6g会过咸"},{"n": "高汤","q": "150ml","a": "减到50ml则肥肠不入味；加到300ml会变成汤锅"},{"n": "食用油","q": "50ml","a": "减到20ml则干锅效果差；加到100ml就成水煮肥肠了"}],"steps": ["肥肠翻面，把面粉和白醋一起抹在内壁上反复搓洗，每洗一遍冲一次水，洗到水变清无黏液，一般要换水四五次，这一步决定成品有没有腥味。","冷水下锅加姜片焯8分钟撇净浮沫，捞出用温水洗净，沥干切成3cm长段。","锅烧热不放油，下肥肠段中火干煸8分钟，不停翻动煸到表面发干、微微焦黄、肥油析出，这一步是干锅不油的关键。","倒出多余的油留底油30ml，转小火下姜片、干辣椒、花椒、蒜末炒香1分钟，蒜末微黄即可。","下豆瓣酱，小火炒30秒到油色红亮、酱香冲出。","转大火把肥肠回锅翻炒1分钟，倒入150ml高汤烧开，加盖焖6分钟让肥肠入味。","开盖转大火收汁2分钟，不停翻动让汤汁包裹肥肠，收到汤汁浓稠挂勺。","调入生抽和盐，翻匀后关火撒紫苏碎，趁热装在干锅或沙锅上，下方点酒精炉保温，边吃边煨。"],"key": "肥肠必须先干煸出油再炒，全程无水状态煸到发干，腥味和多余油脂才能去掉；洗不干净是这道菜失败的头号原因。","tip": "买不到肥肠可用猪大肠替代或用干锅鸡杂；不吃内脏可换藕片炒，但味道会完全不同。"},"东安鸡": {"time": "45分钟","level": "中等","servings": "3-4人份","ing": [{"n": "子鸡（嫩母鸡）","q": "1只约800g","a": "减到500g则肉偏柴，须缩短炖煮；加到1.2kg要炖到50分钟"},{"n": "青红椒（灯笼椒）","q": "150g（青红各半个）","a": "减到60g则酸辣味不足；加到250g则青椒味重且出汤"},{"n": "黄姜（老姜）","q": "20g","a": "东安鸡用黄姜才对味，减到8g去腥弱；加到40g姜味冲"},{"n": "蒜","q": "4瓣","a": "减到2瓣蒜香不足；加到8瓣发苦"},{"n": "干辣椒","q": "8个","a": "减到3个缺干香；加到15个苦"},{"n": "花椒","q": "8g","a": "减到0g没有麻；加到18g麻到发木"},{"n": "米醋","q": "40ml","a": "这是东安鸡酸味的来源，减到10ml则只剩辣不酸；加到70ml会酸到难以下饭"},{"n": "料酒","q": "30ml","a": "减到15ml去腥不净；加到60ml酒味重"},{"n": "生抽","q": "15ml","a": "减到0g则咸味全靠盐；加到25ml过咸"},{"n": "高汤","q": "300ml","a": "减到100ml则鸡肉不入味；加到600ml会冲淡酸辣味"}],"steps": ["子鸡剁成3cm块，用清水冲洗到水清，滤干血水；青红椒切菱形块。","锅烧热，中火下姜片、蒜瓣、干辣椒、花椒炒香40秒，油不用另加，煸鸡块时会自然渗出。","转大火下鸡块煸炒3分钟，煸到鸡皮收紧、表面微黄、锅底有鸡油渗出，这层油是东安鸡香味的来源。","烹入料酒继续炒30秒，加生抽快速翻匀，让每块鸡都裹上颜色。","倒入高汤和米醋30ml，大火烧开转小火加盖焖15分钟，让鸡块入味且肉质嫩滑。","开盖转大火，下青红椒块翻炒2分钟，椒块要炒到断生带脆，不能炒软。","再淋入余下的10ml米醋增酸，转大火收汁30秒，让汤汁薄薄挂在鸡块上。","装盘后趁热上桌，这道菜酸辣开胃，最适合配米饭。"],"key": "醋要分两次放：第一次炖煮时放一部分定酸，第二次出锅前再放一部分提亮酸香；一次全放进去久煮会挥发掉，酸味不足。","tip": "不吃酸可把米醋减到20ml并加5ml糖平衡；用黄姜和鸡骨熬的高汤味道最正宗。"},"腊味合蒸": {"time": "60分钟","level": "简单","servings": "4人份","ing": [{"n": "腊肉","q": "200g","a": "减到100g则腊香不足；加到300g会过于咸香抢掉鱼和肠的味道"},{"n": "腊鱼","q": "150g","a": "减到0g少了鱼肉那份细嫩；加到250g则腊味太重"},{"n": "腊肠","q": "120g","a": "减到60g则少一份烟熏甜；加到200g会抢戏"},{"n": "干辣椒","q": "6个（剁碎）","a": "减到2个则少一层香；加到12个会辣且发苦"},{"n": "豆豉","q": "10g（剁碎）","a": "减到0g少一味发酵香；加到20g发苦"},{"n": "蒜","q": "20g（剁末）","a": "减到8g蒜香不足；加到40g会有生蒜味"},{"n": "葱花","q": "15g","a": "减到0g少清香；加到40g会蔫"},{"n": "料酒","q": "20ml","a": "减到10ml腊味腥气去不掉；加到40ml酒味重"},{"n": "猪油","q": "20g","a": "减到0g蒸出来干涩；加到50g则腻且盖住腊香"},{"n": "高汤或清水","q": "60ml","a": "减到20ml蒸得太干；加到150ml会泡淡腊味"}],"steps": ["腊肉、腊鱼、腊肠分别洗净，腊肉和腊鱼切薄片约3mm厚（太厚不入味、太薄蒸后散），腊肠斜切厚片。","如果是重盐的腊味，切好后放温水里泡15分钟去多余盐分，泡到水微微变咸即可，泡太久会失去腊香。","取深盘或碗，先铺一层腊肉片，再铺腊鱼片，最后铺腊肠片，铺成三层，颜色错开码整齐。","另取小碗，把豆豉碎、蒜末、干辣椒碎、料酒拌成酱料，均匀铺在腊味上面，淋猪油和60ml高汤。","碗上盖保鲜膜或扣盘子，防止蒸汽滴回，冲淡腊味，也让表面保持油润。","蒸锅上汽后放入，大火蒸40分钟（老腊味需久蒸至透），关火焖5分钟再取出。","倒掉碗中多余的油和汤汁，撒上葱花，淋一勺热油激香，趁热上桌配米粉或米饭。"],"key": "腊味码三层再蒸、蒸40分钟不透，腊味自身的烟熏香才能完全透进肉里；蒸汽滴落是最容易毁掉这道菜的小事，所以要盖盖。","tip": "自制腊味（晒制后）可以先蒸20分钟再切片复蒸一次，味道更均匀；怕咸就多泡15分钟温水。"},"外婆菜炒蛋": {"time": "15分钟","level": "简单","servings": "2人份","ing": [{"n": "外婆菜（湖南坛坛菜/梅干菜炒料）","q": "200g","a": "减到100g则不够拌饭；加到300g会咸到需额外加水"},{"n": "鸡蛋","q": "4个","a": "减到2个则蛋香不足；加到6个需多炒30秒"},{"n": "蒜","q": "3瓣","a": "减到1瓣蒜香弱；加到6瓣生蒜味冲"},{"n": "干辣椒","q": "3个","a": "减到0g少一层香；加到6个会苦"},{"n": "豆豉","q": "8g","a": "减到0g少发酵咸香；加到15g发苦"},{"n": "猪油","q": "25g","a": "减到10g则外婆菜不够香；加到50g则腻"},{"n": "生抽","q": "10ml","a": "减到0g需靠盐；加到20ml会咸"},{"n": "糖","q": "4g","a": "减到0g咸中无甜；加到10g会甜腻"},{"n": "葱花","q": "10g","a": "减到0g少香气；加到25g会蔫"},{"n": "盐","q": "1g","a": "外婆菜本身咸，加到3g会过咸；减到0g一般够"}],"steps": ["外婆菜取出用刀切碎（袋装的咸菜整条下锅不易散），如果有明显咸味先用温水冲洗一下挤干。","鸡蛋4个打入碗中，加1g盐和5g清水搅散，蛋液要打匀到蛋清蛋黄完全融合、不成块。","锅烧热下猪油15g，转中火倒入蛋液，边缘凝固后用锅铲推成大块，八成熟就盛出，蛋留在锅里会老。","锅内补余下猪油，下蒜末、豆豉、干辣椒圈，小火炒30秒出香。","转中大火下外婆菜不停翻炒2分钟，炒到菜梗发软、香气明显炒出来。","鸡蛋回锅，调入生抽和糖，大火翻炒30秒让蛋吸味、块块分明。","撒葱花翻两下立刻出锅，配一勺白饭拌着吃，咸香开胃。"],"key": "鸡蛋要八成熟就盛出，最后回锅炒30秒，这样炒出来是嫩块不是碎渣；外婆菜必须中大火干炒出香，不能加水焖。","tip": "外婆菜自制最正宗（萝卜干、豆豉、辣椒、蒜末拌匀腌足一个月）；买不到可用雪菜、榨菜碎、芽菜碎替代，风味略不同。"},"永州血鸭": {"time": "50分钟","level": "稍难","servings": "4人份","ing": [{"n": "麻鸭","q": "1只约1200g（带新鲜鸭血）","a": "减到800g则鸭血配比失衡、腥味重；加到1.5kg需延长焖煮到15分钟"},{"n": "鸭血（新鲜）","q": "300g","a": "这是永州血鸭的魂，减到0g就只是辣炒鸭；加到600g会血味腥重、汤发稀"},{"n": "干辣椒与花椒","q": "干辣椒15g+花椒10g","a": "干辣椒减到8g辣度不足、加到30g发苦；花椒减到3g无麻味、加到20g麻过"},{"n": "姜与蒜","q": "姜20g（切末）+蒜1头（50g，切末）","a": "姜减到8g去腥弱、加到40g姜味抢过一切；蒜减到半头蒜香不足、加到2头会有生蒜冲味"},{"n": "辣椒酱（茶油辣椒）","q": "3勺（45g）","a": "这是永州做法核心，减到1勺则辣而不香；加到6勺咸辣失衡"},{"n": "紫苏","q": "15g","a": "减到0g少一味清凉；加到30g发苦"},{"n": "料酒","q": "30ml","a": "减到15ml腥味重；加到60ml酒味冲"},{"n": "生抽与盐","q": "生抽20ml+盐3g","a": "生抽减到10ml不够咸、加到35ml过咸；盐加到6g会过咸"},{"n": "高汤","q": "200ml","a": "减到50ml血会结块腥味重；加到400ml则变成汤菜"},{"n": "食用油","q": "50ml","a": "减到25ml则煸不出鸭油、香味不足；加到100ml则腻"}],"steps": ["麻鸭剁成3cm块，鸭血倒进碗里搅散防止结块，保留 300ml 备用；块状血渣和内脏另做处理不用。","鸭块冷水下锅加料酒，焯6分钟撇净浮沫，捞出用温水冲洗干净，沥干。","锅烧热下40ml油，转中火下蒜末、干辣椒、花椒小火炒香1分钟。","下辣椒酱，小火炒1分钟至油色红亮、酱香冲鼻。","转大火下鸭块煸炒5分钟，不停翻动煸到鸭皮收紧出油、表面微焦，这层煸出的鸭油是全菜最香的部分。","烹入料酒，加生抽和盐翻匀，倒入高汤烧开，加盖转小火焖8分钟。","开盖把鸭血沿锅边缓缓淋入（先搅匀再淋，否则会结成块），轻轻推匀，转中火焖3分钟至血凝成嫩块。","关火撒入紫苏碎，用余温翻匀后立刻装盘，趁热吃，凉了鸭血凝硬就不好吃了。"],"key": "鸭血必须最后放、小火焖3分钟，火大会沸腾成渣、口感发柴；鸭块先煸出油再焖，血腥味才不会翻上来。","tip": "买不到新鲜鸭血可用鸭血制品（鸭血豆腐或凝固鸭血块）代替，切小块最后下锅；不吃血的可省略，但风味会少一半。"},"湘西酸肉": {"time": "50分钟","level": "中等","servings": "4人份","ing": [{"n": "带皮五花肉","q": "500g","a": "减到300g则每人几片；加到700g需延长腌制时间到3小时"},{"n": "盐","q": "12g","a": "减到6g则肉不入味、酸味不挂；加到20g会咸得压不住酸"},{"n": "干辣椒面（湘西自制糍粑辣椒）","q": "60g","a": "减到30g则辣香不足、酸肉发闷；加到100g会辣到只剩辣味"},{"n": "蒜","q": "1头（50g，剁末）","a": "减到半头蒜香弱；加到2头会发苦"},{"n": "姜","q": "20g（剁末）","a": "减到8g去腥弱；加到40g姜味冲"},{"n": "豆豉","q": "15g（剁碎）","a": "减到0g少一味发酵咸；加到30g发苦"},{"n": "紫苏","q": "10g","a": "减到0g少草香；加到25g发苦"},{"n": "猪油","q": "30g","a": "减到10g则煸不出香气；加到60g则腻"},{"n": "米酒","q": "20ml","a": "减到10ml腌时香味不够；加到40ml酒味残留"},{"n": "高汤","q": "150ml","a": "减到50ml则粘锅焦底；加到300ml则变成汤菜"}],"steps": ["五花肉切5cm长条、1.5cm厚的大片，用盐抓匀腌20分钟至肉色发暗、渗出盐水，腌透是酸肉入味的基础。","取一半干辣椒面（最好是自制糍粑辣椒：新鲜辣椒开水烫过后剁碎、拌盐和蒜末、装坛密封发酵一周）加米酒、蒜末、姜末、豆豉拌成腌料。","把腌料与肉片抓匀，码入坛中压实，上面压石或重物，盖严密封，室温发酵2-3天（天冷则需5天），发酵到闻到明显酸香、肉表面发黏即可。","取出酸肉冲洗掉表面多余辣椒末，沥干切成1.5cm宽的条。","锅烧热下猪油，中火下酸肉条煸炒6分钟，不停翻动煸到边缘微卷、表面出油、辣椒香被激发出来。","加入高汤，大火烧开转小火焖8分钟，让肉彻底吸饱味。","开盖转大火收汁3分钟，收到汤汁浓稠包住肉条，撒紫苏碎翻匀即可装盘。"],"key": "自制发酵是酸肉的根本（辣椒面+蒜+盐+密封发酵），没发酵过就只是辣椒炒肉；腌制约3天是酸香最平衡的窗口，发久了会酸到发馊。","tip": "没时间发酵可用现成酸肉或酸坛菜；发酵时室温别超过28℃，用玻璃坛留一点空间，坛口一定要密封不漏气。"},"宁乡花猪": {"time": "25分钟","level": "中等","servings": "3人份","ing": [{"n": "宁乡花猪肉（带皮五花）","q": "500g","a": "宁乡花猪以皮薄肉嫩著称，减到300g每人只几片；加到800g需分两锅炒"},{"n": "青线椒","q": "250g","a": "减到120g辣味不足；加到400g需多炒1分钟，否则出软水"},{"n": "蒜","q": "4瓣","a": "减到2瓣蒜香弱；加到8瓣生蒜冲味"},{"n": "姜","q": "15g","a": "减到5g去腥弱；加到30g姜味重"},{"n": "干辣椒","q": "6个","a": "减到2个缺干香；加到12个发苦"},{"n": "豆豉","q": "10g（剁碎）","a": "减到0g少发酵咸香；加到20g发苦"},{"n": "紫苏","q": "8g","a": "减到0g少草香；加到20g会发苦"},{"n": "生抽","q": "15ml","a": "减到8ml不入味；加到25ml过咸"},{"n": "猪油","q": "30g","a": "减到10g少镬气；加到60g腻"},{"n": "高汤","q": "50ml","a": "减到0g则炒肉偏干；加到150ml会变煮肉"}],"steps": ["宁乡花猪肉带皮切薄片，皮朝上码在盘中备用；青线椒斜切段。","锅烧到冒青烟，下猪油化开，把肉片皮面朝下平铺锅中，中火煎40秒逼出皮下油脂，煎到皮面起泡微焦，翻面再煎30秒。","下姜末、蒜末、干辣椒、豆豉，小火炒香40秒。","转大火下青椒段，不加水干炒2分钟，炒到青椒表皮起虎皮、边缘微软但仍带脆。","烹入30ml高汤，大火翻炒30秒让青椒吸味，腾起镬气白烟。","肉片回锅，加生抽，大火翻炒30秒均匀裹汁。","关火撒紫苏，翻两下装盘，宁乡花猪肉的鲜嫩配上青椒的香，是湘中最日常也最难替代的一口。"],"key": "花猪肉先带皮煸出油再与青椒合炒，皮的胶质和油脂混着辣椒的焦香，才是宁乡做法与普通五花肉炒青椒的区别。","tip": "没有宁乡花猪可用普通带皮五花肉替代，但要先煮20分钟再切片炒，口感接近；青椒换成二荆条更接近本地风味。"},"湘乡烘鸭": {"time": "3小时（含腌制）","level": "稍难","servings": "4人份","ing": [{"n": "麻鸭","q": "1只约1.5kg","a": "减到1kg则4人分吃太少、肉也偏老；加到2kg需延长时间到2.5小时"},{"n": "生抽","q": "40ml（3勺）","a": "减到20ml则颜色淡、味道不足；加到70ml会过咸发苦"},{"n": "蜂蜜","q": "30ml","a": "这是烘出焦亮鸭皮的钥匙，减到10ml上色不足；加到60ml会烤焦发苦"},{"n": "麦芽糖","q": "20g","a": "减到0g则缺少焦糖层次；加到50g会过甜"},{"n": "五香粉与盐（腌鸭用）","q": "五香粉5g+盐10g","a": "盐减到5g鸭肉不够咸，五香粉减到0g则缺一层卤香；盐加到18g会咸到压住蜂蜜的甜，五香粉加到12g会有明显药味"},{"n": "花椒","q": "8g","a": "减到3g麻味弱；加到15g麻舌"},{"n": "姜与蒜","q": "姜30g（片+末）+蒜4瓣","a": "姜减到10g去腥弱、加到50g姜味冲；蒜减到2瓣蒜香不足、加到8瓣发苦"},{"n": "料酒","q": "30ml","a": "减到15ml去腥不净；加到60ml酒味重"},{"n": "葱花（葱段、葱丝）","q": "20g","a": "减到5g香气不足；加到40g会发蔫"},{"n": "卤汁清水","q": "500ml","a": "减到200ml则无法浸泡上色；加到800ml味道会变淡"}],"steps": ["麻鸭去毛开膛洗净，用清水冲洗腹腔内两遍，鸭油取出另留（湘乡做法会用鸭油刷皮）。","锅中加500ml水、姜片、葱段、料酒烧开，把鸭放入焯3分钟定型，捞出立刻用冷水冲洗，鸭皮收紧后更易烤出脆感。","取小碗混合生抽、蜂蜜、麦芽糖、五香粉、盐、花椒粉、姜末、蒜末、料酒调成挂汁，抹满鸭身内外和腔内。","把鸭挂起或架在烤网上，室温风干2小时（湘乡吊炉烘鸭的核心就是风干），风到鸭皮收紧发干、颜色转深。","烤箱预热200℃，把鸭架在烤网上，下面垫烤盘，烤40分钟，其间取出两次刷挂汁并倒掉滴下的油脂。","取出鸭身再刷一层麦芽糖水，调到220℃高温再烤10分钟，烤到鸭皮呈深琥珀色、油光发亮、发出轻微爆裂声。","出炉静置10分钟让肉汁回流，再斩件装盘，淋上烤盘里的鸭油和卤汁，配葱丝和辣椒圈。"],"key": "风干2小时不能省，鸭皮干透才能在高温下烤出脆亮壳而不回软；最后刷麦芽糖再高温10分钟，是“焦亮”的来源。","tip": "没有吊炉可用烤箱加果木碎增香；一次烤两只可上下叠放，但下层要多刷一次汁、上层延后5分钟出炉。"},"湘西酸豆角炒肉末": {"time": "25分钟","level": "简单","servings": "2人份","ing": [{"n": "酸豆角（酸豇豆）","q": "250g","a": "减到150g则酸味不足；加到400g会酸到压住肉味，需多加油和汤汁"},{"n": "猪肉末","q": "200g","a": "减到120g则不够拌饭；加到300g需多炒2分钟把肉末炒出油"},{"n": "糊辣椒","q": "50g","a": "湘西做法用干锅小火焙至焦香再舂碎，减到20g则糊香不足只剩辣味；加到90g会辣得盖住酸豆角味道"},{"n": "小米辣","q": "3个","a": "减到0g辣度降一档；加到8个辣到跳脚，湘西酸辣就靠这一层"},{"n": "蒜","q": "4瓣（切末）","a": "减到2瓣蒜香弱；加到8瓣会有生蒜冲味"},{"n": "姜","q": "10g（切末）","a": "减到0g去腥不足；加到20g姜味抢过糊辣椒"},{"n": "猪油","q": "25g","a": "减到10g则肉末不出油、香味弱；加到50g则腻"},{"n": "生抽","q": "15ml（1勺）","a": "减到8ml则肉末寡淡；加到25ml会过咸"},{"n": "糖","q": "5g","a": "减到0g则酸中无回甜；加到12g会发甜盖住酸味"},{"n": "葱花","q": "10g","a": "减到0g少一层香；加到25g会发蔫"}],"steps": ["酸豆角冲洗一遍，掐掉两头老筋，切成1cm小段备用；酸豆角本身很咸，一般不用再泡水。","锅烧热下猪油25g，转中火下肉末，用锅铲压散炒散，炒到肉末出油、颜色变深发干，这一步决定成菜是肉末还是肉酱。","下糊辣椒碎、姜末、蒜末和小米辣圈，小火炒40秒，糊辣椒的焦香被激出来后再下酸豆角。","转大火下酸豆角，不停翻炒2分钟，炒到豆角颜色更绿、边缘微微发软、酸味被激出来。","沿锅边淋入生抽，快速翻匀，加糖再炒30秒，让咸甜酸三味咬在一起。","关火撒葱花，翻匀装盘。这道菜最下饭，锅底汤汁拿来泡饭能多吃一碗。"],"key": "糊辣椒要干锅小火焙到焦香再舂碎才出糊香，直接用辣椒面只有辣味没有湘西那股焦糊气；肉末先炒到出油发干再下酸豆角。","tip": "酸豆角咸度高，盐先不放、炒好尝味再决定要不要补；配白饭用锅底汤汁泡着吃是湘西最常见的吃法。"},"擂辣椒皮蛋": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "螺丝椒（青椒）","q": "250g","a": "减到150g则分量不足；加到350g需多擂2分钟，擂椒要擂到出汁成糊"},{"n": "皮蛋","q": "2个","a": "减到1个则不够分；加到3个会抢掉辣椒味且发苦"},{"n": "蒜","q": "4瓣","a": "减到2瓣蒜香弱；加到8瓣会有生蒜冲味"},{"n": "豆豉","q": "10g","a": "减到0g少发酵咸香；加到20g发苦"},{"n": "猪油","q": "20g","a": "减到10g则擂椒不香；加到40g则腻"},{"n": "生抽","q": "15ml（1勺）","a": "减到8ml味道不足；加到25ml会过咸"},{"n": "陈醋","q": "8ml","a": "减到0g少一点开胃酸；加到20ml会酸得倒牙"},{"n": "糖","q": "4g","a": "减到0g咸中无甜；加到10g发甜"},{"n": "葱花","q": "10g","a": "减到0g少香气；加到25g会蔫"},{"n": "盐","q": "1g","a": "豆豉和生抽已有咸味，加到3g会过咸；减到0g一般够"}],"steps": ["青椒洗净擦干，不去蒂（蒂是擂的把手），干锅小火慢焙4-5分钟，焙到表皮起焦斑、颜色转深、用手捏略有回软。","焙好的青椒连蒂放入擂钵，先放蒜瓣、豆豉，用捣杵先捣蒜和豆豉成细末，再把青椒倒入一起捣。","用捣杵把青椒捣到皮破汁出、整体变成糊状，这一步就是“擂”的核心，捣不烂就出不来那股糊香，标准状态是能挂住捣杵。","皮蛋剥壳切4瓣，放在擂钵里与擂椒一起再捣几下，让皮蛋的碱香和辣椒混匀（讲究的可只捣一半保留皮蛋块形）。","另起小锅烧热猪油10g，把擂好的辣椒皮蛋倒入，转小火炒2分钟，边炒边淋余下猪油，炒到油亮、噼啪作响、香气冲鼻。","调入生抽、陈醋、糖和盐，转大火快速翻匀15秒让味道裹匀即可，久炒擂椒会发苦。","撒葱花出锅，趁热吃最好，凉了擂椒会发腥、皮蛋会发硬。"],"key": "擂椒要擂到出汁成糊而不是切碎，捣不烂的辣椒只有辣味没有糊香；青椒必须干锅焙出焦斑再擂。","tip": "没有擂钵可用石臼、蒜臼或擀面杖加厚碗代替；嗜辣可加小米辣一起擂，但建议先擂出原味再另加。"},"蒜薹腊肉": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "蒜薹（蒜苗）","q": "300g","a": "减到150g则菜量不足；加到450g需多炒1分钟并分两次下锅，否则会生"},{"n": "腊肉","q": "150g（切薄片）","a": "减到80g则腊香不足；加到250g会咸到需多放蒜薹"},{"n": "干辣椒","q": "5个（剪段）","a": "减到2个缺干香；加到10个发苦"},{"n": "蒜","q": "3瓣（切片）","a": "减到1瓣蒜香弱；加到6瓣生蒜味重"},{"n": "豆豉","q": "8g","a": "减到0g少发酵咸香；加到15g发苦"},{"n": "生抽","q": "10ml","a": "减到0g需靠腊肉咸味；加到20ml会咸"},{"n": "糖","q": "4g","a": "减到0g咸中无甜；加到10g发甜"},{"n": "猪油","q": "20g","a": "减到10g腊肉煸不出油；加到40g则腻"},{"n": "盐","q": "1g","a": "腊肉本身咸，加到3g会过咸；减到0g一般够"},{"n": "高汤或清水","q": "40ml","a": "减到0g则略干；加到120ml会变成水煮菜"}],"steps": ["腊肉洗净切薄片；如果腊味很咸，把切好的腊肉放温水里泡10分钟去盐，泡淡后再炒更平衡。","蒜薹撕去老筋，斜切成3cm段，洗净后彻底沥干水分，带水下锅会变成煮蒜薹。","锅烧热下猪油10g，中火下腊肉片火下腊肉片煸炒3分钟，煸到腊肉边缘微透、肥油析出、闻到明显腊香。","下蒜片、干辣椒和豆豉，小火炒40秒出香。","转大火下蒜薹，快速翻炒2分钟，炒到蒜薹颜色更翠绿、梗部断生仍带脆，此时不能盖锅盖，蒜薹会出水变软。","沿锅边淋40ml高汤或清水，大火翻炒30秒，加生抽、糖和盐调味。","蒜薹要脆、腊肉要香，两者对比是这道菜的全部魅力，装盘时把腊肉盖在蒜薹上。"],"key": "蒜薹全程不能加盖、不能久炒，2分钟断生封住汁水才脆；腊肉先煸出油，香味才能挂到蒜薹上。","tip": "湖南做法可换成二分肥瘦的广式腊肠、或者用本地烟熏腊肉；没有腊肉可用五花肉加生抽老抽烟熏味替代。"},"乡里腊肉炒豆角": {"time": "45分钟","level": "中等","servings": "3-4人份","ing": [{"n": "湘西烟熏腊肉","q": "250g","a": "250g 正好炒一盘下饭；加到 350g 会咸到发齁、干豆角吸不到肉香，要相应减盐；减到 150g 则腊味不足，需补 2g 盐并多放一把干辣椒才够湘味"},{"n": "干豆角（农家晒的干四季豆）","q": "200g","a": "200g 泡发后约 500g，配 250g 腊肉比例刚好；加到 300g 要延长焖煮 10 分钟，否则外熟内硬；减到 120g 口感偏柴，缺豆角特有的干香"},{"n": "猪油或菜籽油","q": "30ml","a": "30ml 能把腊肉自身的油脂煸出来；加到 50ml 容易腻口、豆角挂不上味，减到 15ml 则干豆角吸油不足，发柴不香"},{"n": "蒜苗","q": "2根约80g","a": "2根切段后香气够足；加到 4 根蒜味压过腊香，减到 1 根少了那股生蒜冲香"},{"n": "干辣椒","q": "5个约8g","a": "5个剪段是湘西的量；加到 10 个辣度盖住豆角香，减到 2 个只剩颜色没有辣味"},{"n": "花椒","q": "1小勺约2g","a": "2g 麻香正好；加到 4g 会麻得舌头发木，减到半勺豆瓣和腊肉的香出不来"},{"n": "生抽","q": "15ml","a": "15ml 提鲜刚好；加到 30ml 咸度过高压掉腊肉回香，减到 5ml 颜色发淡、鲜味不足"},{"n": "盐","q": "3g","a": "腊肉本身很咸，这 3g 是保险量；加到 8g 明显过咸，建议先尝腊肉再决定放不放；减到 0g 只在腊肉偏淡时才合适"},{"n": "清水或高汤","q": "150ml","a": "150ml 刚好焖透豆角；加到 300ml 会变成汤烧豆角、豆角吸味变慢，减到 50ml 豆角焖不透芯还是硬的"},{"n": "姜片","q": "4片","a": "4片去腊肉的烟熏味；加到 8 片姜味抢戏，减到 2 片压不住烟熏气"}],"steps": ["干豆角用温水泡发2小时至完全舒展，撕成5cm长段，冲洗两遍挤干水分；泡不透的话后面焖多久芯都还是硬的。","腊肉整块冷水下锅，加姜片、料酒煮12分钟至筷子能扎透，捞出晾凉切成2mm薄片；煮过的腊肉切不散、炒时出油均匀。","锅中放菜籽油烧至五成热，下腊肉片小火煸3分钟，煸到肉片边缘微卷、肥肉部分透明吐油，盛出一半多余的油留用。","锅内留底油，下干辣椒段和花椒小火煸1分钟至辣椒变棕红出香，再下姜片、蒜末爆香。","转大火倒入豆角段翻炒2分钟，让每段豆角都裹上腊肉油，再倒入腊肉片一起翻炒。","加生抽、盐、白糖和150ml热水，盖盖转小火焖15分钟，中途翻动两次至豆角软糯入味。","开盖大火收汁2分钟，拌入蒜苗段，断生即可出锅，豆角干香裹着腊味特别下饭。"],"key": "干豆角要泡足2小时且焖煮不少于12分钟，纤维才咬得断；腊肉先煮后切是这道菜不散不柴的前提。","tip": "泡豆角时水里加一小勺食用碱能催软，泡好后多冲两遍去碱味；想更香就把煸出的腊肉油留一勺，最后沿锅边淋一圈。"},"九转大肠": {"time": "2.5小时","level": "稍难","servings": "3-4人份","ing": [{"n": "生猪大肠","q": "500g","a": "500g 是3-4人份的标准量，肥厚处切段才够嚼；加到 800g 洗洗炒炒工时翻倍、酱汁不够挂；减到 300g 每人只能分到两三段，成菜显得寒酸"},{"n": "面粉","q": "50g","a": "50g 配小苏打揉洗能彻底带走肠壁黏液；加到 100g 会把肠壁洗得太涩发脆，减到 20g 黏液洗不净，成菜发腥滑口"},{"n": "小苏打","q": "5g","a": "5g 配50g面粉是标准碱性配比；加到 10g 肠皮被腐蚀发软易破，减到 2g 去黏液效果减半"},{"n": "黄豆酱30g与甜面酱20g","q": "50g","a": "黄酱主咸香、甜面酱出甜味，3:2 是鲁菜标准比；黄酱加到 50g 只剩咸、甜味全无，甜面酱加到 40g 则发齁盖住五味"},{"n": "干辣椒","q": "4个","a": "4个剪段出干辣；加到 8 个辣椒味压过醋香，减到 2 个苦辣味不足"},{"n": "葱段3根、姜片5片、蒜末15g","q": "共约50g","a": "葱姜蒜齐用才够复合香；姜减到 2 片压不住大肠腥味，蒜末减到 5g 香气不足"},{"n": "山西老陈醋","q": "40ml","a": "40ml 分两次用：20ml 炒时提酸、20ml 出锅前烹出酸香；一次全倒进去会挥发掉大半酸味，减到 20ml 就只剩酸而没有酸香"},{"n": "白糖","q": "20g","a": "20g 配40ml醋做出酸甜平衡；加到 35g 甜得压住酱香，减到 10g 则酸味单薄、五味不全"},{"n": "生抽","q": "15ml","a": "15ml 上色提鲜；加到 30ml 酱汁发黑发苦，减到 5ml 色泽暗、鲜味弱"},{"n": "高汤200ml与水淀粉30ml","q": "共230ml","a": "高汤 200ml 煨出味、淀粉 30ml 勾亮芡；高汤减到 100ml 煨不透、芡汁过稠会挂成团，减到 50ml 芡汁稀得挂不住大肠"}],"steps": ["大肠翻面用清水冲净内外，撕掉表面白色油膜和淋巴，用面粉50g与小苏打5g反复揉搓内外10分钟，每揉2分钟换一次清水，再冲3遍至水清无黏液。","冷水下锅加葱姜、料酒煮15分钟至筷子能扎透，捞出沥干。","大肠切3cm段，滚水焯1分钟去碱味，捞出用温水冲净沥干；焯过的大肠才紧实弹牙。","锅中放油烧至七成热，下大肠段炸2分钟至表皮鼓起呈虎皮状，捞出控油；油温低于六成热会炸成灰白色、吸不住酱汁。","锅中留底油，下干辣椒段和葱姜蒜小火炒1分钟出香，加黄豆酱、甜面酱小火炒2分钟至酱冒泡香浓；火大会把酱炒苦。","加陈醋20ml、生抽、白糖和200ml高汤烧开，肠段回锅转小火煨8分钟，边煨边翻让每段都吃到味。","淋入水淀粉勾薄芡，芡汁包住肠段后大火翻炒10秒出锅，浇一勺锅底余油。"],"key": "洗大肠的面粉加苏打揉搓、以及炸出虎皮，是成败的两道关；没虎皮吸不住汁，洗不净则整锅发腥。","tip": "怕掌握不住油温就把炸大肠改成先煮后煎；喜欢更酸就把陈醋提到50ml、白糖减到15g，做成酸压甜的老派改法。"},"糖醋鲤鱼": {"time": "50分钟","level": "稍难","servings": "3-4人份","ing": [{"n": "鲤鱼","q": "1条约750g","a": "750g 的鱼片出7片花刀刚好是标准盘；加到 1.2kg 要延长炸制3分钟并用更大的盘撑鱼身，减到 500g 花刀减到5片、造型撑不起来"},{"n": "鸡蛋","q": "1个","a": "1个蛋液配150g淀粉调糊刚好挂住鱼片；加到 2 个蛋糊偏稀、炸不出脆壳，减掉则颜色发白不上色"},{"n": "干淀粉","q": "150g","a": "150g 兑 120ml 水调成能挂住鱼片的稠糊；加到 200g 壳厚发死，减到 100g 则挂浆薄、炸后掉粉露白"},{"n": "白糖","q": "80g","a": "80g 配 60ml 醋是鲁菜糖醋的甜酸比；加到 120g 甜得盖住醋香，减到 50g 则汁偏酸、挂汁发薄"},{"n": "香醋","q": "60ml","a": "60ml 是糖醋汁的酸量；加到 90ml 酸得冲、鱼肉发柴，减到 30ml 只剩甜，失去糖醋二字"},{"n": "番茄酱","q": "30g","a": "30g 主要给红色和一点果酸；加到 60g 颜色太红像番茄鱼，减到 15g 汁色偏暗不喜庆"},{"n": "料酒","q": "30ml","a": "30ml 配姜片去鱼腥并让酒香进肉；加到 60ml 酒味冲、抢糖醋香，减到 10ml 腥气去不净"},{"n": "姜末","q": "10g","a": "10g 塞鱼腹去腥；加到 25g 姜味在汁里发辣，减到 5g 鱼腥味压不住"},{"n": "盐4g与白胡椒粉2g","q": "共6g","a": "盐 4g 腌鱼底味、胡椒 2g 去腥增香；盐加到 10g 会先腌咸、汁一浇就齁，胡椒减到 1g 效果不明显"},{"n": "食用油","q": "800ml","a": "800ml 足够浸没整鱼；油少要分两锅炸、油温下降会影响定型，减到 400ml 鱼身浮不上来、受热不均"}],"steps": ["鲤鱼去鳞去内脏洗净擦干，在鱼身两面剞牡丹花刀：从头至尾片出7片相连的斜刀片、深至鱼骨但不切断，片开后鱼身自然向外翻翘成跳跃造型，刀距约2cm且间距要均匀。","鱼身内外抹盐和白胡椒粉腌10分钟去腥，鱼腹内塞姜末。","锅中油烧至七成热（约200℃），用漏勺提着鱼尾，先把鱼头朝下浸炸3秒定型再翻入锅中，炸4分钟至鱼皮起泡金黄；不做定型这步，鱼花会散开。","捞出控油，锅留底油烧至五成热，倒入白糖、醋、番茄酱和150ml清水，中火熬2分钟至糖化开、汤汁冒大泡、微微发稠。","加盐1g、姜末再熬30秒，糖醋汁能挂勺即可关火，熬过头糖会发苦、颜色发黑。","把炸好的鲤鱼摆在长盘上，糖醋汁快速浇在鱼身上，鱼身发出刺啦的脆响。","趁热上桌，鱼尾翘起、浇汁后带脆响即算造型成功。"],"key": "牡丹花刀的片法与定型浸炸决定造型能不能像鲤鱼跃起；糖醋汁熬到发亮挂勺就关火，久熬糖必焦苦。","tip": "家里油量紧张可炸两遍：低温炸熟捞出，再高温复炸30秒逼出油分，外皮更酥；甜口人群番茄酱加到50g、白糖减到70g。"},"德州扒鸡": {"time": "3.5小时","level": "稍难","servings": "4-6人份","ing": [{"n": "净膛整鸡","q": "1只约1.2kg","a": "1.2kg 是两段煮的标准体型，鸡肉不柴；加到 1.6kg 要把卤煮时间延长到2小时，减到 800g 汤味浸透度不够、肉偏柴"},{"n": "麦芽糖","q": "30g","a": "30g 熬成糖稀上色，光亮带烤香；加到 60g 颜色过深发黑，减到 15g 上色太浅不上镜"},{"n": "卤料包（八角桂皮花椒草果陈皮白芷丁香）","q": "1包约25g","a": "25g 配 1.5L 卤汤香料味正好；加到 40g 会满嘴药味，减到 15g 则香气单薄"},{"n": "葱段4根与姜片30g","q": "共约100g","a": "姜 30g 提香去腥；姜减到 10g 腥味明显，葱减到 2 根香不够"},{"n": "花椒粉","q": "10g","a": "10g 出锅撒香；加到 20g 麻得盖住鸡肉香，减到 3g 则没有扒鸡特有的麻香"},{"n": "精盐","q": "15g","a": "15g 是1.2kg鸡配1.5L汤的基准；加到 25g 咸得齁，减到 8g 肉不够入味、需延长浸泡"},{"n": "生抽30ml与老抽10ml","q": "40ml","a": "生抽提鲜、老抽上色，3:1 是标准配比；老抽加到 25ml 汤色发黑发苦，减到 3ml 色泽偏浅"},{"n": "料酒","q": "50ml","a": "50ml 去腥并让肉香入味；加到 100ml 汤里酒味太重，减到 20ml 去腥力不足"},{"n": "香油","q": "20ml","a": "20ml 趁热刷在表皮上形成油亮膜、防干；加到 50ml 表面油腻不吸味，减到 5ml 皮面容易发干"},{"n": "食用油","q": "1.5L（炸制用）","a": "1.5L 够浸过整鸡定色；油少就要分批炸、每次油温都要重新回升，减到 500ml 鸡身泡不透、炸色不均"}],"steps": ["整鸡洗净去内脏，清水浸泡2小时充分出血水，捞出擦净；用针在腿部和胸口扎小孔便于入味。","锅中加清水、卤料包、葱姜、料酒、盐、生抽老抽烧开，下整鸡浸没，大火烧开转小火保持似开非开煮40分钟，这是第一次煮，主要让盐味和香料味渗入。","捞出鸡用净布擦干，趁热在全身抹匀麦芽糖水（麦芽糖30g加50ml水熬化），晾15分钟至表面发黏。","油锅烧至八成热（约190℃），提着鸡脖把鸡放入油中炸3至4分钟至全身金黄、表皮起泡，这步叫过油，目的是上色定形。","另起锅倒入第二步的卤汤烧开，把炸好的鸡放回卤汤，转小火再煮60分钟至鸡骨酥软、筷子能轻松插透；这一段火不能大，大了肉柴。","捞出放在笸箅上趁热刷一层香油，晾凉后鸡皮发亮不干。","斩件装盘，鸡肉断面呈玉白色带汁、鸡皮金黄，撒花椒粉，配热馒头或米饭。"],"key": "两段煮加一次过油是老卤扒鸡的做法：过油上色不能省，炸后必须回卤汤再煮，否则只有颜色没有入味。","tip": "没有整鸡可用鸡腿、鸡翅分件做；卤汤越煮越浓，留着当老卤下次用。麦芽糖可用红糖1:1替换，色泽略深。"},"葱烧海参": {"time": "3天泡发＋40分钟","level": "稍难","servings": "3人份","ing": [{"n": "干海参（刺参）","q": "50g","a": "50g 干参泡发后约 250g，够 3 人吃；加到 80g 泡发约 400g 要多备一碗高汤，减到 30g 每人只能分到两三口"},{"n": "大葱（山东大葱）","q": "2根约200g","a": "只取葱白 200g 煸出的葱油才够香；用小葱替代香气打折，加到 300g 葱味过冲会盖住海参的鲜，减到 120g 葱香不足"},{"n": "高汤","q": "300ml","a": "300ml 配 250g 海参，芡汁浓而不澥；加到 600ml 汤汁过稀挂不住海参，减到 150ml 味浓但芡容易发稠结块"},{"n": "猪油","q": "40ml","a": "40ml 煸葱油到焦黄的量；用植物油可减到 20ml 但葱香少一层，加到 80ml 成品油腻"},{"n": "蚝油","q": "20g","a": "20g 提鲜增稠；加到 40g 蚝味腥重、压过葱香，减到 8g 鲜味寡淡"},{"n": "生抽15ml与老抽10ml","q": "25ml","a": "两酱3:2 调色又不至于发黑；老抽加到 20ml 颜色乌暗，减到 3ml 色泽偏浅"},{"n": "料酒","q": "30ml","a": "30ml 焯水去腥；加到 60ml 酒味呛人，减到 10ml 去腥不足"},{"n": "白糖","q": "5g","a": "5g 提鲜回甘；加到 15g 汁偏甜减了海参的鲜，减掉也不影响成菜"},{"n": "姜片","q": "5片","a": "5片 焯水去腥；加到 10 片 姜味抢戏，减到 2 片 海参腥味回弹"},{"n": "水淀粉","q": "30ml","a": "30ml 勾成能挂住海参的亮芡；加到 60ml 芡厚发糊，减到 15ml 芡薄挂不住、汤汁摊在盘里"}],"steps": ["干海参清水泡24小时（夏季冷藏），去掉沙嘴和体内沙线洗净，再换清水泡48小时并每天换水一次，泡到用手一捏有弹性、能回弹即发好，泡发后约250g。","泡好的海参切3cm段，入沸水加料酒和姜片焯2分钟去腥，捞出沥干；焯水超过3分钟海参会发硬。","大葱只取葱白，切4cm长段，宽的一劈为二；葱段要厚薄均匀，煸的时候才能同时成熟。","锅中放猪油烧至六成热，下葱段小火慢煸4至5分钟至表面焦黄发软，这一步煸出的就是葱油，火大发苦、只煸到微黄则没有葱香，盛出葱段备用，葱油留在锅内。","葱油中下姜片、蚝油炒香，加高汤、生抽、老抽、白糖烧开。","放入海参转小火煨3分钟让海参吸味，再把煸好的葱段放回煨1分钟。","淋水淀粉勾芡至汤汁浓稠能挂住海参，倒回海参翻匀，淋明油装盘，葱香浓郁、海参软糯。"],"key": "发海参每天换水和葱段煸到焦黄是两道硬关口；海参焯水超时发硬、葱煸过头发苦。","tip": "赶时间就直接买水发好的海参，回家只需焯水；葱油可一次多炼些滤出冷藏，随时用来做葱烧类菜。"},"锅包肉": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "猪里脊","q": "300g","a": "300g 切3mm薄片炸完约一大盘，两人份刚好；加到 500g 需分两锅炸、挂糊时间翻倍，减到 200g 每人夹不到几片"},{"n": "干淀粉","q": "120g","a": "120g 兑 115ml 水调成能挂住肉片的稠糊，比例约1:1；加到 160g 外壳厚死发硬，减到 80g 挂不住、炸后大片掉渣"},{"n": "鸡蛋","q": "1个（取蛋清）","a": "蛋清 1个让外壳更脆；加到 2 个蛋清浆偏稀、挂壳薄，减到半个蛋清脆度下降"},{"n": "白糖","q": "60g","a": "60g 配 45ml 醋是东北酸甜比；加到 80g 甜得盖住肉香，减到 40g 酸甜失衡、只有酸"},{"n": "白醋","q": "45ml","a": "45ml 出酸香；加到 60ml 酸得倒牙，减到 25ml 只剩甜、少了那股冲鼻的酸"},{"n": "番茄酱","q": "25g","a": "25g 给汁上色并添一点果酸；加到 50g 颜色偏红味偏甜，减到 10g 汁色偏暗"},{"n": "料酒","q": "15ml","a": "15ml 腌肉去腥；加到 30ml 肉片带酒味，减到 5ml 腥气残留"},{"n": "白胡椒粉","q": "1g","a": "1g 去肉腥提香；加到 3g 辣喉，减掉则腥味明显"},{"n": "熟白芝麻","q": "5g","a": "5g 撒面上增香；加到 15g 芝麻味压过酸甜，减到 2g 看不出点缀效果"},{"n": "青红椒丝各20g与香菜段10g","q": "共50g","a": "50g 配色添爽脆；加到 100g 抢走主角位置，减到 20g 摆盘颜色寡淡"}],"steps": ["里脊顺纹切成3mm薄片再切成5cm长片，碗中加料酒、少量盐抓匀腌10分钟。","淀粉120g加清水115ml调成能挂住肉片的稠糊，打入1个蛋清拌匀。","腌好的肉片逐片挂糊，抖掉多余淀粉，浆衣要薄而均匀。","油温五成热（170℃）下肉片，中火炸2分钟至外壳定型微黄捞出；油温升到八成热复炸40秒至金黄酥脆，捞出控油。","锅留底油下糖、醋、番茄酱和60ml清水熬1分钟至起泡挂勺，糖醋比例按糖:醋:番茄酱等于60:45:25，甜口可把糖加到75g。","倒入炸好的肉片，转大火快速翻拌15至20秒让每片都挂上亮汁，汁一裹匀立刻出锅，久炒会回软。","撒白芝麻和青红椒丝、香菜段，趁热吃，酥脆带酸甜。"],"key": "定型炸加高温复炸是酥脆的关键；挂糊薄而匀、炸后只翻拌十几秒，这两点决定成品是酥而不软。","tip": "怕挂糊厚就把淀粉减到100g、水减到95g；不吃酸的用白醋减到30ml、糖加到70g做成甜口锅包肉。"},"小鸡炖蘑菇": {"time": "1.5小时","level": "中等","servings": "3-4人份","ing": [{"n": "散养笨鸡（带骨鸡块）","q": "1只约1.2kg","a": "1.2kg 炖40分钟肉嫩不柴；换成 500g 速冻鸡块则10分钟就散，减到 2kg 要延长炖煮40分钟且柴"},{"n": "干榛蘑","q": "40g","a": "40g 泡发后约 200g，是东北做法的标准比例；加到 70g 蘑菇味压过鸡肉香，减到 20g 汤中几乎尝不到菌香"},{"n": "东北宽粉条","q": "100g","a": "100g 吸汤后分量翻倍，配1.2kg鸡正好；加到 150g 粉条抢戏、汤变糊稠，减到 50g 少了东北味"},{"n": "干辣椒","q": "4个","a": "4个东北做法只要微辣；加到 8 个辣味盖住菌香，减到 2 个只有颜色"},{"n": "花椒","q": "15粒","a": "15粒 麻香提鲜；加到 30 粒 麻得发木，减到 5 粒 香气平淡"},{"n": "葱段3根与姜片6片","q": "共约60g","a": "姜 6 片压住鸡的土腥；减到 2 片腥味明显，葱减到 1 根香不足"},{"n": "生抽30ml与老抽8ml","q": "38ml","a": "生抽提鲜、老抽上色，比例约4:1；老抽加到 20ml 汤色发黑，减到 3ml 颜色偏淡"},{"n": "料酒","q": "30ml","a": "30ml 焯水和炒制各用一半；加到 60ml 酒味重，减到 10ml 腥味压不住"},{"n": "白糖","q": "5g","a": "5g 炒糖色提鲜；加到 15g 汤偏甜，减掉也不影响，但颜色会暗一些"},{"n": "食用油","q": "30ml","a": "30ml 煸出鸡油；加到 60ml 汤面浮油重、喝汤发腻，减到 10ml 煸不出油香味淡"}],"steps": ["干榛蘑用温水泡发2小时，反复搓洗3遍去掉表面泥沙和草屑，泡发的水澄清后留用，榛蘑的鲜味都在这碗水里。","鸡斩成3cm块，冷水下锅加姜片、料酒焯3分钟撇净血沫，捞出用温水冲洗干净；冷水下锅是让血一次放净，汤才清不浑。","锅中放油烧至五成热，下鸡块中火煸炒4分钟至表皮微黄出油，鸡肉的香气要先煸出来。","加干辣椒段、花椒、葱姜炒香，烹料酒、生抽老抽，加白糖炒匀上色。","倒入没过鸡块的开水约1.5L和澄清的泡蘑水，大火烧开转小火炖40分钟。","放入提前泡软的宽粉条，再小火炖10分钟，粉条吸饱鸡汤后变透明发亮。","尝味补盐，鸡肉能脱骨、汤汁浓稠即可出锅，撒葱花。"],"key": "榛蘑必须泡发后反复搓洗去沙，泡蘑水澄清留用；鸡肉焯水要冷水下锅，汤清而不浑是这道菜的分水岭。","tip": "用鲜榛蘑200g可免去泡发，但要先焯水1分钟去土腥；粉条最后10分钟下锅，早了会炖化成糊。"},"猪肉炖粉条": {"time": "1小时","level": "简单","servings": "3-4人份","ing": [{"n": "五花肉","q": "400g","a": "400g 切3cm厚片配100g粉条是东北标准量；加到 600g 肥肉偏腻、要先多煸一遍逼油，减到 250g 肉香不足、汤也不够浓"},{"n": "东北宽粉条","q": "100g","a": "100g 泡1小时后分量翻倍；加到 150g 粉条抢汤、吃起来全是粉，减到 60g 少了灵魂"},{"n": "大白菜（酸菜最佳）","q": "300g","a": "300g 切条挤干水，与肉炖到半熟最香；加到 500g 菜味太重压住肉香，减到 150g 汤里菜太少不地道"},{"n": "干辣椒","q": "3个","a": "3个东北家常只要一点辣香；加到 6 个辣味抢戏，减到 1 个香气不足"},{"n": "花椒","q": "10粒","a": "10粒 提香；加到 20 粒麻味明显，减到 4 粒香味平淡"},{"n": "葱段2根与姜片4片","q": "共约40g","a": "姜 4 片去肉腥；减到 1 片腥气重，葱减到 1 根不够香"},{"n": "生抽30ml与老抽8ml","q": "38ml","a": "两酱比例约4:1 上色提鲜；老抽加到 20ml 汤色黑亮过头，减到 3ml 色不匀"},{"n": "料酒","q": "20ml","a": "20ml 去腥；加到 40ml 酒味明显，减到 8ml 去腥不足"},{"n": "白糖","q": "5g","a": "5g 收汁时提鲜；加到 12g 汤偏甜，减掉影响不大"},{"n": "食用油","q": "25ml","a": "25ml 够煸出肉油；加到 50ml 汤面浮油过厚、喝汤腻，减到 10ml 肉片煸不出焦边"}],"steps": ["宽粉条用温水泡1小时至完全软化，捞出剪成段；粉条一定要泡透，泡不透炖时硬芯，泡太久会烂。","五花肉切3cm厚片，冷水下锅加姜片料酒焯2分钟去血水，捞出沥干。","锅中放油烧至六成热，下肉片中火煸炒4分钟至边缘微卷、逼出部分油脂，舀掉一半油，留下的不腻留住香。","加干辣椒、花椒、葱姜炒香，烹料酒、生抽老抽炒匀。","倒入400ml热水烧开，转小火炖30分钟至五花肉软而不烂。","下大白菜（酸菜切条挤干水）再炖10分钟，此时肉已软而白菜刚熟。","放入粉条加盖小火炖8分钟，粉条吸汤后透明发亮；大火收汁，尝味补盐，连汤带肉盛出。"],"key": "肉先煸出油再炖才不腻；粉条最后8分钟下锅，泡不透会硬芯、泡太软会成糊。","tip": "红薯粉条筋道、土豆粉条滑软，可按喜好换；用普通白菜代替酸菜就减掉酸味，想补回来出锅前滴5ml醋即可。"},"地三鲜": {"time": "30分钟","level": "中等","servings": "3-4人份","ing": [{"n": "茄子","q": "2根约400g","a": "400g 是标准量；加到 600g 吸油量翻倍、要用更多粉拍干，减到 250g 盘子太空、茄子香味不足"},{"n": "土豆","q": "2个约350g","a": "350g 滚刀块炸透后不塌；加到 500g 炸制时间要多1分钟，减到 200g 少了这份绵糯的口感"},{"n": "青椒","q": "1个约150g","a": "150g 最后放保持脆绿；加到 250g 生味重、抢主角，减到 80g 配色不足"},{"n": "蒜末","q": "15g","a": "15g 是提香量；加到 30g 蒜味冲过土豆，减到 6g 香气淡"},{"n": "生抽","q": "20ml","a": "20ml 咸鲜基础；加到 35ml 汁偏咸，减到 8ml 味道寡淡"},{"n": "蚝油","q": "15g","a": "15g 增鲜增稠；加到 30g 蚝味发腥，减到 6g 鲜味不够"},{"n": "白糖","q": "8g","a": "8g 提鲜回甘；加到 20g 齁甜，减到 3g 略欠圆润"},{"n": "干淀粉","q": "20g","a": "20g 拍在茄子上防吸油、这是地三鲜不油腻的关键；加到 50g 茄子发齁，减到 5g 茄子吸油变软塌"},{"n": "盐","q": "4g","a": "4g 分两次放；加到 10g 过咸，减到 1g 茄子腌不透水、还会吸更多油"},{"n": "食用油","q": "800ml（过油用）","a": "800ml 够三次过油；油少要分锅炸、油温反复下降影响上色，减到 400ml 食材沉底、炸不匀"}],"steps": ["茄子切滚刀块，撒3g盐拌匀腌15分钟杀出水分，挤干后薄薄拍一层干淀粉，拍淀粉能减少吸油，是地三鲜不油腻的关键。","土豆切滚刀块，薄拍一层淀粉；青椒去籽切块。","油温六成热下土豆块炸4分钟至表面金黄、边缘发硬，捞出沥油；土豆不炸透，后面烧汁会塌。","油温升到七成热下茄子块炸3分钟至外皮起皱金黄，捞出沥油。","锅留底油下蒜末炒香，倒入全部主料，加生抽、蚝油、白糖和80ml清水，大火快速翻匀烧2分钟。","加青椒块和盐再炒1分钟，青椒要最后放才能保持脆绿。","淋少量水淀粉勾薄芡，芡汁包住茄子土豆才挂汁，出锅装盘。"],"key": "茄子腌水拍淀粉是控油关键，青椒最后下锅保脆；土豆和茄子要分开过油，混在一起会互相抢油温。","tip": "想少用油可以把茄子改蒸10分钟再烧汁，热量更低但少了过油的焦香；土豆换成3个约500g也可以，炸制时间相应延长。"},"铁锅炖大鹅": {"time": "2.5小时","level": "中等","servings": "4-5人份","ing": [{"n": "大鹅带骨肉块","q": "800g","a": "800g 配8个饼是标准量；加到 1.2kg 炖煮要延长到90分钟、饼也得多贴4个，减到 500g 不够4人吃到饼"},{"n": "玉米面300g与豆面100g","q": "400g","a": "3:1 是东北贴饼子的经典配比，豆面增加黏性和谷香；玉米面减到 200g 饼会发散掉渣，减到 100g 口感太粗"},{"n": "干辣椒","q": "6个","a": "6个体现东北大鹅的微辣；加到 12 个辣度压过鹅肉香，减到 3 个香味不足"},{"n": "花椒","q": "20粒","a": "20粒去鹅肉腥；加到 40 粒麻味盖过肉香，减到 8 粒腥气明显"},{"n": "葱段4根","q": "4根","a": "4根与姜片一起炖出底味；加到 8 根葱味过重，减到 2 根不够香"},{"n": "姜片8片","q": "8片","a": "8片去腥提香；加到 15 片姜味抢戏，减到 3 片腥味回弹"},{"n": "蒜5瓣拍碎","q": "5瓣","a": "5瓣提香；加到 10 瓣生蒜味冲，减到 2 瓣香不够"},{"n": "生抽40ml与老抽10ml","q": "50ml","a": "4:1 上色提鲜；老抽加到 25ml 汤色发黑，减到 3ml 色不匀"},{"n": "料酒","q": "40ml","a": "40ml焯水和炖制各一半；加到 80ml 酒味重，减到 15ml 去腥不足"},{"n": "白糖","q": "10g","a": "10g炒至上色提鲜；加到 25g 汤偏甜，减到 3g 上色略暗"},{"n": "食用油","q": "40ml","a": "40ml干煸鹅肉逼油；加到 80ml 汤面浮油过厚腻口，减到 15ml 鹅油煸不出、腥味重"}],"steps": ["鹅肉块冷水下锅加姜片、料酒焯5分钟撇净浮沫，捞出用温水冲洗干净沥干。","铁锅烧热不放油，下鹅肉块中火干煸6分钟，煸到表面水分收干、鹅油渗出、边缘微焦；干煸去腥是炖鹅不腥的前提。","加干辣椒、花椒、葱姜蒜，中火炒2分钟出香。","加生抽、老抽、料酒、白糖炒匀上色，倒入开水没过肉面约2cm，大火烧开转小火炖60分钟。","和面：玉米面300g、豆面100g用温水和成偏软的面团，醒30分钟后揪成8个厚饼。","鹅肉炖到筷子能扎透时，把面饼沿锅边贴一圈，饼子一半浸在汤里一半露在锅壁上，盖盖中小火再炖20分钟，饼底吸汤变成锅巴。","沿锅边淋入50ml清水防止粘锅、让锅巴更酥，焖5分钟。","关火，把锅边锅巴饼翻面蘸汤吃，锅内鹅肉软烂脱骨。"],"key": "锅边贴饼要一半泡在汤里一半贴锅壁，蒸汽加汤汁同时作用才能焖出酥脆锅巴；鹅肉先干煸去腥再炖。","tip": "玉米面饼可提前和好冷藏备用；没有铁锅用厚底铸铁锅或砂锅，把饼压在锅边汤面上方10厘米处贴稳。"},"北京烤鸭": {"time": "1天风干＋40分钟","level": "稍难","servings": "4-5人份","ing": [{"n": "净膛鸭","q": "1只约2.2kg","a": "2.2kg 是家庭烤整鸭的合理大小；加到 3kg 烤制要延长20分钟且难熟透，减到 1.5kg 皮脆度好但不够4人吃"},{"n": "麦芽糖","q": "40g","a": "40g熬糖稀上色兼起脆壳；加到 70g 颜色过深发黑，减到 20g 上色太浅不起层"},{"n": "蜂蜜","q": "20g","a": "20g补甜并让皮更亮；加到 50g 甜味明显、壳偏硬，减到 10g 亮度不足"},{"n": "五香粉与盐","q": "五香粉3g、盐15g","a": "盐 15g 是腌鸭坯的基准，烤后才不至于寡淡；盐加到 30g 齁咸，减到 8g 鸭肉没味道"},{"n": "料酒","q": "30ml","a": "30ml去腥并入味；加到 60ml 酒味明显，减到 10ml 腥气残留"},{"n": "甜面酱","q": "100g","a": "100g 配 50ml 清水澥开成稀糊；不澥开会齁且抹不开，加到 150g 太甜，减到 60g 香味不足"},{"n": "大葱","q": "1根约150g","a": "150g 切细丝，卷饼时解腻；加到 300g 饼里全是葱，减到 80g 配得不够"},{"n": "黄瓜","q": "1根约100g","a": "100g 切条清脆解腻；加到 200g 水分太多，卷起来会漏汁，减到 50g 清口不够"},{"n": "薄饼（春饼）","q": "12张","a": "12张配4人刚好；加到 20张显得干瘪，减到 8 张不够分"},{"n": "葱白与姜片","q": "共30g","a": "30g塞鸭腹去腥；加到 60g 腹内味道太重，减到 10g 去腥力弱"}],"steps": ["鸭子从颈部开口掏出内脏，洗净后用清水浸泡3小时充分出血水，捞出用棉线把开口缝好、鸭爪扎起。","锅中加麦芽糖40g、蜂蜜20g、盐15g、料酒30ml和200ml清水熬成糖稀，晾凉备用；糖稀必须晾凉才抹，热糖稀会把鸭皮烫破。","鸭身内外抹匀糖稀，挂入阴凉通风处风干12至24小时至表皮干爽发硬，风干是脆皮的核心，烤箱出品也必须先晾干。","烤箱预热230℃，鸭架在烤网上、下面垫烤盘接油，烤30分钟至表皮金黄。","取出鸭身晾3分钟，刷第二层糖稀，再烤10分钟至颜色枣红、鸭皮发出脆响。","片鸭先片胸脯肉再片腿肉，每片带皮厚2至3mm，刀要快而斜，斜刀片出的皮更宽更完整。","甜面酱加50ml清水澥开成稀糊，葱切细丝、黄瓜切条。","薄饼刷甜面酱，铺葱丝黄瓜和鸭皮卷起食用。"],"key": "风干到位、两次刷糖、烤后回炉，脆皮三要素缺一不可；片皮要带皮斜刀片出，脆响就来自这层皮。","tip": "没有整鸭可用鸭腿半只代替，先蒸再烤也成立；甜面酱太稠必须澥水，稠酱抹在饼上会齁嗓子。"},"老北京炸酱面": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "猪肉丁（肥瘦3:7）","q": "300g","a": "300g 煸出的油刚好够拌面；加到 450g 酱汁不够挂、肉丁发柴，减到 200g 炸酱发干没油香"},{"n": "干黄酱","q": "60g","a": "60g 是北京炸酱的酱主体，配甜面酱才对味；加到 100g 酱发苦发涩，减到 30g 酱香味不足、成了肉末酱"},{"n": "甜面酱","q": "30g","a": "30g 提甜并让酱色发亮；加到 60g 齁甜减了黄酱的咸香，减到 15g 酱偏咸"},{"n": "葱末","q": "50g","a": "50g 分两次：一半炒香一半出锅前拌入；全下锅炒会发黄出苦，减到 20g 少了葱香"},{"n": "姜末","q": "15g","a": "15g 去肉腥；加到 30g 姜味抢戏，减到 5g 腥气压不住"},{"n": "黄瓜丝","q": "150g","a": "150g 是菜码的分量，爽脆解酱咸；加到 250g 面太水，减到 80g 缺清爽口"},{"n": "豆芽","q": "100g","a": "100g 焯1分钟断生；加到 200g 豆芽生味重，减到 50g 菜码不完整"},{"n": "青豆","q": "50g","a": "50g 焯2分钟；加到 100g 面里太杂乱，减到 20g 颜色点缀不足"},{"n": "手擀面","q": "400g","a": "400g 供3-4人；加到 600g 每碗面少菜码，减到 250g 3人份偏少"},{"n": "料酒","q": "20ml","a": "20ml 煸肉去腥；加到 40ml 酒味重，减到 8g 去腥不足"}],"steps": ["黄酱60g先用100ml清水澥开成稀糊备用，干黄酱直接下锅会发硬结块。","锅中放油烧至六成热，下肉丁中火煸炒6分钟，把肉丁煸到表面焦黄、出油、干爽，小碗干炸的核心就是把肉的水分煸干，酱才不水垮。","加葱末一半、姜末、料酒，炒到葱姜出香。","转小火下甜面酱30g炒1分钟出香，再倒入黄酱糊转小火慢炒5分钟，边炒边分三次加50ml清水，让酱汁浓稠、颜色发亮、能挂在肉丁上；火大酱就发苦。","关火拌入剩余葱末，葱末最后放才保香；炒好的炸酱应当油亮、咸香微甜、酱味醇厚。","豆芽焯水1分钟，青豆焯2分钟，黄瓜切细丝。","面条煮至八分熟捞出过一遍凉开水让面更筋道，浇2勺炸酱，配黄瓜丝、豆芽、青豆码成菜码，从碗底往上翻拌均匀。"],"key": "炸酱讲究干炸、小火慢炒、酱炒到油亮挂肉，兑水必须分次少量；菜码是面的另一半，缺了菜码就少了那股清爽。","tip": "甜口可以把甜面酱提到50g、干黄酱减到40g；直接买现成炸酱汁也能用，但味道层次少一截。"},"铜锅涮羊肉": {"time": "40分钟","level": "中等","servings": "3-4人份","ing": [{"n": "手切羊肉片","q": "400g","a": "400g 够3-4人吃两轮；加到 600g 一次涮太多、肉片久放会变色，减到 250g 不够分"},{"n": "清水（汤底）","q": "1500ml","a": "1500ml 配 400g 肉是铜锅清汤比例；加到 2500ml 汤味寡淡，减到 800ml 涮几次就浑了"},{"n": "麻酱","q": "100g","a": "100g 用 60ml 温水澥开就是二八酱的稠度；加到 150g 蘸料太稠发苦，减到 60g 挂不住肉、味道薄"},{"n": "韭菜花","q": "30g","a": "30g 咸香提味；加到 60g 咸得齁嘴，减到 10g 少了那口脆咸"},{"n": "腐乳","q": "2块","a": "2块碾成泥拌进麻酱；加到 4 块腐乳味冲，减到 1 块去膻作用弱"},{"n": "葱花","q": "20g","a": "20g 撒在麻酱里；加到 40g 抢味，减到 8g 香气不足"},{"n": "豆腐","q": "200g","a": "200g 切厚片吸羊汤；加到 400g 抢了羊肉的位置，减到 100g 桌上不够夹"},{"n": "粉丝","q": "50g","a": "50g 涮熟吸味；加到 100g 粉味压过羊肉，减到 20g 桌上显得少"},{"n": "白菜","q": "200g","a": "200g 最后下锅；加到 400g 白菜吸油汤发腻，减到 100g 解腻口不足"},{"n": "香菜","q": "15g","a": "15g 撒在蘸料里；加到 30g 香气太冲，减到 5g 意思不到"}],"steps": ["羊肉逆纹切2mm薄片，摊开放冷藏1小时至冻硬，这样下锅一涮就熟、不卷不柴。","麻酱100g用温水60ml分次澥开，边加边搅，澥到能缓慢流动的稠度，再加韭菜花末、腐乳（碾成泥）、葱花调成麻酱小料；麻酱必须温水分次澥开才不结块。","铜锅坐炉上倒入清水1500ml，放葱段姜片、几粒海米、几朵香菇，大火烧开做清汤锅底，老北京铜锅用清水汤底不加油。","羊肉片夹入滚汤，抖散着七上八下约8秒，羊肉从红变白立刻捞出，蘸麻酱小料吃，涮久了发柴。","豆腐切厚片入汤煮2分钟，粉丝先煮软再下锅，白菜和金针菇最后放。","羊肉涮完后再下白菜豆腐吸收羊味，喝汤前撒香菜。","麻酱小料不够按比例续加，每加50g麻酱补30ml温水。"],"key": "清汤锅底加麻酱小料是灵魂，麻酱必须温水分次澥开才不结块；羊肉七上八下变色即捞，久了就柴。","tip": "没有铜锅用不锈钢锅加清汤即可；羊肉片下锅前冷藏冻硬，是不卷不断的关键。"},"煎饼果子": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "绿豆面","q": "150g","a": "150g 是天津煎饼果子的面糊主料；加到 200g 口感太粗，减到 100g 豆香变淡、绿豆的绿也出不来"},{"n": "小米面","q": "50g","a": "50g 与绿豆面3:1 配出天津味；加到 100g 会偏小米、黏度下降，减到 20g 摊起来易破"},{"n": "清水","q": "250ml","a": "250ml 调成能流动的稀糊；加到 320ml 糊太稀不易成形，减到 180ml 糊稠、摊不开"},{"n": "鸡蛋","q": "2个","a": "2个蛋摊满整张饼；加到 3 个蛋味盖过麦香，减到 1 个没有果子的厚实感"},{"n": "薄脆（油酥饼）","q": "1张","a": "1张是标准夹心；加到 2 张太脆硬、咬下去掉渣，减到半张口感单薄"},{"n": "葱花","q": "20g","a": "20g 撒在蛋液上；加到 40g 生葱味冲，减到 8g 香不明显"},{"n": "香菜","q": "15g","a": "15g 提香；加到 30g 抢味，减掉也不影响但少了那股清新"},{"n": "甜面酱","q": "30g","a": "30g 刷匀；加到 50g 齁甜，减到 15g 味不足"},{"n": "辣椒酱或辣椒油","q": "15g","a": "15g 微辣；加到 35g 太辣抢味，减到 5g 一点辣味都没有"},{"n": "孜然粉","q": "2g","a": "2g 撒在表面；加到 6g 香料味抢过酱香，减到 1g 基本尝不出"}],"steps": ["绿豆面150g、小米面50g混合，加250ml清水调成能流动的稀面糊，盖保鲜膜放温暖处发酵8至12小时至表面有气泡、闻着微酸，发酵是天津煎饼果子区别于普通煎饼的关键。","面糊发酵后会变稀、沉淀充分，摊之前再搅匀，太稠可再加20至30ml水。","铁板烧热刷一层油，倒一勺面糊摊成直径约25cm的圆饼，中火摊30秒至底面凝固、能提起不破。","打入1个鸡蛋摊开，撒葱花和香菜，等边缘蛋液凝固后把面皮翻面。","另一面再摊1个蛋，放上薄脆，用铲子从一边卷起或对折，让蛋液包住薄脆，这就是果子。","刷甜面酱30g和辣椒酱15g，撒孜然粉。","用油纸托住从中间对折再对折，装袋或装盘趁热吃。"],"key": "面糊必须发酵带微酸才正宗；蛋液要摊满并包住薄脆，这是有果子和普通鸡蛋煎饼的区别。","tip": "没有薄脆可用油条切段或炸馒头代替；天津人爱加两个蛋，油多一倍、摊饼时间延长10秒。"},"狗不理包子": {"time": "3小时","level": "稍难","servings": "4人份（15-18个）","ing": [{"n": "中筋面粉","q": "500g","a": "500g 配275ml水是半发面的比例；加到 600g 面偏硬、包子皮不蓬松，减到 400g 面太软难成型"},{"n": "温水","q": "275ml","a": "275ml 分次加；加到 320ml 面粘手难揉，减到 240ml 面硬不易起褶"},{"n": "酵母","q": "5g","a": "5g 发酵到1.5倍正好是半发面；加到 10g 发到两倍、皮发塌不好包，减到 2g 发不起来"},{"n": "猪肉馅（三肥七瘦）","q": "300g","a": "300g 配100ml花椒水正好打水馅；加到 450g 馅多难捏褶，减到 200g 皮馅比例失衡"},{"n": "花椒水","q": "100ml","a": "100ml 分三次打进肉馅；加到 160ml 馅稀难成型，减到 50ml 馅干不出汁"},{"n": "葱末","q": "60g","a": "60g 打出葱香；加到 100g 馅发苦，减到 30g 香不足"},{"n": "姜末","q": "15g","a": "15g 去肉腥；加到 30g 姜味抢戏，减到 5g 去腥力弱"},{"n": "生抽","q": "30ml","a": "30ml 提鲜；加到 50ml 馅发咸，减到 10ml 味道淡"},{"n": "盐","q": "5g","a": "5g 打水馅的基础咸度；加到 10g 过咸，减到 2g 淡而无味"},{"n": "香油","q": "30ml","a": "30ml 最后淋入封住肉汁；加到 60ml 馅滑腻不好包，减到 10ml 肉汁流失"}],"steps": ["面粉加酵母和温水揉成光滑面团，盖盖发酵到两倍大、手指戳洞不回缩；发到1.5倍也可以，这正是水馅半发面的分寸。","肉馅分三次打入100ml花椒水，每次都顺一个方向搅打至上劲，打水馅是狗不理多汁的关键。","拌入葱末、姜末、生抽、盐，最后淋香油封住肉汁，拌好的馅能打上劲、看着发黏。","面团排气揉光，搓条下剂子每个约30g，擀成中间厚边缘薄的圆皮。","包入20g馅，左手托皮右手捏褶，从下往上折出18个褶，收口捏紧不留缝隙。","蒸锅水开后放包子，旺火蒸12分钟，关火焖2分钟再开盖，直接开盖包子会塌。","出锅后垫箅子晾2分钟再吃，防止包子皮被自身水汽沤烂。"],"key": "18个褶和水馅是两个招牌；面皮中间厚边缘薄才不蒸后破底，开盖前必须焖2分钟。","tip": "想省事可以做12褶的新式包法；出锅后垫箅子晾一下，皮才挺括不塌。"},"胡辣汤": {"time": "2.5小时","level": "稍难","servings": "3人份","ing": [{"n": "牛骨与牛肉","q": "牛骨500g、牛肉200g","a": "牛骨 500g 熬出奶白汤、牛肉 200g 切丁；牛骨加到 1kg 汤太浓稠、稀释后反而不白，牛肉减到 100g 少了肉丁口感"},{"n": "面筋","q": "100g","a": "100g 是胡辣汤的料量；加到 200g 面筋抢戏，减到 50g 料不齐全"},{"n": "粉丝","q": "50g","a": "50g 泡软下锅；加到 100g 粉丝味太重，减到 20g 少了滑口"},{"n": "海带丝","q": "50g","a": "50g 切丝；加到 100g 抢味，减到 20g 不成配料"},{"n": "黄豆","q": "30g","a": "30g 提前泡2小时；加到 60g 豆味重，减到 10g 少了嚼劲"},{"n": "胡辣汤料（八角桂皮花椒白芷小茴香草果丁香）","q": "1份约20g","a": "20g 配1.5L汤是标准浓度；加到 40g 药味苦，减到 8g 胡椒香不足"},{"n": "辣椒油","q": "40ml","a": "40ml 是河南喝法必须的辣；加到 80ml 辣得盖住胡味，减到 15ml 没有辣味"},{"n": "香醋","q": "40ml","a": "40ml 关火后淋入才有冲鼻的酸；减到 15ml 酸得不够，减到 0 则只剩辣和胡椒"},{"n": "白胡椒粉","q": "5g","a": "5g 是胡辣汤的主体味；加到 12g 辣喉、抢过其他味，减到 2g 名字里的辣就没了"},{"n": "盐","q": "8g","a": "8g 配2.5L汤；加到 15g 过咸，减到 3g 味太淡"}],"steps": ["牛肉切丁冷水下锅焯2分钟撇沫，与牛骨同入锅，加汤料包、葱姜，大火烧开转小火熬2小时成奶白高汤，高压锅可压到40分钟。","黄豆提前泡2小时，粉丝泡软，海带丝洗净切段。","高汤过滤后重新烧开，下牛肉丁、面筋块、泡好的黄豆和海带丝，煮5分钟。","下粉丝和面筋丝，加盐8g、白胡椒粉5g；粉丝最后放，煮久就烂。","淋水淀粉勾芡，芡要稀而能挂勺，胡辣汤讲究稀糊不是羹，芡过厚会像糨糊。","关火后立刻淋香醋40ml，醋在沸腾时加会挥发掉酸味，关火后加才酸得冲。","再淋辣椒油40ml，撒蒜苗或香菜，趁热喝，配油馍头或千层饼。"],"key": "酸和辣要靠醋与辣椒油最后点入，勾芡只到稀糊状；白胡椒粉是主体味道，不能只靠辣椒撑场面。","tip": "汤料可自制：八角2颗、桂皮1段、花椒10粒、白芷3g、小茴香5g、草果1个、丁香3粒装纱布袋；怕辣就把辣椒油减到15ml、醋保持40ml。"},"烤冷面": {"time": "20分钟","level": "简单","servings": "1-2人份","ing": [{"n": "冷面片（荞麦冷面）","q": "2张","a": "2张是标准做法；加到 3 张铁板放不下、也卷不成筒，减到 1 张卷起来会散"},{"n": "鸡蛋","q": "2个","a": "2个摊满两层；加到 3 个蛋味太重、压住甜酱，减到 1 个口感偏干"},{"n": "洋葱","q": "30g","a": "30g 切丝；加到 60g 洋葱生味重，减到 15g 香不足"},{"n": "火腿肠","q": "1根","a": "1根斜切铺面；加到 2 根咸味过重，减到半根配料不完整"},{"n": "甜面酱","q": "30g","a": "30g 刷面；加到 50g 齁甜，减到 15g 味道不足"},{"n": "辣椒油","q": "15ml","a": "15ml 东北街头味；加到 35ml 太辣，减到 5ml 没辣味"},{"n": "白糖","q": "10g","a": "10g 撒在酱上提甜；加到 25g 甜得发腻，减到 3g 甜味不足"},{"n": "孜然粉","q": "2g","a": "2g 撒面；加到 6g 香料味盖过一切，减到 1g 尝不出"},{"n": "香醋","q": "5ml","a": "5ml 沿锅边烹一下提酸；加到 15ml 酸得跳，减到 0 少了那股冲味"},{"n": "食用油","q": "20ml","a": "20ml 刷铁板；加到 40ml 边缘发泡、面条太软，减到 10ml 易粘板"}],"steps": ["铁板刷油烧热，放冷面片，中火煎1分钟至边缘微翘、底面金黄。","沿锅边淋入30ml清水，盖盖焖1分钟让面片回软变软，靠蒸汽做到软而不烂。","掀盖，在面片上放切碎的洋葱圈和斜切片的火腿肠。","打入2个鸡蛋，用铲子摊开覆盖整片面片，边缘待蛋白凝固。","刷甜面酱30g、辣椒油15ml、白糖10g、孜然粉2g，沿锅边烹入5ml醋。","用铲子从一端把面片卷起成筒，或从中间对折压紧，让酱料和料都裹在里面。","移到铁板边角再煎1分钟至两面金黄、酱汁微焦香，装袋撒孜然。"],"key": "加水盖盖焖那一分钟是烤出软而不烂口感的关键；酱料必须最后放，早放会被面片吸干。","tip": "想更香可先在面片上刷一层油再煎；不吃辣就去掉辣椒油只留甜面酱，孜然粉加到3g更香。"},"葱爆羊肉": {"time": "20分钟","level": "中等","servings": "2-3人份","ing": [{"n": "羊后腿肉","q": "300g","a": "300g 逆纹切2mm片正好一盘；加到 500g 需分锅爆炒、否则来不及出锅，减到 200g 一人几片不够吃"},{"n": "大葱（山东大葱）","q": "2根约200g","a": "200g 切马蹄段是标准量；用小葱替代葱香差一档，加到 300g 葱味压过羊肉，减到 120g 少那股甜葱香"},{"n": "蛋清","q": "1个","a": "1个蛋清上浆锁水，羊肉才滑嫩；加到 2 个蛋清浆太黏挂不住，减半个则嫩度下降"},{"n": "淀粉","q": "10g","a": "10g 与蛋清一起抓匀；加到 25g 浆厚、爆炒易结块，减到 5g 锁水力弱"},{"n": "料酒","q": "15ml","a": "15ml 腌肉去膻；加到 30ml 酒味重，减到 5ml 膻味明显"},{"n": "生抽","q": "15ml","a": "15ml 上色提鲜；加到 25ml 咸味偏重，减到 8ml 色淡味薄"},{"n": "醋","q": "10ml","a": "10ml 沿锅边烹出酸香去膻；加到 20ml 酸得冲羊肉发柴，减到 0 只剩膻"},{"n": "蒜片","q": "10g","a": "10g 爆香；加到 25g 生蒜味冲，减到 5g 香不够"},{"n": "盐","q": "3g","a": "3g 提味；加到 8g 过咸，减到 1g 略欠"},{"n": "食用油","q": "30ml","a": "30ml 需七成热大火爆炒；加到 60ml 羊肉吸油发腻，减到 15ml 锅温上得慢"}],"steps": ["羊肉逆着纹理切2mm薄片，加料酒、1个蛋清、淀粉抓匀上浆，腌10分钟，上浆是羊肉滑嫩的关键。","大葱取葱白斜切马蹄段，葱白与葱绿分开，葱段要厚薄均匀才能同时熟。","锅烧到冒青烟，下油烧至七成热（约200℃），转大火下羊肉片，摊平不动10秒，待边缘卷曲变色立刻盛出，爆字诀就是火力足、时间短。","锅中留底油，下蒜片和葱白段转大火炒20秒，葱段边缘要出现焦斑但不能糊，葱香就在这20秒里逼出来。","倒回羊肉，烹生抽和醋，沿锅边淋醋激出葱香，大火翻炒10秒。","加盐快速翻匀，葱绿下锅再翻5秒出锅。","装盘时保持葱段完整，葱有焦斑、羊肉片不塞。"],"key": "爆的核心是七成热油温加大火加10秒内出锅羊肉；葱白下锅后20秒必须出，葱焦了发苦、没焦没葱香。","tip": "羊肉上浆前用清水泡10分钟去血水（换两次水）腥味更轻；怕膻可加1g白胡椒或用花椒水抓肉。"},"扒牛肉": {"time": "2.5小时","level": "中等","servings": "3-4人份","ing": [{"n": "牛肋条或牛腩","q": "600g","a": "600g 带筋带腩炖出来最香；换成牛腱 600g 口感更紧实、需延长时间，减到 400g 每人分不到几块"},{"n": "土豆","q": "2个约300g","a": "300g 块先炸后炖、能保持形不烂；加到 450g 要多炸1分钟，减到 150g 少了这一层的粉糯"},{"n": "葱段4根","q": "4根","a": "4根与姜片八角一起出底味；加到 8 根葱味过重，减到 2 根不够香"},{"n": "姜片6片","q": "6片","a": "6片去牛肉腥；加到 12 片姜味抢戏，减到 2 片腥气明显"},{"n": "八角2颗","q": "2颗","a": "2颗增香；加到 4 颗香料味太浓，减到 1 颗香气单薄"},{"n": "生抽40ml与老抽10ml","q": "50ml","a": "4:1 上色提鲜；老抽加到 25ml 汁色发黑，减到 3ml 颜色偏淡"},{"n": "料酒","q": "40ml","a": "40ml焯水和炖制；加到 80ml 酒味重，减到 15ml 去腥不足"},{"n": "冰糖","q": "15g","a": "15g炒糖色提亮；加到 30g 汁偏甜，减到 5g 色泽略暗"},{"n": "高汤","q": "500ml","a": "500ml 慢炖入味；加到 900ml 味被稀释、芡也难挂住，减到 250ml 牛肉发紧"},{"n": "淀粉","q": "15g","a": "15g 调水淀粉勾大芡；加到 35g 芡厚成糊、牛肉发暗，减到 8g 芡稀挂不住肉"}],"steps": ["牛肉切4cm块，冷水下锅加姜片料酒焯3分钟撇净血沫，捞出用温水冲洗干净。","锅中放油烧至五成热，下牛肉块中火煸炒6分钟至表面微黄，煸出多余油脂，炖出来才不腻；加葱姜、八角炒香。","加生抽、老抽、料酒、冰糖炒匀，倒入高汤没过肉面，大火烧开转小火炖90分钟至筷子能轻松插透。","土豆切滚刀块另起油锅炸至金黄，捞出拌少许盐，先炸后炖，土豆不烂还能保持形状。","牛肉软烂后放入土豆块，再炖10分钟入味。","挑出葱姜八角，锅中留汁大火收浓到挂勺。","淋淀粉水勾大芡，大芡是扒菜的关键，芡要浓稠到把肉裹住不流。","淋明油翻匀装盘，牛肉块油亮芡汁饱满。"],"key": "大芡是扒的灵魂，芡要浓稠到把肉裹住不流、芡稀了就成了炖牛肉；土豆先炸后炖才不烂。","tip": "牛肋条炖1.5小时最香；土豆也可换成山药1根，炖后不化形；收汁前尝咸淡，糖放多了会盖过肉香。"},"熘肝尖": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "猪肝","q": "250g","a": "250g 切2mm薄片正好一小盘；加到 400g 要分锅滑炒、否则出水变柴，减到 150g 每人几片"},{"n": "青椒","q": "1个约100g","a": "100g 配肝片；加到 180g 抢味，减到 50g 配色和爽脆都不够"},{"n": "木耳（水发）","q": "50g","a": "50g 提脆；加到 100g 抢主角，减到 20g 不成配料"},{"n": "蒜片","q": "15g","a": "15g 爆香是熘肝尖的标志；加到 30g 蒜味冲，盖住肝香，减到 5g 香不足"},{"n": "料酒","q": "20ml","a": "20ml 泡水后抓洗去腥；加到 40ml 酒味重，减到 8ml 腥味压不住"},{"n": "生抽","q": "15ml","a": "15ml 咸鲜基础；加到 25ml 偏咸，减到 8ml 味道淡"},{"n": "醋","q": "10ml","a": "10ml 提香解腥；加到 20ml 酸得压住肝味，减到 0 少那股提味"},{"n": "淀粉","q": "10g","a": "10g 与蛋清上浆；加到 20g 浆厚、炒时发黏，减到 5g 锁水不足"},{"n": "食用油","q": "500ml（滑油用）","a": "500ml 宽油能滑开肝片；油少要分批滑、否则粘锅，减到 250ml 肝片挤在一起出水"},{"n": "盐","q": "3g","a": "3g 出锅前补味；加到 8g 咸苦，减到 1g 略欠"}],"steps": ["猪肝切2mm薄片，放清水中浸泡30分钟，中途换水2次至水色清亮，捞出沥干用料酒抓匀去腥；泡水去腥是这道菜的关键，不泡会有铁锈味。","肝片加蛋清和淀粉抓匀腌10分钟至发黏，蛋清上浆锁住水分，滑油后才嫩到发颤。","锅烧热加宽油至五成热（约150至160℃），下肝片用筷子快速划散，滑炒40秒至刚变色发灰立刻捞出，时间一长就老；捞出后倒掉油留一层底油。","锅留底油下蒜片和青椒块转大火炒20秒，加木耳丝。","倒入滑好的肝片，烹生抽和醋，大火翻炒10秒。","淋淀粉水勾薄芡，熘肝尖只要薄薄一层芡、不必厚芡。","加盐翻匀立刻出锅，肝片断生带一点嫩粉红色最佳。"],"key": "肝片泡水30分钟去腥、蛋清上浆、油温五成滑40秒即出，三步缺一就是咬不动加腥。","tip": "判断油温用筷子插进去周围冒小泡，约150℃；油温过高肝片表面立刻熟透发硬。"},"干炸丸子": {"time": "45分钟","level": "中等","servings": "3-4人份","ing": [{"n": "猪肉馅（肥瘦3:7）","q": "350g","a": "350g 做12个丸子正好；加到 500g 要延长摔打时间否则丸子不成形，减到 250g 一人只能分到四五个"},{"n": "葱末","q": "40g","a": "40g 打进肉馅增香；加到 70g 炸后葱味发苦，减到 20g 香不足"},{"n": "姜末","q": "10g","a": "10g 去肉腥提香；加到 20g 姜味抢戏，减到 3g 腥气明显"},{"n": "鸡蛋","q": "1个","a": "1个蛋液让丸子内里松软；加到 2 个丸子偏软易散，减到半个口感发柴"},{"n": "淀粉","q": "20g","a": "20g 是肉馅总量的6%左右，炸出外酥内嫩；加到 40g 丸子壳硬发死，减到 8g 粘不住易散"},{"n": "花椒粉","q": "3g","a": "3g 打在肉馅里；加到 8g 麻得发木，减到 1g 香气不足"},{"n": "盐","q": "4g","a": "4g 调馅；加到 8g 过咸，减到 2g 淡而无味"},{"n": "料酒","q": "15ml","a": "15ml 去腥并让肉馅更滑；加到 30ml 酒味重，减到 5ml 腥气残留"},{"n": "食用油（炸制）","q": "800ml","a": "800ml 够分两次炸；油少要分锅、油温反复下降影响定型，减到 400ml 丸子泡不全、外壳颜色不匀"},{"n": "椒盐","q": "5g","a": "5g 出锅撒食；加到 12g 咸得抢味，减到 2g 蘸料味不足"}],"steps": ["肉馅加葱末、姜末、料酒、盐、花椒粉，顺一个方向搅打3分钟至上劲，摔打上劲丸子才不散。","加鸡蛋和淀粉继续搅匀，摔打10分钟至肉馅发黏、盆光手光。","手蘸水，把肉馅团成直径3cm的丸子约12个，团紧不留缝隙。","油温五成热（约160℃）下丸子，用勺子沿锅边轻推，炸5分钟至丸子浮起、外皮硬挺发黄，定型阶段火不能大，皮急熟会裂。","捞出升高油温到八成热（约190℃），复炸2分钟至外壳金黄酥脆，捞出控油，复炸是外酥的关键。","撒椒盐5g颠匀，即成。"],"key": "肉馅要摔打上劲丸子才不散；先中温定型再高温复炸，两个油温缺一不可，只炸一次外壳会软。","tip": "肉馅里加15ml淀粉水打进去丸子更嫩；喜欢脆感可加荸荠碎或藕末。"},"爆炒腰花": {"time": "30分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "猪腰","q": "2个约400g","a": "400g 去净腰臊后正片；加到 600g 要分锅爆炒、否则腰花出水变老，减到 250g 一人吃不到几片"},{"n": "蒜苗（青蒜）","q": "150g","a": "150g 切段配腰花；加到 250g 抢味，减到 80g 少了那口蒜香"},{"n": "泡椒（剁碎）","q": "30g","a": "30g 是川鲁做法里的提味点；加到 60g 辣得压住腰花的脆，减到 10g 鲜辣不足"},{"n": "干辣椒","q": "3个","a": "3个剪段；加到 6 个干辣味重，减到 1 个只有颜色"},{"n": "姜末","q": "10g","a": "10g 去腰臊腥；加到 20g 姜味抢戏，减到 3g 腥气明显"},{"n": "料酒","q": "20ml","a": "20ml 泡水后抓腌去臊；加到 40ml 酒味重，减到 8ml 去腥力弱"},{"n": "生抽","q": "15ml","a": "15ml 上色提鲜；加到 25ml 咸味偏重，减到 8ml 味薄"},{"n": "醋","q": "8ml","a": "8ml 烹锅提香；加到 20ml 腰花发酸发柴，减到 0 少那口提味"},{"n": "干淀粉","q": "10g","a": "10g 抓匀挂薄浆、锁住腰花水分；加到 20g 浆厚、腰花不回弹，减到 5g 口感发干"},{"n": "食用油","q": "500ml","a": "500ml 宽油爆腰花；油少会粘锅、腰花出水，减到 250ml 锅温上不去"},{"n": "盐","q": "3g","a": "3g 出锅补味；加到 8g 过咸，减到 1g 略欠"}],"steps": ["猪腰撕净表面白色筋膜，从中间剖成两片，剔掉中间的腰臊，臊不剔干净会腥。","在腰片正面打十字花刀：斜刀每隔0.5cm切一刀、深至腰片厚度的三分之二不切断，再直刀交叉切一遍，切成麦穗花刀，花刀决定腰花能否卷出花纹，切到底会散。","花刀腰片用清水浸泡20分钟去血水，捞出沥干，加料酒、淀粉抓匀腌10分钟。","锅烧宽油至七成热（约200℃），下腰花用手勺快速划散，炸20至25秒至腰花打卷成花、边缘发白立刻捞出控油，火大或时间过腰花都会老。","锅留底油，下干辣椒、泡椒末、姜末转小火炒1分钟出红油香。","转大火倒入腰花，快速翻炒20秒，烹生抽和醋。","下蒜苗段转大火炒15秒，加盐翻匀出锅，腰花中心断生带一点粉红最佳。"],"key": "打花刀深至三分之二且不能切断、油温七成炸25秒即出卷，这两步决定腰花是脆嫩弹牙还是老硬橡皮。","tip": "没有泡椒可用剁椒20g代替，南方做法更辣；腰花要现切现炒，久放失水变干。"},"锅塌豆腐": {"time": "30分钟","level": "中等","servings": "3人份","ing": [{"n": "北豆腐（老豆腐）","q": "400g","a": "400g 切1.5cm厚片；用嫩豆腐400g煎即散，减到 250g 一人两块不够吃"},{"n": "鸡蛋","q": "1个","a": "1个蛋液裹外壳；加到 2 个壳厚发硬，减到半个壳薄不上色"},{"n": "干面粉","q": "30g","a": "30g 打底防粘、让蛋液挂住；加到 60g 壳厚发死，减到 10g 易破"},{"n": "蒜末","q": "15g","a": "15g 是锅塌豆腐的香气核心；加到 30g 蒜味冲，减到 5g 香不足"},{"n": "蚝油","q": "20g","a": "20g 提鲜增稠；加到 40g 蚝味腥重，减到 8g 鲜味不足"},{"n": "生抽","q": "15ml","a": "15ml 上色；加到 25ml 咸味偏重，减到 8ml 色淡"},{"n": "糖","q": "8g","a": "8g 提鲜回甘；加到 20g 甜得抢味，减到 3g 略欠"},{"n": "高汤","q": "200ml","a": "200ml 焖出味；加到 400ml 味淡、芡难挂住，减到 100ml 味浓但芡易发稠"},{"n": "水淀粉","q": "30ml","a": "30ml 勾成能挂住豆腐的芡；加到 60ml 芡厚如糊，减到 15ml 芡薄挂不住"},{"n": "食用油","q": "40ml","a": "40ml 煎豆腐不粘；加到 80ml 底部积油、豆腐发腻，减到 20ml 易粘锅"}],"steps": ["豆腐切1.5cm厚片，用厨房纸吸干表面水，不吸干煎时溅油且挂不住粉。","豆腐片先蘸干面粉，再裹一层蛋液，面粉打底让蛋液挂住、煎出金黄壳。","锅中放油烧至五成热，平码下豆腐片，中小火煎3分钟至底面金黄。","用锅铲小心翻面，再煎2分钟至两面金黄、豆腐被煎塌变软，这一步才叫锅塌。","锅中留底油下蒜末炒香，加蚝油、生抽、糖和200ml高汤烧开。","汤汁浇在豆腐上，加盖小火焖3分钟让豆腐吸味，不焖的话汁挂不进去。","开盖淋水淀粉勾芡，芡汁浓稠裹住豆腐，淋明油出锅。"],"key": "锅塌是两段功夫：先煎到两面金黄变塌，再加汤焖3分钟让豆腐吸味，最后勾芡挂汁，少了焖这一步就只是香煎豆腐。","tip": "必须用北豆腐才煎得住不出水；喜欢甜口糖加到12g、蚝油减到10g。"},"单县羊肉汤": {"time": "5小时","level": "稍难","servings": "4人份","ing": [{"n": "羊骨（羊腿骨、羊排）","q": "1000g","a": "1000g 配2500ml水熬出来汤才浓白；加到 1.5kg 要延长熬煮时间、汤过浓反而发腻，减到 500g 汤味淡薄"},{"n": "羊肉片","q": "300g","a": "300g 切薄片在汤里烫熟；加到 500g 需另加汤底，减到 200g 一人分不到几片"},{"n": "羊杂","q": "200g","a": "200g 切丝垫碗底；加到 350g 杂味盖过羊汤，减到 100g 碗底太空"},{"n": "姜片","q": "60g","a": "60g 熬汤去膻；加到 100g 姜味过重、羊香被遮，减到 30g 膻味压不住"},{"n": "葱白","q": "100g","a": "100g 切段入汤；加到 200g 葱味太冲，减到 50g 不够清甜"},{"n": "白胡椒粉","q": "10g","a": "10g 是羊汤的灵魂，散在碗里随汤冲开；加到 20g 辣喉抢味，减到 4g 胡椒香不足"},{"n": "盐","q": "15g","a": "15g 分两次，熬汤时一次、碗底一次；加到 25g 过咸，减到 8g 汤味太淡"},{"n": "辣椒油","q": "30ml","a": "30ml 撒面；加到 60ml 辣得盖过羊鲜，减到 10ml 没辣味"},{"n": "香菜","q": "20g","a": "20g 撒碗；加到 40g 抢味，减到 5g 香气不足"},{"n": "香醋","q": "15ml","a": "15ml 桌上自调；加到 30ml 太酸减了羊汤的鲜，减到 0 少一个吃法"}],"steps": ["羊骨斩块冷水下锅，水烧开撇净血沫，捞出用温水冲洗干净，冲不净汤就不白。","锅中加水2500ml，放入羊骨、羊杂、姜片、葱白，大火烧开。","保持大火滚20至30分钟至汤色发白、浮沫翻花，滚汤是奶白的关键，靠脂肪乳化，小火慢熬汤不白，此为第一段火。","转中火煮40分钟至骨肉分离，此为第二段火，中火出味。","转小火再熬1小时使汤味醇厚、骨头里的胶质析出，此为第三段火，小火养味；三段火候缺一不可。","捞出羊骨，剔下羊肉切极薄片，羊杂切丝。","碗中先放盐和白胡椒粉，舀滚烫羊汤冲开，盐和胡椒不能久煮否则香味跑掉。","放入羊肉片和羊杂烫熟，撒香菜，淋辣椒油，醋另备。"],"key": "汤要白必须大火滚出乳白，再中火、小火养味；三段火不能省。盐和白胡椒粉一定最后撒进碗里冲汤，久煮会失去鲜辣香。","tip": "汤一次多炖些冷冻保存，次日回锅烧开再放盐和胡椒；膻味重可用纱布包花椒和豆蔻同煮，去膻不减香。"},"油旋": {"time": "2.5小时","level": "稍难","servings": "4人份","ing": [{"n": "中筋面粉","q": "300g","a": "300g 做8个油旋；加到 400g 需相应多加油酥，减到 200g 8个做不出来"},{"n": "温水","q": "150ml","a": "150ml 和成半发面；加到 175ml 面软塌、卷时容易破，减到 130ml 面硬起层差"},{"n": "酵母","q": "3g","a": "3g 发到1.5倍正好；加到 6g 发过头层次乱、卷后易断，减到 1g 发不起来"},{"n": "猪油或植物油（油酥）","q": "60g","a": "60g 抹匀才能起层；加到 100g 太油腻，减到 30g 层次分不开"},{"n": "葱花","q": "50g","a": "50g 撒在油酥上；加到 80g 葱味发苦、烤后发黑，减到 25g 香不足"},{"n": "盐","q": "6g","a": "6g 调味；加到 12g 齁咸，减到 3g 淡"},{"n": "花椒粉","q": "3g","a": "3g 增香；加到 8g 麻得舌头发木，减到 1g 看不出"},{"n": "鸡蛋液","q": "1个","a": "1个刷表面颜色金黄；加到 2 个壳色过深，减到半个不上色"},{"n": "食用油（煎或烤用）","q": "30ml","a": "30ml 煎时刷锅防粘；加到 60ml 底部积油发腻，减到 15ml 易粘锅"}],"steps": ["面粉加酵母和温水揉成软面团，盖盖发酵40分钟至1.5倍大，发得太狠层次会乱。","面团擀成大薄片，抹上40g猪油，油酥要抹匀，卷起时才起层。","撒葱花、盐、花椒粉。","从一边卷成长条，再盘成螺旋形，这就是旋的形状，收口捏紧。","静置10分钟后用手压扁成约10cm的圆饼，层次会撑开变厚。","案板或饼铛刷油，放入油旋，表面刷一层蛋液。","烤箱200℃预热，烤15分钟至表面金黄、层次微微散开，层次散开才是起层成功；也可平底锅刷油中小火煎12分钟。","趁热掰开看层次，拉丝成片即成，夹烧饼加辣椒酱吃。"],"key": "层次全靠抹油酥加撒葱花椒盐加卷起盘成螺旋加压扁这四步，油酥不匀或卷得松就前功尽弃；烤到层次自然张开才算成功。","tip": "油旋放凉后回烤2分钟会更酥，夹烧饼吃最地道。"},"甜沫": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "小米","q": "100g","a": "100g 配1200ml水熬成米糊；加到 150g 糊太稠挂勺，减到 70g 粥味淡薄"},{"n": "清水","q": "1300ml","a": "1200ml 熬粥、100ml 调面糊；加到 1600ml 糊太稀挂不住料，减到 1100ml 糊如米油太厚"},{"n": "面筋","q": "100g","a": "100g 切块；用现成的省事但手洗面筋更地道，加到 150g 料太满，减到 50g 少了嚼感"},{"n": "粉条","q": "30g","a": "30g 泡软下锅；加到 60g 粉味压过米香，减到 15g 不成形"},{"n": "豆皮","q": "40g","a": "40g 切丝；加到 70g 豆皮味重，减到 20g 配料不足"},{"n": "花生米","q": "30g","a": "30g 炒香压碎；加到 50g 抢香，减到 15g 口感单薄"},{"n": "芝麻","q": "10g","a": "10g 炒熟撒面；加到 20g 香得盖过米香，减到 3g 看不出"},{"n": "姜末","q": "10g","a": "10g 是甜沫的姜味；加到 20g 辣姜抢戏，减到 3g 只剩糊味"},{"n": "盐","q": "5g","a": "5g 甜沫是咸口不是甜口，靠盐出味；加到 10g 过咸，减到 2g 没味道"},{"n": "食用油","q": "20ml（炒芝麻花生）","a": "20ml 炒配料；加到 40ml 芝麻花生过香，减到 10ml 炒不出香"}],"steps": ["小米淘洗干净，冷水下锅大火烧开转小火熬25分钟至米油浮起、米汤浓稠，熬到米油出现才算够火候。","舀出一半米汤备用，甜沫的稠度靠回头兑米汤调，全靠米汤才稠而不澥。","另起锅加100ml清水和面粉调成稀面糊备用，这就是洗面水：面粉加清水揉成面团，反复洗面，洗面出的筋就是面筋，带粉的洗面水就是糊。","锅中水开下面筋块和粉条煮3分钟至粉条透明。","加豆皮丝和花生米煮2分钟。","兑入面糊并淋入米汤，边淋边搅，加姜末10g、盐5g，小火熬3分钟至稠而能挂勺。","撒炒熟的芝麻，趁热喝，配油条或烧饼。"],"key": "甜沫的甜不是糖，是小米熬出的米油甜加咸鲜；面糊兑米汤来调稠度，全靠一个熬字。","tip": "熬不出米油就用破壁机先打小米浆再煮；喜欢更稠可多留米汤少兑清水。"},"粘豆包": {"time": "3小时","level": "中等","servings": "4人份","ing": [{"n": "糯米粉","q": "250g","a": "250g 是做12个粘豆包的主料；加到 350g 皮太厚不好包，减到 180g 皮薄易破"},{"n": "红芸豆（豆沙）","q": "300g","a": "300g 煮熟打沙做馅；加到 400g 甜度偏重，减到 200g 馅薄包不满"},{"n": "开水","q": "220ml","a": "220ml 烫粉用，一半开水一半凉水和面；全用开水皮太软粘手，全用凉水皮硬不粘糯，减到 180ml 揉不开"},{"n": "白糖","q": "40g","a": "40g 调豆沙馅；加到 70g 甜得发腻，减到 20g 馅偏淡"},{"n": "玉米面（黏米粉）","q": "80g","a": "80g 掺进糯米粉增加粗粝口感；加到 150g 皮偏硬粘性下降，减到 30g 失去黏性"},{"n": "猪油","q": "20g","a": "20g 揉进面团更油润；加到 40g 皮发腻，减到 5g 口感偏干硬"},{"n": "红糖或黄豆粉（蘸食）","q": "30g","a": "30g 出锅蘸食；加到 60g 太甜，减到 10g 味道不足"},{"n": "酵母","q": "2g","a": "2g 微微发酵更软；加到 5g 粘豆包发起来就不粘了，减到 0 发硬但传统就是这样"}],"steps": ["红豆提前泡一夜，加水煮至软烂，加白糖40g用勺背压成细腻豆沙，晾凉后团成直径2cm的小球，冷冻1小时至硬，豆沙太软包的时候会漏。","糯米粉250g加玉米面80g，先浇一半开水110ml，边浇边搅成絮状，再加剩下110ml凉水和成能捏住不散的面团，加猪油20g揉到光滑。","取20g剂子压成圆片，包入一颗豆沙球，收口搓圆，压成厚圆饼。","蒸屉铺硅油纸或刷薄油，放上粘豆包，间隔2cm以免粘连。","冷水上锅大火蒸15分钟，关火焖2分钟再开盖，直接开盖表面会塌陷起皱。","出锅晾2分钟再吃，此时外皮不粘手、软糯拉丝，蘸红糖或黄豆粉食用。"],"key": "豆沙球必须冻硬才好包，粉皮要一半开水一半凉水和才够软糯；蒸好焖2分钟、开盖前不动，表面才不会塌。","tip": "减糖版可用零卡糖或减到10g；一次多蒸可生坯冷冻，蒸前回温5分钟。"},"肉火烧": {"time": "2.5小时","level": "稍难","servings": "4人份","ing": [{"n": "面粉","q": "400g","a": "400g 做10个肉火烧；加到 500g 需多加油酥，减到 300g 个头偏小"},{"n": "猪肉馅（半肥半瘦）","q": "300g","a": "300g 是潍坊肉火烧的肉量，一掰开满汁；加到 450g 馅太满烤时易漏，减到 200g 不够多汁"},{"n": "大葱","q": "150g","a": "150g 切末，葱白葱心混切香气足；加到 250g 馅发苦，减到 80g 葱香不够"},{"n": "温水","q": "220ml","a": "220ml 和成半发面；加到 250ml 面偏软塌，减到 200ml 难开酥皮"},{"n": "酵母","q": "4g","a": "4g 发到1.5倍，半发面才筋道不塌；加到 8g 发过头口感发软，减到 2g 发不动"},{"n": "猪油（油酥用）","q": "50g","a": "50g 抹酥层起层；加到 80g 太腻，减到 30g 层不出"},{"n": "盐","q": "5g","a": "5g 调馅；加到 10g 齁咸，减到 2g 淡"},{"n": "生抽","q": "15ml","a": "15ml 馅里提鲜；加到 25ml 馅偏咸，减到 8ml 味不足"},{"n": "花椒粉","q": "2g","a": "2g 增香；加到 6g 麻得发木，减到 1g 香气淡"},{"n": "香油","q": "20ml","a": "20ml 拌馅封汁；加到 40ml 馅滑腻难成型，减到 8ml 汁流失"}],"steps": ["面粉加酵母和220ml温水揉成面团，盖盖发酵到1.5倍大，潍坊肉火烧用半发面，发太足口感发软不筋道。","面团擀开，抹上40g猪油撒少许盐，卷成长条再盘成螺旋饼坯，二次醒发30分钟至1.5倍，半发面加油酥层次才酥而不散。","猪肉切小丁加大葱末、盐、生抽、花椒粉，顺一个方向搅打上劲，淋香油拌匀。","取饼坯擀开，把肉馅均匀抹上，四边收口捏紧成长方形，肉馅要封在酥皮里，烤出来掰开才多汁。","烤盘刷油，肉火烧表面刷一层猪油或蛋液。","烤箱200℃预热，烤18至20分钟至表面金黄、边缘起酥。","翻面再烤3分钟让两面都上色，趁热吃，一掰开满汁。"],"key": "半发面加油酥加肉馅打水上劲并封口不漏汁，这三样是肉火烧酥而不柴的关键；收口捏紧否则一烤就漏汁。","tip": "喜欢多汁可把肉馅换成五花肉丁并加30ml清水打进去；冷吃也香，回炉3分钟更酥。"},"兰州牛肉面": {"time": "90分钟（牛汤可提前一天熬好）","level": "稍难","servings": "3-4人份","ing": [{"n": "牛棒骨（牛骨+牛肩骨）","q": "2kg","a": "用2kg牛骨、熬足3小时的汤冲4碗面，味最正；减到1kg汤色发清发薄，只能靠多放牛油和味精硬撑，失去'一清'；加到3kg则一锅炖不完、时间翻倍"},{"n": "牛腱子肉","q": "600g","a": "600g够4碗（每碗约150g）；加到800g要延后20分钟再切片，否则嚼不动；减到300g每碗只有2片，卖相就薄了"},{"n": "白萝卜","q": "1根约500g","a": "切2mm薄片焯水，是'三白'里的白；换成牛骨汤虽更香但就失了三白之一；加到2根汤会发甜抢味"},{"n": "红油辣子","q": "4勺（约60ml）","a": "兰州的'三红'是香而不燥的秦椒红油；加到6勺会盖住牛肉香、吃完全口是辣；减到2勺则只有颜色没有香气，正宗感不够"},{"n": "蒜苗","q": "3根","a": "切末，这是'四绿'；减到1根味道会寡淡；加到6根会抢生蒜的辛辣味"},{"n": "香菜","q": "1小把","a": "切段撒在面上提清香；不要整把倒下去，否则汤发浑浊发涩"},{"n": "拉面面剂子","q": "500g","a": "兰州标准是'三细'（最细），面剂子要提前擀成薄片冷藏；加到600g需多煮1分钟并多备一碗面汤，否则一碗面吃不完"},{"n": "陈醋","q": "2勺（约30ml）","a": "沿碗边点醋增香；加到4勺酸味会盖过肉汤；减到1勺几乎尝不出，这是兰州面馆的标准量"},{"n": "盐、味精、白胡椒粉","q": "盐4g、味精3g、白胡椒1g","a": "盐放多了牛肉汤的鲜就发苦；味精3g足以提鲜，加到6g会有化学味；白胡椒只用来压肉腥，多了发苦"}],"steps": ["牛骨冷水下锅焯3分钟，撇净血沫捞出冲净；另起锅不放油，将牛骨两面用小火干煎2分钟至表面微黄起香，倒热水没过骨头，大火滚开后转小火加盖熬3小时，中途只加热水不加冷水，汤色才奶白不灰。","牛肉冷水下锅，加姜片、料酒焯3分钟去血水，捞出切成1cm见方的薄片（热片带汁，凉片入汤不浑）。","白萝卜切2mm厚片，沸水焯1分钟至边缘透明、中心仍有一点硬芯，捞出沥干，焯透则去生辣味。","面条下滚水煮40秒至八成熟（中心还有一点白芯），捞进碗中并淋一勺面汤冲开面条，这样面不坨。","碗底放盐、味精、蒜苗和香菜，冲入大滚的牛骨汤激出香味，铺上牛肉片和萝卜片。","浇上4勺红油辣子，沿碗边点2勺陈醋，最后撒白胡椒粉，上桌前从碗底向上翻拌几下让料均匀挂汁。","整碗面必须在3分钟内吃完，面会吸汤变坨，红油也会由浮油变成死红。"],"key": "整碗的香气靠'滚汤冲开'——牛汤必须处于大滚状态一次冲入碗中才有'冲味'；面只煮八成熟靠余温在汤里熟透，这是兰州拉面'一清二白三红四绿五黄'以外最关键的一环。","tip": "家中可用牛骨+牛油+一小勺奶粉增白，但千万别用浓缩鸡精勾兑，汤一浑就彻底失去兰州清汤的魂；辣椒油必须自炼（菜籽油烧到六成热，分三次泼入秦椒面），外面买的只有辣没有香。"},"羊肉泡馍": {"time": "2小时（其中熬汤1.5小时）","level": "稍难","servings": "3-4人份","ing": [{"n": "羊腿肉或羊排","q": "1kg","a": "1kg够4碗（每碗约250g连汤）；加到1.5kg要延后炖煮20分钟，肉才酥而不柴；减到600g一人只有一小块，吃不出泡馍的满足感"},{"n": "羊骨（棒骨+脊骨）","q": "1kg","a": "羊骨出味比羊肉快，1kg配1kg肉刚好；减到500g汤不浓白；加到2kg汤要熬4小时且会非常油，必须撇净浮油"},{"n": "死面饼（托托馍）","q": "4个约500g","a": "必须是死面（无酵）硬饼，太软一掰就烂；加到6个需多备200ml汤，否则泡不透；减到3个则一人份不足"},{"n": "红薯粉丝","q": "100g","a": "提前用温水泡软，100g够4碗；加到200g汤会黏稠发坨；减到50g少了'滑'的口感"},{"n": "干木耳、干黄花菜","q": "木耳10g、黄花15g","a": "温水泡发后要焯1分钟去土味；加到木耳20g黄花30g抢了羊肉的鲜；黄花必须泡发，不泡发有碱味"},{"n": "糖醋蒜","q": "3勺（约45ml）","a": "蒜切末用香醋和糖泡2小时，酸甜开胃；加到5勺酸味盖住羊肉膻味；减到1勺则'酸'这一路全无"},{"n": "油泼辣椒/秦椒酱","q": "4勺（约60ml）","a": "陕西泡馍讲究'少油多辣'；加到6勺会夺走羊肉原香；减到2勺味道偏淡"},{"n": "香菜","q": "1小把","a": "切段撒面上；不加味道会厚重"},{"n": "盐、白胡椒粉","q": "盐5g、白胡椒1g","a": "盐放多了汤发苦、肉发紧；白胡椒只提香，多了发苦"}],"steps": ["羊骨和羊腿肉冷水下锅，加葱姜料酒，撇净浮沫后大火烧开，转小火加盖炖1.5小时，炖到筷子能轻松插透、汤色发白。","捞出羊肉晾凉后手撕成1.5cm宽的片（手撕比刀切更挂汤），骨头汤用纱网滤净血沫，撇掉表面那层黄油——汤不撇油会腻得吃不下。","馍撕成黄豆大小的碎块（必须是掰不是切），放进大碗里备用；这是泡馍与'羊肉汤泡整馍'的根本区别。","碗中码入粉丝、木耳、黄花菜，泡馍用的汤另烧一锅水。","锅中水开下馍丁，用中火煮2-3分钟，边煮边轻轻推动，标准是馍心用手一捏就烂但还成粒不散成糊。","把煮好的连汤带馍舀进碗里，和干料拌匀，使每块馍都吸足汤汁，再淋糖醋蒜和辣椒酱、撒香菜和白胡椒粉。","吃前从碗底翻起，让沉在底部的粉丝和馍与上面的料混匀，泡馍必须'汤馍分离'才算到位。"],"key": "馍必须自己掰成黄豆大小并用原汤煮透入味，泡馍不是把汤浇在整块馍上——手上力道要轻，一旦把馍揉成糊，整碗就毁了。","tip": "想吃'干拌'口感的'羊肉泡馍'就多煮30秒让馍吸干汤；喜欢'水城'口味就煮2分钟汤汁多一点。第一次吃建议糖醋蒜少放，先尝原味。"},"肉夹馍": {"time": "3小时（其中卤肉2.5小时）","level": "中等","servings": "4人份（6个馍）","ing": [{"n": "带皮五花肉","q": "1kg","a": "1kg可夹6个馍；加到1.5kg要延长炖煮40分钟，肥肉才化在嘴里；减到600g一人只剩两筷子肉，不够扎实"},{"n": "白吉馍（半发面圆饼）","q": "6个","a": "白吉馍是死面半发、外脆内软，不是甜馒头；换成普通馒头会有回甜味；每个约75g，加到8个需多备肉"},{"n": "菜籽油","q": "80ml","a": "用于炒糖色和煸肉；减到40ml炒糖色易糊锅发苦；加到150ml肉会油腻"},{"n": "冰糖","q": "30g","a": "炒成枣红糖色是'色亮'的关键；加到50g颜色发黑发甜；减到15g上色不足、肉色发暗"},{"n": "生抽、老抽","q": "生抽40ml、老抽10ml","a": "生抽提味老抽上色，老抽超过20ml会发黑发苦；生抽减到20ml则咸味不足需另加盐"},{"n": "香料包（八角2个、桂皮1段、草果1个、香叶3片、小茴香1小勺）","q": "1份","a": "香料过多会盖住肉香，八角加到4个会有明显药味；太少则不出'腊汁'的复合香"},{"n": "黄酒","q": "150ml","a": "去腥增香并软化肉质；加到300ml会盖住汤汁的酱香；减到50ml腥味去不掉"},{"n": "南乳（豆腐乳）1块 + 冰糖 + 盐","q": "南乳1块、盐3g","a": "南乳是腊汁肉发酵回香的关键，1块（10g）刚好；加到2块汤会发臭发酸；不要多"},{"n": "剁椒（腊汁肉专用辣椒）","q": "3勺（约45g）","a": "解腻提味；加到5勺会咸辣盖过肉香；减到1勺腊汁的'辣'就不足了"},{"n": "配菜与提味（焯好的青菜、香醋）","q": "青菜1棵、香醋1勺","a": "青菜夹在馍里解腻、增加脆感，香醋随肉入口去腻；青菜加到2棵会出涩味；醋加到3勺会酸掉腊汁的香"}],"steps": ["五花肉切2.5cm见方的块，冷水下锅加姜片料酒焯5分钟，撇净血沫捞出，用温水冲洗表面浮沫再擦干。","锅中放菜籽油，小火下冰糖慢慢炒，用铲子不停推动，炒到糖熔化变成枣红色并冒小泡；此时立刻倒入肉块，中火翻炒上色，糖色一旦过火就发苦。","加姜块、葱段和香料包炒1分钟出香，南乳用少量温水化开后倒入锅内翻匀，再烹入黄酒。","加生抽、老抽、盐和热水，水面刚好没过肉面1cm，大火烧开转小火加盖炖2.5小时，炖到筷子一戳就透。","开盖转中大火收汁，不停翻动让肉块均匀裹上浓汁，收到汤汁浓稠、能挂在肉上不流到锅底。","取肉连皮带骨一起剁碎（正宗是带皮剁，肥瘦相间保留颗粒，不能剁成肉泥），淋上卤汁的汤汁拌匀。","白吉馍用平底锅小火烙1-2分钟至两面微黄、外壳起酥（家庭版可烙，正宗凉吃时是外脆内软），从边上一刀开口不切底，塞入剁肉、3勺剁椒、青菜和1勺香醋。"],"key": "腊汁肉要'皮软肉烂、肥而不腻'，关键是收汁收到浓稠挂勺而不是泡在汤里，再剁碎时保留肥瘦颗粒——剁成肉泥就变成'烂肉夹馍'，失了'肥而不腻'的层次。","tip": "没有香料包也可用五香粉，但味道会单薄；剁肉时用刀背拍两下比机器绞更香。剩下的卤汁留着，下次夹馍更好吃。"},"凉皮": {"time": "4小时（沉淀需静置3小时）","level": "稍难","servings": "3-4人份","ing": [{"n": "中筋面粉","q": "500g","a": "500g面可做8-10张凉皮；加到700g需多蒸1锅水；减到300g则一人份量不够"},{"n": "和面清水","q": "260ml","a": "面粉与水约2:1偏干，硬面团才洗得出筋；加到320ml面太软会粘盆；减到220ml洗面时难以成型"},{"n": "洗面水（洗出的面筋另用）","q": "500ml","a": "反复洗面换水4-5次，直到面水变清亮；水量不足洗不干净会有碱味"},{"n": "食盐","q": "3g","a": "和面时加盐让面筋更筋道；加到8g凉皮会发苦"},{"n": "熟菜籽油","q": "2勺（约30ml）","a": "1勺刷蒸盘防粘，1勺兑进面浆让蒸出来的皮滑亮；不加则面皮发硬、粘连"},{"n": "辣椒油","q": "3勺（约45ml）","a": "陕西凉皮的灵魂；加到5勺会辣得盖住芝麻香；减到1勺只有颜色没有辣香"},{"n": "蒜水（蒜末加温水）","q": "3勺（约45ml）","a": "现捣蒜末冲温水才出味；用熟蒜水味道寡淡；加到5勺蒜味太冲"},{"n": "香醋","q": "2勺（约30ml）","a": "凉皮的酸主要来自醋；加到4勺会盖掉芝麻酱的香；减到1勺则'酸辣爽'只剩辣"},{"n": "芝麻酱","q": "1.5勺（约25g）","a": "用凉水澥开调稀；加到3勺会发齁盖住蒜味；减到半勺则香而不腻"},{"n": "黄瓜丝、香菜、熟白芝麻","q": "黄瓜1根、香菜1小把、芝麻1勺","a": "黄瓜切细丝提供脆感；香菜和芝麻是点缀，减半即可；不要加太多会抢味"}],"steps": ["面粉加盐和260ml清水揉成偏硬的面团，盖湿布静置10分钟让面筋松弛。","面团放在盆中加清水反复揉搓洗面，揉出的面筋另放碗里（可以做面筋泡），面水换清水继续洗，一共洗4-5次，直到面水清亮、盆底剩下一团硬面渣。","面水静置沉淀3小时，沉淀时间越久面浆越纯；倒掉上层清水不要搅动，底部的面浆浓稠能拉出细丝才对，若像稀米汤说明沉淀不够，还需再静置2小时。","面浆中加1勺熟油搅匀，静置10分钟让油浮到表面，蒸出来的皮才会透亮不粘。","蒸锅水烧开，蒸盘内壁刷一层熟油，倒入一层面浆并迅速转动蒸盘摊成3mm厚的圆片，大火蒸3-4分钟，看到面浆表面起大泡、边缘微微翘起即可取出。","摊开放凉2分钟，再一片片揭下切成2cm宽的条，卷起装盘——不摊凉就卷会粘连成块。","面上浇辣椒油、蒜水、香醋、澥开的芝麻酱，撒黄瓜丝、香菜和白芝麻，吃前从底部拌匀。"],"key": "面浆的浓稠度决定一切：能拉出细丝（类似酸奶稠度）才筋道，稀了蒸出来软塌如粉条；蒸好必须摊开晾透再卷，否则粘连撕破。","tip": "想省事可用买的凉皮，但自制洗面那步别省——洗出的面筋切片拌进凉皮里，就是西安'面筋凉皮'的完整吃法。"},"油泼面": {"time": "40分钟","level": "简单","servings": "2-3人份","ing": [{"n": "高筋面粉","q": "400g","a": "400g够3人份；加到500g需再醒面30分钟；减到300g则面条太少"},{"n": "清水（和面）","q": "215ml","a": "面粉与水约1.9:1，面要硬才扯得动；加到250ml面太软，一扯就断；减到200ml会干得拉不开"},{"n": "秦椒辣椒面","q": "3勺（约15g）","a": "必须是粗中细混合的秦椒面，油泼后香气才立体；加到5勺会辣到盖住面香；减到1勺激不出糊辣椒香"},{"n": "菜籽油","q": "80ml","a": "1碗面用80ml正好能泼透辣椒面；加到120ml会油腻拌不动；减到40ml泼不熟辣椒面，只出辣不出香"},{"n": "蒜末","q": "3瓣（约15g）","a": "蒜末要干水分，湿蒜遇热油会炸锅飞溅；加到6瓣会满嘴蒜味；减到1瓣不够香"},{"n": "葱花","q": "1小把（约15g）","a": "葱花同样要干；油温过高会焦黑发苦"},{"n": "香醋","q": "2勺（约30ml）","a": "沿碗边淋醋解辣；加到4勺酸过；减到1勺则油腻难以下咽"},{"n": "生抽","q": "2勺（约30ml）","a": "油泼后必须靠生抽提咸味；加到3勺偏咸"},{"n": "白芝麻","q": "1勺","a": "撒在辣椒面上一起泼香；减半影响不大"},{"n": "食盐","q": "2g","a": "和面时加盐让面条更筋道"}],"steps": ["面粉加盐和215ml清水揉成硬面团，抹一层油盖湿布醒30分钟。","面团擀成大薄片，表面抹油后叠起再醒10分钟，醒透的面才扯得又宽又不断；取一片用手揪住一头慢慢扯向另一头，扯成宽约3cm的长条。","锅里水完全烧开，下扯好的面条，中火煮2-3分钟至面条边缘发软、中心还有一点硬芯，捞出沥干水装碗。","面条表面撒3勺辣椒面、蒜末、葱花和白芝麻，务必干湿分离，沾了水的辣椒面遇热油会剧烈飞溅。","锅中烧热菜籽油，烧到冒青烟（约220℃、八成热），油面出现明显烟气即可。","油分两次泼在辣椒面上：先泼一半激出第一阵香，隔3秒再泼剩余的一半，听到'滋啦'声、辣椒面边缘变褐出香即成功。","趁热沿碗边淋2勺生抽和2勺香醋，从碗底向上快速翻拌20下让每根面挂上辣椒油，趁热吃。"],"key": "油温必须到八成热（约220℃）并分两次泼：一次泼完辣椒面会焦苦发黑，一次泼半激不出完整的糊香——'滋啦'声和腾起的白烟是判断成功的唯一标准。","tip": "怕辣可把辣椒面减到1勺，但油量不要减，油少了泼不熟辣椒面；宽面换成手擀面同理，重点是油温和分两次泼。"},"新疆大盘鸡": {"time": "1小时","level": "中等","servings": "3-4人份","ing": [{"n": "三黄鸡半只","q": "1.2kg","a": "1.2kg带骨鸡够3-4人；加到1.6kg要延长焖煮15分钟；减到800g则不够4人分。带骨比净肉更有嚼劲，这是新疆做法"},{"n": "土豆","q": "3个约600g","a": "土豆是盘底的另一半主角，选黄心的沙瓤土豆；加到5个会抢走鸡肉味；减到2个则拌面时没有汤汁土豆泥"},{"n": "青椒","q": "3个（约200g）","a": "最后放的'配色配辣'，用薄皮螺丝椒；加到6个会发苦发涩；减到1个则失去清香"},{"n": "洋葱","q": "半个（约150g）","a": "块状下锅增甜；切丝炒久会发甜发软"},{"n": "干辣椒与花椒","q": "干辣椒8个、花椒10粒","a": "8个中干辣椒足够出香不燥；加到15个整锅发苦；减到4个则不够正宗"},{"n": "复合香料（姜5片、蒜4瓣、大料2个、桂皮1段、小茴香1小勺）","q": "1份","a": "香料是新疆风味的底子；大料加到4个会药味重；少了姜蒜则香气单薄"},{"n": "生抽、老抽、冰糖","q": "生抽2勺、老抽1勺、冰糖15g","a": "老抽1勺刚好上色；加到2勺酱色过深发苦；冰糖15g收汁后是咸甜口，加到30g会齁"},{"n": "菜籽油","q": "60ml","a": "煸鸡时用油量足才能出香；减到20ml鸡肉发柴；加到100ml整盘油汪汪"},{"n": "皮带面（宽面）","q": "300g","a": "皮带面要宽约2cm，300g铺满大盘底；加到450g会盖住汤汁；减到200g拌面时不够分"},{"n": "清水与盐","q": "清水500ml、盐5g","a": "水刚好没过鸡块，多了汤稀；盐分两次（焖时3g、起锅前2g），一次加够易过咸"}],"steps": ["鸡斩成3cm见方的块，冷水浸泡20分钟去净血水，沥干后用厨房纸吸干表面水。","锅中放菜籽油烧至五成热（约170℃、油面冒细泡），下鸡块中火煸炒8分钟，煸到表皮焦黄、锅底积起一层金黄的鸡油，鸡的腥味靠这一步逼出来。","加姜片、蒜瓣、大料、桂皮、小茴香、干辣椒和花椒，中火炒2分钟炒出红油，下洋葱块炒软出甜味。","加生抽、老抽和冰糖翻匀，倒入500ml清水，量以刚没过鸡块为准，大火烧开转中小火加盖焖25分钟，焖到筷子能插透。","土豆去皮切滚刀块，用少许汤汁先煸1分钟再倒回锅中，加盖继续焖12分钟，标准是土豆边缘起沙、汤汁自然收稠。","加青椒块转大火翻炒2分钟，青椒边缘微微起皱即断生，加盐调味，翻匀后连汤带菜盛入大盘。","皮带面另锅煮3分钟至八成熟，捞出沥干铺在大盘底部，把鸡块、土豆、青椒连同浓汤汁一起浇在面上，吃时从底部拌开，让面条吸满汤汁。"],"key": "土豆必须在鸡焖到半熟时后放，早下锅会被炖成泥、汤也会发糊；皮带面是垫在盘底吸汤的独立一层，不能提前拌进锅里，否则汤汁会被面吸干。","tip": "没有皮带面可用手擀宽面；汤汁拌面的灵魂是'油'，所以煸鸡时那层锅底鸡油千万别倒掉。"},"烤羊肉串": {"time": "50分钟（腌制30分钟）","level": "简单","servings": "3-4人份","ing": [{"n": "羊后腿肉","q": "800g","a": "选肥瘦相间的后腿或上脑肉，800g可串约20串；加到1.2kg需延长腌制时间且吃不完；减到500g一人只有3串不过瘾"},{"n": "红柳枝","q": "10根","a": "红柳枝自带草木清香，是新疆烤串区别于其他烤肉的关键；换成普通竹签只有炭火味；用签前把树枝削皮刮净"},{"n": "洋葱","q": "1个","a": "切丝腌肉去膻提甜；加到2个会盖住羊肉味；不用洋葱则需多放孜然压味"},{"n": "孜然粒（孜然粉）","q": "3勺（约12g）","a": "颗粒孜然比粉更有香气层次；加到5勺会发苦有草腥；减到1勺只有辣味没有西域香"},{"n": "辣椒面（伊犁椒/朝天椒面）","q": "2勺（约8g）","a": "2勺是微辣基准；加到4勺后味会发苦；减到1勺对不吃辣的人刚好"},{"n": "食盐","q": "8g","a": "撒在肉上，8g配800g肉约1%；加到15g肉会发咸发紧"},{"n": "白胡椒粉","q": "2g","a": "压膻提香；多了发苦"},{"n": "食用油","q": "2勺（约30ml）","a": "腌肉时加一点油让肉不粘串、边缘更焦；加到5勺会滴油起明火"},{"n": "鸡蛋清","q": "1个","a": "腌料里加蛋清让肉更嫩更挂味；不用也可以但口感略柴"},{"n": "孜然粉（烤制时补撒）","q": "1勺","a": "最后两分钟再撒一次提表层香；提前撒会被烤糊"}],"steps": ["羊后腿肉逆着纹理切成2cm见方的块，用刀背轻拍松（断筋后更嫩），装入大盆。","加洋葱丝、8g盐、2g白胡椒、3勺孜然、2勺辣椒面、30ml油和1个蛋清，抓匀后腌30分钟，室温即可，不要腌过夜否则肉发酸。","串肉时肥瘦相间串，块与块之间留出约1cm缝隙不能挤紧，挤太紧热量传不进去，中间会夹生。","炭火烧到没有明火、灰层下呈暗红色时架上肉串，串距火约20cm，先烤肉的平坦面2分钟。","不断翻面，共烤8-10分钟，油脂滴落引起明火时立刻把串挪开；靠近火源的一面更要勤翻，否则外焦里生。","烤到外层有薄薄焦壳、中心还带一丝粉红时出架，最后两分钟撒剩余孜然粉和辣椒面，盐粒此时撒最香。"],"key": "孜然和辣椒面必须在最后两分钟撒，提前下锅会被明火烤糊发苦；火力以'灰下暗红、无明火'为佳，火太旺外焦里生、油脂滴落还会引发窜火。","tip": "没有炭火可用烤箱200℃上下火烤12分钟，中途翻面；红柳枝提前用刀刮净外皮泡水1小时，烤出来才有那股柳木香。"},"手抓饭": {"time": "1小时","level": "中等","servings": "3-4人份","ing": [{"n": "羊排（带骨）","q": "800g","a": "800g够4人；加到1.2kg要延长焖煮15分钟；减到500g则一人份太薄，缺了'抓'的满足"},{"n": "大米（长粒米）","q": "500g","a": "500g配800g羊肉约1:1.6；用长粒米才粒粒分明；加到600g需要按比例多加水否则焖不熟"},{"n": "胡萝卜","q": "2根（约400g）","a": "切成粗条或滚刀块，焖到发软带甜；切丝会太碎失去口感"},{"n": "黄萝卜（皮牙子）","q": "1根（约150g）","a": "新疆特有的黄萝卜，皮脆心实、甜中带香；加到3根会抢掉羊肉膻味以外的全部味道"},{"n": "洋葱","q": "1个（约200g）","a": "切丝用油煸软打底；切末炒过会发苦"},{"n": "葡萄干","q": "50g","a": "新疆抓饭的灵魂点缀，提供微甜和果香；加到150g会过甜像甜饭"},{"n": "菜籽油或羊油","q": "60ml","a": "煸羊肉用羊油最香，没有可用菜籽油；减到20ml羊肉煸不出层、油脂不进饭"},{"n": "盐","q": "8g","a": "分两次加，煸肉时4g、焖饭前4g；一次加够米会咸且发硬"},{"n": "黑胡椒","q": "2g","a": "配羊骨提香；多了发苦"},{"n": "清水","q": "550ml（约1:1.1）","a": "水量只比米面高一点点，蒸汽循环才让米饭分明；加到700ml会成稀饭；减到450ml中间夹生"}],"steps": ["羊排剁成5cm见方的块，冷水下锅焯5分钟，撇净血沫后捞出擦干。","锅中放60ml油烧至六成热，下羊排中火煸炒8分钟，煸到表面焦黄、锅底积油，羊膻味随着水分炒干就淡了。","加洋葱丝炒3分钟至透明发甜，再下胡萝卜条和黄萝卜块翻炒2分钟，加4g盐和黑胡椒炒匀。","大米淘净后沥干，均匀铺在羊肉和蔬菜之上（米在上、肉在下，这样蒸汽自下而上循环，米粒才能颗颗分明），沿锅边缓缓淋入550ml清水，水面与米面基本持平。","撒葡萄干，锅口封一层刷油的油纸或扣上一个大盘压严，先大火煮开约5分钟，转最小火焖25分钟。","关火不开盖，继续焖10分钟让余温把米饭焖透；开盖后用筷子从底部向上把米饭松动，盛出时先将羊肉胡萝卜铺在盘底，再把米饭盖在上面。"],"key": "米必须铺在羊肉之上、水量只比米面高一点点，蒸汽自下而上循环才能让米饭粒粒分明；焖好后必须再关火焖10分钟才开盖，否则上层米芯夹生、羊肉也不酥。","tip": "用厚底铸铁锅或电饭煲（煮饭键）都可；没有羊排可用带骨羊腿或羊肩肉，羊腿要炖更久才脱骨。"},"过桥米线": {"time": "40分钟（汤需提前熬）","level": "中等","servings": "3-4人份","ing": [{"n": "云南米线（干米线）","q": "300g","a": "干米线需温水泡20分钟，300g够4碗；加到450g要延长泡发时间；减到200g则一人份不足"},{"n": "奶白高汤（鸡架+猪筒骨+火腿熬6小时）","q": "1500ml","a": "汤是过桥米线的灵魂，必须滚开；1.5L够4碗并留出烫料的水；减到1L则烫料时会掉温，生料不熟"},{"n": "猪里脊薄片","q": "150g","a": "切得越薄越好，滚汤里15秒即熟；加到250g则需多烫一会儿"},{"n": "鸡肉片","q": "150g","a": "鸡胸切薄片；用鸡腿肉更嫩但要久烫；与里脊二选一也行"},{"n": "鹌鹑蛋","q": "6个","a": "提前煮好去壳；加到10个要增加烫煮时间；生蛋要煮2分钟"},{"n": "豆腐皮（响铃皮）","q": "80g","a": "切宽条吸汤；加到150g会盖住汤味；减到40g少了一味"},{"n": "韭菜","q": "1把（约150g）","a": "掐成5cm段最后放；加到300g会出草味；不用韭菜可用香菜"},{"n": "洋葱","q": "半个","a": "切薄片，是'黄'色配料；加到1个会抢生味"},{"n": "油泼辣椒","q": "2勺（约30ml）","a": "一定最后放、放在肉片上，油遇生肉发出滋啦声就是仪式；加到4勺会辣到盖过鸡汤"},{"n": "盐","q": "4g","a": "汤本身要淡，靠盐在配料烫好后微调"}],"steps": ["干米线用温水泡20分钟至能弯曲不断（凉米线也要泡软再用），泡好后用清水冲一遍防粘。","准备汤锅：把熬好的奶白高汤倒进锅里，用大火加热到完全滚开、汤面翻起拳头大的泡，这叫'滚汤'，是过桥米线能否成就的前提。","先下鹌鹑蛋煮2分钟捞出，再下豆腐皮煮1分钟。","下生肉片（里脊/鸡肉）在滚汤中烫15-20秒，筷子夹着在汤里摆动，颜色一变白立刻捞到漏勺里——绝不在汤里久煮，否则汤会浑。","米线放入另一口沸水锅中煮30秒至软（久煮会糊化在汤里，失去爽滑），捞出沥干放入大碗。","把滚烫的汤连同鹌鹑蛋、豆腐皮、肉片倒入碗中铺在米线上，放上韭菜和洋葱片。","油泼辣椒放在肉片正中间，上桌后由食客自己拌开——滚油接触滚汤和生料发出'滋啦'声，这就是过桥米线的仪式感。"],"key": "汤必须全程处于大滚状态，生料靠滚汤在几秒内熟透——这是云南'过桥'二字的含义；一旦汤温掉到90℃以下，生肉片和米线就会互相污染，汤会浑、肉会腥。","tip": "没有奶白高汤可用鸡架+干贝+虾皮熬2小时替代；肉片要在上桌前5秒内烫好，桌子上的锅务必保持沸腾状态。"},"汽锅鸡": {"time": "2.5小时","level": "简单","servings": "3-4人份","ing": [{"n": "建水紫陶汽锅","q": "1个（直径约25cm）","a": "必须是建水紫陶汽锅，靠蒸汽凝结成汤；用普通砂锅代替则需另外加水，味道完全不同"},{"n": "乌骨鸡（或土鸡）","q": "1只约1.1kg","a": "1.1kg够3-4人；加到1.5kg需延长蒸40分钟；减到800g蒸75分钟即可，但整鸡的香气不如1kg以上的"},{"n": "老姜","q": "1块（约80g）","a": "切厚片；加到半斤会辣得抢味；姜片少了腥气压不住"},{"n": "小葱","q": "2根","a": "打结或切段垫底；加到5根会蔫"},{"n": "盐","q": "8g","a": "汽锅鸡只放盐和胡椒；加到15g汤会发咸发紧；减到3g则鸡肉没味道"},{"n": "白胡椒粉","q": "1g","a": "提鲜去腥；多了发苦"},{"n": "料酒","q": "1勺（约15ml）","a": "腌鸡时去腥；汽锅内不宜放多，会夺走鸡的原味"},{"n": "干红枣3颗、枸杞5粒","q": "1小把","a": "蒸好前10分钟放枸杞，久蒸会烂成糊"},{"n": "鸡油或猪油","q": "1勺（约15ml）","a": "出锅前点在汤面上增香增滑；加到3勺会腻"}],"steps": ["鸡处理干净，剁成3cm见方的块，冷水浸泡20分钟去净血水，沥干后用厨房纸吸干表面水分。","汽锅用温水洗净（内壁的汽孔不用刻意刷洗，那正是凝结汤的通道），放入鸡块、姜片、葱结、料酒，不加一滴水。","在蒸锅或砂锅上架稳汽锅，锅里加足水，务必保证全程有充足的蒸汽供应，水不够汽锅就不凝汤。","大火烧开锅后转中火，蒸2小时（1kg左右的鸡需90-120分钟），中途不要开盖，开盖跑汽汤就不鲜了。","判断标准：鸡骨能轻松脱开、汤色清亮见底、鸡皮完整不烂，用筷子夹肉不散即熟透。","出锅后只加盐、白胡椒和鸡油，再撒枸杞和葱花，连汽锅一起端上桌。"],"key": "汽锅靠蒸汽冷凝成汤，全程不能加一滴水、不能中途开盖——加了就变成普通鸡汤，开盖跑汽则汤味全失。","tip": "没有汽锅可用带盖小砂锅隔水蒸（水浴法），但要先估算加水量；判断熟度用筷子戳鸡腿最厚处，能轻松穿透即够。"},"野生菌火锅": {"time": "2.5小时（汤底需提前熬）","level": "中等","servings": "3-4人份","ing": [{"n": "牛肝菌（干）","q": "30g","a": "干牛肝菌泡发后约150g，香味最浓；加到60g汤会过于厚重发苦；少于20g则失去'菌王'的风味"},{"n": "松茸（干）","q": "20g","a": "泡发后切薄片，20g足够提香；加到40g成本高且味道重叠；少于10g吃不出"},{"n": "鲜羊肚菌/青头菌","q": "300g","a": "当季鲜菌；加到500g则菌味盖过鸡汤；减到150g火锅寡淡"},{"n": "鸡架或老母鸡汤底","q": "1500ml","a": "野菌必须配鸡汤底才鲜；减到1L涮煮时汤温掉得快、菌不熟；加到2L味被冲淡"},{"n": "宣威火腿片","q": "100g","a": "云南火腿提咸鲜；加到200g汤会过咸；少于50g则缺了云南味"},{"n": "涮煮肉片（猪里脊或黄牛肉）","q": "200g","a": "切薄片滚汤一涮即熟；加到400g要分批涮；切太厚会有生肉味"},{"n": "白菜、豆腐","q": "白菜200g、豆腐150g","a": "用来吸菌汤；加量不减反而会稀释汤味"},{"n": "蒜片","q": "1头（约40g）","a": "野生菌的解毒搭档，整头拍散；加到2头会抢菌香"},{"n": "油泼辣椒/菌菇蘸水","q": "3勺（约45ml）","a": "蘸料用小米辣+蒜末+香油+醋；加到5勺会盖掉菌味"},{"n": "野生菌菇（干杂菌）","q": "50g","a": "牛肝菌、松茸之外的补充干货；泡发的水一定要沉淀后当汤底用，菌鲜味一半在水里"}],"steps": ["干菌用30℃温水泡30分钟，泡菌水倒出静置2小时沉淀，取上层清亮的菌水备用，沉淀底部的沙不要倒进锅里。","鲜菌用流水轻轻冲净表面泥沙即可，不要泡水（泡了会像吃烂菜）；牛肝菌必须顺着纹理撕开，检查有无虫蛀。","锅中倒1500ml鸡架汤加泡好的干菌和火腿片，大火烧开转小火煮30分钟，让干菌的鲜味彻底释放，撇净浮油。","涮煮顺序讲究：先下豆腐和白菜打底，再下肉片（滚汤一涮变色立刻捞出，久煮汤会浑），最后下鲜菌。","鲜菌下锅煮3-5分钟，羊肚菌、松茸、牛肝菌必须煮够5分钟以上确保彻底熟透，这是食用野生菌的安全底线。","蘸料碟里放蒜末、小米辣、生抽、香油和醋调成菌菇蘸水，菌汤也可直接舀着喝。","全程保持汤面沸腾，一边涮一边喝汤；菌类绝对不能生食或半生食用。"],"key": "野生菌必须彻底煮透（羊肚菌、牛肝菌、松茸都不少于5分钟），绝对不能生吃或半生食用；鲜菌不泡水、泡菌水要沉淀取清，这两条是云南吃菌的安全与鲜度关键。","tip": "不识菌千万别自行上山采买，只在正规市场选标明品种的菌；吃菌后如有任何不适，立即就医。不同菌不要同时下锅同煮，分开涮更容易判断口感。"},"鲜花饼": {"time": "2.5小时（面团松弛+发酵）","level": "稍难","servings": "8个","ing": [{"n": "食用玫瑰花酱","q": "250g","a": "必须是用可食用玫瑰做的酱，250g可包8个；加到350g收口容易露馅、烤时易溢；减到180g每个馅少会发空"},{"n": "低筋面粉（油皮）","q": "200g","a": "低筋起酥好；换成高筋则酥层会硬；加到250g油皮太厚包不住"},{"n": "中筋面粉（油酥）","q": "100g","a": "油酥用中筋才有层次酥感；用低筋会太散不成酥；加到150g则太干难搓"},{"n": "黄油（油酥用）","q": "60g","a": "黄油决定酥度，60g配100g粉约3:5；减到30g层次少、起酥差；加到90g会太腻易出油"},{"n": "猪油","q": "30g","a": "油皮用猪油香味最正宗（滇式用猪油+菜油）；用黄油替代则偏西式；减到10g皮会发硬"},{"n": "白糖","q": "40g","a": "油皮中的糖提供甜味和层次；加到60g过甜；减到20g则馅的甜味全靠玫瑰酱不够"},{"n": "奶粉","q": "20g","a": "增加奶香层次；不加也可，加到40g会偏甜"},{"n": "鸡蛋液","q": "1个（约50ml）","a": "1个刷表面烤出光亮的壳；用2个则皮更硬"},{"n": "食用玫瑰花瓣","q": "10g","a": "装饰用，可选；烤出的花瓣会变褐变透明，不影响口感"},{"n": "淡奶油（可选）","q": "10ml","a": "调花酱时加一点更细腻；不加直接用花酱也可以"}],"steps": ["油皮：低筋面粉200g加白糖、奶粉、鸡蛋液和猪油揉成团，揉到表面光滑不粘手，盖保鲜膜冷藏松弛30分钟。","油酥：中筋面粉100g加切碎的冷黄油，搓成均匀细沙状无颗粒的油酥团，冷藏20分钟备用。","取油皮团擀成方片，包上油酥团，收口捏紧，擀开卷起，再擀开卷起，共'擀卷两次'，盖保鲜膜松弛20分钟——层次就来自这两下。","玫瑰花酱加10ml淡奶油（或温水）调软，加糖拌匀，分成8份每份约30g。","松弛好的酥皮擀成圆片，包入一份花酱，捏紧收口朝下压扁成扁圆，放入烤盘。","表面刷一层蛋液，撒几片食用玫瑰花瓣，烤箱上下火190℃烤18-20分钟，表面金黄即可。","出炉后晾5分钟再吃，此时酥皮最酥；趁热吃黄油香重但层次稍软。"],"key": "酥皮的层次全靠'擀—卷—擀—卷'两次擀两次卷，少一次就完全不起酥；花酱要用食用玫瑰（观赏玫瑰有苦涩味），且收口必须捏紧朝下压，否则烤时会爆馅。","tip": "面团全程保持低温，黄油一旦化开就混酥了，层次就没了；烤箱一定要先预热到190℃再放进去。"},"热干面": {"time": "25分钟","level": "简单","servings": "2-3人份","ing": [{"n": "武汉碱水面","q": "400g","a": "必须是碱水面，用普通挂面替代则失去碱香和劲道；400g够3人；加到600g需多备2碗芝麻酱"},{"n": "芝麻酱（熟白芝麻自制最佳）","q": "60g","a": "用熟芝麻现场磨的最香；加到90g会齁住其他味；减到40g则香而不厚"},{"n": "凉白开（澥芝麻酱用）","q": "60-80ml","a": "必须分3-4次少量加，边加边搅，酱与水约3:1；一次倒太多会澥不开成疙瘩；用温水会使芝麻酱发死发苦"},{"n": "香油","q": "20ml","a": "芝麻酱的辅助提香；加到40ml会盖住芝麻本身的味道"},{"n": "生抽","q": "2勺（约30ml）","a": "武汉用的是偏咸的复制酱油；减到1勺会淡；加到3勺偏咸"},{"n": "萝卜丁（腌萝卜干）","q": "30g","a": "武汉早点必备的咸脆配料；加到60g会抢味发酸；少于10g少一绝"},{"n": "酸豆角（切末）","q": "30g","a": "酸脆解腻；不加则少一味但味道仍成立"},{"n": "葱花","q": "1小把（约20g）","a": "现切现撒；加到40g会有生葱的辛辣冲味"},{"n": "辣椒油","q": "2勺（约30ml）","a": "武汉热干面的红是自炼红油，色红不辣；加到4勺会辣得抢芝麻香"},{"n": "熟白芝麻","q": "1勺","a": "撒面点缀；用生芝麻会有苦味"}],"steps": ["芝麻酱装碗，用小勺分3-4次加凉白开，每次都顺同一个方向搅到完全澥开、酱体变稀能流动，这一步叫'打芝麻酱'，是最费功夫的环节。","澥好后加香油拌匀备用，芝麻酱必须提前弄，面煮好后再弄会来不及。","锅中水烧开，碱水面下锅煮2分钟至刚断生（中心还有一点硬芯），立刻捞出摊在大盘里用风扇或筷子快速吹凉、抖散。","面要煮到'八成熟'，靠碗里的余温焖到全熟；多煮10秒就软塌成坨，这是热干面最常见的失败。","趁面还热淋入芝麻酱、生抽、辣椒油，撒萝卜丁、酸豆角末、葱花和熟芝麻。","从盘底往上快速翻拌20下，让每根面均匀挂上芝麻酱，立即吃——放凉了芝麻酱会沉底结块。"],"key": "芝麻酱必须用凉白开一小勺一小勺地澥（酱:水约3:1），用温水会发死发苦；面只煮到八成熟、断生即出，靠余温在碗里焖软，这是热干面'筋而不糊'的关键。","tip": "自制芝麻酱最香：熟白芝麻用破壁机打细或用石磨磨，加1勺香油调稠度再澥；没有石磨就用料理机打30秒加几滴水，出来的香度差别很大。"},"清蒸武昌鱼": {"time": "30分钟","level": "简单","servings": "3人份","ing": [{"n": "武昌鱼","q": "1条约700g","a": "武昌鱼体薄肉嫩，700g够3人；加到900g需多蒸2分钟；减到500g则一条鱼3人吃太少"},{"n": "葱","q": "2根（约100g）","a": "一半垫盘底一半切丝铺面；切丝要细，长度与鱼身相当；不用葱用姜也可但香气少一截"},{"n": "老姜","q": "1块（约60g）","a": "切厚片和姜丝；姜丝塞进刀口里能让香气进入鱼肉"},{"n": "蒸鱼豉油","q": "3勺（约45ml）","a": "咸鲜提味；加到5勺会过咸；减到2勺则鱼味寡淡"},{"n": "食用油","q": "40ml","a": "必须是冒烟的热油激葱香；减到20ml激不熟葱丝会发蔫；加到60ml会腻"},{"n": "料酒","q": "1勺（约15ml）","a": "腌鱼去腥；加到3勺会盖住鱼肉的清甜"},{"n": "盐、白胡椒粉","q": "盐3g、白胡椒1g","a": "盐用来腌鱼和最后补味；白胡椒只一点点，多了发苦"},{"n": "红椒丝（装饰）","q": "2个（约30g）","a": "点缀用，可选；用现成的红椒圈颜色更亮"},{"n": "香菜","q": "1小把","a": "撒面提香，可选；不爱香菜就省掉"},{"n": "猪油（可选）","q": "1勺","a": "淋在葱丝上能让葱香更持久，湖北做法常见"}],"steps": ["武昌鱼去鳞去腮去内脏洗净，两面鱼身均匀剞斜刀，每边5-6刀，刀距约2cm、深至鱼骨，剞花刀是为了让蒸汽进入和入味。","用盐和白胡椒抹匀鱼身内外，抹匀鱼腹（腹内是腥味重的地方），腌10分钟去腥。","盘底铺葱段和姜片把鱼架空约2cm，鱼身再塞几片姜和葱段，刀口里也逐一塞进葱姜，这样香味能钻进刀口。","蒸锅的水完全烧开后，把鱼放入，大火蒸8分钟（700g鱼的标准时间），关火后不开盖再虚蒸2分钟。","取出鱼，倒掉盘里的汤汁——这盘水是腥味的来源，必须倒掉，再铺上新的葱丝和红椒丝，淋3勺蒸鱼豉油。","锅中烧40ml油至冒青烟（约200℃），趁热浇在葱丝上'刺啦'一声激出葱香，撒香菜立即上桌。"],"key": "必须水完全烧开后再上锅蒸、蒸好后盘里的水一定要倒掉（那是腥味的来源）；热油要烧到冒烟才浇在葱丝上，否则激不出那股清亮的葱香。","tip": "鱼身剞刀时垫一块砧板在下面更安全；判断蒸熟看鱼眼是否凸出变白、鱼肉能轻松脱骨，蒸过头肉就发柴了。"},"三鲜豆皮": {"time": "2小时（米浆摊皮耗时）","level": "稍难","servings": "3-4人份","ing": [{"n": "米浆（粳米磨浆）","q": "800ml","a": "摊豆皮用稀米浆，能挂住摊板即可；太稠摊不开会厚，太稀不成皮会漏浆；自制可用米浆加等量绿豆粉"},{"n": "绿豆粉","q": "80g","a": "与米浆按1:10掺和，豆皮才有'豆'味；加到150g皮发硬发苦；不用则只是米皮"},{"n": "糯米","q": "400g（干重）","a": "提前泡4小时以上至用手能捏碎；400g是铺满蒸屉的量；加到600g太厚不易熟；少于300g铺不满"},{"n": "鲜肉丁","q": "150g","a": "三鲜之一，肥瘦三七开；加到250g会腻"},{"n": "香菇丁","q": "80g","a": "三鲜之二；香菇要焯水去土腥；加到150g抢香"},{"n": "榨菜丁","q": "50g","a": "咸香配料；加到80g会过咸；少了这一味就不正宗"},{"n": "鸡蛋","q": "3个","a": "摊成蛋皮切丝盖顶，是武汉豆皮的标志；2个不够铺面，4个则盖得太厚"},{"n": "熟白芝麻","q": "1勺（约10g）","a": "撒面提香；不用也成立但少一绝"},{"n": "葱花","q": "1把","a": "撒面用；半把也可"},{"n": "生抽、盐、胡椒粉","q": "生抽2勺、盐4g、胡椒2g","a": "炒馅料时调味；盐多了配榨菜会咸；胡椒是提香的关键"}],"steps": ["糯米用冷水泡足4小时至能捏碎，沥干后上锅蒸20分钟至熟透（提前蒸好备用），这是豆皮'软糯'的基础。","平底锅烧至八成热（约170℃），锅面刷油，倒一勺米浆并迅速转匀成3mm厚的圆片，见边缘翘起、中间起大泡即取出，摊开放凉后切成2cm宽的长条——摊厚了就不是豆皮。","锅中下油，炒肉丁至变色出油，加香菇丁和榨菜丁炒2分钟，加生抽、盐和胡椒粉炒匀成馅料，晾凉备用。","蒸屉铺一层保鲜布或刷油，先铺一层摊好的豆皮条，再均匀铺上蒸好的糯米，铺馅料，最后盖一层豆皮条压平。","另用平底锅摊3张薄蛋皮（每张1个鸡蛋），晾凉后切丝，整齐铺在最上面。","撒葱花和熟白芝麻，蒸笼上汽后大火蒸10分钟，让所有味道融合。","出锅稍等2分钟，切成方块装盘，咬开时能拉出糯米丝、豆皮层和蛋皮的层次。"],"key": "豆皮要在平底锅上'一勺一滚'摊成薄圆皮，摊厚就成米粉皮；最上层的蛋皮丝和芝麻是判断正宗与否的标志，缺了这两样就不叫三鲜豆皮。","tip": "摊皮是整个工序最费时间的环节，一次多摊些冷藏可存3天，蒸之前回温即可；正宗武汉豆皮用铁锅摊，锅温更高、皮更薄。"},"东坡肉": {"time": "3小时（其中炖煮2小时）","level": "稍难","servings": "4人份","ing": [{"n": "带皮五花肉（一方整块）","q": "1kg","a": "1kg切4-5块正好；加到1.5kg需延长炖煮40分钟；减到600g一人一块不够，仪式感全无"},{"n": "绍兴黄酒","q": "500ml","a": "这是东坡肉的第一主料，500ml刚好没过肉面；一次加足中途绝不加清水；加到800ml肉会醉、味道发闷；减到300ml则酒香不足、肉仍有腥"},{"n": "冰糖","q": "50g","a": "小火炒成糖色给肉上色；加到80g收汁后发齁；减到30g色不红亮"},{"n": "生抽、老抽","q": "生抽3勺、老抽1勺","a": "老抽只用来上色，加到2勺会发黑发苦；生抽减到2勺则咸度不够需另加盐"},{"n": "老姜","q": "1块（约100g）","a": "切厚片，姜是黄酒炖肉去腥的关键；多了会辣"},{"n": "小葱","q": "3根","a": "打结垫底；加到6根会蔫烂"},{"n": "八角、桂皮","q": "八角1个、桂皮1段","a": "香料宜少不宜多，八角加到3个会有明显药味"},{"n": "清水","q": "400ml","a": "只在收汁阶段补一次水；加到700ml汤味被冲淡，收汁时间也翻倍"},{"n": "绍兴黄酒（蒸制时用）","q": "2勺","a": "最后蒸时再淋2勺酒提香；不加也成立，但香气少一层次"}],"steps": ["五花肉切5cm见方的块，冷水下锅加姜片和料酒焯5分钟，撇净血沫捞出，用温水冲洗掉浮沫再擦干。","锅中放少量油，小火下冰糖慢慢炒，不停推动至糖熔化变成枣红色并冒密集小泡，这一步叫'炒糖色'，火候一旦过就发苦。","立刻下肉块，中火翻炒让每块肉均匀裹上糖色，倒出多余的油（留少许即可），加姜块、葱结、八角和桂皮炒香。","烹入500ml黄酒，大火烧开转最小火加盖焖60分钟，让黄酒完全渗入肉纤维。","加生抽、老抽和400ml清水，转小火加盖再焖40分钟，标准是筷子能轻松插透肉皮但不散。","开盖转中大火收汁，边收边翻动并用勺子把浓汁反复淋在肉块上，收到汤汁浓稠拉丝挂住肉面。","肉块皮朝上码入碗中，浇上浓汁，上锅蒸20分钟让肉皮软糯酥而不碎，最后撒少许葱花。"],"key": "焖煮时黄酒必须一次加足（500ml），中途加清水会冲掉酒香；收汁后必须再上锅蒸20分钟——这一蒸才是东坡肉'酥而不碎、入口即化'的成色所在。","tip": "选'四方块'那种带皮五花，皮厚才能久炖不化；收汁时用勺子淋汁代替不停翻动，能减少肉块破碎。"},"西湖醋鱼": {"time": "50分钟","level": "稍难","servings": "3人份","ing": [{"n": "草鱼（活水鱼或西湖鱼）","q": "1条约750g","a": "750g够3人；加到1kg需多汆1分钟；减到600g则不够分。草鱼用清水养2小时去土腥（传统是饿养一两日）"},{"n": "镇江香醋","q": "80ml","a": "必须是镇江香醋，酸香有回味；加到120ml酸味盖住鱼香；减到50ml'醋鱼'就不成立了"},{"n": "白糖","q": "60g","a": "与醋成'糖醋'平衡，糖需略多于直觉；加到90g会甜得发腻；减到40g则酸得倒牙"},{"n": "生抽","q": "2勺（约30ml）","a": "提鲜增色；加到3勺会压住蟹香"},{"n": "姜、葱","q": "姜4片、葱3根","a": "姜片腌鱼去腥、葱段煮鱼汤提味；姜片加到8片会辣"},{"n": "蟹肉（蟹黄+蟹肉）","q": "80g","a": "'带蟹味'的来源，最后放入才留鲜；加到150g会有腥气；不用蟹肉可用干贝末替代"},{"n": "水淀粉","q": "2勺（约30ml）","a": "勾薄芡让芡汁挂住鱼身；加到4勺芡汁变糊发稠；减到1勺则芡汁挂不住会流到盘底"},{"n": "猪油","q": "1勺（约15ml）","a": "熬芡时加猪油是杭帮做法，芡汁更亮更润；不用也可以"},{"n": "料酒","q": "2勺（约30ml）","a": "腌鱼去腥；加到4勺酒味会冲出来"},{"n": "姜末、葱丝（装盘）","q": "各1小把","a": "点缀提香；用量随意"}],"steps": ["草鱼处理干净，从背部剖开成两片但不切腹的鱼片（这样熟后能一片片挑开），鱼身两面剞几刀便于入味。","用料酒和姜片把鱼身内外抹匀腌15分钟去腥，同时把鱼捞出用清水冲净表面酒水。","锅中水烧到'蟹眼水'状态——大泡刚起、还没翻滚的状态，提着鱼皮把鱼轻轻放入，全程不翻动。","汆煮2-3分钟，标准是鱼皮起皱、鳃盖发白、鱼肉能被筷子轻松分开，立刻捞出装盘——鱼只能'汆'不能'煮'，久煮肉就发柴。","原锅留200ml鱼汤（这锅汤是鲜味的来源），加姜片葱段煮香后过滤去渣。","另起锅放猪油、白糖、醋、生抽和鱼汤，小火熬2分钟至糖完全化开、汤汁略稠；加蟹肉煮1分钟。","用水淀粉勾成流动的薄芡（芡汁清亮能挂在勺背上），均匀浇在鱼身上，撒葱丝和姜末。"],"key": "鱼只能'汆'不能'煮'：水刚到大泡未翻滚时下锅，2-3分钟即起，久了鱼肉发柴、汤也会浑；蟹肉最后放才留得住蟹香而不被醋酸盖掉。","tip": "杭州做法讲究'活鱼现杀、现杀现汆'，家里做不到时至少用清水养2小时并在汤里加几片姜同煮去土腥；芡汁宁可偏稀也不要偏稠。"},"松鼠桂鱼": {"time": "50分钟","level": "稍难","servings": "3-4人份","ing": [{"n": "桂鱼（鳜鱼）","q": "1条约650g","a": "选1斤半左右活桂鱼，肉厚能立起造型；加到900g需多炸1分钟；减到500g则花刀不够密、造型撑不起来"},{"n": "干淀粉（玉米淀粉或生粉）","q": "80g","a": "拍干粉才能填满刀口形成刺猬状；加到120g外壳过厚发硬；少于50g刀口露白、炸不起花"},{"n": "鸡蛋清","q": "1个","a": "只取蛋清和淀粉调成糊拍在鱼上（蛋清糊更酥）；用全蛋会外壳偏硬"},{"n": "番茄酱","q": "4勺（约60g）","a": "苏式糖醋汁的甜酸主体；加到6勺酸味太冲；减到2勺则甜味不足"},{"n": "白糖","q": "50g","a": "与番茄酱形成'糖醋'；加到70g过甜；减到30g则酸甜失衡"},{"n": "白醋","q": "30ml","a": "镇江香醋最好；加到50ml太酸；少于15ml酸度不够挑起鲜味"},{"n": "盐","q": "3g","a": "腌鱼用；加到6g鱼肉发紧"},{"n": "蒜末","q": "3瓣（约15g）","a": "起香；加到6瓣会有蒜辣冲味"},{"n": "松子仁（或青豆）与白芝麻","q": "松子仁30g、白芝麻1勺","a": "'松鼠'造型要'眼睛'和'脚'，传统用松子仁，用青豆则偏家常；加到60g会盖住芡汁；白芝麻可省，量少不影响"},{"n": "料酒","q": "1勺","a": "腌鱼去腥；加到3勺会盖掉鱼肉的鲜"}],"steps": ["桂鱼处理干净，保留鱼头鱼尾；沿鱼身两侧剞成菱形花刀，刀距约1.5cm、深度必须切到鱼皮（切不到皮就炸不出刺），切下的鱼肉块翻成直立的花刀。","鱼用盐和料酒抹匀腌10分钟，擦干表面水分（不擦干下锅会崩油）。","调蛋清淀粉糊，把鱼身刀口处全部蘸上糊，再用手把干淀粉拍进每一条刀缝里，拍实拍匀——这是'松鼠'外壳的来源。","油温五成热（约170℃、油面冒细泡）提鱼入锅，保持定型不动，炸3分钟至外层定型微黄捞出。","把油温升到八成热（约200℃），复炸40秒至外壳金黄酥脆、敲起来有脆响，捞出控油静置1分钟（回油会更酥）。","糖醋汁：锅中放番茄酱、白糖、白醋和50ml清水，小火熬3分钟至起泡浓稠、颜色红亮，加蒜末炒香。","鱼头鱼尾朝上斜立在盘中央，鱼身花刀朝外展开呈松鼠状，把糖醋芡汁均匀浇满鱼身，撒松子仁（或青豆）和白芝麻。"],"key": "花刀必须深至鱼皮、拍粉要压实填满刀口，才能炸出直立的刺状外形；两次复炸（低温定型、高温酥脆）才外酥里嫩；糖醋汁要现做现浇，凉了会流到盘底毁掉造型。","tip": "怕油溅可以用锅盖挡着下鱼；定型的关键是下锅后千万别用铲子碰鱼身；盘底可先铺一层生菜或垫几根葱段吸收流下的芡汁。"},"龙井虾仁": {"time": "40分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "明虾仁（河虾或海虾）","q": "400g","a": "400g够3人；加到600g需分两锅滑；减到250g则一人份不足。选活虾现剥最鲜"},{"n": "明前龙井茶叶","q": "10g","a": "特级龙井，用3g则茶香不足；加到20g会有明显茶涩盖住虾甜；也可用龙井茶包但香气淡"},{"n": "80℃龙井茶水","q": "150ml","a": "用80℃水泡龙井，水太烫会把茶杀熟发苦；加到250ml茶味冲淡虾鲜；减到80ml则菜太干"},{"n": "蛋清","q": "1个（约30g）","a": "上浆的核心，能锁住虾仁水分；用全蛋会带腥"},{"n": "淀粉","q": "15g","a": "配蛋清调成稀浆挂住虾仁；加到30g会外层发硬；减到5g挂不住浆"},{"n": "食用油（滑油）","q": "500ml（炸油）+ 30ml（炒油）","a": "500ml宽油温稳定、不会因锅小降温；用普通炒菜的油量会导致虾仁粘锅"},{"n": "盐","q": "3g","a": "虾仁上浆前用盐抓洗是提鲜的关键；加到6g虾仁发紧"},{"n": "姜末、葱段","q": "姜末5g、葱2根","a": "提香；姜末多了会抢茶香"},{"n": "淡菜（干贝）","q": "6颗","a": "提海鲜甜；用3颗也够；加到10颗会过甜"},{"n": "高汤","q": "50ml","a": "调底味；不用高汤用清水也可，但鲜度略逊"}],"steps": ["虾仁用牙签从背部第二节挑出虾线（不挑会有腥味），加3g盐抓洗10分钟至虾仁发亮发黏，再用清水冲净沥干。","虾仁加蛋清、淀粉、料酒抓匀，封一层油防止水分蒸发，冷藏20分钟完成上浆——这层浆是虾仁弹嫩的关键。","龙井茶叶用80℃水泡3分钟，茶水留用，茶叶沥干备用（不要用100℃沸水，茶会发涩）。","锅中倒500ml宽油烧至四成热（约120℃），下上浆的虾仁，用勺子快速滑散，虾仁刚一变白就立刻捞出——全程不超过30秒。","锅中留30ml底油，下姜末和泡发的淡菜炒香，倒入高汤和龙井茶水，加盐调味煮开。","虾仁回锅推匀，随即关火，撒入龙井茶叶和葱段，用锅中的余温把虾仁焖熟——杭帮菜讲究不让虾仁在锅里多待一秒，这样才嫩。","立即装盘，虾仁颗颗晶莹弹牙，茶香与虾鲜相互成就而不互相覆盖。"],"key": "上浆后虾仁要用'滑油'而不是'炒'：四成油温下锅、变色即出，全程不超过30秒；最后关火用余温让虾仁在汤汁里焖熟，这是杭帮菜'清雅鲜嫩'的讲究所在。","tip": "虾仁上浆后放冷藏别超过2小时，久了浆会破；茶叶要最后撒，焖在锅里久了会发苦。"},"腌笃鲜": {"time": "1.5小时","level": "简单","servings": "3-4人份","ing": [{"n": "春笋（鲜嫩小笋）","q": "4根约600g","a": "必须是清明前后挖的春笋，老笋炖不脆；600g够4人；加到1kg需多焯水5分钟；减到300g则不够分"},{"n": "咸肉/腊肉（带皮）","q": "300g","a": "咸肉是'咸'那一路，300g配600g笋比例合适；加到500g汤会过咸；少于150g则腌笃鲜名不副实"},{"n": "鲜五花肉","q": "300g","a": "'鲜'那一路，不能省；用里脊替代会失去肥香；加到500g则抢了春笋的鲜"},{"n": "百叶结","q": "200g","a": "吸汤的经典配料；加到300g会抢味"},{"n": "老姜","q": "4片","a": "去咸肉腥味；多了会辣"},{"n": "小葱","q": "2根","a": "起锅撒葱花；也可一半下锅炖"},{"n": "料酒","q": "2勺（约30ml）","a": "焯水用；加到4勺会夺汤味"},{"n": "清水","q": "1500ml","a": "一次加足，中途不添水（加了汤味变淡）；减到1L不够炖"},{"n": "盐","q": "2g","a": "咸肉已提供咸度，起锅前尝味再决定；加到5g必然过咸"},{"n": "白胡椒粉","q": "1g","a": "提鲜去腥；多了发苦"}],"steps": ["春笋剥壳切滚刀块，沸水下锅焯5分钟，焯到笋芯完全变成淡黄绿色，捞出沥干——春笋不焯透汤会发苦。","咸肉切1cm厚片，冷水浸泡30分钟去多余盐分（这是汤不咸的关键一步），沥干后擦干。","鲜五花肉切2cm块，冷水下锅加姜片和料酒焯3分钟，撇净浮沫捞出。","锅中不放油，下咸肉块小火煸3分钟，煸出肥油和香气，这层油是'鲜'的来源。","加姜片、葱结、料酒，倒入1500ml清水大火烧开，转小火加盖炖40分钟。","下鲜肉块和春笋块，加盖转小火炖25分钟，标准是笋能咬断但不散、鲜肉酥而不烂。","下百叶结煮8分钟，加盐和白胡椒调味，起锅前撒葱花，趁热喝汤。"],"key": "咸肉要先用冷水泡30分钟去盐、再用小火煸出油才下锅炖，这是'鲜'与'咸'平衡的核心；春笋必须沸水焯5分钟去涩，不焯汤必苦。","tip": "腌笃鲜讲究'咸肉出鲜'，汤面浮油不必撇掉，那层油带着肉香；若想更清爽可撇掉一半再下百叶结。"},"蟹黄汤包": {"time": "3.5小时（熬皮冻2小时）","level": "稍难","servings": "4人份（12个）","ing": [{"n": "猪后腿肉","q": "400g","a": "肥瘦三七开，400g配150g皮冻刚好；加到600g则汤汁不足、咬开是干的；减到300g汤太多皮兜不住"},{"n": "猪皮（熬皮冻）","q": "150g","a": "150g能熬出约300ml浓皮冻；加到250g冻太硬咬不动；少于100g冻量不足"},{"n": "蟹黄","q": "120g","a": "蟹黄是'蟹'的灵魂，最后放入不要搅；加到200g会腥、也抢馅的肉香"},{"n": "蟹肉","q": "80g","a": "与蟹黄配比约3:2；加到150g会有明显蟹腥；用蟹粉酱也可但要减量"},{"n": "姜","q": "1块（约60g）","a": "姜末去肉腥；多了会辣"},{"n": "葱","q": "2根","a": "葱花增香；和姜末一起腌肉"},{"n": "盐、生抽","q": "盐6g、生抽1勺","a": "盐6g配400g肉正合适；加到10g馅会过咸（皮冻是咸的）"},{"n": "面粉（皮）","q": "300g","a": "烫面用；300g可做12个；加到350g皮会偏厚、透光性差"},{"n": "白胡椒粉","q": "1g","a": "提香；不用也可"},{"n": "香醋、姜丝（蘸料）","q": "香醋4勺、姜丝10g","a": "镇江醋配姜丝是官方吃法；用醋加酱油也可"}],"steps": ["猪皮焯水后加姜葱，小火熬2小时成浓白汤，滤净后倒进方盘，晾凉放入冰箱冷藏成皮冻（皮冻是汤包汤汁的来源，不可省）。","肉馅加姜末、葱花、生抽、盐和白胡椒，顺一个方向搅打3分钟至上劲发黏，再拌入蟹肉和蟹黄——蟹黄最后放、轻轻拌匀，搅久了会破出腥水。","把冷藏的皮冻切成小丁，与肉馅拌匀，冷藏30分钟让冻粒在馅里分布均匀。","皮用165℃的热水（约70%沸水兑30%凉水）烫面，揉成光滑的烫面团，盖布醒30分钟——必须用烫面，凉面和出来的皮硬且不漏汤。","面团搓条下剂子，擀成中间厚、边缘薄（约1mm）的圆皮，包入馅料，捏出18道以上的褶，收口留一个小气孔让汤汁有处可去。","蒸笼水完全烧开后再上锅，大火蒸7分钟（包子未熟时最易塌陷），关火焖1分钟再开盖。","上桌前在包口处垫一小块纱布或用漏勺接住，先咬小口喝汤、再吃皮和馅，配姜丝香醋。"],"key": "皮必须是烫面（165℃水烫面）才够薄透、能兜住滚烫的汤汁；包好后要留一个小气孔，汤包在蒸制时汤汁翻腾，若完全封死必然爆皮。","tip": "吃的时候用筷子在褶子口轻轻夹开一个小口，先喝汤；蘸香醋加姜丝可去腥提鲜。"},"小笼包": {"time": "2小时","level": "稍难","servings": "3-4人份（16个）","ing": [{"n": "猪腿肉","q": "500g","a": "500g可包16个（每个18g馅）；加到700g需分批；减到350g则每口咬到的肉太少，不成其为小笼"},{"n": "嫩笋丁（春笋）","q": "150g","a": "这是小笼与肉包的区别所在，加笋丁才有'鲜'；加到250g会抢味；不用笋的'灌汤小笼'是另一路"},{"n": "猪皮冻","q": "200g","a": "切成小丁拌入馅，是'一口爆汁'的来源；加到300g则咬开全是冻、味道寡淡；少于100g没汁"},{"n": "皮冻水或高汤","q": "150ml","a": "打肉馅时打进清水增加汤汁；加到250ml馅会稀、包子易破；不用高汤用清水也可"},{"n": "姜末、葱花","q": "姜15g、葱20g","a": "姜末要用清水泡一下去掉辛辣；多了会有明显姜味"},{"n": "生抽","q": "2勺（约30ml）","a": "咸鲜底味；加到3勺偏咸"},{"n": "白糖","q": "8g","a": "提鲜去腥；不加会腥；加到20g偏甜"},{"n": "食盐","q": "7g","a": "皮冻本身带咸，7g配500g肉正合适；加到12g会过咸"},{"n": "面粉","q": "300g（其中250g烫面、50g生面）","a": "半烫面兼顾韧性和麦香；全用烫面会太软漏汁，全用生面太硬"},{"n": "香油","q": "1勺（约15ml）","a": "最后拌入馅提香；减到半勺差别不大"}],"steps": ["猪腿肉手工剁馅（不要用绞肉机绞成泥），保留肥瘦颗粒，加姜末、葱花、生抽、糖、盐和150ml水，同一方向搅打5分钟至肉馅发黏、上劲。","笋丁焯水1分钟过凉水切碎，与肉馅拌匀；冷藏的皮冻切成3-4mm的小丁拌入馅中，冷藏20分钟让冻粒分布均匀（冻粒是爆汁的关键）。","面粉250g用160℃水烫成半烫面，趁热加入剩余50g生面粉揉成团，盖布醒30分钟——半烫面既有韧性又有麦香。","面团搓成长条下剂子（每个约15g），用擀面杖把中间擀厚、边缘擀薄（约1mm厚），这是小笼包能兜汤的关键。","每人皮包18g馅，捏出14-16道褶，收口朝上并留一个小气孔。","蒸笼铺笼布（或刷油、垫笼垫），包子之间留出约2cm间距，挤在一起会互相粘破皮漏汁。","蒸笼上汽后放入包子，大火蒸6分钟（从上汽后开始计时），关火焖1分钟再揭盖，避免骤冷回缩。"],"key": "皮冻必须切成小丁而不是搅碎——咬开瞬间一颗冻化成汤，这是'一口爆汁'的物理原理；蒸6分钟足够，蒸过头肉馅发柴、汤也全跑了。","tip": "上海本地小笼用猪腿肉加皮冻和笋丁，讲究'一口先喝汤'；蘸醋加姜丝是标准吃法。判断熟度：包子明显变轻变大、边缘透出肉色即熟。"},"扬州炒饭": {"time": "20分钟","level": "中等","servings": "2人份","ing": [{"n": "隔夜冷米饭","q": "400g","a": "必须是隔夜冷饭，水分少才能炒得粒粒分明；加到600g需大火多炒2分钟；用新蒸的湿饭必炒成坨"},{"n": "鸡蛋","q": "3个（约150g）","a": "3个蛋配400g米是'金包银'的黄金比例；加到4个蛋香更浓但会抢蔬菜味；减到2个则蛋香不足"},{"n": "虾仁","q": "100g","a": "必须上浆或至少用料酒抓一下；加到150g虾鲜更足但成本高"},{"n": "火腿丁","q": "60g","a": "用金华火腿或火腿肠丁；加到100g会偏咸；减到30g则少了咸鲜"},{"n": "青豆","q": "50g","a": "焯熟才脆甜；加到80g会抢味"},{"n": "腊肠丁","q": "50g","a": "广式腊肠带甜香，是扬州炒饭的隐藏主角；加到80g会过甜"},{"n": "小葱","q": "1把（约25g）","a": "起锅前撒以保葱香；加到50g会有生葱冲味"},{"n": "食盐","q": "3g","a": "火腿和腊肠已带咸，3g足够；加到6g必咸"},{"n": "生抽","q": "1勺（约15ml）","a": "只用来提色和补咸；加到2勺颜色发深、偏咸"},{"n": "食用油","q": "40ml（其中20ml润锅倒掉）","a": "润锅的油要倒掉再下新油，这是'镬气'的来源；省掉这步就没有锅气"}],"steps": ["隔夜米饭用手搓散、饭勺拨成粒粒分离的状态，散不开的饭块要挑出来或用手指捏散——这是粒粒分明的第一步。","虾仁用料酒和少许盐抓匀腌5分钟；火腿丁、腊肠丁、青豆分别下沸水焯1分钟至断生，捞出沥干（生食材不能直接下锅炒半熟）。","锅烧到冒烟，下20ml油润锅，转动锅子让油铺满锅面，再把油倒出来，重新下20ml油——这一步是'镬气'的关键。","油温六成热（约170℃）倒入打散的蛋液，用铲子快速推散，蛋液将凝固未全干时立刻下米饭。","中大火翻炒2分钟，用锅铲不停压、推、翻，让每一粒米饭都均匀裹上蛋液（这就是'金包银'），直到饭粒粒粒分明、微微发亮。","下虾仁、火腿丁、腊肠丁和青豆翻炒1分钟，沿锅边淋1勺生抽，加盐，翻匀。","出锅前沿锅边淋1勺热油增加镬气，撒上葱花再翻两下立刻装盘。"],"key": "必须用隔夜冷饭且下锅前把饭粒彻底拨散，湿饭无论怎么炒都会结坨；油要'润锅—倒掉—再下新油'两遍，这是扬州炒饭镬气的真正来源，缺了这一步就只是蛋炒饭。","tip": "配料自己掌握但比例有章法：蛋液与米饭约1:2.7、肉类配料与饭约1:4；正宗扬州炒饭是'饭粒、蛋、料三分离'，看不到大块的料。"},"红烧狮子头": {"time": "2小时","level": "稍难","servings": "3-4人份","ing": [{"n": "猪五花肉（肥瘦约3:7）","q": "600g","a": "600g可做4个150g的大丸子；加到800g需延长炖煮20分钟；减到400g则每人一个刚好不够吃"},{"n": "马蹄","q": "6个（约200g）","a": "马蹄是狮子头的'脆'，不能只用荸荠；加到10个则脆过头发硬；少于4个口感会发黏"},{"n": "荸荠","q": "5个（约100g）","a": "荸荠增甜增脆；可与马蹄二选一但马蹄更脆；加到10个会抢味"},{"n": "鸡蛋清","q": "1个（约30g）","a": "上劲用；用全蛋会带腥；加到2个则丸子偏硬"},{"n": "淀粉","q": "20g","a": "帮助上劲成型；加到40g口感发面发散；少于10g丸子易碎"},{"n": "姜末","q": "10g","a": "去肉腥；多了会辣；用水泡一下姜末更温和"},{"n": "小葱","q": "2根","a": "葱花入馅增香；不要切得太碎"},{"n": "盐、生抽","q": "盐5g、生抽2勺","a": "5g配600g肉正合适；加到8g丸子发紧；生抽3勺会发黑"},{"n": "冰糖","q": "20g","a": "收汁上色；加到35g会齁；减到10g色不亮"},{"n": "清水","q": "500ml","a": "一次加足，中途不添水；减到300ml会把丸子炖干"}],"steps": ["五花肉先切成1cm方粒，再手工剁成细茸（不要用绞肉机，绞出来的肉太碎、烧不出'松'的口感），马蹄和荸荠切小丁。","肉茸加姜末、葱花、盐、生抽、蛋清和淀粉，全部用手同一方向搅打3分钟，打到肉馅发黏、手握成团松手不散（这是上劲的关键）。","团成大丸子，每个约150g，放在掌心向上抛摔15-20下把内部空气排出，表面必须光滑不裂缝——有气孔炖时就散。","砂锅底先铺姜片和葱段（防止粘底，也防止丸子吸不到底味），放入狮子头，一次性加500ml清水至刚没过丸子，大火烧开转最小火加盖焖90分钟。","焖足90分钟后开盖转中大火收汁，用勺子把浓汁反复淋在狮子头表面，让表面均匀上色发亮，收到汤汁浓稠能挂住。","取一小块白菜或冬笋垫底装盘，狮子头摆正，浇上原汁即可。","成菜标准：入口先是'松'——内部有蜂窝状缝隙含在肉汁里，然后是'嫩'和'酥'，用筷子夹会颤但绝不散开。"],"key": "肉茸必须手工剁粒并搅到上劲，丸子才能'松而不散'——'松'指的是内部蜂窝状含着肉汁，而不是炖得稀烂；焖足90分钟且全程最小火，火大必散。","tip": "摔打丸子时手上可抹一点水防粘；没有马蹄可用荸荠+藕丁替代，脆感稍逊但味道成立。"},"佛跳墙": {"time": "4.5小时（干货泡发需提前一晚）","level": "稍难","servings": "4人份","ing": [{"n": "老母鸡半只","q": "600g","a": "用于吊高汤，600g可吊1L浓白汤；加到1kg汤太稠会盖住其他味；减到400g汤味不足"},{"n": "水发鱼翅（可用花胶或肉翅替代）","q": "50g","a": "鱼翅按包装说明泡发，50g够4人；加到100g成本极高；没有鱼翅可用瑶柱和笋干替代"},{"n": "干贝","q": "30g","a": "泡发后约80g，'佛跳墙'的鲜味主力；加到50g过鲜发腥；少于20g则鲜味不足"},{"n": "干鲍鱼","q": "4只（约40g）","a": "涨发后每个约30g；加到6只成本高；干鲍需提前泡发48小时"},{"n": "瑶柱、蹄筋","q": "各50g","a": "瑶柱提鲜、蹄筋提供胶质口感；蹄筋泡发要12小时以上"},{"n": "花胶","q": "50g","a": "泡发后约150g，绵软吸味；加到100g口感过黏"},{"n": "金华火腿","q": "50g","a": "切薄片提咸鲜；加到100g会过咸；少于30g则缺了火腿的咸甜"},{"n": "冬笋","q": "100g","a": "切成滚刀块，吸收汤汁；用春笋也可以，但冬笋更脆甜"},{"n": "绍兴黄酒","q": "200ml","a": "'坛香'的关键；加到300ml酒味太重抢鲜；少于100ml则香气不足"},{"n": "荷叶","q": "1张（干荷叶需泡水）","a": "封口用，荷叶的清香是标志；没有荷叶用纱布+豆腐盖也行但少了那味"}],"steps": ["前一天晚上把所有干货处理：干贝温水泡发12小时（加几滴白酒去腥）、蹄筋和花胶泡发12小时以上、干鲍泡发48小时、瑶柱泡2小时，泡好后分别冷藏备用。","老母鸡斩块冷水下锅焯5分钟去血沫，捞出加姜葱和150ml黄酒，小火炖1小时成高汤，撇净表面浮油只留清汤。","鱼翅焯水30秒去腥（久煮会发硬发柴），鲍鱼改花刀后沸水焯2分钟备用，冬笋切滚刀块焯水2分钟。","取一只陶制小坛或砂锅，底部先铺发好的蹄筋、花胶、干贝和瑶柱，再依次码上鲍鱼、鸡肉块、火腿片和冬笋，摆得紧凑好看。","倒入高汤和剩余的50ml黄酒，量以没过食材八成为准，上面盖一张泡软的荷叶，用细绳把坛口扎紧封住。","上锅隔水炖3小时（放进蒸锅或水浴的砂锅中，锅里的水始终保持微滚），火候以汤汁微微翻滚不剧烈沸腾为准。","炖到汤汁浓稠、鲍鱼软糯、干贝一碰就散时即可开盖，揭去荷叶，那股'坛香'扑面而来。"],"key": "所有干货必须提前泡足时间（干鲍48小时、蹄筋花胶12小时以上），没泡透会咬不动；荷叶封口隔水炖是'坛香'的来源，若明火直接炖，所有食材的鲜味会在高温中挥发殆尽。","tip": "这是闽菜之王，费工费时，家庭简化版可以用花胶+干贝+瑶柱+火腿+笋干+鸡肉六件，炖2小时也很像样；避免用鲜鲍和冻干鲍，鲜鲍一炖即老。"},"沙茶面": {"time": "1.5小时（沙茶酱自制需1小时）","level": "中等","servings": "2-3人份","ing": [{"n": "沙茶酱（自熬为佳）","q": "250g","a": "自制沙茶酱用虾干、扁鱼、椰奶、蒜、辣椒、芝麻和咖喱粉熬成；250g可冲1.2L汤；用市售沙茶酱则减到150g，否则会太稠太辣"},{"n": "虾干（虾米）","q": "40g","a": "沙茶酱的海味来源；加到60g酱会发腥发苦；少于20g则失去'沙茶'的鲜"},{"n": "扁鱼（鱼干）","q": "30g","a": "闽南特有的香料鱼干，炸香剁碎；加到50g会过腥"},{"n": "椰奶（椰浆或淡奶）","q": "100ml","a": "沙茶酱的奶香与柔和度；加到200ml会盖住虾干香；少于50ml酱会发干发辣"},{"n": "猪筒骨（熬汤）","q": "1.5kg（出汤1.2L）","a": "沙茶汤底必须用猪骨或鸡骨熬的浓汤；减到800g汤不够浓；用清水冲酱会寡淡"},{"n": "碱水面或细面","q": "300g","a": "厦门用碱面；300g够3人；加到450g需多备汤；面条另锅煮"},{"n": "豆腐泡（油豆腐）","q": "100g","a": "吸汤的关键配料；加到200g会抢味；少于50g则少了厦门特色"},{"n": "瘦肉片、虾或鱿鱼","q": "共150g","a": "'料随便加'的经典配置；瘦肉切薄片、虾去虾线"},{"n": "空心菜","q": "150g","a": "烫30秒即断生；加到300g会出草涩味"},{"n": "白醋或柠檬","q": "半个柠檬（或2勺醋）","a": "厦门吃沙茶面要滴白醋或柠檬汁提味；加了酸才正宗；不加则少了这一口"}],"steps": ["沙茶酱自制：虾干和扁鱼用少量油小火炸3分钟至酥香，捞出放凉后剁成细碎；锅中下蒜末、洋葱碎和辣椒小火炒香，加咖喱粉、芝麻酱和剁碎的虾干扁鱼同炒2分钟，最后倒入椰奶，小火熬10分钟成浓稠酱。","猪骨焯水后加姜片大火烧开，转小火熬2小时成白汤，滤净浮沫备用。","取200ml热骨汤在小锅中把沙茶酱一小勺一小勺澇开，搅到完全均匀无颗粒，再连汤倒入大锅，其余骨汤补足到1.2L。","酱汤用小火加热到微微冒泡即可，绝不能大滚——大火会让沙茶酱里的油脂分离出来漂在汤面，香味也散掉。","面条另用沸水煮熟（厦门是'面另煮、汤另滚'），捞出沥干装碗；不要在沙茶汤里煮，否则汤会浑、面会吸酱。","沙茶汤中依次下豆腐泡、瘦肉片、虾或鱿鱼，烫熟后连汤舀入面碗，最后烫30秒空心菜摆上。","食用前滴半个柠檬汁或2勺白醋，这一步是厦门沙茶面的点睛，酸与辣同时提起来。"],"key": "沙茶酱必须先用热骨汤澇开再入锅，直接倒进锅里会结块起油花；汤只能小火保持微沸，一大滚酱就分离；面必须另锅煮，绝不能在沙茶汤里煮。","tip": "厦门人吃沙茶面'料随便加'，最经典是豆腐泡加油条（油条剪段泡汤）；做酱时手边没有扁鱼可用小黄鱼干代替，虾干不能减。"},"海蛎煎": {"time": "25分钟","level": "简单","servings": "2人份","ing": [{"n": "海蛎（肥瘦相间的新鲜蚵仔）","q": "400g","a": "闽南要选肥瘦'三肥七瘦'的，煎出来才爆汁香；加到600g需分两锅；减到250g则一人份不足"},{"n": "地瓜粉","q": "80g","a": "地瓜粉是'粉'的关键（番薯粉），不可用玉米粉替代（会返生不脆）；加到120g口感会偏硬；少于50g挂不住海蛎"},{"n": "清水（调粉浆）","q": "150ml","a": "粉与水约1:2调成稀浆，能挂勺即可；加到220ml会太稀煎不成形；少于100ml会结块"},{"n": "鸡蛋","q": "4个（约200g）","a": "4个配400g海蛎，蛋香与海味平衡；加到6个会只剩蛋味；减到3个则海蛎味突出"},{"n": "小葱","q": "1把（约30g）","a": "切末撒面和拌粉浆；加到50g会有生葱冲味"},{"n": "香菜","q": "1小把","a": "闽南必撒，可选"},{"n": "白胡椒、盐","q": "白胡椒2g、盐3g","a": "去海蛎腥味；盐要少，海蛎本身带咸；盐加到6g会发咸"},{"n": "食用油","q": "40ml","a": "平底锅用油煎制；减到20ml会粘锅破底；加到60ml会油腻"},{"n": "甜辣酱","q": "4勺（约60ml）","a": "闽南灵魂，虾酱、辣椒、甜味调成；加到6勺会过甜；少于2勺则少了灵魂"},{"n": "甘薯粉水（可选勾芡）","q": "1勺","a": "海蛎汁多时调一点水淀粉收在底部，让口感更整"}],"steps": ["海蛎轻轻淘洗一下去掉细沙后沥干，不要用力搓洗（海水养的蚵肉一搓就稀烂），再用厨房纸吸干表面水分。","地瓜粉80g加150ml清水调成稀浆，加入白胡椒、盐和一半葱花搅匀，静置5分钟让粉充分吸水。","平底锅放20ml油烧至六成热（约170℃），倒入粉浆迅速转匀摊平，中火煎1分钟至粉浆半透明、表面起小泡。","均匀撒上海蛎，转大火煎2分钟，此时海蛎边缘会微微焦香，注意底部不要焦糊。","淋上打散的鸡蛋液，轻轻转动锅子让蛋液铺满，大火再煎1分钟至蛋液完全凝固、边缘呈焦黄色蕾丝状。","沿锅边再淋10ml油，转动锅子让底面也受热1分钟——闽南海蛎煎讲究'边焦香、中间嫩'。","出锅撒剩下的葱花和香菜，配4勺甜辣酱食用，可再撒一点胡椒粉。"],"key": "海蛎要选肥瘦相间的新鲜货并轻淘轻沥；地瓜粉浆必须先摊底再放海蛎，否则就煎成了'海蛎蛋饼'，失去闽南'粉浆包蛎'的层次。","tip": "正宗吃法是蘸甜辣酱吃，不要在锅里撒太多盐；喜欢更酥的可以复煎一遍。另外厦门常用的是'珠蚝'（小海蛎），个头小更嫩更入味。"},"生煎包": {"time": "1.5小时（发酵1小时）","level": "中等","servings": "3-4人份（12个）","ing": [{"n": "面粉","q": "300g","a": "300g可做12个（每个约15g）；加到400g皮会偏厚；减到250g则包不满12个"},{"n": "酵母","q": "3g","a": "3g配300g面粉、150ml水，25℃发1小时正好涨到两倍大；加到6g会发过头、包子发酸"},{"n": "温水（和面）","q": "150ml（约面粉的一半）","a": "水温30-35℃，太热会烫死酵母；加到180ml面会偏软粘手"},{"n": "猪肉馅（肥瘦3:7）","q": "350g","a": "350g配12个（每个约18g馅）；加到450g会包不上或太肥"},{"n": "皮冻","q": "150g","a": "切成小丁拌入馅，是'汁多'的关键；加到250g则咬开全是冻；少于80g没什么汁"},{"n": "姜末","q": "8g","a": "去肉腥；用水泡一下姜末更温和；多了会辣"},{"n": "葱花","q": "1把（约25g）","a": "拌馅和出锅撒两用；葱要切得细"},{"n": "盐、生抽","q": "盐5g、生抽2勺","a": "皮冻带咸，5g正合适；加到8g会过咸"},{"n": "白芝麻（熟）","q": "1勺（约10g）","a": "出锅撒在脆底上，是生煎的标志；生芝麻会发苦"},{"n": "食用油","q": "30ml（煎制）+ 10ml（刷锅）","a": "煎底用30ml，另留10ml刷锅防粘；煎用油减到10ml会粘锅破底；刷锅油可多可少，不影响味道"}],"steps": ["面粉加酵母和150ml温水揉成光滑面团，盖湿布放在温暖处发酵至两倍大（约1小时，25℃时约60-70分钟），手指蘸粉戳洞不回缩即发好。","肉馅加姜末、葱花、生抽和盐，同一方向搅打上劲，再拌入切小丁的皮冻，冷藏20分钟让冻粒分布均匀。","面团排气揉光，搓成长条切成15g左右的小剂子，用擀面杖把每个剂子擀成中间厚、边缘薄的圆皮（直径约7cm）。","包入18g馅，捏紧收口朝下，逐一排在刷过油的平底锅或铸铁煎盘中，间距2cm，不要挤在一起（否则底部会粘在一起破皮）。","平底锅大火烧热，倒入50ml清水，立刻盖上锅盖转中火焖8分钟——这是'半煎半蒸'的蒸汽阶段，靠蒸汽把面皮和馅心蒸熟。","开盖转大火，此时锅底的水已被收干，继续煎2-3分钟至锅底金黄酥脆，能听到明显的'沙沙'响并飘出焦香。","用刷子在锅底薄薄刷一层油增加酥度，关火扣盘倒扣到盘中，撒上熟白芝麻和葱花，趁热吃。"],"key": "生煎的核心是'半煎半蒸'：先加清水盖盖靠蒸汽把面皮蒸熟，再开盖大火收干水份煎出脆底；省掉加水焖这一步就只是煎包，咬开会是生面皮；水收不干则底不脆，撒不上芝麻也失了灵魂。","tip": "上海派生煎是'先蒸后煎'、汤汁多；浙江派是'先煎后蒸'、底更脆。判断底够不够脆：听声音、看颜色，闻到焦香即可，别煎过头发黑。"},"文昌鸡": {"time": "80分钟","level": "中等","servings": "3-4人份","ing": [{"n": "文昌鸡（本地阉鸡）","q": "1只约1.2kg","a": "用到1.5kg则需延长浸煮8分钟，皮更紧实；减到1kg则浸22分钟就够，皮稍松但肉更嫩；超过1.8kg皮厚难入味，不适合浸煮法"},{"n": "精盐","q": "15g","a": "增至20g能把鸡皮腌得更紧有嚼劲，但蘸料就别再放盐了；减到8g腌味不足、鸡皮发滑"},{"n": "沙姜","q": "20g","a": "加到30g沙姜味更冲更有海南味；减到8g只剩蒜香，丢掉文昌鸡的招牌风味"},{"n": "蒜头","q": "40g","a": "加到60g蒜香更烈适合重口；减到15g则蒜香不足、蘸料发单薄"},{"n": "桔子酱","q": "40g","a": "加到70g酸甜更突出、极开胃；减到15g酸度不够，只剩咸鲜味"},{"n": "生抽","q": "30ml","a": "加到50ml蘸料偏咸，鸡肉本味会被盖住；减到10ml则咸度不足需另补盐"},{"n": "芝麻油","q": "15ml","a": "加到30ml油香更浓、蘸料更顺口；减到5ml会发干发涩，蒜蓉挂不住"},{"n": "老姜","q": "60g","a": "姜块加到100g可多煮一锅姜汤同吃；减到20g姜味不足、去腥效果弱"},{"n": "大葱","q": "2根","a": "加到4根适合熬一大锅姜葱水；减到1根姜葱香气不够压不住鸡油味"},{"n": "冰水","q": "1大盆","a": "冰块加到500g冰水温度更低、皮更爽脆；用常温凉白开代替皮会发黏不脆弹"}],"steps": ["整鸡处理干净，掏净膛内内脏和油脂，剪掉脚爪与多余鸡油，用清水反复冲洗腹腔，沥干水分备用。","精盐在鸡身内外均匀揉搓，重点在鸡腿根和鸡胸肉厚处，静置腌20分钟；腌好后用清水冲净表面盐分。","锅中加足量清水（约4L）没过整鸡，放老姜块、葱段，大火烧开后转小火，保持汤面如虾眼水般微微冒泡，切勿大滚。","提着鸡颈把整鸡在沸汤中提放3次，每次约2秒，让鸡腔内外温度一致、皮肤收紧；随后整只沉入汤中，用漏勺轻压使鸡完全浸没。","保持90℃左右的微沸状态浸煮25分钟，关火后加盖焖10分钟；判断标准是筷子扎入鸡腿根部最厚处无血水渗出、肉骨微微分离。","立即捞出放入冰水盆中浸10分钟让鸡皮收紧变爽脆，捞出擦干鸡身表面水分；这一步是文昌鸡皮爽肉滑的关键。","斩件要用快刀顺着骨节下刀，鸡肉不带骨渣、鸡皮完整不撕破；摆盘时鸡头放正中、鸡翅与鸡腿分列两侧。","蘸料：蒜头与沙姜一起剁成细蓉，加桔子酱、生抽、芝麻油、少许盐和煮鸡的原汤拌匀；吃前将花生油或芝麻油烧至冒烟，泼在蒜蓉沙姜上激香，再上桌。"],"key": "水温必须稳定在90℃左右的\"虾眼水\"微沸状态——大滚会把鸡皮煮烂、蛋白收缩变柴；煮好后必须立刻冰水激皮，这是文昌鸡\"皮爽肉滑\"两大命门。","tip": "没有文昌鸡用本地三黄鸡或清远鸡替代，但浸煮时间按重量减5分钟；喜欢更清淡可把桔子酱减半，另加10ml米醋。"},"清补凉": {"time": "90分钟","level": "简单","servings": "3-4人份","ing": [{"n": "鲜椰奶","q": "400ml","a": "加到600ml椰香更浓稠像雪糕质地；减到250ml会变成稀糖水，喝不出椰味"},{"n": "薏米","q": "50g","a": "加到80g更饱腹、口感更绵；减到20g则配料太少显得空荡"},{"n": "绿豆","q": "40g","a": "加到60g更浓稠解暑；减到15g甜汤会寡淡"},{"n": "芋头","q": "150g","a": "加到250g芋香更足、饱腹感强；减到60g则少了绵密的嚼劲层次"},{"n": "鹌鹑蛋","q": "6个","a": "加到10个更热闹像本地摊档；减到3个则配料偏少"},{"n": "冬瓜薏","q": "40g","a": "这是海南清补凉的标志配料，加到60g清甜感更足；减掉则少了那股独特甘味"},{"n": "花生米","q": "40g","a": "加到60g香脆更突出；减到15g口感偏软不够酥"},{"n": "冰糖","q": "80g","a": "加到120g甜度接近椰奶甜品该有的浓度；减到40g会偏淡，且压不住豆类的土味"},{"n": "椰丝","q": "30g","a": "加到50g椰香和口感双增；减到10g香气不足"},{"n": "银耳","q": "15g（干）","a": "加到25g出胶更多汤更稠；减掉也不影响但少了滑润感"}],"steps": ["薏米、绿豆分别用清水浸泡2小时，冬瓜薏提前泡1小时，银耳用冷水泡发30分钟至完全舒展。","薏米冷水下锅大火煮开转小火煮30分钟至开花；绿豆另锅煮25分钟至开花但豆衣不破，两者都不要煮到完全化开。","芋头去皮切成1cm小丁，上蒸锅蒸15分钟至筷子能轻松插透；银耳撕小朵炖至出胶备用。","花生米冷油下锅小火干炒8分钟至微微爆裂发黄，晾凉备用；鹌鹑蛋冷水下锅煮10分钟后剥壳。","另起一锅加500ml清水和冰糖，小火熬10分钟成糖水，放凉备用——糖水必须单独熬，不能和豆类同煮，否则豆腥味会污染糖水。","碗中先舀入椰奶，再按喜好依次加薏米、绿豆、芋头、冬瓜薏、银耳、鹌鹑蛋，最后沿碗边缓缓注入冰糖水至八分满。","表面撒椰丝和花生米，吃前用勺子轻轻搅匀，让每种配料都裹上椰奶即成。"],"key": "椰奶不能加热、不能与热糖水混合，高温会让椰浆分层并破坏椰香；糖水与椰奶都必须放凉后入碗，否则会结块、椰味变酸。","tip": "椰奶可用现成椰浆+牛奶+少量糖自调（椰浆120ml+牛奶280ml+糖20g）；怕冷可加冰块同吃，消暑效果更好。"},"桂林米粉": {"time": "3小时","level": "稍难","servings": "3-4人份","ing": [{"n": "桂林米粉（干）","q": "300g","a": "加到400g够4人吃饱；减到200g则一人份偏少，需要另加面"},{"n": "猪前腿肉","q": "300g","a": "加到450g卤肉更厚实；减到150g卤水香气会变薄，需靠豆豉补"},{"n": "猪皮","q": "150g","a": "加到250g锅烧更肥糯有胶质感；减到50g锅烧会偏瘦偏硬"},{"n": "豆豉","q": "15g","a": "桂林卤水的灵魂，加到25g发酵香更浓；减到5g会失去那口独特的咸鲜回甘"},{"n": "腐乳","q": "2块","a": "加到3块卤水更稠更香；减到1块味不够厚，勉强可吃"},{"n": "桂林三花酒","q": "40ml","a": "加到60ml酒香更足可去腥；减到15ml酒香不足，用普通米酒会偏甜"},{"n": "酸豆角","q": "60g","a": "加到100g酸香更足；减到20g会缺少那口解腻的酸"},{"n": "油炸黄豆","q": "30g","a": "加到50g香脆感更足；减到10g则缺了这层酥脆对比"},{"n": "生抽","q": "30ml","a": "加到50ml卤汁颜色更深更咸；减到10ml则颜色淡、咸度靠盐补"},{"n": "卤料（桂皮、八角）","q": "桂皮3g、八角2个","a": "这是卤水香底的来源，加到桂皮5g、八角4个药香更足；减到桂皮1g、八角1个卤味层次会明显变单薄"}],"steps": ["干米粉用温水泡30分钟至微软不断，用手指能轻松捏弯而不折断即可，捞出沥干备用。","猪骨冷水下锅焯3分钟去血水，捞出冲净；锅中加1200ml清水、猪骨和卤料（桂皮、八角），大火烧开转小火熬40分钟成骨汤。","豆豉略剁碎与腐乳一起用少许热油小火炒香至豆豉微微发红，这一步决定卤水底味的厚度；倒入骨汤，烹入三花酒，加生抽，转小火熬1.5小时成卤水。","猪前腿肉整块下卤水煮40分钟至筷子能扎透但仍有嚼劲，捞出晾凉切薄片；猪皮同锅煮30分钟至软烂，捞出，把猪皮与切好的瘦肉片一起卷紧成长卷、用棉线扎住，冷藏2小时定型后切成薄片即成锅烧。","酸豆角切细末，油炸黄豆提前炸酥备用，蒜末备齐。","碗底放卤水、生抽、少许盐、酸豆角末、豆豉末和油辣子。","宽水大滚下米粉烫40-50秒，筷子夹起能弯且不断即捞出过一遍凉开水防粘，甩干放入碗中。","铺上卤肉片和锅烧片，淋一勺滚热的卤油，最后撒油炸黄豆，从碗底充分拌匀食用。"],"key": "豆豉和腐乳必须先用热油小火炒香再入汤——这是桂林卤水区别于普通卤水的根本；米粉只能\"烫\"不能\"煮\"，煮久了会糊成糊状失去爽滑。","tip": "锅烧自制麻烦，可用现成卤猪耳或卤牛肉替代；没有三花酒可用广东米酒代替，风味略逊但不失败。"},"潮汕牛肉火锅": {"time": "4小时","level": "稍难","servings": "3-4人份","ing": [{"n": "黄牛肉（吊龙、匙柄、嫩肉、五花趾）","q": "600g","a": "加到900g够5人涮；减到400g每部位分不到几片，转着涮不过瘾"},{"n": "牛骨","q": "1kg","a": "加到1.5kg汤更浓白；减到500g汤味寡淡、涮出来的肉没有回甘"},{"n": "南姜","q": "80g","a": "潮汕汤底去臊的关键，加到120g辛香更足；减到30g膻味压不住"},{"n": "沙茶酱","q": "100g","a": "加到150g蘸碟更香浓；减到60g会嫌淡，需另补花生酱"},{"n": "蒜头","q": "40g","a": "加到60g蒜味更冲；减到15g蒜香不足，与沙茶酱不搭"},{"n": "小米辣","q": "15g","a": "加到25g辣度明显提升；减到5g基本尝不到辣"},{"n": "香菜","q": "30g","a": "加到50g香气更足；减到10g则少了解腻提味的一层"},{"n": "鱼露","q": "20ml","a": "加到35ml鲜味更足；减到5ml几乎尝不出，需靠沙茶酱补咸"},{"n": "潮汕粿条","q": "200g","a": "加到300g更适合饱腹；减到100g则汤多粉少"},{"n": "卤料（白豆蔻、草果、甘草片）","q": "白豆蔻6g、草果3个、甘草5片","a": "是潮汕汤底去臊回甘的关键，加到白豆蔻10g、草果5个、甘草8片辛香更足；减到白豆蔻2g、草果1个膻味压不住"}],"steps": ["牛骨冷水下锅焯水，加姜片、葱段、料酒煮开撇净浮沫，捞出用温水冲洗干净；汤锅加4L清水，放牛骨、南姜片和卤料（白豆蔻、草果、甘草片）。","大火烧开转小火熬3-4小时，中途只加热水不换水，熬到汤色浓白如牛奶即成汤底；这是潮汕火锅\"锅底决定一切\"的一步。","牛肉剔净筋膜，逆着肌肉纹理切薄片：吊龙切2mm、匙柄切3mm、嫩肉切2mm、五花趾带一层筋膜切3mm；切好的肉片摊开冷藏备用。","沙茶酱、蒜蓉、小米辣、香菜末、鱼露、少许生抽调成沙茶蘸碟；另备一碟生抽加蒜末做\"韭黄碟\"，用来点吊龙等部位。","汤底开大火滚到\"菊花心\"状态——中心翻腾、边缘只在微动；这个状态能保证汤始终滚烫而不上浮血沫。","先下五花趾和吊龙，涮10秒；再下匙柄涮8秒；最后下嫩肉涮6秒——判断标准是肉片边缘刚刚变色、中心还带一丝粉红，立刻捞出。","涮好的肉先在碟里蘸韭黄酱油，再裹沙茶酱，两层味叠起来才是地道吃法。","吃完牛肉后下粿条煮2分钟，再放芹菜、豆腐皮、玉米、娃娃菜；锅底汤要保持一直滚，随时舀一勺浇在肉上。"],"key": "汤底必须维持\"菊花心\"——中心滚、边缘不翻；水一旦整锅大滚，汤会浑浊起沫、牛肉涮出来发柴。牛肉必须逆纹切，顺纹切会塞牙。","tip": "在家可用高压锅把牛骨汤压到90分钟再开大火滚开，香味略淡但可行；没有干贝可用虾皮10g替代。"},"潮汕生腌": {"time": "5小时","level": "中等","servings": "3人份","ing": [{"n": "活基围虾","q": "500g","a": "加到800g够4人；减到250g腌料比例需减半，否则会太咸太臭"},{"n": "蒜头","q": "60g","a": "生腌的蒜量必须给足，加到90g蒜香更冲；减到30g腥味压不住，这是最不该减的一项"},{"n": "南姜","q": "20g","a": "加到30g辛香更立体；减到8g只剩蒜香，缺少潮汕特有的凉辛感"},{"n": "小米辣","q": "10g","a": "加到20g辣度明显；减到3g基本是蒜味泡虾"},{"n": "精盐","q": "20g","a": "加到30g更咸更入味；减到10g虾肉发水、腥味出不来"},{"n": "白砂糖","q": "15g","a": "加到25g甜味能中和刺激感；减到5g会只剩咸和辣"},{"n": "高度米酒（40度以上）","q": "50ml","a": "加到80ml酒香更足、杀菌更彻底；减到20ml达不到杀菌浓度，容易变质"},{"n": "生抽","q": "20ml","a": "加到35ml酱色更浓；减到5ml则咸度全靠盐，颜色发淡"},{"n": "鱼露","q": "10ml","a": "加到20ml海味更足；减到3ml鲜味变单"},{"n": "冰块","q": "1大把","a": "冰块加到1kg降温更快、虾肉更弹；用冷藏矿泉水代替则温度降得慢"}],"steps": ["虾买回后用冰水养2小时吐沙，中途换水两次；挑选虾身弯曲、壳硬肉厚、活力好的，剪掉虾须虾脚，保留虾壳。","用剪刀从虾背部剪开至尾部但不切断，剔除黑色虾线，用清水冲净血水，再用厨房纸彻底吸干表面水分——带水下刀必坏。","蒜头、南姜、小米辣剁成细蓉但保留颗粒感，不能用料理机打成糊，否则腌料会糊住虾壳；盐与糖先混合均匀。","腌料：蒜姜辣蓉加盐、糖、生抽、鱼露、高度米酒搅匀至糖基本溶解，静置5分钟让香味互相渗透。","虾与腌料抓拌均匀，装入密封玻璃容器，铺上一层冰块降温并防止虾肉在腌制中变质，盖紧盖子。","冷藏腌制4-6小时，期间不要开盖搅动；判断标准是虾肉呈半透明玉白色、虾壳红透，蒜香和酒香完全渗入。","食用前从冰箱取出直接冷食，讲究的用冰镇白粥或高度白酒送；虾肉应紧实弹牙、有淡淡酒香与蒜香而无异味。"],"key": "腌料里的米酒必须是40度以上的高度酒——这是靠酒精杀菌防腐的唯一保障，低度米酒腌不透还容易坏；虾一定要吸干水分、带壳腌。","tip": "新手第一次建议只腌虾不腌蟹，蟹肉更敏感；肠胃弱的人一次别超过6只并当天吃完，次日风味最佳。"},"南昌瓦罐汤": {"time": "4小时","level": "中等","servings": "3人份","ing": [{"n": "猪肋排","q": "500g","a": "加到700g汤更浓；减到300g汤味寡淡，撑不起3人份"},{"n": "老母鸡（半只）","q": "400g","a": "加到600g鸡味更浓白；减掉则成纯排骨汤，失去瓦罐汤的醇厚"},{"n": "干墨鱼","q": "1只约80g","a": "这是南昌瓦罐汤提鲜的关键，加到2只汤头海味更足；减掉则少了那股鲜甜回甘"},{"n": "干香菇","q": "5朵","a": "加到8朵菌香更浓；减到2朵则香气不足"},{"n": "老姜","q": "30g","a": "加到50g姜味更足能压住鸡肉腥；减到10g去腥力弱"},{"n": "精盐","q": "8g","a": "加到12g汤味更足；减到3g会淡而无味"},{"n": "料酒","q": "30ml","a": "加到50ml去腥更彻底；减到10ml残留腥味"},{"n": "枸杞","q": "8g","a": "加到15g回甘明显；减到3g几乎尝不出"},{"n": "红枣","q": "4颗","a": "加到6颗甜度更柔和；减到2颗汤会偏单"},{"n": "清水","q": "1500ml","a": "加到1800ml汤更清亮；减到1200ml汤浓到挂勺、容易溢出罐口"}],"steps": ["瓦罐用清水刷净晾干，新瓦罐先空烧一遍或煮一锅米汤\"开罐\"去土腥；干墨鱼和香菇用温水泡发2小时。","排骨冷水下锅加姜片料酒焯3分钟撇净血沫，捞出用温水冲净；鸡块同样焯水，洗净沥干。","排骨、鸡肉、墨鱼、香菇、姜片、红枣依次码入瓦罐，加清水至罐身八分满——必须留两成空间，煨时汤会翻涨溢出。","用糯米粉加酒糟调成糊封住罐口，或用陶瓷盖盖紧后接缝处用湿泥封严，密闭是炭火煨汤出味的前提。","炭火烧旺，先用旺火催10分钟让汤重新翻腾，再压成小火慢煨3小时，全程不加水——中途添水汤味就散了。","煨到汤色金黄、鸡块酥烂脱骨、汤面浮一层细黄油即为成；判断标准是用筷子一夹肉块就散开。","起罐后加盐和白胡椒粉调味，撒枸杞焖2分钟即可，枸杞久煮会发酸；上桌时连瓦罐带汤一起上桌保温。"],"key": "加水必须一次加够且只加八分满，中途绝不能揭盖添水——瓦罐汤的全部精华都在\"密闭+持续小火\"的浓缩过程里，一加水香气就散了。","tip": "没有炭火可用砂锅小火焖2小时，或用电饭煲\"煮饭\"档2小时；封口也可用保鲜膜+橡皮筋代替泥封。"},"新疆烤全羊": {"time": "5小时","level": "稍难","servings": "8-10人份","ing": [{"n": "整羊（带骨）","q": "1只约18kg","a": "这是传统规格，家庭可用羊排或半只（约8-9kg）替代；减到3kg的整羊难以架起来，烤箱也放不下，切成羊排烤反而更入味"},{"n": "精盐","q": "300g","a": "按羊重1.7%配比，加到400g会腌得过咸发硬；减到200g则肉香透不出来"},{"n": "洋葱","q": "500g","a": "加到800g甜味更足、能锁住肉汁；减到200g香料味单薄"},{"n": "大蒜","q": "100g","a": "加到150g蒜香更冲；减到50g则去膻和提香都不够"},{"n": "生姜","q": "80g","a": "加到120g去腥更彻底；减到30g膻味压不住"},{"n": "孜然粒","q": "腌料用100g、撒面用50g","a": "加到腌料150g、撒面80g香气更浓；减到腌料60g、撒面20g只剩辣椒味，孜然那种干燥回甜会消失"},{"n": "辣椒面","q": "100g","a": "加到150g辣度明显且颜色更正红；减到40g烤出来偏褐色，不够红亮"},{"n": "鸡蛋","q": "4个","a": "加到6个粘合效果更好、脆皮更整；减到1个容易烤裂掉皮"},{"n": "面粉","q": "150g","a": "这是脆皮的秘密武器，加到200g外壳更酥；减到50g则成不了那层金黄脆壳"},{"n": "辣椒油/辣子酱","q": "100ml","a": "最后刷油用，加到200ml更红亮油润；减到30ml干撒辣椒面颜色发暗"}],"steps": ["整羊处理干净：开膛去净内脏，斩去头蹄与多余油脂，反复冲洗腹腔血污，用刀在羊腿、羊背肉厚处划深刀口便于入味。","盐、洋葱块、姜片、蒜瓣、孜然粒（腌料用）、辣椒面全部加适量清水打成糊状腌料，拌入鸡蛋和面粉搅成能挂住肉的稠糊。","把腌料抹遍羊身内外，重点填满刀口、羊腔和羊腿之间的缝隙；整只用保鲜膜包紧，冷藏腌制8小时以上（过夜最佳），让盐和香料彻底渗入。","生火：备足优质无烟炭，先烧成白灰状态再放羊，架到烤架上或用铁签穿起固定；炭火要\"不见明火只见红炭\"，否则肉会发黑发苦。","先中火烤40分钟，让外层形成白亮的干皮；每20分钟转动一次烤架并刷一次辣椒油，全程保证受热均匀。","羊皮表面开始泛黄出油时，把剩余的辣椒面和孜然粒（撒面用）混合，分3-4次均匀撒在羊身上并立即用手拍打使其附着；这一步是烤全羊颜色红亮、味道透的关键。","继续大火烤40-60分钟，靠近火源处要不时翻动防止烤焦；判断标准是羊皮呈均匀的金黄棕色、羊腿肉能被刀轻松切下、油脂滋滋滴落成焦褐色。","取下静置20分钟让肉汁回渗再斩件，配馕饼或抓饭上桌，最后淋一勺热油并撒最后一层孜然粒。"],"key": "脆皮来自\"腌料里的鸡蛋+面粉\"这层糊衣，配合炭火由中火转大火、分3-4次撒辣椒面孜然粉拍打附着——一次性全撒必然烤糊发苦。","tip": "家里没有烤全羊条件，可做\"迷你版\"：用同样腌料腌 2kg 羊排或羊腿，200℃烤90分钟，中途翻面刷油2次，风味能到七八成。"},"新疆烤包子": {"time": "2.5小时","level": "中等","servings": "4-5人份（约12个）","ing": [{"n": "面粉","q": "500g","a": "加到600g皮更厚能兜住更多汤汁；减到400g则皮太薄、馅容易漏出来"},{"n": "羊腿肉","q": "600g","a": "加到800g馅更饱满；减到400g则包子太空，咬开不爆汁"},{"n": "羊油","q": "120g","a": "这是烤包子酥香的核心，加到200g更油润；减到40g皮会发干不酥"},{"n": "皮牙子（洋葱）","q": "400g","a": "加到500g水分更多更解腻；减到200g馅会偏干失去新疆风味的\"洋葱甜\"，也不够出汁"},{"n": "精盐","q": "12g","a": "加到18g咸度够压住羊肉；减到6g会太淡"},{"n": "孜然粉","q": "15g","a": "加到25g香料味更足；减到6g基本尝不出孜然"},{"n": "清水","q": "280ml（和面）","a": "加到320ml面偏软不易成型；减到240ml面太硬、包子会开裂"},{"n": "温水","q": "120ml（调馅）","a": "加到180ml馅更嫩多汁；减到60ml肉馅发紧咬不动"},{"n": "蛋黄液","q": "1个","a": "刷表面用，加到2个颜色更亮；减掉则上色靠辣椒油"},{"n": "黑芝麻","q": "10g","a": "加到20g口感更丰富；减到3g几乎看不出"}],"steps": ["面粉加清水和成稍硬的面团，揉至表面光滑，盖湿布醒发40分钟——这是烤包子皮烤出来有\"小气泡\"口感的前提。","羊腿肉切成1cm的肉丁（不要剁成肉泥，保留颗粒感才有新疆烤包子的嚼劲），皮牙子同样切细丁。","肉丁与洋葱丁加盐、孜然粉和温水，顺一个方向搅打上劲，让肉丁吸水发黏；再拌入切成小丁的羊油。","把馅料冷藏腌30分钟，同时面团继续醒发到能轻松拉开不反弹的程度。","面团搓条下剂，擀成直径约12cm、中间厚边缘薄的圆皮；放上约50g馅料，像包饺子一样收口捏紧，接口朝下摆成圆饼状——烤包子必须是这个扁平带褶的形状，不是包子形。","烤箱提前230℃预热，烤盘刷油或铺硅油纸，把包子接口朝下摆好，烤5分钟后表面定型。","取出刷上蛋黄液、撒黑芝麻，放回烤箱继续烤15-18分钟至底部金黄、上色焦脆；判断标准是底部呈深金棕色、敲起来有干脆的空响声。","出炉后趁热吃，可配砖茶或烤羊肉串一起。"],"key": "馅料必须\"顺一个方向搅打上劲\"并加温水打水，羊油要切小丁后拌入（不要化成油直接倒），这两步决定烤包子咬下去是爆汁香还是干巴巴一坨。","tip": "正宗新疆是用馕坑贴壁烤，家里用烤箱最省事；烤盘上垫锡纸可让底部更脆，上色不够时最后开上火烤2分钟上色。"},"青海手抓羊肉": {"time": "2.5小时","level": "简单","servings": "4人份","ing": [{"n": "带骨羊肉（羊排/羊腿）","q": "1.5kg","a": "加到2kg够6人；减到800g肉太少、只够3人且啃不过瘾"},{"n": "精盐","q": "20g","a": "青海做法是原味手抓，盐只做提味，加到40g会变成咸肉；减到8g则腥味压不住"},{"n": "花椒","q": "10g","a": "加到15g麻香更突出；减到3g几乎尝不出花椒味"},{"n": "白胡椒","q": "6g","a": "加到10g辛香更浓；减到2g香气单薄"},{"n": "姜","q": "30g","a": "加到50g去膻更彻底；减到10g腥味会返上来"},{"n": "料酒","q": "40ml","a": "加到60ml去腥彻底；减到15ml残留膻气"},{"n": "蒜","q": "40g","a": "蘸料用，加到60g蒜味更冲；减到15g则蒜香不足"},{"n": "香菜","q": "30g","a": "加到50g解腻效果更好；减到10g点缀作用"},{"n": "小米辣/辣椒面","q": "10g","a": "加到20g辣度明显；减到3g基本是清淡原味"},{"n": "醋","q": "20ml","a": "加到35ml酸香开胃；减到5ml只剩蒜味"}],"steps": ["羊肉斩成5cm左右的骨肉块，冷水浸泡2小时中途换水2次，把血水彻底泡出来——这一步是青海羊肉不膻的前提，产地好但也要去血水。","冷水下锅（一次加足，中途不加冷水），加姜片、料酒，大火烧开后仔细撇净浮沫，浮沫不撇净就会发浑发膻。","转小火保持汤面微微冒泡、不剧烈翻滚的状态慢煮1.5小时，期间绝不能大滚——大火滚煮会让肉质变柴纤维收紧；判断标准是筷子能轻松插进羊腿肉、但肉不散。","关火后在原汤中加盖焖30分钟，让肉吸收汤汁里的鲜味，捞出沥干；汤别倒，留下就是青海的\"羊汤\"，可下面条或直接喝。","趁热斩件装盘，讲究的连骨节大块斩开摆盘，保留骨髓和骨边筋膜的原味。","椒盐：花椒与白胡椒加少许盐在干锅小火炒香2分钟至微微发亮，研成粗粉装碟，这是最正统的青海吃法。","另一碟做\"蒜蘸\"：蒜末加盐、醋、香菜末、少量辣椒面拌匀；两种蘸料各配一份，任选。","肉上桌，配一碗滚烫的羊汤和几块饼，蘸椒盐吃。"],"key": "煮羊肉全程只放盐和去味香料，绝不能放八角桂皮花椒等重香料盖住原味，且必须小火不翻滚——青海手抓吃的就是肉本身的高原鲜甜。","tip": "没有高原羊肉可用普通绵羊或山羊肉替代，浸泡时间加倍到3小时并加少许白醋泡血水；蘸椒盐配大蒜和生抽一起吃最解腻。"},"甘肃洋芋搅团": {"time": "50分钟","level": "简单","servings": "3-4人份","ing": [{"n": "洋芋（土豆）","q": "1kg（约5个）","a": "加到1.5kg够5-6人；减到600g则一人一小团，不够饱"},{"n": "精盐","q": "8g","a": "煮洋芋时用，加到15g会偏咸；减到3g则洋芋本身寡淡"},{"n": "油泼辣子","q": "100g","a": "加到150g辣油更香；减到50g辣味不足，可用干辣椒面替代"},{"n": "蒜末","q": "40g","a": "加到60g蒜香更浓；减到15g不够味"},{"n": "葱花","q": "30g","a": "加到50g香气更足；减到10g只是点缀"},{"n": "香醋","q": "20ml","a": "加到35ml酸香开胃；减到5ml只剩辣"},{"n": "生抽","q": "20ml","a": "加到30ml咸鲜更足；减到5ml需另补盐"},{"n": "花椒粉","q": "5g","a": "加到10g麻香明显；减到1g基本无感"},{"n": "浆水（发酵酸菜水）","q": "150ml","a": "这是甘肃陇南/天水最地道的吃法，加到250ml酸汤味更足；减掉则只剩辣味版本"},{"n": "菜籽油","q": "80ml","a": "泼辣子用，加到120ml更油亮；减到30ml泼不出香味"}],"steps": ["洋芋去皮切成大块，冷水下锅加盐，大火烧开后转中火煮20-25分钟至筷子能轻松插透但边缘还没散烂——要煮得比\"刚好\"稍欠一点，太烂就捣不成团。","捞出沥干，趁热放入石臼或大盆中，用捣蒜器/擀面杖反复捣压成细腻的团；这一步叫\"搅团\"，必须趁热才捣得动、捣得细，凉了就结块。","捣到完全没有颗粒、质地紧实成团，能捏成团不散开即成标准状态；如果太干可加几勺热水再捣匀。","取小碗调\"酸辣汁\"：蒜末、香醋、生抽、少许盐、葱花、花椒粉拌匀，再按口味加辣椒面。","另取碗放油泼辣子，将烧到冒烟的菜籽油直接泼在辣椒面上，\"刺啦\"一声激出红油香。","吃法一（陇南天水浆水版）：舀一勺浆水兑进酸辣汁，搅匀后浇在洋芋团上。","吃法二（干拌版）：把油泼辣子直接浇在洋芋团上，加蒜末、葱花、香醋、生抽拌匀。","也可把洋芋团蘸着酸辣汁吃，或用切开的洋芋块蘸汁，块状吃口感更扎实。"],"key": "洋芋必须煮到\"筷子能插透但还没散\"就捞出，且要趁热捣——凉了的洋芋纤维已经定型，捣出来是带颗粒的沙团而非细腻的黏团。","tip": "选黄心的沙瓤洋芋最好，粉糯易捣；选白心脆性的品种口感偏硬。浆水就是自家腌的酸菜水，甘肃人视为灵魂，没有可用酸辣汁加醋替代。"},"兰州酿皮": {"time": "5小时","level": "稍难","servings": "3-4人份","ing": [{"n": "高筋面粉","q": "500g","a": "加到600g产量更多；减到350g洗出来的淀粉少，酿皮偏少"},{"n": "清水（和面）","q": "280ml","a": "加到320ml面偏软难成型；减到240ml面太硬不易洗出淀粉"},{"n": "清水（洗面）","q": "3L","a": "分4-5次用，加到4L洗得更净；减到2L面筋里会残留大量面糊"},{"n": "精盐","q": "8g","a": "加到12g更入味；减到3g基本是原味"},{"n": "辣椒油","q": "120ml","a": "兰州酿皮的灵魂，加到180ml更红油亮；减到50ml颜色发暗不够香"},{"n": "蒜","q": "40g","a": "加到60g蒜味更足；减到15g蒜水太寡"},{"n": "香醋","q": "40ml","a": "加到60ml酸度更足；减到15ml与辣椒油不搭"},{"n": "芝麻","q": "10g","a": "加到20g香更浓；减到3g几乎看不出"},{"n": "黄瓜丝","q": "100g","a": "加到150g爽脆感更强；减到30g只是配色"},{"n": "面筋（洗面所得）","q": "200g","a": "加到300g口感更厚实；减掉也行，兰州也有只吃酿皮的"}],"steps": ["面粉加清水揉成硬实面团，静置20分钟让面筋充分吸水；面团要揉到\"三光\"（手光、面光、盆光），太软会在洗面时糊掉。","把面团放入盆中加少量清水反复揉搓洗面，洗面水变得浓稠后倒出，反复4-5次，直到面团只剩一小团弹性面筋、水变清。","把历次洗面水合并静置沉淀3小时以上，让淀粉沉到盆底；倒出上层清水，盆底就是浓稠的淀粉糊。","淀粉糊上锅蒸制：蒸屉铺湿布或垫盘，把淀粉糊均匀倒入约1cm厚，大火蒸25-30分钟至完全凝固透明，晾凉后切成宽条即成酿皮。","同时把洗面剩下的面筋上锅蒸20分钟，晾凉切块备用。","调\"酸辣汁\"：蒜捣成蒜泥，加香醋、精盐、少量凉白开调匀备用——蒜泥要用凉水激一下才不会发苦。","碗底先铺黄瓜丝、面筋块，码上酿皮条，浇足量辣椒油，再淋酸辣汁、撒芝麻。","食用前从底部彻底拌匀，让每根酿皮都挂上红油和蒜汁——不拌开是干吃，拌开才是兰州味。"],"key": "洗面次数和沉淀时间决定成败：至少洗4-5次、沉淀不少于3小时，淀粉要足量否则蒸出来会散、会\"拉丝断条\"而不是完整的酿皮。","tip": "可以一次多洗一些淀粉糊冷藏备用（3天内用完），蒸制前若糊太稠加一点温水调稀；怕辣可辣椒油减半、另加蒜汁提味。"},"岐山臊子面": {"time": "1.5小时","level": "中等","servings": "3-4人份","ing": [{"n": "手工面条","q": "400g（干）","a": "加到500g够4人；减到300g一人份偏少"},{"n": "五花肉","q": "300g","a": "加到400g臊子更油润；减到200g则臊子发干不香"},{"n": "辣椒面（秦椒）","q": "50g","a": "岐山臊子的灵魂，加到70g辣色更正红；减到25g则只剩酱油色、失去\"油泼\"特色"},{"n": "岐山香醋","q": "80ml","a": "加到120ml酸度更足；减到40ml会失去那股\"酸出味\"的层次"},{"n": "豆腐（老豆腐）","q": "150g","a": "加到250g臊子里豆香更足；减到50g口感偏单调"},{"n": "鸡蛋","q": "2个","a": "加到3个蛋花更厚；减到1个汤面挂不住"},{"n": "高汤或清水","q": "700ml","a": "加到900ml汤更宽；减到450ml会咸、臊子挂不住"},{"n": "生抽","q": "30ml","a": "加到45ml颜色更深；减到10ml需另补咸味"},{"n": "青菜（小白菜/菠菜）","q": "200g","a": "加到300g解腻；减到80g会缺一口清甜"},{"n": "姜蒜末","q": "姜末20g、蒜末20g","a": "加到姜末30g、蒜末30g去腥提香更足；减到各10g则臊子发腻、蒜香撑不住"}],"steps": ["五花肉切成1cm的小丁（不是肉末，臊子要能嚼到颗粒），冷水下锅焯2分钟去血水，捞出沥干。","锅中放油烧至六成热，下肉丁中火煸炒5-6分钟，把肥肉熬出油、肉丁煸到表面焦黄发香——这一步\"煸\"出的猪油就是臊子的香气基底，不能用瘦肉末代替。","把多余猪油倒出留用，锅中下辣椒面，用小火慢慢\"油泼\"到辣椒面变成红油且微微冒泡（约1分钟）；判断标准是颜色由深褐转成透亮的枣红色，千万别用大火，一秒就糊。","下姜蒜末炒香，烹入香醋激出酸香（醋遇热油\"呲\"的一声，香气才出得来），加生抽、盐翻匀。","倒入高汤或清水烧开，下老豆腐切成的丁，小火煮5分钟让豆腐吸味入臊子。","另起一锅宽水烧开煮面，水要宽、火要猛；下面条煮到浮起后再点一次凉水，捞出时不能有硬芯，盛入大碗。","把臊子连汤浇在面上，用锅里的热汤把面\"烫\"热，撒上葱花。","磕开鸡蛋，用滚汤冲成蛋花飘在面汤上，配焯好的青菜，浇一勺原汁臊汤同食。"],"key": "辣椒面必须小火油泼到枣红透亮才能出红油，高火一秒即糊；臊子里的酸味靠\"热油烹醋\"激发，直接倒醋只有酸气没有醋香。","tip": "正宗吃法是\"酸辣香\"，觉得太酸可把醋减到50ml并多舀两勺原汤稀释；岐山人还要在碗里另加醋和辣椒油自调。"},"宝鸡擀面皮": {"time": "4小时","level": "稍难","servings": "3-4人份","ing": [{"n": "中筋面粉","q": "400g","a": "加到500g出品更多；减到300g则面皮偏少、需另配"},{"n": "清水（和面）","q": "220ml","a": "加到250ml面偏软；减到190ml面硬、擀不开"},{"n": "秦椒辣椒面","q": "60g","a": "宝鸡擀面皮的灵魂，加到90g辣味更足、色更红；减到30g只剩油而不香"},{"n": "菜籽油","q": "150ml","a": "用来泼辣椒面，加到200ml更油亮；减到80ml泼出来发干"},{"n": "盐","q": "6g","a": "和面用，加到10g面皮更筋道；减到2g口感发软"},{"n": "蒜","q": "40g","a": "加到60g蒜汁更冲；减到15g蒜香不足"},{"n": "香醋","q": "35ml","a": "加到50ml酸度更足；减到15ml太淡"},{"n": "生抽","q": "20ml","a": "加到30ml咸鲜更足；减到5ml需另补盐"},{"n": "黄瓜丝","q": "150g","a": "加到200g爽脆感强；减到50g仅作点缀"},{"n": "绿豆芽","q": "100g","a": "加到150g更脆；减到50g配料显少"}],"steps": ["面粉加盐和清水，揉成硬面团，反复揉10分钟至表面光滑，盖湿布醒30分钟——必须醒足，面不醒就擀不开、蒸出来会裂。","把面团放在案板上用力反复揉搓揉筋15分钟，揉到面团变得非常筋挺，此时面筋已充分形成；也可先烤/蒸一下再揉，更易出筋。","大盆中加清水，把面团按入水中反复揉搓洗面，洗面水变浓稠后滤出面水备用；重复4-5次，直到面团只剩一小团紧实的面筋。","把洗面水静置沉淀3-4小时，倒掉上层清水，底部沉淀的淀粉糊就是做面皮的原料；用勺子把淀粉糊表面的泡沫撇净。","取一只长方形不锈钢盘（擀面皮专用盘），刷一层油，倒入淀粉糊晃匀铺成薄薄一层，水开后上锅蒸5-8分钟，蒸到淀粉糊鼓起大泡并呈半透明即可取出。","趁热用小刀在边缘划一圈，小心揭下整张面皮，摊开放凉；面皮晾凉后切成5mm宽的细条，抖散防止粘连。","另做油泼辣子：辣椒面加盐，用烧至冒烟的菜籽油分两次泼入，激出红油香。","碗中放擀面皮条、焯过的绿豆芽和黄瓜丝，浇蒜汁（蒜末用凉水激开）、香醋、生抽，最后铺上厚厚的油泼辣子，拌匀即成。"],"key": "整个流程的命门是\"洗面沉淀\"——淀粉糊必须沉淀到足够浓稠（能挂住勺子不流），否则蒸出来是稀糊状的面汤而不是能挑起的面皮；揭皮必须在热时小心进行，凉后会粘连撕破。","tip": "用蒸凉粉的盘子代替不锈钢盘，蒸出来的皮更薄更透；吃不完的面皮晾干可存一周，回蒸或干拌都行。"},"宁夏滩羊": {"time": "2.5小时","level": "简单","servings": "4人份","ing": [{"n": "盐池滩羊（羊腿/羊排肉）","q": "1kg","a": "加到1.5kg够5-6人；减到600g则只够3人"},{"n": "精盐","q": "12g","a": "加到18g更入味；减到6g肉会发淡"},{"n": "姜","q": "20g","a": "加到30g去膻更足；减到8g残留腥气"},{"n": "大葱","q": "40g","a": "加到60g葱香更足；减到15g提香不够"},{"n": "料酒","q": "30ml","a": "加到50ml去腥更彻底；减到10ml腥味明显"},{"n": "干辣椒","q": "10g","a": "加到20g辣香更足；减到4g只有淡淡辣味"},{"n": "孜然粉","q": "6g","a": "加到10g西北味更浓；减到2g基本无味"},{"n": "蒜","q": "30g","a": "加到50g蒜香浓；减到10g不够味"},{"n": "香菜","q": "20g","a": "加到35g解腻；减到8g装饰作用"},{"n": "生抽","q": "25ml","a": "加到40ml更咸鲜；减到10ml需另补咸味"}],"steps": ["羊肉切块，冷水浸泡1小时去血水，中途换水；盐池滩羊本身几乎无膻，但去血水能让汤更清。","冷水下锅加姜、葱、料酒，大火烧开撇净浮沫，转小火煮1.5小时；判断标准是筷子能轻松插入肉中、汤面浮油呈清亮白色而非浑浊。","捞出一半羊肉改刀成小块做\"爆炒\"，另一半保持大块做\"手抓\"原味，两种吃法一锅出。","爆炒：锅烧热下油烧至七成热，把肉块下锅中火翻炒4分钟至表面焦黄逼出油脂，加干辣椒段、蒜片炒香。","加孜然粉、葱段、生抽，大火快炒1分钟至调料挂匀，撒香菜出锅——判断标准是肉块表面有一层亮红油光、孜然焦香爆出。","手抓部分：大块装盘，撒盐和少许胡椒粉即可，原味吃法最能尝出滩羊\"无膻\"的特点。","把煮肉的清汤过滤后撒葱花香菜，盛一碗上桌解腻。"],"key": "滩羊\"无膻\"靠的是品种不是调料，所以炖煮时只用姜葱料酒这些基础去味物，绝不能拿重香料去盖；一旦加了八角桂皮，反而失去滩羊的意义。","tip": "买不到盐池滩羊可用宁夏本地羊或滩羊的替代部位（羊肩肉）；炖汤剩下的清汤别倒，第二天用它炖白菜或下面条极鲜。"},"内蒙古手把肉": {"time": "2小时","level": "简单","servings": "5-6人份","ing": [{"n": "带骨羊肉（羊排+羊腿）","q": "2kg","a": "这是草原做法的分量，加到2.5kg够8人；减到1.2kg则不够分"},{"n": "精盐","q": "25g","a": "手把肉唯一的调料，加到40g会过咸发死；减到15g则肉香寡淡"},{"n": "姜","q": "30g","a": "加到50g去膻更足；减到10g膻味会返上来"},{"n": "大葱","q": "60g","a": "加到100g葱香更浓；减到20g香气太弱"},{"n": "花椒","q": "10g","a": "加到15g麻香明显；减到3g基本无感"},{"n": "料酒","q": "40ml","a": "加到60ml去腥更彻底；减到15ml残留膻味"},{"n": "韭菜花","q": "40g","a": "这是手把肉的经典蘸料，加到60g辛香味足；减到10g只有咸味"},{"n": "蒜","q": "40g","a": "加到60g蒜味更冲；减到15g蒜香不足"},{"n": "腐乳","q": "2块","a": "加到3块咸香更浓；减到1块也可"},{"n": "辣椒/油泼辣子","q": "30g","a": "加到50g辣味更足；减到10g基本是原味"}],"steps": ["羊肉按骨节分割成大块（每块约400-500g），冷水浸泡1.5小时去血水，中途换水两次；草原做法讲究\"大块\"，才像手把着啃的样子。","大锅一次性加足清水（约2000ml），放姜块、葱段、花椒、料酒，大火烧开。","烧开后仔细撇净所有浮沫，这一步是决定汤清肉不膻的关键；浮沫不撇净，整锅都会发浑发臭。","把羊肉块下锅，大火煮开转小火，保持汤面微微冒泡的状态煮1.5小时；全程不能大滚盖死盖——草原的手把肉靠\"水滚肉不滚\"来保持肉质不柴。","煮到用筷子能轻松扎进羊腿肉深处但肉不散开即关火，加盐（每500g肉约6g），再加盖焖30分钟让肉吃进盐味。","捞出沥干，用锋利的刀顺着骨节把肉斩成大块，连骨带肉上桌——手把肉就是抓着啃的，不要切成小片。","蘸料：韭菜花、蒜末、腐乳、辣椒拌成一大碗，浇一点原汤调成糊状；另备椒盐碟供清淡吃法。","配砖茶和奶食一起上桌，这是草原上吃手把肉的标准配置。"],"key": "手把肉只放盐（姜葱蒜料酒只是去味），绝不能放八角桂皮香叶；煮时\"水滚肉不滚\"、小火慢煮加焖，是肉不柴的关键。","tip": "斩肉时刀要快，一刀断骨不要来回锯，锯出来的碎骨渣会影响口感；吃不完的肉次日切片炒菜极香。"},"蒙古馅饼": {"time": "2.5小时","level": "中等","servings": "4人份（约10个）","ing": [{"n": "面粉","q": "500g","a": "加到600g饼皮更酥；减到400g则不易成型"},{"n": "羊腿肉","q": "600g","a": "加到800g馅更足；减到400g则馅少皮厚"},{"n": "大葱","q": "300g","a": "加到400g葱香更足、汁水更多；减到150g则馅偏干"},{"n": "姜末","q": "20g","a": "加到30g去膻去味更足；减到8g羊肉味太冲"},{"n": "花椒粉","q": "6g","a": "加到10g麻香突出；减到2g几乎无感"},{"n": "盐","q": "12g","a": "加到18g咸度够；减到6g则肉馅发腥"},{"n": "食用油（和面）","q": "60ml","a": "加到90ml饼皮更酥层次更多；减到30ml饼皮偏硬"},{"n": "温水（和面）","q": "280ml","a": "加到310ml面偏软；减到250ml面太硬开裂"},{"n": "清水（打馅）","q": "80ml","a": "加到120ml馅更嫩多汁；减到30ml肉馅发柴"},{"n": "土豆","q": "1个（约200g）","a": "草原馅饼常加土豆丁增饱腹，加到2个口感更绵；减掉也可以"}],"steps": ["面粉加温水和成稍软的面团，加20ml食用油揉至光滑，盖湿布醒40分钟——\"烫面+醒面\"是饼皮酥而不硬的关键。","羊腿肉切成小丁（保留颗粒，草原馅饼要嚼劲），大葱切碎末，土豆去皮切小丁。","肉丁加盐、姜末、花椒粉和80ml清水，顺一个方向搅打至上劲发黏，让肉馅吸饱水分；拌入葱末和土豆丁。","面团分成10份，擦少许干粉防粘，逐个擀成直径约14cm、中间略厚的圆片。","取一张皮放约80g馅料，边缘收拢捏出褶子花边，再用手把包子压扁成直径约12cm的厚饼——蒙古馅饼是压扁的扁圆形，不是鼓起的包子形。","平底锅刷油烧至五成热，放入馅饼，中小火煎3-4分钟至底面金黄酥脆。","翻面再煎3-4分钟，用手按压饼身确认两面都上色；判断标准是两面金黄、边缘层次分明、饼身按下去有弹性而不塌。","出锅后趁热吃，配砖茶或奶茶，也可以切块蘸蒜醋。"],"key": "馅肉必须打水（上劲）才嫩，同时保留小丁颗粒不能剁成肉泥；包好后要用手压扁成扁圆饼再煎，这才是蒙古馅饼\"皮酥馅大\"的正确形制。","tip": "用平底锅比烙饼机省事，锅温控制在160℃左右；一次多煎几个用小火保温，回锅时饼皮会更酥。"},"延吉冷面": {"time": "1.5小时","level": "中等","servings": "3-4人份","ing": [{"n": "荞麦面（朝鲜冷面）","q": "400g","a": "加到500g够4人；减到300g则一人份偏少。纯小麦面也可但少了荞麦的筋道与微苦回甘"},{"n": "牛肉（腱子/牛腩）","q": "400g","a": "加到600g汤更浓、肉更多；减到250g汤味会薄"},{"n": "牛骨","q": "500g","a": "加到800g冷面汤更白厚；减到300g汤不浓"},{"n": "黄瓜","q": "2根","a": "加到3根配菜更足；减到1根则少了爽脆口感和卖相"},{"n": "鸡蛋","q": "4个","a": "加到6个更丰盛；减到2个显单薄"},{"n": "泡菜（朝鲜辣白菜）","q": "150g","a": "加到250g酸味更足；减到50g只是点缀"},{"n": "香醋","q": "80ml","a": "冷面汤的酸度全靠它，加到120ml更酸更解腻；减到30ml会甜腻"},{"n": "白糖","q": "40g","a": "加到60g甜酸比例更柔和；减到15g会只剩酸和咸"},{"n": "辣椒油","q": "50ml","a": "加到80ml更香；减到15ml颜色不够红"}],"steps": ["牛骨冷水下锅焯水，加葱姜料酒煮开撇沫，加姜片、葱段、料酒，小火熬2小时成奶白牛骨汤，滤出备用。","牛肉下锅煮1.5小时至软而不散，捞出晾凉切成薄片；煮肉的汤留一部分做冷面汤底，剩下的当清汤喝。","冷面汤调味：取400ml牛骨汤放凉后加香醋、白糖、生抽、少许盐和蒜泥，搅匀后冷藏至冰凉——醋和糖必须用凉汤冲开，高温会让酸味挥发变钝。","荞麦面煮熟：宽水烧开下面，煮到无硬芯（约6-8分钟）后立刻捞出过两三遍冷水，抖散沥干，拌少许香油防粘。","黄瓜切细丝，泡菜切段或粗丝，鸡蛋煮8分钟后剥壳对半切或切片备用。","碗底先铺黄瓜丝、泡菜、鸡蛋和牛肉片，摆上沥干的冷面。","浇上冰凉的冷面汤至八分满，让面充分吸味（泡2分钟更入味）。","最后淋辣椒油、撒上葱花，从底部彻底拌开，冷热交替、甜酸咸辣齐上。"],"key": "煮好的面必须立刻过冷水并拌油防粘，否则会坨成一团；冷面汤一定要用凉汤冲调并且冷透——热汤冲醋只会得到又冲又酸又浑的汤。","tip": "正宗延吉冷面还会加\"梨干肉\"或煮牛肉片、泡菜、熟芝麻，冷吃为主；夏天配冷面汤和冰镇汽水最解暑。"},"哈尔滨红肠": {"time": "6小时","level": "稍难","servings": "5-6人份","ing": [{"n": "猪肉（肥瘦3:7）","q": "1.5kg","a": "加到2kg更够分；减到800g则灌出来的肠偏少"},{"n": "牛肉","q": "500g","a": "哈尔滨红肠经典是猪肉+牛肉，加到800g肉感更紧实；减掉也成立但口感偏松软"},{"n": "猪肥膘","q": "300g","a": "单独加的肥膘决定肠体的油润与弹牙，加到450g更香；减到150g会偏瘦偏柴"},{"n": "蒜末","q": "80g","a": "哈尔滨红肠的灵魂，加到120g蒜香更冲更正宗；减到20g则完全失去蒜肠特色"},{"n": "食盐","q": "45g","a": "按肉重1.9%配比，加到60g过咸；减到25g则不易保存"},{"n": "白胡椒粉","q": "15g","a": "加到25g辛香更足；减到5g香气不足"},{"n": "硝盐（亚硝酸盐）","q": "5g","a": "这是传统腌肉保色防腐用，家庭做建议减到2-3g，或改用少量比例的\"护色剂\"替代"},{"n": "肠衣（猪肠衣）","q": "2套","a": "加到3套更粗更有嚼劲；减到1套则灌得少"},{"n": "玉米淀粉","q": "80g","a": "加到120g口感更弹；减到20g则纯肉肠口感发柴"},{"n": "熏料（柏木/杨木屑+茶叶）","q": "200g","a": "加到300g烟熏味更足；减到80g只有煮肠味没有熏香"}],"steps": ["猪肉、牛肉、猪肥膘分别用刀剁成粗颗粒（保留2-3mm的颗粒，不要打成肉泥，这是红肠口感弹牙不似香肠的原因），也可绞肉机粗绞。","肉粒加盐、硝盐、蒜末、白胡椒、淀粉，顺一个方向搅打3-5分钟至上劲发黏，静置腌2小时。","洗肠衣：清水反复冲洗内外，用两根筷子从一端捅出翻面，去净油脂和杂质，再用清水冲几遍。","灌肠：用灌肠器或漏斗把肉馅灌入肠衣，灌到七分满（留出膨胀空间，灌太满煮时会破），末端用棉线扎紧，每隔15cm打一道结做出节状。","用针在肠体上扎几个小孔排气，挂在阴凉通风处晾2小时让表面收紧，这一步能让肠衣不破、形状规整。","下锅煮：水中加白胡椒粉、葱段、姜片，水温控制在80℃左右下肠，全程小火，保持\"虾眼水\"微沸状态煮40分钟；判断标准是肠体紧实有弹性、用手指按压能回弹。","捞出晾凉后进行熏制：熏锅底层放锯末与茶叶，密闭后小火慢熏1.5-2小时，中途翻动一次确保上色均匀；没有熏锅可用旧铁锅盖严后放阳台通风处熏一晚。","熏好后表面呈枣红油亮、富有蒜香和烟熏气即可，晾凉后斜切薄片装盘，可冷吃也可煎香后夹面包。"],"key": "肉必须粗绞成粒不能打成泥、灌肠只灌七分满并扎排气孔、煮制水温不超过85℃——这三条任何一条破了，肠衣就会爆、味道会发柴发死。","tip": "初次尝试可先做1kg的小份，用蒸锅代替煮锅（水温温和不易爆）；城市里买不到熏料可用少量柏木屑+茶叶末代替，切勿用松木（松脂味会串味发苦）。"},"地锅鸡": {"time": "1.5小时","level": "中等","servings": "4人份","ing": [{"n": "三黄鸡（整鸡或鸡腿）","q": "1.2kg","a": "加到1.5kg够5人；减到800g则贴的饼不够、汤也少"},{"n": "猪五花肉","q": "150g","a": "这是贴锅饼吸油的关键，加到250g饼更香；减掉则饼会干硬"},{"n": "郫县豆瓣酱","q": "40g","a": "地锅鸡的味底，加到60g更红更辣；减到15g会变成普通炖鸡"},{"n": "干辣椒段","q": "15g","a": "加到25g辣味更足；减到5g基本尝不出"},{"n": "姜片","q": "25g","a": "加到40g去腥更足；减到10g腥味返上来"},{"n": "蒜瓣","q": "30g","a": "加到50g蒜香浓；减到10g不够味"},{"n": "生抽","q": "40ml","a": "加到60ml咸度够；减到20ml需另补盐"},{"n": "玉米面（贴饼用）","q": "200g","a": "加到300g饼更粗糙吸汁更多；减到100g饼太细腻、挂不住汤"},{"n": "中筋面粉（贴饼用）","q": "150g","a": "加到250g饼有嚼劲；减到50g饼会碎"},{"n": "清水","q": "500ml","a": "加到700ml汤更多饼泡得更透；减到300ml会糊锅"}],"steps": ["鸡剁成3cm的块，冷水下锅加姜片料酒焯3分钟撇净血沫，捞出冲洗沥干——焯过水的鸡炖出来汤才清不浑。","五花肉切薄片，锅中不放油小火煸5分钟至出油、边缘微卷；利用煸出的猪油下豆瓣酱和干辣椒段，小火炒2分钟炒出红油——豆瓣的红油就是地锅鸡的颜色来源，不必另炒糖色。","下姜蒜片炒香，倒入鸡块翻裹均匀，加生抽炒至上色。","加清水没过鸡块，大火烧开后盖盖转小火炖25分钟，炖到鸡肉用筷子一夹就脱骨。","用玉米面加面粉和温水（比例约6:4）揉成偏硬的软面团，揪成小剂子擀成直径约8cm、厚5mm的圆饼；面团要硬，饼才能吸住汤而不烂。","把面饼逐个贴在锅边锅壁上（贴着锅壁、浸在汤里的上半部分），一个挨一个围成一圈，剩余汤汁刚刚没过饼底。","盖盖转中小火焖15-18分钟，期间不要开盖晃动；判断标准是饼底吸透汤汁变透亮、边缘金黄微焦。","开盖撒上葱花，沿锅边淋一圈热油激香，连锅端上桌直接揭盖吃。"],"key": "面饼必须一半贴在锅壁上、一半浸在汤里，才能同时做到\"下焦脆、上吸汁\"；贴完盖盖焖时绝不能开盖翻动，一翻饼就碎汤就浑。","tip": "没有玉米面可用全白面但口感略差；想吃更辣的可在豆瓣里再拌2勺剁椒；饼子多贴几个会更富裕，蘸汤吃最香。"},"昆明小锅米线": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "米线（细米线）","q": "400g（2份）","a": "加到500g则每份量足；减到300g一人份偏少。粗米线不行，要细的才挂得住肉帽"},{"n": "猪肉末（肉帽）","q": "150g","a": "加到250g肉帽更厚；减到80g汤味会薄、少了昆明\"小锅\"的灵魂"},{"n": "酸菜（腌酸菜）","q": "80g","a": "加到120g酸味更足；减到30g会失去那股酸爽"},{"n": "猪油辣椒面（油辣子）","q": "50g","a": "加到80g更香更辣；减到20g则辣味寡淡"},{"n": "韭菜花","q": "30g","a": "加到50g咸香味更足；减到10g只是点缀"},{"n": "豌豆尖/青菜","q": "150g","a": "加到250g解腻；减到60g缺一口绿色"},{"n": "肉片（猪里脊）","q": "100g","a": "加到150g料更足；减到50g偏素"},{"n": "骨汤/清水","q": "700ml","a": "加到900ml汤更宽；减到450ml会咸、挂不住料"},{"n": "蒜末","q": "20g","a": "加到30g蒜香更冲；减到8g不够蒜"},{"n": "味精","q": "3g","a": "加到5g提鲜明显；减到1g味道平淡"}],"steps": ["米线提前用温水泡30分钟至软而不烂，捞出沥干；用温水泡是为了下锅即熟，不会外熟内生。","小锅烧热下猪油（或用油辣子里的油）化开，倒入肉末，中火煸炒4-5分钟把肉末炒到发干、粒粒分明、微微焦黄——这就是\"肉帽\"，湿哒哒的肉末是失败的关键。","下蒜末炒香，加酸菜末炒1分钟逼出酸味，再加韭菜花、生抽、味精炒匀成\"肉帽\"。","倒入骨汤或清水烧开，保持滚烫。","转大火，先把米线抖散下入小锅，用筷子不断推动防止粘底，煮90秒至米线完全透热。","下肉片和豌豆尖，青菜烫20秒立刻关火——青菜久煮会发黄、失去那股清甜。","起锅前淋入油辣子和一勺热油激过的蒜末，趁热吃。"],"key": "肉末一定要\"煸干\"成粒粒分明的肉帽（下锅前肉末含水越少越好，煸到微微焦黄），这是小锅米线和普通米线汤的分野；全程用小锅一次一碗，火大汤滚才够香。","tip": "肉末可用肥瘦3:7的猪肉自己剁，比机器绞的更香；想省事可买现成肉末但要保证煸够干；酸菜必须是自己腌的云南酸菜，超市酸菜味道偏甜不正宗。"},"宣威火腿": {"time": "3小时","level": "稍难","servings": "6-8人份","ing": [{"n": "宣威火腿（整条后腿）","q": "1条约5kg","a": "整条腿是传统形态，能看到\"竹签骨\"和红圈；减到2kg的短腿风味弱、成本高；生吃务必选熟成一年以上的老腿"},{"n": "精盐","q": "400g","a": "按腿重8%配比，加到500g会过咸压死肉香；减到300g则不易入味、发酵味不足"},{"n": "葡萄糖/白糖","q": "80g","a": "加到120g发酵更活跃、色泽更红；减到30g色淡"},{"n": "花椒","q": "20g","a": "加到30g香辛料味更足；减到8g香料感不足"},{"n": "八角","q": "10g","a": "加到15g回甘更明显；减到4g层次变薄"},{"n": "桂皮","q": "8g","a": "加到12g药香更圆润；减到3g略显单薄"},{"n": "干辣椒","q": "15g","a": "加到25g辣香更足；减到5g只有咸香"},{"n": "蒜","q": "50g","a": "拍泥抹腿用，加到80g杀菌更彻底；减到20g表面容易长霉"},{"n": "清水","q": "2000ml（隔水蒸用）","a": "加到3000ml能完全没过火腿、蒸得更透；减到1200ml会露出腿面、蒸不透中心"},{"n": "白酒","q": "腌制用100ml、刷洗用50ml","a": "加到腌制150ml、刷洗80ml酒香与防腐力都更强；减到腌制50ml、刷洗20ml发酵不够、表面油垢也洗不净"}],"steps": ["选腿：宣威火腿取猪后腿，要求皮薄肉厚、腿形完整、股骨细；腌制前用竹签在腿的三个位置戳孔排气，这是\"打眼\"的工序。","炒料：盐、花椒、八角、桂皮、干辣椒、蒜泥一起小火炒香炒透，冷却后备用——盐必须炒过，生盐直接抹会发苦。","揉盐：把炒料配白糖、白酒，分3-4次均匀揉搓在火腿内外，每揉一次渗入一次，重点是腿根、蹄筋处这些厚肉部位。","堆码腌制：将火腿放在干净木缸或缸中，撒料堆压，上面压石板或重物，室温腌制7-10天，每天翻一次、揉一次；判断标准是肉色由暗红转为玫红、腿面渗出油水。","晾晒风干：腌好后用清水冲净表面余盐，用白酒擦洗表面，挂于通风阴凉处风干45天以上；这一步是\"火腿\"区别于\"咸腿\"的关键，表面的绿褐色霉菌层是正常发酵形成的。","陈化：风干后转入仓库继续熟成3个月到1年，时间越久香味越醇厚（云南\"老腿\"需1-3年）；判断标准是切开瘦肉呈玫瑰红色、肥肉透亮、香气浓郁无氨味。","食用：整腿隔水蒸2小时（火腿不能直接水煮，否则香味流失），晾凉后逆纹切薄片，肥瘦相间的\"红圈\"最香。","可生食切片配白酒，也可做火腿蒸蛋、火腿炒饭、火腿炖汤；切下的边角料别丢，煨汤极鲜。"],"key": "整个流程的命门是\"炒盐+打眼+石板压+长时间风干熟成\"这四步——盐不炒会苦、腿不打眼会在腌制中胀气爆裂、时间不足则只有咸味没有那股醇厚的发酵香。","tip": "自己制作用时半年以上；想快点尝到正宗味道可直接买云南本地1年以上的老火腿，蒸后切片生吃是最本分的吃法。真空包装的即食火腿风味偏淡，别用来炒菜。"},"大理乳扇": {"time": "2小时","level": "稍难","servings": "4人份","ing": [{"n": "新鲜牛奶","q": "1L","a": "加到1.5L可做更多；减到500ml只够做4小片"},{"n": "酸水（酸木瓜水或白醋）","q": "50ml","a": "这是让奶凝结的关键，加到80ml会结块过粗、口感发硬颗粒大；减到20ml结不成形"},{"n": "白糖","q": "40g","a": "加到60g甜度更协调；减到20g会偏酸"},{"n": "玫瑰糖","q": "30g","a": "大理乳扇的经典配餐，加到50g花香更明显；减到10g甜度略淡"},{"n": "白糖（卷内）","q": "50g","a": "卷乳扇时用，加到80g更甜；减到20g会露馅"},{"n": "蜂蜜","q": "30ml","a": "刷在烤好的乳扇上，加到50ml更亮更甜；减到10ml香气弱"},{"n": "熟花生碎","q": "30g","a": "夹馅用，加到50g口感更丰富；减到10g几乎尝不到"},{"n": "食用油","q": "20ml（刷锅用）","a": "用刷子薄薄刷一层即可，加到40ml会发腻；减到5ml容易粘锅、煎的时候会破皮"},{"n": "细竹签/苇杆","q": "10根","a": "卷乳扇用，加到20根可多做；减到5根份数不够"},{"n": "辣椒面/玫瑰酱","q": "15g","a": "甜口之外的咸口吃法，加到25g味道更立体；减掉只吃甜味也成立"}],"steps": ["牛奶倒入不锈钢盆或厚底锅，中火加热到锅边冒小泡、约60-70℃时离火——不能煮沸，沸腾会导致奶质粗硬、无法拉出薄片。","把酸水（酸木瓜水最好，没有可用白醋加几滴白酒）一次性倒入，静置1-2分钟不要搅动，奶会自然凝结成絮状奶块。","用勺子轻轻压散奶块，舀进纱布袋在清水下冲洗去酸味，挤干水分备用。","取一块奶块放在干净案板上，用手指反复搓揉、推压、抻拉，让它变成薄而匀的奶膜；这一步是乳扇成形的关键，必须有耐心慢慢拉薄，拉不动就再搓热。","把奶膜缠在细竹签上卷成扇形，层层叠绕成巴掌大的扇形饼，用力压紧定型。","把成型的乳扇放在通风处晾干，或用烤箱50℃低温烘2-3小时，晾到质地干脆、颜色微黄即成乳扇干；判断标准是拿起来有硬度、掰开会\"咔\"地断开。","食用前把乳扇干刷一层薄油，用平底锅或炭火小火慢煎两面各1-2分钟，煎到表面起小泡、边缘微微焦黄、奶香四溢。","出锅后卷上白糖或玫瑰糖、夹熟花生碎，淋一点蜂蜜，趁热吃口感最好（凉了会变硬失去奶香）。"],"key": "酸度决定成败——酸水不足结不出奶絮，酸水过量则奶块粗硬颗粒重；温度同样关键，奶温超过70℃就煮\"老\"了，无论怎么拉都拉不出薄而韧的乳扇膜。","tip": "没有牛奶可用奶粉冲调，但口感和拉膜难度都会下降；酸木瓜水在云南菜市场或网上有售，用它做出的味道比醋正宗得多。"},"丽江粑粑": {"time": "1.5小时","level": "中等","servings": "4人份（约10个）","ing": [{"n": "面粉","q": "400g","a": "加到500g出品更多；减到300g则面团太硬、开裂"},{"n": "猪油或食用油（和面）","q": "80g","a": "丽江粑粑起酥的关键，加到120g更酥；减到30g层次感明显减弱"},{"n": "白糖（面团用）","q": "30g","a": "加到50g面团更柔；减到10g会发硬难开"},{"n": "温水（和面）","q": "210ml","a": "加到240ml面偏软；减到180ml面太干易裂"},{"n": "红糖/玫瑰糖（馅）","q": "200g","a": "加到300g甜馅更足；减到100g甜味偏淡"},{"n": "白糖（馅）","q": "60g","a": "加到100g甜度更好；减到20g只有红糖的焦香"},{"n": "猪油（煎制）","q": "60g","a": "煎粑粑用，加到90ml更酥更香；减到20ml容易粘锅"},{"n": "葱花（咸口可选）","q": "40g","a": "丽江粑粑有咸口葱油版，加到60g葱香足；减掉做甜口"},{"n": "酵母","q": "4g","a": "加到6g发得更蓬；减到2g香气不足"},{"n": "熟芝麻","q": "15g","a": "加到25g香更浓；减到5g几乎无感"}],"steps": ["面粉加酵母、白糖、温水揉成光滑面团，加猪油继续揉到面团起膜、能拉出薄膜，盖湿布发酵至两倍大约60分钟。","发好的面团排气，分成10份，擀成直径约15cm的薄圆片；擀的时候中间厚边缘薄，这样煎的时候边缘会起酥边。","甜口做法：红糖加白糖、芝麻、10g猪油小火加热搅拌成能流动的糖馅（不要煮得太稠，否则包不进去会漏）；咸口做法：葱花加10g猪油和盐拌匀。","在面片上抹匀馅料，从一边卷成长卷，再盘成蜗牛状或直接卷成条，静置10分钟让面皮回软定型。","平底锅烧热加猪油烧至四成热，放入粑粑，中小火慢煎3-4分钟至底面金黄，用锅铲压平使其贴锅。","翻面再煎3-4分钟至两面金黄酥脆、判断标准是表面起细密酥层、边缘出现焦黄斑、闻起来有芝麻与糖的焦香。","出锅后趁热撒少许熟芝麻增加香气；丽江粑粑的\"薄\"是关键，凉了会回软，煎好就要吃。"],"key": "粑粑要\"薄而酥\"，面团必须加足猪油揉到起膜、发到两倍大，馅料只抹薄薄一层——馅太多或面太厚都会变成厚实的甜面饼，失去丽江粑粑的酥脆感。","tip": "丽江粑粑分\"厚粑粑\"和\"薄粑粑\"，厚的是发面版（内软），薄的是酥油版（层次多）；甜馅可用红糖加花生碎，咸口用葱花加火腿末也很好吃。"},"南宁老友粉": {"time": "1小时","level": "中等","servings": "3人份","ing": [{"n": "柳州米粉","q": "400g","a": "加到500g够4人；减到300g一人份偏少"},{"n": "酸笋","q": "200g","a": "老友粉的\"臭\"全靠它，加到300g味道更冲更正宗；减到80g会变成普通酸辣粉"},{"n": "豆豉","q": "25g","a": "加到40g发酵咸香更浓；减到8g那股独特豆香就没了"},{"n": "蒜头","q": "50g","a": "加到80g蒜味更足；减到20g不够蒜香"},{"n": "指天椒/小米辣","q": "15g","a": "加到25g辣度明显；减到5g基本不辣"},{"n": "黄豆酱/甜面酱","q": "30g","a": "加到50g酱香更厚；减到10g汤会偏淡"},{"n": "猪骨汤或清水","q": "800ml","a": "加到1L汤更足；减到500ml会咸、料挂不住"},{"n": "牛肉/猪杂/叉烧","q": "200g","a": "加到300g料更足；减到100g太素"},{"n": "油辣椒","q": "60ml","a": "加到90ml更香更辣；减到20ml颜色淡"},{"n": "香醋","q": "20ml","a": "加到35ml酸度更足；减到5ml只有辣没有酸"}],"steps": ["酸笋切碎，用清水冲洗一遍挤干水分——冲洗是为了去掉过强的酸臭、留下发酵的醇香，这一步处理得好不好直接决定老友粉是\"香\"还是\"冲\"。","锅中放油烧热，下豆豉小火炒2分钟炒出豆香至微微发红，下蒜末和指天椒继续炒1分钟出蒜香，注意火不能大，蒜末一焦就苦。","下酸笋碎转中火炒3分钟，不停翻炒逼出酸笋的香气，这一步\"炒酸笋\"是老友粉与普通酸辣粉最大的区别。","加黄豆酱炒匀，倒入骨汤或清水烧开，转小火熬5分钟让各种味道融合成汤底，尝味后补盐。","米粉另锅煮熟（或用温水泡软后下汤锅），捞出沥干放入碗中——老友粉的米粉要能挂得住浓汤。","碗中码上牛肉片或叉烧，浇上滚烫的老友汤，汤要没过米粉。","淋入油辣椒和香醋，趁热拌匀从底部翻起吃；酸笋可以再单独加一勺在面上。"],"key": "\"炒酸笋\"和\"炒香豆豉蒜末\"这两步小火慢炒是老友粉的命门，火大会苦、火小不出香；酸笋必须冲洗后再炒，否则只剩刺鼻的酸臭而没有醇香。","tip": "不能吃太酸的人可以先不放醋、吃时再加；正宗南宁人爱在粉里加\"油炸黄豆\"或\"烧卤\"，也可用腐竹换成油条段。"},"玉林牛巴": {"time": "4小时","level": "稍难","servings": "5-6人份","ing": [{"n": "黄牛后腿肉（腱子）","q": "1.5kg","a": "必须选带筋的腱子肉，加到2kg更足；减到800g会太紧、嚼不动"},{"n": "南乳（腐乳）","q": "3块","a": "玉林牛巴的灵魂，加到5块酱香更浓；减到1块风味明显不足"},{"n": "腐乳","q": "2块","a": "加到4块颜色更红；减到1块略淡"},{"n": "豆豉","q": "20g","a": "加到30g咸香更足；减到8g香气弱"},{"n": "白酒","q": "50ml","a": "加到80ml酒香更足；减到20ml去腥和增香都不够"},{"n": "清水","q": "3000ml（没过牛肉）","a": "加到4000ml能完全浸没、卤汁更清淡；减到2000ml会露出肉面、卤不匀"},{"n": "熟白芝麻","q": "10g","a": "加到20g香更浓；减到3g几乎无感"},{"n": "卤料（甘草片、八角、桂皮、花椒）","q": "甘草5g、八角5个、桂皮10g、花椒8g","a": "是卤汁的香底，加到甘草8g、八角8个、桂皮15g、花椒12g香更厚；减到甘草2g、八角2个、桂皮5g、花椒3g则香单薄"}],"steps": ["牛肉选后腿腱子（带明显筋纹的整块），切去表面筋膜和多余脂肪，保留筋——玉林牛巴之所以有嚼劲，全靠这些筋。","整块冷水浸泡2小时去血水，中途换水两次，泡到水基本清亮。","冷水下锅加姜、葱、料酒焯3分钟撇净血沫，捞出用温水冲洗干净，沥干。","锅中加清水3L烧开，下南乳、腐乳（压碎）、豆豉、卤料（甘草片、八角、桂皮、花椒）和白酒，烧开转小火熬20分钟成卤汁。","下牛肉块，用小火慢卤2.5-3小时，期间不加盖、保持微沸；判断标准是用筷子能插入但略有阻力，瘦肉中心还带一点暗红——太软就过了。","关火后加盖焖1小时让牛肉充分吸收卤汁，捞出沥干卤汁，晾凉。","晾透后切成0.5cm的薄片或1cm的条；正宗玉林牛巴是切条，方便夹在馒头或米粉里吃。","食用时配熟芝麻，可干吃也可以下锅加少许卤汁翻炒；拌面、夹烧饼都极香。"],"key": "火候是全部——小火微沸卤2.5-3小时、关火焖1小时，卤到\"筷子能插但有阻力\"即停手；卤过头肉会散成渣，卤不够则纤维粗硬不入味，焖那一步是让味道吃进筋里的关键。","tip": "没时间卤3小时可用高压锅（保持上汽后40分钟），但收汁后一定要再放回卤汁里焖1小时补味；剩余卤汁别倒，滤渣后冷藏可再卤别的肉。"},"柳州螺蛳粉": {"time": "3小时","level": "稍难","servings": "3-4人份","ing": [{"n": "柳州米粉","q": "400g","a": "加到500g够4人；减到300g一人份偏少"},{"n": "石螺/田螺（带壳）","q": "1.5kg","a": "自己吐沙做汤底，加到2kg汤味更浓；减到800g则螺味不足"},{"n": "猪骨/鸡骨","q": "800g","a": "加到1kg汤底更浓白；减到400g螺汤会单薄发苦"},{"n": "酸笋","q": "200g","a": "柳州螺蛳粉的灵魂，加到300g\"臭香\"更足；减到80g只剩普通酸辣味"},{"n": "油炸花生米","q": "60g","a": "加到80g香脆感强；减到30g口感偏软"},{"n": "木耳（水发）","q": "80g","a": "加到120g更丰富；减到30g配料偏少"},{"n": "油辣椒","q": "80ml","a": "加到120ml更香更红；减到30ml颜色发暗"},{"n": "鹌鹑蛋/卤蛋","q": "6个","a": "加到10个更饱腹；减到3个显单薄"},{"n": "鸡爪/猪脚（卤味）","q": "200g","a": "加到300g料更足；减到100g汤料不平衡"},{"n": "高汤/清水","q": "2L（煮螺汤用）","a": "加到3L螺汤更宽；减到1.5L容易煮干发苦"}],"steps": ["石螺提前用清水加几滴油养24小时吐沙，反复搓洗去掉螺身黑膜；吐沙不彻底汤会发苦、有泥味。","猪骨冷水下锅焯水洗净，加姜片、葱段、料酒熬2小时成白色高汤，滤出备用。","螺钳开壳取螺肉，螺肉剁碎（保留一点颗粒口感），螺壳洗净；把高汤倒入大锅，加螺壳大火烧开转小火熬1.5小时，熬出浓白螺汤后过滤，这一步是柳州螺蛳粉正宗汤底的关键（商用多用螺肉骨汤浓缩）。","酸笋切丝泡在少量清水里去多余酸味；木耳切丝焯水；花生米炸酥备用。","另起锅做\"炒酸笋\"：热锅冷油下酸笋丝中火炒2分钟至香气逼出，加豆豉末炒香——这一步让酸笋的\"臭\"变成\"香\"。","米粉下沸水煮8-10分钟至断生，捞出用冷水冲一下沥干，装碗。","碗底放炒酸笋、木耳、花生米、鹌鹑蛋、鸡爪或猪脚，浇上滚烫的螺蛳汤。","淋上大量油辣椒，撒葱花，配一瓶酸笋或炸豆皮同食。"],"key": "汤底必须用螺肉和螺壳真材实料熬出\"螺味\"（至少1.5小时），这是外面用\"螺蛳粉料包\"替代不了的；配菜中的炒酸笋不能省，直接用生酸笋泡汤出不来那股\"臭香\"。","tip": "嫌麻烦可买螺蛳粉汤料包打底，但一定要自己熬一锅螺壳汤再混进去，并配足酸笋；腐竹、花生、卤蛋齐全才够正宗。"},"烤苕皮": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "红薯粉（苕皮粉）","q": "200g","a": "加到300g可做更多；减到120g份量少且不好摊"},{"n": "清水（调糊）","q": "450ml","a": "粉水比约1:2.2，加到550ml会太稀摊不成形；减到350ml糊太稠不易摊薄"},{"n": "泡椒/酸萝卜粒","q": "150g","a": "重庆烤苕皮的核心配料，加到250g酸辣味更足；减到60g会太寡淡"},{"n": "豆干/腊肉丁","q": "80g","a": "加到120g料更足；减掉也成立，纯酸萝卜版也很好吃"},{"n": "辣椒油","q": "60ml","a": "加到90ml更香更红亮；减到20ml味道不够"},{"n": "花椒粉","q": "5g","a": "加到8g麻香突出；减到2g几乎无感"},{"n": "蒜末","q": "15g","a": "加到25g蒜味更冲；减到5g不够味"},{"n": "葱花","q": "20g","a": "加到30g香气足；减到8g点缀"},{"n": "香醋","q": "10ml","a": "加到20ml酸度更足；减到3ml基本尝不出"},{"n": "食用油","q": "30ml","a": "摊苕皮时刷油用，加到50ml更不粘；减到10ml易破皮"}],"steps": ["红薯粉加清水搅成无颗粒的稀浆，静置30分钟让粉充分吸水糊化——不静置直接摊会开裂发不起来。","平底锅刷油烧至六成热，倒入一薄层粉浆（约2-3mm厚），立即转动锅子摊成均匀的圆片。","中小火煎2-3分钟，苕皮边缘会自然翘起、底面呈半透明黄褐色即可，不可煎太焦；翻面再煎30秒。","取出摊在案板上晾至微温，苕皮凉了会更Q弹，太热时不好卷。","酸萝卜粒、豆干丁加蒜末、香醋、少许辣椒油拌成馅料。","把苕皮对折开口，用勺子把馅料塞进折缝里，再卷成筒状或两头对折成长条；重庆做法通常塞满后再抹一层辣椒油。","刷足辣椒油，撒上花椒粉、葱花。","再回锅小火烤1分钟让苕皮微微回软起泡，撒葱花即可出炉；刚出炉的苕皮外脆内糯、微微拉丝最香。"],"key": "苕皮粉与水的比例和静置糊化决定成败——粉太多摊不开、太少会碎；摊皮厚度控制在2-3mm，煎到半透明就够，煎久了会硬失去\"软糯拉丝\"的口感。","tip": "没有红薯粉可用木薯粉或红薯淀粉替代，风味略逊；酸萝卜必须用泡椒味或酸辣味、切成小粒才有那股重庆街头味。"},"狼牙土豆": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "土豆（中等大小）","q": "3个约600g","a": "加到4个约800g够4人；减到2个份量少不够抢"},{"n": "折耳根（鱼腥草）","q": "80g","a": "贵州做法里的灵魂，加到120g冲味更足；减到30g特色变淡、只剩普通土豆"},{"n": "辣椒面","q": "20g","a": "加到30g辣味更足；减到8g味道寡淡"},{"n": "蒜末","q": "25g","a": "加到40g蒜香更浓；减到10g不够蒜"},{"n": "葱花","q": "25g","a": "加到40g香气足；减到10g装饰作用"},{"n": "香醋","q": "20ml","a": "加到30ml酸香更开胃；减到8ml只有辣没有酸"},{"n": "生抽","q": "20ml","a": "加到30ml咸鲜更足；减到8ml需另补盐"},{"n": "白糖","q": "4g","a": "加到8g甜味能提鲜并压住辣；减掉会只剩咸辣"},{"n": "花椒粉","q": "4g","a": "加到7g麻香突出；减到1g无感"},{"n": "食用油","q": "1500ml（没过土豆条）","a": "加到2000ml可以一次炸更多；减到800ml就得分2-3批炸，油温掉下去会吸油发软"}],"steps": ["土豆去皮，用波浪刀（花刀）沿土豆表面切出连续的菱形纹路，纹距约1cm、深约2/3——切太浅炸不出造型，切太深会断成碎块。","切好的土豆条立刻用清水反复冲洗3遍洗掉表面淀粉，捞出沥干并用厨房纸彻底吸干；这一步决定炸出来是脆的还是黏的。","锅中倒油烧至六成热（约180℃），下土豆条中火炸3-4分钟至定型捞出；油温升到八成热（约210℃）复炸40秒至表面金黄起泡，捞出控油。","另取碗调汁：蒜末、辣椒面、花椒粉、葱花、白糖、生抽、香醋拌匀。","土豆条趁热倒入碗中，快速翻拌让每一条都均匀裹上调料汁。","折耳根切成小段，最后撒进碗里再拌两下——折耳根不能久拌久焖，否则那股特有的鱼腥清香会散掉，只剩草腥味。","装盘后撒一把葱花，趁热吃；土豆凉了就回软失去外脆内糯的层次。"],"key": "土豆必须洗掉淀粉并彻底吸干水才能炸得脆；折耳根最后放且只拌两下——它是靠挥发性芳香物质提味的，早放早拌香味就跑了，剩下土腥味。","tip": "没有波浪刀可用普通刀在土豆表面斜切出网纹（每刀间隔1cm、深度一致），成型的菱形块效果稍逊但口感一样；想更香可加炸花生碎或香酥腐竹。"},"天水麻辣烫": {"time": "40分钟","level": "中等","servings": "3-4人份","ing": [{"n": "宽粉（干）","q": "200g","a": "加到280g汤会变稠挂不住料汁，需同时多加100ml清水；减到120g则一人一小碗不够吃，宽粉吸汤发涨要按干重算"},{"n": "甘谷辣椒面","q": "30g","a": "加到50g辣度明显上一个台阶、油色更红但发苦发燥；减到15g只剩香气没有辣味，麻辣烫变成清汤面"},{"n": "菜籽油","q": "150ml","a": "泼辣椒面专用油，加到250ml辣椒全部泡成糊、油亮但入口油腻；减到80ml辣椒面烫不熟、糊香出不来"},{"n": "大蒜","q": "4瓣","a": "加到6瓣蒜味冲、压过豆皮和青菜的味道；减到2瓣蒜香不足，料汁会偏单薄"},{"n": "生抽","q": "25ml","a": "加到40ml咸鲜味明显、需减盐；减到10ml则只有辣没有鲜，底味发空"},{"n": "香醋","q": "20ml","a": "加到35ml酸味突出、能解腻但会盖住辣味；减到8ml只剩回甜，麻辣的层次感出不来"},{"n": "白芝麻","q": "10g","a": "加到20g香气更浓但易有生味；减到3g几乎尝不到，糊辣香就不完整"},{"n": "花椒粉","q": "3g","a": "加到6g麻味重、舌尖发木容易盖住甘谷辣椒的香；减到1g则基本没有麻，不能叫麻辣烫"},{"n": "豆腐皮","q": "4张（约150g）","a": "加到6张更耐吸汤、蛋白质足；减到2张素味不足、配菜太单一"},{"n": "上海青","q": "250g","a": "加到350g汤色更清绿；减到150g则配菜偏少，一碗主要是粉"}],"steps": ["宽粉用温水泡30分钟至完全软透，捞出剪成10cm段；上海青洗净掰开，豆腐皮切宽条备用。","菜籽油倒入小碗至三分之一满，烧至六成热（约170℃），离火静置10秒降温至160℃左右备用。","取干碗放甘谷辣椒面、白芝麻，先浇一勺热油激出红油并用勺子大力搅5秒，再浇第二勺继续搅，如此\"三泼两搅\"，直到辣椒面全部泡成红油、发出焦香而不发黑。","大蒜捣成细泥，与生抽、香醋、花椒粉、少许盐调成料汁，静置5分钟让蒜泥出味。","烧一锅宽水，水开下宽粉煮4分钟至无硬芯，捞出过一遍凉开水；同锅烫上海青30秒、豆皮20秒，一起沥干。","碗底先放料汁和一勺红油，再铺宽粉、豆皮、青菜，浇入煮粉的原汤约150ml，汤要刚好没过粉面。","上桌前撒白芝麻、葱花，再淋一勺热油激香，趁烫拌开吃。"],"key": "油泼辣椒是这道菜的灵魂：油温太高（冒烟）会把辣椒面烫焦发苦，太低（低于140℃）则激不出红油，只剩干辣椒味；必须六成热、分三次泼、每次泼完立刻搅动。","tip": "怕辣的人把甘谷辣椒面减到15g、花椒粉减到1g，靠红油的香和蒜味撑住；天水本地的做法还会加一小勺炒香的油泼辣子（整颗辣椒焙香剪碎），想更正宗可加。"},"淄博小饼烧烤": {"time": "50分钟","level": "稍难","servings": "3人份","ing": [{"n": "中筋面粉","q": "250g","a": "加到300g可多做2张小饼，饼更挺括好卷；减到200g饼偏小偏软，容易在卷肉时破"},{"n": "温水（35℃）","q": "140g","a": "加到165g面变软粘手、饼心会塌；减到120g面太硬难开、饼发干不挂酱"},{"n": "五花肉","q": "400g","a": "加到600g够4-5人吃但每串肉少；减到300g每人约100g，偏少需要多配素串"},{"n": "羊尾油","q": "80g","a": "加到150g滋滋声更响、油脂滴到炭上冒烟起烟气最香；减到30g烤出来偏干，需要多刷两次油"},{"n": "大葱","q": "2根","a": "加到3根葱香更足、卷起来更解腻；减到1根则每卷都吃不到葱，串味"},{"n": "大蒜","q": "6瓣","a": "加到10瓣蒜蓉酱更冲更解腻；减到3瓣蒜味淡，压不住羊肉膻味"},{"n": "甜面酱","q": "60g","a": "加到100g酱香甜浓、蘸着吃很上瘾；减到30g则只剩辣，淄博的甜酱特色就淡了"},{"n": "辣椒油","q": "40g","a": "加到70g辣度提升、适合重口；减到15g只吃得到酱的甜，辣味完全靠串上的辣椒面"},{"n": "孜然粉","q": "10g","a": "加到18g孜然味盖过肉味；减到4g只剩生孜然草味，需选新疆孜然而非北方花椒孜然"},{"n": "盐","q": "5g","a": "加到8g腌肉偏咸、蘸酱也救不回来；减到3g肉串味道寡淡"}],"steps": ["面粉加温水揉成偏硬的面团（比馒头面硬、能拉起不粘手），盖湿布醒20分钟，擀成薄片刷一层油，卷紧成条再擀成小圆饼，饼直径约10cm。","平底锅不放油小火干烙小饼，两面各烙1分钟至微黄起鼓，边缘出现焦斑后取出（烙好的饼放凉更挺括）。","五花肉切2cm见方的块，加盐、孜然粉抓匀腌20分钟，肥瘦相间串成串，每串3块，串顶抹一小块羊尾油。","炭火中火或烤箱上下火200℃，肉串离火约8cm烤5分钟，中途翻面2次并刷一层油，边角焦香、肉块边缘发白时移到火旺处再烤2分钟。","蒜剁成细泥，与甜面酱、辣椒油、少许清水调匀成能挂在小饼上的稀稠度，静置10分钟让蒜味释放。","吃法：取一张小饼摊开抹酱，放1-2串肉，夹入切成马蹄段的葱白，卷起后整根蘸酱咬下。","配烤蔬菜：烤茄子皮、烤豆腐皮、烤韭菜，火候与肉串同步，最后蘸同一碗酱。"],"key": "小饼必须薄而不破：面要揉得比馒头硬、卷紧后再擀，烙到边缘起焦斑才够挺括，能托住肉和酱而不塌。","tip": "在家做最省事的是用电饼铛或平底锅烙小饼，一次多烙几张放凉保存；蘸酱里蒜末别现剁现用，剁好静置10分钟味道完全不同。"},"铁板鱿鱼": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "鲜鱿鱼须","q": "400g","a": "加到600g需分两锅煎、否则出水太多变成煮鱿鱼；减到250g摆盘好看但不够吃"},{"n": "洋葱","q": "半个（约150g）","a": "加到1个洋葱甜味更足、能衬出酱香；减到50g铁板只有酱没有甜味垫底"},{"n": "大蒜","q": "4瓣","a": "加到8瓣蒜香扑鼻；减到2瓣则酱里带生蒜腥味"},{"n": "甜辣酱","q": "60g","a": "加到90g酱汁更稠、裹得厚；减到30g挂不住肉，摊开只剩一层薄味"},{"n": "生抽","q": "15ml","a": "加到25ml咸味足、需减盐；减到5ml酱汁只有甜辣没有咸味兜底"},{"n": "料酒","q": "15ml","a": "加到25ml去腥更彻底但酒味会留在热铁板上；减到5ml腥味压不住"},{"n": "孜然粉","q": "5g","a": "加到10g香料味明显盖过甜辣；减到2g只剩酱香"},{"n": "辣椒面","q": "5g","a": "加到12g辣度上一个台阶、颜色更红；减到1g基本不辣，适合给孩子吃"},{"n": "熟白芝麻","q": "5g","a": "加到12g口感更丰富；减到2g几乎看不见"},{"n": "铁板食用油","q": "30ml","a": "加到50ml铁板更滑、鱿鱼不粘；减到10ml容易粘板、鱿鱼须一铲就断"}],"steps": ["鱿鱼须洗净沥干，划十字花刀或切段；用料酒、少许盐抓匀腌10分钟去腥，腌好后擦干水分。","铁板或厚底厚底锅烧至冒青烟，倒入食用油，油面出现细密纹路即达到八成热（约200℃）。","先下洋葱丝或洋葱圈摊开，中火翻炒1分钟至边缘焦黄出甜味，拨到铁板两侧。","下鱿鱼须猛火快煎2-3分钟，用铲子不断翻动，煎到表面起密集水泡、边缘卷曲、鱿鱼须收紧变挺。","另取小碗调汁：甜辣酱+生抽+蒜末+少量清水搅匀；沿铁板边缘淋入酱汁，猛火翻匀让每根鱿鱼都挂上酱。","撒孜然粉、辣椒面、白芝麻，翻两下立刻出锅，最后挤几滴柠檬汁提鲜。","装盘后趁热吃，放凉了鱿鱼回软、酱汁也结块发黏。"],"key": "铁板要烧到冒烟再下油，油够热才能瞬间封住鱿鱼须表面的水分，形成\"弹\"的口感；火候一软就变成水煮鱿鱼。","tip": "街边摊的甜辣酱多是番茄酱+辣椒酱+蜂蜜+白醋+少许蚝油自己熬的，家里照做味道更接近；甜辣酱太稠要加两勺热水化开，不然会糊锅。"},"脆皮五花肉": {"time": "60分钟","level": "中等","servings": "3-4人份","ing": [{"n": "带皮五花肉","q": "500g","a": "加到800g需分两盘烤、脆度不均；减到350g每人不到100g，垫肚子不够"},{"n": "麦芽糖（可换蜂蜜）","q": "15g","a": "加到30g上色更深亮、脆壳更厚；减到5g皮色发白不上色，卖相差"},{"n": "老抽","q": "15ml","a": "加到25ml颜色红亮、需注意后段会加深；减到5ml皮色暗沉"},{"n": "生抽","q": "20ml","a": "加到30ml咸味足；减到10ml肉偏淡需补盐"},{"n": "料酒","q": "20ml","a": "加到30ml去腥更净；减到10ml焯水时仍有肉膻味"},{"n": "五香粉","q": "3g","a": "加到5g卤香更浓；减到1g香料味不足、只剩肉味"},{"n": "白胡椒粉","q": "2g","a": "加到4g辛香明显；减到1g几乎尝不到"},{"n": "姜片","q": "4片","a": "加到8片去腥更彻底；减到2片腥气会回弹"},{"n": "葱段","q": "3根","a": "加到6根香气更浓；减到1根焯水去腥作用有限"},{"n": "白醋","q": "10ml","a": "加到20ml肉皮更脆更易爆开；减到3ml脆度提升不明显"}],"steps": ["五花肉带皮切1.5cm厚片，冷水下锅，加姜片、葱段、料酒，中火煮8分钟至筷子能轻松穿透，捞出用厨房纸彻底吸干表面水分。","趁肉皮还温热，用刷子在皮面均匀刷一层白醋，静置10分钟让醋软化角质层。","把麦芽糖与老抽调匀刷在肉皮上，肉面抹生抽、撒五香粉和白胡椒粉，腌制30分钟以上。","烤箱上下火220℃预热10分钟，肉皮朝上摆在烤网上（下面垫烤盘接油），中途翻面一次让两面都上色。","烤25分钟，取出刷一层薄薄的糖水（麦芽糖+少量水），再烤5分钟，此时肉皮应开始起泡。","把温度调到200℃继续烤8-12分钟，全程盯着肉皮：表面鼓起密集大泡、听到轻微爆裂声、颜色变成焦糖色，即是脆皮成功。","出炉静置3分钟再切，用剪刀剪成小条更方便入口；切开会看到肉皮和肉脂分离、油脂微微流出。"],"key": "脆皮成败只看两点：肉皮必须完全烤干、起泡爆开；一旦中途水汽没烤净，皮只会变韧不起泡。上色靠糖水，出脆靠最后那8-12分钟的高温。","tip": "没有烤箱可用空气炸锅200℃先烤20分钟、再200℃复烤8分钟，锅小的话中途要翻面；最后阶段千万别走开，焦了就是苦的。"},"爆汁烤鸭肠": {"time": "40分钟","level": "中等","servings": "2-3人份","ing": [{"n": "鲜鸭肠","q": "400g","a": "加到600g需分两批烤、火力不够就出水；减到250g每人约80g，一顿吃不够"},{"n": "小苏打","q": "1g","a": "加到3g去腥更彻底但要久冲洗、否则有碱味；减到0.3g腥味压不住，只能靠料酒和蒜"},{"n": "料酒","q": "20ml","a": "加到30ml去腥足；减到10ml腥气明显"},{"n": "生抽","q": "15ml","a": "加到25ml咸鲜更足；减到8ml鸭肠味道发白"},{"n": "盐","q": "2g","a": "加到4g需同步减生抽；减到1g腌不透"},{"n": "蒜末","q": "10g","a": "加到20g蒜香盖过腥味；减到5g蒜味不足"},{"n": "烧烤酱","q": "50g","a": "加到80g酱香更浓、颜色更深；减到25g挂不住鸭肠，只能干撒料"},{"n": "辣椒面","q": "10g","a": "加到20g辣度翻倍、适合重口；减到4g基本不辣"},{"n": "孜然粉","q": "8g","a": "加到15g孜然味盖过酱味；减到3g只剩酱香"},{"n": "食用油","q": "20ml","a": "加到40ml鸭肠更亮、烤时滋滋冒油；减到5ml容易烤干发柴"}],"steps": ["鸭肠用清水冲净，撒一把面粉反复搓洗2分钟去掉表面黏液，再用清水冲到不滑手，剪成10cm长段。","小苏打用1勺水化开，抓洗鸭肠2分钟后用流水彻底冲洗干净，沥干备用（这一步是去腥和去黏液的关键）。","鸭肠加料酒、生抽、盐、蒜末抓匀，腌15分钟。","用铁签或竹签把鸭肠折叠穿成串，每串3-4段，串紧不留空隙（空隙处容易烤干）。","烤箱上下火200℃预热，鸭肠串架在烤网上，下面垫烤盘，先烤5分钟至表面变色发紧。","取出刷一层食用油，回到烤箱再烤3分钟，鸭肠边缘收缩起皱、表面渗出油脂时，刷上烧烤酱。","撒辣椒面和孜然粉，转上火230℃烤2分钟上色撒白芝麻，出炉撒葱花香菜，趁热吃。"],"key": "鸭肠必须彻底洗净黏液并用小苏打抓洗，否则烤出来又腥又滑；同时火候要\"中火逼油\"，烤到边缘收缩起皱、油脂滋滋响才对，烤过头就发硬失去爆汁感。","tip": "用空气炸锅180℃烤12分钟、再200℃复烤3分钟最接近炭火味；喜欢更爆汁可以在最后刷酱时把酱里加两勺清水调稀一点。"},"炸串": {"time": "45分钟","level": "中等","servings": "3人份","ing": [{"n": "鸡胸肉/里脊肉","q": "300g","a": "加到450g需分两锅炸；减到200g裹糊相对变厚，口感更酥但性价比低"},{"n": "低筋面粉","q": "100g","a": "加到150g糊更厚更酥但吸油多、发面疙瘩；减到60g挂不住肉，炸出光面"},{"n": "玉米淀粉","q": "50g","a": "加到80g外壳更脆更耐泡；减到20g外壳软塌，容易回吸油"},{"n": "鸡蛋","q": "1个","a": "加到2个糊更黏稠、包裹更牢；减到半个糊会流到锅里炸成碎渣"},{"n": "泡打粉","q": "3g","a": "加到5g外壳更蓬松；减到1g几乎没变化，放久了才生效"},{"n": "清水","q": "150ml","a": "加到190ml糊更稀好挂但薄脆易破；减到110ml糊太稠、挂肉不均"},{"n": "甜辣酱","q": "80g","a": "加到120g酱甜辣更浓、适合刷厚；减到50g只能薄薄一层，香味不足"},{"n": "孜然粉","q": "5g","a": "加到10g烧烤味更足；减到2g只剩酱味"},{"n": "辣椒面","q": "5g","a": "加到12g辣度提升明显；减到2g基本不辣"},{"n": "食用油","q": "1L","a": "炸一次约耗500ml，加到1.5L可复炸不急；减到600ml不够一次炸完，油温下降外壳发吸油"}],"steps": ["鸡胸肉或里脊切1cm厚、4cm长的条，加盐、料酒、孜然粉、辣椒面抓匀腌20分钟。","调糊：低筋面粉、玉米淀粉、泡打粉混合，加鸡蛋和清水搅到无颗粒、能缓慢流动的稠糊（提起筷子呈连续线状滴落）。","肉条可先串竹签再挂糊，串着炸更酥也更好翻；素串（土豆片、豆皮、金针菇）需擦干水分。","油烧至六成热（约170℃），筷子插入周围冒小泡时挂好糊下锅，下锅后用漏勺轻推防粘。","中火炸3-4分钟至外壳起泡金黄、浮上油面，捞出控油静置2分钟。","油温升到八成热（约190℃），回锅复炸30-40秒，外壳会发出清脆的\"沙沙\"响，捞出沥油。","甜辣酱加少许水调稀倒入小锅小火炒30秒至冒泡出香，刷在炸串上，撒孜然粉、辣椒面、葱花、蒜末。"],"key": "酥脆的关键是\"复炸\"：第一次中火炸熟定型，第二次高温把表面水分逼出来并逼出多余的油，只炸一次的外壳放10分钟就软塌。","tip": "甜辣酱别调太稀，否则挂不住、咬一口全流到手上；炸素串务必擦干表面水分，否则下锅会剧烈爆油。"},"锅巴土豆": {"time": "40分钟","level": "稍难","servings": "2-3人份","ing": [{"n": "土豆","q": "3个约500g","a": "加到700g需分两锅炸、否则油温不够炸不脆；减到300g一人一小盘，壳少口感不足"},{"n": "菜籽油","q": "800ml","a": "加到1.2L炸得更透、壳更硬挺；减到500ml一次只能炸一半，土豆沉底容易粘锅"},{"n": "折耳根","q": "50g","a": "加到100g折耳根香更冲、与土豆的土味互补；减到20g香味淡，贵州特色出不来"},{"n": "姜蒜末","q": "20g（姜5g+蒜15g）","a": "加到35g料汁味更厚；减到8g蒜香不足、折耳根的腥味压不住"},{"n": "香醋","q": "20ml","a": "加到35ml酸味突出、能把土豆的厚味化开；减到8ml只剩辣和咸、味道发闷"},{"n": "生抽","q": "20ml","a": "加到30ml咸鲜足；减到10ml折耳根吃起来寡淡"},{"n": "辣椒油","q": "40ml","a": "加到70ml辣度提升、颜色更红亮；减到15g则不辣、少了贵州的辣味灵魂"},{"n": "白糖","q": "2g","a": "加到5g能中和折耳根的苦味、回口更圆润；减到0g后味会发苦"},{"n": "盐","q": "4g","a": "加到6g咸味足；减到2g折耳根的生味压不住"},{"n": "葱花与花生碎","q": "10g","a": "加到20g口感更丰富、炒香后更香；减到3g只剩颜色没有香气"}],"steps": ["土豆切2.5cm滚刀块，冷水冲10分钟洗掉表面部分淀粉（保留一部分，这层淀粉才是\"锅巴\"壳的来源），沥干后用厨房纸擦到表面无水。","烧一锅水，水开下土豆块煮3分钟至外层微软、掰开中心仍有硬芯，捞出沥干晾2分钟。","油烧至八成热（约200℃），土豆块逐个下锅，中火炸3-4分钟，边炸边推，待表面起壳、颜色金黄捞出。","油温继续升到九成热（约215℃），土豆回锅复炸40秒，壳会变得硬挺发脆，捞出控油。","折耳根洗净切小段，沸水烫10秒断生，捞出挤干水分（有水会稀释料汁）。","碗底放姜蒜末、生抽、香醋、白糖、盐、辣椒油，搅匀成料汁。","趁热把土豆和折耳根倒入料汁中，用\"颠勺+轻压\"的手法翻拌，让土豆壳均匀吸味，撒葱花和花生碎。"],"key": "土豆表面不能洗得太干净也不能有水：留着淀粉层才炸得出厚壳，擦干水才不爆油；炸好必须趁热拌，凉了壳回软就再也咬不出\"锅巴\"感。","tip": "拌的时候别用勺子猛搅，用锅铲从底部向上翻、把土豆压在碗壁上\"磕\"几下，这样壳不易碎而料汁能吃进去；正宗贵阳做法还会加炸香的蒜薹段。"},"手搓冰粉": {"time": "30分钟（另需冷藏凝固2小时）","level": "简单","servings": "2人份","ing": [{"n": "冰粉籽（冰粉子）","q": "20g","a": "加到30g出的凝量更多、只需1200ml水；减到10g需2000ml水才够稠，否则不成形"},{"n": "清水","q": "1500ml","a": "加到1800ml口感更软嫩但要更长时间凝固；减到1000ml则胶质过厚、像果冻硬块"},{"n": "红糖","q": "60g","a": "加到90g糖浆更浓稠挂勺；减到30g甜味不足、红糖香淡"},{"n": "山楂片或山楂糕","q": "30g","a": "加到50g酸味更突出、开胃；减到10g酸味太弱、失去了山楂的解腻作用"},{"n": "花生碎","q": "30g","a": "加到50g口感更扎实；减到10g几乎尝不到颗粒感"},{"n": "葡萄干","q": "15g","a": "加到30g甜度更足；减到5g点缀作用弱"},{"n": "蔓越莓干","q": "10g","a": "加到25g酸甜层次更好；减到3g颜色不够丰富"},{"n": "白芝麻","q": "5g","a": "加到10g香气更浓；减到2g几乎看不到"},{"n": "柠檬汁","q": "5ml","a": "加到15ml能加快凝固但会偏酸；减到1ml效果有限"},{"n": "蜂蜜或炼乳","q": "10g","a": "加到20g更甜更香；减到0g纯红糖味更清爽"}],"steps": ["冰粉籽装进纱布袋，在1500ml凉水中用双手反复揉搓挤压3-5分钟，籽里的胶质被揉出，水开始变得黏稠、能拉出细丝。","提起纱布袋把水彻底挤干，静置在阴凉处或冰箱冷藏2小时至完全凝固（滴2滴柠檬汁可加速凝结）。","红糖加100ml水小火熬10分钟，边熬边搅至起泡、颜色变深、挂勺不流，晾凉成糖浆。","山楂片剪碎加少量水小火煮8分钟至软烂，压成带颗粒的山楂酱（也可用现成山楂膏切碎）。","冰粉凝好后用勺子舀入碗中，堆成小丘。","淋红糖浆、铺山楂酱、撒花生碎、葡萄干、蔓越莓干和白芝麻。","吃前从底部往上翻拌，让红糖浆裹住每一口冰粉。"],"key": "揉冰粉籽要\"挤+抖\"交替，直到水明显变稠能拉丝，静置才会凝结成冻；籽可以重复用三次，第二三次出的胶质会少一些。","tip": "没有冰粉籽可用琼脂或吉利丁替代（吉利丁5g+500ml水）；红糖别熬到发黑焦苦，微苦的糖浆会影响整碗的味道。"},"手打柠檬茶": {"time": "15分钟","level": "简单","servings": "1-2人份","ing": [{"n": "香水柠檬","q": "2个（黄柠檬1个+青柠檬1个）","a": "加到3个果肉更多、需更多冰；减到1个则只有青柠檬的冲劲、缺少黄柠檬的甜香"},{"n": "红茶包","q": "2个","a": "加到3个茶味更浓接近港式冻柠茶；减到1个茶味偏淡、柠檬味完全盖过茶"},{"n": "热水（95℃）","q": "500ml","a": "加到700ml茶更柔和但柠檬汁被稀释；减到350ml茶味浓烈、需用大杯否则放不下冰"},{"n": "白砂糖","q": "20g","a": "加到30g甜度平衡酸；减到5g酸得倒牙"},{"n": "蜂蜜","q": "15g","a": "加到25g香气更明显；减到0g改用纯糖浆、少了花蜜调性"},{"n": "冰块","q": "200g","a": "加到300g更冰更解辣，但茶味被稀释；减到100g化得快、很快变温"},{"n": "海盐","q": "1g","a": "加到2g咸甜平衡、甜味更立体；减到0g甜得发腻"}],"steps": ["500ml 95℃热水冲入红茶包，盖盖泡3分钟，捞出茶包，把茶汤晾到60℃左右（太烫会让柠檬发苦）。","青柠檬切小方块，黄柠檬切薄片备用；青柠檬块放入杯底。","用捣棒或擀面杖对准青柠檬块\"暴打\"30-60秒，边打边转杯，把汁水压出来、果籽压破、表皮精油激出，杯底应出现明显汁液。","加白砂糖和蜂蜜（先用少量温水化开），加海盐搅匀至溶解。","倒入晾至60℃的茶汤，用勺子搅匀，尝一口调整酸甜。","加入大量冰块，再放黄柠檬片挂杯壁，插吸管立即喝。"],"key": "\"暴打\"是手打柠檬茶与普通柠檬片的全部差别：必须把果肉压烂、籽压破、把果皮的精油激出来，柠檬的香气才冲得起来；只切片泡是温和的柠檬水。","tip": "柠檬要选皮薄、香气浓的香水柠檬，青柠檬负责冲劲、黄柠檬负责甜香，两者搭配层次最好；茶汤温度超过70℃会把柠檬的苦味逼出来。"},"竹筒奶茶": {"time": "30分钟","level": "稍难","servings": "1杯（约500ml）","ing": [{"n": "新鲜竹筒","q": "1根（直径8-10cm、高20cm，带盖）","a": "加到2根可做双杯组合；换大号（12cm）容量更足但奶盖比例要按比例放大"},{"n": "红茶叶","q": "5g","a": "加到8g茶汤更浓、压得住奶味；减到3g茶味太淡、喝起来像甜牛奶"},{"n": "全脂牛奶","q": "300ml","a": "加到400ml奶味更厚但更腻、需减少糖；减到200ml口感偏稀、层次不明显"},{"n": "淡奶油","q": "100ml","a": "加到150ml奶盖更厚更浓；减到50ml打不发、盖不住茶"},{"n": "奶粉","q": "20g","a": "加到30g奶盖更有厚度、更稳；减到8g盖偏薄，容易被茶冲散"},{"n": "白糖","q": "15g","a": "加到25g甜度足；减到5g微苦、奶香发涩"},{"n": "海盐","q": "1g","a": "加到2g甜味更立体；减到0g甜腻"},{"n": "炼乳","q": "10g","a": "加到20g甜度和奶香翻倍；减到0g奶盖偏硬、缺少奶香"},{"n": "冰块","q": "150g","a": "加到250g更冰；减到80g很快变温、奶盖会塌"},{"n": "可可粉或抹茶粉","q": "2g","a": "加到5g装饰更明显；减到0g纯色奶盖也好看"}],"steps": ["竹筒用清水浸泡30分钟后刷洗内外，用小刀刮掉内壁的竹青膜，底部用竹签戳2-3个小孔便于走冰。","红茶叶5g用150ml 95℃水泡3分钟，滤出茶汤，静置晾到60℃（温度过高会让奶浆分离、结块）。","全脂牛奶300ml加白糖15g，小火加热到60-65℃，锅边刚冒细泡就立刻离火（一旦沸腾奶香会变腥）。","淡奶油100ml+奶粉20g+海盐1g+炼乳10g，用打蛋器打到提起打蛋头能立出小尖角（有硬度但不打过头）。","竹筒底部铺满冰块，先缓缓倒入温牛奶，再沿筒壁缓慢注入茶汤，形成上奶下茶（或反之）的自然渐层。","顶部挤上一层奶盖，淋一圈炼乳，撒可可粉或抹茶粉装饰。","插竹管立刻饮用，超过20分钟冰化后分层会散掉。"],"key": "分层靠温度差和密度差：茶和奶都必须控在60℃左右（太烫分层会混、太凉奶会析出），而且要\"沿壁缓慢注入\"，冲下去就会全混成一杯奶茶。","tip": "竹筒用前清水煮10分钟可以去掉竹青的青涩味；没有竹筒就用透明杯做渐层，视觉效果一样。奶盖打过头会打不出奶酪感，看到小尖角就要停。"},"烤牛奶": {"time": "25分钟","level": "中等","servings": "2人份","ing": [{"n": "全脂牛奶","q": "300ml","a": "加到400ml更湿润、需多烤3分钟；减到200ml质地太稠、像蛋糕糊"},{"n": "蛋黄","q": "2个","a": "加到3个凝固更快更嫩；减到1个蛋白多、成品偏硬不拉丝"},{"n": "白糖","q": "35g","a": "加到50g甜度足、底焦化明显；减到15g偏淡且焦香味弱"},{"n": "低筋面粉","q": "20g","a": "加到35g组织更扎实像蛋糕；减到8g口感极嫩像布丁、不够\"烤奶\"味"},{"n": "玉米淀粉","q": "5g","a": "加到10g凝固更快、中心更少流心；减到0g中心容易偏湿"},{"n": "马苏里拉芝士","q": "80g","a": "加到120g拉丝更明显、口感更浓；减到40g拉丝弱、芝士味不足"},{"n": "淡奶油","q": "60ml","a": "加到100ml更香更滑；减到20ml口感偏干、奶香不突出"},{"n": "黄油","q": "20g","a": "加到35g香气更足、表面更焦香；减到10g香味清淡"},{"n": "盐","q": "1g","a": "加到2g甜味更平衡；减到0g容易发腻"}],"steps": ["蛋黄+白糖放入无水无油的盆中，用电动打蛋器高速打2分钟至颜色发白、纹路能划出清晰的\"8\"字不消失（这是松软的关键）。","筛入低筋面粉和玉米淀粉，用刮刀翻拌至无颗粒，再倒入牛奶和淡奶油，拌成顺滑细腻的奶糊。","拌入一半马苏里拉芝士碎（约40g）搅匀，倒入刷了黄油的耐热小碗，表面铺满剩余芝士碎。","室温静置10分钟让气泡上浮消掉，否则表面有大气孔影响口感。","空气炸锅或烤箱预热200℃，放入中层烤12-15分钟。","观察表面：芝士完全融化、出现金黄焦斑、边缘鼓起时，把温度调到220℃上色2分钟，至焦斑呈深棕。","出炉静置2分钟，用小勺挖开中心，芝士呈半流动拉丝状时最好吃，表面可撒糖粉或淋一点蜂蜜。"],"key": "蛋黄和糖必须打到颜色发白、划线不消失，气泡足够才能做出外焦里嫩的\"烤奶\"；最后2分钟的高温上色是\"焦香\"的来源，不能省。","tip": "想要更强的拉丝就多铺20g芝士，但面粉别超过25g，否则成品变成硬蛋糕而不是绵密的烤奶；用牙签插进中心不带出湿糊即可判断熟度。"},"芝士烤红薯": {"time": "45分钟","level": "简单","servings": "2人份","ing": [{"n": "红薯","q": "2个（约500g）","a": "加到3个（约750g）需延长烤制10分钟；减到1个两人份量不足"},{"n": "马苏里拉芝士","q": "100g","a": "加到150g拉丝更厚、芝士味浓；减到50g拉丝薄、盖不住薯泥"},{"n": "淡奶油","q": "40ml","a": "加到60ml薯泥更顺滑湿润；减到15ml薯泥发干、容易起团"},{"n": "牛奶","q": "30ml","a": "加到50ml更顺滑；减到10ml过于干稠、拌不开"},{"n": "黄油","q": "15g","a": "加到25g奶香更浓；减到5g香味偏淡"},{"n": "盐","q": "1g","a": "加到2g甜味更平衡；减到0g甜到发腻"},{"n": "黑胡椒","q": "1g","a": "加到2g能压住甜味、增加香气；减到0g只有甜"},{"n": "百里香或欧芹碎","q": "1g","a": "加到3g草香更明显；减到0g仅是纯甜芝士味"},{"n": "牛奶（拌入芝士用）","q": "0","a": "如芝士偏干可再加10ml牛奶调整浓稠度，最多不超过50ml否则会稀掉"}],"steps": ["红薯洗净，烤箱200℃整根烤20分钟至皮变软能轻松插入筷子（也可用蒸锅蒸15分钟），取出放凉到不烫手。","沿纵向对半切开，用小勺小心挖出薯肉，保留 0.5cm 厚的薯皮做容器（挖太薄会破，挖太厚口感偏硬）。","把薯肉压成粗泥，加淡奶油、牛奶、黄油、盐，隔水加热或小火翻炒并不断搅拌，直到完全顺滑、能挂勺。","在薯泥里拌入30g马苏里拉芝士碎拌匀，让芝士先融进薯泥里，烤出来更香。","把薯泥填回薯皮，堆成高出碗口的小山丘，用勺背把表面抹平。","铺满剩余70g马苏里拉芝士丝，烤箱200℃烤10-12分钟至芝士完全融化、起泡并出现焦斑，再开上火230℃烤2分钟上色。","出炉撒黑胡椒和百里香碎，趁热用勺子挖着吃。"],"key": "芝士必须先拌一部分进薯泥、再在表面铺满一层并烤出焦斑——只焗到\"融化\"是不够的，焦斑才是芝士香的来源。","tip": "挖薯皮时用小勺贴着皮走，留厚一点就不破；想更丰富可以在薯泥里加50g芝士和一点培根丁，冷天配热牛奶最佳。"},"芝士玉米粒": {"time": "20分钟","level": "简单","servings": "2人份","ing": [{"n": "甜玉米粒","q": "250g","a": "加到400g需分两盘焗、芝士量也要加倍；减到150g铺不满碗、看着不热闹"},{"n": "马苏里拉芝士","q": "80g","a": "加到120g拉丝更粗更明显；减到40g几乎拉不出丝"},{"n": "黄油","q": "20g","a": "加到35g酱汁更香更顺；减到10g会有颗粒感"},{"n": "牛奶","q": "50ml","a": "加到80ml白酱更稀但更顺；减到25ml容易结块"},{"n": "低筋面粉","q": "15g","a": "加到25g酱更稠挂得住玉米；减到8g酱稀、玉米粒会沉底"},{"n": "玉米淀粉","q": "10g","a": "加到15g勾芡更厚；减到0g只用面粉也可以、但稳定性差"},{"n": "盐","q": "2g","a": "加到3g能压住玉米的甜；减到1g甜味发闷"},{"n": "黑胡椒","q": "1g","a": "加到2g香气更明显；减到0g只有甜味"},{"n": "欧芹碎","q": "1g","a": "加到3g颜色好看、味道清爽；减到0g纯芝士味"},{"n": "黄油（防粘）","q": "0","a": "焗饭碗内壁薄刷一层黄油防粘，不刷会在边缘结底"}],"steps": ["玉米粒沥干水分（罐头玉米要用清水冲掉糖水），沸水焯2分钟捞出摊开晾一下。","小锅放黄油化开，小火倒入牛奶，边搅边筛入面粉和玉米淀粉，搅煮1-2分钟至酱汁浓稠、能挂在勺背上。","倒入玉米粒翻匀，小火翻炒2分钟让白酱均匀裹住每粒玉米，盛入耐热碗中压平。","表面铺满马苏里拉芝士丝，厚度尽量均匀。","烤箱200℃预热，放入中层烤8-10分钟至芝士完全融化、表面起泡并出现金黄焦斑。","再开上火230℃烤1-2分钟让焦斑颜色更深，出炉撒黑胡椒和欧芹碎。","趁热用勺子舀着吃，芝士能拉出长丝。"],"key": "玉米粒必须彻底沥干，带水下烤会变成一锅稀汤、芝士也拉不动丝；白酱要熬到\"挂勺\"的浓度，不然芝士会被稀释、结在碗底。","tip": "用冷冻玉米粒不必焯水、沥干直接下锅更省事；想更丰富可在白酱里加50g火腿丁和50g青豆，焗出来像餐厅版。"},"提拉米苏": {"time": "40分钟（另需冷藏4小时）","level": "中等","servings": "6人份","ing": [{"n": "马斯卡彭芝士","q": "250g","a": "加到350g更浓稠、支撑力强不塌；减到180g味道偏淡、要用更多淡奶油补稠度"},{"n": "淡奶油","q": "200ml","a": "加到300ml口感更轻盈；减到120ml会打不发、质地粗糙"},{"n": "蛋黄","q": "2个","a": "加到3个更细腻稳定；减到1个组织偏稀、隔夜会出水"},{"n": "细砂糖","q": "60g","a": "加到80g甜度够；减到35g偏淡、奶酪的酸撑不住"},{"n": "手指饼干","q": "12根","a": "加到16根层更厚更耐吃；减到8根一层铺不满、夹层不均"},{"n": "浓缩咖啡","q": "150ml","a": "加到200ml咖啡味更重、苦味平衡甜；减到100ml饼干吸不满、底部会干硬"},{"n": "朗姆酒","q": "20ml","a": "加到30ml酒香更明显；减到0g可用咖啡酒或纯咖啡替代"},{"n": "吉利丁片","q": "5g","a": "加到8g凝固更硬挺、切块不化；减到3g太软、舀起来就散"},{"n": "可可粉","q": "10g","a": "加到20g苦香浓、可盖住表面甜味；减到5g颜色浅、甜味显得单薄"}],"steps": ["吉利丁片用冷水泡软5分钟（用冰水泡，否则会化掉失去凝固力）。","马斯卡彭芝士250g隔水软化，加淡奶油200ml，用打蛋器搅打5分钟至顺滑无颗粒（全程保持隔水温热，太热会化、油水分离）。","蛋黄+细砂糖60g高速打至颜色发白、膨松发亮，体积约翻倍。","吉利丁挤干水，隔水加热至完全融化（不超过60℃），立刻拌入芝士糊，再拌入蛋黄糊，翻拌均匀。","容器底部铺一层手指饼干；用浓缩咖啡150ml+朗姆酒20ml调成咖啡液，手指饼干在液里快速蘸1秒即取出（久蘸会烂），密密铺满一层。","倒入一半奶糊，轻震气泡；再铺一层蘸过的手指饼干，倒入剩余奶糊，抹平表面。","冷藏4小时以上（最好隔夜），食用前用细筛均匀筛上可可粉，用勺子挖着吃。"],"key": "手指饼干蘸咖啡液只能1秒：泡久了会吸水塌掉，夹层就黏不住、成品变糊成一坨；吉利丁必须完全融化并且温度控制在60℃以下，否则会破坏整盆奶酪糊。","tip": "咖啡液要完全凉透再蘸，热咖啡会把饼干泡化；层数按\"饼干-糊-饼干-糊\"来做，切开时能看到漂亮的分层。喜欢酒香可以把朗姆酒换成咖啡利口酒。"},"蛋烘糕": {"time": "30分钟","level": "稍难","servings": "4人份","ing": [{"n": "鸡蛋","q": "4个","a": "加到6个可做约16个小蛋糕；减到2个面糊太少、摊出来薄而摊不平"},{"n": "细砂糖","q": "100g","a": "加到130g更甜更松；减到70g甜味不足、口感偏紧实"},{"n": "低筋面粉","q": "120g","a": "加到150g蛋糕体更有嚼劲；减到90g太软、翻面易破"},{"n": "清水","q": "30ml","a": "加到45ml面糊更顺但摊开变薄；减到15ml面糊太稠、会有疙瘩"},{"n": "泡打粉","q": "2g","a": "加到4g气孔更足、发起更高；减到1g不够松软"},{"n": "玉米油","q": "20g","a": "加到30g口感更润；减到10g偏干、易粘锅"},{"n": "盐","q": "1g","a": "加到2g甜味更平衡；减到0g只有甜、腻"},{"n": "蜂蜜或红糖浆","q": "30g","a": "加到50g甜度足；减到10g淋上去没味道"},{"n": "猪油或黄油（煎制）","q": "10g","a": "加到20g更香更润；减到0g用不粘锅也可以、但香味少一层"}],"steps": ["鸡蛋4个磕入盆中，加细砂糖100g，用电动打蛋器高速打8分钟至颜色发白、体积膨大到2倍，提起打蛋头落下的纹路能保持10秒不消失——这是蛋烘糕蓬松的根本。","筛入低筋面粉120g、泡打粉2g、盐1g，用刮刀从底部翻拌至无干粉，加清水30ml、玉米油20g翻拌均匀，成细腻无颗粒的稠面糊。","面糊静置15分钟，让面粉充分吸水、气泡自行消掉，这样煎出来表面才平整不会起大气泡。","平底锅或蛋烘糕铁模小火预热，刷一层薄油，转锅用勺子舀15ml面糊快速倒入，晃锅摊成直径约6cm的圆片。","小火煎2分钟，待表面布满密集小气泡、边缘变干发黄、饼身能轻轻晃动时，用铲子快速翻面，再煎40秒至两面金黄。","出锅趁热在表面扎几个小孔，淋蜂蜜或红糖浆，趁热吃（凉了会回软）。","一次只煎一个，火保持小火，火大表面焦了里面还是生的。"],"key": "蛋和糖一定要打到\"落下成纹、10秒不消失\"，这个气泡量决定了成品是否像云朵一样松软；翻面必须快而准，晚翻5秒底就焦了。","tip": "没有专用模具可用平底锅配一个圆形碗口压出形状；面糊别舀太多，摊不开就变成厚饼；煎好的可以叠起来做\"蛋烘糕夹层\"。"},"空气炸锅鸡米花": {"time": "30分钟","level": "简单","servings": "2人份","ing": [{"n": "鸡胸肉","q": "300g","a": "加到450g需分两锅炸、否则受热不均；减到200g份量偏少"},{"n": "低筋面粉","q": "60g","a": "加到90g外壳更厚更酥；减到40g壳薄、容易露肉"},{"n": "玉米淀粉","q": "30g","a": "加到45g更酥更脆；减到15g外壳偏软"},{"n": "鸡蛋","q": "1个","a": "加到2个粘性更强、壳更牢；减到半个液稀、粉容易脱落"},{"n": "牛奶","q": "50ml","a": "加到80ml更湿润嫩滑；减到25ml面糊偏干、粘性下降"},{"n": "盐","q": "3g","a": "加到4g更咸香；减到2g味道偏淡"},{"n": "黑胡椒","q": "2g","a": "加到3g辛香更明显；减到1g几乎尝不到"},{"n": "蒜粉","q": "2g","a": "加到4g蒜香更足；减到0g只有椒香"},{"n": "辣椒粉","q": "3g","a": "加到6g辣度提升；减到1g基本不辣，适合给孩子"},{"n": "食用油","q": "10g","a": "加到20g外壳更亮更酥（喷油）；减到0g干炸容易发柴、粘锅"}],"steps": ["鸡胸肉切2cm见方的丁，加盐、黑胡椒、蒜粉、辣椒粉抓匀腌15分钟（不要提前太久腌，否则表面失水炸不脆）。","混合干粉：低筋面粉60g+玉米淀粉30g。另将牛奶50ml+鸡蛋1个打散成液。","鸡丁先在牛奶蛋液里蘸一遍，再放进干粉中滚一圈，用手轻轻按压让粉牢牢附着（这是外壳厚的关键）。","空气炸锅200℃预热5分钟，鸡米花单层平铺在炸篮里，不要堆叠重叠。","200℃炸12分钟，在第8分钟时把鸡米花全部翻动一次，并喷一次油。","继续炸到总时长14分钟，表皮金黄酥脆；最厚的一颗切开检查，内部无粉红色、看不到生鸡胸的纹理即可。","出锅撒欧芹碎或干辣椒粉，配番茄酱、蜂蜜芥末或沙拉汁。"],"key": "两个要点：鸡米花必须单层平铺，重叠的部位既不脆又可能夹生；干粉要用手按实，抖一抖多余粉，粘不牢的粉一炸就掉光。","tip": "想更酥可复热200℃再烤3分钟；剩余的干粉装密封袋冷藏能再用两次，中间不要沾水。判断熟度别只看颜色，最厚处切开必须无粉红。"},"炒酸奶": {"time": "10分钟操作（另需冷冻2-4小时）","level": "简单","servings": "2人份","ing": [{"n": "原味酸奶（无糖型）","q": "400g","a": "加到600g可以做两份厚片；减到250g铺薄后冻得更快但量偏少"},{"n": "白砂糖","q": "30g","a": "加到50g甜度足；减到10g偏酸，需靠水果干补甜"},{"n": "草莓/芒果等水果","q": "100g","a": "加到180g果味更足；减到50g水果点缀作用弱"},{"n": "坚果碎","q": "20g","a": "加到35g口感更丰富；减到8g几乎尝不到"},{"n": "葡萄干","q": "15g","a": "加到25g甜度提升；减到5g点缀"},{"n": "蔓越莓干","q": "10g","a": "加到20g酸甜平衡、颜色好看；减到3g颜色不足"},{"n": "蜂蜜","q": "10g","a": "加到20g可以拌面糊也可以淋表面；减到0g只有酸奶的酸"},{"n": "蜂蜜（表面装饰）","q": "0","a": "从上面10g中留出5g作表面淋用，其余拌入"}],"steps": ["选浅口的不锈钢盘或硅胶刮刀盘，倒入酸奶400g，用刮刀摊平到1cm厚（不能超过1.5cm，否则中间冻不实、刮出来是糊）。","均匀撒上白砂糖30g，再摆上草莓/芒果块、坚果碎、葡萄干、蔓越莓干。","放入冷冻室-18℃冷冻2小时，摇晃盘子酸奶完全硬实不流动即可；想更扎实可冻4小时。","取出平放在操作台上，用硅胶刮刀或宽刀片贴着盘面一刮一翻，酸奶会成大片卷状落下。","把刮好的酸奶片装碗，表面再撒坚果碎和蔓越莓干，淋上剩余蜂蜜。","现刮现吃，放久会化；也可以外带两片用保鲜盒装、路上吃。"],"key": "盘子要浅、酸奶要摊薄在1cm左右：太厚中间冻不透，刮起来是一团糊而不是片；冻到完全硬透再刮，一刮就成漂亮的大片。","tip": "一定要用原味无糖酸奶，甜味自己控制；刮的时候刀刃平贴盘面、用力均匀，才能刮出大片而不是碎渣。表面加芒果丁和薄荷叶最出片。"},"脏脏包": {"time": "2小时（发酵占大部分）","level": "稍难","servings": "4人份","ing": [{"n": "高筋面粉","q": "250g","a": "加到300g做4个稍大的包、组织更好；减到200g面团偏硬、成品不够蓬松"},{"n": "牛奶","q": "130g","a": "加到150g面团更软但需延长10分钟发酵；减到110g面团偏干、易开裂"},{"n": "淡奶油（面团）","q": "40g","a": "加到60g内含油脂多、组织更柔软；减到20g口感偏干"},{"n": "细砂糖","q": "30g","a": "加到45g甜度足；减到15g发酵偏慢、成品不够甜"},{"n": "干酵母","q": "3g","a": "加到5g发酵更快更稳；减到2g在26℃以下发不起来"},{"n": "盐","q": "2g","a": "加到3g风味更足、抑制过甜；减到1g偏甜"},{"n": "黑巧克力（内馅）","q": "100g","a": "加到150g流心更足、一口爆浆；减到60g每个包馅少、层次感弱"},{"n": "淡奶油（调巧克力）","q": "50g","a": "加到70g巧克力更顺滑；减到30g巧克力会变稠、容易有颗粒"},{"n": "黄油","q": "25g","a": "加到40g面团更酥软；减到15g口感偏紧实"},{"n": "可可粉或巧克力酱","q": "30g","a": "加到50g\"脏\"的效果更夸张；减到10g表面不够脏、甜味全露"}],"steps": ["除黄油外的所有面团材料混合，揉成团后加入软化黄油，揉到能拉出透亮薄膜的完全阶段（手温控制在26℃以下）。","面团盖保鲜膜，28℃发酵1小时至两倍大，手指戳孔不回缩即可。","黑巧克力100g与淡奶油50g隔水加热搅至完全顺滑无颗粒，倒出晾到30℃左右备用（太烫会烫熟面团）。","面团排气后分成4份，擀开成圆形，包入15-20g巧克力馅，收口捏紧搓圆，收口朝下。","摆入烤盘，二次发酵20分钟至明显变轻变大，表面刷一层全蛋液。","烤箱预热180℃，中下层烤18-20分钟至表面金黄、底部呈深棕色（内馅巧克力不需要烤到深色）。","出炉趁热在顶部淋上剩余的融化巧克力酱，撒厚厚一层可可粉，滚一圈让巧克力挂满整个表面，放凉2分钟再切开。"],"key": "巧克力馅必须提前完全融化并过一遍筛、无颗粒，否则包的时候有块状会顶破面皮；表面淋巧克力酱要趁面包还热，凉了挂不住、\"脏\"不起来。","tip": "想要更夸张的\"脏\"就多撒可可粉；喜欢双层口感可以在面团里先抹一层马苏里拉芝士再包巧克力。面团揉不到薄膜也能做，只是口感偏扎实。"},"铁板牛排": {"time": "25分钟","level": "中等","servings": "2人份","ing": [{"n": "牛外脊/西冷","q": "2块（每块200-250g）","a": "加到300g每块更厚需要每面多煎40秒；减到150g每块太薄、容易煎老"},{"n": "海盐","q": "4g","a": "加到7g咸度更足；减到2g肉香出不来"},{"n": "现磨黑胡椒","q": "5g","a": "加到10g辛香明显；减到2g香草味不足"},{"n": "橄榄油","q": "20ml","a": "加到35ml煎制更顺、烟点多；减到10ml容易粘锅、破坏焦壳"},{"n": "黄油","q": "20g","a": "加到35g淋油香更浓；减到10g香草味淡"},{"n": "大蒜","q": "4瓣","a": "加到8瓣蒜香更足；减到2瓣淋油香味弱"},{"n": "迷迭香","q": "1枝","a": "加到2枝烟熏香更明显；减到0g少了草本香、味道偏单调"},{"n": "柠檬","q": "半个","a": "加到1个挤汁更酸更解腻；减到0g牛排后味偏厚重"},{"n": "芦笋/口蘑等时蔬","q": "150g","a": "加到250g更解腻；减到80g盘里只有肉、配菜不足"},{"n": "黑胡椒汁（可选）","q": "30g","a": "加到50g汁更多、蘸食更方便；减到0g直接撒黑胡椒碎也成立"}],"steps": ["牛排提前2小时从冰箱取出回温至室温（冷肉下锅必煎老），用厨房纸把表面水分彻底吸干。","撒海盐和黑胡椒碎静置10分钟，让盐渗入肉里形成汁水。","铁板或厚底锅烧到冒青烟（约250℃），倒橄榄油，油面出现流动的纹路即达到八成热。","下牛排，大火煎第一面2分钟，全程不要移动（移动会破坏焦壳；想要明显焦纹就每面90秒）。","加黄油、蒜瓣、迷迭香，用勺子把融化的黄油反复淋在牛排表面30-40秒（basting，让黄油和蒜香渗进表层）。","厚牛排翻面再煎1-2分钟，用手指按压的弹性或探针温度判断：内里52-54℃为三分熟、57℃为五分熟。","取出静置5分钟让肉汁回流，斜刀切条；铁板余油煎时蔬，挤柠檬汁，配黑胡椒汁一起上桌。"],"key": "表面必须完全干燥才起焦壳；厚牛排每面只煎1-2分钟且必须静置5分钟再切，这一步决定它是多汁还是被切成一摊汁水。","tip": "想要五成熟就把每面延到3分钟；家里锅火候不如铁板猛，可以先大火煎30秒后转中小火慢慢升温，黑胡椒汁最后才下锅防止炒糊。"},"舒芙蕾松饼": {"time": "30分钟","level": "稍难","servings": "2人份","ing": [{"n": "低筋面粉","q": "60g","a": "加到80g松饼更扎实有嚼劲；减到45g口感像泡芙、过于蓬软没咬劲"},{"n": "鸡蛋","q": "2个","a": "加到3个体积更大更蓬；减到1个面糊稀、难成型"},{"n": "牛奶","q": "80g","a": "加到100g面糊更顺；减到60g糊稠、摊不开会厚"},{"n": "细砂糖","q": "40g","a": "加到55g甜度足、也更稳定；减到30g偏淡且蛋白霜偏薄"},{"n": "泡打粉","q": "3g","a": "加到5g发起更高；减到1g蓬松度不足、回缩明显"},{"n": "黄油","q": "25g","a": "加到35g香气更足；减到10g风味寡淡"},{"n": "蜂蜜","q": "20g","a": "加到30g甜度更足；减到10g甜味不够"},{"n": "盐","q": "1g","a": "加到2g平衡甜味；减到0g只有甜"},{"n": "柠檬汁","q": "2滴","a": "加到5滴蛋白更稳定；减到0g打蛋白时糖容易返砂"}],"steps": ["蛋黄+牛奶搅匀，筛入低筋面粉、泡打粉、盐，用刮刀翻拌成无颗粒的细腻面糊。","蛋白加柠檬汁，用打蛋器分三次加入细砂糖，打到湿性偏干的状态——提起打蛋头能拉出直立的小弯钩、盆倒扣蛋白霜不流动。这是松饼蓬松的核心。","取1/3蛋白霜入蛋黄糊翻拌均匀，再把蛋黄糊倒回剩余蛋白霜中，用\"切拌\"手法（从底部向上翻起、像写J字）拌匀，绝对不能画圈搅拌，否则气泡全消、成品变成厚实的饼饼。","平底锅中小火预热，不刷油（刷油就粘锅且起不来厚松饼），舀一勺面糊倒成堆，静置1-2分钟。","等表面布满小气泡、边缘开始凝固变干、底部呈浅黄时翻面，再煎40-60秒至两面金黄、饼身蓬松高起。","出锅立即叠成2-3层厚松饼，顶部放一块黄油，淋蜂蜜，趁热吃。"],"key": "打蛋白要打到\"湿性偏干\"（有硬挺的弯钩），并且用切拌而非画圈搅拌——这两点决定松饼是蓬松如云还是塌成一摊厚饼；锅一定不刷油。","tip": "一次只煎一个面糊，第二个要等锅重新预热；面糊别太稠，倒下去会摊不开，高度就上不来。想更高可叠煎两次再叠。"},"熔岩芝士鸡排": {"time": "40分钟","level": "中等","servings": "2人份","ing": [{"n": "鸡胸肉","q": "2片（每片200g）","a": "加到300g每片更厚、要多炸1分钟；减到150g每片太薄、芝士放不下"},{"n": "马苏里拉芝士","q": "100g","a": "加到140g流心更足、一切开就爆浆；减到60g内馅薄、流心不明显"},{"n": "面包糠","q": "60g","a": "加到90g外壳更厚更酥；减到40g壳薄、容易破口漏芝士"},{"n": "低筋面粉","q": "30g","a": "加到45g粘性更好、壳不易掉；减到15g蛋液挂不住会滑落"},{"n": "鸡蛋","q": "1个","a": "加到2个封口更牢；减到半个易破壳"},{"n": "盐","q": "3g","a": "加到4g腌得更入味；减到2g偏淡"},{"n": "黑胡椒","q": "2g","a": "加到3g辛香明显；减到1g几乎无味"},{"n": "蒜粉","q": "2g","a": "加到4g蒜香更足；减到0g只有椒香"},{"n": "炸油","q": "500ml","a": "加到800ml一次炸两片、控温更稳；减到300ml油不够深、壳不酥"},{"n": "番茄沙拉酱","q": "30g","a": "加到50g解腻更好；减到0g直接吃也可以"}],"steps": ["鸡胸从中间片开成两片相连的大片（底部不要切断），用刀背在肉面轻拍松（断筋、容易熟也松嫩）。","加盐、黑胡椒、蒜粉抓匀腌15分钟，腌好后用厨房纸把表面水分彻底擦干。","把马苏里拉芝士50g均匀铺在鸡排中间，向对折合拢成口袋，用手沿边缘压紧封口（封不严会爆浆流失）。","依次裹：低筋面粉抖薄粉→蛋液→面包糠，每一层都要用手按实，最后用叉子在表面戳几个小孔防炸时鼓泡。","油温160℃（五成热，筷子插入冒小泡）下锅，保持中火炸3-4分钟至外壳金黄酥硬、浮上油面。","捞出放在厨房纸上吸油，静置2分钟让内部芝士重新融化（这一步决定能不能拉出流心）。","用刀从中间对半切开，芝士呈半流动状流出时立即食用，配番茄沙拉酱和沙拉叶。"],"key": "三步定成败：芝士要包满并把边缘压死否则爆浆漏光；炸好后必须静置2分钟让芝士回温融化（切太早是固态、切太晚全流光）；鸡排表面必须擦干再裹粉。","tip": "用空气炸锅200℃先炸12分钟、再200℃复炸3分钟，出油更少但壳略软；静置时间可以自己用手背试温判断，摸着温热时切最好。"},"网红芝士焗饭": {"time": "35分钟","level": "简单","servings": "2人份","ing": [{"n": "隔夜米饭","q": "400g","a": "加到600g需调整碗的大小和芝士量；减到250g一人一小碗、芝士铺不满"},{"n": "马苏里拉芝士","q": "120g","a": "加到180g拉丝更厚、焗出来更香；减到80g拉丝弱、芝士香不足"},{"n": "洋葱","q": "半个","a": "加到1个甜味更足、能盖住隔夜饭的米味；减到1/4个则饭里发闷"},{"n": "培根","q": "50g","a": "加到100g咸香更足；减到20g少了烟熏香、没有层次"},{"n": "青豆玉米粒","q": "60g","a": "加到100g颜色更丰富、口感更脆；减到20g只是点缀"},{"n": "番茄膏","q": "30g","a": "加到50g酸甜更明显、接近番茄焗饭；减到10g味道偏淡、奶味压不住"},{"n": "全脂牛奶","q": "80ml","a": "加到120ml酱汁更顺滑；减到40ml容易糊锅结块"},{"n": "黄油","q": "20g","a": "加到30g炒洋葱更香；减到10g香味略淡"},{"n": "蒜末","q": "5g","a": "加到10g蒜香突出；减到2g几乎闻不到"},{"n": "盐","q": "3g","a": "加到4g需相应减番茄膏和牛奶；减到2g偏淡"}],"steps": ["洋葱切细丝，培根切小丁；黄油化开，小火下洋葱丝炒3分钟至变软透明、微出甜味。","下培根丁中火炒2分钟至出油微微焦黄，加蒜末和黑胡椒炒香。","加番茄膏30g小火炒1分钟炒出红油，倒入牛奶80ml搅匀，加盐，小火煮2分钟至酱汁略微浓稠。","倒入青豆玉米粒炒2分钟，再加入隔夜米饭，用锅铲压着翻炒2-3分钟，让米粒均匀裹上酱汁并压实。","关火，把马苏里拉芝士80g拌进米饭里（半融化状态），盛入焗饭碗，用锅铲压平铺满。","表面再铺剩余40g芝士丝，200℃烤10-12分钟至芝士完全融化、起泡并出现焦斑。","出炉撒黑胡椒，趁热挖着吃，芝士能拉出长丝。"],"key": "必须用隔夜冷饭：新饭水分大，炒出来是糊、焗完湿答答不成型；芝士要在入烤箱前先拌进饭里一部分，才能在加热时完全融化、把每粒米饭裹住。","tip": "没有隔夜饭就把新饭摊开摊薄吹凉20分钟再炒；表面想更香可以先铺一层马苏里拉+淡奶油调成的芝士酱再焗，这是餐厅做法。"}}
;